Module support.
Import ListNotations.

Lemma size_typ_pos : forall A, 1 <= size_typ A.
Proof. induction A; simpl; lia. Qed.

Lemma size_exp_pos : forall e, 1 <= size_exp e.
Proof.
  induction e; simpl; try lia;
  pose proof (size_typ_pos t); pose proof (size_typ_pos t0); lia.
Qed.

Lemma size_typ_open_typ_tvar : forall k (X:typevar) A,
    size_typ (open_typ_wrt_typ_rec k (t_tvar_f X) A) = size_typ A.
Proof.
  intros k X A. revert k. induction A; intros k; simpl.
  - destruct (lt_eq_lt_dec n k) as [ [Hlt|Heq] | Hgt ]; simpl; reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite IHA1, IHA2. reflexivity.
  - rewrite IHA1, IHA2. reflexivity.
  - rewrite IHA1, IHA2. reflexivity.
  - rewrite IHA. reflexivity.
Qed.

Lemma size_exp_open_exp_tvar : forall k (x:termvar) e,
    size_exp (open_exp_wrt_exp_rec k (e_var_f x) e) = size_exp e.
Proof.
  intros k x e. revert k. induction e; intros k; simpl.
  - destruct (lt_eq_lt_dec n k) as [ [Hlt|Heq] | Hgt ]; simpl; reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite IHe. reflexivity.
  - rewrite IHe. reflexivity.
  - rewrite IHe1, IHe2. reflexivity.
  - rewrite IHe1, IHe2. reflexivity.
  - rewrite IHe. reflexivity.
  - rewrite IHe. reflexivity.
  - rewrite IHe. reflexivity.
  - rewrite IHe. reflexivity.
  - rewrite IHe. reflexivity.
Qed.

Lemma size_exp_open_exp_typ_tvar : forall k (X:typevar) e,
    size_exp (open_exp_wrt_typ_rec k (t_tvar_f X) e) = size_exp e.
Proof.
  intros k X e. revert k. induction e; intros k; simpl.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite IHe, size_typ_open_typ_tvar. reflexivity.
  - rewrite IHe, size_typ_open_typ_tvar. reflexivity.
  - rewrite IHe1, IHe2. reflexivity.
  - rewrite IHe1, IHe2. reflexivity.
  - rewrite IHe, size_typ_open_typ_tvar. reflexivity.
  - rewrite IHe. reflexivity.
  - rewrite IHe. reflexivity.
  - rewrite IHe. reflexivity.
  - rewrite IHe, size_typ_open_typ_tvar. reflexivity.
Qed.

Lemma deg_typ_mono : forall n m A, n <= m -> degree_typ_wrt_typ n A -> degree_typ_wrt_typ m A.
Proof.
  intros n m A Hle H. revert m Hle. induction H; intros m' Hle.
  - constructor.
  - constructor; lia.
  - constructor.
  - constructor.
  - constructor.
  - constructor. apply IHdegree_typ_wrt_typ1; auto. apply IHdegree_typ_wrt_typ2; lia.
  - constructor; eauto.
  - constructor; eauto.
  - constructor; eauto.
Qed.

Lemma deg_typ_open_fwd : forall n A, degree_typ_wrt_typ n A ->
  forall k (X:typevar), degree_typ_wrt_typ n (open_typ_wrt_typ_rec k (t_tvar_f X) A).
Proof.
  intros n A H. induction H; intros k X.
  - constructor.
  - match goal with
    | |- degree_typ_wrt_typ _ (open_typ_wrt_typ_rec ?kk (t_tvar_f _) (t_tvar_b ?m)) =>
        simpl; destruct (lt_eq_lt_dec m kk) as [ [Hlt|Heq] | Hgt ]; simpl;
        constructor; lia
    end.
  - constructor.
  - constructor.
  - constructor.
  - constructor.
    + apply IHdegree_typ_wrt_typ1.
    + apply IHdegree_typ_wrt_typ2.
  - constructor; auto.
  - constructor; auto.
  - constructor; auto.
Qed.

Lemma deg_typ_open_inv : forall k n (X:typevar) A,
    k <= n -> degree_typ_wrt_typ n (open_typ_wrt_typ_rec k (t_tvar_f X) A) ->
    degree_typ_wrt_typ (S n) A.
Proof.
  intros k n X A Hkn H. induction A in k, n, Hkn, H |- *; simpl in H.
  - simpl in H; destruct (lt_eq_lt_dec n0 k) as [ [Hlt|Heq] | Hgt ]; simpl in H;
      try (inversion H; subst; constructor; lia).
  - constructor.
  - constructor.
  - constructor.
  - constructor.
  - inversion H; subst; constructor.
    + apply (IHA1 k n); [assumption|assumption].
    + apply (IHA2 (S k) (S n)); [lia|assumption].
  - inversion H; subst; constructor.
    + apply (IHA1 k n); [assumption|assumption].
    + apply (IHA2 k n); [assumption|assumption].
  - inversion H; subst; constructor.
    + apply (IHA1 k n); [assumption|assumption].
    + apply (IHA2 k n); [assumption|assumption].
  - inversion H; subst; constructor. apply (IHA k n); [assumption|assumption].
Qed.

Lemma deg_exp_open_term_fwd : forall n e, degree_exp_wrt_exp n e ->
  forall k (x:termvar), degree_exp_wrt_exp n (open_exp_wrt_exp_rec k (e_var_f x) e).
Proof.
  intros n e H. induction H; intros k x0.
  - constructor.
  - match goal with
    | |- degree_exp_wrt_exp _ (open_exp_wrt_exp_rec ?kk (e_var_f _) (e_var_b ?m)) =>
        simpl; destruct (lt_eq_lt_dec m kk) as [ [Hlt|Heq] | Hgt ]; simpl;
        constructor; lia
    end.
  - constructor.
  - constructor.
  - constructor. apply IHdegree_exp_wrt_exp.
  - constructor. apply IHdegree_exp_wrt_exp.
  - constructor; auto.
  - constructor; auto.
  - constructor; auto.
  - constructor; auto.
  - constructor; auto.
  - constructor. apply IHdegree_exp_wrt_exp.
  - constructor; auto.
Qed.

Lemma deg_exp_open_term_inv : forall k n (x:termvar) e,
    k <= n -> degree_exp_wrt_exp n (open_exp_wrt_exp_rec k (e_var_f x) e) ->
    degree_exp_wrt_exp (S n) e.
Proof.
  intros k n x e Hkn H. induction e in k, n, Hkn, H |- *; simpl in H.
  - simpl in H; destruct (lt_eq_lt_dec n0 k) as [ [Hlt|Heq] | Hgt ]; simpl in H.
    + inversion H; subst; constructor; lia.
    + subst n0; constructor; lia.
    + inversion H; subst; constructor; lia.
  - constructor.
  - constructor.
  - constructor.
  - inversion H; subst; constructor. apply (IHe (S k) (S n)); [lia|assumption].
  - inversion H; subst; constructor. apply (IHe (S k) (S n)); [lia|assumption].
  - inversion H; subst; constructor.
    + apply (IHe1 k n); [assumption|assumption].
    + apply (IHe2 k n); [assumption|assumption].
  - inversion H; subst; constructor.
    + apply (IHe1 k n); [assumption|assumption].
    + apply (IHe2 k n); [assumption|assumption].
  - inversion H; subst; constructor. apply (IHe k n); [assumption|assumption].
  - inversion H; subst; constructor. apply (IHe k n); [assumption|assumption].
  - inversion H; subst; constructor. apply (IHe k n); [assumption|assumption].
  - inversion H; subst; constructor. apply (IHe k n); [assumption|assumption].
  - inversion H; subst; constructor. apply (IHe k n); [assumption|assumption].
Qed.

Lemma deg_exp_open_typ_fwd : forall n e, degree_exp_wrt_typ n e ->
  forall k (X:typevar), degree_exp_wrt_typ n (open_exp_wrt_typ_rec k (t_tvar_f X) e).
Proof.
  intros n e H. induction H; intros k X; simpl.
  - constructor.
  - constructor.
  - constructor.
  - constructor.
  - constructor.
    + apply deg_typ_open_fwd; auto.
    + apply IHdegree_exp_wrt_typ.
  - constructor.
    + apply deg_typ_open_fwd; auto.
    + apply IHdegree_exp_wrt_typ.
  - constructor; auto.
  - constructor; auto.
  - constructor.
    + apply IHdegree_exp_wrt_typ.
    + apply deg_typ_open_fwd; auto.
  - constructor; auto.
  - constructor; auto.
  - constructor. apply IHdegree_exp_wrt_typ.
  - constructor.
    + apply IHdegree_exp_wrt_typ.
    + apply deg_typ_open_fwd; auto.
Qed.

Lemma deg_exp_open_typ_inv : forall k n (X:typevar) e,
    k <= n -> degree_exp_wrt_typ n (open_exp_wrt_typ_rec k (t_tvar_f X) e) ->
    degree_exp_wrt_typ (S n) e.
Proof.
  intros k n X e Hkn H. induction e in k, n, Hkn, H |- *; simpl in H.
  - constructor.
  - constructor.
  - constructor.
  - constructor.
  - inversion H; subst; constructor.
    + match goal with
      | H1 : degree_typ_wrt_typ ?n0 (open_typ_wrt_typ_rec ?k0 (t_tvar_f ?Y) ?AA) |- degree_typ_wrt_typ (S ?n0) ?AA =>
          exact (deg_typ_open_inv k0 n0 Y AA Hkn H1)
      end.
    + apply (IHe k n); [assumption|assumption].
  - inversion H; subst; constructor.
    + match goal with
      | H1 : degree_typ_wrt_typ ?n0 (open_typ_wrt_typ_rec ?k0 (t_tvar_f ?Y) ?AA) |- degree_typ_wrt_typ (S ?n0) ?AA =>
          exact (deg_typ_open_inv k0 n0 Y AA Hkn H1)
      end.
    + apply (IHe k n); [assumption|assumption].
  - inversion H; subst; constructor.
    + apply (IHe1 k n); [assumption|assumption].
    + apply (IHe2 k n); [assumption|assumption].
  - inversion H; subst; constructor.
    + apply (IHe1 k n); [assumption|assumption].
    + apply (IHe2 k n); [assumption|assumption].
  - inversion H; subst; constructor.
    + apply (IHe k n); [assumption|assumption].
    + match goal with
      | H1 : degree_typ_wrt_typ ?n0 (open_typ_wrt_typ_rec ?k0 (t_tvar_f ?Y) ?AA) |- degree_typ_wrt_typ (S ?n0) ?AA =>
          exact (deg_typ_open_inv k0 n0 Y AA Hkn H1)
      end.
  - inversion H; subst; constructor. apply (IHe k n); [assumption|assumption].
  - inversion H; subst; constructor. apply (IHe k n); [assumption|assumption].
  - inversion H; subst; constructor. apply (IHe (S k) (S n)); [lia|assumption].
  - inversion H; subst; constructor.
    + apply (IHe k n); [assumption|assumption].
    + match goal with
      | H1 : degree_typ_wrt_typ ?n0 (open_typ_wrt_typ_rec ?k0 (t_tvar_f ?Y) ?AA) |- degree_typ_wrt_typ (S ?n0) ?AA =>
          exact (deg_typ_open_inv k0 n0 Y AA Hkn H1)
      end.
Qed.

Lemma deg_typ_of_open_term : forall n k (x:termvar) e,
    degree_exp_wrt_typ n (open_exp_wrt_exp_rec k (e_var_f x) e) <-> degree_exp_wrt_typ n e.
Proof.
  intros n k x e. induction e in n, k |- *; simpl.
  - destruct (lt_eq_lt_dec n0 k) as [ [Hlt|Heq] | Hgt ]; simpl; split; intros; constructor.
  - tauto.
  - tauto.
  - tauto.
  - split.
    + intro H; inversion H; subst; constructor.
      * assumption.
      * apply (proj1 (IHe n (S k))); assumption.
    + intro H; inversion H; subst; constructor.
      * assumption.
      * apply (proj2 (IHe n (S k))); assumption.
  - split.
    + intro H; inversion H; subst; constructor.
      * assumption.
      * apply (proj1 (IHe n (S k))); assumption.
    + intro H; inversion H; subst; constructor.
      * assumption.
      * apply (proj2 (IHe n (S k))); assumption.
  - split.
    + intro H; inversion H; subst; constructor.
      * apply (proj1 (IHe1 n k)); assumption.
      * apply (proj1 (IHe2 n k)); assumption.
    + intro H; inversion H; subst; constructor.
      * apply (proj2 (IHe1 n k)); assumption.
      * apply (proj2 (IHe2 n k)); assumption.
  - split.
    + intro H; inversion H; subst; constructor.
      * apply (proj1 (IHe1 n k)); assumption.
      * apply (proj1 (IHe2 n k)); assumption.
    + intro H; inversion H; subst; constructor.
      * apply (proj2 (IHe1 n k)); assumption.
      * apply (proj2 (IHe2 n k)); assumption.
  - split.
    + intro H; inversion H; subst; constructor.
      * apply (proj1 (IHe n k)); assumption.
      * assumption.
    + intro H; inversion H; subst; constructor.
      * apply (proj2 (IHe n k)); assumption.
      * assumption.
  - split; intro H; inversion H; subst; constructor; [ apply (proj1 (IHe n k)) | apply (proj2 (IHe n k)) ]; assumption.
  - split; intro H; inversion H; subst; constructor; [ apply (proj1 (IHe n k)) | apply (proj2 (IHe n k)) ]; assumption.
  - split; intro H; inversion H; subst; constructor; [ apply (proj1 (IHe (S n) k)) | apply (proj2 (IHe (S n) k)) ]; assumption.
  - split.
    + intro H; inversion H; subst; constructor.
      * apply (proj1 (IHe n k)); assumption.
      * assumption.
    + intro H; inversion H; subst; constructor.
      * apply (proj2 (IHe n k)); assumption.
      * assumption.
Qed.

Lemma deg_exp_of_open_typ : forall n k (X:typevar) e,
    degree_exp_wrt_exp n (open_exp_wrt_typ_rec k (t_tvar_f X) e) <-> degree_exp_wrt_exp n e.
Proof.
  intros n k X e. induction e in n, k |- *; simpl.
  - tauto.
  - tauto.
  - tauto.
  - tauto.
  - split; intro H; inversion H; subst; constructor; [ apply (proj1 (IHe (S n) k)) | apply (proj2 (IHe (S n) k)) ]; assumption.
  - split; intro H; inversion H; subst; constructor; [ apply (proj1 (IHe (S n) k)) | apply (proj2 (IHe (S n) k)) ]; assumption.
  - split.
    + intro H; inversion H; subst; constructor.
      * apply (proj1 (IHe1 n k)); assumption.
      * apply (proj1 (IHe2 n k)); assumption.
    + intro H; inversion H; subst; constructor.
      * apply (proj2 (IHe1 n k)); assumption.
      * apply (proj2 (IHe2 n k)); assumption.
  - split.
    + intro H; inversion H; subst; constructor.
      * apply (proj1 (IHe1 n k)); assumption.
      * apply (proj1 (IHe2 n k)); assumption.
    + intro H; inversion H; subst; constructor.
      * apply (proj2 (IHe1 n k)); assumption.
      * apply (proj2 (IHe2 n k)); assumption.
  - split; intro H; inversion H; subst; constructor; [ apply (proj1 (IHe n k)) | apply (proj2 (IHe n k)) ]; assumption.
  - split; intro H; inversion H; subst; constructor; [ apply (proj1 (IHe n k)) | apply (proj2 (IHe n k)) ]; assumption.
  - split; intro H; inversion H; subst; constructor; [ apply (proj1 (IHe n k)) | apply (proj2 (IHe n k)) ]; assumption.
  - split; intro H; inversion H; subst; constructor; [ apply (proj1 (IHe n (S k))) | apply (proj2 (IHe n (S k))) ]; assumption.
  - split; intro H; inversion H; subst; constructor; [ apply (proj1 (IHe n k)) | apply (proj2 (IHe n k)) ]; assumption.
Qed.

Lemma deg_typ_open_dec : forall n k (X:typevar) A,
    k <= n -> degree_typ_wrt_typ (S n) A -> degree_typ_wrt_typ n (open_typ_wrt_typ_rec k (t_tvar_f X) A).
Proof.
  intros n k X A. induction A in n, k |- *; intros Hle H; simpl in H |- *.
  - destruct (lt_eq_lt_dec n0 k) as [ [Hlt|Heq] | Hgt ]; simpl.
    + inversion H; subst; apply degree_wrt_typ_t_tvar_b; lia.
    + exact (degree_wrt_typ_t_tvar_f n X).
    + inversion H; subst; apply degree_wrt_typ_t_tvar_b; lia.
  - constructor.
  - constructor.
  - constructor.
  - constructor.
  - inversion H; subst; constructor.
    + apply (IHA1 n k); [lia|assumption].
    + apply (IHA2 (S n) (S k)); [lia|assumption].
  - inversion H; subst; constructor.
    + apply (IHA1 n k); [lia|assumption].
    + apply (IHA2 n k); [lia|assumption].
  - inversion H; subst; constructor.
    + apply (IHA1 n k); [lia|assumption].
    + apply (IHA2 n k); [lia|assumption].
  - inversion H; subst; constructor. apply (IHA n k); [lia|assumption].
Qed.

Lemma deg_exp_open_term_dec : forall n k (x:termvar) e,
    k <= n -> degree_exp_wrt_exp (S n) e -> degree_exp_wrt_exp n (open_exp_wrt_exp_rec k (e_var_f x) e).
Proof.
  intros n k x e. induction e in n, k |- *; intros Hle H; simpl in H |- *.
  - destruct (lt_eq_lt_dec n0 k) as [ [Hlt|Heq] | Hgt ]; simpl.
    + inversion H; subst; apply degree_wrt_exp_e_var_b; lia.
    + exact (degree_wrt_exp_e_var_f n x).
    + inversion H; subst; apply degree_wrt_exp_e_var_b; lia.
  - constructor.
  - constructor.
  - constructor.
  - inversion H; subst; constructor. apply (IHe (S n) (S k)); [lia|assumption].
  - inversion H; subst; constructor. apply (IHe (S n) (S k)); [lia|assumption].
  - inversion H; subst; constructor.
    + apply (IHe1 n k); [lia|assumption].
    + apply (IHe2 n k); [lia|assumption].
  - inversion H; subst; constructor.
    + apply (IHe1 n k); [lia|assumption].
    + apply (IHe2 n k); [lia|assumption].
  - inversion H; subst; constructor. apply (IHe n k); [lia|assumption].
  - inversion H; subst; constructor. apply (IHe n k); [lia|assumption].
  - inversion H; subst; constructor. apply (IHe n k); [lia|assumption].
  - inversion H; subst; constructor. apply (IHe n k); [assumption|assumption].
  - inversion H; subst; constructor. apply (IHe n k); [lia|assumption].
Qed.

Lemma deg_exp_open_typ_dec : forall n k (X:typevar) e,
    k <= n -> degree_exp_wrt_typ (S n) e -> degree_exp_wrt_typ n (open_exp_wrt_typ_rec k (t_tvar_f X) e).
Proof.
  intros n k X e. induction e in n, k |- *; intros Hle H; simpl in H |- *.
  - constructor.
  - constructor.
  - constructor.
  - constructor.
  - inversion H; subst; constructor.
    + apply (deg_typ_open_dec n k); assumption.
    + apply (IHe n k); assumption.
  - inversion H; subst; constructor.
    + apply (deg_typ_open_dec n k); assumption.
    + apply (IHe n k); assumption.
  - inversion H; subst; constructor.
    + apply (IHe1 n k); assumption.
    + apply (IHe2 n k); assumption.
  - inversion H; subst; constructor.
    + apply (IHe1 n k); assumption.
    + apply (IHe2 n k); assumption.
  - inversion H; subst; constructor.
    + apply (IHe n k); assumption.
    + apply (deg_typ_open_dec n k); assumption.
  - inversion H; subst; constructor. apply (IHe n k); assumption.
  - inversion H; subst; constructor. apply (IHe n k); assumption.
  - inversion H; subst; constructor. apply (IHe (S n) (S k)); [lia|assumption].
  - inversion H; subst; constructor.
    + apply (IHe n k); assumption.
    + apply (deg_typ_open_dec n k); assumption.
Qed.
End support.
Import support.

Module agentA.
Import ListNotations.

(* ------------------------------------------------------------------ *)
(* Basic inversion helpers for the degree relation                     *)
(* ------------------------------------------------------------------ *)

Lemma degree_tvar_b_iff : forall n i, degree_typ_wrt_typ n (t_tvar_b i) <-> i < n.
Proof.
  intros n i. split; intro H.
  - inversion H; subst; assumption.
  - constructor; assumption.
Qed.

Lemma degree_arrow_iff : forall n A B,
    degree_typ_wrt_typ n (t_arrow A B) <->
    degree_typ_wrt_typ n A /\ degree_typ_wrt_typ n B.
Proof.
  intros. split; intro H.
  - inversion H; subst; auto.
  - destruct H. constructor; assumption.
Qed.

Lemma degree_and_iff : forall n A B,
    degree_typ_wrt_typ n (t_and A B) <->
    degree_typ_wrt_typ n A /\ degree_typ_wrt_typ n B.
Proof.
  intros. split; intro H.
  - inversion H; subst; auto.
  - destruct H. constructor; assumption.
Qed.

Lemma degree_rcd_iff : forall n l A,
    degree_typ_wrt_typ n (t_rcd l A) <-> degree_typ_wrt_typ n A.
Proof.
  intros. split; intro H.
  - inversion H; subst; assumption.
  - constructor; assumption.
Qed.

Lemma degree_forall_iff : forall n A B,
    degree_typ_wrt_typ n (t_forall A B) <->
    degree_typ_wrt_typ n A /\ degree_typ_wrt_typ (S n) B.
Proof.
  intros. split; intro H.
  - inversion H; subst; auto.
  - destruct H. constructor; assumption.
Qed.

Definition sd (A : typ) : Prop :=
  degree_typ_wrt_typ 0 A <-> lc_typ A.

(* lc_typ implies degree 0, by induction on the lc_typ derivation *)
Lemma lc_typ_degree0 : forall A, lc_typ A -> degree_typ_wrt_typ 0 A.
Proof.
  intros A H. induction H as [ X
    | | | | A B HA HB
    | A B HA HB | A B HA HB | l A HA ].
  - constructor.
  - constructor.
  - constructor.
  - constructor.
  - constructor.
    + assumption.
    + destruct (atom_fresh (empty : atoms)) as [X _].
      apply (deg_typ_open_inv 0 0 X B); [lia | apply H0].
  - constructor; assumption.
  - constructor; assumption.
  - constructor; assumption.
Qed.

(* degree 0 implies lc_typ, by strong induction on the size of the type.
   Opening with a fresh variable preserves size, so the hypothesis can be
   applied recursively to opened bodies. *)
Lemma degree0_lc_typ : forall A, degree_typ_wrt_typ 0 A -> lc_typ A.
Proof.
  intros A. remember (size_typ A) as s eqn:Hs. revert A Hs.
  induction s as [s IHs] using lt_wf_ind.
  intros A Hs Hdeg.
  destruct A as [i | X | | | | A1 A2 | A1 A2 | A1 A2 | l A1].
  - rewrite degree_tvar_b_iff in Hdeg. lia.
  - constructor.
  - constructor.
  - constructor.
  - constructor.
  - (* t_forall *)
    rewrite degree_forall_iff in Hdeg. destruct Hdeg as [H1 H2].
    constructor.
    + apply (IHs (size_typ A1)).
      * rewrite Hs. simpl. pose proof (size_typ_pos A2). lia.
      * reflexivity.
      * assumption.
    + intro X.
      apply (IHs (size_typ (open_typ_wrt_typ_rec 0 (t_tvar_f X) A2))).
      * rewrite size_typ_open_typ_tvar. rewrite Hs. simpl.
        pose proof (size_typ_pos A1). lia.
      * reflexivity.
      * apply (deg_typ_open_dec 0 0 X A2); [lia | assumption].
  - (* t_arrow *)
    rewrite degree_arrow_iff in Hdeg. destruct Hdeg as [H1 H2].
    constructor.
    + apply (IHs (size_typ A1)); [ | reflexivity | assumption].
      rewrite Hs. simpl. pose proof (size_typ_pos A2). lia.
    + apply (IHs (size_typ A2)); [ | reflexivity | assumption].
      rewrite Hs. simpl. pose proof (size_typ_pos A1). lia.
  - (* t_and *)
    rewrite degree_and_iff in Hdeg. destruct Hdeg as [H1 H2].
    constructor.
    + apply (IHs (size_typ A1)); [ | reflexivity | assumption].
      rewrite Hs. simpl. pose proof (size_typ_pos A2). lia.
    + apply (IHs (size_typ A2)); [ | reflexivity | assumption].
      rewrite Hs. simpl. pose proof (size_typ_pos A1). lia.
  - (* t_rcd *)
    rewrite degree_rcd_iff in Hdeg.
    constructor. apply (IHs (size_typ A1)); [ | reflexivity | assumption].
    rewrite Hs. simpl. lia.
Qed.

Lemma lc_typ_degree0_iff : forall A, lc_typ A <-> degree_typ_wrt_typ 0 A.
Proof.
  intro A. split.
  - apply lc_typ_degree0.
  - apply degree0_lc_typ.
Qed.

(* ------------------------------------------------------------------ *)
(* Well-formedness implies local closedness                            *)
(* ------------------------------------------------------------------ *)

Lemma TWell_degree0 : forall D A, TWell D A -> degree_typ_wrt_typ 0 A.
Proof.
  intros D A H. induction H as [ D | D | D
    | D X A Hb | D l A HA | D A B HA HB | D A B HA HB | L D A B HA HB ].
  - constructor.
  - constructor.
  - constructor.
  - constructor.
  - constructor; assumption.
  - constructor; assumption.
  - constructor; assumption.
  - constructor.
    + assumption.
    + destruct (atom_fresh L) as [X HX].
      apply (deg_typ_open_inv 0 0 X B); [lia | apply H0; assumption].
Qed.

Lemma TWell_lc_typ : forall D A, TWell D A -> lc_typ A.
Proof.
  intros D A H. apply degree0_lc_typ. apply (TWell_degree0 D A). assumption.
Qed.

Lemma ord_degree0 : forall A, ord A -> degree_typ_wrt_typ 0 A.
Proof.
  intros A H. induction H as [ X | | | | A B HA HB
    | L A B HA HB | l B HB ].
  - constructor.
  - constructor.
  - constructor.
  - constructor.
  - constructor.
    + apply lc_typ_degree0; assumption.
    + assumption.
  - constructor.
    + apply lc_typ_degree0; assumption.
    + destruct (atom_fresh L) as [X HX].
      apply (deg_typ_open_inv 0 0 X B); [lia | apply H; assumption].
  - constructor; assumption.
Qed.

Lemma ord_lc_typ : forall A, ord A -> lc_typ A.
Proof.
  intros A H. apply degree0_lc_typ. apply ord_degree0. assumption.
Qed.

Lemma botLike_lc_typ : forall A, botLike A -> lc_typ A.
Proof.
  intros A H. induction H as [ | A B HB HA | A B HA HB ].
  - constructor.
  - constructor; assumption.
  - constructor; assumption.
Qed.

Lemma TCWell_cons_inv : forall (D:tctx) (X:typevar) (A:typ),
    TCWell (cons (X,A) D) -> TCWell D.
Proof.
  intros D X A H. inversion H; subst; assumption.
Qed.

Lemma TCWell_cons_TWell : forall (D:tctx) (X:typevar) (A:typ),
    TCWell (cons (X,A) D) -> TWell D A.
Proof.
  intros D X A H. inversion H; subst; assumption.
Qed.

Lemma topLike_TCWell : forall D A, topLike D A -> TCWell D.
Proof.
  intros D A H. induction H as [ D HTC | D A B HA HB
    | D A B HA HB | D l B HB | L D A B HB | D X A HTC Hb ].
  - assumption.
  - assumption.
  - assumption.
  - assumption.
  - destruct (atom_fresh L) as [X HX].
    exact (TCWell_cons_inv D X A (H X HX)).
  - assumption.
Qed.

Lemma topLike_TWell_TCWell : forall D A, TCWell D -> topLike D A -> TWell D A.
Proof.
  intros D A HTC H. revert HTC. induction H as [ D HTC | D A B HA HB
    | D A B HA HB | D l B HB | L D A B HB | D X A HTC Hb ].
  - intros _. constructor.
  - intros HTC. apply TW_and.
    + apply HB; assumption.
    + apply IHtopLike1; assumption.
  - intros HTC. constructor.
    + assumption.
    + apply IHHB; assumption.
  - intros HTC. constructor. apply IHHB; assumption.
  - intros HTC.
    assert (Hdom : TWell D A).
    { destruct (atom_fresh L) as [X HX].
      exact (TCWell_cons_TWell D X A (topLike_TCWell _ _ (HB X HX))). }
    apply (TW_all L D A B).
    + assumption.
    + intro X. intro HX.
      apply (H X HX).
      apply (topLike_TCWell (cons (X,A) D) (B -^ X)). apply (HB X HX).
  - intros HTC0. apply (TW_var D X A). assumption.
Qed.

Lemma topLike_TWell : forall D A, topLike D A -> TWell D A.
Proof.
  intros D A H.
  apply topLike_TWell_TCWell.
  - apply (topLike_TCWell D A). assumption.
  - assumption.
Qed.

Lemma topLike_lc_typ : forall D A, topLike D A -> lc_typ A.
Proof.
  intros D A H. apply TWell_lc_typ with (D := D). apply topLike_TWell. assumption.
Qed.

(* ------------------------------------------------------------------ *)
(* Renaming of free type variables                                     *)
(* ------------------------------------------------------------------ *)

Fixpoint ren_typ (f : typevar -> typevar) (A : typ) : typ :=
  match A with
  | t_tvar_b i => t_tvar_b i
  | t_tvar_f X => t_tvar_f (f X)
  | t_int => t_int
  | t_top => t_top
  | t_bot => t_bot
  | t_forall A1 A2 => t_forall (ren_typ f A1) (ren_typ f A2)
  | t_arrow A1 A2 => t_arrow (ren_typ f A1) (ren_typ f A2)
  | t_and A1 A2 => t_and (ren_typ f A1) (ren_typ f A2)
  | t_rcd l A1 => t_rcd l (ren_typ f A1)
  end.

Lemma ren_typ_open : forall (f : typevar -> typevar) k (X:typevar) B,
    ren_typ f (open_typ_wrt_typ_rec k (t_tvar_f X) B) =
    open_typ_wrt_typ_rec k (t_tvar_f (f X)) (ren_typ f B).
Proof.
  intros f k X B. revert k. induction B; intros k; simpl.
  - (* t_tvar_b *) destruct (lt_eq_lt_dec n k) as [ [H|H] | H ]; simpl; reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite IHB1, IHB2. reflexivity.
  - rewrite IHB1, IHB2. reflexivity.
  - rewrite IHB1, IHB2. reflexivity.
  - rewrite IHB. reflexivity.
Qed.

Lemma ren_typ_open0 : forall (f : typevar -> typevar) (Y:typevar) B,
    ren_typ f (B -^ Y) = (ren_typ f B) -^ (f Y).
Proof.
  intros f Y B. unfold open_typ_wrt_typ at 1 2.
  rewrite ren_typ_open. reflexivity.
Qed.

Lemma degree_ren : forall n A, degree_typ_wrt_typ n A ->
    forall f, degree_typ_wrt_typ n (ren_typ f A).
Proof.
  intros n A H. induction H; intro f; simpl; try constructor; auto.
Qed.

Lemma lc_typ_ren : forall A, lc_typ A -> forall f, lc_typ (ren_typ f A).
Proof.
  intros A H f. apply degree0_lc_typ. apply degree_ren with (f := f).
  apply lc_typ_degree0. assumption.
Qed.

Lemma ren_typ_id : forall A (f : typevar -> typevar),
    (forall X, X \in [[A]] -> f X = X) -> ren_typ f A = A.
Proof.
  induction A; intros f H; simpl.
  - reflexivity.
  - apply f_equal. apply H. apply AtomSetImpl.singleton_2. reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite IHA1, IHA2; [reflexivity | | ].
    + intros X HX. apply H. first [apply AtomSetImpl.union_2; assumption | apply AtomSetImpl.union_3; assumption].
    + intros X HX. apply H. first [apply AtomSetImpl.union_2; assumption | apply AtomSetImpl.union_3; assumption].
  - rewrite IHA1, IHA2; [reflexivity | | ].
    + intros X HX. apply H. first [apply AtomSetImpl.union_2; assumption | apply AtomSetImpl.union_3; assumption].
    + intros X HX. apply H. first [apply AtomSetImpl.union_2; assumption | apply AtomSetImpl.union_3; assumption].
  - rewrite IHA1, IHA2; [reflexivity | | ].
    + intros X HX. apply H. first [apply AtomSetImpl.union_2; assumption | apply AtomSetImpl.union_3; assumption].
    + intros X HX. apply H. first [apply AtomSetImpl.union_2; assumption | apply AtomSetImpl.union_3; assumption].
  - rewrite IHA; [reflexivity | intros X HX; apply H; assumption].
Qed.

Definition rename_var (Y X : typevar) : typevar -> typevar :=
  fun Z => if eq_dec Z Y then X else Z.

Lemma rename_var_eq : forall Y X, rename_var Y X Y = X.
Proof.
  intros Y X. unfold rename_var. destruct (eq_dec Y Y); [reflexivity | exfalso; apply n; reflexivity].
Qed.

Lemma rename_var_neq : forall Y X Z, Z <> Y -> rename_var Y X Z = Z.
Proof.
  intros Y X Z H. unfold rename_var. destruct (eq_dec Z Y); [exfalso; apply H; assumption | reflexivity].
Qed.

Lemma notin_union : forall (x:atom) s t, x \notin (s \u t) -> x \notin s /\ x \notin t.
Proof.
  intros x s t H. split; intro Hx.
  - apply H. apply AtomSetImpl.union_2. assumption.
  - apply H. apply AtomSetImpl.union_3. assumption.
Qed.

Lemma notin_singleton : forall (x y:atom), x \notin {{y}} -> x <> y.
Proof.
  intros x y H Heq. subst. apply H. apply AtomSetImpl.singleton_2. reflexivity.
Qed.

Lemma ord_ren_single : forall A Y X, ord A -> ord (ren_typ (rename_var Y X) A).
Proof.
  intros A Y X H. induction H as [ Z | | | | A B HA HB
    | L A B HA HB | l B HB ].
  - simpl. constructor.
  - simpl. constructor.
  - simpl. constructor.
  - simpl. constructor.
  - simpl. constructor.
    + apply lc_typ_ren. assumption.
    + apply IHHB.
  - simpl. apply (O_all ((L \u {{X}}) \u {{Y}}) (ren_typ (rename_var Y X) A) (ren_typ (rename_var Y X) B)).
    + apply lc_typ_ren. assumption.
    + intros Z HZ.
      destruct (notin_union Z (L \u {{X}}) {{Y}} HZ) as [HZ1 HZY].
      destruct (notin_union Z L {{X}} HZ1) as [HZL HZX].
      assert (HZy : Z <> Y) by (apply notin_singleton; assumption).
      assert (Hne : rename_var Y X Z = Z) by (apply rename_var_neq; assumption).
      specialize (HB Z HZL).
      specialize (H Z HZL).
      rewrite ren_typ_open0 in H.
      rewrite Hne in H.
      exact H.
  - simpl. constructor. apply IHHB.
Qed.

(* ------------------------------------------------------------------ *)
(* Inversion principles                                                *)
(* ------------------------------------------------------------------ *)

Lemma topLike_and_inv : forall D A B, topLike D (t_and A B) ->
    topLike D A /\ topLike D B.
Proof. intros D A B H. inversion H; subst; auto. Qed.

Lemma topLike_arrow_inv : forall D A B, topLike D (t_arrow A B) ->
    TWell D A /\ topLike D B.
Proof. intros D A B H. inversion H; subst; auto. Qed.

Lemma topLike_rcd_inv : forall D l A, topLike D (t_rcd l A) -> topLike D A.
Proof. intros D l A H. inversion H; subst; assumption. Qed.

Lemma TWell_arrow_inv : forall D A B, TWell D (t_arrow A B) ->
    TWell D A /\ TWell D B.
Proof. intros D A B H. inversion H; subst; auto. Qed.

Lemma TWell_and_inv : forall D A B, TWell D (t_and A B) ->
    TWell D A /\ TWell D B.
Proof. intros D A B H. inversion H; subst; auto. Qed.

Lemma TWell_rcd_inv : forall D l A, TWell D (t_rcd l A) -> TWell D A.
Proof. intros D l A H. inversion H; subst; assumption. Qed.

Lemma TWell_all_inv : forall D A B, TWell D (t_forall A B) -> TWell D A.
Proof. intros D A B H. inversion H; subst; assumption. Qed.

Lemma topLike_all_dom : forall D A B, topLike D (t_forall A B) -> TWell D A.
Proof.
  intros D A B H. apply TWell_all_inv with (B := B).
  apply topLike_TWell. assumption.
Qed.

Lemma ord_arrow_inv : forall A B, ord (t_arrow A B) -> lc_typ A /\ ord B.
Proof. intros A B H. inversion H; subst; auto. Qed.

Lemma ord_rcd_inv : forall l A, ord (t_rcd l A) -> ord A.
Proof. intros l A H. inversion H; subst; assumption. Qed.

Lemma ord_all_inv : forall A B, ord (t_forall A B) ->
    lc_typ A /\ (forall X, ord (open_typ_wrt_typ B (t_tvar_f X))).
Proof.
  intros A B H. inversion H; subst.
  split; [assumption |].
  intro X.
  destruct (atom_fresh (((L \u {{X}}) \u [[B]]))) as [Y HY].
  destruct (notin_union Y (L \u {{X}}) [[B]] HY) as [HY1 HYB].
  destruct (notin_union Y L {{X}} HY1) as [HYL HYX].
  assert (HYX' : Y <> X) by (apply notin_singleton; assumption).
  pose proof (H3 Y HYL) as Ho.
  pose proof (ord_ren_single (B -^ Y) Y X Ho) as Hren.
  rewrite ren_typ_open0 in Hren.
  rewrite rename_var_eq in Hren.
  assert (Hid : ren_typ (rename_var Y X) B = B).
  { apply ren_typ_id. intros Z HZ.
    apply rename_var_neq. intro Heq. subst Z. apply HYB. assumption. }
  rewrite Hid in Hren. exact Hren.
Qed.

(* ------------------------------------------------------------------ *)
(* topLike is impossible for some types                                *)
(* ------------------------------------------------------------------ *)

Lemma topLike_t_int_false : forall D, ~ topLike D t_int.
Proof. intros D H. inversion H. Qed.

Lemma topLike_t_bot_false : forall D, ~ topLike D t_bot.
Proof. intros D H. inversion H. Qed.

Lemma topLike_tvar_nil_false : forall X, ~ topLike nil (t_tvar_f X).
Proof.
  intros X H. inversion H; subst. simpl in H2. contradiction.
Qed.

(* ------------------------------------------------------------------ *)
(* Context facts                                                       *)
(* ------------------------------------------------------------------ *)

Lemma TCWell_uniq : forall D, TCWell D -> uniq D.
Proof.
  intros D H. induction H as [ | D X A HTC HTW HU ].
  - apply uniq_nil.
  - assumption.
Qed.

Lemma in_dom_map_fst : forall (D1 D2 : tctx) (X:atom),
    map fst D1 = map fst D2 -> X \in dom D1 -> X \in dom D2.
Proof.
  induction D1 as [|[a A] D1 IH]; intros D2 X Hmap Hin.
  - simpl in Hin. apply AtomSetProperties.Dec.F.empty_iff in Hin. contradiction.
  - destruct D2 as [|[b B] D2].
    + simpl in Hmap. discriminate Hmap.
    + simpl in Hmap. injection Hmap as Hab Hmap. subst b.
      simpl in Hin. apply AtomSetProperties.Dec.F.add_iff in Hin.
      destruct Hin as [Heq | Hin].
      * simpl. apply AtomSetProperties.Dec.F.add_iff. left. exact Heq.
      * simpl. apply AtomSetProperties.Dec.F.add_iff. right.
        apply (IH D2 X Hmap Hin).
Qed.

Lemma TWell_dom_irrel : forall D1 A, TWell D1 A ->
    forall D2, map fst D1 = map fst D2 -> TWell D2 A.
Proof.
  intros D1 A H. induction H as [ D1 | D1 | D1
    | D1 X A Hb | D1 l A HA | D1 A B HA HB | D1 A B HA HB | L D1 A B HA HB ];
    intros D2 Hmap.
  - apply TW_top.
  - apply TW_bot.
  - apply TW_int.
  - pose proof (binds_In typ X A D1 Hb) as HX.
    pose proof (in_dom_map_fst D1 D2 X Hmap HX) as HX2.
    destruct (binds_In_inv typ X D2 HX2) as [A2 Hb2].
    apply (TW_var D2 X A2). assumption.
  - apply TW_rcd. eauto.
  - apply TW_arrow; eauto.
  - apply TW_and; eauto.
  - apply (TW_all L D2 A B).
    + eauto.
    + intros X HX.
      assert (Hmap' : map fst (cons (X,A) D1) = map fst (cons (X,A) D2)).
      { simpl. rewrite Hmap. reflexivity. }
      apply (H0 X HX (cons (X,A) D2) Hmap').
Qed.

(* ------------------------------------------------------------------ *)
(* spl                                                                 *)
(* ------------------------------------------------------------------ *)

Lemma lc_open_all : forall B L,
    (forall X, X \notin L -> lc_typ (open_typ_wrt_typ B (t_tvar_f X))) ->
    forall X, lc_typ (open_typ_wrt_typ B (t_tvar_f X)).
Proof.
  intros B L H X.
  destruct (atom_fresh L) as [Y HY].
  pose proof (H Y HY) as HYlc.
  apply lc_typ_degree0 in HYlc.
  apply (deg_typ_open_inv 0 0 Y B) in HYlc; [| lia].
  apply degree0_lc_typ.
  apply (deg_typ_open_dec 0 0 X B); [lia | assumption].
Qed.

Lemma spl_lc : forall A B C, spl A B C -> lc_typ A /\ lc_typ B /\ lc_typ C.
Proof.
  intros A B C H. induction H as [ A B C1 C2 HA HBp HB
    | L A B C1 C2 HA HBp HB | l B C1 C2 HBp HB | A B HA HB ].
  - destruct HB as [HBlc HCrest]. destruct HCrest as [HC1 HC2].
    repeat split; apply lc_t_arrow; assumption.
  - repeat split; apply lc_t_forall; try assumption.
    + apply (lc_open_all B L). intros X HX. apply (proj1 (HB X HX)).
    + apply (lc_open_all C1 L). intros X HX. apply (proj1 (proj2 (HB X HX))).
    + apply (lc_open_all C2 L). intros X HX. apply (proj2 (proj2 (HB X HX))).
  - destruct HB as [HBlc HCrest]. destruct HCrest as [HC1 HC2].
    repeat split; apply lc_t_rcd; assumption.
  - repeat split.
    + apply lc_t_and; assumption.
    + assumption.
    + assumption.
Qed.

Lemma TWell_all_body : forall D A B, TWell D (t_forall A B) ->
    exists L, forall X, X \notin L -> TWell (cons (X,A) D) (open_typ_wrt_typ B (t_tvar_f X)).
Proof.
  intros D A B H. inversion H; subst; eauto.
Qed.

Lemma spl_TWell : forall D A B C, TWell D A -> spl A B C ->
    TWell D B /\ TWell D C.
Proof.
  intros D A B C HT H. revert D HT.
  induction H as [ A B C1 C2 HA HBp HB
    | L A B C1 C2 HA HBp HB | l B C1 C2 HBp HB | A B HA HB ];
    intros D0 HT0.
  - destruct (TWell_arrow_inv D0 A B HT0) as [HDA HDB].
    destruct (HB D0 HDB) as [HC1 HC2].
    split; apply TW_arrow; assumption.
  - destruct (TWell_all_body D0 A B HT0) as [L0 HB0].
    assert (HDA : TWell D0 A) by (apply (TWell_all_inv D0 A B HT0)).
    split; apply (TW_all (L0 \u L) D0 A).
    + assumption.
    + intros X HX. destruct (notin_union X L0 L HX) as [HX0 HXL].
      destruct (HB X HXL (cons (X,A) D0) (HB0 X HX0)) as [HC1 HC2]. assumption.
    + assumption.
    + intros X HX. destruct (notin_union X L0 L HX) as [HX0 HXL].
      destruct (HB X HXL (cons (X,A) D0) (HB0 X HX0)) as [HC1 HC2]. assumption.
  - pose proof (TWell_rcd_inv D0 l B HT0) as HDB.
    destruct (HB D0 HDB) as [HC1 HC2].
    split; apply TW_rcd; assumption.
  - destruct (TWell_and_inv D0 A B HT0) as [HDA HDB].
    split; assumption.
Qed.

(* ------------------------------------------------------------------ *)
(* Algorithmic subtyping: local closedness                             *)
(* ------------------------------------------------------------------ *)

Lemma algo_sub_lc : forall D A B, algo_sub D A B -> lc_typ A /\ lc_typ B.
Proof.
  intros D A B H.
  induction H as
    [ D X HTC HTW
    | D HTC
    | D A B HTW Hord Htop
    | D A HTC HTW Hord
    | D A B C HTWB Hord Hsubp Hsub
    | D A B C HTWA Hord Hsubp Hsub
    | D A1 B1 A2 B2 Hord Hsub1p Hsub1 Hsub2p Hsub2
    | L D A1 A2 B1 B2 Hord Hsub1p Hsub1 Hsub2p Hsub2
    | D l A B Hord Hsubp Hsub
    | D A B B1 B2 Hspl Hsub1p Hsub1 Hsub2p Hsub2 ].
  - split; apply lc_t_tvar_f.
  - split; apply lc_t_int.
  - split.
    + apply (TWell_lc_typ D A). assumption.
    + apply ord_lc_typ. assumption.
  - split.
    + apply lc_t_bot.
    + apply ord_lc_typ. assumption.
  - destruct Hsub as [HA HC]. split.
    + apply lc_t_and; [assumption | apply (TWell_lc_typ D B); assumption].
    + assumption.
  - destruct Hsub as [HB HC]. split.
    + apply lc_t_and; [apply (TWell_lc_typ D A); assumption | assumption].
    + assumption.
  - destruct Hsub1 as [HA2 HA1]. destruct Hsub2 as [HB1 HB2]. split.
    + apply lc_t_arrow; assumption.
    + apply lc_t_arrow; assumption.
  - destruct Hsub1 as [HB1 HA1]. split.
    + apply lc_t_forall.
      * assumption.
      * apply (lc_open_all A2 L). intros X HX. apply (proj1 (Hsub2 X HX)).
    + apply lc_t_forall.
      * assumption.
      * apply (lc_open_all B2 L). intros X HX. apply (proj2 (Hsub2 X HX)).
  - destruct Hsub as [HA HB]. split; apply lc_t_rcd; assumption.
  - destruct Hsub1 as [HA HB1]. split.
    + assumption.
    + apply (proj1 (spl_lc B B1 B2 Hspl)).
Qed.

Lemma spl_back_TWell : forall B B1 B2, spl B B1 B2 ->
    forall D, TWell D B1 -> TWell D B2 -> TWell D B.
Proof.
  intros B B1 B2 H.
  induction H as [ A B C1 C2 HA HBp HB
    | L A B C1 C2 HA HBp HB | l B C1 C2 HBp HB | A B HA HB ].
  - intros D0 HT1 HT2.
    destruct (TWell_arrow_inv D0 A C1 HT1) as [HDA HC1].
    destruct (TWell_arrow_inv D0 A C2 HT2) as [_ HC2].
    apply (TW_arrow D0 A B).
    + assumption.
    + apply (HB D0 HC1 HC2).
  - intros D0 HT1 HT2.
    destruct (TWell_all_body D0 A C1 HT1) as [L1 HB1].
    destruct (TWell_all_body D0 A C2 HT2) as [L2 HB2].
    assert (HDA : TWell D0 A) by (apply (TWell_all_inv D0 A C1 HT1)).
    apply (TW_all ((L \u L1) \u L2) D0 A B).
    + assumption.
    + intros X HX.
      destruct (notin_union X (L \u L1) L2 HX) as [HX12 HX2].
      destruct (notin_union X L L1 HX12) as [HXL HX1].
      apply (HB X HXL (cons (X,A) D0) (HB1 X HX1) (HB2 X HX2)).
  - intros D0 HT1 HT2.
    pose proof (TWell_rcd_inv D0 l C1 HT1) as HC1.
    pose proof (TWell_rcd_inv D0 l C2 HT2) as HC2.
    apply TW_rcd. apply (HB D0 HC1 HC2).
  - intros D0 HT1 HT2. apply TW_and; assumption.
Qed.

(* ------------------------------------------------------------------ *)
(* Algorithmic subtyping: well-formedness of source and target         *)
(* ------------------------------------------------------------------ *)

Lemma algo_sub_TWell_both : forall D A B, TCWell D -> algo_sub D A B ->
    TWell D A /\ TWell D B.
Proof.
  intros D A B HTC H. revert HTC.
  induction H as
    [ D X HTC HTW
    | D HTC
    | D A B HTW Hord Htop
    | D A HTC HTW Hord
    | D A B C HTWB Hord Hsubp Hsub
    | D A B C HTWA Hord Hsubp Hsub
    | D A1 B1 A2 B2 Hord Hsub1p Hsub1 Hsub2p Hsub2
    | L D A1 A2 B1 B2 Hord Hsub1p Hsub1 Hsub2p Hsub2
    | D l A B Hord Hsubp Hsub
    | D A B B1 B2 Hspl Hsub1p Hsub1 Hsub2p Hsub2 ];
    intros HTC0.
  - split; assumption.
  - split; apply TW_int.
  - split.
    + assumption.
    + apply (topLike_TWell D B). assumption.
  - split.
    + apply TW_bot.
    + assumption.
  - destruct (Hsub HTC0) as [HA HC]. split.
    + apply TW_and; assumption.
    + assumption.
  - destruct (Hsub HTC0) as [HB HC]. split.
    + apply TW_and; assumption.
    + assumption.
  - destruct (Hsub1 HTC0) as [HA2 HA1].
    destruct (Hsub2 HTC0) as [HB1 HB2]. split.
    + apply TW_arrow; assumption.
    + apply TW_arrow; assumption.
  - destruct (Hsub1 HTC0) as [HWB1 HWA1].
    assert (Hcons : forall X, X \notin (L \u dom D) ->
      TCWell (cons (X,B1) D) /\ TWell (cons (X,B1) D) (open_typ_wrt_typ A2 (t_tvar_f X)) /\
      TWell (cons (X,B1) D) (open_typ_wrt_typ B2 (t_tvar_f X))).
    { intros X HX. destruct (notin_union X L (dom D) HX) as [HXL HXD].
      assert (HTCcons : TCWell (cons (X,B1) D)).
      { apply (TCW_cons D X B1 HTC0 HWB1).
        apply (uniq_cons_3 typ X B1 D); [apply (TCWell_uniq D HTC0) | exact HXD]. }
      destruct (Hsub2 X HXL HTCcons) as [HA2x HB2x].
      auto. }
    split.
    + apply (TW_all (L \u dom D) D A1 A2).
      * assumption.
      * intros X HX. destruct (Hcons X HX) as [Hc Hpair]. destruct Hpair as [HA2x HB2x].
        apply (TWell_dom_irrel (cons (X,B1) D) (open_typ_wrt_typ A2 (t_tvar_f X))
                 HA2x (cons (X,A1) D)).
        simpl. reflexivity.
    + apply (TW_all (L \u dom D) D B1 B2).
      * assumption.
      * intros X HX. destruct (Hcons X HX) as [Hc Hpair]. destruct Hpair as [HA2x HB2x]. assumption.
  - destruct (Hsub HTC0) as [HA HB]. split; apply TW_rcd; assumption.
  - destruct (Hsub1 HTC0) as [HA HB1].
    destruct (Hsub2 HTC0) as [_ HB2]. split.
    + assumption.
    + apply (spl_back_TWell B B1 B2 Hspl D HB1 HB2).
Qed.

Lemma algo_sub_TWell_source : forall D A B, TCWell D -> algo_sub D A B -> TWell D A.
Proof.
  intros D A B HTC H. apply (algo_sub_TWell_both D A B); assumption.
Qed.

Lemma algo_sub_TWell_target : forall D A B, TCWell D -> algo_sub D A B -> TWell D B.
Proof.
  intros D A B HTC H. apply (algo_sub_TWell_both D A B); assumption.
Qed.

(* ------------------------------------------------------------------ *)
(* Disjointness: local closedness                                      *)
(* ------------------------------------------------------------------ *)

Lemma disjoint_lc : forall D A B, disjoint D A B -> lc_typ A /\ lc_typ B.
Proof.
  intros D A B H.
  induction H as
    [ D A B HTC HTWA HTWB Hax
    | D A B HTWB Htop
    | D A B HTWA Htop
    | D A1 A2 B1 B2 HTW1 HTW2 Hdp Hd
    | D l A B Hdp Hd
    | L D A1 B1 A2 B2 HTW1 HTW2 Hdp Hd
    | D X B A Hbind Hsub
    | D B X A Hbind Hsub
    | D A B A1 A2 Hspl Hd1p Hd1 Hd2p Hd2
    | D A B B1 B2 Hspl Hd1p Hd1 Hd2p Hd2 ].
  - split; apply (TWell_lc_typ D); assumption.
  - split.
    + apply (topLike_lc_typ D A); assumption.
    + apply (TWell_lc_typ D B). assumption.
  - split.
    + apply (TWell_lc_typ D A). assumption.
    + apply (topLike_lc_typ D B); assumption.
  - split.
    + apply (TWell_lc_typ D (t_arrow A1 A2)). assumption.
    + apply (TWell_lc_typ D (t_arrow B1 B2)). assumption.
  - destruct Hd as [HA HB]. split; apply lc_t_rcd; assumption.
  - split; apply lc_t_forall.
    + apply (TWell_lc_typ D A1). assumption.
    + apply (lc_open_all B1 L). intros X HX. apply (proj1 (Hd X HX)).
    + apply (TWell_lc_typ D A2). assumption.
    + apply (lc_open_all B2 L). intros X HX. apply (proj2 (Hd X HX)).
  - split.
    + apply lc_t_tvar_f.
    + apply (proj2 (algo_sub_lc D A B Hsub)).
  - split.
    + apply (proj2 (algo_sub_lc D A B Hsub)).
    + apply lc_t_tvar_f.
  - destruct Hd1 as [_ HB]. split.
    + apply (proj1 (spl_lc A A1 A2 Hspl)).
    + assumption.
  - destruct Hd1 as [HA _]. split.
    + assumption.
    + apply (proj1 (spl_lc B B1 B2 Hspl)).
Qed.
End agentA.
Import agentA.

Module agentB.
Import ListNotations.

Lemma size_exp_open_term_f : forall (x : termvar) e,
    size_exp (open_exp_wrt_exp e (e_var_f x)) = size_exp e.
Proof. intros. unfold open_exp_wrt_exp. apply size_exp_open_exp_tvar. Qed.

Lemma size_exp_open_typ_f : forall (X : typevar) e,
    size_exp (open_exp_wrt_typ e (t_tvar_f X)) = size_exp e.
Proof. intros. unfold open_exp_wrt_typ. apply size_exp_open_exp_typ_tvar. Qed.

Lemma size_typ_open_typ_f : forall (X : typevar) A,
    size_typ (open_typ_wrt_typ A (t_tvar_f X)) = size_typ A.
Proof. intros. unfold open_typ_wrt_typ. apply size_typ_open_typ_tvar. Qed.

(* ============================================================ *)
(* Basic inversion helpers for lc_typ                          *)
(* ============================================================ *)

Lemma not_lc_typ_tvar_b : forall n, ~ lc_typ (t_tvar_b n).
Proof.
  intros n H. inversion H.
Qed.

Lemma lc_typ_arrow_inv : forall A B, lc_typ (t_arrow A B) -> lc_typ A /\ lc_typ B.
Proof.
  intros A B H. inversion H; subst; auto.
Qed.

Lemma lc_typ_and_inv : forall A B, lc_typ (t_and A B) -> lc_typ A /\ lc_typ B.
Proof.
  intros A B H. inversion H; subst; auto.
Qed.

Lemma lc_typ_rcd_inv : forall l A, lc_typ (t_rcd l A) -> lc_typ A.
Proof.
  intros l A H. inversion H; subst; auto.
Qed.

Lemma lc_typ_forall_inv : forall A B,
    lc_typ (t_forall A B) -> lc_typ A /\ (forall X, lc_typ (open_typ_wrt_typ B (t_tvar_f X))).
Proof.
  intros A B H. inversion H; subst; auto.
Qed.

(* ============================================================ *)
(* A1: lc_typ <-> degree 0                                     *)
(* ============================================================ *)

Lemma lc_typ_deg_aux : forall n A,
    size_typ A <= n -> (lc_typ A <-> degree_typ_wrt_typ 0 A).
Proof.
  intros n. induction n as [n IH] using lt_wf_ind.
  intros A Hn. destruct A as [n0|X0| | | | A1 B1 | A1 B1 | A1 B1 | l A1]; simpl in Hn.
  - (* t_tvar_b *)
    split.
    + intros H. exfalso. exact (not_lc_typ_tvar_b n0 H).
    + intros H. exfalso. inversion H; subst; lia.
  - (* t_tvar_f *)
    split; intros _; constructor.
  - (* t_int *)
    split; intros _; constructor.
  - (* t_top *)
    split; intros _; constructor.
  - (* t_bot *)
    split; intros _; constructor.
  - (* t_forall *)
    assert (HltA1 : size_typ A1 < n) by lia.
    assert (HltB1 : size_typ B1 < n) by lia.
    split.
    + intros H. inversion H; subst.
      match goal with H : lc_typ A1 |- _ => rename H into HAlc end.
      match goal with H : forall X : typevar, lc_typ (open_typ_wrt_typ B1 (t_tvar_f X)) |- _ => rename H into Hbody end.
      constructor.
      * exact (proj1 (IH (size_typ A1) HltA1 A1 (le_n _)) HAlc).
      * destruct (atom_fresh (empty : atoms)) as [X0 _].
        apply (deg_typ_open_inv 0 0 X0 B1 (le_n 0)).
        apply (proj1 (IH (size_typ (open_typ_wrt_typ_rec 0 (t_tvar_f X0) B1)) (ltac:(rewrite size_typ_open_typ_tvar; exact HltB1)) (open_typ_wrt_typ_rec 0 (t_tvar_f X0) B1) (le_n _))).
        -- exact (Hbody X0).
    + intros H. inversion H; subst.
      match goal with H : degree_typ_wrt_typ 0 A1 |- _ => rename H into HdegA end.
      match goal with H : degree_typ_wrt_typ (S 0) B1 |- _ => rename H into HdegB end.
      constructor.
      * exact (proj2 (IH (size_typ A1) HltA1 A1 (le_n _)) HdegA).
      * intros X0.
        apply (proj2 (IH (size_typ (open_typ_wrt_typ_rec 0 (t_tvar_f X0) B1)) (ltac:(rewrite size_typ_open_typ_tvar; exact HltB1)) (open_typ_wrt_typ_rec 0 (t_tvar_f X0) B1) (le_n _))).
        -- exact (deg_typ_open_dec 0 0 X0 B1 (le_n 0) HdegB).
  - (* t_arrow *)
    assert (HltA1 : size_typ A1 < n) by lia.
    assert (HltB1 : size_typ B1 < n) by lia.
    split.
    + intros H. inversion H; subst.
      match goal with H : lc_typ A1 |- _ => rename H into HAlcA end.
      match goal with H : lc_typ B1 |- _ => rename H into HAlcB end.
      constructor;
        [ exact (proj1 (IH (size_typ A1) HltA1 A1 (le_n _)) HAlcA)
        | exact (proj1 (IH (size_typ B1) HltB1 B1 (le_n _)) HAlcB) ].
    + intros H. inversion H; subst.
      match goal with H : degree_typ_wrt_typ 0 A1 |- _ => rename H into HdegA end.
      match goal with H : degree_typ_wrt_typ 0 B1 |- _ => rename H into HdegB end.
      constructor;
        [ exact (proj2 (IH (size_typ A1) HltA1 A1 (le_n _)) HdegA)
        | exact (proj2 (IH (size_typ B1) HltB1 B1 (le_n _)) HdegB) ].
  - (* t_and *)
    assert (HltA1 : size_typ A1 < n) by lia.
    assert (HltB1 : size_typ B1 < n) by lia.
    split.
    + intros H. inversion H; subst.
      match goal with H : lc_typ A1 |- _ => rename H into HAlcA end.
      match goal with H : lc_typ B1 |- _ => rename H into HAlcB end.
      constructor;
        [ exact (proj1 (IH (size_typ A1) HltA1 A1 (le_n _)) HAlcA)
        | exact (proj1 (IH (size_typ B1) HltB1 B1 (le_n _)) HAlcB) ].
    + intros H. inversion H; subst.
      match goal with H : degree_typ_wrt_typ 0 A1 |- _ => rename H into HdegA end.
      match goal with H : degree_typ_wrt_typ 0 B1 |- _ => rename H into HdegB end.
      constructor;
        [ exact (proj2 (IH (size_typ A1) HltA1 A1 (le_n _)) HdegA)
        | exact (proj2 (IH (size_typ B1) HltB1 B1 (le_n _)) HdegB) ].
  - (* t_rcd *)
    assert (HltA1 : size_typ A1 < n) by lia.
    split.
    + intros H. inversion H; subst.
      match goal with H : lc_typ A1 |- _ => rename H into HAlcA end.
      constructor. exact (proj1 (IH (size_typ A1) HltA1 A1 (le_n _)) HAlcA).
    + intros H. inversion H; subst.
      match goal with H : degree_typ_wrt_typ 0 A1 |- _ => rename H into HdegA end.
      constructor. exact (proj2 (IH (size_typ A1) HltA1 A1 (le_n _)) HdegA).
Qed.

Lemma lc_typ_deg : forall A, lc_typ A <-> degree_typ_wrt_typ 0 A.
Proof.
  intros A. exact (lc_typ_deg_aux (size_typ A) A (le_n _)).
Qed.

(* Independence of degree from the particular free type variable inserted. *)
Lemma deg_typ_open_subst : forall n k (X : typevar) B A,
    degree_typ_wrt_typ n A ->
    degree_typ_wrt_typ n (open_typ_wrt_typ_rec k (t_tvar_f X) B) ->
    degree_typ_wrt_typ n (open_typ_wrt_typ_rec k A B).
Proof.
  intros n k X B. induction B as
      [n0|X0| | | | A1 IHA1 B1 IHB1 | A1 IHA1 B1 IHB1 | A1 IHA1 B1 IHB1 | l A1 IHA1]
      in n, k |- *; intros A HA HB; simpl in *.
  - destruct (lt_eq_lt_dec n0 k) as [ [Hlt|Heq] | Hgt ]; simpl in *.
    + exact HB.
    + subst. exact HA.
    + exact HB.
  - constructor.
  - constructor.
  - constructor.
  - constructor.
  - inversion HB; subst.
    match goal with H : degree_typ_wrt_typ n (open_typ_wrt_typ_rec k (t_tvar_f X) A1) |- _ => rename H into Hd1 end.
    match goal with H : degree_typ_wrt_typ (S n) (open_typ_wrt_typ_rec (S k) (t_tvar_f X) B1) |- _ => rename H into Hd2 end.
    constructor.
    + exact (IHA1 n k A HA Hd1).
    + exact (IHB1 (S n) (S k) A (deg_typ_mono n (S n) A (ltac:(lia)) HA) Hd2).
  - inversion HB; subst.
    match goal with H : degree_typ_wrt_typ n (open_typ_wrt_typ_rec k (t_tvar_f X) A1) |- _ => rename H into Hd1 end.
    match goal with H : degree_typ_wrt_typ n (open_typ_wrt_typ_rec k (t_tvar_f X) B1) |- _ => rename H into Hd2 end.
    constructor;
        [ exact (IHA1 n k A HA Hd1) | exact (IHB1 n k A HA Hd2) ].
  - inversion HB; subst.
    match goal with H : degree_typ_wrt_typ n (open_typ_wrt_typ_rec k (t_tvar_f X) A1) |- _ => rename H into Hd1 end.
    match goal with H : degree_typ_wrt_typ n (open_typ_wrt_typ_rec k (t_tvar_f X) B1) |- _ => rename H into Hd2 end.
    constructor;
        [ exact (IHA1 n k A HA Hd1) | exact (IHB1 n k A HA Hd2) ].
  - inversion HB; subst.
    match goal with H : degree_typ_wrt_typ n (open_typ_wrt_typ_rec k (t_tvar_f X) A1) |- _ => rename H into Hd1 end.
    constructor.
    exact (IHA1 n k A HA Hd1).
Qed.

(* lc_typ is independent of the inserted free type variable. *)
Lemma lc_typ_open_free_inv : forall k (X Y : typevar) B,
    lc_typ (open_typ_wrt_typ_rec k (t_tvar_f X) B) ->
    lc_typ (open_typ_wrt_typ_rec k (t_tvar_f Y) B).
Proof.
  intros k X Y B H.
  apply lc_typ_deg in H.
  apply lc_typ_deg.
  exact (deg_typ_open_subst 0 k X B (t_tvar_f Y)
           (degree_wrt_typ_t_tvar_f 0 Y) H).
Qed.

(* ============================================================ *)
(* A2: lc_exp <-> degree 0 (both kinds)                        *)
(* ============================================================ *)

Lemma lc_exp_deg_aux : forall n e,
    size_exp e <= n ->
    (lc_exp e <-> (degree_exp_wrt_exp 0 e /\ degree_exp_wrt_typ 0 e)).
Proof.
  intros n. induction n as [n IH] using lt_wf_ind.
  intros e Hn. destruct e as
      [n0|x0| |i| A e0 | A e0 | e1 e2 | e1 e2 | e0 A | l e0 | e0 l | e0 | e0 A];
    simpl in Hn.
  - (* e_var_b *)
    split.
    + intros H. inversion H.
    + intros [Hde _]. exfalso. inversion Hde; subst; lia.
  - (* e_var_f *)
    split; [ intros _; split; constructor | intros _; constructor ].
  - (* e_top *)
    split; [ intros _; split; constructor | intros _; constructor ].
  - (* e_lit *)
    split; [ intros _; split; constructor | intros _; constructor ].
  - (* e_abs *)
    assert (Hlte : size_exp e0 < n) by (pose proof size_typ_pos A; lia).
    split.
    + intros H. inversion H; subst.
      match goal with H : lc_typ A |- _ => rename H into HAlc end.
      match goal with H : forall x : termvar, lc_exp (open_exp_wrt_exp e0 (e_var_f x)) |- _ => rename H into Hbody end.
      destruct (atom_fresh (empty : atoms)) as [x _].
      specialize (Hbody x) as Hlcopen.
      assert (Hsizeopen : size_exp (open_exp_wrt_exp e0 (e_var_f x)) <= size_exp e0).
      { rewrite size_exp_open_term_f. apply le_n. }
      destruct (IH (size_exp e0) Hlte (open_exp_wrt_exp e0 (e_var_f x)) Hsizeopen)
        as [Hoe Hot].
      assert (HdeE : degree_exp_wrt_exp 1 e0).
      { apply (deg_exp_open_term_inv 0 0 x e0 (le_n 0)). exact (proj1 (Hoe Hlcopen)). }
      assert (HdtE : degree_exp_wrt_typ 0 e0).
      { apply (proj1 (deg_typ_of_open_term 0 0 x e0)). exact (proj2 (Hoe Hlcopen)). }
      assert (HdA : degree_typ_wrt_typ 0 A).
      { apply (proj1 (lc_typ_deg A)). exact HAlc. }
      split.
      * constructor. exact HdeE.
      * constructor; assumption.
    + intros [Hde Hdt]. inversion Hde; subst.
      match goal with H : degree_exp_wrt_exp (S 0) e0 |- _ => rename H into HdeE end.
      inversion Hdt; subst.
      match goal with H : degree_typ_wrt_typ 0 A |- _ => rename H into HdA end.
      match goal with H : degree_exp_wrt_typ 0 e0 |- _ => rename H into HdtE end.
      constructor.
      * apply (proj2 (lc_typ_deg A)). exact HdA.
      * intro x.
        assert (Hsizeopen : size_exp (open_exp_wrt_exp e0 (e_var_f x)) <= size_exp e0).
        { rewrite size_exp_open_term_f. apply le_n. }
        apply (proj2 (IH (size_exp e0) Hlte (open_exp_wrt_exp e0 (e_var_f x)) Hsizeopen)).
        split.
        -- apply (deg_exp_open_term_dec 0 0 x e0 (le_n 0)). exact HdeE.
        -- apply (proj2 (deg_typ_of_open_term 0 0 x e0)). exact HdtE.
  - (* e_fixpoint *)
    assert (Hlte : size_exp e0 < n) by (pose proof size_typ_pos A; lia).
    split.
    + intros H. inversion H; subst.
      match goal with H : lc_typ A |- _ => rename H into HAlc end.
      match goal with H : forall x : termvar, lc_exp (open_exp_wrt_exp e0 (e_var_f x)) |- _ => rename H into Hbody end.
      destruct (atom_fresh (empty : atoms)) as [x _].
      specialize (Hbody x) as Hlcopen.
      assert (Hsizeopen : size_exp (open_exp_wrt_exp e0 (e_var_f x)) <= size_exp e0).
      { rewrite size_exp_open_term_f. apply le_n. }
      destruct (IH (size_exp e0) Hlte (open_exp_wrt_exp e0 (e_var_f x)) Hsizeopen)
        as [Hoe Hot].
      assert (HdeE : degree_exp_wrt_exp 1 e0).
      { apply (deg_exp_open_term_inv 0 0 x e0 (le_n 0)). exact (proj1 (Hoe Hlcopen)). }
      assert (HdtE : degree_exp_wrt_typ 0 e0).
      { apply (proj1 (deg_typ_of_open_term 0 0 x e0)). exact (proj2 (Hoe Hlcopen)). }
      assert (HdA : degree_typ_wrt_typ 0 A).
      { apply (proj1 (lc_typ_deg A)). exact HAlc. }
      split.
      * constructor. exact HdeE.
      * constructor; assumption.
    + intros [Hde Hdt]. inversion Hde; subst.
      match goal with H : degree_exp_wrt_exp (S 0) e0 |- _ => rename H into HdeE end.
      inversion Hdt; subst.
      match goal with H : degree_typ_wrt_typ 0 A |- _ => rename H into HdA end.
      match goal with H : degree_exp_wrt_typ 0 e0 |- _ => rename H into HdtE end.
      constructor.
      * apply (proj2 (lc_typ_deg A)). exact HdA.
      * intro x.
        assert (Hsizeopen : size_exp (open_exp_wrt_exp e0 (e_var_f x)) <= size_exp e0).
        { rewrite size_exp_open_term_f. apply le_n. }
        apply (proj2 (IH (size_exp e0) Hlte (open_exp_wrt_exp e0 (e_var_f x)) Hsizeopen)).
        split.
        -- apply (deg_exp_open_term_dec 0 0 x e0 (le_n 0)). exact HdeE.
        -- apply (proj2 (deg_typ_of_open_term 0 0 x e0)). exact HdtE.
  - (* e_app *)
    assert (Hlte1 : size_exp e1 < n) by (pose proof size_exp_pos e2; lia).
    assert (Hlte2 : size_exp e2 < n) by (pose proof size_exp_pos e1; lia).
    split.
    + intros H. inversion H; subst.
      match goal with H : lc_exp e1 |- _ => rename H into Hl1 end.
      match goal with H : lc_exp e2 |- _ => rename H into Hl2 end.
      destruct (IH (size_exp e1) Hlte1 e1 (le_n _)) as [H1 _].
      destruct (IH (size_exp e2) Hlte2 e2 (le_n _)) as [H2 _].
      destruct (H1 Hl1) as [Hde1 Hdt1].
      destruct (H2 Hl2) as [Hde2 Hdt2].
      split.
      * constructor; assumption.
      * constructor; assumption.
    + intros [Hde Hdt]. inversion Hde; subst.
      match goal with H : degree_exp_wrt_exp 0 e1 |- _ => rename H into Hde1 end.
      match goal with H : degree_exp_wrt_exp 0 e2 |- _ => rename H into Hde2 end.
      inversion Hdt; subst.
      match goal with H : degree_exp_wrt_typ 0 e1 |- _ => rename H into Hdt1 end.
      match goal with H : degree_exp_wrt_typ 0 e2 |- _ => rename H into Hdt2 end.
      destruct (IH (size_exp e1) Hlte1 e1 (le_n _)) as [_ H1].
      destruct (IH (size_exp e2) Hlte2 e2 (le_n _)) as [_ H2].
      constructor.
      * apply H1. split; assumption.
      * apply H2. split; assumption.
  - (* e_merge *)
    assert (Hlte1 : size_exp e1 < n) by (pose proof size_exp_pos e2; lia).
    assert (Hlte2 : size_exp e2 < n) by (pose proof size_exp_pos e1; lia).
    split.
    + intros H. inversion H; subst.
      match goal with H : lc_exp e1 |- _ => rename H into Hl1 end.
      match goal with H : lc_exp e2 |- _ => rename H into Hl2 end.
      destruct (IH (size_exp e1) Hlte1 e1 (le_n _)) as [H1 _].
      destruct (IH (size_exp e2) Hlte2 e2 (le_n _)) as [H2 _].
      destruct (H1 Hl1) as [Hde1 Hdt1].
      destruct (H2 Hl2) as [Hde2 Hdt2].
      split.
      * constructor; assumption.
      * constructor; assumption.
    + intros [Hde Hdt]. inversion Hde; subst.
      match goal with H : degree_exp_wrt_exp 0 e1 |- _ => rename H into Hde1 end.
      match goal with H : degree_exp_wrt_exp 0 e2 |- _ => rename H into Hde2 end.
      inversion Hdt; subst.
      match goal with H : degree_exp_wrt_typ 0 e1 |- _ => rename H into Hdt1 end.
      match goal with H : degree_exp_wrt_typ 0 e2 |- _ => rename H into Hdt2 end.
      destruct (IH (size_exp e1) Hlte1 e1 (le_n _)) as [_ H1].
      destruct (IH (size_exp e2) Hlte2 e2 (le_n _)) as [_ H2].
      constructor.
      * apply H1. split; assumption.
      * apply H2. split; assumption.
  - (* e_anno *)
    assert (Hlte : size_exp e0 < n) by (pose proof size_typ_pos A; lia).
    split.
    + intros H. inversion H; subst.
      match goal with H : lc_exp e0 |- _ => rename H into Hle end.
      match goal with H : lc_typ A |- _ => rename H into HlA end.
      destruct (IH (size_exp e0) Hlte e0 (le_n _)) as [H1 _].
      destruct (H1 Hle) as [Hde Hdt].
      assert (HdA : degree_typ_wrt_typ 0 A) by (apply (proj1 (lc_typ_deg A)); exact HlA).
      split.
      * constructor. exact Hde.
      * constructor; assumption.
    + intros [Hde Hdt]. inversion Hde; subst.
      match goal with H : degree_exp_wrt_exp 0 e0 |- _ => rename H into Hde1 end.
      inversion Hdt; subst.
      match goal with H : degree_exp_wrt_typ 0 e0 |- _ => rename H into Hdt1 end.
      match goal with H : degree_typ_wrt_typ 0 A |- _ => rename H into HdA end.
      destruct (IH (size_exp e0) Hlte e0 (le_n _)) as [_ H1].
      constructor.
      * apply H1. split; assumption.
      * apply (proj2 (lc_typ_deg A)). exact HdA.
  - (* e_rcd *)
    assert (Hlte : size_exp e0 < n) by lia.
    split.
    + intros H. inversion H; subst.
      match goal with H : lc_exp e0 |- _ => rename H into Hle end.
      destruct (IH (size_exp e0) Hlte e0 (le_n _)) as [H1 _].
      destruct (H1 Hle) as [Hde Hdt].
      split; constructor; assumption.
    + intros [Hde Hdt]. inversion Hde; subst.
      match goal with H : degree_exp_wrt_exp 0 e0 |- _ => rename H into Hde1 end.
      inversion Hdt; subst.
      match goal with H : degree_exp_wrt_typ 0 e0 |- _ => rename H into Hdt1 end.
      destruct (IH (size_exp e0) Hlte e0 (le_n _)) as [_ H1].
      constructor. apply H1. split; assumption.
  - (* e_proj *)
    assert (Hlte : size_exp e0 < n) by lia.
    split.
    + intros H. inversion H; subst.
      match goal with H : lc_exp e0 |- _ => rename H into Hle end.
      destruct (IH (size_exp e0) Hlte e0 (le_n _)) as [H1 _].
      destruct (H1 Hle) as [Hde Hdt].
      split; constructor; assumption.
    + intros [Hde Hdt]. inversion Hde; subst.
      match goal with H : degree_exp_wrt_exp 0 e0 |- _ => rename H into Hde1 end.
      inversion Hdt; subst.
      match goal with H : degree_exp_wrt_typ 0 e0 |- _ => rename H into Hdt1 end.
      destruct (IH (size_exp e0) Hlte e0 (le_n _)) as [_ H1].
      constructor. apply H1. split; assumption.
  - (* e_tabs *)
    assert (Hlte : size_exp e0 < n) by lia.
    split.
    + intros H. inversion H; subst.
      match goal with H : forall X : typevar, lc_exp (open_exp_wrt_typ e0 (t_tvar_f X)) |- _ => rename H into Hbody end.
      destruct (atom_fresh (empty : atoms)) as [X _].
      specialize (Hbody X) as Hlcopen.
      assert (Hsizeopen : size_exp (open_exp_wrt_typ e0 (t_tvar_f X)) <= size_exp e0).
      { rewrite size_exp_open_typ_f. apply le_n. }
      destruct (IH (size_exp e0) Hlte (open_exp_wrt_typ e0 (t_tvar_f X)) Hsizeopen)
        as [Hoe Hot].
      assert (HdeE : degree_exp_wrt_exp 0 e0).
      { apply (proj1 (deg_exp_of_open_typ 0 0 X e0)). exact (proj1 (Hoe Hlcopen)). }
      assert (HdtE : degree_exp_wrt_typ 1 e0).
      { apply (deg_exp_open_typ_inv 0 0 X e0 (le_n 0)). exact (proj2 (Hoe Hlcopen)). }
      split.
      * constructor. exact HdeE.
      * constructor. exact HdtE.
    + intros [Hde Hdt]. inversion Hde; subst.
      match goal with H : degree_exp_wrt_exp 0 e0 |- _ => rename H into Hde1 end.
      inversion Hdt; subst.
      match goal with H : degree_exp_wrt_typ (S 0) e0 |- _ => rename H into Hdt1 end.
      constructor.
      intro X.
      assert (Hsizeopen : size_exp (open_exp_wrt_typ e0 (t_tvar_f X)) <= size_exp e0).
      { rewrite size_exp_open_typ_f. apply le_n. }
      apply (proj2 (IH (size_exp e0) Hlte (open_exp_wrt_typ e0 (t_tvar_f X)) Hsizeopen)).
      split.
      * apply (proj2 (deg_exp_of_open_typ 0 0 X e0)). exact Hde1.
      * apply (deg_exp_open_typ_dec 0 0 X e0 (le_n 0)). exact Hdt1.
  - (* e_tapp *)
    assert (Hlte : size_exp e0 < n) by (pose proof size_typ_pos A; lia).
    split.
    + intros H. inversion H; subst.
      match goal with H : lc_exp e0 |- _ => rename H into Hle end.
      match goal with H : lc_typ A |- _ => rename H into HlA end.
      destruct (IH (size_exp e0) Hlte e0 (le_n _)) as [H1 _].
      destruct (H1 Hle) as [Hde Hdt].
      assert (HdA : degree_typ_wrt_typ 0 A) by (apply (proj1 (lc_typ_deg A)); exact HlA).
      split.
      * constructor. exact Hde.
      * constructor; assumption.
    + intros [Hde Hdt]. inversion Hde; subst.
      match goal with H : degree_exp_wrt_exp 0 e0 |- _ => rename H into Hde1 end.
      inversion Hdt; subst.
      match goal with H : degree_exp_wrt_typ 0 e0 |- _ => rename H into Hdt1 end.
      match goal with H : degree_typ_wrt_typ 0 A |- _ => rename H into HdA end.
      destruct (IH (size_exp e0) Hlte e0 (le_n _)) as [_ H1].
      constructor.
      * apply H1. split; assumption.
      * apply (proj2 (lc_typ_deg A)). exact HdA.
Qed.

Lemma lc_exp_deg : forall e,
    lc_exp e <-> (degree_exp_wrt_exp 0 e /\ degree_exp_wrt_typ 0 e).
Proof.
  intros e. exact (lc_exp_deg_aux (size_exp e) e (le_n _)).
Qed.

(* ============================================================ *)
(* Well-formedness and lc helpers                              *)
(* ============================================================ *)

Lemma TWell_lc : forall D A, TWell D A -> lc_typ A.
Proof.
  intros D A H. induction H as
    [D|D|D|D X A Hb|D l A HT IHr|D A B H1 IH1 H2 IH2|D A B H1 IH1 H2 IH2|L D A B HA IHA Hbody IHB].
  - apply lc_t_top.
  - apply lc_t_bot.
  - apply lc_t_int.
  - apply lc_t_tvar_f.
  - apply lc_t_rcd. exact IHr.
  - apply lc_t_arrow; assumption.
  - apply lc_t_and; assumption.
  - apply lc_t_forall.
    + exact IHA.
    + intro Y. destruct (atom_fresh L) as [X0 HX0].
      exact (lc_typ_open_free_inv 0 X0 Y B (IHB X0 HX0)).
Qed.

Lemma botLike_lc : forall A, botLike A -> lc_typ A.
Proof.
  intros A H. induction H as [|A B HlcB Hbl IHA|A B HlcA Hbl IHB].
  - apply lc_t_bot.
  - apply lc_t_and; assumption.
  - apply lc_t_and; assumption.
Qed.

Lemma ord_lc : forall A, ord A -> lc_typ A.
Proof.
  intros A H. induction H as
    [X| | | | A B HlcA HordB IHB|L A B HlcA Hbody IHB|l B HordB IHB].
  - apply lc_t_tvar_f.
  - apply lc_t_top.
  - apply lc_t_bot.
  - apply lc_t_int.
  - apply lc_t_arrow; assumption.
  - apply lc_t_forall.
    + exact HlcA.
    + intro Y. destruct (atom_fresh L) as [X0 HX0].
      exact (lc_typ_open_free_inv 0 X0 Y B (IHB X0 HX0)).
  - apply lc_t_rcd. exact IHB.
Qed.

Lemma topLike_TCWell : forall D B, topLike D B -> TCWell D.
Proof.
  intros D B H. induction H as
    [D HTC|D A B H1 IH1 H2 IH2|D A B HT H2 IH2|D l B H IH|L D A B Hbody IHB|D X A HTC Hb Hbl].
  - exact HTC.
  - exact IH1.
  - exact IH2.
  - exact IH.
  - destruct (atom_fresh L) as [X0 HX0].
    pose proof (IHB X0 HX0) as Hc. inversion Hc; subst; assumption.
  - exact HTC.
Qed.

Lemma topLike_lc : forall D B, topLike D B -> TCWell D -> lc_typ B.
Proof.
  intros D B H. induction H as
    [D Htc0|D A B H1 IH1 H2 IH2|D A B HT H2 IH2|D l B H IH|L D A B Hbody IHB|D X A Htc1 Hb Hbl];
    intros Hcw.
  - apply lc_t_top.
  - apply lc_t_and; [apply IH1; assumption | apply IH2; assumption].
  - apply lc_t_arrow; [exact (TWell_lc D A HT) | apply IH2; exact Hcw].
  - apply lc_t_rcd. apply IH; exact Hcw.
  - destruct (atom_fresh L) as [X0 HX0].
    assert (Hc : TCWell (cons (X0, A) D)) by (apply (topLike_TCWell (cons (X0, A) D) (open_typ_wrt_typ B (t_tvar_f X0))); apply Hbody; exact HX0).
    apply lc_t_forall.
    + inversion Hc; subst. match goal with Hh : TWell D A |- _ => exact (TWell_lc D A Hh) end.
    + intro Y. exact (lc_typ_open_free_inv 0 X0 Y B (IHB X0 HX0 Hc)).
  - apply lc_t_tvar_f.
Qed.

Lemma spl_lc : forall A B C, spl A B C -> lc_typ A /\ lc_typ B /\ lc_typ C.
Proof.
  intros A B C H. induction H as
    [A B C1 C2 HlcA Hsub IHsub|L A B C1 C2 HlcA Hbody IHB|l B C1 C2 Hsub IHsub|A B HlcA HlcB].
  - destruct IHsub as [HB [HC1 HC2] ].
    split.
    + apply lc_t_arrow; assumption.
    + split; apply lc_t_arrow; assumption.
  - destruct (atom_fresh L) as [X0 HX0].
    destruct (IHB X0 HX0) as [HB [HC1 HC2] ].
    split.
    + apply lc_t_forall; [exact HlcA | intro Y; exact (lc_typ_open_free_inv 0 X0 Y B HB)].
    + split.
      * apply lc_t_forall; [exact HlcA | intro Y; exact (lc_typ_open_free_inv 0 X0 Y C1 HC1)].
      * apply lc_t_forall; [exact HlcA | intro Y; exact (lc_typ_open_free_inv 0 X0 Y C2 HC2)].
  - destruct IHsub as [HB [HC1 HC2] ].
    split.
    + apply lc_t_rcd; exact HB.
    + split; apply lc_t_rcd; assumption.
  - split.
    + apply lc_t_and; assumption.
    + split; assumption.
Qed.

Lemma appDist_lc : forall A B, appDist A B -> lc_typ A /\ lc_typ B.
Proof.
  intros A B H. induction H as
    [A1 A2 B1 B2 C1 C2 Hd1 IH1 Hd2 IH2
    |A1 A2 l B1 B2 Hd1 IH1 Hd2 IH2
    |A1 A2 B1 B2 C1 C2 Hd1 IH1 Hd2 IH2
    |A Hlc].
  - destruct IH1 as [HA1 Harr1]. destruct IH2 as [HA2 Harr2].
    destruct (lc_typ_arrow_inv B1 C1 Harr1) as [HB1 HC1].
    destruct (lc_typ_arrow_inv B2 C2 Harr2) as [HB2 HC2].
    split.
    + apply lc_t_and; assumption.
    + apply lc_t_arrow; [apply lc_t_and; assumption | apply lc_t_and; assumption].
  - destruct IH1 as [HA1 Hr1]. destruct IH2 as [HA2 Hr2].
    pose proof (lc_typ_rcd_inv l B1 Hr1) as HB1.
    pose proof (lc_typ_rcd_inv l B2 Hr2) as HB2.
    split.
    + apply lc_t_and; assumption.
    + apply lc_t_rcd. apply lc_t_and; assumption.
  - destruct IH1 as [HA1 Hall1]. destruct IH2 as [HA2 Hall2].
    destruct (lc_typ_forall_inv B1 C1 Hall1) as [HB1 Hbody1].
    destruct (lc_typ_forall_inv B2 C2 Hall2) as [HB2 Hbody2].
    split.
    + apply lc_t_and; assumption.
    + apply lc_t_forall.
      * apply lc_t_and; assumption.
      * intro X. simpl. apply lc_t_and; [exact (Hbody1 X) | exact (Hbody2 X)].
  - split; assumption.
Qed.

Lemma algo_sub_lc : forall D A B, algo_sub D A B -> lc_typ A /\ lc_typ B.
Proof.
  intros D A B H. induction H as
    [D X HTC HT
    |D HTC
    |D A B HT Hord Htop
    |D A HTC HT Hord
    |D A B C HTB Hord Hsub IHsub
    |D A B C HTA Hord Hsub IHsub
    |D A1 B1 A2 B2 Hord Hsub1 IH1 Hsub2 IH2
    |L D A1 A2 B1 B2 Hords Hsub1 IH1 Hbody IHB
    |D l A B Hord Hsub IH
    |D A B B1 B2 Hspl Hsub1 IH1 Hsub2 IH2].
  - split; apply lc_t_tvar_f.
  - split; apply lc_t_int.
  - split.
    + exact (TWell_lc D A HT).
    + exact (topLike_lc D B Htop (topLike_TCWell D B Htop)).
  - split.
    + apply lc_t_bot.
    + exact (TWell_lc D A HT).
  - destruct IHsub as [HA HC].
    split.
    + apply lc_t_and; [exact HA | exact (TWell_lc D B HTB)].
    + exact HC.
  - destruct IHsub as [HB HC].
    split.
    + apply lc_t_and; [exact (TWell_lc D A HTA) | exact HB].
    + exact HC.
  - destruct IH1 as [HA2 HA1]. destruct IH2 as [HB1 HB2].
    split.
    + apply lc_t_arrow; assumption.
    + apply lc_t_arrow; assumption.
  - destruct (atom_fresh L) as [X0 HX0].
    destruct IH1 as [HB1 HA1].
    destruct (IHB X0 HX0) as [HA2open HB2open].
    split.
    + apply lc_t_forall; [exact HA1 | intro Y; exact (lc_typ_open_free_inv 0 X0 Y A2 HA2open)].
    + apply lc_t_forall; [exact HB1 | intro Y; exact (lc_typ_open_free_inv 0 X0 Y B2 HB2open)].
  - destruct IH as [HA HB].
    split.
    + apply lc_t_rcd; exact HA.
    + apply lc_t_rcd; exact HB.
  - destruct IH1 as [HA HB1].
    destruct (spl_lc B B1 B2 Hspl) as [HB _].
    split; assumption.
Qed.

Lemma disjoint_lc : forall D A B, disjoint D A B -> lc_typ A /\ lc_typ B.
Proof.
  intros D A B H. induction H as
    [D A B HTC HTA HTB Hax
    |D A B HTB HtopA
    |D A B HTA HtopB
    |D A1 A2 B1 B2 HT1 HT2 Hsub IHsub
    |D l A B Hsub IHsub
    |L D A1 B1 A2 B2 HT1 HT2 Hbody IHB
    |D X B A Hb Hsub
    |D B X A Hb Hsub
    |D A B A1 A2 Hspl Hsub1 IH1 Hsub2 IH2
    |D A B B1 B2 Hspl Hsub1 IH1 Hsub2 IH2].
  - split; [exact (TWell_lc D A HTA) | exact (TWell_lc D B HTB)].
  - split.
    + exact (topLike_lc D A HtopA (topLike_TCWell D A HtopA)).
    + exact (TWell_lc D B HTB).
  - split.
    + exact (TWell_lc D A HTA).
    + exact (topLike_lc D B HtopB (topLike_TCWell D B HtopB)).
  - pose proof (TWell_lc _ _ HT1) as Hl1.
    pose proof (TWell_lc _ _ HT2) as Hl2.
    destruct (lc_typ_arrow_inv A1 A2 Hl1) as [HA1 HA2].
    destruct (lc_typ_arrow_inv B1 B2 Hl2) as [HB1 HB2].
    split; apply lc_t_arrow; assumption.
  - destruct IHsub as [HA HB].
    split; apply lc_t_rcd; assumption.
  - destruct (atom_fresh L) as [X0 HX0].
    destruct (IHB X0 HX0) as [HB1 HB2].
    pose proof (TWell_lc _ _ HT1) as HA1.
    pose proof (TWell_lc _ _ HT2) as HA2.
    split.
    + apply lc_t_forall; [exact HA1 | intro Y; exact (lc_typ_open_free_inv 0 X0 Y B1 HB1)].
    + apply lc_t_forall; [exact HA2 | intro Y; exact (lc_typ_open_free_inv 0 X0 Y B2 HB2)].
  - destruct (algo_sub_lc D A B Hsub) as [HA HB].
    split; [apply lc_t_tvar_f | exact HB].
  - destruct (algo_sub_lc D A B Hsub) as [HA HB].
    split; [exact HB | apply lc_t_tvar_f].
  - destruct (spl_lc A A1 A2 Hspl) as [HA _].
    destruct IH1 as [_ HB].
    split; assumption.
  - destruct (spl_lc B B1 B2 Hspl) as [HB _].
    destruct IH1 as [HA _].
    split; assumption.
Qed.

(* ============================================================ *)
(* B3-B5                                                       *)
(* ============================================================ *)

Lemma TCWell_cons_inv : forall D X A, TCWell (cons (X, A) D) -> TCWell D /\ TWell D A.
Proof.
  intros D X A H. inversion H; subst; auto.
Qed.

Lemma TCWell_TWell : forall D X A, TCWell (cons (X, A) D) -> TWell D A.
Proof.
  intros D X A H. exact (proj2 (TCWell_cons_inv D X A H)).
Qed.

Lemma CWell_cons_inv : forall D G x A, CWell D (cons (x, A) G) -> CWell D G /\ TWell D A.
Proof.
  intros D G x A H. inversion H; subst; auto.
Qed.

Lemma CWell_binds : forall D G, CWell D G -> forall x A, binds x A G -> TWell D A.
Proof.
  intros D G H. induction H as [D|D G x A HCW IHCW HTW]; intros x0 A0 Hb.
  - apply binds_nil_iff in Hb. destruct Hb.
  - simpl in Hb. destruct Hb as [Heq | Hin].
    + injection Heq as Hx HA. subst. exact HTW.
    + exact (IHCW x0 A0 Hin).
Qed.

Lemma CWell_TWell_all : forall D G x A, CWell D G -> binds x A G -> lc_typ A.
Proof.
  intros D G x A HCW Hb.
  exact (TWell_lc D A (CWell_binds D G HCW x A Hb)).
Qed.

(* ============================================================ *)
(* B6: typing environment well-formedness                      *)
(* ============================================================ *)

Lemma typing_env_wf : forall D G e d A,
    Typing D G e d A -> TCWell D /\ CWell D G /\ uniq G.
Proof.
  intros D G e d A H. induction H as
    [D G HTC HCW Hu
    |D G i HTC HCW Hu
    |D G x A HTC HCW Hb Hu
    |L D G A e B1 B2 Hsub Hbody IHbody
    |D G e1 e2 C A B Ht1 IH1 Hdist Ht2 IH2
    |L D G e A B HCW Hbody IHbody
    |D G e A C2 B C1 Ht IH Hdist Hdisj
    |D G e l C A Ht IH Hdist
    |D G l e A Ht IH
    |D G e1 e2 A B Ht1 IH1 Ht2 IH2 Hdisj
    |D G e A B Ht1 IH1 Ht2 IH2
    |D G e A Ht IH
    |L D G A e Hbody IHbody
    |D G u1 u2 A B HTC HCW Hu Ht1 IH1 Ht2 IH2 Hcons
    |D G e B A Ht IH Hsub].
  - split; [exact HTC | split; assumption].
  - split; [exact HTC | split; assumption].
  - split; [exact HTC | split; assumption].
  - destruct (atom_fresh L) as [x Hx]. specialize (IHbody x Hx).
    destruct IHbody as [HTC [HCW Hu] ].
    split; [exact HTC | split].
    + exact (proj1 (CWell_cons_inv D G x A HCW)).
    + exact (uniq_cons_1 typ x A G Hu).
  - destruct IH1 as [HTC [HCW Hu] ].
    split; [exact HTC | split; assumption].
  - destruct (atom_fresh L) as [X HX]. specialize (IHbody X HX).
    destruct IHbody as [HTC [HCW2 Hu] ].
    split.
    + inversion HTC; subst; assumption.
    + split; [exact HCW | exact Hu].
  - destruct IH as [HTC [HCW Hu] ].
    split; [exact HTC | split; assumption].
  - destruct IH as [HTC [HCW Hu] ].
    split; [exact HTC | split; assumption].
  - destruct IH as [HTC [HCW Hu] ].
    split; [exact HTC | split; assumption].
  - destruct IH1 as [HTC [HCW Hu] ].
    split; [exact HTC | split; assumption].
  - destruct IH1 as [HTC [HCW Hu] ].
    split; [exact HTC | split; assumption].
  - destruct IH as [HTC [HCW Hu] ].
    split; [exact HTC | split; assumption].
  - destruct (atom_fresh L) as [x Hx]. specialize (IHbody x Hx).
    destruct IHbody as [HTC [HCW Hu] ].
    split; [exact HTC | split].
    + exact (proj1 (CWell_cons_inv D G x A HCW)).
    + exact (uniq_cons_1 typ x A G Hu).
  - split; [exact HTC | split; assumption].
  - destruct IH as [HTC [HCW Hu] ].
    split; [exact HTC | split; assumption].
Qed.

(* ============================================================ *)
(* B9: typing preserves degree 0 (and typing of exp)           *)
(* ============================================================ *)

Lemma typing_degree : forall D G e d A,
    Typing D G e d A ->
    degree_exp_wrt_exp 0 e /\ degree_exp_wrt_typ 0 e /\ degree_typ_wrt_typ 0 A.
Proof.
  intros D G e d A H. induction H as
    [D G HTC HCW Hu
    |D G i HTC HCW Hu
    |D G x A HTC HCW Hb Hu
    |L D G A e B1 B2 Hsub Hbody IHbody
    |D G e1 e2 C A B Ht1 IH1 Hdist Ht2 IH2
    |L D G e A B HCW Hbody IHbody
    |D G e A C2 B C1 Ht IH Hdist Hdisj
    |D G e l C A Ht IH Hdist
    |D G l e A Ht IH
    |D G e1 e2 A B Ht1 IH1 Ht2 IH2 Hdisj
    |D G e A B Ht1 IH1 Ht2 IH2
    |D G e A Ht IH
    |L D G A e Hbody IHbody
    |D G u1 u2 A B HTC HCW Hu Ht1 IH1 Ht2 IH2 Hcons
    |D G e B A Ht IH Hsub].
  - split; [constructor | split; constructor].
  - split; [constructor | split; constructor].
  - split; [constructor | split; [constructor | apply (proj1 (lc_typ_deg A)); apply (CWell_TWell_all D G x A HCW Hb)] ].
  - destruct (atom_fresh L) as [x Hx]. specialize (IHbody x Hx).
    destruct IHbody as [Hde [Hdt HdB2] ].
    destruct (algo_sub_lc D B1 A Hsub) as [HlcB1 HlcA].
    assert (HdB1 : degree_typ_wrt_typ 0 B1) by (apply (proj1 (lc_typ_deg B1)); exact HlcB1).
    assert (HdA : degree_typ_wrt_typ 0 A) by (apply (proj1 (lc_typ_deg A)); exact HlcA).
    assert (HdeE : degree_exp_wrt_exp 1 e) by (apply (deg_exp_open_term_inv 0 0 x e (le_n 0)); exact Hde).
    assert (HdtE : degree_exp_wrt_typ 0 e) by (apply (proj1 (deg_typ_of_open_term 0 0 x e)); exact Hdt).
    split.
    + constructor. exact HdeE.
    + split; [constructor; assumption | constructor; assumption].
  - destruct IH1 as [Hde1 [Hdt1 _] ].
    destruct IH2 as [Hde2 [Hdt2 _] ].
    destruct (appDist_lc A (t_arrow B C) Hdist) as [_ HlcArr].
    destruct (lc_typ_arrow_inv B C HlcArr) as [_ HlcC].
    assert (HdC : degree_typ_wrt_typ 0 C) by (apply (proj1 (lc_typ_deg C)); exact HlcC).
    split; [constructor; assumption | split; [constructor; assumption | exact HdC] ].
  - destruct (atom_fresh L) as [X HX]. specialize (IHbody X HX).
    destruct IHbody as [Hde [Hdt HdB] ].
    assert (HdB1 : degree_typ_wrt_typ 1 B) by (apply (deg_typ_open_inv 0 0 X B (le_n 0)); exact HdB).
    pose proof (proj1 (typing_env_wf (cons (X, A) D) G (open_exp_wrt_typ e (t_tvar_f X)) Chk (open_typ_wrt_typ B (t_tvar_f X)) (Hbody X HX))) as HTC.
    destruct (TCWell_cons_inv D X A HTC) as [_ HTA].
    assert (HdA : degree_typ_wrt_typ 0 A) by (apply (proj1 (lc_typ_deg A)); exact (TWell_lc D A HTA)).
    assert (HdeE : degree_exp_wrt_exp 0 e) by (apply (proj1 (deg_exp_of_open_typ 0 0 X e)); exact Hde).
    assert (HdtE : degree_exp_wrt_typ 1 e) by (apply (deg_exp_open_typ_inv 0 0 X e (le_n 0)); exact Hdt).
    split; [constructor; exact HdeE | split; [constructor; exact HdtE | constructor; assumption] ].
  - destruct IH as [Hde [Hdt _] ].
    destruct (disjoint_lc D A C1 Hdisj) as [HlcA _].
    assert (HdA : degree_typ_wrt_typ 0 A) by (apply (proj1 (lc_typ_deg A)); exact HlcA).
    destruct (appDist_lc B (t_forall C1 C2) Hdist) as [_ HlcAll].
    destruct (lc_typ_forall_inv C1 C2 HlcAll) as [_ HbodyC2].
    destruct (atom_fresh (empty : atoms)) as [X _].
    assert (Hdopen : degree_typ_wrt_typ 0 (open_typ_wrt_typ_rec 0 (t_tvar_f X) C2)).
    { apply (proj1 (lc_typ_deg (open_typ_wrt_typ_rec 0 (t_tvar_f X) C2))). exact (HbodyC2 X). }
    assert (HdopenA : degree_typ_wrt_typ 0 (open_typ_wrt_typ_rec 0 A C2)).
    { exact (deg_typ_open_subst 0 0 X C2 A HdA Hdopen). }
    split; [constructor; exact Hde | split; [constructor; assumption | exact HdopenA] ].
  - destruct IH as [Hde [Hdt _] ].
    destruct (appDist_lc A (t_rcd l C) Hdist) as [_ HlcR].
    assert (HdC : degree_typ_wrt_typ 0 C) by (apply (proj1 (lc_typ_deg C)); exact (lc_typ_rcd_inv l C HlcR)).
    split; [constructor; exact Hde | split; [constructor; exact Hdt | exact HdC] ].
  - destruct IH as [Hde [Hdt HdA] ].
    split; [constructor; exact Hde | split; [constructor; exact Hdt | constructor; exact HdA] ].
  - destruct IH1 as [Hde1 [Hdt1 HdA] ].
    destruct IH2 as [Hde2 [Hdt2 HdB] ].
    split; [constructor; assumption | split; [constructor; assumption | constructor; assumption] ].
  - destruct IH1 as [Hde1 [Hdt1 HdA] ].
    destruct IH2 as [_ [_ HdB] ].
    split; [exact Hde1 | split; [exact Hdt1 | constructor; assumption] ].
  - destruct IH as [Hde [Hdt HdA] ].
    split; [constructor; exact Hde | split; [constructor; assumption | exact HdA] ].
  - destruct (atom_fresh L) as [x Hx]. specialize (IHbody x Hx).
    destruct IHbody as [Hde [Hdt HdA] ].
    assert (HdeE : degree_exp_wrt_exp 1 e) by (apply (deg_exp_open_term_inv 0 0 x e (le_n 0)); exact Hde).
    assert (HdtE : degree_exp_wrt_typ 0 e) by (apply (proj1 (deg_typ_of_open_term 0 0 x e)); exact Hdt).
    split; [constructor; exact HdeE | split; [constructor; assumption | exact HdA] ].
  - destruct IH1 as [Hde1 [Hdt1 HdA] ].
    destruct IH2 as [Hde2 [Hdt2 HdB] ].
    split; [constructor; assumption | split; [constructor; assumption | constructor; assumption] ].
  - destruct IH as [Hde [Hdt _] ].
    destruct (algo_sub_lc D A B Hsub) as [_ HlcB].
    assert (HdB : degree_typ_wrt_typ 0 B) by (apply (proj1 (lc_typ_deg B)); exact HlcB).
    split; [exact Hde | split; [exact Hdt | exact HdB] ].
Qed.

(* ============================================================ *)
(* B7, B8                                                      *)
(* ============================================================ *)

Lemma typing_lc_typ : forall D G e d A, Typing D G e d A -> lc_typ A.
Proof.
  intros D G e d A H.
  apply (proj2 (lc_typ_deg A)).
  exact (proj2 (proj2 (typing_degree D G e d A H))).
Qed.

Lemma typing_lc_exp : forall D G e d A, Typing D G e d A -> lc_exp e.
Proof.
  intros D G e d A H.
  apply (proj2 (lc_exp_deg e)).
  split.
  - exact (proj1 (typing_degree D G e d A H)).
  - exact (proj1 (proj2 (typing_degree D G e d A H))).
Qed.
End agentB.
Import agentB.

Module agentC.
Import ListNotations.

(* ================================================================ *)
(* Auxiliary degree monotonicity lemmas (not present in support).    *)
(* ================================================================ *)

Lemma deg_exp_typ_mono : forall n m e,
    n <= m -> degree_exp_wrt_typ n e -> degree_exp_wrt_typ m e.
Proof.
  intros n m e. revert n m. induction e; intros dn dm Hle H; inversion H; subst.
  - constructor.
  - constructor.
  - constructor.
  - constructor.
  - constructor.
    + apply deg_typ_mono with (n := dn); assumption.
    + apply (IHe dn dm); assumption.
  - constructor.
    + apply deg_typ_mono with (n := dn); assumption.
    + apply (IHe dn dm); assumption.
  - constructor.
    + apply (IHe1 dn dm); assumption.
    + apply (IHe2 dn dm); assumption.
  - constructor.
    + apply (IHe1 dn dm); assumption.
    + apply (IHe2 dn dm); assumption.
  - constructor.
    + apply (IHe dn dm); assumption.
    + apply deg_typ_mono with (n := dn); assumption.
  - constructor. apply (IHe dn dm); assumption.
  - constructor. apply (IHe dn dm); assumption.
  - constructor. apply (IHe (S dn) (S dm)); [lia|assumption].
  - constructor.
    + apply (IHe dn dm); assumption.
    + apply deg_typ_mono with (n := dn); assumption.
Qed.

Lemma deg_exp_exp_mono : forall n m e,
    n <= m -> degree_exp_wrt_exp n e -> degree_exp_wrt_exp m e.
Proof.
  intros n m e. revert n m. induction e; intros dn dm Hle H; inversion H; subst.
  - constructor; lia.
  - constructor.
  - constructor.
  - constructor.
  - constructor. apply (IHe (S dn) (S dm)); [lia|assumption].
  - constructor. apply (IHe (S dn) (S dm)); [lia|assumption].
  - constructor.
    + apply (IHe1 dn dm); assumption.
    + apply (IHe2 dn dm); assumption.
  - constructor.
    + apply (IHe1 dn dm); assumption.
    + apply (IHe2 dn dm); assumption.
  - constructor. apply (IHe dn dm); assumption.
  - constructor. apply (IHe dn dm); assumption.
  - constructor. apply (IHe dn dm); assumption.
  - constructor. apply (IHe dn dm); assumption.
  - constructor. apply (IHe dn dm); assumption.
Qed.

(* ================================================================ *)
(* A locally closed type is left unchanged by opening at any level.  *)
(* ================================================================ *)

Lemma deg_open_identity : forall A d k (Cc:typ),
    d <= k -> degree_typ_wrt_typ d A ->
    open_typ_wrt_typ_rec k Cc A = A.
Proof.
  induction A; intros d k Cc Hle Hdeg; simpl.
  - destruct (lt_eq_lt_dec n k) as [ [Hlt|Heq] | Hgt]; simpl.
    + reflexivity.
    + inversion Hdeg; subst. exfalso; lia.
    + inversion Hdeg; subst. exfalso; lia.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - inversion Hdeg; subst.
    assert (E1 : open_typ_wrt_typ_rec k Cc A1 = A1)
      by (apply (IHA1 d k Cc); [assumption|assumption]).
    assert (E2 : open_typ_wrt_typ_rec (S k) Cc A2 = A2)
      by (apply (IHA2 (S d) (S k) Cc); [lia|assumption]).
    rewrite E1, E2. reflexivity.
  - inversion Hdeg; subst.
    assert (E1 : open_typ_wrt_typ_rec k Cc A1 = A1)
      by (apply (IHA1 d k Cc); [assumption|assumption]).
    assert (E2 : open_typ_wrt_typ_rec k Cc A2 = A2)
      by (apply (IHA2 d k Cc); [assumption|assumption]).
    rewrite E1, E2. reflexivity.
  - inversion Hdeg; subst.
    assert (E1 : open_typ_wrt_typ_rec k Cc A1 = A1)
      by (apply (IHA1 d k Cc); [assumption|assumption]).
    assert (E2 : open_typ_wrt_typ_rec k Cc A2 = A2)
      by (apply (IHA2 d k Cc); [assumption|assumption]).
    rewrite E1, E2. reflexivity.
  - inversion Hdeg; subst.
    assert (E1 : open_typ_wrt_typ_rec k Cc A = A)
      by (apply (IHA d k Cc); [assumption|assumption]).
    rewrite E1. reflexivity.
Qed.

(* ================================================================ *)
(* Simultaneous opening of the outermost [d] levels of a type.       *)
(* ================================================================ *)

Fixpoint C_agentC (d off : nat) (v : nat -> typevar) (A : typ) : typ :=
  match A with
  | t_tvar_b m =>
      if lt_dec m off then t_tvar_b m
      else if lt_dec m (off + d) then t_tvar_f (v (m - off))
      else t_tvar_b (m - d)
  | t_tvar_f X => t_tvar_f X
  | t_int => t_int
  | t_top => t_top
  | t_bot => t_bot
  | t_forall D E => t_forall (C_agentC d off v D) (C_agentC d (S off) v E)
  | t_arrow D E => t_arrow (C_agentC d off v D) (C_agentC d off v E)
  | t_and D E => t_and (C_agentC d off v D) (C_agentC d off v E)
  | t_rcd l D => t_rcd l (C_agentC d off v D)
  end.

Lemma C_agentC_bound : forall d off (v:nat -> typevar) m,
    C_agentC d off v (t_tvar_b m) =
    (if lt_dec m off then t_tvar_b m
     else if lt_dec m (off + d) then t_tvar_f (v (m - off))
     else t_tvar_b (m - d)).
Proof. intros. simpl. reflexivity. Qed.

(* One more opening step, at the level just below the pending range. *)
Lemma C_agentC_open : forall A off d (v:nat -> typevar) (Y:typevar),
    open_typ_wrt_typ_rec off (t_tvar_f Y) (C_agentC d (S off) v A) =
    C_agentC (S d) off (fun m => match m with 0 => Y | S m' => v m' end) A.
Proof.
  induction A; intros off d v Y; simpl.
  - (* t_tvar_b m *)
    destruct (lt_eq_lt_dec n off) as [ [Hlt|Heq] | Hgt].
    + (* n < off *)
      assert (H1 : n < S off) by lia.
      assert (H2 : n < S off + d) by lia.
      destruct (lt_dec n (S off)) as [_|Hc]; [|exfalso; lia].
      destruct (lt_dec n (S off + d)) as [_|Hc]; [|exfalso; lia].
      destruct (lt_dec n off) as [_|Hc]; [|exfalso; lia].
      destruct (lt_dec n (off + S d)) as [_|Hc]; [|exfalso; lia].
      simpl.
      destruct (lt_eq_lt_dec n off) as [ [Hc|Hc] | Hc];
        [reflexivity|exfalso; lia|exfalso; lia].
    + (* n = off *)
      subst n.
      assert (H2 : off < S off) by lia.
      assert (H3 : off < S off + d) by lia.
      destruct (lt_dec off (S off)) as [_|Hc]; [|exfalso; lia].
      destruct (lt_dec off (S off + d)) as [_|Hc]; [|exfalso; lia].
      destruct (lt_dec off off) as [Hc|_]; [exfalso; lia|].
      destruct (lt_dec off (off + S d)) as [_|Hc]; [|exfalso; lia].
      simpl.
      destruct (lt_eq_lt_dec off off) as [ [Hc|Hc] | Hc];
        [exfalso; lia|replace (off - off) with 0 by lia; simpl; reflexivity|exfalso; lia].
    + (* off < n *)
      assert (Hoff : ~ n < off) by lia.
      assert (HSoff : ~ n < S off) by lia.
      destruct (lt_dec n (S off)) as [Hc|_]; [exfalso; lia|].
      destruct (lt_dec n off) as [Hc|_]; [exfalso; lia|].
      destruct (lt_dec n (S (off + d))) as [Hlt2|Hge2].
      * (* n < S off + d : the value becomes a free variable *)
        assert (Hlt3 : n - off < S d) by lia.
        destruct (lt_dec n (off + S d)) as [_|Hc]; [|exfalso; lia].
        simpl.
        replace (n - off) with (S (n - S off)) by lia.
        simpl. reflexivity.
      * (* n >= S off + d : the value stays bound *)
        assert (Hge3 : ~ n - off < S d) by lia.
        destruct (lt_dec n (off + S d)) as [Hc|_]; [exfalso; lia|].
        (* open at [off] of [t_tvar_b (n-d)] with [n-d > off] *)
        simpl.
        destruct (lt_eq_lt_dec (n - d) off) as [ [Hc|Hc] | Hc];
          [exfalso; lia|exfalso; lia|].
        replace (n - d - 1) with (n - S d) by lia. reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - (* t_forall *)
    rewrite (IHA1 off d v Y). rewrite (IHA2 (S off) d v Y). reflexivity.
  - (* t_arrow *)
    rewrite (IHA1 off d v Y). rewrite (IHA2 off d v Y). reflexivity.
  - (* t_and *)
    rewrite (IHA1 off d v Y). rewrite (IHA2 off d v Y). reflexivity.
  - (* t_rcd *)
    rewrite (IHA off d v Y). reflexivity.
Qed.

Lemma C_agentC_zero : forall A off (v:nat -> typevar), C_agentC 0 off v A = A.
Proof.
  induction A; intros off v; simpl.
  - destruct (lt_dec n off) as [_|Hn].
    + reflexivity.
    + destruct (lt_dec n (off + 0)) as [Hc|_].
      * exfalso; lia.
      * rewrite Nat.sub_0_r. reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite IHA1, IHA2. reflexivity.
  - rewrite IHA1, IHA2. reflexivity.
  - rewrite IHA1, IHA2. reflexivity.
  - rewrite IHA. reflexivity.
Qed.

(* The main invariant: a type of degree [d], with its [d] outermost
   bound levels replaced by free variables, is locally closed. *)
Lemma deg_C : forall A d,
    degree_typ_wrt_typ d A -> forall v, lc_typ (C_agentC d 0 v A).
Proof.
  induction A; intros d Hdeg v; simpl.
  - (* t_tvar_b m *)
    inversion Hdeg; subst.
    destruct (lt_dec n 0) as [Hc|_]; [exfalso; lia|].
    destruct (lt_dec n d) as [_|Hc]; [|exfalso; lia].
    constructor.
  - constructor.
  - constructor.
  - constructor.
  - constructor.
  - (* t_forall *)
    inversion Hdeg; subst.
    apply lc_t_forall.
    + apply IHA1; assumption.
    + intro Y.
      change (lc_typ (open_typ_wrt_typ_rec 0 (t_tvar_f Y) (C_agentC d (S 0) v A2))).
      rewrite (C_agentC_open A2 0 d v Y).
      apply IHA2; assumption.
  - inversion Hdeg; subst.
    apply lc_t_arrow; [apply IHA1; assumption|apply IHA2; assumption].
  - inversion Hdeg; subst.
    apply lc_t_and; [apply IHA1; assumption|apply IHA2; assumption].
  - inversion Hdeg; subst.
    apply lc_t_rcd. apply IHA; assumption.
Qed.

(* ================================================================ *)
(* Item 1: locally closed types are exactly types of degree 0.       *)
(* ================================================================ *)

Lemma lc_typ_deg : forall A, lc_typ A -> degree_typ_wrt_typ 0 A.
Proof.
  apply (lc_typ_ind' (fun A _ => degree_typ_wrt_typ 0 A)).
  - intros X. constructor.
  - constructor.
  - constructor.
  - constructor.
  - intros A B l IHl l0 IHl0.
    apply degree_wrt_typ_t_forall.
    + apply IHl.
    + apply (deg_typ_open_inv 0 0 (Atom.fresh nil) B (le_n 0)).
      apply (IHl0 (Atom.fresh nil)).
  - intros A B l IHl l0 IHl0. constructor; assumption.
  - intros A B l IHl l0 IHl0. constructor; assumption.
  - intros l A l0 IHl0. constructor. assumption.
Qed.

Lemma deg_lc_typ : forall A, degree_typ_wrt_typ 0 A -> lc_typ A.
Proof.
  intros A H.
  rewrite <- (C_agentC_zero A 0 (fun _ => Atom.fresh nil)).
  apply deg_C. assumption.
Qed.

(* ================================================================ *)
(* Item 2: opening preserves the degree of a type.                   *)
(* ================================================================ *)

Lemma degree_typ_open_gen : forall n k A B,
    degree_typ_wrt_typ n A ->
    degree_typ_wrt_typ 0 B ->
    degree_typ_wrt_typ n (open_typ_wrt_typ_rec k B A).
Proof.
  intros n k A. revert k n.
  induction A as [m|X| | | |D IHD E IHE|D IHD E IHE|D IHD E IHE|l D IHD];
    intros k n B HA HB; inversion HA; subst; simpl.
  - destruct (lt_eq_lt_dec m k) as [ [Hlt|Heq] | Hgt].
    + apply degree_wrt_typ_t_tvar_b. lia.
    + subst m. apply deg_typ_mono with (n := 0); [lia|assumption].
    + apply degree_wrt_typ_t_tvar_b. lia.
  - constructor.
  - constructor.
  - constructor.
  - constructor.
  - constructor.
    + apply (IHD k n B); assumption.
    + apply (IHE (S k) (S n) B); assumption.
  - constructor.
    + apply (IHD k n B); assumption.
    + apply (IHE k n B); assumption.
  - constructor.
    + apply (IHD k n B); assumption.
    + apply (IHE k n B); assumption.
  - constructor. apply (IHD k n B); assumption.
Qed.

(* ================================================================ *)
(* Item 3: opening a locally closed type leaves it unchanged.        *)
(* ================================================================ *)

Lemma lc_typ_open_arg : forall k A B,
    lc_typ B -> lc_typ A -> lc_typ (open_typ_wrt_typ_rec k B A).
Proof.
  intros k A B _ HA.
  rewrite (deg_open_identity A 0 k B (le_0_n k) (lc_typ_deg A HA)).
  assumption.
Qed.

(* ================================================================ *)
(* Item 4: type substitution preserves the degree of a type.         *)
(* ================================================================ *)

Lemma degree_typ_typsubst : forall n A X B,
    degree_typ_wrt_typ n A ->
    degree_typ_wrt_typ n B ->
    degree_typ_wrt_typ n (typsubst_typ A X B).
Proof.
  intros n A X B. revert n.
  induction B as [m|X0| | | |D IHD E IHE|D IHD E IHE|D IHD E IHE|l D IHD];
    intros n HA HB; simpl.
  - inversion HB; subst. constructor. assumption.
  - destruct (eq_var X0 X) as [Heq|Hneq]; [assumption|constructor].
  - constructor.
  - constructor.
  - constructor.
  - inversion HB; subst.
    apply degree_wrt_typ_t_forall.
    + apply (IHD n); assumption.
    + apply (IHE (S n)).
      * apply deg_typ_mono with (n := n); [lia|assumption].
      * assumption.
  - inversion HB; subst.
    apply degree_wrt_typ_t_arrow; [apply (IHD n); assumption|apply (IHE n); assumption].
  - inversion HB; subst.
    apply degree_wrt_typ_t_and; [apply (IHD n); assumption|apply (IHE n); assumption].
  - inversion HB; subst.
    apply degree_wrt_typ_t_rcd. apply (IHD n); assumption.
Qed.

(* ================================================================ *)
(* Item 5: type substitution preserves the type-degree of an exp.    *)
(* ================================================================ *)

Lemma degree_exp_wrt_typ_typsubst : forall e n A X,
    degree_typ_wrt_typ n A ->
    degree_exp_wrt_typ n e ->
    degree_exp_wrt_typ n (typsubst_exp A X e).
Proof.
  intros e n A X. revert n A X.
  induction e as [m|x| |i|D e1 IHe1|D e1 IHe1|e1 IHe1 e2 IHe2
                 |e1 IHe1 e2 IHe2|e1 IHe1 D|D e1 IHe1|e1 IHe1 l|e1 IHe1|e1 IHe1 D];
    intros n A X HA He; simpl.
  - constructor.
  - constructor.
  - constructor.
  - constructor.
  - inversion He; subst.
    apply degree_wrt_typ_e_abs.
    + apply degree_typ_typsubst; assumption.
    + apply (IHe1 n A X); assumption.
  - inversion He; subst.
    apply degree_wrt_typ_e_fixpoint.
    + apply degree_typ_typsubst; assumption.
    + apply (IHe1 n A X); assumption.
  - inversion He; subst.
    apply degree_wrt_typ_e_app.
    + apply (IHe1 n A X); assumption.
    + apply (IHe2 n A X); assumption.
  - inversion He; subst.
    apply degree_wrt_typ_e_merge.
    + apply (IHe1 n A X); assumption.
    + apply (IHe2 n A X); assumption.
  - inversion He; subst.
    apply degree_wrt_typ_e_anno.
    + apply (IHe1 n A X); assumption.
    + apply degree_typ_typsubst; assumption.
  - inversion He; subst.
    apply degree_wrt_typ_e_rcd. apply (IHe1 n A X); assumption.
  - inversion He; subst.
    apply degree_wrt_typ_e_proj. apply (IHe1 n A X); assumption.
  - inversion He; subst.
    apply degree_wrt_typ_e_tabs.
    apply (IHe1 (S n) A X).
    + apply deg_typ_mono with (n := n); [lia|assumption].
    + assumption.
  - inversion He; subst.
    apply degree_wrt_typ_e_tapp.
    + apply (IHe1 n A X); assumption.
    + apply degree_typ_typsubst; assumption.
Qed.

(* ================================================================ *)
(* Item 6: type substitution preserves the term-degree of an exp.    *)
(* ================================================================ *)

Lemma degree_exp_wrt_exp_typsubst : forall e n A X,
    degree_exp_wrt_exp n e ->
    degree_exp_wrt_exp n (typsubst_exp A X e).
Proof.
  intros e n A X. revert n A X.
  induction e as [m|x| |i|D e1 IHe1|D e1 IHe1|e1 IHe1 e2 IHe2
                 |e1 IHe1 e2 IHe2|e1 IHe1 D|D e1 IHe1|e1 IHe1 l|e1 IHe1|e1 IHe1 D];
    intros n A X He; simpl.
  - inversion He; subst. constructor. assumption.
  - constructor.
  - constructor.
  - constructor.
  - inversion He; subst. apply degree_wrt_exp_e_abs.
    apply (IHe1 (S n) A X); assumption.
  - inversion He; subst. apply degree_wrt_exp_e_fixpoint.
    apply (IHe1 (S n) A X); assumption.
  - inversion He; subst. apply degree_wrt_exp_e_app.
    + apply (IHe1 n A X); assumption.
    + apply (IHe2 n A X); assumption.
  - inversion He; subst. apply degree_wrt_exp_e_merge.
    + apply (IHe1 n A X); assumption.
    + apply (IHe2 n A X); assumption.
  - inversion He; subst. apply degree_wrt_exp_e_anno.
    apply (IHe1 n A X); assumption.
  - inversion He; subst. apply degree_wrt_exp_e_rcd.
    apply (IHe1 n A X); assumption.
  - inversion He; subst. apply degree_wrt_exp_e_proj.
    apply (IHe1 n A X); assumption.
  - inversion He; subst. apply degree_wrt_exp_e_tabs.
    apply (IHe1 n A X); assumption.
  - inversion He; subst. apply degree_wrt_exp_e_tapp.
    apply (IHe1 n A X); assumption.
Qed.

(* ================================================================ *)
(* Item 7: term substitution preserves the type-degree of an exp.    *)
(* ================================================================ *)

Lemma degree_exp_wrt_typ_subst_exp : forall e n e' x,
    degree_exp_wrt_typ n e' ->
    degree_exp_wrt_typ n e ->
    degree_exp_wrt_typ n (subst_exp e' x e).
Proof.
  intros e n e' x. revert n e' x.
  induction e as [m|x0| |i|D e1 IHe1|D e1 IHe1|e1 IHe1 e2 IHe2
                 |e1 IHe1 e2 IHe2|e1 IHe1 D|D e1 IHe1|e1 IHe1 l|e1 IHe1|e1 IHe1 D];
    intros n e' x He' He; simpl.
  - constructor.
  - destruct (eq_var x0 x) as [Heq|Hneq]; [assumption|constructor].
  - constructor.
  - constructor.
  - inversion He; subst. apply degree_wrt_typ_e_abs.
    + assumption.
    + apply (IHe1 n e' x); assumption.
  - inversion He; subst. apply degree_wrt_typ_e_fixpoint.
    + assumption.
    + apply (IHe1 n e' x); assumption.
  - inversion He; subst. apply degree_wrt_typ_e_app.
    + apply (IHe1 n e' x); assumption.
    + apply (IHe2 n e' x); assumption.
  - inversion He; subst. apply degree_wrt_typ_e_merge.
    + apply (IHe1 n e' x); assumption.
    + apply (IHe2 n e' x); assumption.
  - inversion He; subst. apply degree_wrt_typ_e_anno.
    + apply (IHe1 n e' x); assumption.
    + assumption.
  - inversion He; subst. apply degree_wrt_typ_e_rcd.
    apply (IHe1 n e' x); assumption.
  - inversion He; subst. apply degree_wrt_typ_e_proj.
    apply (IHe1 n e' x); assumption.
  - inversion He; subst. apply degree_wrt_typ_e_tabs.
    apply (IHe1 (S n) e' x).
    + apply deg_exp_typ_mono with (n := n); [lia|assumption].
    + assumption.
  - inversion He; subst. apply degree_wrt_typ_e_tapp.
    + apply (IHe1 n e' x); assumption.
    + assumption.
Qed.

(* ================================================================ *)
(* Item 8: term substitution preserves the term-degree of an exp.    *)
(* ================================================================ *)

Lemma degree_exp_wrt_exp_subst_exp : forall e n e' x,
    degree_exp_wrt_exp n e' ->
    degree_exp_wrt_exp n e ->
    degree_exp_wrt_exp n (subst_exp e' x e).
Proof.
  intros e n e' x. revert n e' x.
  induction e as [m|x0| |i|D e1 IHe1|D e1 IHe1|e1 IHe1 e2 IHe2
                 |e1 IHe1 e2 IHe2|e1 IHe1 D|D e1 IHe1|e1 IHe1 l|e1 IHe1|e1 IHe1 D];
    intros n e' x He' He; simpl.
  - inversion He; subst. constructor. assumption.
  - destruct (eq_var x0 x) as [Heq|Hneq]; [assumption|constructor].
  - constructor.
  - constructor.
  - inversion He; subst. apply degree_wrt_exp_e_abs.
    apply (IHe1 (S n) e' x).
    + apply deg_exp_exp_mono with (n := n); [lia|assumption].
    + assumption.
  - inversion He; subst. apply degree_wrt_exp_e_fixpoint.
    apply (IHe1 (S n) e' x).
    + apply deg_exp_exp_mono with (n := n); [lia|assumption].
    + assumption.
  - inversion He; subst. apply degree_wrt_exp_e_app.
    + apply (IHe1 n e' x); assumption.
    + apply (IHe2 n e' x); assumption.
  - inversion He; subst. apply degree_wrt_exp_e_merge.
    + apply (IHe1 n e' x); assumption.
    + apply (IHe2 n e' x); assumption.
  - inversion He; subst. apply degree_wrt_exp_e_anno.
    apply (IHe1 n e' x); assumption.
  - inversion He; subst. apply degree_wrt_exp_e_rcd.
    apply (IHe1 n e' x); assumption.
  - inversion He; subst. apply degree_wrt_exp_e_proj.
    apply (IHe1 n e' x); assumption.
  - inversion He; subst. apply degree_wrt_exp_e_tabs.
    apply (IHe1 n e' x); assumption.
  - inversion He; subst. apply degree_wrt_exp_e_tapp.
    apply (IHe1 n e' x); assumption.
Qed.

(* ================================================================ *)
(* Expression-level simultaneous opening for type and term levels.   *)
(* ================================================================ *)

Fixpoint Cexp_agentC (dt ot de oe : nat) (vt : nat -> typevar) (ve : nat -> termvar)
    (e : exp) : exp :=
  match e with
  | e_var_b m =>
      if lt_dec m oe then e_var_b m
      else if lt_dec m (oe + de) then e_var_f (ve (m - oe))
      else e_var_b (m - de)
  | e_var_f x => e_var_f x
  | e_top => e_top
  | e_lit i => e_lit i
  | e_abs A e1 => e_abs (C_agentC dt ot vt A) (Cexp_agentC dt ot de (S oe) vt ve e1)
  | e_fixpoint A e1 => e_fixpoint (C_agentC dt ot vt A) (Cexp_agentC dt ot de (S oe) vt ve e1)
  | e_app e1 e2 => e_app (Cexp_agentC dt ot de oe vt ve e1) (Cexp_agentC dt ot de oe vt ve e2)
  | e_merge e1 e2 => e_merge (Cexp_agentC dt ot de oe vt ve e1) (Cexp_agentC dt ot de oe vt ve e2)
  | e_anno e1 A => e_anno (Cexp_agentC dt ot de oe vt ve e1) (C_agentC dt ot vt A)
  | e_rcd l e1 => e_rcd l (Cexp_agentC dt ot de oe vt ve e1)
  | e_proj e1 l => e_proj (Cexp_agentC dt ot de oe vt ve e1) l
  | e_tabs e1 => e_tabs (Cexp_agentC dt (S ot) de oe vt ve e1)
  | e_tapp e1 A => e_tapp (Cexp_agentC dt ot de oe vt ve e1) (C_agentC dt ot vt A)
  end.

Lemma TypeOpen : forall e ot dt de oe (vt : nat -> typevar) ve (Y : typevar),
    open_exp_wrt_typ_rec ot (t_tvar_f Y) (Cexp_agentC dt (S ot) de oe vt ve e) =
    Cexp_agentC (S dt) ot de oe
      (fun m => match m with 0 => Y | S m' => vt m' end) ve e.
Proof.
  induction e as [m|x| |i|D e1 IHe1|D e1 IHe1|e1 IHe1 e2 IHe2
                 |e1 IHe1 e2 IHe2|e1 IHe1 D|D e1 IHe1|e1 IHe1 l|e1 IHe1|e1 IHe1 D];
    intros ot dt de oe vt ve Y; simpl.
  - destruct (lt_dec m oe) as [Hlt|_]; simpl.
    + reflexivity.
    + destruct (lt_dec m (oe + de)) as [Hin|_]; simpl; reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite (C_agentC_open D ot dt vt Y). rewrite (IHe1 ot dt de (S oe) vt ve Y).
    reflexivity.
  - rewrite (C_agentC_open D ot dt vt Y). rewrite (IHe1 ot dt de (S oe) vt ve Y).
    reflexivity.
  - rewrite (IHe1 ot dt de oe vt ve Y). rewrite (IHe2 ot dt de oe vt ve Y).
    reflexivity.
  - rewrite (IHe1 ot dt de oe vt ve Y). rewrite (IHe2 ot dt de oe vt ve Y).
    reflexivity.
  - rewrite (IHe1 ot dt de oe vt ve Y). rewrite (C_agentC_open D ot dt vt Y).
    reflexivity.
  - rewrite (IHe1 ot dt de oe vt ve Y). reflexivity.
  - rewrite (IHe1 ot dt de oe vt ve Y). reflexivity.
  - rewrite (IHe1 (S ot) dt de oe vt ve Y). reflexivity.
  - rewrite (IHe1 ot dt de oe vt ve Y). rewrite (C_agentC_open D ot dt vt Y).
    reflexivity.
Qed.

Lemma TermOpen : forall e dt ot de oe (vt : nat -> typevar) ve (x : termvar),
    open_exp_wrt_exp_rec oe (e_var_f x) (Cexp_agentC dt ot de (S oe) vt ve e) =
    Cexp_agentC dt ot (S de) oe vt
      (fun m => match m with 0 => x | S m' => ve m' end) e.
Proof.
  induction e as [m|x0| |i|D e1 IHe1|D e1 IHe1|e1 IHe1 e2 IHe2
                 |e1 IHe1 e2 IHe2|e1 IHe1 D|D e1 IHe1|e1 IHe1 l|e1 IHe1|e1 IHe1 D];
    intros dt ot de oe vt ve x; simpl.
  - destruct (lt_eq_lt_dec m oe) as [ [Hlt|Heq] | Hgt].
    + destruct (lt_dec m (S oe)) as [_|Hc]; [|exfalso; lia].
      destruct (lt_dec m oe) as [_|Hc]; [|exfalso; lia].
      simpl.
      destruct (lt_eq_lt_dec m oe) as [ [Hc|Hc] | Hc];
        [reflexivity|exfalso; lia|exfalso; lia].
    + subst m.
      destruct (lt_dec oe (S oe)) as [_|Hc]; [|exfalso; lia].
      destruct (lt_dec oe oe) as [Hc|_]; [exfalso; lia|].
      destruct (lt_dec oe (oe + S de)) as [_|Hc]; [|exfalso; lia].
      simpl.
      destruct (lt_eq_lt_dec oe oe) as [ [Hc|Hc] | Hc];
        [exfalso; lia|replace (oe - oe) with 0 by lia; simpl; reflexivity|exfalso; lia].
    + destruct (lt_dec m (S oe)) as [Hc|_]; [exfalso; lia|].
      destruct (lt_dec m oe) as [Hc|_]; [exfalso; lia|].
      destruct (lt_dec m (S (oe + de))) as [Hlt2|Hge2].
      * destruct (lt_dec m (oe + S de)) as [_|Hc]; [|exfalso; lia].
        simpl.
        replace (m - oe) with (S (m - S oe)) by lia.
        simpl. reflexivity.
      * destruct (lt_dec m (oe + S de)) as [Hc|_]; [exfalso; lia|].
        simpl.
        destruct (lt_eq_lt_dec (m - de) oe) as [ [Hc|Hc] | Hc];
          [exfalso; lia|exfalso; lia|].
        replace (m - de - 1) with (m - S de) by lia. reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite (IHe1 dt ot de (S oe) vt ve x). reflexivity.
  - rewrite (IHe1 dt ot de (S oe) vt ve x). reflexivity.
  - rewrite (IHe1 dt ot de oe vt ve x). rewrite (IHe2 dt ot de oe vt ve x).
    reflexivity.
  - rewrite (IHe1 dt ot de oe vt ve x). rewrite (IHe2 dt ot de oe vt ve x).
    reflexivity.
  - rewrite (IHe1 dt ot de oe vt ve x). reflexivity.
  - rewrite (IHe1 dt ot de oe vt ve x). reflexivity.
  - rewrite (IHe1 dt ot de oe vt ve x). reflexivity.
  - rewrite (IHe1 dt (S ot) de oe vt ve x). reflexivity.
  - rewrite (IHe1 dt ot de oe vt ve x). reflexivity.
Qed.

Lemma Cexp_zero : forall e ot oe (vt : nat -> typevar) (ve : nat -> termvar),
    Cexp_agentC 0 ot 0 oe vt ve e = e.
Proof.
  induction e as [m|x| |i|D e1 IHe1|D e1 IHe1|e1 IHe1 e2 IHe2
                 |e1 IHe1 e2 IHe2|e1 IHe1 D|D e1 IHe1|e1 IHe1 l|e1 IHe1|e1 IHe1 D];
    intros ot oe vt ve; simpl.
  - destruct (lt_dec m oe) as [Hlt|Hge]; [reflexivity|].
    destruct (lt_dec m (oe + 0)) as [Hc|_]; [exfalso; lia|].
    rewrite Nat.sub_0_r. reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite C_agentC_zero. rewrite (IHe1 ot (S oe) vt ve). reflexivity.
  - rewrite C_agentC_zero. rewrite (IHe1 ot (S oe) vt ve). reflexivity.
  - rewrite (IHe1 ot oe vt ve). rewrite (IHe2 ot oe vt ve). reflexivity.
  - rewrite (IHe1 ot oe vt ve). rewrite (IHe2 ot oe vt ve). reflexivity.
  - rewrite (IHe1 ot oe vt ve). rewrite C_agentC_zero. reflexivity.
  - rewrite (IHe1 ot oe vt ve). reflexivity.
  - rewrite (IHe1 ot oe vt ve). reflexivity.
  - rewrite (IHe1 (S ot) oe vt ve). reflexivity.
  - rewrite (IHe1 ot oe vt ve). rewrite C_agentC_zero. reflexivity.
Qed.

(* The main invariant for expressions. *)
Lemma deg_Cexp : forall e dt de,
    degree_exp_wrt_typ dt e ->
    degree_exp_wrt_exp de e ->
    forall vt ve, lc_exp (Cexp_agentC dt 0 de 0 vt ve e).
Proof.
  induction e as [m|x| |i|D e1 IHe1|D e1 IHe1|e1 IHe1 e2 IHe2
                 |e1 IHe1 e2 IHe2|e1 IHe1 D|D e1 IHe1|e1 IHe1 l|e1 IHe1|e1 IHe1 D];
    intros dt de Ht He vt ve; simpl.
  - inversion He; subst.
    destruct (lt_dec m 0) as [Hc|_]; [exfalso; lia|].
    destruct (lt_dec m de) as [_|Hc]; [|exfalso; lia].
    apply lc_e_var_f.
  - apply lc_e_var_f.
  - apply lc_e_top.
  - apply lc_e_lit.
  - inversion Ht; subst. inversion He; subst.
    apply lc_e_abs.
    + apply deg_C; assumption.
    + intro x.
      change (lc_exp (open_exp_wrt_exp_rec 0 (e_var_f x)
                        (Cexp_agentC dt 0 de 1 vt ve e1))).
      rewrite (TermOpen e1 dt 0 de 0 vt ve x).
      apply (IHe1 dt (S de)); assumption.
  - inversion Ht; subst. inversion He; subst.
    apply lc_e_fixpoint.
    + apply deg_C; assumption.
    + intro x.
      change (lc_exp (open_exp_wrt_exp_rec 0 (e_var_f x)
                        (Cexp_agentC dt 0 de 1 vt ve e1))).
      rewrite (TermOpen e1 dt 0 de 0 vt ve x).
      apply (IHe1 dt (S de)); assumption.
  - inversion Ht; subst. inversion He; subst.
    apply lc_e_app.
    + apply (IHe1 dt de); assumption.
    + apply (IHe2 dt de); assumption.
  - inversion Ht; subst. inversion He; subst.
    apply lc_e_merge.
    + apply (IHe1 dt de); assumption.
    + apply (IHe2 dt de); assumption.
  - inversion Ht; subst. inversion He; subst.
    apply lc_e_anno.
    + apply (IHe1 dt de); assumption.
    + apply deg_C; assumption.
  - inversion Ht; subst. inversion He; subst.
    apply lc_e_rcd. apply (IHe1 dt de); assumption.
  - inversion Ht; subst. inversion He; subst.
    apply lc_e_proj. apply (IHe1 dt de); assumption.
  - inversion Ht; subst. inversion He; subst.
    apply lc_e_tabs.
    intro X.
    change (lc_exp (open_exp_wrt_typ_rec 0 (t_tvar_f X)
                      (Cexp_agentC dt 1 de 0 vt ve e1))).
    rewrite (TypeOpen e1 0 dt de 0 vt ve X).
    apply (IHe1 (S dt) de); assumption.
  - inversion Ht; subst. inversion He; subst.
    apply lc_e_tapp.
    + apply (IHe1 dt de); assumption.
    + apply deg_C; assumption.
Qed.

Lemma lc_exp_deg : forall e, lc_exp e -> degree_exp_wrt_typ 0 e.
Proof.
  apply (lc_exp_ind' (fun e _ => degree_exp_wrt_typ 0 e)).
  - intros x. apply degree_wrt_typ_e_var_f.
  - apply degree_wrt_typ_e_top.
  - intros i. apply degree_wrt_typ_e_lit.
  - intros A e l l0 IH.
    apply degree_wrt_typ_e_abs.
    + apply lc_typ_deg. assumption.
    + apply (proj1 (deg_typ_of_open_term 0 0 (Atom.fresh nil) e)).
      apply (IH (Atom.fresh nil)).
  - intros A e l l0 IH.
    apply degree_wrt_typ_e_fixpoint.
    + apply lc_typ_deg. assumption.
    + apply (proj1 (deg_typ_of_open_term 0 0 (Atom.fresh nil) e)).
      apply (IH (Atom.fresh nil)).
  - intros e1 e2 l IH1 l0 IH2. apply degree_wrt_typ_e_app; assumption.
  - intros e1 e2 l IH1 l0 IH2. apply degree_wrt_typ_e_merge; assumption.
  - intros e A l IH l0. apply degree_wrt_typ_e_anno.
    + assumption.
    + apply lc_typ_deg. assumption.
  - intros l e l0 IH. apply degree_wrt_typ_e_rcd. assumption.
  - intros e l l0 IH. apply degree_wrt_typ_e_proj. assumption.
  - intros e l IH.
    apply degree_wrt_typ_e_tabs.
    apply (deg_exp_open_typ_inv 0 0 (Atom.fresh nil) e (le_n 0)).
    apply (IH (Atom.fresh nil)).
  - intros e A l IH l0. apply degree_wrt_typ_e_tapp.
    + assumption.
    + apply lc_typ_deg. assumption.
Qed.

Lemma lc_exp_deg_exp : forall e, lc_exp e -> degree_exp_wrt_exp 0 e.
Proof.
  apply (lc_exp_ind' (fun e _ => degree_exp_wrt_exp 0 e)).
  - intros x. apply degree_wrt_exp_e_var_f.
  - apply degree_wrt_exp_e_top.
  - intros i. apply degree_wrt_exp_e_lit.
  - intros A e l l0 IH.
    apply degree_wrt_exp_e_abs.
    apply (deg_exp_open_term_inv 0 0 (Atom.fresh nil) e (le_n 0)).
    apply (IH (Atom.fresh nil)).
  - intros A e l l0 IH.
    apply degree_wrt_exp_e_fixpoint.
    apply (deg_exp_open_term_inv 0 0 (Atom.fresh nil) e (le_n 0)).
    apply (IH (Atom.fresh nil)).
  - intros e1 e2 l IH1 l0 IH2. apply degree_wrt_exp_e_app; assumption.
  - intros e1 e2 l IH1 l0 IH2. apply degree_wrt_exp_e_merge; assumption.
  - intros e A l IH l0. apply degree_wrt_exp_e_anno. assumption.
  - intros l e l0 IH. apply degree_wrt_exp_e_rcd. assumption.
  - intros e l l0 IH. apply degree_wrt_exp_e_proj. assumption.
  - intros e l IH.
    apply degree_wrt_exp_e_tabs.
    apply (proj1 (deg_exp_of_open_typ 0 0 (Atom.fresh nil) e)).
    apply (IH (Atom.fresh nil)).
  - intros e A l IH l0. apply degree_wrt_exp_e_tapp. assumption.
Qed.

(* Corrected form of the converse: both degrees are needed, because
   [degree_exp_wrt_typ] does not constrain bound term variables.        *)
Lemma deg_lc_exp : forall e,
    degree_exp_wrt_typ 0 e ->
    degree_exp_wrt_exp 0 e ->
    lc_exp e.
Proof.
  intros e H1 H2.
  rewrite <- (Cexp_zero e 0 0 (fun _ => Atom.fresh nil) (fun _ => Atom.fresh nil)).
  apply deg_Cexp; assumption.
Qed.

(* ================================================================ *)
(* Item 9: type substitution preserves local closure of expressions. *)
(* ================================================================ *)

Lemma lc_exp_typsubst : forall A X e,
    lc_typ A -> lc_exp e -> lc_exp (typsubst_exp A X e).
Proof.
  intros A X e HA He.
  apply deg_lc_exp.
  - apply (degree_exp_wrt_typ_typsubst e 0 A X).
    + apply lc_typ_deg. assumption.
    + apply lc_exp_deg. assumption.
  - apply (degree_exp_wrt_exp_typsubst e 0 A X).
    apply lc_exp_deg_exp. assumption.
Qed.

(* ================================================================ *)
(* Item 10: type substitution preserves local closure of types.      *)
(* ================================================================ *)

Lemma lc_typ_typsubst : forall A X B,
    lc_typ A -> lc_typ B -> lc_typ (typsubst_typ A X B).
Proof.
  intros A X B HA HB.
  apply deg_lc_typ.
  apply (degree_typ_typsubst 0 A X B).
  - apply lc_typ_deg. assumption.
  - apply lc_typ_deg. assumption.
Qed.

(* ================================================================ *)
(* Item 11: term substitution preserves local closure.               *)
(* ================================================================ *)

Lemma lc_exp_subst_exp : forall e' x e,
    lc_exp e' -> lc_exp e -> lc_exp (subst_exp e' x e).
Proof.
  intros e' x e He' He.
  apply deg_lc_exp.
  - apply (degree_exp_wrt_typ_subst_exp e 0 e' x).
    + apply lc_exp_deg. assumption.
    + apply lc_exp_deg. assumption.
  - apply (degree_exp_wrt_exp_subst_exp e 0 e' x).
    + apply lc_exp_deg_exp. assumption.
    + apply lc_exp_deg_exp. assumption.
Qed.

(* ================================================================ *)
(* Item 15: substituting a fresh variable has no effect.             *)
(* ================================================================ *)

Lemma subst_exp_notin : forall e' x e,
    ~ AtomSetImpl.In x (termfv_exp e) ->
    subst_exp e' x e = e.
Proof.
  intros e' x e. revert e' x.
  induction e as [m|x0| |i|D e1 IHe1|D e1 IHe1|e1 IHe1 e2 IHe2
                 |e1 IHe1 e2 IHe2|e1 IHe1 D|D e1 IHe1|e1 IHe1 l|e1 IHe1|e1 IHe1 D];
    intros e' x H; simpl in H; simpl.
  - reflexivity.
  - destruct (eq_var x0 x) as [Heq|Hneq].
    + exfalso. exact ((notin_singleton_1 x0 x H) Heq).
    + reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite (IHe1 e' x H). reflexivity.
  - rewrite (IHe1 e' x H). reflexivity.
  - rewrite (IHe1 e' x).
    2: { intro Hc. apply H. apply AtomSetImpl.union_2. exact Hc. }
    rewrite (IHe2 e' x).
    2: { intro Hc. apply H. apply AtomSetImpl.union_3. exact Hc. }
    reflexivity.
  - rewrite (IHe1 e' x).
    2: { intro Hc. apply H. apply AtomSetImpl.union_2. exact Hc. }
    rewrite (IHe2 e' x).
    2: { intro Hc. apply H. apply AtomSetImpl.union_3. exact Hc. }
    reflexivity.
  - rewrite (IHe1 e' x H). reflexivity.
  - rewrite (IHe1 e' x H). reflexivity.
  - rewrite (IHe1 e' x H). reflexivity.
  - rewrite (IHe1 e' x H). reflexivity.
  - rewrite (IHe1 e' x H). reflexivity.
Qed.

Lemma typsubst_same : forall (A : typ) (X : typevar),
    typsubst_typ A X (t_tvar_f X) = A.
Proof.
  intros. simpl.
  destruct (eq_var X X) as [Heq|Hneq]; [reflexivity|exfalso; exact (Hneq eq_refl)].
Qed.

(* ================================================================ *)
(* Item 13: type substitution commutes with opening a type.          *)
(* ================================================================ *)

Lemma typsubst_open_typ : forall k X A B,
    lc_typ A ->
    ~ AtomSetImpl.In X (typefv_typ B) ->
    typsubst_typ A X (open_typ_wrt_typ_rec k (t_tvar_f X) B) =
    open_typ_wrt_typ_rec k A B.
Proof.
  intros k X A B. revert k X A.
  induction B as [m|X0| | | |D IHD E IHE|D IHD E IHE|D IHD E IHE|l D IHD];
    intros k X A HA H; simpl in H; simpl.
  - destruct (lt_eq_lt_dec m k) as [ [Hlt|Heq] | Hgt].
    + reflexivity.
    + subst m.
      destruct (lt_eq_lt_dec k k) as [ [Hlt|Heq] | Hgt].
      * exfalso; lia.
      * apply typsubst_same.
      * exfalso; lia.
    + reflexivity.
  - destruct (eq_var X0 X) as [Heq|Hneq].
    + exfalso. exact ((notin_singleton_1 X0 X H) Heq).
    + reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite (IHD k X A HA).
    2: { intro Hc. apply H. apply AtomSetImpl.union_2. exact Hc. }
    rewrite (IHE (S k) X A HA).
    2: { intro Hc. apply H. apply AtomSetImpl.union_3. exact Hc. }
    reflexivity.
  - rewrite (IHD k X A HA).
    2: { intro Hc. apply H. apply AtomSetImpl.union_2. exact Hc. }
    rewrite (IHE k X A HA).
    2: { intro Hc. apply H. apply AtomSetImpl.union_3. exact Hc. }
    reflexivity.
  - rewrite (IHD k X A HA).
    2: { intro Hc. apply H. apply AtomSetImpl.union_2. exact Hc. }
    rewrite (IHE k X A HA).
    2: { intro Hc. apply H. apply AtomSetImpl.union_3. exact Hc. }
    reflexivity.
  - rewrite (IHD k X A HA H). reflexivity.
Qed.

(* ================================================================ *)
(* Item 14: type substitution commutes with opening an expression.   *)
(* ================================================================ *)

Lemma typsubst_open_exp_typ : forall k X A e,
    lc_typ A ->
    ~ AtomSetImpl.In X (typefv_exp e) ->
    typsubst_exp A X (open_exp_wrt_typ_rec k (t_tvar_f X) e) =
    open_exp_wrt_typ_rec k A e.
Proof.
  intros k X A e. revert k X A.
  induction e as [m|x| |i|D e1 IHe1|D e1 IHe1|e1 IHe1 e2 IHe2
                 |e1 IHe1 e2 IHe2|e1 IHe1 D|D e1 IHe1|e1 IHe1 l|e1 IHe1|e1 IHe1 D];
    intros k X A HA H; simpl in H; simpl.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite (typsubst_open_typ k X A D HA).
    2: { intro Hc. apply H. apply AtomSetImpl.union_2. exact Hc. }
    rewrite (IHe1 k X A HA).
    2: { intro Hc. apply H. apply AtomSetImpl.union_3. exact Hc. }
    reflexivity.
  - rewrite (typsubst_open_typ k X A D HA).
    2: { intro Hc. apply H. apply AtomSetImpl.union_2. exact Hc. }
    rewrite (IHe1 k X A HA).
    2: { intro Hc. apply H. apply AtomSetImpl.union_3. exact Hc. }
    reflexivity.
  - rewrite (IHe1 k X A HA).
    2: { intro Hc. apply H. apply AtomSetImpl.union_2. exact Hc. }
    rewrite (IHe2 k X A HA).
    2: { intro Hc. apply H. apply AtomSetImpl.union_3. exact Hc. }
    reflexivity.
  - rewrite (IHe1 k X A HA).
    2: { intro Hc. apply H. apply AtomSetImpl.union_2. exact Hc. }
    rewrite (IHe2 k X A HA).
    2: { intro Hc. apply H. apply AtomSetImpl.union_3. exact Hc. }
    reflexivity.
  - rewrite (IHe1 k X A HA).
    2: { intro Hc. apply H. apply AtomSetImpl.union_2. exact Hc. }
    rewrite (typsubst_open_typ k X A D HA).
    2: { intro Hc. apply H. apply AtomSetImpl.union_3. exact Hc. }
    reflexivity.
  - rewrite (IHe1 k X A HA H). reflexivity.
  - rewrite (IHe1 k X A HA H). reflexivity.
  - rewrite (IHe1 (S k) X A HA H). reflexivity.
  - rewrite (IHe1 k X A HA).
    2: { intro Hc. apply H. apply AtomSetImpl.union_2. exact Hc. }
    rewrite (typsubst_open_typ k X A D HA).
    2: { intro Hc. apply H. apply AtomSetImpl.union_3. exact Hc. }
    reflexivity.
Qed.

Lemma subst_exp_same : forall (e' : exp) (x : termvar),
    subst_exp e' x (e_var_f x) = e'.
Proof.
  intros. simpl.
  destruct (eq_var x x) as [Heq|Hneq]; [reflexivity|exfalso; exact (Hneq eq_refl)].
Qed.

(* ================================================================ *)
(* Item 12: substituting for the variable introduced by opening a    *)
(* term abstraction reproduces the open term.                        *)
(* ================================================================ *)

Lemma subst_open_exp_exp_fresh : forall k x e' e,
    ~ AtomSetImpl.In x (termfv_exp e) ->
    subst_exp e' x (open_exp_wrt_exp_rec k (e_var_f x) e) =
    open_exp_wrt_exp_rec k e' e.
Proof.
  intros k x e' e. revert k x e'.
  induction e as [m|x0| |i|D e1 IHe1|D e1 IHe1|e1 IHe1 e2 IHe2
                 |e1 IHe1 e2 IHe2|e1 IHe1 D|D e1 IHe1|e1 IHe1 l|e1 IHe1|e1 IHe1 D];
    intros k x e' H; simpl in H; simpl.
  - destruct (lt_eq_lt_dec m k) as [ [Hlt|Heq] | Hgt].
    + reflexivity.
    + subst m. apply subst_exp_same.
    + reflexivity.
  - destruct (eq_var x0 x) as [Heq|Hneq].
    + exfalso. exact ((notin_singleton_1 x0 x H) Heq).
    + reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite (IHe1 (S k) x e' H). reflexivity.
  - rewrite (IHe1 (S k) x e' H). reflexivity.
  - rewrite (IHe1 k x e').
    2: { intro Hc. apply H. apply AtomSetImpl.union_2. exact Hc. }
    rewrite (IHe2 k x e').
    2: { intro Hc. apply H. apply AtomSetImpl.union_3. exact Hc. }
    reflexivity.
  - rewrite (IHe1 k x e').
    2: { intro Hc. apply H. apply AtomSetImpl.union_2. exact Hc. }
    rewrite (IHe2 k x e').
    2: { intro Hc. apply H. apply AtomSetImpl.union_3. exact Hc. }
    reflexivity.
  - rewrite (IHe1 k x e' H). reflexivity.
  - rewrite (IHe1 k x e' H). reflexivity.
  - rewrite (IHe1 k x e' H). reflexivity.
  - rewrite (IHe1 k x e' H). reflexivity.
  - rewrite (IHe1 k x e' H). reflexivity.
Qed.
End agentC.
Import agentC.

Module agentG.
Import ListNotations.

(* ================================================================== *)
(* Basic renaming helpers                                              *)
(* ================================================================== *)

Lemma ren_typ_eq_on_fv : forall A (f g : typevar -> typevar),
  (forall X, X \in [[A]] -> f X = g X) -> ren_typ f A = ren_typ g A.
Proof.
  induction A; intros f g H; simpl.
  - reflexivity.
  - apply f_equal. apply H. apply AtomSetImpl.singleton_2. reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - f_equal; [apply IHA1 | apply IHA2];
      intros X HX; apply H;
      first [apply AtomSetImpl.union_2; assumption | apply AtomSetImpl.union_3; assumption].
  - f_equal; [apply IHA1 | apply IHA2];
      intros X HX; apply H;
      first [apply AtomSetImpl.union_2; assumption | apply AtomSetImpl.union_3; assumption].
  - f_equal; [apply IHA1 | apply IHA2];
      intros X HX; apply H;
      first [apply AtomSetImpl.union_2; assumption | apply AtomSetImpl.union_3; assumption].
  - f_equal. apply IHA. intros X HX. apply H. assumption.
Qed.

Definition ren_ctx (f : typevar -> typevar) (D : tctx) : tctx :=
  map (fun p => (f (fst p), ren_typ f (snd p))) D.

Lemma ren_ctx_nil : forall f, ren_ctx f nil = nil.
Proof. reflexivity. Qed.

Lemma ren_ctx_cons : forall f X A D,
  ren_ctx f (cons (X, A) D) = cons (f X, ren_typ f A) (ren_ctx f D).
Proof. reflexivity. Qed.

Lemma ren_ctx_eq : forall D (f g : typevar -> typevar),
  (forall X, X \in dom D -> f X = g X) ->
  (forall X, X \in typefv_typ_range D -> f X = g X) ->
  ren_ctx f D = ren_ctx g D.
Proof.
  induction D as [|[Y B] D' IH]; intros f g Hdom Hfv; simpl.
  - reflexivity.
  - assert (HY : f Y = g Y).
    { apply Hdom. apply add_iff. left. reflexivity. }
    assert (HB : ren_typ f B = ren_typ g B).
    { apply ren_typ_eq_on_fv. intros X HX. apply Hfv.
      apply AtomSetImpl.union_2. assumption. }
    assert (HD : ren_ctx f D' = ren_ctx g D').
    { apply IH.
      - intros X HX. apply Hdom. apply add_iff. right. assumption.
      - intros X HX. apply Hfv. apply AtomSetImpl.union_3. assumption. }
    rewrite HY, HB, HD. reflexivity.
Qed.

Lemma binds_ren : forall (D : tctx) X A,
  binds X A D -> forall f, binds (f X) (ren_typ f A) (ren_ctx f D).
Proof.
  induction D as [|[Y B] D' IH]; intros X A Hb f; simpl in *.
  - contradiction.
  - destruct Hb as [Heq | Hin].
    + inversion Heq; subst. left. reflexivity.
    + right. apply IH. assumption.
Qed.

Lemma botLike_ren : forall A, botLike A -> forall f, botLike (ren_typ f A).
Proof.
  induction 1 as [| A B Hlc HB IH | A B Hlc HB IH]; intros f; simpl.
  - constructor.
  - constructor; [ apply lc_typ_ren; assumption | apply IH ].
  - constructor; [ apply lc_typ_ren; assumption | apply IH ].
Qed.

(* InA_In / freshness glue (copied from progress.v, where they are local) *)
Lemma InA_In : forall (x : atom) (l : list atom), InA eq x l -> In x l.
Proof. induction 1; [left; auto | right; auto]. Qed.

Lemma fresh_notin : forall (L : atoms), fresh (AtomSetImpl.elements L) \notin L.
Proof.
  intros L Hin.
  apply (Atom.fresh_not_in (AtomSetImpl.elements L)).
  apply InA_In. apply AtomSetImpl.elements_1. exact Hin.
Qed.

(* ================================================================== *)
(* Renaming well-formedness: TWell, TCWell, topLike                   *)
(* ================================================================== *)

Lemma TWell_ren_aux : forall n, forall (D : tctx) (A : typ),
  size_typ A <= n -> TWell D A -> forall f, TWell (ren_ctx f D) (ren_typ f A).
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D A Hle HT f.
  destruct HT as [D | D | D | D X A Hb | D l A HA | D A B HA HB
                  | D A B HA HB | L D A B HA HB].
  - simpl. apply TW_top.
  - simpl. apply TW_bot.
  - simpl. apply TW_int.
  - simpl. apply (TW_var (ren_ctx f D) (f X) (ren_typ f A)). apply binds_ren. assumption.
  - simpl. apply TW_rcd.
    apply (IH (size_typ A)). simpl in Hle. lia.
    exact (le_n (size_typ A)). assumption.
  - simpl. apply TW_arrow.
    + apply (IH (size_typ A)). simpl in Hle. pose proof (size_typ_pos B). lia.
      exact (le_n (size_typ A)). assumption.
    + apply (IH (size_typ B)). simpl in Hle. pose proof (size_typ_pos A). lia.
      exact (le_n (size_typ B)). assumption.
  - simpl. apply TW_and.
    + apply (IH (size_typ A)). simpl in Hle. pose proof (size_typ_pos B). lia.
      exact (le_n (size_typ A)). assumption.
    + apply (IH (size_typ B)). simpl in Hle. pose proof (size_typ_pos A). lia.
      exact (le_n (size_typ B)). assumption.
  - simpl. apply (TW_all L (ren_ctx f D) (ren_typ f A) (ren_typ f B)).
    + apply (IH (size_typ A)). simpl in Hle. pose proof (size_typ_pos B). lia.
      exact (le_n (size_typ A)). assumption.
    + intros X HX.
      pose (bad := L \u [[A]] \u [[B]] \u dom D \u typefv_typ_range D).
      pose (Y := fresh (AtomSetImpl.elements bad)).
      assert (HYbad : Y \notin bad) by (apply fresh_notin).
      assert (HYL : Y \notin L).
      { intro Hc. apply HYbad. unfold bad. apply AtomSetImpl.union_2. assumption. }
      assert (HYA : Y \notin [[A]]).
      { intro Hc. apply HYbad. unfold bad. apply AtomSetImpl.union_3.
        apply AtomSetImpl.union_2. assumption. }
      assert (HYB : Y \notin [[B]]).
      { intro Hc. apply HYbad. unfold bad. apply AtomSetImpl.union_3.
        apply AtomSetImpl.union_3. apply AtomSetImpl.union_2. assumption. }
      assert (HYdom : Y \notin dom D).
      { intro Hc. apply HYbad. unfold bad. apply AtomSetImpl.union_3.
        apply AtomSetImpl.union_3. apply AtomSetImpl.union_3.
        apply AtomSetImpl.union_2. assumption. }
      assert (HYrng : Y \notin typefv_typ_range D).
      { intro Hc. apply HYbad. unfold bad. apply AtomSetImpl.union_3.
        apply AtomSetImpl.union_3. apply AtomSetImpl.union_3.
        apply AtomSetImpl.union_3. assumption. }
      pose (f' := fun W => if eq_dec W Y then X else f W).
      assert (Hf'Y : f' Y = X).
      { unfold f'. destruct (eq_dec Y Y) as [Heq | Hne]; [reflexivity | exfalso; apply Hne; reflexivity]. }
      assert (Hf'A : ren_typ f' A = ren_typ f A).
      { apply ren_typ_eq_on_fv. intros Z HZ. unfold f'.
        destruct (eq_dec Z Y) as [Heq | Hne].
        - subst Z. exfalso. apply HYA. assumption.
        - reflexivity. }
      assert (Hf'B : ren_typ f' B = ren_typ f B).
      { apply ren_typ_eq_on_fv. intros Z HZ. unfold f'.
        destruct (eq_dec Z Y) as [Heq | Hne].
        - subst Z. exfalso. apply HYB. assumption.
        - reflexivity. }
      assert (Hf'D : ren_ctx f' D = ren_ctx f D).
      { apply ren_ctx_eq.
        - intros Z HZ. unfold f'. destruct (eq_dec Z Y) as [Heq | Hne].
          + subst Z. exfalso. apply HYdom. assumption.
          + reflexivity.
        - intros Z HZ. unfold f'. destruct (eq_dec Z Y) as [Heq | Hne].
          + subst Z. exfalso. apply HYrng. assumption.
          + reflexivity. }
      specialize (HB Y HYL).
      specialize (IH (size_typ (open_typ_wrt_typ B (t_tvar_f Y)))).
      assert (Hlt : size_typ (open_typ_wrt_typ B (t_tvar_f Y)) < n).
      { unfold open_typ_wrt_typ. rewrite size_typ_open_typ_tvar.
        simpl in Hle. pose proof (size_typ_pos A). lia. }
      specialize (IH Hlt (cons (Y, A) D)
                    (open_typ_wrt_typ B (t_tvar_f Y)) (le_n _) HB f').
      assert (Huniq : ren_ctx f' (cons (Y, A) D) = cons (X, ren_typ f A) (ren_ctx f D)).
      { rewrite ren_ctx_cons. rewrite Hf'A, Hf'D. rewrite Hf'Y. reflexivity. }
      rewrite Huniq in IH.
      rewrite ren_typ_open0 in IH. rewrite Hf'B, Hf'Y in IH.
      exact IH.
Qed.

Lemma TWell_ren : forall (D : tctx) A, TWell D A ->
  forall f, TWell (ren_ctx f D) (ren_typ f A).
Proof. intros. apply (TWell_ren_aux (size_typ A) D A (le_n _) H f). Qed.

Lemma TWell_nil_ren : forall A, TWell nil A ->
  forall f, TWell nil (ren_typ f A).
Proof. intros. apply (TWell_ren nil A H f). Qed.

Lemma TCWell_ren : forall D, TCWell D ->
  forall f, uniq (ren_ctx f D) -> TCWell (ren_ctx f D).
Proof.
  induction 1 as [| D X A HTC IH HTW Huniq]; intros f Huniq'.
  - apply TCW_empty.
  - rewrite ren_ctx_cons.
    apply TCW_cons.
    + apply IH. rewrite ren_ctx_cons in Huniq'. apply uniq_cons_1 with (x:=f X) (a:=ren_typ f A). assumption.
    + apply TWell_ren. assumption.
    + exact Huniq'.
Qed.

Lemma topLike_ren_aux : forall n, forall (D : tctx) (A : typ),
  size_typ A <= n -> topLike D A ->
  forall f, uniq (ren_ctx f D) -> topLike (ren_ctx f D) (ren_typ f A).
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D A Hle HT f Huniq.
  destruct HT as [D HTC | D A B HA HB | D A B HTW Htop | D l B HB
                  | L D A B HB | D X A HTC Hb Hbot].
  - simpl. apply TL_top. apply TCWell_ren; assumption.
  - simpl. apply TL_and.
    + apply (IH (size_typ A)). simpl in Hle. pose proof (size_typ_pos B). lia.
      exact (le_n (size_typ A)). assumption. assumption.
    + apply (IH (size_typ B)). simpl in Hle. pose proof (size_typ_pos A). lia.
      exact (le_n (size_typ B)). assumption. assumption.
  - simpl. apply TL_arrow.
    + apply TWell_ren. assumption.
    + apply (IH (size_typ B)). simpl in Hle. pose proof (size_typ_pos A). lia.
      exact (le_n (size_typ B)). assumption. assumption.
  - simpl. apply TL_rcd.
    apply (IH (size_typ B)). simpl in Hle. lia.
    exact (le_n (size_typ B)). assumption. assumption.
  - simpl. apply (TL_all (L \u dom (ren_ctx f D)) (ren_ctx f D) (ren_typ f A) (ren_typ f B)).
    intros X HX.
    destruct (notin_union X L (dom (ren_ctx f D)) HX) as [HXL HXdom].
    pose (bad := L \u [[A]] \u [[B]] \u dom D \u typefv_typ_range D).
    pose (Y := fresh (AtomSetImpl.elements bad)).
    assert (HYbad : Y \notin bad) by (apply fresh_notin).
    assert (HYL : Y \notin L).
    { intro Hc. apply HYbad. unfold bad. apply AtomSetImpl.union_2. assumption. }
    assert (HYA : Y \notin [[A]]).
    { intro Hc. apply HYbad. unfold bad. apply AtomSetImpl.union_3.
      apply AtomSetImpl.union_2. assumption. }
    assert (HYB : Y \notin [[B]]).
    { intro Hc. apply HYbad. unfold bad. apply AtomSetImpl.union_3.
      apply AtomSetImpl.union_3. apply AtomSetImpl.union_2. assumption. }
    assert (HYdom : Y \notin dom D).
    { intro Hc. apply HYbad. unfold bad. apply AtomSetImpl.union_3.
      apply AtomSetImpl.union_3. apply AtomSetImpl.union_3.
      apply AtomSetImpl.union_2. assumption. }
    assert (HYrng : Y \notin typefv_typ_range D).
    { intro Hc. apply HYbad. unfold bad. apply AtomSetImpl.union_3.
      apply AtomSetImpl.union_3. apply AtomSetImpl.union_3.
      apply AtomSetImpl.union_3. assumption. }
    pose (f' := fun W => if eq_dec W Y then X else f W).
    assert (Hf'Y : f' Y = X).
    { unfold f'. destruct (eq_dec Y Y) as [Heq | Hne]; [reflexivity | exfalso; apply Hne; reflexivity]. }
    assert (Hf'A : ren_typ f' A = ren_typ f A).
    { apply ren_typ_eq_on_fv. intros Z HZ. unfold f'.
      destruct (eq_dec Z Y) as [Heq | Hne].
      - subst Z. exfalso. apply HYA. assumption.
      - reflexivity. }
    assert (Hf'B : ren_typ f' B = ren_typ f B).
    { apply ren_typ_eq_on_fv. intros Z HZ. unfold f'.
      destruct (eq_dec Z Y) as [Heq | Hne].
      - subst Z. exfalso. apply HYB. assumption.
      - reflexivity. }
    assert (Hf'D : ren_ctx f' D = ren_ctx f D).
    { apply ren_ctx_eq.
      - intros Z HZ. unfold f'. destruct (eq_dec Z Y) as [Heq | Hne].
        + subst Z. exfalso. apply HYdom. assumption.
        + reflexivity.
      - intros Z HZ. unfold f'. destruct (eq_dec Z Y) as [Heq | Hne].
        + subst Z. exfalso. apply HYrng. assumption.
        + reflexivity. }
    assert (Huniq' : uniq (ren_ctx f' (cons (Y, A) D))).
    { rewrite ren_ctx_cons. rewrite Hf'A, Hf'D, Hf'Y.
      apply uniq_cons with (x:=X) (a:=ren_typ f A) (E:=ren_ctx f D).
      - assumption.
      - exact HXdom. }
    specialize (HB Y HYL).
    assert (Hlt : size_typ (open_typ_wrt_typ B (t_tvar_f Y)) < n).
    { unfold open_typ_wrt_typ. rewrite size_typ_open_typ_tvar.
      simpl in Hle. pose proof (size_typ_pos A). lia. }
    pose proof (IH (size_typ (open_typ_wrt_typ B (t_tvar_f Y))) Hlt
                  (cons (Y, A) D) (open_typ_wrt_typ B (t_tvar_f Y))
                  (le_n _) HB f' Huniq') as Hres.
    rewrite ren_ctx_cons in Hres. rewrite Hf'A, Hf'D, Hf'Y in Hres.
    rewrite ren_typ_open0 in Hres. rewrite Hf'B, Hf'Y in Hres.
    exact Hres.
  - simpl. apply (TL_var (ren_ctx f D) (f X) (ren_typ f A)).
    + apply TCWell_ren; assumption.
    + apply binds_ren. assumption.
    + apply botLike_ren. assumption.
Qed.

Lemma topLike_ren : forall D A, topLike D A ->
  forall f, uniq (ren_ctx f D) -> topLike (ren_ctx f D) (ren_typ f A).
Proof. intros. apply (topLike_ren_aux (size_typ A) D A (le_n _) H f H0). Qed.

Lemma topLike_nil_ren : forall A, topLike nil A ->
  forall f, topLike nil (ren_typ f A).
Proof.
  intros A H f.
  apply (topLike_ren nil A H f).
  simpl. apply uniq_nil.
Qed.

(* ================================================================== *)
(* spl and ord are stable under renaming                              *)
(* ================================================================== *)

Lemma spl_ren_aux : forall n, forall A B C : typ,
  size_typ A <= n -> spl A B C ->
  forall f, spl (ren_typ f A) (ren_typ f B) (ren_typ f C).
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros A B C Hle Hs f.
  destruct Hs as [A0 B0 C1 C2 Hlc Hsub | L A0 B0 C1 C2 Hlc Hsub
                  | l B0 C1 C2 Hsub | A0 B0 Hlc1 Hlc2].
  - simpl. apply Sp_arrow.
    + apply lc_typ_ren. assumption.
    + apply (IH (size_typ B0)).
      * simpl in Hle. pose proof (size_typ_pos A0). lia.
      * exact (le_n (size_typ B0)).
      * assumption.
  - simpl. apply (Sp_all L (ren_typ f A0) (ren_typ f B0)
                          (ren_typ f C1) (ren_typ f C2)).
    + apply lc_typ_ren. assumption.
    + intros X HX.
      pose (bad := L \u [[B0]] \u [[C1]] \u [[C2]]).
      pose (Y := fresh (AtomSetImpl.elements bad)).
      assert (HYbad : Y \notin bad) by (apply fresh_notin).
      assert (HYL : Y \notin L).
      { intro Hc. apply HYbad. unfold bad. apply AtomSetImpl.union_2. assumption. }
      assert (HYB : Y \notin [[B0]]).
      { intro Hc. apply HYbad. unfold bad. apply AtomSetImpl.union_3.
        apply AtomSetImpl.union_2. assumption. }
      assert (HYC1 : Y \notin [[C1]]).
      { intro Hc. apply HYbad. unfold bad. apply AtomSetImpl.union_3.
        apply AtomSetImpl.union_3. apply AtomSetImpl.union_2. assumption. }
      assert (HYC2 : Y \notin [[C2]]).
      { intro Hc. apply HYbad. unfold bad. apply AtomSetImpl.union_3.
        apply AtomSetImpl.union_3. apply AtomSetImpl.union_3. assumption. }
      pose (f' := fun W => if eq_dec W Y then X else f W).
      assert (Hf'Y : f' Y = X).
      { unfold f'. destruct (eq_dec Y Y) as [Heq | Hne]; [reflexivity | exfalso; apply Hne; reflexivity]. }
      assert (Hf'B : ren_typ f' B0 = ren_typ f B0).
      { apply ren_typ_eq_on_fv. intros Z HZ. unfold f'.
        destruct (eq_dec Z Y) as [Heq | Hne].
        - subst Z. exfalso. apply HYB. assumption.
        - reflexivity. }
      assert (Hf'C1 : ren_typ f' C1 = ren_typ f C1).
      { apply ren_typ_eq_on_fv. intros Z HZ. unfold f'.
        destruct (eq_dec Z Y) as [Heq | Hne].
        - subst Z. exfalso. apply HYC1. assumption.
        - reflexivity. }
      assert (Hf'C2 : ren_typ f' C2 = ren_typ f C2).
      { apply ren_typ_eq_on_fv. intros Z HZ. unfold f'.
        destruct (eq_dec Z Y) as [Heq | Hne].
        - subst Z. exfalso. apply HYC2. assumption.
        - reflexivity. }
      assert (Hlt : size_typ (B0 -^ Y) < n).
      { unfold open_typ_wrt_typ. rewrite size_typ_open_typ_tvar.
        simpl in Hle. pose proof (size_typ_pos A0). lia. }
      pose proof (IH (size_typ (B0 -^ Y)) Hlt (B0 -^ Y) (C1 -^ Y) (C2 -^ Y)
                    (le_n _) (Hsub Y HYL) f') as Hres.
      rewrite !ren_typ_open0 in Hres.
      rewrite Hf'B, Hf'C1, Hf'C2, Hf'Y in Hres.
      exact Hres.
  - simpl. apply Sp_rcd.
    apply (IH (size_typ B0)).
    + simpl in Hle. lia.
    + exact (le_n (size_typ B0)).
    + assumption.
  - simpl. apply Sp_and.
    + apply lc_typ_ren. assumption.
    + apply lc_typ_ren. assumption.
Qed.

Lemma spl_ren : forall A B C, spl A B C ->
  forall f, spl (ren_typ f A) (ren_typ f B) (ren_typ f C).
Proof. intros. apply (spl_ren_aux (size_typ A) A B C (le_n _) H f). Qed.

Lemma ord_ren_aux : forall n, forall A : typ,
  size_typ A <= n -> ord A -> forall f, ord (ren_typ f A).
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros A Hle Ho f.
  destruct Ho as [X | | | | A0 B0 Hlc HoB | L A0 B0 Hlc HB | l B0 HoB].
  - simpl. apply O_var.
  - simpl. apply O_top.
  - simpl. apply O_bot.
  - simpl. apply O_int.
  - simpl. apply O_arrow.
    + apply lc_typ_ren. assumption.
    + apply (IH (size_typ B0)).
      * simpl in Hle. pose proof (size_typ_pos A0). lia.
      * exact (le_n (size_typ B0)).
      * assumption.
  - simpl. apply (O_all L (ren_typ f A0) (ren_typ f B0)).
    + apply lc_typ_ren. assumption.
    + intros X HX.
      pose (bad := L \u [[B0]]).
      pose (Y := fresh (AtomSetImpl.elements bad)).
      assert (HYbad : Y \notin bad) by (apply fresh_notin).
      assert (HYL : Y \notin L).
      { intro Hc. apply HYbad. unfold bad. apply AtomSetImpl.union_2. assumption. }
      assert (HYB : Y \notin [[B0]]).
      { intro Hc. apply HYbad. unfold bad. apply AtomSetImpl.union_3. assumption. }
      pose (f' := fun W => if eq_dec W Y then X else f W).
      assert (Hf'Y : f' Y = X).
      { unfold f'. destruct (eq_dec Y Y) as [Heq | Hne]; [reflexivity | exfalso; apply Hne; reflexivity]. }
      assert (Hf'B : ren_typ f' B0 = ren_typ f B0).
      { apply ren_typ_eq_on_fv. intros Z HZ. unfold f'.
        destruct (eq_dec Z Y) as [Heq | Hne].
        - subst Z. exfalso. apply HYB. assumption.
        - reflexivity. }
      assert (Hlt : size_typ (B0 -^ Y) < n).
      { unfold open_typ_wrt_typ. rewrite size_typ_open_typ_tvar.
        simpl in Hle. pose proof (size_typ_pos A0). lia. }
      pose proof (IH (size_typ (B0 -^ Y)) Hlt (B0 -^ Y)
                    (le_n _) (HB Y HYL) f') as Hres.
      rewrite ren_typ_open0 in Hres.
      rewrite Hf'B, Hf'Y in Hres.
      exact Hres.
  - simpl. apply O_rcd.
    apply (IH (size_typ B0)).
    + simpl in Hle. lia.
    + exact (le_n (size_typ B0)).
    + assumption.
Qed.

Lemma ord_ren : forall A, ord A ->
  forall f, ord (ren_typ f A).
Proof. intros. apply (ord_ren_aux (size_typ A) A (le_n _) H f). Qed.

(* ------------------------------------------------------------------ *)
(* Opening commutes with the tailored renaming X -> Y                 *)
(* ------------------------------------------------------------------ *)

Lemma ren_typ_open_rename : forall (B : typ) (X Y : typevar),
  X \notin [[B]] ->
  ren_typ (rename_var X Y) (B -^ X) = (B -^ Y).
Proof.
  intros B X Y HX.
  rewrite ren_typ_open0.
  rewrite rename_var_eq.
  assert (Hid : ren_typ (rename_var X Y) B = B).
  { apply ren_typ_id. intros Z HZ.
    apply rename_var_neq. intro Heq. subst Z. apply HX. assumption. }
  rewrite Hid. reflexivity.
Qed.

Lemma spl_open_rename : forall (B C1 C2 : typ) (X Y : typevar),
  ~ AtomSetImpl.In X (typefv_typ B) ->
  spl (open_typ_wrt_typ B (t_tvar_f X)) C1 C2 ->
  exists C1' C2',
    spl (open_typ_wrt_typ B (t_tvar_f Y)) C1' C2'.
Proof.
  intros B C1 C2 X Y HX Hspl.
  exists (ren_typ (rename_var X Y) C1),
         (ren_typ (rename_var X Y) C2).
  pose proof (spl_ren (B -^ X) C1 C2 Hspl (rename_var X Y)) as Hr.
  rewrite ren_typ_open_rename in Hr; [exact Hr | exact HX].
Qed.

Lemma ord_open_rename : forall (B : typ) (X Y : typevar),
  ~ AtomSetImpl.In X (typefv_typ B) ->
  ord (open_typ_wrt_typ B (t_tvar_f X)) ->
  ord (open_typ_wrt_typ B (t_tvar_f Y)).
Proof.
  intros B X Y HX Ho.
  pose proof (ord_ren (B -^ X) Ho (rename_var X Y)) as Hr.
  rewrite ren_typ_open_rename in Hr; [exact Hr | exact HX].
Qed.

(* ================================================================== *)
(* Closing and reopening a type                                       *)
(* ================================================================== *)

Lemma open_rec_tvar_b_lt : forall k (Y : typevar) n, n < k ->
  open_typ_wrt_typ_rec k (t_tvar_f Y) (t_tvar_b n) = t_tvar_b n.
Proof.
  intros k Y n H. unfold open_typ_wrt_typ_rec.
  destruct (lt_eq_lt_dec n k) as [Hlt' | Hgt].
  - destruct Hlt' as [Hlt'' | Heq]; [reflexivity | exfalso; lia].
  - exfalso; lia.
Qed.

Lemma open_rec_tvar_b_gt : forall k (Y : typevar) n, k < n ->
  open_typ_wrt_typ_rec k (t_tvar_f Y) (t_tvar_b n) = t_tvar_b (n - 1).
Proof.
  intros k Y n H. unfold open_typ_wrt_typ_rec.
  destruct (lt_eq_lt_dec n k) as [Hlt' | Hgt].
  - destruct Hlt' as [Hlt'' | Heq]; exfalso; lia.
  - reflexivity.
Qed.

Lemma open_rec_tvar_b_eq : forall k (Y : typevar),
  open_typ_wrt_typ_rec k (t_tvar_f Y) (t_tvar_b k) = t_tvar_f Y.
Proof.
  intros k Y. unfold open_typ_wrt_typ_rec.
  destruct (lt_eq_lt_dec k k) as [Hlt' | Hgt].
  - destruct Hlt' as [Hlt'' | Heq]; [exfalso; lia | reflexivity].
  - exfalso; lia.
Qed.

Lemma open_close_typ_rec : forall k (X Y : typevar) (A : typ),
  open_typ_wrt_typ_rec k (t_tvar_f Y) (close_typ_wrt_typ_rec k X A) =
  ren_typ (rename_var X Y) A.
Proof.
  intros k X Y A. revert k. induction A as [nb | Z | | | | A1 IHA1 A2 IHA2 | A1 IHA1 A2 IHA2 | A1 IHA1 A2 IHA2 | l A1 IHA]; intros k.
  - unfold close_typ_wrt_typ_rec.
    destruct (lt_ge_dec nb k) as [Hlt | Hge].
    + change (open_typ_wrt_typ_rec k (t_tvar_f Y) (t_tvar_b nb) = t_tvar_b nb).
      apply open_rec_tvar_b_lt. exact Hlt.
    + change (open_typ_wrt_typ_rec k (t_tvar_f Y) (t_tvar_b (S nb)) = t_tvar_b nb).
      rewrite open_rec_tvar_b_gt; [| lia].
      replace (S nb - 1) with nb by lia. reflexivity.
  - unfold close_typ_wrt_typ_rec.
    destruct (eq_dec X Z) as [Heq | Hne].
    + subst Z. rewrite open_rec_tvar_b_eq.
      change (t_tvar_f Y = t_tvar_f (rename_var X Y X)).
      rewrite rename_var_eq. reflexivity.
    + simpl. rewrite rename_var_neq;
        [reflexivity | intro Hc; apply Hne; symmetry; assumption].
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - simpl. f_equal. apply IHA1. apply IHA2.
  - simpl. f_equal. apply IHA1. apply IHA2.
  - simpl. f_equal. apply IHA1. apply IHA2.
  - simpl. f_equal. apply IHA.
Qed.

Lemma open_close_typ : forall (X Y : typevar) (A : typ),
  open_typ_wrt_typ (close_typ_wrt_typ X A) (t_tvar_f Y) =
  ren_typ (rename_var X Y) A.
Proof.
  intros X Y A. unfold open_typ_wrt_typ, close_typ_wrt_typ.
  apply open_close_typ_rec.
Qed.

(* ================================================================== *)
(* A non-ordering top-like type splits                               *)
(* ================================================================== *)

Lemma topLike_not_ord_spl : forall (D : tctx) (A : typ),
  topLike D A -> ~ ord A -> exists B C, spl A B C.
Proof.
  intros D A H.
  induction H as [D HTC | D A0 B0 HA IHA HB IHB | D A0 B0 HTW Htop IHtop
                | D l B0 HB IHB | L D A0 B0 HB IHB | D X A0 HTC Hb Hbot].
  - intros Hno. exfalso. apply Hno. apply O_top.
  - intros Hno. exists A0, B0. apply Sp_and.
    + apply topLike_lc_typ with (D:=D). exact HA.
    + apply topLike_lc_typ with (D:=D). exact HB.
  - intros Hno.
    assert (HnB : ~ ord B0).
    { intro Ho. apply Hno. apply O_arrow.
      - apply TWell_lc_typ with (D:=D). exact HTW.
      - exact Ho. }
    destruct (IHtop HnB) as [C1 Hrest]. destruct Hrest as [C2 Hs].
    exists (t_arrow A0 C1), (t_arrow A0 C2). apply Sp_arrow.
    + apply TWell_lc_typ with (D:=D). exact HTW.
    + exact Hs.
  - intros Hno.
    assert (HnB : ~ ord B0).
    { intro Ho. apply Hno. apply O_rcd. exact Ho. }
    destruct (IHB HnB) as [C1 Hrest]. destruct Hrest as [C2 Hs].
    exists (t_rcd l C1), (t_rcd l C2). apply Sp_rcd. exact Hs.
  - intros Hno.
    assert (HlcA : lc_typ A0).
    { pose (Xf := fresh (AtomSetImpl.elements L)).
      assert (HXfL : Xf \notin L) by (apply fresh_notin).
      exact (TWell_lc_typ D A0
        (TCWell_cons_TWell D Xf A0
          (topLike_TCWell ((Xf, A0) :: D) (B0 -^ Xf) (HB Xf HXfL)))). }
    pose (bad := L \u [[B0]]).
    pose (X0 := fresh (AtomSetImpl.elements bad)).
    assert (HX0bad : X0 \notin bad) by (apply fresh_notin).
    assert (HX0L : X0 \notin L).
    { intro Hc. apply HX0bad. unfold bad. apply AtomSetImpl.union_2. assumption. }
    assert (HX0fv : X0 \notin [[B0]]).
    { intro Hc. apply HX0bad. unfold bad. apply AtomSetImpl.union_3. assumption. }
    assert (HnoX0 : ~ ord (B0 -^ X0)).
    { intro Ho. apply Hno. apply (O_all L A0 B0 HlcA).
      intros Y HYL. apply (ord_open_rename B0 X0 Y HX0fv Ho). }
    destruct (IHB X0 HX0L HnoX0) as [C1 Hrest]. destruct Hrest as [C2 Hs].
    exists (t_forall A0 (close_typ_wrt_typ X0 C1)),
           (t_forall A0 (close_typ_wrt_typ X0 C2)).
    apply (Sp_all empty A0 B0 (close_typ_wrt_typ X0 C1)
                   (close_typ_wrt_typ X0 C2) HlcA).
    intros Y HY.
    pose proof (spl_ren (B0 -^ X0) C1 C2 Hs (rename_var X0 Y)) as Hr.
    rewrite ren_typ_open_rename in Hr; [| exact HX0fv].
    rewrite (open_close_typ X0 Y C1).
    rewrite (open_close_typ X0 Y C2).
    exact Hr.
  - intros Hno. exfalso. apply Hno. apply O_var.
Qed.

(* ================================================================== *)
(* Decidability of ord under well-formedness                          *)
(* ================================================================== *)

Lemma ord_dec_TWell_aux : forall n, forall (D : tctx) (A : typ),
  size_typ A <= n -> TWell D A -> ord A \/ ~ ord A.
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D A Hle HT.
  destruct A as [i | X | | | | A1 A2 | A1 A2 | A1 A2 | l A1].
  - right. intro Ho. inversion Ho.
  - left. apply O_var.
  - left. apply O_int.
  - left. apply O_top.
  - left. apply O_bot.
  - pose proof (TWell_all_body D A1 A2 HT) as [L HB].
    pose proof (TWell_all_inv D A1 A2 HT) as HTA1.
    assert (HlcA : lc_typ A1) by (apply TWell_lc_typ with (D:=D); exact HTA1).
    pose (bad := L \u [[A2]]).
    pose (X0 := fresh (AtomSetImpl.elements bad)).
    assert (HX0bad : X0 \notin bad) by (apply fresh_notin).
    assert (HX0L : X0 \notin L).
    { intro Hc. apply HX0bad. unfold bad. apply AtomSetImpl.union_2. assumption. }
    assert (HX0fv : X0 \notin [[A2]]).
    { intro Hc. apply HX0bad. unfold bad. apply AtomSetImpl.union_3. assumption. }
    assert (Hlt : size_typ A2 < n).
    { simpl in Hle. pose proof (size_typ_pos A1). lia. }
    assert (Hsize : size_typ (A2 -^ X0) <= size_typ A2).
    { unfold open_typ_wrt_typ. rewrite size_typ_open_typ_tvar. apply le_n. }
    destruct (IH (size_typ A2) Hlt (cons (X0, A1) D) (A2 -^ X0)
                  Hsize (HB X0 HX0L)) as [HoB | HnoB].
    + left. apply (O_all L A1 A2 HlcA).
      intros Y HYL. apply (ord_open_rename A2 X0 Y HX0fv HoB).
    + right. intro HoAll. apply HnoB.
      exact (proj2 (ord_all_inv A1 A2 HoAll) X0).
  - destruct (TWell_arrow_inv D A1 A2 HT) as [HT1 HT2].
    assert (Hlt : size_typ A2 < n).
    { simpl in Hle. pose proof (size_typ_pos A1). lia. }
    destruct (IH (size_typ A2) Hlt D A2 (le_n _) HT2) as [HoB | HnoB].
    + left. apply O_arrow.
      * apply TWell_lc_typ with (D:=D). exact HT1.
      * exact HoB.
    + right. intro Ho. apply HnoB.
      exact (proj2 (ord_arrow_inv A1 A2 Ho)).
  - right. intro Ho. inversion Ho.
  - pose proof (TWell_rcd_inv D l A1 HT) as HT1.
    assert (Hlt : size_typ A1 < n) by (simpl in Hle; lia).
    destruct (IH (size_typ A1) Hlt D A1 (le_n _) HT1) as [Ho | Hno].
    + left. apply O_rcd. exact Ho.
    + right. intro Ho. apply Hno. exact (ord_rcd_inv l A1 Ho).
Qed.

Lemma ord_dec_TWell : forall (D : tctx) (A : typ),
  TWell D A -> ord A \/ ~ ord A.
Proof.
  intros. apply (ord_dec_TWell_aux (size_typ A) D A (le_n _) H).
Qed.

(* ================================================================== *)
(* Coverage: every well-formed type is ord, top-like, or splitting    *)
(* ================================================================== *)

Lemma coverage_gen_aux : forall n, forall (D : tctx) (A : typ),
  size_typ A <= n -> TCWell D -> TWell D A ->
  ord A \/ topLike D A \/ (exists B C, spl A B C).
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D A Hle HTC HT.
  destruct A as [i | X | | | | A1 A2 | A1 A2 | A1 A2 | l A1].
  - inversion HT.
  - left. apply O_var.
  - left. apply O_int.
  - left. apply O_top.
  - left. apply O_bot.
  - (* forall *)
    pose proof (TWell_all_body D A1 A2 HT) as [L HB].
    pose proof (TWell_all_inv D A1 A2 HT) as HTA1.
    assert (HlcA : lc_typ A1).
    { apply TWell_lc_typ with (D:=D). exact HTA1. }
    destruct (ord_dec_TWell D (t_forall A1 A2) HT) as [Hord | Hno].
    + left. exact Hord.
    + right. right.
      pose (bad := L \u [[A2]] \u dom D).
      pose (X := fresh (AtomSetImpl.elements bad)).
      assert (HXbad : X \notin bad) by (apply fresh_notin).
      assert (HXL : X \notin L).
      { intro Hc. apply HXbad. unfold bad. apply AtomSetImpl.union_2. assumption. }
      assert (HXfv : X \notin [[A2]]).
      { intro Hc. apply HXbad. unfold bad. apply AtomSetImpl.union_3.
        apply AtomSetImpl.union_2. assumption. }
      assert (HXdom : X \notin dom D).
      { intro Hc. apply HXbad. unfold bad. apply AtomSetImpl.union_3.
        apply AtomSetImpl.union_3. assumption. }
      assert (HTC' : TCWell (cons (X, A1) D)).
      { apply TCW_cons.
        - exact HTC.
        - exact HTA1.
        - apply uniq_cons.
          + apply TCWell_uniq. exact HTC.
          + exact HXdom. }
      assert (Hlt : size_typ A2 < n).
      { simpl in Hle. pose proof (size_typ_pos A1). lia. }
      assert (Hsize : size_typ (A2 -^ X) <= size_typ A2).
      { unfold open_typ_wrt_typ. rewrite size_typ_open_typ_tvar. apply le_n. }
      pose proof (IH (size_typ A2) Hlt (cons (X, A1) D) (A2 -^ X)
                    Hsize HTC' (HB X HXL)) as Hcov.
      destruct Hcov as [HordB | Hrest].
      * exfalso. apply Hno. apply (O_all L A1 A2 HlcA).
        intros Y HYL. apply (ord_open_rename A2 X Y HXfv). exact HordB.
      * destruct Hrest as [HtopB | Hex].
        -- assert (HnB : ~ ord (A2 -^ X)).
           { intro Ho. apply Hno. apply (O_all L A1 A2 HlcA).
             intros Y HYL. apply (ord_open_rename A2 X Y HXfv). exact Ho. }
           destruct (topLike_not_ord_spl (cons (X, A1) D) (A2 -^ X)
                       HtopB HnB) as [C1 Hrest2].
           destruct Hrest2 as [C2 Hs].
           assert (HsplAll : spl (t_forall A1 A2)
                    (t_forall A1 (close_typ_wrt_typ X C1))
                    (t_forall A1 (close_typ_wrt_typ X C2))).
           { apply (Sp_all empty A1 A2 (close_typ_wrt_typ X C1)
                          (close_typ_wrt_typ X C2) HlcA).
             intros Y HY.
             pose proof (spl_ren (A2 -^ X) C1 C2 Hs (rename_var X Y)) as Hr.
             rewrite ren_typ_open_rename in Hr; [| exact HXfv].
             rewrite (open_close_typ X Y C1).
             rewrite (open_close_typ X Y C2).
             exact Hr. }
           exists (t_forall A1 (close_typ_wrt_typ X C1)),
                  (t_forall A1 (close_typ_wrt_typ X C2)).
           exact HsplAll.
        -- destruct Hex as [C1 Hrest2]. destruct Hrest2 as [C2 Hs].
           assert (HsplAll : spl (t_forall A1 A2)
                    (t_forall A1 (close_typ_wrt_typ X C1))
                    (t_forall A1 (close_typ_wrt_typ X C2))).
           { apply (Sp_all empty A1 A2 (close_typ_wrt_typ X C1)
                          (close_typ_wrt_typ X C2) HlcA).
             intros Y HY.
             pose proof (spl_ren (A2 -^ X) C1 C2 Hs (rename_var X Y)) as Hr.
             rewrite ren_typ_open_rename in Hr; [| exact HXfv].
             rewrite (open_close_typ X Y C1).
             rewrite (open_close_typ X Y C2).
             exact Hr. }
           exists (t_forall A1 (close_typ_wrt_typ X C1)),
                  (t_forall A1 (close_typ_wrt_typ X C2)).
           exact HsplAll.
  - (* arrow *)
    destruct (TWell_arrow_inv D A1 A2 HT) as [HT1 HT2].
    assert (Hlt : size_typ A2 < n).
    { simpl in Hle. pose proof (size_typ_pos A1). lia. }
    destruct (IH (size_typ A2) Hlt D A2 (le_n _) HTC HT2) as [Ho | Hrest].
    + left. apply O_arrow.
      * apply TWell_lc_typ with (D:=D). exact HT1.
      * exact Ho.
    + destruct Hrest as [Htop | Hex].
      * right. left. apply TL_arrow; assumption.
      * right. right. destruct Hex as [C1 Hrest2]. destruct Hrest2 as [C2 Hs].
        exists (t_arrow A1 C1), (t_arrow A1 C2). apply Sp_arrow.
        -- apply TWell_lc_typ with (D:=D). exact HT1.
        -- exact Hs.
  - (* and *)
    destruct (TWell_and_inv D A1 A2 HT) as [HT1 HT2].
    right. right. exists A1, A2. apply Sp_and.
    + apply TWell_lc_typ with (D:=D). exact HT1.
    + apply TWell_lc_typ with (D:=D). exact HT2.
  - (* rcd *)
    pose proof (TWell_rcd_inv D l A1 HT) as HT1.
    assert (Hlt : size_typ A1 < n).
    { simpl in Hle. lia. }
    destruct (IH (size_typ A1) Hlt D A1 (le_n _) HTC HT1) as [Ho | Hrest].
    + left. apply O_rcd. exact Ho.
    + destruct Hrest as [Htop | Hex].
      * right. left. apply TL_rcd. exact Htop.
      * right. right. destruct Hex as [C1 Hrest2]. destruct Hrest2 as [C2 Hs].
        exists (t_rcd l C1), (t_rcd l C2). apply Sp_rcd. exact Hs.
Qed.

Lemma TWell_coverage : forall A, TWell nil A ->
  ord A \/ (exists B C, spl A B C).
Proof.
  intros A HT.
  destruct (coverage_gen_aux (size_typ A) nil A (le_n _) TCW_empty HT)
    as [Ho | Hrest].
  - left. exact Ho.
  - destruct Hrest as [Htop | Hspl].
    + destruct (ord_dec_TWell nil A HT) as [Ho | Hno].
      * left. exact Ho.
      * right. exact (topLike_not_ord_spl nil A Htop Hno).
    + right. exact Hspl.
Qed.

Lemma spl_TWell_nil : forall A B C,
  TWell nil A -> spl A B C -> TWell nil B /\ TWell nil C.
Proof. intros A B C HA Hs. exact (spl_TWell nil A B C HA Hs). Qed.
End agentG.
Import agentG.

Module agentD.

Import ListNotations.

(* ============================================================ *)
(* Basic well-formedness facts for TWell                       *)
(* ============================================================ *)

Lemma TWell_arrow_inv : forall D A B,
    TWell D (t_arrow A B) -> TWell D A /\ TWell D B.
Proof.
  intros D A B H. inversion H; subst; auto.
Qed.

Lemma TWell_and_inv : forall D A B,
    TWell D (t_and A B) -> TWell D A /\ TWell D B.
Proof.
  intros D A B H. inversion H; subst; auto.
Qed.

Lemma TWell_rcd_inv : forall D l A,
    TWell D (t_rcd l A) -> TWell D A.
Proof.
  intros D l A H. inversion H; subst; auto.
Qed.

Lemma TWell_forall_inv : forall D A B,
    TWell D (t_forall A B) ->
    exists L, TWell D A /\
      (forall X, X \notin L ->
         TWell (cons (X, A) D) (open_typ_wrt_typ B (t_tvar_f X))).
Proof.
  intros D A B H. inversion H; subst.
  eexists. split; eassumption.
Qed.

(* TWell only depends on the domain of the type context. *)

Lemma TWell_dom : forall D D' A,
    TWell D A -> dom D [=] dom D' -> TWell D' A.
Proof.
  intros D D' A H. revert D'.
  induction H as
    [D
    |D
    |D
    |D X A Hb
    |D l A HT IHr
    |D A B H1 IH1 H2 IH2
    |D A B H1 IH1 H2 IH2
    |L D A B HA IHA Hbody IHB];
    intros D' Hdom.
  - apply TW_top.
  - apply TW_bot.
  - apply TW_int.
  - apply binds_In in Hb.
    apply (proj1 (Hdom X)) in Hb.
    destruct (binds_In_inv typ X D' Hb) as [B HB].
    apply (TW_var D' X B). exact HB.
  - apply TW_rcd. apply IHr. exact Hdom.
  - apply TW_arrow; [apply IH1 | apply IH2]; exact Hdom.
  - apply TW_and; [apply IH1 | apply IH2]; exact Hdom.
  - apply TW_all with L.
    + apply IHA. exact Hdom.
    + intros X HX.
      assert (Hcons : dom (cons (X, A) D) [=] dom (cons (X, A) D')).
      { eapply AtomSetProperties.equal_trans.
        - apply dom_cons.
        - eapply AtomSetProperties.equal_trans.
          + eapply AtomSetProperties.union_equal_2. exact Hdom.
          + apply AtomSetProperties.equal_sym. apply dom_cons. }
      exact (IHB X HX (cons (X, A) D') Hcons).
Qed.

(* Weakening of TWell along a binding-preserving context extension. *)

Lemma TWell_weaken : forall D D' A,
    TWell D A ->
    (forall X B, binds X B D -> binds X B D') ->
    TWell D' A.
Proof.
  intros D D' A H. revert D'.
  induction H as
    [D
    |D
    |D
    |D X A Hb
    |D l A HT IHr
    |D A B H1 IH1 H2 IH2
    |D A B H1 IH1 H2 IH2
    |L D A B HA IHA Hbody IHB];
    intros D' Hmap.
  - apply TW_top.
  - apply TW_bot.
  - apply TW_int.
  - apply (TW_var D' X A). apply Hmap. exact Hb.
  - apply TW_rcd. apply IHr. exact Hmap.
  - apply TW_arrow; [apply IH1 | apply IH2]; exact Hmap.
  - apply TW_and; [apply IH1 | apply IH2]; exact Hmap.
  - apply TW_all with L.
    + apply IHA. exact Hmap.
    + intros X HX. apply (IHB X HX (cons (X, A) D')).
      intros Y C Hy.
      apply binds_cons_1 in Hy.
      destruct Hy as [Heq | Hin].
      * destruct Heq as [HY HC]. subst. apply binds_cons_2; auto.
      * apply binds_cons_3. apply Hmap. exact Hin.
Qed.

(* TCWell entails uniqueness of the type context. *)

Lemma TCWell_uniq : forall D, TCWell D -> uniq D.
Proof.
  intros D H. induction H as [| D X A HTC IH HT Hu].
  - apply uniq_nil.
  - exact Hu.
Qed.

(* Helper: domain equality of two contexts with the same head name. *)

Lemma dom_cons_same : forall (D:tctx) (X:typevar) (A1 A2:typ),
    dom (cons (X, A1) D) [=] dom (cons (X, A2) D).
Proof.
  intros.
  eapply AtomSetProperties.equal_trans.
  - apply dom_cons.
  - apply AtomSetProperties.equal_sym. apply dom_cons.
Qed.

(* topLike types are well formed in a well-formed type context. *)

Lemma topLike_TWell : forall D B, topLike D B -> TCWell D -> TWell D B.
Proof.
  intros D B H.
  induction H as
    [D HTC
    |D A B H1 IH1 H2 IH2
    |D A B HT H2 IH2
    |D l B H IH
    |L D A B Hbody IHBODY
    |D X A HTC Hb Hbl];
    intros HTC'.
  - apply TW_top.
  - apply TW_and; [apply IH1; exact HTC' | apply IH2; exact HTC'].
  - apply TW_arrow; [exact HT | apply IH2; exact HTC'].
  - apply TW_rcd. apply IH. exact HTC'.
  - apply TW_all with L.
    + destruct (atom_fresh L) as [X0 HX0].
      pose proof (topLike_TCWell _ _ (Hbody X0 HX0)) as Hc.
      exact (proj2 (TCWell_cons_inv D X0 A Hc)).
    + intros X HX.
      apply IHBODY; [exact HX |].
      exact (topLike_TCWell (cons (X, A) D)
               (open_typ_wrt_typ B (t_tvar_f X)) (Hbody X HX)).
  - apply (TW_var D X A). exact Hb.
Qed.

(* A split type is well formed if its components are. *)

Lemma spl_TWell : forall D B C1 C2,
    spl B C1 C2 -> TWell D C1 -> TWell D C2 -> TWell D B.
Proof.
  intros D B C1 C2 H. revert D.
  induction H as
    [A B C1 C2 HlcA Hsub IHsub
    |L A B C1 C2 HlcA Hbody IHBODY
    |l B C1 C2 Hsub IHsub
    |A B HlcA HlcB];
    intros D HTC1 HTC2.
  - destruct (TWell_arrow_inv D A C1 HTC1) as [HTA HTC1'].
    destruct (TWell_arrow_inv D A C2 HTC2) as [_ HTC2'].
    apply TW_arrow; [exact HTA | exact (IHsub D HTC1' HTC2')].
  - destruct (TWell_forall_inv D A C1 HTC1) as [L1 Htmp1].
    destruct Htmp1 as [HTA1 Hbody1].
    destruct (TWell_forall_inv D A C2 HTC2) as [L2 Htmp2].
    destruct Htmp2 as [_ Hbody2].
    apply TW_all with ((L \u L1) \u L2).
    + exact HTA1.
    + intros X HX.
      pose proof (notin_union_1 X (L \u L1) L2 HX) as HX12.
      pose proof (notin_union_2 X (L \u L1) L2 HX) as HXL2.
      pose proof (notin_union_1 X L L1 HX12) as HXL.
      pose proof (notin_union_2 X L L1 HX12) as HXL1.
      exact (IHBODY X HXL (cons (X, A) D) (Hbody1 X HXL1) (Hbody2 X HXL2)).
  - pose proof (TWell_rcd_inv D l C1 HTC1) as HTC1'.
    pose proof (TWell_rcd_inv D l C2 HTC2) as HTC2'.
    apply TW_rcd. exact (IHsub D HTC1' HTC2').
  - apply TW_and; assumption.
Qed.

(* ============================================================ *)
(* Well-formedness of algorithmic subtyping                    *)
(* ============================================================ *)

Lemma algo_sub_TWell : forall D A B,
    TCWell D -> algo_sub D A B -> TWell D A /\ TWell D B.
Proof.
  intros D A B HTC H.
  revert HTC.
  induction H as
    [D X HTC0 HT
    |D HTC0
    |D A0 B0 HT Hord Htop
    |D A0 HTC0 HT Hord
    |D A0 B0 C HTB Hord Hsub IHsub
    |D A0 B0 C HTA Hord Hsub IHsub
    |D A1 B1 A2 B2 Hord Hsub1 IH1 Hsub2 IH2
    |L D A1 A2 B1 B2 Hords Hsub1 IH1 Hbody IHB
    |D l A0 B0 Hord Hsub IH
    |D A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2];
    intros HTC.
  - split; exact HT.
  - split; apply TW_int.
  - split.
    + exact HT.
    + exact (topLike_TWell D B0 Htop HTC).
  - split; [apply TW_bot | exact HT].
  - destruct (IHsub HTC) as [HTA HTCt].
    split; [apply TW_and; assumption | exact HTCt].
  - destruct (IHsub HTC) as [HTB HTCt].
    split; [apply TW_and; assumption | exact HTCt].
  - destruct (IH1 HTC) as [HA2 HA1].
    destruct (IH2 HTC) as [HB1 HB2].
    split; apply TW_arrow; assumption.
  - destruct (IH1 HTC) as [HTB1 HTA1].
    split.
    + apply TW_all with (L \u dom D).
      * exact HTA1.
      * intros X HX.
        pose proof (notin_union_1 X L (dom D) HX) as HXL.
        pose proof (notin_union_2 X L (dom D) HX) as HXD.
        assert (HTCcons : TCWell (cons (X, B1) D)).
        { apply TCW_cons.
          - exact HTC.
          - exact HTB1.
          - apply uniq_cons.
            + apply TCWell_uniq. exact HTC.
            + exact HXD. }
        destruct (IHB X HXL HTCcons) as [HA2 _].
        exact (TWell_dom (cons (X, B1) D) (cons (X, A1) D)
                 (open_typ_wrt_typ A2 (t_tvar_f X)) HA2
                 (dom_cons_same D X B1 A1)).
    + apply TW_all with (L \u dom D).
      * exact HTB1.
      * intros X HX.
        pose proof (notin_union_1 X L (dom D) HX) as HXL.
        pose proof (notin_union_2 X L (dom D) HX) as HXD.
        assert (HTCcons : TCWell (cons (X, B1) D)).
        { apply TCW_cons.
          - exact HTC.
          - exact HTB1.
          - apply uniq_cons.
            + apply TCWell_uniq. exact HTC.
            + exact HXD. }
        exact (proj2 (IHB X HXL HTCcons)).
  - destruct (IH HTC) as [HA HB].
    split; apply TW_rcd; assumption.
  - destruct (IH1 HTC) as [HTA HTB1].
    destruct (IH2 HTC) as [_ HTB2].
    split.
    + exact HTA.
    + exact (spl_TWell D B0 B1 B2 Hspl HTB1 HTB2).
Qed.

(* ============================================================ *)
(* Weakening of topLike along a type-context extension         *)
(* ============================================================ *)

Lemma topLike_weaken : forall D D' B,
    topLike D B -> TCWell D' ->
    (forall X C, binds X C D -> binds X C D') ->
    topLike D' B.
Proof.
  intros D D' B H. revert D'.
  induction H as
    [D HTC0
    |D A B H1 IH1 H2 IH2
    |D A B HT H2 IH2
    |D l B H IH
    |L D A B Hbody IHBODY
    |D X A HTC0 Hb Hbl];
    intros D' HTC' Hmap.
  - apply TL_top. exact HTC'.
  - apply TL_and.
    + exact (IH1 D' HTC' Hmap).
    + exact (IH2 D' HTC' Hmap).
  - apply TL_arrow.
    + exact (TWell_weaken D D' A HT Hmap).
    + exact (IH2 D' HTC' Hmap).
  - apply TL_rcd. exact (IH D' HTC' Hmap).
  - apply TL_all with (L \u dom D').
    + intros X HX.
      pose proof (notin_union_1 X L (dom D') HX) as HXL.
      pose proof (notin_union_2 X L (dom D') HX) as HXD'.
      pose proof (topLike_TCWell (cons (X, A) D)
                    (open_typ_wrt_typ B (t_tvar_f X)) (Hbody X HXL)) as Hcc.
      destruct (TCWell_cons_inv D X A Hcc) as [_ HTDA].
      apply (IHBODY X HXL (cons (X, A) D')).
      * apply TCW_cons.
        -- exact HTC'.
        -- exact (TWell_weaken D D' A HTDA Hmap).
        -- apply uniq_cons.
           ++ apply TCWell_uniq. exact HTC'.
           ++ exact HXD'.
      * intros Y C Hy.
        apply binds_cons_1 in Hy.
        destruct Hy as [Heq | Hin].
        -- destruct Heq as [HY HC]. subst. apply binds_cons_2; auto.
        -- apply binds_cons_3. apply Hmap. exact Hin.
  - apply TL_var with (A := A).
    + exact HTC'.
    + apply Hmap. exact Hb.
    + exact Hbl.
Qed.

(* ============================================================ *)
(* Weakening of algorithmic subtyping                          *)
(* ============================================================ *)

Lemma algo_sub_weaken : forall D D' A B,
    TCWell D -> TCWell D' ->
    (forall X C, binds X C D -> binds X C D') ->
    algo_sub D A B -> algo_sub D' A B.
Proof.
  intros D D' A B HTC HTC' Hmap H.
  revert D' HTC HTC' Hmap.
  induction H as
    [D X HTC0 HT
    |D HTC0
    |D A0 B0 HT Hord Htop
    |D A0 HTC0 HT Hord
    |D A0 B0 C HTB Hord Hsub IHsub
    |D A0 B0 C HTA Hord Hsub IHsub
    |D A1 B1 A2 B2 Hord Hsub1 IH1 Hsub2 IH2
    |L D A1 A2 B1 B2 Hords Hsub1 IH1 Hbody IHB
    |D l A0 B0 Hord Hsub IH
    |D A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2];
    intros D' HTC HTC' Hmap.
  - apply S_var.
    + exact HTC'.
    + exact (TWell_weaken D D' (t_tvar_f X) HT Hmap).
  - apply S_int. exact HTC'.
  - apply S_top.
    + exact (TWell_weaken D D' A0 HT Hmap).
    + exact Hord.
    + exact (topLike_weaken D D' B0 Htop HTC' Hmap).
  - apply S_bot.
    + exact HTC'.
    + exact (TWell_weaken D D' A0 HT Hmap).
    + exact Hord.
  - apply S_andl.
    + exact (TWell_weaken D D' B0 HTB Hmap).
    + exact Hord.
    + exact (IHsub D' HTC HTC' Hmap).
  - apply S_andr.
    + exact (TWell_weaken D D' A0 HTA Hmap).
    + exact Hord.
    + exact (IHsub D' HTC HTC' Hmap).
  - apply S_arrow.
    + exact Hord.
    + exact (IH1 D' HTC HTC' Hmap).
    + exact (IH2 D' HTC HTC' Hmap).
  - apply (S_all ((L \u dom D) \u dom D') D' A1 A2 B1 B2).
    + intros X HX.
      pose proof (notin_union_1 X (L \u dom D) (dom D') HX) as HX1.
      pose proof (notin_union_2 X (L \u dom D) (dom D') HX) as HXD'.
      pose proof (notin_union_1 X L (dom D) HX1) as HXL.
      apply Hords. exact HXL.
    + exact (IH1 D' HTC HTC' Hmap).
    + intros X HX.
      pose proof (notin_union_1 X (L \u dom D) (dom D') HX) as HX1.
      pose proof (notin_union_2 X (L \u dom D) (dom D') HX) as HXD'.
      pose proof (notin_union_1 X L (dom D) HX1) as HXL.
      pose proof (notin_union_2 X L (dom D) HX1) as HXD.
      destruct (algo_sub_TWell D B1 A1 HTC Hsub1) as [HTB1 _].
      assert (HTCcons : TCWell (cons (X, B1) D)).
      { apply TCW_cons.
        - exact HTC.
        - exact HTB1.
        - apply uniq_cons.
          + apply TCWell_uniq. exact HTC.
          + exact HXD. }
      assert (HTCcons' : TCWell (cons (X, B1) D')).
      { apply TCW_cons.
        - exact HTC'.
        - exact (TWell_weaken D D' B1 HTB1 Hmap).
        - apply uniq_cons.
          + apply TCWell_uniq. exact HTC'.
          + exact HXD'. }
      apply (IHB X HXL (cons (X, B1) D') HTCcons HTCcons').
      intros Y C Hy.
      apply binds_cons_1 in Hy.
      destruct Hy as [Heq | Hin].
      * destruct Heq as [HY HC]. subst. apply binds_cons_2; auto.
      * apply binds_cons_3. apply Hmap. exact Hin.
  - apply S_rcd.
    + exact Hord.
    + exact (IH D' HTC HTC' Hmap).
  - apply (S_and D' A0 B0 B1 B2 Hspl).
    + exact (IH1 D' HTC HTC' Hmap).
    + exact (IH2 D' HTC HTC' Hmap).
Qed.

(* ============================================================ *)
(* Weakening of disjointness                                   *)
(* ============================================================ *)

Lemma disjoint_weaken : forall D D' A B,
    TCWell D -> TCWell D' ->
    (forall X C, binds X C D -> binds X C D') ->
    disjoint D A B -> disjoint D' A B.
Proof.
  intros D D' A B HTC HTC' Hmap H.
  revert D' HTC HTC' Hmap.
  induction H as
    [D A0 B0 HTC0 HTA HTB Hax
    |D A0 B0 HTB HtopA
    |D A0 B0 HTA HtopB
    |D A1 A2 B1 B2 HT1 HT2 Hsub IHsub
    |D l A0 B0 Hsub IHsub
    |L D A1 B1 A2 B2 HT1 HT2 Hbody IHB
    |D X B0 A0 Hb Hsub
    |D B0 X A0 Hb Hsub
    |D A0 B0 A1 A2 Hspl Hsub1 IH1 Hsub2 IH2
    |D A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2];
    intros D' HTC HTC' Hmap.
  - apply D_ax.
    + exact HTC'.
    + exact (TWell_weaken D D' A0 HTA Hmap).
    + exact (TWell_weaken D D' B0 HTB Hmap).
    + exact Hax.
  - apply D_topl.
    + exact (TWell_weaken D D' B0 HTB Hmap).
    + exact (topLike_weaken D D' A0 HtopA HTC' Hmap).
  - apply D_topr.
    + exact (TWell_weaken D D' A0 HTA Hmap).
    + exact (topLike_weaken D D' B0 HtopB HTC' Hmap).
  - apply D_arrow.
    + exact (TWell_weaken D D' (t_arrow A1 A2) HT1 Hmap).
    + exact (TWell_weaken D D' (t_arrow B1 B2) HT2 Hmap).
    + exact (IHsub D' HTC HTC' Hmap).
  - apply D_rcdEq. exact (IHsub D' HTC HTC' Hmap).
  - apply (D_all ((L \u dom D) \u dom D') D' A1 B1 A2 B2).
    + exact (TWell_weaken D D' A1 HT1 Hmap).
    + exact (TWell_weaken D D' A2 HT2 Hmap).
    + intros X HX.
      pose proof (notin_union_1 X (L \u dom D) (dom D') HX) as HX1.
      pose proof (notin_union_2 X (L \u dom D) (dom D') HX) as HXD'.
      pose proof (notin_union_1 X L (dom D) HX1) as HXL.
      pose proof (notin_union_2 X L (dom D) HX1) as HXD.
      assert (HTCcons : TCWell (cons (X, t_and A1 A2) D)).
      { apply TCW_cons.
        - exact HTC.
        - apply TW_and; assumption.
        - apply uniq_cons.
          + apply TCWell_uniq. exact HTC.
          + exact HXD. }
      assert (HTCcons' : TCWell (cons (X, t_and A1 A2) D')).
      { apply TCW_cons.
        - exact HTC'.
        - apply TW_and.
          + exact (TWell_weaken D D' A1 HT1 Hmap).
          + exact (TWell_weaken D D' A2 HT2 Hmap).
        - apply uniq_cons.
          + apply TCWell_uniq. exact HTC'.
          + exact HXD'. }
      apply (IHB X HXL (cons (X, t_and A1 A2) D') HTCcons HTCcons').
      intros Y C Hy.
      apply binds_cons_1 in Hy.
      destruct Hy as [Heq | Hin].
      * destruct Heq as [HY HC]. subst. apply binds_cons_2; auto.
      * apply binds_cons_3. apply Hmap. exact Hin.
  - apply D_varl with (A := A0).
    + apply Hmap. exact Hb.
    + exact (algo_sub_weaken D D' A0 B0 HTC HTC' Hmap Hsub).
  - apply D_varr with (A := A0).
    + apply Hmap. exact Hb.
    + exact (algo_sub_weaken D D' A0 B0 HTC HTC' Hmap Hsub).
  - apply (D_andl D' A0 B0 A1 A2 Hspl).
    + exact (IH1 D' HTC HTC' Hmap).
    + exact (IH2 D' HTC HTC' Hmap).
  - apply (D_andr D' A0 B0 B1 B2 Hspl).
    + exact (IH1 D' HTC HTC' Hmap).
    + exact (IH2 D' HTC HTC' Hmap).
Qed.

(* ============================================================ *)
(* Transporting CWell along a type-context extension           *)
(* ============================================================ *)

Lemma CWell_weaken : forall D D' G,
    CWell D G -> TCWell D' ->
    (forall X C, binds X C D -> binds X C D') ->
    CWell D' G.
Proof.
  intros D D' G H.
  induction H as [D | D G x A HCW IHCW HTW]; intros HTC' Hmap.
  - apply CW_empty.
  - apply CW_cons.
    + apply IHCW; assumption.
    + exact (TWell_weaken D D' A HTW Hmap).
Qed.

(* ============================================================ *)
(* Weakening of the term context                               *)
(* ============================================================ *)

Lemma typing_weaken_G : forall D G G' e d A,
    Typing D G e d A -> CWell D G' -> uniq G' ->
    (forall x B, binds x B G -> binds x B G') ->
    Typing D G' e d A.
Proof.
  intros D G G' e d A H. revert G'.
  induction H as
    [D G HTC HCW Hu
    |D G i HTC HCW Hu
    |D G x A HTC HCW Hb Hu
    |L D G A e B1 B2 Hsub Hbody IHbody
    |D G e1 e2 C A B Ht1 IH1 Hdist Ht2 IH2
    |L D G e A B HCW Hbody IHbody
    |D G e A C2 B C1 Ht IH Hdist Hdisj
    |D G e l C A Ht IH Hdist
    |D G l e A Ht IH
    |D G e1 e2 A B Ht1 IH1 Ht2 IH2 Hdisj
    |D G e A B Ht1 IH1 Ht2 IH2
    |D G e A Ht IH
    |L D G A e Hbody IHbody
    |D G u1 u2 A B HTC HCW Hu Ht1 IH1 Ht2 IH2 Hcons
    |D G e B A Ht IH Hsub];
    intros G' HCW' Hu' Hmap.
  - apply Typ_top; assumption.
  - apply Typ_lit; assumption.
  - apply Typ_var.
    + exact HTC.
    + exact HCW'.
    + apply Hmap. exact Hb.
    + exact Hu'.
  - apply (Typ_abs (L \u dom G') D G' A e B1 B2 Hsub).
    intros x Hx.
    pose proof (notin_union_1 x L (dom G') Hx) as HxL.
    pose proof (notin_union_2 x L (dom G') Hx) as HxG'.
    specialize (Hbody x HxL).
    destruct (typing_env_wf _ _ _ _ _ Hbody) as [HTCx HCWx].
    destruct HCWx as [HCWx _].
    destruct (CWell_cons_inv D G x A HCWx) as [_ HTDA].
    apply (IHbody x HxL (cons (x, A) G')).
    + apply CW_cons; assumption.
    + apply uniq_cons; assumption.
    + intros y B Hy.
      apply binds_cons_1 in Hy.
      destruct Hy as [Heq | Hin].
      * destruct Heq as [HY HB]. subst. apply binds_cons_2; auto.
      * apply binds_cons_3. apply Hmap. exact Hin.
  - apply (Typ_app D G' e1 e2 C A B).
    + exact (IH1 G' HCW' Hu' Hmap).
    + exact Hdist.
    + exact (IH2 G' HCW' Hu' Hmap).
  - apply (Typ_tabs L D G' e A B).
    + exact HCW'.
    + intros X HX.
      destruct (typing_env_wf _ _ _ _ _ (Hbody X HX)) as [HTCcons _].
      apply (IHbody X HX G').
      * apply (CWell_weaken D (cons (X, A) D) G' HCW' HTCcons).
        intros Y C Hy. apply binds_cons_3. exact Hy.
      * exact Hu'.
      * exact Hmap.
  - apply (Typ_tapp D G' e A C2 B C1).
    + exact (IH G' HCW' Hu' Hmap).
    + exact Hdist.
    + exact Hdisj.
  - apply (Typ_proj D G' e l C A).
    + exact (IH G' HCW' Hu' Hmap).
    + exact Hdist.
  - apply (Typ_rcd D G' l e A).
    exact (IH G' HCW' Hu' Hmap).
  - apply (Typ_merge D G' e1 e2 A B).
    + exact (IH1 G' HCW' Hu' Hmap).
    + exact (IH2 G' HCW' Hu' Hmap).
    + exact Hdisj.
  - apply (Typ_inter D G' e A B).
    + exact (IH1 G' HCW' Hu' Hmap).
    + exact (IH2 G' HCW' Hu' Hmap).
  - apply (Typ_anno D G' e A).
    exact (IH G' HCW' Hu' Hmap).
  - apply (Typ_fix (L \u dom G') D G' A e).
    intros x Hx.
    pose proof (notin_union_1 x L (dom G') Hx) as HxL.
    pose proof (notin_union_2 x L (dom G') Hx) as HxG'.
    specialize (Hbody x HxL).
    destruct (typing_env_wf _ _ _ _ _ Hbody) as [HTCx HCWx].
    destruct HCWx as [HCWx _].
    destruct (CWell_cons_inv D G x A HCWx) as [_ HTDA].
    apply (IHbody x HxL (cons (x, A) G')).
    + apply CW_cons; assumption.
    + apply uniq_cons; assumption.
    + intros y B Hy.
      apply binds_cons_1 in Hy.
      destruct Hy as [Heq | Hin].
      * destruct Heq as [HY HB]. subst. apply binds_cons_2; auto.
      * apply binds_cons_3. apply Hmap. exact Hin.
  - apply (Typ_mergev D G' u1 u2 A B).
    + exact HTC.
    + exact HCW'.
    + exact Hu'.
    + exact Ht1.
    + exact Ht2.
    + exact Hcons.
  - apply (Typ_sub D G' e B A).
    + exact (IH G' HCW' Hu' Hmap).
    + exact Hsub.
Qed.

(* ============================================================ *)
(* Weakening of the type context                               *)
(* ============================================================ *)

Lemma typing_weaken_D_aux : forall D D' G e d A,
    Typing D G e d A -> TCWell D -> TCWell D' ->
    (forall X B, binds X B D -> binds X B D') ->
    Typing D' G e d A.
Proof.
  intros D D' G e d A H. revert D'.
  induction H as
    [D G HTC0 HCW Hu
    |D G i HTC0 HCW Hu
    |D G x A HTC0 HCW Hb Hu
    |L D G A e B1 B2 Hsub Hbody IHbody
    |D G e1 e2 C A B Ht1 IH1 Hdist Ht2 IH2
    |L D G e A B HCW Hbody IHbody
    |D G e A C2 B C1 Ht IH Hdist Hdisj
    |D G e l C A Ht IH Hdist
    |D G l e A Ht IH
    |D G e1 e2 A B Ht1 IH1 Ht2 IH2 Hdisj
    |D G e A B Ht1 IH1 Ht2 IH2
    |D G e A Ht IH
    |L D G A e Hbody IHbody
    |D G u1 u2 A B HTC0 HCW Hu Ht1 IH1 Ht2 IH2 Hcons
    |D G e B A Ht IH Hsub];
    intros D' HTC HTC' Hmap.
  - apply Typ_top.
    + exact HTC'.
    + exact (CWell_weaken D D' G HCW HTC' Hmap).
    + exact Hu.
  - apply Typ_lit.
    + exact HTC'.
    + exact (CWell_weaken D D' G HCW HTC' Hmap).
    + exact Hu.
  - apply Typ_var with (A := A).
    + exact HTC'.
    + exact (CWell_weaken D D' G HCW HTC' Hmap).
    + exact Hb.
    + exact Hu.
  - apply (Typ_abs L D' G A e B1 B2).
    + exact (algo_sub_weaken D D' B1 A HTC HTC' Hmap Hsub).
    + intros x Hx. exact (IHbody x Hx D' HTC HTC' Hmap).
  - apply (Typ_app D' G e1 e2 C A B).
    + exact (IH1 D' HTC HTC' Hmap).
    + exact Hdist.
    + exact (IH2 D' HTC HTC' Hmap).
  - apply (Typ_tabs (L \u dom D') D' G e A B).
    + exact (CWell_weaken D D' G HCW HTC' Hmap).
    + intros X HX.
      pose proof (notin_union_1 X L (dom D') HX) as HXL.
      pose proof (notin_union_2 X L (dom D') HX) as HXD'.
      destruct (typing_env_wf _ _ _ _ _ (Hbody X HXL)) as [HTCcons _].
      destruct (TCWell_cons_inv D X A HTCcons) as [_ HTDA].
      assert (HTCcons' : TCWell (cons (X, A) D')).
      { apply TCW_cons.
        - exact HTC'.
        - exact (TWell_weaken D D' A HTDA Hmap).
        - apply uniq_cons.
          + apply TCWell_uniq. exact HTC'.
          + exact HXD'. }
      apply (IHbody X HXL (cons (X, A) D') HTCcons HTCcons').
      intros Y C Hy.
      apply binds_cons_1 in Hy.
      destruct Hy as [Heq | Hin].
      * destruct Heq as [HY HC]. subst. apply binds_cons_2; auto.
      * apply binds_cons_3. apply Hmap. exact Hin.
  - apply (Typ_tapp D' G e A C2 B C1).
    + exact (IH D' HTC HTC' Hmap).
    + exact Hdist.
    + exact (disjoint_weaken D D' A C1 HTC HTC' Hmap Hdisj).
  - apply (Typ_proj D' G e l C A).
    + exact (IH D' HTC HTC' Hmap).
    + exact Hdist.
  - apply (Typ_rcd D' G l e A).
    exact (IH D' HTC HTC' Hmap).
  - apply (Typ_merge D' G e1 e2 A B).
    + exact (IH1 D' HTC HTC' Hmap).
    + exact (IH2 D' HTC HTC' Hmap).
    + exact (disjoint_weaken D D' A B HTC HTC' Hmap Hdisj).
  - apply (Typ_inter D' G e A B).
    + exact (IH1 D' HTC HTC' Hmap).
    + exact (IH2 D' HTC HTC' Hmap).
  - apply (Typ_anno D' G e A).
    exact (IH D' HTC HTC' Hmap).
  - apply (Typ_fix L D' G A e).
    intros x Hx. exact (IHbody x Hx D' HTC HTC' Hmap).
  - apply (Typ_mergev D' G u1 u2 A B).
    + exact HTC'.
    + exact (CWell_weaken D D' G HCW HTC' Hmap).
    + exact Hu.
    + exact Ht1.
    + exact Ht2.
    + exact Hcons.
  - apply (Typ_sub D' G e B A).
    + exact (IH D' HTC HTC' Hmap).
    + exact (algo_sub_weaken D D' A B HTC HTC' Hmap Hsub).
Qed.

Lemma typing_weaken_D : forall D D' G e d A,
    Typing D G e d A -> TCWell D' ->
    (forall X B, binds X B D -> binds X B D') ->
    Typing D' G e d A.
Proof.
  intros D D' G e d A H HTC' Hmap.
  destruct (typing_env_wf D G e d A H) as [HTC _].
  exact (typing_weaken_D_aux D D' G e d A H HTC HTC' Hmap).
Qed.

(* ============================================================ *)
(* Cons corollaries and permutation                            *)
(* ============================================================ *)

Lemma typing_weaken_G_cons : forall D G y B e d A,
    Typing D G e d A -> TCWell D -> CWell D G -> uniq G ->
    y # G -> TWell D B ->
    Typing D (cons (y, B) G) e d A.
Proof.
  intros D G y B e d A H HTC HCW Hu Hy HTB.
  apply (typing_weaken_G D G (cons (y, B) G) e d A H).
  - apply CW_cons; assumption.
  - apply uniq_cons; assumption.
  - intros x C Hb. apply binds_cons_3. exact Hb.
Qed.

Lemma typing_weaken_D_cons : forall D X B G e d A,
    Typing D G e d A -> TCWell (cons (X, B) D) ->
    Typing (cons (X, B) D) G e d A.
Proof.
  intros D X B G e d A H HTC.
  apply (typing_weaken_D D (cons (X, B) D) G e d A H HTC).
  intros Y C Hy. apply binds_cons_3. exact Hy.
Qed.

Lemma typing_permute_G : forall D G1 G2 e d A,
    Typing D G1 e d A -> uniq G2 -> CWell D G2 ->
    (forall x B, binds x B G1 <-> binds x B G2) ->
    Typing D G2 e d A.
Proof.
  intros D G1 G2 e d A H Hu HCW Hiff.
  apply (typing_weaken_G D G1 G2 e d A H HCW Hu).
  intros x B Hb. apply Hiff. exact Hb.
Qed.

Lemma typing_permute_D : forall D1 D2 G e d A,
    Typing D1 G e d A -> TCWell D2 ->
    (forall X B, binds X B D1 <-> binds X B D2) ->
    Typing D2 G e d A.
Proof.
  intros D1 D2 G e d A H HTC Hiff.
  apply (typing_weaken_D D1 D2 G e d A H HTC).
  intros X B Hb. apply Hiff. exact Hb.
Qed.
End agentD.
Import agentD.

Module agentE.
Import ListNotations.

(* ================================================================== *)
(* Basic facts about casting results                                   *)
(* ================================================================== *)

Lemma lc_exp_abs_lc_typ : forall A e, lc_exp (e_abs A e) -> lc_typ A.
Proof. intros A e H. inversion H; subst. assumption. Qed.

Lemma lc_exp_tabs_body : forall e, lc_exp (e_tabs e) ->
  forall X, lc_exp (open_exp_wrt_typ e (t_tvar_f X)).
Proof. intros e H. inversion H; subst. assumption. Qed.

Lemma lc_exp_rcd_body : forall l e, lc_exp (e_rcd l e) -> lc_exp e.
Proof. intros l e H. inversion H; subst. assumption. Qed.

Lemma casting_prevalue : forall v A v', casting v A v' -> prevalue v'.
Proof.
  intros v A v' H. induction H.
  - apply PV_int.
  - apply PV_top.
  - apply PV_anno.
    + apply lc_e_abs.
      * apply lc_t_top.
      * intros x. apply lc_e_top.
    + apply (ord_lc_typ (t_arrow A1 A2)); assumption.
  - apply PV_anno.
    + apply lc_e_tabs. intros X. apply lc_e_top.
    + apply (ord_lc_typ (t_forall A1 A2)); assumption.
  - apply PV_anno.
    + apply lc_e_rcd. apply lc_e_top.
    + apply (ord_lc_typ (t_rcd l A)); assumption.
  - apply PV_anno.
    + assumption.
    + apply (ord_lc_typ B); assumption.
  - assumption.
  - assumption.
  - apply PV_merge; assumption.
Qed.

(* The statement "casting_pType : casting v A v' -> pType v' A" is FALSE:
   for Cast_and the result has pType (t_and B C), while the cast target is
   the spl source A.  The best correct statement is the following: if the
   result is not a merge (the Cast_and image), then it has pType A. *)

Lemma casting_pType_nonmerge : forall v A v', casting v A v' ->
  (forall b c : exp, v' <> e_merge b c) -> pType v' A.
Proof.
  intros v A v' H. induction H; intro Hna.
  - apply PT_int.
  - apply PT_top.
  - apply PT_anno.
    + apply lc_e_abs.
      * apply lc_t_top.
      * intros x. apply lc_e_top.
    + apply (ord_lc_typ (t_arrow A1 A2)); assumption.
  - apply PT_anno.
    + apply lc_e_tabs. intros X. apply lc_e_top.
    + apply (ord_lc_typ (t_forall A1 A2)); assumption.
  - apply PT_anno.
    + apply lc_e_rcd. apply lc_e_top.
    + apply (ord_lc_typ (t_rcd l A)); assumption.
  - apply PT_anno.
    + assumption.
    + apply (ord_lc_typ B); assumption.
  - apply IHcasting. assumption.
  - apply IHcasting. assumption.
  - exfalso. apply (Hna v1 v2). reflexivity.
Qed.

(* Corrected version: a cast result always has *some* pType, and in the
   Cast_and case it is the intersection of the two component pTypes. *)
Lemma casting_pType_exists : forall v A v', casting v A v' -> exists T, pType v' T.
Proof.
  intros v A v' H. induction H.
  - exists t_int. apply PT_int.
  - exists t_top. apply PT_top.
  - exists (t_arrow A1 A2). apply PT_anno.
    + apply lc_e_abs; [apply lc_t_top | intros x; apply lc_e_top].
    + apply (ord_lc_typ (t_arrow A1 A2)); assumption.
  - exists (t_forall A1 A2). apply PT_anno.
    + apply lc_e_tabs; intros X; apply lc_e_top.
    + apply (ord_lc_typ (t_forall A1 A2)); assumption.
  - exists (t_rcd l A). apply PT_anno.
    + apply lc_e_rcd; apply lc_e_top.
    + apply (ord_lc_typ (t_rcd l A)); assumption.
  - exists B. apply PT_anno.
    + assumption.
    + apply (ord_lc_typ B); assumption.
  - exact IHcasting.
  - exact IHcasting.
  - destruct IHcasting1 as [T1 HT1]. destruct IHcasting2 as [T2 HT2].
    exists (t_and T1 T2). apply PT_merge; assumption.
Qed.

(* ================================================================== *)
(* Copy of the algorithmic-subtyping inversions for intersections      *)
(* (independent of the Section assumptions in progress.v).             *)
(* ================================================================== *)

Lemma algo_sub_and_l : forall D X A B, algo_sub D X (t_and A B) -> algo_sub D X A.
Proof.
  intros D X A B H. remember (t_and A B) as T eqn:ET.
  revert A B ET. induction H; intros A0 B0 ET.
  - discriminate ET.
  - discriminate ET.
  - subst. exfalso. match goal with Ho : ord (t_and _ _) |- _ => inversion Ho end.
  - subst. exfalso. match goal with Ho : ord (t_and _ _) |- _ => inversion Ho end.
  - subst. exfalso. match goal with Ho : ord (t_and _ _) |- _ => inversion Ho end.
  - subst. exfalso. match goal with Ho : ord (t_and _ _) |- _ => inversion Ho end.
  - discriminate ET.
  - discriminate ET.
  - discriminate ET.
  - subst. match goal with Hs : spl (t_and A0 B0) ?C1 ?C2 |- _ =>
      inversion Hs; subst; try assumption;
      try (exfalso; match goal with Ho : ord (t_and _ _) |- _ => inversion Ho end) end.
Qed.

Lemma algo_sub_and_r : forall D X A B, algo_sub D X (t_and A B) -> algo_sub D X B.
Proof.
  intros D X A B H. remember (t_and A B) as T eqn:ET.
  revert A B ET. induction H; intros A0 B0 ET.
  - discriminate ET.
  - discriminate ET.
  - subst. exfalso. match goal with Ho : ord (t_and _ _) |- _ => inversion Ho end.
  - subst. exfalso. match goal with Ho : ord (t_and _ _) |- _ => inversion Ho end.
  - subst. exfalso. match goal with Ho : ord (t_and _ _) |- _ => inversion Ho end.
  - subst. exfalso. match goal with Ho : ord (t_and _ _) |- _ => inversion Ho end.
  - discriminate ET.
  - discriminate ET.
  - discriminate ET.
  - subst. match goal with Hs : spl (t_and A0 B0) ?C1 ?C2 |- _ =>
      inversion Hs; subst; try assumption;
      try (exfalso; match goal with Ho : ord (t_and _ _) |- _ => inversion Ho end) end.
Qed.

Lemma chk_and_l_gen : forall D G e d T, Typing D G e d T ->
  forall A B, T = t_and A B -> d = Chk -> Typing D G e Chk A.
Proof.
  intros D G e d T Hty. induction Hty; intros A0 B0 ET Ed.
  - discriminate Ed. - discriminate Ed. - discriminate Ed.
  - discriminate ET.
  - discriminate Ed.
  - discriminate ET.
  - discriminate Ed. - discriminate Ed.
  - discriminate ET.
  - discriminate Ed.
  - inversion ET; subst. match goal with H1 : Typing D G e Chk A0 |- _ => exact H1 end.
  - discriminate Ed.
  - discriminate Ed.
  - discriminate Ed.
  - inversion ET; subst.
    match goal with Hinf : Typing D G e Inf ?C, Hs : algo_sub D ?C (t_and A0 B0) |- _ =>
      exact (Typ_sub D G e A0 C Hinf (algo_sub_and_l D C A0 B0 Hs)) end.
Qed.

Lemma chk_and_r_gen : forall D G e d T, Typing D G e d T ->
  forall A B, T = t_and A B -> d = Chk -> Typing D G e Chk B.
Proof.
  intros D G e d T Hty. induction Hty; intros A0 B0 ET Ed.
  - discriminate Ed. - discriminate Ed. - discriminate Ed.
  - discriminate ET.
  - discriminate Ed.
  - discriminate ET.
  - discriminate Ed. - discriminate Ed.
  - discriminate ET.
  - discriminate Ed.
  - inversion ET; subst. match goal with H1 : Typing D G e Chk B0 |- _ => exact H1 end.
  - discriminate Ed.
  - discriminate Ed.
  - discriminate Ed.
  - inversion ET; subst.
    match goal with Hinf : Typing D G e Inf ?C, Hs : algo_sub D ?C (t_and A0 B0) |- _ =>
      exact (Typ_sub D G e B0 C Hinf (algo_sub_and_r D C A0 B0 Hs)) end.
Qed.

Lemma chk_and_l : forall D G e A B, Typing D G e Chk (t_and A B) -> Typing D G e Chk A.
Proof. intros. eapply chk_and_l_gen; [ exact H | reflexivity | reflexivity ]. Qed.

Lemma chk_and_r : forall D G e A B, Typing D G e Chk (t_and A B) -> Typing D G e Chk B.
Proof. intros. eapply chk_and_r_gen; [ exact H | reflexivity | reflexivity ]. Qed.

(* ================================================================== *)
(* Splitting and ordinariness                                          *)
(* ================================================================== *)

Lemma InA_In : forall (x:atom) (l:list atom), InA eq x l -> In x l.
Proof. induction 1; [left; auto | right; auto]. Qed.

Lemma fresh_notin : forall (L:atoms), fresh (AtomSetImpl.elements L) \notin L.
Proof.
  intros L Hin.
  apply (Atom.fresh_not_in (AtomSetImpl.elements L)).
  apply InA_In. apply AtomSetImpl.elements_1. exact Hin.
Qed.

Lemma spl_not_ord : forall A B C, spl A B C -> ~ ord A.
Proof.
  intros A B C H. induction H; intro Ho.
  - destruct (ord_arrow_inv A B Ho) as [_ HoB]. exact (IHspl HoB).
  - destruct (ord_all_inv A B Ho) as [_ HoB].
    destruct (atom_fresh L) as [X HX].
    exact (H1 X HX (HoB X)).
  - apply (IHspl (ord_rcd_inv l B Ho)).
  - inversion Ho.
Qed.

(* ================================================================== *)
(* Injectivity of opening a type for a fresh variable                  *)
(* ================================================================== *)

Lemma open_bvar_eq : forall k (X:typevar) n m,
  open_typ_wrt_typ_rec k (t_tvar_f X) (t_tvar_b n) =
  open_typ_wrt_typ_rec k (t_tvar_f X) (t_tvar_b m) -> n = m.
Proof.
  intros k X n m.
  cbn [open_typ_wrt_typ_rec].
  destruct (lt_eq_lt_dec n k) as [Hn|Hgt].
  - destruct Hn as [Hlt|Hne].
    + destruct (lt_eq_lt_dec m k) as [Hm|Hgt'].
      * destruct Hm as [Hlt'|Hne'].
        -- intro E. injection E. lia.
        -- intro E. discriminate.
      * intro E. injection E. lia.
    + destruct (lt_eq_lt_dec m k) as [Hm|Hgt'].
      * destruct Hm as [Hlt'|Hne'].
        -- intro E. discriminate.
        -- intro E. lia.
      * intro E. discriminate.
  - destruct (lt_eq_lt_dec m k) as [Hm|Hgt'].
    + destruct Hm as [Hlt'|Hne'].
      * intro E. injection E. lia.
      * intro E. discriminate.
    + intro E. injection E. lia.
Qed.

Lemma close_open_typ : forall A k (Y:typevar),
  Y \notin typefv_typ A ->
  close_typ_wrt_typ_rec k Y (open_typ_wrt_typ_rec k (t_tvar_f Y) A) = A.
Proof.
  induction A; intros k Y HA; simpl.
  - (* tvar_b *)
    destruct (lt_eq_lt_dec n k) as [Hn|Hgt].
    + destruct Hn as [Hlt|Hne].
      * cbn [close_typ_wrt_typ_rec]. destruct (lt_ge_dec n k) as [Hlk|Hge]; [reflexivity | exfalso; lia].
      * subst n. cbn [close_typ_wrt_typ_rec]. destruct (Y == Y) as [Heq|Hneq]; [reflexivity | exfalso; apply Hneq; reflexivity].
    + cbn [close_typ_wrt_typ_rec]. destruct (lt_ge_dec (n-1) k) as [Hlk|Hge]; [exfalso; lia | f_equal; lia].
  - (* tvar_f *)
    cbn [close_typ_wrt_typ_rec]. destruct (Y == X) as [Heq|Hneq].
    + simpl in HA. exfalso. apply (notin_singleton Y X HA). exact Heq.
    + reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - (* forall *)
    destruct (notin_union Y (typefv_typ A1) (typefv_typ A2) HA) as [HA1 HA2].
    rewrite (IHA1 k Y HA1). rewrite (IHA2 (S k) Y HA2). reflexivity.
  - (* arrow *)
    destruct (notin_union Y (typefv_typ A1) (typefv_typ A2) HA) as [HA1 HA2].
    rewrite (IHA1 k Y HA1). rewrite (IHA2 k Y HA2). reflexivity.
  - (* and *)
    destruct (notin_union Y (typefv_typ A1) (typefv_typ A2) HA) as [HA1 HA2].
    rewrite (IHA1 k Y HA1). rewrite (IHA2 k Y HA2). reflexivity.
  - (* rcd *)
    rewrite (IHA k Y HA). reflexivity.
Qed.

Lemma open_typ_rec_inj : forall A B k (Y:typevar),
  Y \notin typefv_typ A -> Y \notin typefv_typ B ->
  open_typ_wrt_typ_rec k (t_tvar_f Y) A = open_typ_wrt_typ_rec k (t_tvar_f Y) B -> A = B.
Proof.
  intros A B k Y HA HB E.
  assert (H := f_equal (close_typ_wrt_typ_rec k Y) E).
  rewrite (close_open_typ A k Y HA) in H.
  rewrite (close_open_typ B k Y HB) in H.
  exact H.
Qed.

(* ================================================================== *)
(* Determinacy of splitting                                          *)
(* ================================================================== *)

Lemma spl_functional_aux : forall n A B1 C1 B2 C2,
  size_typ A <= n -> spl A B1 C1 -> spl A B2 C2 -> B1 = B2 /\ C1 = C2.
Proof.
  induction n as [|n IH]; intros A B1 C1 B2 C2 Hle H1 H2.
  - exfalso. pose proof (size_typ_pos A). lia.
  - destruct H1 as [A0 B0 C10 C20 Hlc Hspl
                 | L A0 B0 C10 C20 Hlc Hbody
                 | l B0 C10 C20 Hspl
                 | A0 B0 HlcA HlcB].
    + (* Sp_arrow *)
      inversion H2; subst.
      assert (Hsz : size_typ B0 <= n) by (simpl in Hle; lia).
      destruct (IH B0 C10 C20 C1 C0 Hsz Hspl H5) as [E1 E2].
      subst. split; reflexivity.
    + (* Sp_all *)
      inversion H2; subst.
      destruct (atom_fresh (L \u L0 \u [[C10]] \u [[C20]] \u [[C1]] \u [[C0]])) as [Z HZ].
      destruct (notin_union Z L (L0 \u [[C10]] \u [[C20]] \u [[C1]] \u [[C0]]) HZ) as [HZL HZ1].
      destruct (notin_union Z L0 ([[C10]] \u [[C20]] \u [[C1]] \u [[C0]]) HZ1) as [HZL0 HZ2].
      destruct (notin_union Z [[C10]] ([[C20]] \u [[C1]] \u [[C0]]) HZ2) as [HZC10 HZ3].
      destruct (notin_union Z [[C20]] ([[C1]] \u [[C0]]) HZ3) as [HZC20 HZ4].
      destruct (notin_union Z [[C1]] [[C0]] HZ4) as [HZC1 HZC0].
      assert (Hb1 := Hbody Z HZL).
      assert (Hb2 := H5 Z HZL0).
      assert (Hsz : size_typ (open_typ_wrt_typ B0 (t_tvar_f Z)) <= n)
        by (unfold open_typ_wrt_typ; rewrite size_typ_open_typ_tvar; simpl in Hle; lia).
      destruct (IH (open_typ_wrt_typ B0 (t_tvar_f Z))
                   (open_typ_wrt_typ C10 (t_tvar_f Z)) (open_typ_wrt_typ C20 (t_tvar_f Z))
                   (open_typ_wrt_typ C1 (t_tvar_f Z)) (open_typ_wrt_typ C0 (t_tvar_f Z))
                   Hsz Hb1 Hb2) as [E1 E2].
      assert (HC1 : C10 = C1) by
        (apply (open_typ_rec_inj C10 C1 0 Z); [simpl; exact HZC10 | simpl; exact HZC1 | exact E1]).
      assert (HC2 : C20 = C0) by
        (apply (open_typ_rec_inj C20 C0 0 Z); [simpl; exact HZC20 | simpl; exact HZC0 | exact E2]).
      subst. split; reflexivity.
    + (* Sp_rcd *)
      inversion H2; subst.
      assert (Hsz : size_typ B0 <= n) by (simpl in Hle; lia).
      destruct (IH B0 C10 C20 C1 C0 Hsz Hspl H4) as [E1 E2].
      subst. split; reflexivity.
    + (* Sp_and *)
      inversion H2; subst. split; reflexivity.
Qed.

Lemma spl_functional : forall A B1 C1 B2 C2,
  spl A B1 C1 -> spl A B2 C2 -> B1 = B2 /\ C1 = C2.
Proof.
  intros A B1 C1 B2 C2 H1 H2.
  apply (spl_functional_aux (size_typ A) A B1 C1 B2 C2).
  - lia.
  - exact H1.
  - exact H2.
Qed.

(* ================================================================== *)
(* Splitting a source of an algorithmic subtyping                      *)
(* ================================================================== *)

Lemma algo_sub_spl_l : forall D A0 A B C,
  algo_sub D A0 A -> spl A B C -> algo_sub D A0 B.
Proof.
  intros D A0 A B C H. revert B C.
  induction H; intros U V Hspl.
  - inversion Hspl.
  - inversion Hspl.
  - exfalso. eapply spl_not_ord; eassumption.
  - exfalso. eapply spl_not_ord; eassumption.
  - exfalso. eapply spl_not_ord; eassumption.
  - exfalso. eapply spl_not_ord; eassumption.
  - inversion Hspl; subst.
    match goal with Ht : spl B2 ?X ?Y |- _ => exfalso; eapply spl_not_ord; [exact Ht | exact H] end.
  - inversion Hspl; subst.
    destruct (atom_fresh (L \u L0)) as [Z HZ].
    destruct (notin_union Z L L0 HZ) as [HZL HZL0].
    exfalso. exact (spl_not_ord (open_typ_wrt_typ B2 (t_tvar_f Z)) (open_typ_wrt_typ C1 (t_tvar_f Z)) (open_typ_wrt_typ C2 (t_tvar_f Z)) (H8 Z HZL0) (H Z HZL)).
  - inversion Hspl; subst.
    match goal with Ht : spl ?S ?X ?Y |- _ => exfalso; eapply spl_not_ord; [exact Ht | exact H] end.
  - destruct (spl_functional B B1 B2 U V H Hspl) as [E1 E2].
    subst. exact H0.
Qed.

Lemma algo_sub_spl_r : forall D A0 A B C,
  algo_sub D A0 A -> spl A B C -> algo_sub D A0 C.
Proof.
  intros D A0 A B C H. revert B C.
  induction H; intros U V Hspl.
  - inversion Hspl.
  - inversion Hspl.
  - exfalso. eapply spl_not_ord; eassumption.
  - exfalso. eapply spl_not_ord; eassumption.
  - exfalso. eapply spl_not_ord; eassumption.
  - exfalso. eapply spl_not_ord; eassumption.
  - inversion Hspl; subst.
    match goal with Ht : spl B2 ?X ?Y |- _ => exfalso; eapply spl_not_ord; [exact Ht | exact H] end.
  - inversion Hspl; subst.
    destruct (atom_fresh (L \u L0)) as [Z HZ].
    destruct (notin_union Z L L0 HZ) as [HZL HZL0].
    exfalso. exact (spl_not_ord (open_typ_wrt_typ B2 (t_tvar_f Z)) (open_typ_wrt_typ C1 (t_tvar_f Z)) (open_typ_wrt_typ C2 (t_tvar_f Z)) (H8 Z HZL0) (H Z HZL)).
  - inversion Hspl; subst.
    match goal with Ht : spl ?S ?X ?Y |- _ => exfalso; eapply spl_not_ord; [exact Ht | exact H] end.
  - destruct (spl_functional B B1 B2 U V H Hspl) as [E1 E2].
    subst. exact H1.
Qed.

(* ================================================================== *)
(* Bot-like and top-like types under algorithmic subtyping             *)
(* ================================================================== *)

Lemma not_topLike_botLike : forall D A, topLike D A -> botLike A -> False.
Proof.
  intros D A HT. induction HT as
    [D0 HTC | D0 A0 B0 H1 IH1 H2 IH2 | D0 A0 B0 HTW H2 IH2
     | D0 l B0 H1 IH1 | L D0 A0 B0 Hbody IHBODY | D0 X A0 HTC Hb Hbl];
    intro HB.
  - inversion HB.
  - inversion HB as [|A1 B1 HlcB HblA|A1 B1 HlcA HblB]; subst.
    + apply (IH1 HblA).
    + apply (IH2 HblB).
  - inversion HB.
  - inversion HB.
  - inversion HB.
  - inversion HB.
Qed.

Lemma botLike_spl : forall B B1 B2, botLike B -> spl B B1 B2 ->
  botLike B1 \/ botLike B2.
Proof.
  intros B B1 B2 HB Hs. induction HB.
  - inversion Hs.
  - inversion Hs; subst. left. assumption.
  - inversion Hs; subst. right. assumption.
Qed.

Lemma algo_sub_botLike_gen : forall D A B, algo_sub D A B -> botLike B -> botLike A.
Proof.
  intros D A B H. induction H; intro HB.
  - inversion HB.
  - inversion HB.
  - exfalso. match goal with Ht : topLike D ?T |- _ =>
      exact (not_topLike_botLike D T Ht HB) end.
  - apply BL_bot.
  - apply BL_andl.
    + match goal with HT : TWell D ?Y |- lc_typ ?Y => exact (TWell_lc D Y HT) end.
    + apply IHalgo_sub. exact HB.
  - apply BL_andr.
    + match goal with HT : TWell D ?Y |- lc_typ ?Y => exact (TWell_lc D Y HT) end.
    + apply IHalgo_sub. exact HB.
  - inversion HB.
  - inversion HB.
  - inversion HB.
  - match goal with Hs : spl ?B ?X ?Y |- _ =>
      destruct (botLike_spl B X Y HB Hs) as [Hb1 | Hb2];
      [ apply IHalgo_sub1; exact Hb1 | apply IHalgo_sub2; exact Hb2 ] end.
Qed.

(* ================================================================== *)
(* Transporting top-like types along a change of one type binding      *)
(* ================================================================== *)

Lemma topLike_conv : forall D1 T, topLike D1 T ->
  forall D2, TCWell D2 ->
  map fst D1 = map fst D2 ->
  (forall X C, binds X C D1 ->
     exists C', binds X C' D2 /\ (botLike C -> botLike C')) ->
  topLike D2 T.
Proof.
  intros D1 T HT. induction HT as
    [D0 HTC | D0 A B H1 IH1 H2 IH2 | D0 A B HTW H2 IH2
     | D0 l B0 H1 IH1 | L D0 A0 B0 Hbody IHBODY | D0 X A0 HTC Hb Hbl];
    intros D2 HTC2 Hmap R.
  - apply TL_top. exact HTC2.
  - apply TL_and; [ exact (IH1 D2 HTC2 Hmap R) | exact (IH2 D2 HTC2 Hmap R) ].
  - apply TL_arrow.
    + apply (TWell_dom_irrel D0 A HTW D2 Hmap).
    + exact (IH2 D2 HTC2 Hmap R).
  - apply TL_rcd. exact (IH1 D2 HTC2 Hmap R).
  - apply (TL_all ((L \u dom D2) \u dom D0) D2 A0 B0).
    intros X HX.
    assert (HX2 : X \notin (L \u dom D2) \u dom D0) by exact HX.
    destruct (notin_union X (L \u dom D2) (dom D0) HX2) as [HX12 HXD0].
    destruct (notin_union X L (dom D2) HX12) as [HXL HXD2].
    assert (HTWA : TWell D0 A0) by (exact (topLike_all_dom D0 A0 B0 (TL_all L D0 A0 B0 Hbody))).
    assert (HTWA2 : TWell D2 A0) by (apply (TWell_dom_irrel D0 A0 HTWA D2 Hmap)).
    assert (HTCcons2 : TCWell (cons (X,A0) D2)).
    { apply (TCW_cons D2 X A0 HTC2 HTWA2).
      apply uniq_cons.
      - apply (TCWell_uniq D2 HTC2).
      - exact HXD2. }
    assert (Hmap' : map fst (cons (X,A0) D0) = map fst (cons (X,A0) D2)).
    { simpl. rewrite Hmap. reflexivity. }
    assert (R' : forall Y C, binds Y C (cons (X,A0) D0) ->
                exists C', binds Y C' (cons (X,A0) D2) /\ (botLike C -> botLike C')).
    { intros Y C Hb. apply binds_cons_1 in Hb.
      destruct Hb as [Hx | Hin].
      - destruct Hx as [HY HC]. subst. exists A0. split;
          [ apply binds_cons_2; reflexivity | intro Hbl; exact Hbl ].
      - destruct (R Y C Hin) as [C' Hpair]. destruct Hpair as [Hb' Hbl'].
        exists C'. split;
          [ apply binds_cons_3; exact Hb' | exact Hbl' ]. }
    apply (IHBODY X HXL); [exact HTCcons2 | exact Hmap' | exact R'].
  - destruct (R X A0 Hb) as [C' Hpair]. destruct Hpair as [Hb' Hbl'].
    apply (TL_var D2 X C' HTC2 Hb').
    apply Hbl'. exact Hbl.
Qed.

Corollary topLike_ctx_sub : forall D (X:typevar) A1 B1 T,
  TCWell D -> X \notin dom D ->
  algo_sub D B1 A1 ->
  topLike (cons (X,A1) D) T ->
  topLike (cons (X,B1) D) T.
Proof.
  intros D X A1 B1 T HTC HXD Hrel HT.
  assert (HTB1 : TWell D B1) by (apply (algo_sub_TWell_source D B1 A1); assumption).
  assert (HTC' : TCWell (cons (X,B1) D)).
  { apply (TCW_cons D X B1 HTC HTB1). apply uniq_cons.
    - apply (TCWell_uniq D HTC).
    - exact HXD. }
  assert (Hmap : map fst (cons (X,A1) D) = map fst (cons (X,B1) D))
    by (simpl; reflexivity).
  assert (R : forall Y C, binds Y C (cons (X,A1) D) ->
             exists C', binds Y C' (cons (X,B1) D) /\ (botLike C -> botLike C')).
  { intros Y C Hb. apply binds_cons_1 in Hb. destruct Hb as [Hx | Hin].
    - destruct Hx as [HY HC]. subst. exists B1. split;
        [ apply binds_cons_2; reflexivity
        | intro Hbl; exact (algo_sub_botLike_gen D B1 A1 Hrel Hbl) ].
    - exists C. split; [ apply binds_cons_3; exact Hin | intro Hbl; exact Hbl ]. }
  apply (topLike_conv (cons (X,A1) D) T HT (cons (X,B1) D) HTC' Hmap R).
Qed.

(* ================================================================== *)
(* Counterexample: casting_typing_inf is not provable                  *)
(* ================================================================== *)

Definition Bt := t_arrow t_top t_top.
Definition At := t_arrow t_top (t_and t_top t_top).
Definition A0t := t_and Bt Bt.
Definition eabs := e_abs t_top e_top.
Definition v1t := e_anno eabs Bt.
Definition vt := e_merge v1t v1t.

Lemma uniq_tcons : forall (x:termvar) A, uniq (cons (x,A) (nil:ctx)).
Proof.
  intros x A. apply (uniq_cons typ x A nil).
  - apply (@uniq_nil typ).
  - apply notin_empty.
Qed.

Lemma TCW_cons_top : forall (x:termvar), TCWell (cons (x,t_top) (nil:tctx)).
Proof.
  intros. apply TCW_cons.
  - apply TCW_empty.
  - apply TW_top.
  - apply uniq_tcons.
Qed.

Lemma lc_eabs : lc_exp eabs.
Proof. apply lc_e_abs; [apply lc_t_top | intros x; apply lc_e_top]. Qed.

Lemma lc_Bt : lc_typ Bt.
Proof. apply lc_t_arrow; apply lc_t_top. Qed.

Lemma lc_A0t : lc_typ A0t.
Proof. apply lc_t_and; apply lc_Bt. Qed.

Lemma TWell_Bt : TWell nil Bt.
Proof. apply TW_arrow; apply TW_top. Qed.

Lemma ord_Bt : ord Bt.
Proof. apply (O_arrow t_top t_top); [apply lc_t_top | apply O_top]. Qed.

Lemma topLike_Bt : topLike nil Bt.
Proof. apply (TL_arrow nil t_top t_top); [apply TW_top | apply TL_top; apply TCW_empty]. Qed.

Lemma asub_top_top : algo_sub nil t_top t_top.
Proof. apply (S_top nil t_top t_top); [apply TW_top | apply O_top | apply TL_top; apply TCW_empty]. Qed.

Lemma asub_Bt_Bt : algo_sub nil Bt Bt.
Proof.
  apply (S_arrow nil t_top t_top t_top t_top).
  - apply O_top.
  - apply asub_top_top.
  - apply asub_top_top.
Qed.

Lemma asub_A0_Bt : algo_sub nil A0t Bt.
Proof.
  apply (S_andl nil Bt Bt Bt).
  - apply TWell_Bt.
  - apply ord_Bt.
  - apply asub_Bt_Bt.
Qed.

Lemma spl_At_Bt : spl At Bt Bt.
Proof.
  unfold At, Bt.
  apply (Sp_arrow t_top (t_and t_top t_top) t_top t_top).
  - apply lc_t_top.
  - apply Sp_and; apply lc_t_top.
Qed.

Lemma asub_A0_At : algo_sub nil A0t At.
Proof.
  apply (S_and nil A0t At Bt Bt).
  - apply spl_At_Bt.
  - apply asub_A0_Bt.
  - apply asub_A0_Bt.
Qed.

Lemma typing_eabs_Bt : Typing nil nil eabs Chk Bt.
Proof.
  unfold eabs, Bt.
  apply (Typ_abs empty (nil:tctx) (nil:ctx) t_top e_top t_top t_top).
  - apply asub_top_top.
  - intros x Hx. cbn [open_exp_wrt_exp open_exp_wrt_exp_rec].
    apply (Typ_sub nil (cons (x,t_top) (nil:ctx)) e_top t_top t_top).
    + apply Typ_top.
      * apply TCW_empty.
      * apply (CW_cons nil nil x t_top (CW_empty nil) (TW_top nil)).
      * apply uniq_tcons.
    + apply asub_top_top.
Qed.

Lemma typing_v1 : Typing nil nil v1t Inf Bt.
Proof.
  unfold v1t.
  apply Typ_anno.
  apply typing_eabs_Bt.
Qed.

Lemma consistent_v1 : consistent v1t v1t.
Proof.
  unfold v1t.
  apply (C_anno eabs Bt Bt); [apply lc_Bt | apply lc_eabs | apply lc_Bt].
Qed.

Lemma typing_v : Typing nil nil vt Inf A0t.
Proof.
  unfold vt, A0t, v1t.
  apply (Typ_mergev nil nil (e_anno eabs Bt) (e_anno eabs Bt) Bt Bt).
  - apply TCW_empty.
  - apply (CW_empty nil).
  - apply (@uniq_nil typ).
  - apply typing_v1.
  - apply typing_v1.
  - apply consistent_v1.
Qed.

Lemma value_v : value vt.
Proof.
  unfold vt, v1t.
  apply V_merge.
  - apply (V_abs t_top e_top Bt); [apply lc_t_top | apply lc_eabs | apply lc_Bt].
  - apply (V_abs t_top e_top Bt); [apply lc_t_top | apply lc_eabs | apply lc_Bt].
Qed.

Lemma prevalue_v : prevalue vt.
Proof.
  unfold vt, v1t.
  apply PV_merge.
  - apply PV_anno; [apply lc_eabs | apply lc_Bt].
  - apply PV_anno; [apply lc_eabs | apply lc_Bt].
Qed.

Lemma cast_v1 : casting v1t Bt v1t.
Proof.
  unfold v1t.
  apply (Cast_topArrow (e_anno eabs Bt) t_top t_top).
  - apply lc_e_anno; [apply lc_eabs | apply lc_Bt].
  - apply ord_Bt.
  - apply topLike_Bt.
Qed.

Lemma cast_v_Bt : casting vt Bt v1t.
Proof.
  unfold vt.
  apply (Cast_mergel v1t v1t Bt v1t).
  - unfold v1t. apply lc_e_anno; [apply lc_eabs | apply lc_Bt].
  - apply ord_Bt.
  - apply cast_v1.
Qed.

Lemma cast_v_At : casting vt At (e_merge v1t v1t).
Proof.
  unfold vt.
  apply (Cast_and (e_merge v1t v1t) At v1t v1t Bt Bt).
  - apply spl_At_Bt.
  - apply cast_v_Bt.
  - apply cast_v_Bt.
Qed.

Theorem casting_typing_inf_false :
  ~ (forall (v:exp) A0 A v', Typing nil nil v Inf A0 -> value v -> prevalue v ->
       algo_sub nil A0 A -> casting v A v' -> Typing nil nil v' Inf A).
Proof.
  intro H.
  assert (Hty : Typing nil nil (e_merge v1t v1t) Inf At)
    by (apply (H vt A0t At (e_merge v1t v1t));
        [apply typing_v | apply value_v | apply prevalue_v | apply asub_A0_At | apply cast_v_At]).
  unfold At in Hty.
  inversion Hty.
Qed.

Theorem casting_pType_false :
  ~ (forall (v:exp) A v', casting v A v' -> pType v' A).
Proof.
  intro H.
  assert (Hp : pType (e_merge v1t v1t) At)
    by (apply (H vt At (e_merge v1t v1t)); apply cast_v_At).
  unfold At in Hp.
  inversion Hp.
Qed.

(* ================================================================== *)
(* Status of chk_sub_ord_ntl                                           *)
(* ================================================================== *)

(* The unconditional statement

     chk_sub_ord_ntl :
       forall D G e A B,
         Typing D G e Chk A -> algo_sub D A B -> ord B ->
         notTopLike D B -> Typing D G e Chk B

   is NOT proved here.  No counterexample was found, but the proof needs
   the following two pieces of infrastructure, neither of which is
   available in agentA/agentB/agentC:

   1. Transitivity/composition of algorithmic subtyping:
        algo_sub_trans :
          forall D A B C, algo_sub D A B -> algo_sub D B C -> algo_sub D A C.
      It is used by the Typ_abs case (composing the domain premise
      algo_sub D A2 B1 with the annotation premise algo_sub D B1 A) and,
      more directly, by the Typ_sub case.

   2. Conversion of typing derivations when one type-context binding is
      replaced by a subtype:
        typing_ctx_sub :
          forall D X A1 B1 G e d T,
            TCWell D -> X \notin dom D -> algo_sub D B1 A1 ->
            Typing (cons (X,A1) D) G e d T ->
            Typing (cons (X,B1) D) G e d T.
      This is needed for the Typ_tabs case, where the target S_all rule
      changes the binding of the quantified type variable.

   The file does provide the surrounding ingredients that were needed for
   these: spl_functional, algo_sub_spl_l/r, transport of topLike across a
   changed binding (topLike_ctx_sub), and botLike inversion
   (algo_sub_botLike_gen).  The remaining obstruction for (1) is the
   S_all rule, whose body derivations live under different type contexts
   (cons (X,A1) D) and (cons (X,B1) D); (2) is the same obstruction at
   the level of Typing. *)
End agentE.
Import agentE.

Module dup.
Import ListNotations.

Section Dup.
Variable chk_and_l : forall D G e A B, Typing D G e Chk (t_and A B) -> Typing D G e Chk A.
Variable chk_and_r : forall D G e A B, Typing D G e Chk (t_and A B) -> Typing D G e Chk B.
Variable spl_open : forall A B C X, spl A B C ->
  spl (open_typ_wrt_typ A (t_tvar_f X)) (open_typ_wrt_typ B (t_tvar_f X)) (open_typ_wrt_typ C (t_tvar_f X)).
Variable spl_all_open : forall L A B C,
  (forall X, X \notin L -> spl (open_typ_wrt_typ A (t_tvar_f X)) (open_typ_wrt_typ B (t_tvar_f X)) (open_typ_wrt_typ C (t_tvar_f X))) ->
  forall X, spl (open_typ_wrt_typ A (t_tvar_f X)) (open_typ_wrt_typ B (t_tvar_f X)) (open_typ_wrt_typ C (t_tvar_f X)).

Lemma dup_lc : forall A B, DuplicatedType A B -> lc_typ A /\ lc_typ B.
Proof.
  intros A B H. induction H.
  - split; assumption.
  - destruct IHDuplicatedType1 as [H1a H1c]. destruct IHDuplicatedType2 as [H2b _]. split; [ apply lc_t_and; assumption | assumption ].
  - destruct IHDuplicatedType1 as [H1a H1b]. destruct IHDuplicatedType2 as [H2a H2b]. split; [ apply lc_t_and; assumption | apply lc_t_and; assumption ].
Qed.

Lemma dup_refl : forall A, lc_typ A -> DuplicatedType A A.
Proof. intros. apply DT_refl; assumption. Qed.

Lemma chk_dup : forall B' B, DuplicatedType B' B ->
  forall D G e, Typing D G e Chk B -> Typing D G e Chk B'.
Proof.
  intros B' B Hdt. induction Hdt; intros D0 G0 e0 Hty.
  - exact Hty.
  - apply Typ_inter.
    + apply IHHdt1; exact Hty.
    + apply IHHdt2; exact Hty.
  - apply Typ_inter.
    + apply IHHdt1. apply (chk_and_l D0 G0 e0 A B); exact Hty.
    + apply IHHdt2. apply (chk_and_r D0 G0 e0 A B); exact Hty.
Qed.

Lemma appDist_dup_arrow : forall A' A, DuplicatedType A' A ->
  forall B C, appDist A (t_arrow B C) ->
  exists B' C', appDist A' (t_arrow B' C') /\ DuplicatedType B' B /\ DuplicatedType C' C.
Proof.
  intros A' A H. induction H; intros Bt Ct Happ.
  - exists Bt, Ct. destruct (appDist_lc _ _ Happ) as [Hs Ht].
    apply lc_typ_arrow_inv in Ht as [HB HC].
    split; [ assumption | split; [ apply DT_refl; assumption | apply DT_refl; assumption ] ].
  - destruct (IHDuplicatedType1 Bt Ct Happ) as [ B1 [ C1 [ Ha1 [ Hb1 Hc1 ] ] ] ].
    destruct (IHDuplicatedType2 Bt Ct Happ) as [ B2 [ C2 [ Ha2 [ Hb2 Hc2 ] ] ] ].
    exists (t_and B1 B2), (t_and C1 C2). split; [ apply AD_andArrow; assumption | split; [ apply DT_copy; assumption | apply DT_copy; assumption ] ].
  - inversion Happ; subst.
    destruct (IHDuplicatedType1 _ _ H4) as [ B1' [ C1' [ Ha1 [ Hb1 Hc1 ] ] ] ].
    destruct (IHDuplicatedType2 _ _ H6) as [ B2' [ C2' [ Ha2 [ Hb2 Hc2 ] ] ] ].
    exists (t_and B1' B2'), (t_and C1' C2'). split; [ apply AD_andArrow; assumption | split; [ apply DT_and; assumption | apply DT_and; assumption ] ].
Qed.

Lemma appDist_dup_rcd : forall A' A, DuplicatedType A' A ->
  forall l C, appDist A (t_rcd l C) ->
  exists C', appDist A' (t_rcd l C') /\ DuplicatedType C' C.
Proof.
  intros A' A H. induction H; intros lb Ct Happ.
  - exists Ct. destruct (appDist_lc _ _ Happ) as [Hs Ht].
    apply lc_typ_rcd_inv in Ht as HC.
    split; [ assumption | apply DT_refl; assumption ].
  - destruct (IHDuplicatedType1 lb Ct Happ) as [ C1 [ Ha1 Hc1 ] ].
    destruct (IHDuplicatedType2 lb Ct Happ) as [ C2 [ Ha2 Hc2 ] ].
    exists (t_and C1 C2). split; [ apply AD_andRcd; assumption | apply DT_copy; assumption ].
  - inversion Happ; subst.
    destruct (IHDuplicatedType1 _ _ H4) as [ C1' [ Ha1 Hc1 ] ].
    destruct (IHDuplicatedType2 _ _ H6) as [ C2' [ Ha2 Hc2 ] ].
    exists (t_and C1' C2'). split; [ apply AD_andRcd; assumption | apply DT_and; assumption ].
Qed.

Lemma appDist_dup_all : forall A' A, DuplicatedType A' A ->
  forall C1 C2, appDist A (t_forall C1 C2) ->
  exists C1' C2', appDist A' (t_forall C1' C2') /\ DuplicatedType C1' C1 /\
    (forall X, DuplicatedType (open_typ_wrt_typ C2' (t_tvar_f X)) (open_typ_wrt_typ C2 (t_tvar_f X))).
Proof.
  intros A' A H. induction H; intros Ct1 Ct2 Happ.
  - exists Ct1, Ct2. destruct (appDist_lc _ _ Happ) as [Hs Ht].
    apply lc_typ_forall_inv in Ht as [HC1 HC2].
    split; [ assumption | split; [ apply DT_refl; assumption | intros X; apply DT_refl; apply HC2 ] ].
  - destruct (IHDuplicatedType1 Ct1 Ct2 Happ) as [ X1 [ X2 [ Ha1 [ Hx1 Hx2 ] ] ] ].
    destruct (IHDuplicatedType2 Ct1 Ct2 Happ) as [ Y1 [ Y2 [ Ha2 [ Hy1 Hy2 ] ] ] ].
    exists (t_and X1 Y1), (t_and X2 Y2). split; [ apply AD_andAll; assumption | split; [ apply DT_copy; assumption | intros X; simpl; apply DT_copy; [ apply Hx2 | apply Hy2 ] ] ].
  - inversion Happ; subst.
    destruct (IHDuplicatedType1 _ _ H4) as [ C1' [ D1' [ Ha1 [ Hc1 Hd1 ] ] ] ].
    destruct (IHDuplicatedType2 _ _ H6) as [ C2' [ D2' [ Ha2 [ Hc2 Hd2 ] ] ] ].
    exists (t_and C1' C2'), (t_and D1' D2'). split; [ apply AD_andAll; assumption | split; [ apply DT_and; assumption | intros X; simpl; apply DT_and; [ apply Hd1 | apply Hd2 ] ] ].
Qed.

Lemma DT_TWell : forall D A' A, DuplicatedType A' A -> TWell D A -> TWell D A'.
Proof.
  intros D A' A H. induction H; intros HTA.
  - exact HTA.
  - apply TW_and; [ apply IHDuplicatedType1; assumption | apply IHDuplicatedType2; assumption ].
  - inversion HTA; subst.
    apply TW_and; [ apply IHDuplicatedType1; assumption | apply IHDuplicatedType2; assumption ].
Qed.

Lemma appDist_arrow_inv2 : forall (B1 B2 B C:typ),
  appDist (t_arrow B1 B2) (t_arrow B C) -> B1 = B /\ B2 = C.
Proof. intros B1 B2 B C H. inversion H; subst; auto. Qed.

Lemma appDist_rcd_inv2 : forall (l:label) (B1 B:typ),
  appDist (t_rcd l B1) (t_rcd l B) -> B1 = B.
Proof. intros l B1 B H. inversion H; subst; auto. Qed.

Lemma appDist_rcd_inv3 : forall (l1:label) (B1:typ) (l2:label) (B2:typ),
  appDist (t_rcd l1 B1) (t_rcd l2 B2) -> l1 = l2 /\ B1 = B2.
Proof. intros l1 B1 l2 B2 H. inversion H; subst; auto. Qed.

Lemma appDist_all_inv2 : forall (B1 B2 B C:typ),
  appDist (t_forall B1 B2) (t_forall B C) -> B1 = B /\ B2 = C.
Proof. intros B1 B2 B C H. inversion H; subst; auto. Qed.

Lemma appDist_rcd_not_arrow2 : forall (l:label) (A:typ) (B C:typ), appDist (t_rcd l A) (t_arrow B C) -> False.
Proof. intros. inversion H. Qed.
Lemma appDist_all_not_arrow2 : forall (A1 A2:typ) (B C:typ), appDist (t_forall A1 A2) (t_arrow B C) -> False.
Proof. intros. inversion H. Qed.
Lemma appDist_arrow_not_rcd2 : forall (A1 A2:typ) (l:label) (B:typ), appDist (t_arrow A1 A2) (t_rcd l B) -> False.
Proof. intros. inversion H. Qed.
Lemma appDist_all_not_rcd2 : forall (A1 A2:typ) (l:label) (B:typ), appDist (t_forall A1 A2) (t_rcd l B) -> False.
Proof. intros. inversion H. Qed.
Lemma appDist_arrow_not_all2 : forall (A1 A2:typ) (B1 B2:typ), appDist (t_arrow A1 A2) (t_forall B1 B2) -> False.
Proof. intros. inversion H. Qed.
Lemma appDist_rcd_not_all2 : forall (l:label) (A:typ) (B1 B2:typ), appDist (t_rcd l A) (t_forall B1 B2) -> False.
Proof. intros. inversion H. Qed.

Lemma appDist_subsub_arrow : forall A' A, subsub A' A ->
  forall B C, appDist A (t_arrow B C) ->
  exists B' C', appDist A' (t_arrow B' C') /\ DuplicatedType B' B /\ subsub C' C.
Proof.
  intros A' A Hsub0. induction Hsub0; intros Bt Ct Happ.
  - exists Bt, Ct. destruct (appDist_lc _ _ Happ) as [Hs Ht].
    apply lc_typ_arrow_inv in Ht as [HB HC].
    split; [ assumption | split; [ apply DT_refl; assumption | apply IS_refl; assumption ] ].
  - destruct H as [A0 Bp C1 C2 HlcA Hsub | L A0 Bp C1 C2 HlcA Hbody | lb Bp C1 C2 Hsub | X Y HlcX HlcY].
    + (* Sp_arrow *)
      destruct (spl_lc Bp C1 C2 Hsub) as [ _ [ HC1 HC2 ] ].
      assert (Hlc1 : lc_typ (t_arrow A0 C1)) by (apply lc_t_arrow; assumption).
      assert (Hlc2 : lc_typ (t_arrow A0 C2)) by (apply lc_t_arrow; assumption).
      destruct (appDist_arrow_inv2 A0 Bp Bt Ct Happ) as [EB EC]; subst Bt Ct.
      destruct (IHHsub0_1 A0 C1) as [ Ba1 [ Ca1 [ Ha1 [ Hdt1 Hss1 ] ] ] ];
        [ apply AD_refl; apply Hlc1 | ].
      destruct (IHHsub0_2 A0 C2) as [ Ba2 [ Ca2 [ Ha2 [ Hdt2 Hss2 ] ] ] ];
        [ apply AD_refl; apply Hlc2 | ].
      exists (t_and Ba1 Ba2), (t_and Ca1 Ca2). split; [ apply AD_andArrow; assumption | split; [ apply DT_copy; assumption | apply IS_and with (B := Bp) (B1 := C1) (B2 := C2); assumption ] ].
    + (* Sp_all impossible *)
      exfalso. eapply appDist_all_not_arrow2. exact Happ.
    + (* Sp_rcd impossible *)
      exfalso. eapply appDist_rcd_not_arrow2. exact Happ.
    + (* Sp_and *)
      inversion Happ; subst.
      destruct (appDist_lc _ _ Happ) as [_ Htlc].
      apply lc_typ_arrow_inv in Htlc as [_ Handlc].
      apply lc_typ_and_inv in Handlc as [HC1lc HC2lc].
      destruct (IHHsub0_1 _ _ H2) as [ Ba1 [ Ca1 [ Ha1 [ Hdt1 Hss1 ] ] ] ].
      destruct (IHHsub0_2 _ _ H4) as [ Ba2 [ Ca2 [ Ha2 [ Hdt2 Hss2 ] ] ] ].
      exists (t_and Ba1 Ba2), (t_and Ca1 Ca2). split; [ apply AD_andArrow; assumption | split; [ apply DT_and; assumption | apply IS_and with (B := t_and C1 C2) (B1 := C1) (B2 := C2); [ apply Sp_and; assumption | assumption | assumption ] ] ].
Qed.

Lemma appDist_subsub_rcd : forall A' A, subsub A' A ->
  forall l C, appDist A (t_rcd l C) ->
  exists C', appDist A' (t_rcd l C') /\ subsub C' C.
Proof.
  intros A' A Hsub0. induction Hsub0; intros lb Ct Happ.
  - exists Ct. destruct (appDist_lc _ _ Happ) as [Hs Ht].
    apply lc_typ_rcd_inv in Ht as HC.
    split; [ assumption | apply IS_refl; assumption ].
  - destruct H as [A0 Bp C1 C2 HlcA Hsub | L A0 Bp C1 C2 HlcA Hbody | l0 Bp C1 C2 Hsub | X Y HlcX HlcY].
    + (* Sp_arrow impossible *)
      exfalso. eapply appDist_arrow_not_rcd2. exact Happ.
    + (* Sp_all impossible *)
      exfalso. eapply appDist_all_not_rcd2. exact Happ.
    + (* Sp_rcd *)
      destruct (spl_lc Bp C1 C2 Hsub) as [ _ [ HC1 HC2 ] ].
      destruct (appDist_rcd_inv3 l0 Bp lb Ct Happ) as [El EC]; subst lb Ct.
      destruct (IHHsub0_1 l0 C1) as [ C1' [ Ha1 Hss1 ] ]; [ apply AD_refl; apply lc_t_rcd; apply HC1 | ].
      destruct (IHHsub0_2 l0 C2) as [ C2' [ Ha2 Hss2 ] ]; [ apply AD_refl; apply lc_t_rcd; apply HC2 | ].
      exists (t_and C1' C2'). split; [ apply AD_andRcd; assumption | apply IS_and with (B := Bp) (B1 := C1) (B2 := C2); assumption ].
    + (* Sp_and *)
      inversion Happ; subst.
      destruct (appDist_lc _ _ Happ) as [_ Htlc].
      apply lc_typ_rcd_inv in Htlc as Handlc.
      apply lc_typ_and_inv in Handlc as [HB1 HB2].
      destruct (IHHsub0_1 lb B1) as [ C1' [ Ha1 Hss1 ] ]; [ exact H2 | ].
      destruct (IHHsub0_2 lb B2) as [ C2' [ Ha2 Hss2 ] ]; [ exact H4 | ].
      exists (t_and C1' C2'). split; [ apply AD_andRcd; assumption | apply IS_and with (B := t_and B1 B2) (B1 := B1) (B2 := B2); [ apply Sp_and; assumption | assumption | assumption ] ].
Qed.

Lemma appDist_subsub_all : forall A' A, subsub A' A ->
  forall C1 C2, appDist A (t_forall C1 C2) ->
  exists C1' C2', appDist A' (t_forall C1' C2') /\ DuplicatedType C1' C1 /\
    (forall X, subsub (open_typ_wrt_typ C2' (t_tvar_f X)) (open_typ_wrt_typ C2 (t_tvar_f X))).
Proof.
  intros A' A Hsub0. induction Hsub0; intros Ct1 Ct2 Happ.
  - exists Ct1, Ct2. destruct (appDist_lc _ _ Happ) as [Hs Ht].
    apply lc_typ_forall_inv in Ht as [HC1 HC2].
    split; [ assumption | split; [ apply DT_refl; assumption | intros X; apply IS_refl; apply HC2 ] ].
  - destruct H as [A0 Bp C1 C2 HlcA Hsub | L A0 Bp C1 C2 HlcA Hbody | l0 Bp C1 C2 Hsub | X Y HlcX HlcY].
    + (* Sp_arrow impossible *)
      exfalso. eapply appDist_arrow_not_all2. exact Happ.
    + (* Sp_all *)
      destruct (spl_lc (t_forall A0 Bp) (t_forall A0 C1) (t_forall A0 C2) (Sp_all L A0 Bp C1 C2 HlcA Hbody)) as [ _ [ Hl1 Hl2 ] ].
      destruct (appDist_all_inv2 A0 Bp Ct1 Ct2 Happ) as [E1 E2]; subst Ct1 Ct2.
      destruct (IHHsub0_1 A0 C1) as [ C11 [ C21 [ Ha1 [ Hdt1 Hss1 ] ] ] ]; [ apply AD_refl; apply Hl1 | ].
      destruct (IHHsub0_2 A0 C2) as [ C12 [ C22 [ Ha2 [ Hdt2 Hss2 ] ] ] ]; [ apply AD_refl; apply Hl2 | ].
      exists (t_and C11 C12), (t_and C21 C22). split; [ apply AD_andAll; assumption | split; [ apply DT_copy; assumption | intros Z; simpl; apply IS_and with (B := open_typ_wrt_typ Bp (t_tvar_f Z)) (B1 := open_typ_wrt_typ C1 (t_tvar_f Z)) (B2 := open_typ_wrt_typ C2 (t_tvar_f Z)); [ exact (spl_all_open L Bp C1 C2 Hbody Z) | exact (Hss1 Z) | exact (Hss2 Z) ] ] ].
    + (* Sp_rcd impossible *)
      exfalso. eapply appDist_rcd_not_all2. exact Happ.
    + (* Sp_and *)
      inversion Happ; subst.
      destruct (appDist_lc _ _ Happ) as [_ Htlc].
      apply lc_typ_forall_inv in Htlc as [_ HC2lc].
      destruct (IHHsub0_1 _ _ H2) as [ C11 [ C21 [ Ha1 [ Hdt1 Hss1 ] ] ] ].
      destruct (IHHsub0_2 _ _ H4) as [ C12 [ C22 [ Ha2 [ Hdt2 Hss2 ] ] ] ].
      exists (t_and C11 C12), (t_and C21 C22). split; [ apply AD_andAll; assumption | split; [ apply DT_and; assumption | intros Z; simpl; assert (Hlc : lc_typ (open_typ_wrt_typ (t_and C1 C2) (t_tvar_f Z))) by apply HC2lc; simpl in Hlc; apply lc_typ_and_inv in Hlc as [Hc1 Hc2]; apply IS_and with (B := t_and (open_typ_wrt_typ C1 (t_tvar_f Z)) (open_typ_wrt_typ C2 (t_tvar_f Z))) (B1 := open_typ_wrt_typ C1 (t_tvar_f Z)) (B2 := open_typ_wrt_typ C2 (t_tvar_f Z)); [ apply Sp_and; assumption | exact (Hss1 Z) | exact (Hss2 Z) ] ] ].
Qed.
End Dup.
End dup.
Import dup.

Module splfacts.
Import ListNotations.

Lemma notin_union_l' : forall (x:atom) (s s':atoms), x \notin (s \u s') -> x \notin s.
Proof. intros x s s' H Hin. apply H. rewrite union_iff. left; exact Hin. Qed.
Lemma notin_union_r' : forall (x:atom) (s s':atoms), x \notin (s \u s') -> x \notin s'.
Proof. intros x s s' H Hin. apply H. rewrite union_iff. right; exact Hin. Qed.
Lemma notin_singleton_imp' : forall (x y:atom), y \notin AtomSetImpl.singleton x -> y <> x.
Proof. intros x y H Heq. apply H. rewrite singleton_iff. symmetry; exact Heq. Qed.

Lemma spl_all_open : forall L A B C,
  (forall X, X \notin L -> spl (open_typ_wrt_typ A (t_tvar_f X))
      (open_typ_wrt_typ B (t_tvar_f X)) (open_typ_wrt_typ C (t_tvar_f X))) ->
  forall X, spl (open_typ_wrt_typ A (t_tvar_f X))
      (open_typ_wrt_typ B (t_tvar_f X)) (open_typ_wrt_typ C (t_tvar_f X)).
Proof.
  intros L A B C H X.
  destruct (atom_fresh (L \u ([[A]] \u ([[B]] \u ([[C]] \u AtomSetImpl.singleton X))))) as [Y HY].
  assert (HYL : Y \notin L) by exact (notin_union_l' Y L ([[A]] \u ([[B]] \u ([[C]] \u AtomSetImpl.singleton X))) HY).
  assert (HYA : Y \notin [[A]]) by exact (notin_union_l' Y [[A]] ([[B]] \u ([[C]] \u AtomSetImpl.singleton X)) (notin_union_r' Y L ([[A]] \u ([[B]] \u ([[C]] \u AtomSetImpl.singleton X))) HY)).
  assert (HYB : Y \notin [[B]]) by exact (notin_union_l' Y [[B]] ([[C]] \u AtomSetImpl.singleton X) (notin_union_r' Y [[A]] ([[B]] \u ([[C]] \u AtomSetImpl.singleton X)) (notin_union_r' Y L ([[A]] \u ([[B]] \u ([[C]] \u AtomSetImpl.singleton X))) HY))).
  assert (HYC : Y \notin [[C]]) by exact (notin_union_l' Y [[C]] (AtomSetImpl.singleton X) (notin_union_r' Y [[B]] ([[C]] \u AtomSetImpl.singleton X) (notin_union_r' Y [[A]] ([[B]] \u ([[C]] \u AtomSetImpl.singleton X)) (notin_union_r' Y L ([[A]] \u ([[B]] \u ([[C]] \u AtomSetImpl.singleton X))) HY)))).
  assert (HYX : Y <> X) by exact (notin_singleton_imp' X Y (notin_union_r' Y [[C]] (AtomSetImpl.singleton X) (notin_union_r' Y [[B]] ([[C]] \u AtomSetImpl.singleton X) (notin_union_r' Y [[A]] ([[B]] \u ([[C]] \u AtomSetImpl.singleton X)) (notin_union_r' Y L ([[A]] \u ([[B]] \u ([[C]] \u AtomSetImpl.singleton X))) HY))))).
  pose proof (H Y HYL) as Hs.
  pose proof (spl_ren _ _ _ Hs (rename_var Y X)) as Hren.
  rewrite (ren_typ_open_rename A Y X HYA) in Hren.
  rewrite (ren_typ_open_rename B Y X HYB) in Hren.
  rewrite (ren_typ_open_rename C Y X HYC) in Hren.
  exact Hren.
Qed.
End splfacts.
Import splfacts.

Module agentI.

Import ListNotations.

(* ================================================================== *)
(* 1. topLike is preserved by duplication (DuplicatedType)             *)
(* ================================================================== *)

Lemma topLike_DT : forall D A' A, DuplicatedType A' A -> topLike D A -> topLike D A'.
Proof.
  intros D A' A Hdt. induction Hdt; intros Htop.
  - exact Htop.
  - apply TL_and; [ apply IHHdt1 | apply IHHdt2 ]; exact Htop.
  - apply topLike_and_inv in Htop. destruct Htop as [HA HB].
    apply TL_and; [ apply IHHdt1 | apply IHHdt2 ]; assumption.
Qed.

(* Helper for the [DT_and] case of [disjoint_DT_r]: lifting disjointness
   against a conjunction, when each conjunct is duplicated. *)
Lemma disjoint_dup_and_r : forall D0 A' A B' B,
  DuplicatedType A' A -> DuplicatedType B' B ->
  (forall D X, disjoint D X A -> disjoint D X A') ->
  (forall D X, disjoint D X B -> disjoint D X B') ->
  forall X, disjoint D0 X (t_and A B) -> disjoint D0 X (t_and A' B').
Proof.
  intros D0 A' A B' B HdtA HdtB IHA IHB X Hd.
  destruct (dup_lc A' A HdtA) as [HlcA' HlcA].
  destruct (dup_lc B' B HdtB) as [HlcB' HlcB].
  remember (t_and A B) as BT eqn:EB.
  assert (Hd' : disjoint D0 X BT) by exact Hd.
  clear Hd.
  induction Hd' as
    [ D X0 BT0 HTC HTA HTB Hax
    | D X0 BT0 HTB HtopA
    | D X0 BT0 HTA HtopB
    | D A1 A2 B1 B2 HT1 HT2 Hsub IHsub
    | D l A0 B0 Hsub IHsub
    | L D A1 B1 A2 B2 HT1 HT2 Hbody IHBd
    | D X0 BT0 A0 Hb Hsub
    | D BT0 X0 A0 Hb Hsub
    | D X0 BT0 A1 A2 Hspl Hsub1 IH1 Hsub2 IH2
    | D X0 BT0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2 ].
  - (* D_ax *) subst BT0. inversion Hax.
  - (* D_topl *)
    subst BT0. apply D_topl.
    + apply (DT_TWell D (t_and A' B') (t_and A B)).
      * apply (DT_and A' B' A B); assumption.
      * assumption.
    + assumption.
  - (* D_topr *)
    subst BT0. apply D_topr.
    + assumption.
    + apply (topLike_DT D (t_and A' B') (t_and A B)).
      * apply (DT_and A' B' A B); assumption.
      * assumption.
  - (* D_arrow *) discriminate EB.
  - (* D_rcdEq *) discriminate EB.
  - (* D_all *) discriminate EB.
  - (* D_varl *)
    subst BT0.
    apply D_andr with (B1 := A') (B2 := B').
    + apply Sp_and; assumption.
    + apply IHA. exact (D_varl D X0 A A0 Hb (algo_sub_and_l D A0 A B Hsub)).
    + apply IHB. exact (D_varl D X0 B A0 Hb (algo_sub_and_r D A0 A B Hsub)).
  - (* D_varr *) discriminate EB.
  - (* D_andl *)
    apply (D_andl D X0 (t_and A' B') A1 A2 Hspl).
    + exact (IH1 EB).
    + exact (IH2 EB).
  - (* D_andr *)
    subst BT0. inversion Hspl; subst.
    apply D_andr with (B1 := A') (B2 := B').
    + apply Sp_and; assumption.
    + apply IHA. assumption.
    + apply IHB. assumption.
Qed.

(* ================================================================== *)
(* 2. disjointness is preserved by duplication on the right            *)
(* ================================================================== *)

Lemma disjoint_DT_r : forall D A B B',
  disjoint D A B -> DuplicatedType B' B -> disjoint D A B'.
Proof.
  intros D A B B' Hd Hdt. revert D A Hd.
  induction Hdt as
    [ A0 Hlc
    | A0 B0 C Hdt1 IH1 Hdt2 IH2
    | A0 B0 A1 B1 Hdt1 IH1 Hdt2 IH2 ];
    intros D X Hd.
  - exact Hd.
  - apply D_andr with (B1 := A0) (B2 := B0).
    + apply Sp_and.
      * apply (proj1 (dup_lc A0 C Hdt1)).
      * apply (proj1 (dup_lc B0 C Hdt2)).
    + apply (IH1 D X Hd).
    + apply (IH2 D X Hd).
  - apply (disjoint_dup_and_r D A0 A1 B0 B1 Hdt1 Hdt2 IH1 IH2 X Hd).
Qed.

(* Helper for the [DT_and] case of [disjoint_DT_l], dual to the above. *)
Lemma disjoint_dup_and_l : forall D0 A' A B' B,
  DuplicatedType A' A -> DuplicatedType B' B ->
  (forall D X, disjoint D A X -> disjoint D A' X) ->
  (forall D X, disjoint D B X -> disjoint D B' X) ->
  forall X, disjoint D0 (t_and A B) X -> disjoint D0 (t_and A' B') X.
Proof.
  intros D0 A' A B' B HdtA HdtB IHA IHB X Hd.
  destruct (dup_lc A' A HdtA) as [HlcA' HlcA].
  destruct (dup_lc B' B HdtB) as [HlcB' HlcB].
  remember (t_and A B) as AT eqn:EB.
  assert (Hd' : disjoint D0 AT X) by exact Hd.
  clear Hd.
  induction Hd' as
    [ D A0 BT0 HTC HTA HTB Hax
    | D A0 BT0 HTB HtopA
    | D A0 BT0 HTA HtopB
    | D A1 A2 B1 B2 HT1 HT2 Hsub IHsub
    | D l A0 B0 Hsub IHsub
    | L D A1 B1 A2 B2 HT1 HT2 Hbody IHBd
    | D X0 BT0 A0 Hb Hsub
    | D BT0 X0 A0 Hb Hsub
    | D A0 BT0 A1 A2 Hspl Hsub1 IH1 Hsub2 IH2
    | D A0 BT0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2 ].
  - (* D_ax *) subst A0. inversion Hax.
  - (* D_topl *)
    subst A0. apply D_topl.
    + assumption.
    + apply (topLike_DT D (t_and A' B') (t_and A B)).
      * apply (DT_and A' B' A B); assumption.
      * assumption.
  - (* D_topr *)
    subst A0. apply D_topr.
    + apply (DT_TWell D (t_and A' B') (t_and A B)).
      * apply (DT_and A' B' A B); assumption.
      * assumption.
    + assumption.
  - (* D_arrow *) discriminate EB.
  - (* D_rcdEq *) discriminate EB.
  - (* D_all *) discriminate EB.
  - (* D_varl *) discriminate EB.
  - (* D_varr *)
    subst BT0.
    apply D_andl with (A1 := A') (A2 := B').
    + apply Sp_and; assumption.
    + apply IHA. exact (D_varr D A X0 A0 Hb (algo_sub_and_l D A0 A B Hsub)).
    + apply IHB. exact (D_varr D B X0 A0 Hb (algo_sub_and_r D A0 A B Hsub)).
  - (* D_andl *)
    subst A0. inversion Hspl; subst.
    apply (D_andl D (t_and A' B') BT0 A' B').
    + apply Sp_and; assumption.
    + apply IHA. assumption.
    + apply IHB. assumption.
  - (* D_andr *)
    apply (D_andr D (t_and A' B') BT0 B1 B2 Hspl).
    + apply IH1. exact EB.
    + apply IH2. exact EB.
Qed.

(* ================================================================== *)
(* 3. disjointness is preserved by duplication on the left             *)
(* ================================================================== *)

Lemma disjoint_DT_l : forall D A A' B,
  disjoint D A B -> DuplicatedType A' A -> disjoint D A' B.
Proof.
  intros D A A' B Hd Hdt. revert D B Hd.
  induction Hdt as
    [ A0 Hlc
    | A0 B0 C Hdt1 IH1 Hdt2 IH2
    | A0 B0 A1 B1 Hdt1 IH1 Hdt2 IH2 ];
    intros D X Hd.
  - exact Hd.
  - apply D_andl with (A1 := A0) (A2 := B0).
    + apply Sp_and.
      * apply (proj1 (dup_lc A0 C Hdt1)).
      * apply (proj1 (dup_lc B0 C Hdt2)).
    + apply (IH1 D X Hd).
    + apply (IH2 D X Hd).
  - apply (disjoint_dup_and_l D A0 A1 B0 B1 Hdt1 Hdt2 IH1 IH2 X Hd).
Qed.

(* ================================================================== *)
(* Splitting and (topLike / algo_sub / disjoint_axiom) components      *)
(* ================================================================== *)

Lemma topLike_forall_inv : forall D A B,
  topLike D (t_forall A B) ->
  exists L, forall X, X \notin L ->
    topLike (cons (X, A) D) (open_typ_wrt_typ B (t_tvar_f X)).
Proof.
  intros D A B H. inversion H; subst. eexists; eassumption.
Qed.

Lemma topLike_spl : forall D B B1 B2,
  spl B B1 B2 -> topLike D B -> topLike D B1 /\ topLike D B2.
Proof.
  intros D B B1 B2 Hspl. revert D.
  induction Hspl as
    [ A B C1 C2 HlcA Hsub IHsub
    | L A B C1 C2 HlcA Hbody IHBODY
    | l B C1 C2 Hsub IHsub
    | A B HlcA HlcB ];
    intros D Htop.
  - apply topLike_arrow_inv in Htop. destruct Htop as [HTA HtopB].
    destruct (IHsub D HtopB) as [H1 H2].
    split; apply TL_arrow; assumption.
  - destruct (topLike_forall_inv D A B Htop) as [L0 Hbody0].
    split.
    + apply (TL_all ((L \u L0))).
      intros X HX. destruct (notin_union X L L0 HX) as [HXL HXL0].
      apply (proj1 (IHBODY X HXL (cons (X, A) D) (Hbody0 X HXL0))).
    + apply (TL_all ((L \u L0))).
      intros X HX. destruct (notin_union X L L0 HX) as [HXL HXL0].
      apply (proj2 (IHBODY X HXL (cons (X, A) D) (Hbody0 X HXL0))).
  - apply topLike_rcd_inv in Htop.
    destruct (IHsub D Htop) as [H1 H2].
    split; apply TL_rcd; assumption.
  - apply topLike_and_inv in Htop. destruct Htop as [H1 H2].
    split; assumption.
Qed.

Lemma lc_forall_of_body : forall A B L,
  lc_typ A ->
  (forall X, X \notin L -> lc_typ (open_typ_wrt_typ B (t_tvar_f X))) ->
  lc_typ (t_forall A B).
Proof.
  intros A B L HlcA Hbody.
  apply lc_t_forall; [ assumption | ].
  apply (lc_open_all B L). assumption.
Qed.

Lemma algo_sub_spl : forall D A B,
  algo_sub D A B ->
  forall B1 B2, spl B B1 B2 -> algo_sub D A B1 /\ algo_sub D A B2.
Proof.
  intros D A B H. induction H as
    [ D X HTC HTW
    | D HTC
    | D A0 B0 HTW Hord Htop
    | D A0 HTC HTW Hord
    | D A0 B0 C HTWB Hord Hsub IHsub
    | D A0 B0 C HTWA Hord Hsub IHsub
    | D A1 B1 A2 B2 Hord Hsub1 IH1 Hsub2 IH2
    | L D A1 A2 B1 B2 Hord Hsub1 IH1 Hsub2 IH2
    | D l A0 B0 Hord Hsub IHsub
    | D A0 B0 B1 B2 Hspl0 Hsub1 IH1 Hsub2 IH2 ];
    intros C1 C2 Hspl.
  - (* S_var *) inversion Hspl.
  - (* S_int *) inversion Hspl.
  - (* S_top *) exfalso. exact (spl_not_ord B0 C1 C2 Hspl Hord).
  - (* S_bot *) exfalso. exact (spl_not_ord A0 C1 C2 Hspl Hord).
  - (* S_andl *) exfalso. exact (spl_not_ord C C1 C2 Hspl Hord).
  - (* S_andr *) exfalso. exact (spl_not_ord C C1 C2 Hspl Hord).
  - (* S_arrow *)
    exfalso.
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2].
    exact (spl_not_ord B2 q1 q2 Hsplq Hord).
  - (* S_all *)
    exfalso.
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2].
    destruct (atom_fresh (L \u Lq)) as [X HX].
    destruct (notin_union X L Lq HX) as [HXL HXL0].
    exact (spl_not_ord (open_typ_wrt_typ B2 (t_tvar_f X))
             (open_typ_wrt_typ q1 (t_tvar_f X))
             (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HXL0) (Hord X HXL)).
  - (* S_rcd *)
    exfalso.
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2].
    exact (spl_not_ord B0 q1 q2 Hsplq Hord).
  - (* S_and *)
    destruct (@spl_functional B0 B1 B2 C1 C2 Hspl0 Hspl) as [E1 E2].
    subst C1 C2. split; assumption.
Qed.

Lemma spl_lcA : forall A B C, spl A B C -> lc_typ A.
Proof. intros A B C H. apply (proj1 (spl_lc A B C H)). Qed.
Lemma spl_lcB : forall A B C, spl A B C -> lc_typ B.
Proof. intros A B C H. apply (proj1 (proj2 (spl_lc A B C H))). Qed.
Lemma spl_lcC : forall A B C, spl A B C -> lc_typ C.
Proof. intros A B C H. apply (proj2 (proj2 (spl_lc A B C H))). Qed.

(* Splitting the target of a disjointness axiom keeps an axiom. *)
Lemma disjoint_axiom_spl_r : forall A B B1 B2,
  disjoint_axiom A B -> spl B B1 B2 -> disjoint_axiom A B1.
Proof.
  intros A B B1 B2 Hax. revert B1 B2.
  induction Hax as
    [ A1 A2 Hlc1 Hlc2
    | l A0 HlcA
    | A0 B0 HlcA HlcAll
    | A1 A2 l A0 Hlc1 Hlc2 HlcA
    | A1 A2 A0 B0 Hlc1 Hlc2 HlcA HlcAll
    | l C0 A0 B0 HlcC HlcA HlcAll
    | A1 A2 Hlc1 Hlc2
    | l A0 HlcA
    | A0 B0 HlcA HlcAll
    | l A0 A1 A2 HlcA Hlc1 Hlc2
    | A0 B0 A1 A2 HlcA HlcAll Hlc1 Hlc2
    | A0 B0 l C0 HlcA HlcAll HlcC
    | l1 A0 l2 B0 HlcA HlcB Hneq ];
    intros B1 B2 Hspl.
  - (* Dax_intArrow *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_intArrow; [ assumption | apply (spl_lcB A2 q1 q2 Hsplq) ].
  - (* Dax_intRcd *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_intRcd. apply (spl_lcB A0 q1 q2 Hsplq).
  - (* Dax_intAll *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_intAll; [ assumption | ].
    apply (lc_forall_of_body A0 q1 Lq HlcA).
    intros X HX. apply (spl_lcB (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_arrowRcd *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_arrowRcd; [ assumption | assumption | apply (spl_lcB A0 q1 q2 Hsplq) ].
  - (* Dax_arrowAll *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_arrowAll; [ assumption | assumption | assumption | ].
    apply (lc_forall_of_body A0 q1 Lq HlcA).
    intros X HX. apply (spl_lcB (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_rcdAll *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdAll; [ assumption | assumption | ].
    apply (lc_forall_of_body A0 q1 Lq HlcA).
    intros X HX. apply (spl_lcB (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_arrowInt *) inversion Hspl.
  - (* Dax_rcdInt *) inversion Hspl.
  - (* Dax_allInt *) inversion Hspl.
  - (* Dax_rcdArrow *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdArrow; [ assumption | assumption | apply (spl_lcB A2 q1 q2 Hsplq) ].
  - (* Dax_allArrow *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_allArrow; [ assumption | assumption | assumption | apply (spl_lcB A2 q1 q2 Hsplq) ].
  - (* Dax_allRcd *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_allRcd; [ assumption | assumption | apply (spl_lcB C0 q1 q2 Hsplq) ].
  - (* Dax_rcdNeq *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdNeq; [ assumption | apply (spl_lcB B0 q1 q2 Hsplq) | assumption ].
Qed.

(* Splitting the target of a disjointness axiom, second component. *)
Lemma disjoint_axiom_spl_r2 : forall A B B1 B2,
  disjoint_axiom A B -> spl B B1 B2 -> disjoint_axiom A B2.
Proof.
  intros A B B1 B2 Hax. revert B1 B2.
  induction Hax as
    [ A1 A2 Hlc1 Hlc2
    | l A0 HlcA
    | A0 B0 HlcA HlcAll
    | A1 A2 l A0 Hlc1 Hlc2 HlcA
    | A1 A2 A0 B0 Hlc1 Hlc2 HlcA HlcAll
    | l C0 A0 B0 HlcC HlcA HlcAll
    | A1 A2 Hlc1 Hlc2
    | l A0 HlcA
    | A0 B0 HlcA HlcAll
    | l A0 A1 A2 HlcA Hlc1 Hlc2
    | A0 B0 A1 A2 HlcA HlcAll Hlc1 Hlc2
    | A0 B0 l C0 HlcA HlcAll HlcC
    | l1 A0 l2 B0 HlcA HlcB Hneq ];
    intros B1 B2 Hspl.
  - (* Dax_intArrow *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_intArrow; [ assumption | apply (spl_lcC A2 q1 q2 Hsplq) ].
  - (* Dax_intRcd *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_intRcd. apply (spl_lcC A0 q1 q2 Hsplq).
  - (* Dax_intAll *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_intAll; [ assumption | ].
    apply (lc_forall_of_body A0 q2 Lq HlcA).
    intros X HX. apply (spl_lcC (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_arrowRcd *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_arrowRcd; [ assumption | assumption | apply (spl_lcC A0 q1 q2 Hsplq) ].
  - (* Dax_arrowAll *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_arrowAll; [ assumption | assumption | assumption | ].
    apply (lc_forall_of_body A0 q2 Lq HlcA).
    intros X HX. apply (spl_lcC (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_rcdAll *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdAll; [ assumption | assumption | ].
    apply (lc_forall_of_body A0 q2 Lq HlcA).
    intros X HX. apply (spl_lcC (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_arrowInt *) inversion Hspl.
  - (* Dax_rcdInt *) inversion Hspl.
  - (* Dax_allInt *) inversion Hspl.
  - (* Dax_rcdArrow *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdArrow; [ assumption | assumption | apply (spl_lcC A2 q1 q2 Hsplq) ].
  - (* Dax_allArrow *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_allArrow; [ assumption | assumption | assumption | apply (spl_lcC A2 q1 q2 Hsplq) ].
  - (* Dax_allRcd *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_allRcd; [ assumption | assumption | apply (spl_lcC C0 q1 q2 Hsplq) ].
  - (* Dax_rcdNeq *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdNeq; [ assumption | apply (spl_lcC B0 q1 q2 Hsplq) | assumption ].
Qed.

(* ============================================================ *)
(* Decomposing disjointness along the split (right-hand side)   *)
(* ============================================================ *)

Lemma disjoint_spl_r : forall D A B B1 B2,
  spl B B1 B2 -> disjoint D A B -> disjoint D A B1 /\ disjoint D A B2.
Proof.
  intros D A B B1 B2 Hspl Hd. revert B1 B2 Hspl.
  induction Hd as
    [ D0 A0 B0 Htc HtwA HtwB Hax
    | D0 A0 B0 HtwB Htop
    | D0 A0 B0 HtwA Htop
    | D0 A1 A2 B0_1 B0_2 Htw1 Htw2 Hdd IHd
    | D0 l A0 B0 Hdd IHd
    | L D0 A1 B1 A2 B2 Htw1 Htw2 Hbody IHb
    | D0 X B0 A0 Hb Ha
    | D0 B0 X A0 Hb Ha
    | D0 A0 B0 A1 A2 Hspl0 Hd1 IH1 Hd2 IH2
    | D0 A0 B0 C1 C2 Hspl0 Hd1 IH1 Hd2 IH2 ];
    intros E1 E2 Hsplit.
  - (* D_ax *)
    destruct (agentA.spl_TWell D0 B0 E1 E2 HtwB Hsplit) as [HtwE1 HtwE2].
    split.
    + apply D_ax; [ exact Htc | exact HtwA | exact HtwE1 | apply (disjoint_axiom_spl_r A0 B0 E1 E2 Hax Hsplit) ].
    + apply D_ax; [ exact Htc | exact HtwA | exact HtwE2 | apply (disjoint_axiom_spl_r2 A0 B0 E1 E2 Hax Hsplit) ].
  - (* D_topl *)
    destruct (agentA.spl_TWell D0 B0 E1 E2 HtwB Hsplit) as [HtwE1 HtwE2].
    split; apply D_topl; [ exact HtwE1 | exact Htop | exact HtwE2 | exact Htop ].
  - (* D_topr *)
    destruct (topLike_spl D0 B0 E1 E2 Hsplit Htop) as [Htop1 Htop2].
    split; apply D_topr; [ exact HtwA | exact Htop1 | exact HtwA | exact Htop2 ].
  - (* D_arrow *)
    inversion Hsplit as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    destruct (agentA.spl_TWell D0 (t_arrow B0_1 B0_2) (t_arrow B0_1 q1) (t_arrow B0_1 q2) Htw2 Hsplit) as [HtwE1 HtwE2].
    destruct (IHd q1 q2 Hsplq) as [Hq1 Hq2].
    split.
    + apply D_arrow; [ exact Htw1 | exact HtwE1 | exact Hq1 ].
    + apply D_arrow; [ exact Htw1 | exact HtwE2 | exact Hq2 ].
  - (* D_rcdEq *)
    inversion Hsplit as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    destruct (IHd q1 q2 Hsplq) as [Hq1 Hq2].
    split; [ apply D_rcdEq; exact Hq1 | apply D_rcdEq; exact Hq2 ].
  - (* D_all *)
    inversion Hsplit as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    split.
    + apply (D_all (L \u Lq) D0 A1 B1 A2 q1); [ exact Htw1 | exact Htw2 | ].
      intros X HX. destruct (notin_union X L Lq HX) as [HXL HXLq].
      exact (proj1 (IHb X HXL (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HXLq))).
    + apply (D_all (L \u Lq) D0 A1 B1 A2 q2); [ exact Htw1 | exact Htw2 | ].
      intros X HX. destruct (notin_union X L Lq HX) as [HXL HXLq].
      exact (proj2 (IHb X HXL (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HXLq))).
  - (* D_varl *)
    destruct (algo_sub_spl D0 A0 B0 Ha E1 E2 Hsplit) as [Ha1 Ha2].
    split; [ apply (D_varl D0 X E1 A0 Hb Ha1) | apply (D_varl D0 X E2 A0 Hb Ha2) ].
  - (* D_varr *)
    inversion Hsplit.
  - (* D_andl *)
    destruct (IH1 E1 E2 Hsplit) as [H11 H12].
    destruct (IH2 E1 E2 Hsplit) as [H21 H22].
    split; [ apply (D_andl D0 A0 E1 A1 A2 Hspl0 H11 H21) | apply (D_andl D0 A0 E2 A1 A2 Hspl0 H12 H22) ].
  - (* D_andr *)
    destruct (@spl_functional B0 C1 C2 E1 E2 Hspl0 Hsplit) as [EQ1 EQ2].
    subst E1 E2.
    split; assumption.
Qed.

(* Splitting the source of a disjointness axiom. *)
Lemma disjoint_axiom_spl_l : forall A B A1 A2,
  disjoint_axiom A B -> spl A A1 A2 -> disjoint_axiom A1 B.
Proof.
  intros A B A1 A2 Hax. revert A1 A2.
  induction Hax as
    [ A0_1 A0_2 Hlc1 Hlc2
    | l A0 HlcA
    | A0 B0 HlcA HlcAll
    | A1 A2 l A0 Hlc1 Hlc2 HlcA
    | A1 A2 A0 B0 Hlc1 Hlc2 HlcA HlcAll
    | l C0 A0 B0 HlcC HlcA HlcAll
    | A1 A2 Hlc1 Hlc2
    | l A0 HlcA
    | A0 B0 HlcA HlcAll
    | l A0 A1 A2 HlcA Hlc1 Hlc2
    | A0 B0 A1 A2 HlcA HlcAll Hlc1 Hlc2
    | A0 B0 l C0 HlcA HlcAll HlcC
    | l1 A0 l2 B0 HlcA HlcB Hneq ];
    intros C1 C2 Hspl.
  - (* Dax_intArrow *) inversion Hspl.
  - (* Dax_intRcd *) inversion Hspl.
  - (* Dax_intAll *) inversion Hspl.
  - (* Dax_arrowRcd *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_arrowRcd; [ assumption | apply (spl_lcB A2 q1 q2 Hsplq) | assumption ].
  - (* Dax_arrowAll *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_arrowAll; [ assumption | apply (spl_lcB A2 q1 q2 Hsplq) | assumption | assumption ].
  - (* Dax_rcdAll *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdAll; [ apply (spl_lcB C0 q1 q2 Hsplq) | assumption | assumption ].
  - (* Dax_arrowInt *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_arrowInt; [ assumption | apply (spl_lcB A2 q1 q2 Hsplq) ].
  - (* Dax_rcdInt *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdInt. apply (spl_lcB A0 q1 q2 Hsplq).
  - (* Dax_allInt *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_allInt; [ assumption | ].
    apply (lc_forall_of_body A0 q1 Lq HlcA).
    intros X HX. apply (spl_lcB (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_rcdArrow *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdArrow; [ apply (spl_lcB A0 q1 q2 Hsplq) | assumption | assumption ].
  - (* Dax_allArrow *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_allArrow; [ assumption | | assumption | assumption ].
    apply (lc_forall_of_body A0 q1 Lq HlcA).
    intros X HX. apply (spl_lcB (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_allRcd *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_allRcd; [ assumption | | assumption ].
    apply (lc_forall_of_body A0 q1 Lq HlcA).
    intros X HX. apply (spl_lcB (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_rcdNeq *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdNeq; [ apply (spl_lcB A0 q1 q2 Hsplq) | assumption | assumption ].
Qed.


(* Splitting the source of a disjointness axiom, second component. *)
Lemma disjoint_axiom_spl_l2 : forall A B A1 A2,
  disjoint_axiom A B -> spl A A1 A2 -> disjoint_axiom A2 B.
Proof.
  intros A B A1 A2 Hax. revert A1 A2.
  induction Hax as
    [ A0_1 A0_2 Hlc1 Hlc2
    | l A0 HlcA
    | A0 B0 HlcA HlcAll
    | A1 A2 l A0 Hlc1 Hlc2 HlcA
    | A1 A2 A0 B0 Hlc1 Hlc2 HlcA HlcAll
    | l C0 A0 B0 HlcC HlcA HlcAll
    | A1 A2 Hlc1 Hlc2
    | l A0 HlcA
    | A0 B0 HlcA HlcAll
    | l A0 A1 A2 HlcA Hlc1 Hlc2
    | A0 B0 A1 A2 HlcA HlcAll Hlc1 Hlc2
    | A0 B0 l C0 HlcA HlcAll HlcC
    | l1 A0 l2 B0 HlcA HlcB Hneq ];
    intros C1 C2 Hspl.
  - (* Dax_intArrow *) inversion Hspl.
  - (* Dax_intRcd *) inversion Hspl.
  - (* Dax_intAll *) inversion Hspl.
  - (* Dax_arrowRcd *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_arrowRcd; [ assumption | apply (spl_lcC A2 q1 q2 Hsplq) | assumption ].
  - (* Dax_arrowAll *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_arrowAll; [ assumption | apply (spl_lcC A2 q1 q2 Hsplq) | assumption | assumption ].
  - (* Dax_rcdAll *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdAll; [ apply (spl_lcC C0 q1 q2 Hsplq) | assumption | assumption ].
  - (* Dax_arrowInt *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_arrowInt; [ assumption | apply (spl_lcC A2 q1 q2 Hsplq) ].
  - (* Dax_rcdInt *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdInt. apply (spl_lcC A0 q1 q2 Hsplq).
  - (* Dax_allInt *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_allInt; [ assumption | ].
    apply (lc_forall_of_body A0 q2 Lq HlcA).
    intros X HX. apply (spl_lcC (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_rcdArrow *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdArrow; [ apply (spl_lcC A0 q1 q2 Hsplq) | assumption | assumption ].
  - (* Dax_allArrow *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_allArrow; [ assumption | | assumption | assumption ].
    apply (lc_forall_of_body A0 q2 Lq HlcA).
    intros X HX. apply (spl_lcC (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_allRcd *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_allRcd; [ assumption | | assumption ].
    apply (lc_forall_of_body A0 q2 Lq HlcA).
    intros X HX. apply (spl_lcC (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_rcdNeq *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdNeq; [ apply (spl_lcC A0 q1 q2 Hsplq) | assumption | assumption ].
Qed.

(* ============================================================ *)
(* Decomposing disjointness along the split (left-hand side)    *)
(* ============================================================ *)

Lemma disjoint_spl_l : forall D A A1 A2 B,
  spl A A1 A2 -> disjoint D A B -> disjoint D A1 B /\ disjoint D A2 B.
Proof.
  intros D A A1 A2 B Hspl Hd. revert A1 A2 Hspl.
  induction Hd as
    [ D0 A0 B0 Htc HtwA HtwB Hax
    | D0 A0 B0 HtwB Htop
    | D0 A0 B0 HtwA Htop
    | D0 A1 A2 B1 B2 Htw1 Htw2 Hdd IHd
    | D0 l A0 B0 Hdd IHd
    | L D0 A1 B1 A2 B2 Htw1 Htw2 Hbody IHb
    | D0 X B0 A0 Hb Ha
    | D0 B0 X A0 Hb Ha
    | D0 A0 B0 A1 A2 Hspl0 Hd1 IH1 Hd2 IH2
    | D0 A0 B0 B1 B2 Hspl0 Hd1 IH1 Hd2 IH2 ];
    intros E1 E2 Hsplit.
  - (* D_ax *)
    destruct (agentA.spl_TWell D0 A0 E1 E2 HtwA Hsplit) as [HtwE1 HtwE2].
    split.
    + apply D_ax; [ exact Htc | exact HtwE1 | exact HtwB | apply (disjoint_axiom_spl_l A0 B0 E1 E2 Hax Hsplit) ].
    + apply D_ax; [ exact Htc | exact HtwE2 | exact HtwB | apply (disjoint_axiom_spl_l2 A0 B0 E1 E2 Hax Hsplit) ].
  - (* D_topl *)
    destruct (topLike_spl D0 A0 E1 E2 Hsplit Htop) as [Htop1 Htop2].
    split; apply D_topl; [ exact HtwB | exact Htop1 | exact HtwB | exact Htop2 ].
  - (* D_topr *)
    destruct (agentA.spl_TWell D0 A0 E1 E2 HtwA Hsplit) as [HtwE1 HtwE2].
    split; apply D_topr; [ exact HtwE1 | exact Htop | exact HtwE2 | exact Htop ].
  - (* D_arrow *)
    inversion Hsplit as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    destruct (agentA.spl_TWell D0 (t_arrow A1 A2) (t_arrow A1 q1) (t_arrow A1 q2) Htw1 Hsplit) as [HtwE1 HtwE2].
    destruct (IHd q1 q2 Hsplq) as [Hq1 Hq2].
    split.
    + apply D_arrow; [ exact HtwE1 | exact Htw2 | exact Hq1 ].
    + apply D_arrow; [ exact HtwE2 | exact Htw2 | exact Hq2 ].
  - (* D_rcdEq *)
    inversion Hsplit as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    destruct (IHd q1 q2 Hsplq) as [Hq1 Hq2].
    split; [ apply D_rcdEq; exact Hq1 | apply D_rcdEq; exact Hq2 ].
  - (* D_all *)
    inversion Hsplit as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    split.
    + apply (D_all (L \u Lq) D0 A1 q1 A2 B2); [ exact Htw1 | exact Htw2 | ].
      intros X HX. destruct (notin_union X L Lq HX) as [HXL HXLq].
      exact (proj1 (IHb X HXL (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HXLq))).
    + apply (D_all (L \u Lq) D0 A1 q2 A2 B2); [ exact Htw1 | exact Htw2 | ].
      intros X HX. destruct (notin_union X L Lq HX) as [HXL HXLq].
      exact (proj2 (IHb X HXL (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HXLq))).
  - (* D_varl *)
    inversion Hsplit.
  - (* D_varr *)
    destruct (algo_sub_spl D0 A0 B0 Ha E1 E2 Hsplit) as [Ha1 Ha2].
    split; [ apply (D_varr D0 E1 X A0 Hb Ha1) | apply (D_varr D0 E2 X A0 Hb Ha2) ].
  - (* D_andl *)
    destruct (@spl_functional A0 A1 A2 E1 E2 Hspl0 Hsplit) as [EQ1 EQ2].
    subst E1 E2.
    split; assumption.
  - (* D_andr *)
    destruct (IH1 E1 E2 Hsplit) as [H11 H12].
    destruct (IH2 E1 E2 Hsplit) as [H21 H22].
    split; [ apply (D_andr D0 E1 B0 B1 B2 Hspl0 H11 H21) | apply (D_andr D0 E2 B0 B1 B2 Hspl0 H12 H22) ].
Qed.

(* ============================================================ *)
(* subsub: local closedness and disjointness transfer           *)
(* ============================================================ *)

Lemma subsub_lc : forall A B, subsub A B -> lc_typ A /\ lc_typ B.
Proof.
  intros A B H. induction H as
    [ A0 Hlc
    | A1 A2 B0 B1 B2 Hspl Hss1 IH1 Hss2 IH2 ].
  - split; assumption.
  - destruct (spl_lc B0 B1 B2 Hspl) as [HlcB0 _].
    split.
    + apply lc_t_and; [ apply (proj1 IH1) | apply (proj1 IH2) ].
    + exact HlcB0.
Qed.

Lemma disjoint_subsub_r : forall D A B B',
  disjoint D A B -> subsub B' B -> disjoint D A B'.
Proof.
  intros D A B B' Hd Hss. revert D A Hd.
  induction Hss as
    [ B0 Hlc
    | A1 A2 B0 B1 B2 Hspl Hss1 IH1 Hss2 IH2 ];
    intros D0 X Hd.
  - exact Hd.
  - destruct (disjoint_spl_r D0 X B0 B1 B2 Hspl Hd) as [Hd1 Hd2].
    apply (D_andr D0 X (t_and A1 A2) A1 A2).
    + apply Sp_and; [ apply (proj1 (subsub_lc A1 B1 Hss1)) | apply (proj1 (subsub_lc A2 B2 Hss2)) ].
    + exact (IH1 D0 X Hd1).
    + exact (IH2 D0 X Hd2).
Qed.

Lemma disjoint_subsub_l : forall D A A' B,
  disjoint D A B -> subsub A' A -> disjoint D A' B.
Proof.
  intros D A A' B Hd Hss. revert D B Hd.
  induction Hss as
    [ A0 Hlc
    | A1 A2 B0 B1 B2 Hspl Hss1 IH1 Hss2 IH2 ];
    intros D0 Y Hd.
  - exact Hd.
  - destruct (disjoint_spl_l D0 B0 B1 B2 Y Hspl Hd) as [Hd1 Hd2].
    apply (D_andl D0 (t_and A1 A2) Y A1 A2).
    + apply Sp_and; [ apply (proj1 (subsub_lc A1 B1 Hss1)) | apply (proj1 (subsub_lc A2 B2 Hss2)) ].
    + exact (IH1 D0 Y Hd1).
    + exact (IH2 D0 Y Hd2).
Qed.

(* ============================================================ *)
(* Opening a locally closed type does not change it             *)
(* ============================================================ *)

Lemma disjoint_open : forall D A B X,
  disjoint D A B ->
  disjoint D (open_typ_wrt_typ A (t_tvar_f X)) (open_typ_wrt_typ B (t_tvar_f X)).
Proof.
  intros D A B X Hd.
  destruct (agentA.disjoint_lc D A B Hd) as [HlcA HlcB].
  unfold open_typ_wrt_typ.
  rewrite (agentC.deg_open_identity A 0 0 (t_tvar_f X) (le_n 0) (agentC.lc_typ_deg A HlcA)).
  rewrite (agentC.deg_open_identity B 0 0 (t_tvar_f X) (le_n 0) (agentC.lc_typ_deg B HlcB)).
  exact Hd.
Qed.
End agentI.
Import agentI.

Module agentI2.
Import ListNotations.

(* ==================================================================== *)
(* Free variables of expressions                                        *)
(* ==================================================================== *)

Lemma typing_In_dom : forall (A:Type) (x:atom) (a:A) (E:list (atom*A)),
  In (x,a) E -> AtomSetImpl.In x (dom E).
Proof.
  intros A x a E H. induction E as [|[y b] E IH].
  - inversion H.
  - simpl. inversion H as [HE|HE].
    + inversion HE; subst. apply add_iff. left. reflexivity.
    + apply add_iff. right. apply IH. assumption.
Qed.

Lemma termfv_open_exp_subset : forall k u e x,
  x \in termfv_exp e ->
  x \in termfv_exp (open_exp_wrt_exp_rec k u e).
Proof.
  intros k u e. revert k u.
  induction e as
    [ n | y | | i | A e IH | A e IH | e1 IH1 e2 IH2
    | e1 IH1 e2 IH2 | e IH A | A e IH | e IH l | e IH | e IH A ];
    intros k u x Hx; simpl in *.
  - apply AtomSetProperties.Dec.F.empty_iff in Hx. contradiction.
  - exact Hx.
  - apply AtomSetProperties.Dec.F.empty_iff in Hx. contradiction.
  - apply AtomSetProperties.Dec.F.empty_iff in Hx. contradiction.
  - apply (IH (S k) u x Hx).
  - apply (IH (S k) u x Hx).
  - rewrite union_iff in Hx. destruct Hx as [Hx|Hx].
    + rewrite union_iff. left. apply (IH1 k u x Hx).
    + rewrite union_iff. right. apply (IH2 k u x Hx).
  - rewrite union_iff in Hx. destruct Hx as [Hx|Hx].
    + rewrite union_iff. left. apply (IH1 k u x Hx).
    + rewrite union_iff. right. apply (IH2 k u x Hx).
  - apply (IH k u x Hx).
  - apply (IH k u x Hx).
  - apply (IH k u x Hx).
  - apply (IH k u x Hx).
  - apply (IH k u x Hx).
Qed.

Lemma termfv_exp_open_typ : forall k A e,
  termfv_exp (open_exp_wrt_typ_rec k A e) = termfv_exp e.
Proof.
  intros k A e. revert k A.
  induction e as
    [ n | y | | i | B e IH | B e IH | e1 IH1 e2 IH2
    | e1 IH1 e2 IH2 | e IH B0 | B e IH | e IH l | e IH | e IH B0 ];
    intros k A; simpl.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite IH. reflexivity.
  - rewrite IH. reflexivity.
  - rewrite IH1, IH2. reflexivity.
  - rewrite IH1, IH2. reflexivity.
  - rewrite IH. reflexivity.
  - rewrite IH. reflexivity.
  - rewrite IH. reflexivity.
  - rewrite IH. reflexivity.
  - rewrite IH. reflexivity.
Qed.

(* ==================================================================== *)
(* Context substitution helpers                                         *)
(* ==================================================================== *)

Definition subst_tctx (C:typ) (X:typevar) (D:tctx) : tctx :=
  EnvImpl.map (typsubst_typ C X) D.

Lemma subst_tctx_cons : forall C X Z A D,
  subst_tctx C X (cons (Z,A) D) = cons (Z, typsubst_typ C X A) (subst_tctx C X D).
Proof. intros. reflexivity. Qed.

Lemma dom_subst_tctx : forall C X D,
  dom (subst_tctx C X D) [=] dom D.
Proof. intros. apply dom_map. Qed.

Lemma map_fst_subst_tctx : forall C X D,
  map fst (subst_tctx C X D) = map fst D.
Proof.
  intros C X D. unfold subst_tctx.
  induction D as [|[Z B] D IH]; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma binds_subst_tctx : forall C X D Z A,
  binds Z A D -> binds Z (typsubst_typ C X A) (subst_tctx C X D).
Proof. intros. apply binds_map_2. assumption. Qed.

Lemma notin_dom_cons_neq : forall (D:tctx) Z A Y,
  Y <> Z -> Y \notin dom D -> Y \notin dom (cons (Z,A) D).
Proof.
  intros D Z A Y Hne Hnot Hin.
  simpl in Hin.
  exact (Hnot (AtomSetImpl.add_3 (fun Heq => Hne (eq_sym Heq)) Hin)).
Qed.

Lemma notin_dom_cons_inv : forall (D:tctx) Z A Y,
  Y \notin dom (cons (Z,A) D) -> Y \notin dom D.
Proof.
  intros D Z A Y H Hin. apply H. simpl.
  apply AtomSetImpl.add_2. exact Hin.
Qed.

Lemma binds_cons_neq : forall (D:tctx) Z A Y B,
  Y <> Z -> binds Y B (cons (Z,A) D) -> binds Y B D.
Proof.
  intros D Z A Y B Hne Hb.
  apply binds_cons_1 in Hb.
  destruct Hb as [Heq | Hin].
  - destruct Heq as [HY HB]. subst Y B.
    exfalso. apply Hne. reflexivity.
  - exact Hin.
Qed.

Lemma binds_nil_any : forall (D:tctx) Y B,
  binds Y B nil -> binds Y B D.
Proof.
  intros D Y B Hb. apply binds_nil_iff in Hb. destruct Hb.
Qed.

(* ==================================================================== *)
(* Commutation of type substitution with opening of types               *)
(* ==================================================================== *)

Lemma open_typ_lc_id : forall C, lc_typ C ->
    forall k (A:typ), open_typ_wrt_typ_rec k A C = C.
Proof.
  intros C HC k A.
  exact (deg_open_identity C 0 k A (Nat.le_0_l k) (lc_typ_deg C HC)).
Qed.

Lemma typsubst_open_typ_dep : forall C Y, lc_typ C ->
    forall k (Z:typevar) (B:typ),
      typsubst_typ C Y (open_typ_wrt_typ_rec k (t_tvar_f Z) B) =
      open_typ_wrt_typ_rec k (if eq_var Z Y then C else (t_tvar_f Z))
                              (typsubst_typ C Y B).
Proof.
  intros C Y HC k Z B. revert k.
  induction B as [n|X| | | |B1 IH1 B2 IH2|B1 IH1 B2 IH2|B1 IH1 B2 IH2|l B1 IH1];
    intros k; simpl.
  - destruct (lt_eq_lt_dec n k) as [Hleft|Hgt].
    + destruct Hleft as [Hlt|Heq].
      * reflexivity.
      * subst n. reflexivity.
    + reflexivity.
  - destruct (eq_var X Y) as [Heq|Hne]; simpl.
    + subst X. rewrite open_typ_lc_id; [|exact HC].
      destruct (eq_var Z Y) as [HZY|HnZY]; simpl; reflexivity.
    + destruct (eq_var Z Y) as [HZY|HnZY]; simpl; reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite IH1. rewrite IH2. reflexivity.
  - rewrite IH1. rewrite IH2. reflexivity.
  - rewrite IH1. rewrite IH2. reflexivity.
  - rewrite IH1. reflexivity.
Qed.

Lemma typsubst_open_typ_neq : forall C Y, lc_typ C ->
    forall Z (B:typ), Z <> Y ->
      typsubst_typ C Y (open_typ_wrt_typ B (t_tvar_f Z)) =
      open_typ_wrt_typ (typsubst_typ C Y B) (t_tvar_f Z).
Proof.
  intros C Y HC Z B Hne.
  unfold open_typ_wrt_typ.
  rewrite (typsubst_open_typ_dep C Y HC 0 Z B).
  destruct (eq_var Z Y) as [Heq|Hne']; [exfalso; apply Hne; exact Heq|reflexivity].
Qed.

Lemma typsubst_tvar_same : forall C Y, typsubst_typ C Y (t_tvar_f Y) = C.
Proof.
  intros. simpl.
  destruct (eq_var Y Y) as [Heq|Hne]; [reflexivity|exfalso; apply Hne; reflexivity].
Qed.

Lemma typsubst_tvar_neq : forall C Y Z, Z <> Y ->
    typsubst_typ C Y (t_tvar_f Z) = t_tvar_f Z.
Proof.
  intros. simpl.
  destruct (eq_var Z Y) as [Heq|Hne]; [exfalso; apply H; exact Heq|reflexivity].
Qed.

(* ==================================================================== *)
(* Free variables of a typed expression are in the term context         *)
(* ==================================================================== *)

Lemma typing_termfv : forall D G e d A,
  Typing D G e d A -> forall x, x \in termfv_exp e -> x \in dom G.
Proof.
  intros D G e d A Hty. induction Hty as
    [D G Htc0 Hcw0 Hu0
    |D G i Htc0 Hcw0 Hu0
    |D G z A Htc0 Hcw0 Hb Hu0
    |L D G A e B1 B2 Hsub Hbody IHbody
    |D G e1 e2 C A B Ht1 IH1 Hdist Ht2 IH2
    |L D G e A B Hcw0 Hbody IHbody
    |D G e A C2 B C1 Ht IH Hdist Hdisj
    |D G e l C A Ht IH Hdist
    |D G l e A Ht IH
    |D G e1 e2 A B Ht1 IH1 Ht2 IH2 Hdisj
    |D G e A B Ht1 IH1 Ht2 IH2
    |D G e A Ht IH
    |L D G A e Hbody IHbody
    |D G u1 u2 A B Htc0 Hcw0 Hu0 Ht1 IH1 Ht2 IH2 Hcons
    |D G e B A Ht IH Hsub].
  - (* Typ_top *)
    intros x Hx. simpl in Hx.
    apply AtomSetProperties.Dec.F.empty_iff in Hx. contradiction.
  - (* Typ_lit *)
    intros x Hx. simpl in Hx.
    apply AtomSetProperties.Dec.F.empty_iff in Hx. contradiction.
  - (* Typ_var *)
    intros x Hx. simpl in Hx.
    rewrite singleton_iff in Hx. subst x.
    exact (typing_In_dom typ z A G Hb).
  - (* Typ_abs *)
    intros x Hx. simpl in Hx.
    destruct (atom_fresh (L \u dom G \u termfv_exp e)) as [y Hy].
    destruct (notin_union y L (dom G \u termfv_exp e) Hy) as [HyL HyDrest].
    destruct (notin_union y (dom G) (termfv_exp e) HyDrest) as [HyD HyFV].
    pose proof (IHbody y HyL x (termfv_open_exp_subset 0 (e_var_f y) e x Hx)) as Hdom.
    simpl in Hdom. rewrite add_iff in Hdom.
    destruct Hdom as [Heq|Hin].
    + exfalso. apply HyFV. rewrite <- Heq in Hx. exact Hx.
    + exact Hin.
  - (* Typ_app *)
    intros x Hx. simpl in Hx. rewrite union_iff in Hx.
    destruct Hx as [Hx|Hx].
    + exact (IH1 x Hx).
    + exact (IH2 x Hx).
  - (* Typ_tabs *)
    intros x Hx. simpl in Hx.
    destruct (atom_fresh L) as [X HX].
    apply (IHbody X HX x). unfold open_exp_wrt_typ. rewrite termfv_exp_open_typ. exact Hx.
  - (* Typ_tapp *)
    intros x Hx. simpl in Hx. exact (IH x Hx).
  - (* Typ_proj *)
    intros x Hx. simpl in Hx. exact (IH x Hx).
  - (* Typ_rcd *)
    intros x Hx. simpl in Hx. exact (IH x Hx).
  - (* Typ_merge *)
    intros x Hx. simpl in Hx. rewrite union_iff in Hx.
    destruct Hx as [Hx|Hx].
    + exact (IH1 x Hx).
    + exact (IH2 x Hx).
  - (* Typ_inter *)
    intros x Hx. simpl in Hx.
    exact (IH1 x Hx).
  - (* Typ_anno *)
    intros x Hx. simpl in Hx. exact (IH x Hx).
  - (* Typ_fix *)
    intros x Hx. simpl in Hx.
    destruct (atom_fresh (L \u dom G \u termfv_exp e)) as [y Hy].
    destruct (notin_union y L (dom G \u termfv_exp e) Hy) as [HyL HyDrest].
    destruct (notin_union y (dom G) (termfv_exp e) HyDrest) as [HyD HyFV].
    pose proof (IHbody y HyL x (termfv_open_exp_subset 0 (e_var_f y) e x Hx)) as Hdom.
    simpl in Hdom. rewrite add_iff in Hdom.
    destruct Hdom as [Heq|Hin].
    + exfalso. apply HyFV. rewrite <- Heq in Hx. exact Hx.
    + exact Hin.
  - (* Typ_mergev *)
    intros x Hx. simpl in Hx. rewrite union_iff in Hx.
    destruct Hx as [Hx|Hx].
    + pose proof (IH1 x Hx) as Hnil. simpl in Hnil.
      apply AtomSetProperties.Dec.F.empty_iff in Hnil. contradiction.
    + pose proof (IH2 x Hx) as Hnil. simpl in Hnil.
      apply AtomSetProperties.Dec.F.empty_iff in Hnil. contradiction.
  - (* Typ_sub *)
    intros x Hx. simpl in Hx. exact (IH x Hx).
Qed.

Lemma typing_nil_notin : forall x e d A,
  Typing nil nil e d A -> ~ x \in termfv_exp e.
Proof.
  intros x e d A Hty Hin.
  pose proof (typing_termfv nil nil e d A Hty x Hin) as Hdom.
  simpl in Hdom.
  apply AtomSetProperties.Dec.F.empty_iff in Hdom. exact Hdom.
Qed.

(* ==================================================================== *)
(* Application shape of a well-formed type                              *)
(* ==================================================================== *)

Lemma appDist_TWell : forall D A B,
  TWell D A -> appDist A B -> TWell D B.
Proof.
  intros D A B HTA Hdist. revert HTA.
  induction Hdist as
    [ A1 A2 B1 B2 C1 C2 Hd1 IH1 Hd2 IH2
    | A1 A2 l B1 B2 Hd1 IH1 Hd2 IH2
    | A1 A2 B1 B2 C1 C2 Hd1 IH1 Hd2 IH2
    | A0 Hlc ]; intros HTA.
  - destruct (TWell_and_inv D A1 A2 HTA) as [HTA1 HTA2].
    pose proof (IH1 HTA1) as H1.
    pose proof (IH2 HTA2) as H2.
    destruct (TWell_arrow_inv D B1 C1 H1) as [HB1 HC1].
    destruct (TWell_arrow_inv D B2 C2 H2) as [HB2 HC2].
    apply TW_arrow.
    + apply TW_and; assumption.
    + apply TW_and; assumption.
  - destruct (TWell_and_inv D A1 A2 HTA) as [HTA1 HTA2].
    pose proof (IH1 HTA1) as H1.
    pose proof (IH2 HTA2) as H2.
    apply TW_rcd.
    apply TW_and.
    + exact (TWell_rcd_inv D l B1 H1).
    + exact (TWell_rcd_inv D l B2 H2).
  - destruct (TWell_and_inv D A1 A2 HTA) as [HTA1 HTA2].
    pose proof (IH1 HTA1) as H1.
    pose proof (IH2 HTA2) as H2.
    destruct (TWell_forall_inv D B1 C1 H1) as [L1 Hrest1].
    destruct Hrest1 as [HB1 Hbody1].
    destruct (TWell_forall_inv D B2 C2 H2) as [L2 Hrest2].
    destruct Hrest2 as [HB2 Hbody2].
    apply (TW_all (L1 \u (L2 \u dom D)) D (t_and B1 B2) (t_and C1 C2)).
    + apply TW_and; assumption.
    + intros X HX.
      destruct (notin_union X L1 (L2 \u dom D) HX) as [HXL1 HXrest].
      pose proof (Hbody1 X HXL1) as Hb1.
      assert (Hb1' : TWell (cons (X, t_and B1 B2) D) (open_typ_wrt_typ C1 (t_tvar_f X))).
      { apply (TWell_dom_irrel (cons (X,B1) D) (open_typ_wrt_typ C1 (t_tvar_f X)) Hb1 (cons (X, t_and B1 B2) D)).
        simpl. reflexivity. }
      destruct (notin_union X L2 (dom D) HXrest) as [HXL2 HXD].
      pose proof (Hbody2 X HXL2) as Hb2.
      assert (Hb2' : TWell (cons (X, t_and B1 B2) D) (open_typ_wrt_typ C2 (t_tvar_f X))).
      { apply (TWell_dom_irrel (cons (X,B2) D) (open_typ_wrt_typ C2 (t_tvar_f X)) Hb2 (cons (X, t_and B1 B2) D)).
        simpl. reflexivity. }
      apply TW_and; assumption.
  - exact HTA.
Qed.

(* ==================================================================== *)
(* The left component of a disjointness judgement is well formed        *)
(* ==================================================================== *)

Lemma disjoint_TWell_l : forall D A B,
  TCWell D -> disjoint D A B -> TWell D A.
Proof.
  intros D A B HTC Hd. induction Hd as
    [ D0 A0 B0 Htc0 HTA HTB Hax
    | D0 A0 B0 HTB Htop
    | D0 A0 B0 HTA Htop
    | D0 A1 A2 B1 B2 HT1 HT2 Hdd IHd
    | D0 l A0 B0 Hdd IHd
    | L D0 A1 B1 A2 B2 HTW1 HTW2 Hbody IHb
    | D0 X B0 A0 Hb Ha
    | D0 B0 X A0 Hb Ha
    | D0 A0 B0 A1 A2 Hspl0 Hd1 IH1 Hd2 IH2
    | D0 A0 B0 B1 B2 Hspl0 Hd1 IH1 Hd2 IH2 ].
  - exact HTA.
  - exact (agentA.topLike_TWell D0 A0 Htop).
  - exact HTA.
  - exact HT1.
  - apply TW_rcd. apply IHd. exact HTC.
  - apply (TW_all (L \u dom D0) D0 A1 B1).
    + exact HTW1.
    + intros X HX.
      destruct (notin_union X L (dom D0) HX) as [HXL HXD].
      assert (HUniq0 : uniq D0) by (apply agentA.TCWell_uniq; exact HTC).
      assert (HUniqX : uniq (cons (X, t_and A1 A2) D0)).
      { apply (uniq_cons_3 typ X (t_and A1 A2) D0 HUniq0 HXD). }
      assert (HTCX : TCWell (cons (X, t_and A1 A2) D0)).
      { apply (TCW_cons D0 X (t_and A1 A2) HTC (@TW_and D0 A1 A2 HTW1 HTW2) HUniqX). }
      exact (TWell_dom_irrel ((X, t_and A1 A2) :: D0)
                               (open_typ_wrt_typ B1 (t_tvar_f X))
                               (IHb X HXL HTCX)
                               ((X, A1) :: D0) eq_refl).
  - apply (TW_var D0 X A0). exact Hb.
  - exact (agentA.algo_sub_TWell_target D0 A0 B0 HTC Ha).
  - exact (agentD.spl_TWell D0 A0 A1 A2 Hspl0 (IH1 HTC) (IH2 HTC)).
  - exact (IH1 HTC).
Qed.

(* ==================================================================== *)
(* Type substitution preserves well-formedness                          *)
(* ==================================================================== *)
Lemma binds_app_neq : forall (D:tctx) Y Dom Z A,
  Z <> Y -> binds Z A (D ++ [(Y,Dom)]) -> binds Z A D.
Proof.
  intros D Y Dom Z A Hne Hb.
  apply in_app_or in Hb.
  destruct Hb as [Hin | Hin].
  - exact Hin.
  - simpl in Hin. destruct Hin as [Heq | Hnil].
    + inversion Heq; subst. exfalso. apply Hne. reflexivity.
    + inversion Hnil.
Qed.

Lemma TWell_cons_weaken : forall (D:tctx) A Z B,
  TWell D A -> TWell (cons (Z,B) D) A.
Proof.
  intros D A Z B HT.
  apply (TWell_weaken D (cons (Z,B) D) A HT).
  intros X C Hb. apply binds_cons_3. exact Hb.
Qed.

(* Type substitution preserves well-formedness when the substituted
   type variable is bound at the end of the type context.  The proof
   follows the standard LN style, carrying the decomposition of the
   ambient context as an explicit equality. *)

Lemma TWell_typsubst_end_aux : forall (D0:tctx) A,
  TWell D0 A ->
  forall (Delta:tctx) Y Dom,
  D0 = Delta ++ [(Y,Dom)] ->
  Y \notin dom Delta ->
  forall C, TWell (subst_tctx C Y Delta) C ->
  TWell (subst_tctx C Y Delta) (typsubst_typ C Y A).
Proof.
  intros D0 A HTW. induction HTW as
    [ D1
    | D1
    | D1
    | D1 X A0 Hb
    | D1 l A0 HT IH
    | D1 A0 B0 H1 IH1 H2 IH2
    | D1 A0 B0 H1 IH1 H2 IH2
    | L D1 A0 B0 Hdom IHdom Hbody IHBODY ];
    intros Delta Y Dom HD0 Hfresh C HC.
  - simpl. apply TW_top.
  - simpl. apply TW_bot.
  - simpl. apply TW_int.
  - (* TW_var *)
    simpl. destruct (eq_var X Y) as [Heq|Hne].
    + exact HC.
    + apply (TW_var (subst_tctx C Y Delta) X (typsubst_typ C Y A0)).
      apply (binds_subst_tctx C Y Delta X A0).
      apply (binds_app_neq Delta Y Dom X A0 Hne).
      rewrite <- HD0. exact Hb.
  - (* TW_rcd *)
    simpl. apply TW_rcd. exact (IH Delta Y Dom HD0 Hfresh C HC).
  - (* TW_arrow *)
    simpl. apply TW_arrow.
    + exact (IH1 Delta Y Dom HD0 Hfresh C HC).
    + exact (IH2 Delta Y Dom HD0 Hfresh C HC).
  - (* TW_and *)
    simpl. apply TW_and.
    + exact (IH1 Delta Y Dom HD0 Hfresh C HC).
    + exact (IH2 Delta Y Dom HD0 Hfresh C HC).
  - (* TW_all *)
    assert (HlcC : lc_typ C)
      by (apply (TWell_lc (subst_tctx C Y Delta) C); exact HC).
    apply (TW_all (L \u ({{Y}} \u (dom Delta \u dom (subst_tctx C Y Delta))))
                 (subst_tctx C Y Delta)
                 (typsubst_typ C Y A0) (typsubst_typ C Y B0)).
    + exact (IHdom Delta Y Dom HD0 Hfresh C HC).
    + intros Z HZ.
      pose proof (notin_union Z L ({{Y}} \u (dom Delta \u dom (subst_tctx C Y Delta))) HZ) as HZLrest.
      destruct HZLrest as [HZL HZrest].
      pose proof (notin_union Z {{Y}} (dom Delta \u dom (subst_tctx C Y Delta)) HZrest) as HZsingdd.
      destruct HZsingdd as [HZsing HZdd].
      pose proof (notin_union Z (dom Delta) (dom (subst_tctx C Y Delta)) HZdd) as HZDsub.
      destruct HZDsub as [HZD HZsub].
      assert (HZY : Y <> Z) by (apply (notin_singleton_1 Y Z); exact HZsing).
      assert (HYZ : Z <> Y) by (intro Heq; apply HZY; symmetry; exact Heq).
      assert (Hfresh' : Y \notin dom (cons (Z,A0) Delta)).
      { apply (notin_dom_cons_neq Delta Z A0 Y HZY). exact Hfresh. }
      assert (HC' : TWell (subst_tctx C Y (cons (Z,A0) Delta)) C).
      { change (TWell (cons (Z, typsubst_typ C Y A0) (subst_tctx C Y Delta)) C).
        apply TWell_cons_weaken. exact HC. }
      assert (HeqZ : cons (Z,A0) D1 = (cons (Z,A0) Delta) ++ [(Y,Dom)]).
      { rewrite HD0. reflexivity. }
      pose proof (IHBODY Z HZL (cons (Z,A0) Delta) Y Dom HeqZ Hfresh' C HC') as Hres.
      rewrite (typsubst_open_typ_neq C Y HlcC Z B0 HYZ) in Hres.
      change (TWell (cons (Z, typsubst_typ C Y A0) (subst_tctx C Y Delta))
                    (open_typ_wrt_typ (typsubst_typ C Y B0) (t_tvar_f Z))) in Hres.
      exact Hres.
Qed.

Lemma TWell_typsubst_end : forall (Delta:tctx) Y Dom C A,
  Y \notin dom Delta ->
  TWell (Delta ++ [(Y,Dom)]) A ->
  TWell (subst_tctx C Y Delta) C ->
  TWell (subst_tctx C Y Delta) (typsubst_typ C Y A).
Proof.
  intros Delta Y Dom C A Hfresh HTW HC.
  exact (TWell_typsubst_end_aux (Delta ++ [(Y,Dom)]) A HTW Delta Y Dom eq_refl Hfresh C HC).
Qed.

(* Version with the substituted variable bound at the front of the
   context, which is the form produced by decomposition of a type
   application. *)

Lemma TWell_typsubst_front : forall D X C B,
  X \notin dom D ->
  TWell (cons (X,C) D) B ->
  forall A, TWell D A -> TWell D (typsubst_typ A X B).
Proof.
  intros D X C B Hfresh HTW A HTA.
  assert (Hmap : map fst (subst_tctx A X D) = map fst D)
    by (apply map_fst_subst_tctx).
  assert (HAsub : TWell (subst_tctx A X D) A).
  { exact (TWell_dom_irrel D A HTA (subst_tctx A X D) (eq_sym Hmap)). }
  assert (HTWend : TWell (D ++ [(X,C)]) B).
  { apply (TWell_weaken (cons (X,C) D) (D ++ [(X,C)]) B HTW).
    intros Y Bz Hb.
    apply binds_cons_1 in Hb.
    destruct Hb as [Heq|Hin].
    - destruct Heq as [HY HBz]. subst Y Bz.
      apply in_or_app. right. simpl. left. reflexivity.
    - apply in_or_app. left. exact Hin. }
  pose proof (TWell_typsubst_end D X C A B Hfresh HTWend HAsub) as Hres.
  exact (TWell_dom_irrel (subst_tctx A X D) (typsubst_typ A X B) Hres D Hmap).
Qed.

(* ==================================================================== *)
(* Every typed expression has a well-formed result type                 *)
(* ==================================================================== *)

Lemma typing_TWell_ctx : forall D G e d A,
  Typing D G e d A -> TCWell D -> TWell D A.
Proof.
  intros D G e d A Hty HTC. induction Hty as
    [D G Htc0 Hcw0 Hu0
    |D G i Htc0 Hcw0 Hu0
    |D G z A Htc0 Hcw0 Hb Hu0
    |L D G A e B1 B2 Hsub Hbody IHbody
    |D G e1 e2 C A B Ht1 IH1 Hdist Ht2 IH2
    |L D G e A B Hcw0 Hbody IHbody
    |D G e A C2 B C1 Ht IH Hdist Hdisj
    |D G e l C A Ht IH Hdist
    |D G l e A Ht IH
    |D G e1 e2 A B Ht1 IH1 Ht2 IH2 Hdisj
    |D G e A B Ht1 IH1 Ht2 IH2
    |D G e A Ht IH
    |L D G A e Hbody IHbody
    |D G u1 u2 A B Htc0 Hcw0 Hu0 Ht1 IH1 Ht2 IH2 Hcons
    |D G e B A Ht IH Hsub].
  - (* Typ_top *) apply TW_top.
  - (* Typ_lit *) apply TW_int.
  - (* Typ_var *) exact (agentB.CWell_binds D G Hcw0 z A Hb).
  - (* Typ_abs *)
    apply TW_arrow.
    + exact (agentA.algo_sub_TWell_source D B1 A HTC Hsub).
    + destruct (atom_fresh L) as [x Hx].
      exact (IHbody x Hx HTC).
  - (* Typ_app *)
    destruct (TWell_arrow_inv D B C
                (appDist_TWell D A (t_arrow B C) (IH1 HTC) Hdist)) as [HB HC].
    exact HC.
  - (* Typ_tabs *)
    destruct (atom_fresh (L \u dom D)) as [X HX].
    destruct (notin_union X L (dom D) HX) as [HXL HXD].
    assert (HTCX : TCWell (cons (X,A) D)).
    { exact (proj1 (agentB.typing_env_wf (cons (X,A) D) G
                    (open_exp_wrt_typ e (t_tvar_f X)) Chk
                    (open_typ_wrt_typ B (t_tvar_f X)) (Hbody X HXL))). }
    assert (HTA : TWell D A) by (exact (proj2 (agentB.TCWell_cons_inv D X A HTCX))).
    apply (TW_all (L \u dom D) D A B).
    + exact HTA.
    + intros Y HY.
      destruct (notin_union Y L (dom D) HY) as [HYL HYD].
      assert (HTCY : TCWell (cons (Y,A) D)).
      { exact (proj1 (agentB.typing_env_wf (cons (Y,A) D) G
                      (open_exp_wrt_typ e (t_tvar_f Y)) Chk
                      (open_typ_wrt_typ B (t_tvar_f Y)) (Hbody Y HYL))). }
      exact (IHbody Y HYL HTCY).
  - (* Typ_tapp *)
    pose proof (appDist_TWell D B (t_forall C1 C2) (IH HTC) Hdist) as HTWforall.
    assert (HTA : TWell D A) by (apply (disjoint_TWell_l D A C1 HTC); exact Hdisj).
    destruct (TWell_forall_inv D C1 C2 HTWforall) as [L0 Hrest].
    destruct Hrest as [HC1 Hbodyforall].
    destruct (atom_fresh (L0 \u typefv_typ C2 \u dom D)) as [X HX].
    destruct (notin_union X L0 (typefv_typ C2 \u dom D) HX) as [HXL0 HXrest].
    destruct (notin_union X (typefv_typ C2) (dom D) HXrest) as [HXfv HXD].
    pose proof (Hbodyforall X HXL0) as HbodyTW.
    pose proof (TWell_typsubst_front D X C1
                  (open_typ_wrt_typ C2 (t_tvar_f X)) HXD HbodyTW A HTA) as Hres.
    assert (HlcA : lc_typ A) by (apply (agentA.TWell_lc_typ D A); exact HTA).
    unfold open_typ_wrt_typ in Hres.
    rewrite (agentC.typsubst_open_typ 0 X A C2 HlcA HXfv) in Hres.
    exact Hres.
  - (* Typ_proj *)
    exact (TWell_rcd_inv D l C
             (appDist_TWell D A (t_rcd l C) (IH HTC) Hdist)).
  - (* Typ_rcd *)
    apply TW_rcd. exact (IH HTC).
  - (* Typ_merge *)
    apply TW_and.
    + exact (IH1 HTC).
    + exact (IH2 HTC).
  - (* Typ_inter *)
    apply TW_and.
    + exact (IH1 HTC).
    + exact (IH2 HTC).
  - (* Typ_anno *)
    exact (IH HTC).
  - (* Typ_fix *)
    destruct (atom_fresh L) as [x Hx].
    exact (IHbody x Hx HTC).
  - (* Typ_mergev *)
    assert (HTA : TWell D A).
    { apply (TWell_weaken nil D A (IH1 TCW_empty)).
      intros Z Bz Hb. apply (binds_nil_any D Z Bz). exact Hb. }
    assert (HTB : TWell D B).
    { apply (TWell_weaken nil D B (IH2 TCW_empty)).
      intros Z Bz Hb. apply (binds_nil_any D Z Bz). exact Hb. }
    apply TW_and; assumption.
  - (* Typ_sub *)
    exact (agentA.algo_sub_TWell_target D A B HTC Hsub).
Qed.

Lemma typing_TWell : forall (e:exp) (d:dirflag) (A:typ),
  Typing nil nil e d A -> TWell nil A.
Proof.
  intros e d A Hty.
  exact (typing_TWell_ctx nil nil e d A Hty TCW_empty).
Qed.
End agentI2.
Import agentI2.

Module appdist_uniq.
Import ListNotations.

Lemma appDist_arrow_unique : forall A B C B' C',
  appDist A (t_arrow B C) -> appDist A (t_arrow B' C') -> B = B' /\ C = C'.
Proof.
  intros A. induction A as [n|X| | | |A1 IHA1 A2 IHA2|A1 IHA1 A2 IHA2|A1 IHA1 A2 IHA2|l A1 IHA1];
    intros B C B' C' H1 H2.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - (* arrow *) inversion H1; subst. inversion H2; subst. split; reflexivity.
  - (* and *) inversion H1; subst. inversion H2; subst.
    match goal with
    | H1a : appDist A1 (t_arrow ?X1 ?Y1), H1b : appDist A2 (t_arrow ?X2 ?Y2),
      H2a : appDist A1 (t_arrow ?X1' ?Y1'), H2b : appDist A2 (t_arrow ?X2' ?Y2') |- _ =>
      destruct (IHA1 X1 Y1 X1' Y1' H1a H2a) as [E1 E2];
      destruct (IHA2 X2 Y2 X2' Y2' H1b H2b) as [E3 E4]; subst; split; reflexivity end.
  - (* rcd *) inversion H1.
Qed.

Lemma appDist_rcd_unique : forall A l C l' C',
  appDist A (t_rcd l C) -> appDist A (t_rcd l' C') -> l = l' /\ C = C'.
Proof.
  intros A. induction A as [n|X| | | |A1 IHA1 A2 IHA2|A1 IHA1 A2 IHA2|A1 IHA1 A2 IHA2|l0 A1 IHA1];
    intros l C l' C' H1 H2.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - (* arrow *) inversion H1.
  - (* and *) inversion H1; subst. inversion H2; subst.
    match goal with
    | H1a : appDist A1 (t_rcd ?L1 ?X1), H1b : appDist A2 (t_rcd ?L2 ?X2),
      H2a : appDist A1 (t_rcd ?L1' ?X1'), H2b : appDist A2 (t_rcd ?L2' ?X2') |- _ =>
      destruct (IHA1 L1 X1 L1' X1' H1a H2a) as [E1 E2];
      destruct (IHA2 L2 X2 L2' X2' H1b H2b) as [E3 E4]; subst; split; reflexivity end.
  - (* rcd *) inversion H1; subst. inversion H2; subst. split; reflexivity.
Qed.

Lemma appDist_all_unique : forall A B C B' C',
  appDist A (t_forall B C) -> appDist A (t_forall B' C') -> B = B' /\ C = C'.
Proof.
  intros A. induction A as [n|X| | | |A1 IHA1 A2 IHA2|A1 IHA1 A2 IHA2|A1 IHA1 A2 IHA2|l A1 IHA1];
    intros B C B' C' H1 H2.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - (* forall *) inversion H1; subst. inversion H2; subst. split; reflexivity.
  - (* arrow *) inversion H1.
  - (* and *) inversion H1; subst. inversion H2; subst.
    match goal with
    | H1a : appDist A1 (t_forall ?X1 ?Y1), H1b : appDist A2 (t_forall ?X2 ?Y2),
      H2a : appDist A1 (t_forall ?X1' ?Y1'), H2b : appDist A2 (t_forall ?X2' ?Y2') |- _ =>
      destruct (IHA1 X1 Y1 X1' Y1' H1a H2a) as [E1 E2];
      destruct (IHA2 X2 Y2 X2' Y2' H1b H2b) as [E3 E4]; subst; split; reflexivity end.
  - (* rcd *) inversion H1.
Qed.
End appdist_uniq.
Import appdist_uniq.

Module agentH.
Import ListNotations.

(* ==================================================================== *)
(* Size facts                                                            *)
(* ==================================================================== *)

Lemma size_typ_open_typH : forall (X:typevar) A,
  size_typ (open_typ_wrt_typ A (t_tvar_f X)) = size_typ A.
Proof. intros. unfold open_typ_wrt_typ. apply size_typ_open_typ_tvar. Qed.

Lemma spl_size_ltH : forall A B C, spl A B C ->
  size_typ B < size_typ A /\ size_typ C < size_typ A.
Proof.
  intros A B C H. induction H.
  - (* Sp_arrow *) simpl. split; lia.
  - (* Sp_all *) simpl.
    assert (Hs := H1 (fresh (AtomSetImpl.elements L)) (fresh_notin L)).
    simpl in Hs. rewrite !size_typ_open_typH in Hs.
    split; lia.
  - (* Sp_rcd *) simpl. split; lia.
  - (* Sp_and *) simpl. split; lia.
Qed.

(* ==================================================================== *)
(* Simple inversions                                                     *)
(* ==================================================================== *)

Lemma ord_and_false : forall A B, ~ ord (t_and A B).
Proof. intros A B H. inversion H. Qed.

Lemma spl_and_inv : forall A B C D, spl (t_and A B) C D -> C = A /\ D = B.
Proof. intros A B C D H. inversion H; subst; auto. Qed.

Lemma spl_arrow_inv : forall A B C D, spl (t_arrow A B) C D ->
  exists C' D', C = t_arrow A C' /\ D = t_arrow A D' /\ spl B C' D'.
Proof.
  intros A B C D H. inversion H; subst. eexists; eexists; repeat split; eauto.
Qed.

Lemma spl_rcd_inv : forall l A C D, spl (t_rcd l A) C D ->
  exists C' D', C = t_rcd l C' /\ D = t_rcd l D' /\ spl A C' D'.
Proof.
  intros l A C D H. inversion H; subst. eexists; eexists; repeat split; eauto.
Qed.

(* ==================================================================== *)
(* Coverage: every well-formed type is either ord or splits             *)
(* ==================================================================== *)

Lemma TWell_coverage_TC : forall D A, TCWell D -> TWell D A ->
  ord A \/ (exists B C, spl A B C).
Proof.
  intros D A HTC HT.
  destruct (coverage_gen_aux (size_typ A) D A (le_n _) HTC HT) as [Ho | Hrest].
  - left. exact Ho.
  - destruct Hrest as [Htop | Hs].
    + destruct (ord_dec_TWell D A HT) as [Ho | Hno].
      * left. exact Ho.
      * right. destruct (topLike_not_ord_spl D A Htop Hno) as (C1 & C2 & Hs').
        exists C1, C2. exact Hs'.
    + right. exact Hs.
Qed.

Lemma TWell_coverage_nil : forall A, TWell nil A ->
  ord A \/ (exists B C, spl A B C).
Proof. intros A H. exact (TWell_coverage A H). Qed.

(* Components of a split of a well-formed type are well formed.  The
   corresponding lemma from agentA is shadowed by agentD's lemma of the
   same name, so we restate it here. *)

Lemma TWell_all_bodyH : forall D A B, TWell D (t_forall A B) ->
    exists L, forall X, X \notin L -> TWell (cons (X,A) D) (open_typ_wrt_typ B (t_tvar_f X)).
Proof.
  intros D A B H. inversion H; subst; eauto.
Qed.

Lemma spl_TWell_components : forall D A B C, TWell D A -> spl A B C ->
    TWell D B /\ TWell D C.
Proof.
  intros D A B C HT H. revert D HT.
  induction H as [ A B C1 C2 HA HBp HB
    | L A B C1 C2 HA HBp HB | l B C1 C2 HBp HB | A B HA HB ];
    intros D0 HT0.
  - destruct (TWell_arrow_inv D0 A B HT0) as [HDA HDB].
    destruct (HB D0 HDB) as [HC1 HC2].
    split; apply TW_arrow; assumption.
  - destruct (TWell_all_bodyH D0 A B HT0) as [L0 HB0].
    assert (HDA : TWell D0 A) by (apply (TWell_all_inv D0 A B HT0)).
    split; apply (TW_all (L0 \u L) D0 A).
    + assumption.
    + intros X HX. destruct (notin_union X L0 L HX) as [HX0 HXL].
      destruct (HB X HXL (cons (X,A) D0) (HB0 X HX0)) as [HC1 HC2]. assumption.
    + assumption.
    + intros X HX. destruct (notin_union X L0 L HX) as [HX0 HXL].
      destruct (HB X HXL (cons (X,A) D0) (HB0 X HX0)) as [HC1 HC2]. assumption.
  - pose proof (TWell_rcd_inv D0 l B HT0) as HDB.
    destruct (HB D0 HDB) as [HC1 HC2].
    split; apply TW_rcd; assumption.
  - destruct (TWell_and_inv D0 A B HT0) as [HDA HDB].
    split; assumption.
Qed.

Lemma spl_TWell_nilH : forall A B C,
  TWell nil A -> spl A B C -> TWell nil B /\ TWell nil C.
Proof. intros A B C H Hs. exact (spl_TWell_components nil A B C H Hs). Qed.

(* ==================================================================== *)
(* Lifting a derivation through an extra conjunct on the source          *)
(* ==================================================================== *)

Lemma algo_sub_and_l_ctx : forall D A B C,
  TWell D A -> algo_sub D B C -> algo_sub D (t_and A B) C.
Proof.
  intros D A B C HTA H. revert A HTA.
  induction H as
    [ D0 X HTC HTW
    | D0 HTC
    | D0 A0 B0 HTW Hord Htop
    | D0 A0 HTC HTW Hord
    | D0 A0 B0 C0 HTWB Hord Hsub
    | D0 A0 B0 C0 HTWA Hord Hsub
    | D0 A1 B1 A2 B2 Hord Hsub1 IH1 Hsub2 IH2
    | L D0 A1 A2 B1 B2 Hords Hsub1 IH1 Hbody IHBODY
    | D0 l A0 B0 Hord Hsub
    | D0 A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2 ];
    intros Aextra HTA.
  - (* S_var *) apply (S_andr D0 Aextra (t_tvar_f X) (t_tvar_f X) HTA (O_var X)).
    apply (S_var D0 X HTC HTW).
  - (* S_int *) apply (S_andr D0 Aextra t_int t_int HTA (O_int)).
    apply (S_int D0 HTC).
  - (* S_top *) apply (S_top D0 (t_and Aextra A0) B0 (TW_and D0 Aextra A0 HTA HTW) Hord Htop).
  - (* S_bot *) apply (S_andr D0 Aextra t_bot A0 HTA Hord (S_bot D0 A0 HTC HTW Hord)).
  - (* S_andl *) apply (S_andr D0 Aextra (t_and A0 B0) C0 HTA Hord).
    apply (S_andl D0 A0 B0 C0 HTWB Hord Hsub).
  - (* S_andr *) apply (S_andr D0 Aextra (t_and A0 B0) C0 HTA Hord).
    apply (S_andr D0 A0 B0 C0 HTWA Hord Hsub).
  - (* S_arrow *)
    apply (S_andr D0 Aextra (t_arrow A1 B1) (t_arrow A2 B2) HTA
             (O_arrow A2 B2 (proj1 (algo_sub_lc D0 A2 A1 Hsub1)) Hord)).
    apply (S_arrow D0 A1 B1 A2 B2 Hord Hsub1 Hsub2).
  - (* S_all *)
    apply (S_andr D0 Aextra (t_forall A1 A2) (t_forall B1 B2) HTA
             (O_all L B1 B2 (proj1 (algo_sub_lc D0 B1 A1 Hsub1)) Hords)).
    apply (S_all L D0 A1 A2 B1 B2 Hords Hsub1 Hbody).
  - (* S_rcd *)
    apply (S_andr D0 Aextra (t_rcd l A0) (t_rcd l B0) HTA (O_rcd l B0 Hord)).
    apply (S_rcd D0 l A0 B0 Hord Hsub).
  - (* S_and *) apply (S_and D0 (t_and Aextra A0) B0 B1 B2 Hspl).
    + apply IH1. exact HTA.
    + apply IH2. exact HTA.
Qed.

Lemma algo_sub_and_r_ctx : forall D A B C,
  TWell D A -> algo_sub D B C -> algo_sub D (t_and B A) C.
Proof.
  intros D A B C HTA H. revert A HTA.
  induction H as
    [ D0 X HTC HTW
    | D0 HTC
    | D0 A0 B0 HTW Hord Htop
    | D0 A0 HTC HTW Hord
    | D0 A0 B0 C0 HTWB Hord Hsub
    | D0 A0 B0 C0 HTWA Hord Hsub
    | D0 A1 B1 A2 B2 Hord Hsub1 IH1 Hsub2 IH2
    | L D0 A1 A2 B1 B2 Hords Hsub1 IH1 Hbody IHBODY
    | D0 l A0 B0 Hord Hsub
    | D0 A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2 ];
    intros Aextra HTA.
  - (* S_var *) apply (S_andl D0 (t_tvar_f X) Aextra (t_tvar_f X) HTA (O_var X)).
    apply (S_var D0 X HTC HTW).
  - (* S_int *) apply (S_andl D0 t_int Aextra t_int HTA (O_int)).
    apply (S_int D0 HTC).
  - (* S_top *) apply (S_top D0 (t_and A0 Aextra) B0 (TW_and D0 A0 Aextra HTW HTA) Hord Htop).
  - (* S_bot *) apply (S_andl D0 t_bot Aextra A0 HTA Hord (S_bot D0 A0 HTC HTW Hord)).
  - (* S_andl *) apply (S_andl D0 (t_and A0 B0) Aextra C0 HTA Hord).
    apply (S_andl D0 A0 B0 C0 HTWB Hord Hsub).
  - (* S_andr *) apply (S_andl D0 (t_and A0 B0) Aextra C0 HTA Hord).
    apply (S_andr D0 A0 B0 C0 HTWA Hord Hsub).
  - (* S_arrow *)
    apply (S_andl D0 (t_arrow A1 B1) Aextra (t_arrow A2 B2) HTA
             (O_arrow A2 B2 (proj1 (algo_sub_lc D0 A2 A1 Hsub1)) Hord)).
    apply (S_arrow D0 A1 B1 A2 B2 Hord Hsub1 Hsub2).
  - (* S_all *)
    apply (S_andl D0 (t_forall A1 A2) Aextra (t_forall B1 B2) HTA
             (O_all L B1 B2 (proj1 (algo_sub_lc D0 B1 A1 Hsub1)) Hords)).
    apply (S_all L D0 A1 A2 B1 B2 Hords Hsub1 Hbody).
  - (* S_rcd *)
    apply (S_andl D0 (t_rcd l A0) Aextra (t_rcd l B0) HTA (O_rcd l B0 Hord)).
    apply (S_rcd D0 l A0 B0 Hord Hsub).
  - (* S_and *) apply (S_and D0 (t_and A0 Aextra) B0 B1 B2 Hspl).
    + apply IH1. exact HTA.
    + apply IH2. exact HTA.
Qed.

(* ==================================================================== *)
(* Well-formedness of the source of subsub                              *)
(* ==================================================================== *)

Lemma subsub_TWell : forall D A B, TWell D B -> subsub A B -> TWell D A.
Proof.
  intros D A B HT H. revert HT.
  induction H as [ A0 Hlc
    | A1 A2 B0 B1 B2 Hspl Hss1 IH1 Hss2 IH2 ]; intros HT.
  - exact HT.
  - destruct (spl_TWell_components D B0 B1 B2 HT Hspl) as [HT1 HT2].
    apply TW_and; [apply IH1; exact HT1 | apply IH2; exact HT2].
Qed.

(* ==================================================================== *)
(* botLike facts                                                         *)
(* ==================================================================== *)

Lemma botLike_not_topLike : forall A, botLike A -> forall D, ~ topLike D A.
Proof.
  intros A H. induction H as [| A0 B0 HlcB0 HblA0 IH | A0 B0 HlcA0 HblB0 IH].
  - intros D Ht. inversion Ht.
  - intros D Ht. destruct (topLike_and_inv D A0 B0 Ht) as [HtA _].
    exact (IH D HtA).
  - intros D Ht. destruct (topLike_and_inv D A0 B0 Ht) as [_ HtB].
    exact (IH D HtB).
Qed.

Lemma botLike_down : forall D A B, algo_sub D A B -> botLike B -> botLike A.
Proof.
  intros D A B H. induction H as
    [ D X HTC HT
    | D HTC
    | D A0 B0 HT Hord Htop
    | D A0 HTC HT Hord
    | D A0 B0 C0 HTB Hord Hsub IHsub
    | D A0 B0 C0 HTA Hord Hsub IHsub
    | D A1 B1 A2 B2 Hord Hsub1 IH1 Hsub2 IH2
    | L D A1 A2 B1 B2 Hords Hsub1 IH1 Hbody IHB
    | D l A0 B0 Hord Hsub IH
    | D A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2 ];
    intro Hbl.
  - inversion Hbl.
  - inversion Hbl.
  - exfalso. exact (botLike_not_topLike B0 Hbl D Htop).
  - apply BL_bot.
  - apply (BL_andl A0 B0 (TWell_lc_typ D B0 HTB)). exact (IHsub Hbl).
  - apply (BL_andr A0 B0 (TWell_lc_typ D A0 HTA)). exact (IHsub Hbl).
  - inversion Hbl.
  - inversion Hbl.
  - inversion Hbl.
  - destruct Hbl as [| X Y HlcY HblX | X Y HlcX HblY].
    + exfalso. apply (spl_not_ord t_bot B1 B2 Hspl). apply O_bot.
    + destruct (spl_and_inv X Y B1 B2 Hspl) as [HB1 HB2]. subst.
      exact (IH1 HblX).
    + destruct (spl_and_inv X Y B1 B2 Hspl) as [HB1 HB2]. subst.
      exact (IH2 HblY).
Qed.

(* ==================================================================== *)
(* Transport of topLike across a context morphism that only shrinks     *)
(* binding types (botLike is preserved).                                *)
(* ==================================================================== *)

Lemma topLike_ctx_morph : forall D B, topLike D B ->
  forall D', TCWell D' ->
    map fst D = map fst D' ->
    (forall X A, binds X A D -> exists A', binds X A' D' /\ (botLike A -> botLike A')) ->
    topLike D' B.
Proof.
  intros D B H. induction H as
    [ D0 HTC0
    | D0 A0 B0 H1 IH1 H2 IH2
    | D0 A0 B0 HT H2 IH2
    | D0 l B0 H1 IH1
    | L D0 A0 B0 Hbody IHBODY
    | D0 X A0 HTC0 Hb Hbl ];
    intros D' HTC' Heq Hmap.
  - apply TL_top. exact HTC'.
  - apply TL_and.
    + exact (IH1 D' HTC' Heq Hmap).
    + exact (IH2 D' HTC' Heq Hmap).
  - apply TL_arrow.
    + exact (TWell_dom_irrel D0 A0 HT D' Heq).
    + exact (IH2 D' HTC' Heq Hmap).
  - apply TL_rcd. exact (IH1 D' HTC' Heq Hmap).
  - pose (L' := (L \u dom D0) \u dom D').
    apply (TL_all L' D' A0 B0).
    intros X HX.
    destruct (notin_union X (L \u dom D0) (dom D') HX) as [HX1 HXD'].
    destruct (notin_union X L (dom D0) HX1) as [HXL HXD].
    assert (HbodyX := IHBODY X HXL).
    assert (HTA : TWell D0 A0).
    { apply (topLike_all_dom D0 A0 B0). apply (TL_all L D0 A0 B0). exact Hbody. }
    assert (HTA' : TWell D' A0) by (exact (TWell_dom_irrel D0 A0 HTA D' Heq)).
    assert (HTCcons : TCWell (cons (X, A0) D')).
    { apply TCW_cons.
      - exact HTC'.
      - exact HTA'.
      - apply uniq_cons.
        + apply TCWell_uniq. exact HTC'.
        + exact HXD'. }
    assert (Heqcons : map fst (cons (X, A0) D0) = map fst (cons (X, A0) D')).
    { simpl. rewrite Heq. reflexivity. }
    assert (Hmapcons : forall Y C, binds Y C (cons (X, A0) D0) ->
              exists C', binds Y C' (cons (X, A0) D') /\ (botLike C -> botLike C')).
    { intros Y C Hy. apply binds_cons_1 in Hy.
      destruct Hy as [Hcase | Hin].
      - destruct Hcase as [HY HC]. subst. exists A0. split.
        + apply binds_cons_2; reflexivity.
        + auto.
      - destruct (Hmap Y C Hin) as (A' & Hb' & Himp).
        exists A'. split.
        + apply binds_cons_3. exact Hb'.
        + exact Himp. }
    exact (HbodyX (cons (X, A0) D') HTCcons Heqcons Hmapcons).
  - destruct (Hmap X A0 Hb) as (A' & Hb' & Himp).
    apply (TL_var D' X A'). exact HTC'. exact Hb'. exact (Himp Hbl).
Qed.

(* ==================================================================== *)
(* Transport of algo_sub across the same context morphism               *)
(* ==================================================================== *)

Lemma algo_sub_ctx_morph : forall D A B,
  TCWell D -> algo_sub D A B ->
  forall D', TCWell D' ->
    map fst D = map fst D' ->
    (forall X C, binds X C D -> exists C', binds X C' D' /\ (botLike C -> botLike C')) ->
    algo_sub D' A B.
Proof.
  intros D A B HTC H. induction H as
    [ D0 X HTC0 HT
    | D0 HTC0
    | D0 A0 B0 HT Hord Htop
    | D0 A0 HTC0 HT Hord
    | D0 A0 B0 C0 HTB Hord Hsub IHsub
    | D0 A0 B0 C0 HTA Hord Hsub IHsub
    | D0 A1 B1 A2 B2 Hord Hsub1 IH1 Hsub2 IH2
    | L D0 A1 A2 B1 B2 Hords Hsub1 IH1 Hbody IHB
    | D0 l A0 B0 Hord Hsub IH
    | D0 A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2 ];
    intros D' HTC' Heq Hmap.
  - apply (S_var D' X). exact HTC'.
    exact (TWell_dom_irrel D0 (t_tvar_f X) HT D' Heq).
  - apply (S_int D'). exact HTC'.
  - apply (S_top D' A0 B0).
    + exact (TWell_dom_irrel D0 A0 HT D' Heq).
    + exact Hord.
    + exact (topLike_ctx_morph D0 B0 Htop D' HTC' Heq Hmap).
  - apply (S_bot D' A0). exact HTC'.
    + exact (TWell_dom_irrel D0 A0 HT D' Heq).
    + exact Hord.
  - apply (S_andl D' A0 B0 C0).
    + exact (TWell_dom_irrel D0 B0 HTB D' Heq).
    + exact Hord.
    + exact (IHsub HTC D' HTC' Heq Hmap).
  - apply (S_andr D' A0 B0 C0).
    + exact (TWell_dom_irrel D0 A0 HTA D' Heq).
    + exact Hord.
    + exact (IHsub HTC D' HTC' Heq Hmap).
  - apply (S_arrow D' A1 B1 A2 B2).
    + exact Hord.
    + exact (IH1 HTC D' HTC' Heq Hmap).
    + exact (IH2 HTC D' HTC' Heq Hmap).
  - pose (L' := (L \u dom D0) \u dom D').
    apply (S_all L' D' A1 A2 B1 B2).
    + intros X HX. destruct (notin_union X (L \u dom D0) (dom D') HX) as [HX1 HXD'].
      destruct (notin_union X L (dom D0) HX1) as [HXL HXD].
      exact (Hords X HXL).
    + exact (IH1 HTC D' HTC' Heq Hmap).
    + intros X HX. destruct (notin_union X (L \u dom D0) (dom D') HX) as [HX1 HXD'].
      destruct (notin_union X L (dom D0) HX1) as [HXL HXD].
      assert (HTB1 : TWell D0 B1).
      { exact (algo_sub_TWell_source D0 B1 A1 HTC Hsub1). }
      assert (HTB1' : TWell D' B1).
      { exact (TWell_dom_irrel D0 B1 HTB1 D' Heq). }
      assert (HTCcons : TCWell (cons (X, B1) D0)).
      { apply TCW_cons.
        - exact HTC.
        - exact HTB1.
        - apply uniq_cons.
          + apply TCWell_uniq. exact HTC.
          + exact HXD. }
      assert (HTCcons' : TCWell (cons (X, B1) D')).
      { apply TCW_cons.
        - exact HTC'.
        - exact HTB1'.
        - apply uniq_cons.
          + apply TCWell_uniq. exact HTC'.
          + exact HXD'. }
      assert (Heqcons : map fst (cons (X, B1) D0) = map fst (cons (X, B1) D')).
      { simpl. rewrite Heq. reflexivity. }
      assert (Hmapcons : forall Y C, binds Y C (cons (X, B1) D0) ->
                exists C', binds Y C' (cons (X, B1) D') /\ (botLike C -> botLike C')).
      { intros Y C Hy. apply binds_cons_1 in Hy.
        destruct Hy as [Hcase | Hin].
        - destruct Hcase as [HY HC]. subst. exists B1. split.
          + apply binds_cons_2; reflexivity.
          + auto.
        - destruct (Hmap Y C Hin) as (C' & Hb' & Himp).
          exists C'. split.
          + apply binds_cons_3. exact Hb'.
          + exact Himp. }
      exact (IHB X HXL HTCcons (cons (X, B1) D') HTCcons' Heqcons Hmapcons).
  - apply (S_rcd D' l A0 B0).
    + exact Hord.
    + exact (IH HTC D' HTC' Heq Hmap).
  - apply (S_and D' A0 B0 B1 B2 Hspl).
    + exact (IH1 HTC D' HTC' Heq Hmap).
    + exact (IH2 HTC D' HTC' Heq Hmap).
Qed.

(* ==================================================================== *)
(* Congruences (right-hand side) for arrows and records                 *)
(* ==================================================================== *)

Lemma algo_sub_arrow_congr : forall n D A B C,
  size_typ C <= n -> TCWell D -> lc_typ A -> algo_sub D A A ->
  algo_sub D B C -> algo_sub D (t_arrow A B) (t_arrow A C).
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D A B C Hle HTC HlcA Hrefl H.
  destruct (ord_dec_TWell D C (algo_sub_TWell_target D B C HTC H)) as [Hord | Hno].
  - apply (S_arrow D A B A C Hord Hrefl H).
  - destruct (TWell_coverage_TC D C HTC (algo_sub_TWell_target D B C HTC H))
      as [Ho | (C1 & C2 & Hs)].
    + exfalso. apply Hno. exact Ho.
    + apply (S_and D (t_arrow A B) (t_arrow A C) (t_arrow A C1) (t_arrow A C2)).
      * apply (Sp_arrow A C C1 C2 HlcA Hs).
      * assert (Hlt : size_typ C1 < n) by (pose proof (proj1 (spl_size_ltH C C1 C2 Hs)); lia).
        exact (IH (size_typ C1) Hlt D A B C1 (le_n _) HTC HlcA Hrefl
                 (algo_sub_spl_l D B C C1 C2 H Hs)).
      * assert (Hlt : size_typ C2 < n) by (pose proof (proj2 (spl_size_ltH C C1 C2 Hs)); lia).
        exact (IH (size_typ C2) Hlt D A B C2 (le_n _) HTC HlcA Hrefl
                 (algo_sub_spl_r D B C C1 C2 H Hs)).
Qed.

Lemma algo_sub_rcd_congr : forall n D l B C,
  size_typ C <= n -> TCWell D -> algo_sub D B C ->
  algo_sub D (t_rcd l B) (t_rcd l C).
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D l B C Hle HTC H.
  destruct (ord_dec_TWell D C (algo_sub_TWell_target D B C HTC H)) as [Hord | Hno].
  - apply (S_rcd D l B C Hord H).
  - destruct (TWell_coverage_TC D C HTC (algo_sub_TWell_target D B C HTC H))
      as [Ho | (C1 & C2 & Hs)].
    + exfalso. apply Hno. exact Ho.
    + apply (S_and D (t_rcd l B) (t_rcd l C) (t_rcd l C1) (t_rcd l C2)).
      * apply (Sp_rcd l C C1 C2 Hs).
      * assert (Hlt : size_typ C1 < n) by (pose proof (proj1 (spl_size_ltH C C1 C2 Hs)); lia).
        exact (IH (size_typ C1) Hlt D l B C1 (le_n _) HTC
                 (algo_sub_spl_l D B C C1 C2 H Hs)).
      * assert (Hlt : size_typ C2 < n) by (pose proof (proj2 (spl_size_ltH C C1 C2 Hs)); lia).
        exact (IH (size_typ C2) Hlt D l B C2 (le_n _) HTC
                 (algo_sub_spl_r D B C C1 C2 H Hs)).
Qed.

Lemma spl_all_invH : forall A B C D,
  spl (t_forall A B) C D ->
  exists L C1 C2, C = t_forall A C1 /\ D = t_forall A C2 /\
    (forall X, X \notin L -> spl (B -^ X) (C1 -^ X) (C2 -^ X)).
Proof.
  intros A B C D H. inversion H; subst.
  match goal with
  | Hbody : forall X, X \notin ?L0 -> spl (B -^ X) (?C1 -^ X) (?C2 -^ X) |- _ =>
      exists L0, C1, C2; repeat split; try reflexivity; intros X HX;
      exact (Hbody X HX)
  end.
Qed.

Lemma size_typ_spl_lt_inv : forall B C1 C2 L,
  (forall X, X \notin L -> spl (B -^ X) (C1 -^ X) (C2 -^ X)) ->
  size_typ C1 < size_typ B /\ size_typ C2 < size_typ B.
Proof.
  intros B C1 C2 L Hspl.
  pose (X0 := fresh (AtomSetImpl.elements L)).
  assert (HX0 : X0 \notin L) by (unfold X0; apply fresh_notin).
  pose proof (spl_size_ltH (B -^ X0) (C1 -^ X0) (C2 -^ X0) (Hspl X0 HX0)).
  rewrite !size_typ_open_typH in H. exact H.
Qed.

Lemma algo_sub_all_congr : forall n D A B C Lh,
  size_typ (t_forall A C) <= n -> TCWell D -> lc_typ A ->
  algo_sub D A A -> TWell D (t_forall A C) ->
  (forall X, X \notin Lh -> algo_sub (cons (X, A) D)
        (open_typ_wrt_typ B (t_tvar_f X)) (open_typ_wrt_typ C (t_tvar_f X))) ->
  algo_sub D (t_forall A B) (t_forall A C).
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D A B C Lh Hle HTC HlcA Hrefl HTW Hbody.
  destruct (ord_dec_TWell D (t_forall A C) HTW) as [Hord | Hno].
  - apply (S_all (Lh \u dom D) D A B A C).
    + intros X HX. exact (proj2 (ord_all_inv A C Hord) X).
    + exact Hrefl.
    + intros X HX. destruct (notin_union X Lh (dom D) HX) as [HXLh _].
      exact (Hbody X HXLh).
  - destruct (TWell_coverage_TC D (t_forall A C) HTC HTW) as [Ho | (C1 & C2 & Hs)].
    + exfalso. apply Hno. exact Ho.
    + destruct (spl_all_invH A C C1 C2 Hs) as (Ls & C1' & C2' & HC1 & HC2 & Hspl).
      subst C1 C2.
      assert (HTWA : TWell D A) by (exact (TWell_all_inv D A C HTW)).
      destruct (TWell_all_body D A C HTW) as (L0 & HTWbody).
      assert (HTW1 : TWell D (t_forall A C1')).
      { apply (TW_all (Ls \u L0 \u dom D) D A).
        - exact HTWA.
        - intros X HX. destruct (notin_union X Ls (L0 \u dom D) HX) as [HXs HX0].
          destruct (notin_union X L0 (dom D) HX0) as [HX0' _].
          exact (proj1 (spl_TWell_components (cons (X, A) D)
                 (C -^ X) (C1' -^ X) (C2' -^ X)
                 (HTWbody X HX0') (Hspl X HXs))). }
      assert (HTW2 : TWell D (t_forall A C2')).
      { apply (TW_all (Ls \u L0 \u dom D) D A).
        - exact HTWA.
        - intros X HX. destruct (notin_union X Ls (L0 \u dom D) HX) as [HXs HX0].
          destruct (notin_union X L0 (dom D) HX0) as [HX0' _].
          exact (proj2 (spl_TWell_components (cons (X, A) D)
                 (C -^ X) (C1' -^ X) (C2' -^ X)
                 (HTWbody X HX0') (Hspl X HXs))). }
      apply (S_and D (t_forall A B) (t_forall A C)
               (t_forall A C1') (t_forall A C2')).
      * apply (Sp_all Ls A C C1' C2' HlcA Hspl).
      * assert (Hlt : size_typ (t_forall A C1') < n).
        { simpl. simpl in Hle.
          pose proof (proj1 (size_typ_spl_lt_inv C C1' C2' Ls Hspl)). lia. }
        apply (IH (size_typ (t_forall A C1')) Hlt D A B C1' (Lh \u Ls)).
        -- apply le_n.
        -- exact HTC.
        -- exact HlcA.
        -- exact Hrefl.
        -- exact HTW1.
        -- intros X HX. destruct (notin_union X Lh Ls HX) as [HXLh HXLs].
           exact (algo_sub_spl_l ((X, A) :: D) (B -^ X) (C -^ X) (C1' -^ X) (C2' -^ X)
                    (Hbody X HXLh) (Hspl X HXLs)).
      * assert (Hlt : size_typ (t_forall A C2') < n).
        { simpl. simpl in Hle.
          pose proof (proj2 (size_typ_spl_lt_inv C C1' C2' Ls Hspl)). lia. }
        apply (IH (size_typ (t_forall A C2')) Hlt D A B C2' (Lh \u Ls)).
        -- apply le_n.
        -- exact HTC.
        -- exact HlcA.
        -- exact Hrefl.
        -- exact HTW2.
        -- intros X HX. destruct (notin_union X Lh Ls HX) as [HXLh HXLs].
           exact (algo_sub_spl_r ((X, A) :: D) (B -^ X) (C -^ X) (C1' -^ X) (C2' -^ X)
                    (Hbody X HXLh) (Hspl X HXLs)).
Qed.

(* ==================================================================== *)
(* Reflexivity and split subtyping                                       *)
(* ==================================================================== *)

Lemma algo_sub_spl_refl_aux : forall n A,
  size_typ A <= n ->
  (forall D B C, TCWell D -> TWell D A -> spl A B C ->
     algo_sub D A B /\ algo_sub D A C) /\
  (forall D, TCWell D -> TWell D A -> algo_sub D A A).
Proof.
  intros n. induction n as [n IH] using lt_wf_ind.
  intros A HA.
  assert (Hsplit : forall D B C, TCWell D -> TWell D A -> spl A B C ->
     algo_sub D A B /\ algo_sub D A C).
  { (* splitting *)
    intros D B C HTC HTA Hspl.
    revert HTA. induction Hspl as
      [ A0 B0 C1 C2 HlcA0 Hspl0
      | L A0 B0 C1 C2 HlcA0 Hspl0
      | l B0 C1 C2 Hspl0
      | A0 B0 HlcA0 HlcB0 ];
      intros HTA.
    + (* Sp_arrow *)
      destruct (TWell_arrow_inv D A0 B0 HTA) as [HTA0 HTB0].
      assert (HAs : size_typ A0 < n) by (simpl in HA; lia).
      assert (HBs : size_typ B0 < n) by (simpl in HA; lia).
      destruct (IH (size_typ A0) HAs A0 (le_n _)) as [HSA0 HPA0].
      destruct (IH (size_typ B0) HBs B0 (le_n _)) as [HSB0 _].
      destruct (HSB0 D C1 C2 HTC HTB0 Hspl0) as [HBC1 HBC2].
      assert (HC1n : size_typ C1 <= n) by
        (pose proof (proj1 (spl_size_ltH B0 C1 C2 Hspl0)); lia).
      assert (HC2n : size_typ C2 <= n) by
        (pose proof (proj2 (spl_size_ltH B0 C1 C2 Hspl0)); lia).
      split.
      * apply (algo_sub_arrow_congr n D A0 B0 C1 HC1n HTC
                 (TWell_lc_typ D A0 HTA0) (HPA0 D HTC HTA0) HBC1).
      * apply (algo_sub_arrow_congr n D A0 B0 C2 HC2n HTC
                 (TWell_lc_typ D A0 HTA0) (HPA0 D HTC HTA0) HBC2).
    + (* Sp_all *)
      assert (HAs : size_typ A0 < n) by (simpl in HA; lia).
      assert (HBs : size_typ B0 < n) by (simpl in HA; lia).
      assert (HTA0 : TWell D A0) by
        (exact (TWell_all_inv D A0 B0 HTA)).
      destruct (IH (size_typ A0) HAs A0 (le_n _)) as [HSA0 HPA0].
      destruct (TWell_all_bodyH D A0 B0 HTA) as (Lbody & HTWbody).
      assert (HTWf1 : TWell D (t_forall A0 C1)) by
        (apply (proj1 (spl_TWell_components D (t_forall A0 B0)
          (t_forall A0 C1) (t_forall A0 C2) HTA
          (Sp_all L A0 B0 C1 C2 HlcA0 Hspl0)))).
      assert (HTWf2 : TWell D (t_forall A0 C2)) by
        (apply (proj2 (spl_TWell_components D (t_forall A0 B0)
          (t_forall A0 C1) (t_forall A0 C2) HTA
          (Sp_all L A0 B0 C1 C2 HlcA0 Hspl0)))).
      assert (HC1lt : size_typ C1 < size_typ B0) by
        (exact (proj1 (size_typ_spl_lt_inv B0 C1 C2 L Hspl0))).
      assert (HC2lt : size_typ C2 < size_typ B0) by
        (exact (proj2 (size_typ_spl_lt_inv B0 C1 C2 L Hspl0))).
      assert (Hsz1 : size_typ (t_forall A0 C1) <= n) by (simpl; simpl in HA; lia).
      assert (Hsz2 : size_typ (t_forall A0 C2) <= n) by (simpl; simpl in HA; lia).
      split.
      * apply (algo_sub_all_congr n D A0 B0 C1 (L \u Lbody \u dom D)
                 Hsz1 HTC HlcA0 (HPA0 D HTC HTA0) HTWf1).
        intros X HX.
        destruct (notin_union X L (Lbody \u dom D) HX) as [HXL HXrest].
        destruct (notin_union X Lbody (dom D) HXrest) as [HXbody HXD].
        assert (HTCcons : TCWell (cons (X, A0) D)).
        { apply (TCW_cons D X A0 HTC HTA0). apply uniq_cons.
          - apply (TCWell_uniq D HTC).
          - exact HXD. }
        assert (HszBx : size_typ (B0 -^ X) < n).
        { rewrite size_typ_open_typH. simpl in HA. lia. }
        destruct (IH (size_typ (B0 -^ X)) HszBx (B0 -^ X) (le_n _))
          as [HSBx _].
        destruct (HSBx (cons (X, A0) D) (C1 -^ X) (C2 -^ X) HTCcons
                  (HTWbody X HXbody) (Hspl0 X HXL)) as [HB1 _].
        exact HB1.
      * apply (algo_sub_all_congr n D A0 B0 C2 (L \u Lbody \u dom D)
                 Hsz2 HTC HlcA0 (HPA0 D HTC HTA0) HTWf2).
        intros X HX.
        destruct (notin_union X L (Lbody \u dom D) HX) as [HXL HXrest].
        destruct (notin_union X Lbody (dom D) HXrest) as [HXbody HXD].
        assert (HTCcons : TCWell (cons (X, A0) D)).
        { apply (TCW_cons D X A0 HTC HTA0). apply uniq_cons.
          - apply (TCWell_uniq D HTC).
          - exact HXD. }
        assert (HszBx : size_typ (B0 -^ X) < n).
        { rewrite size_typ_open_typH. simpl in HA. lia. }
        destruct (IH (size_typ (B0 -^ X)) HszBx (B0 -^ X) (le_n _))
          as [HSBx _].
        destruct (HSBx (cons (X, A0) D) (C1 -^ X) (C2 -^ X) HTCcons
                  (HTWbody X HXbody) (Hspl0 X HXL)) as [_ HB2].
        exact HB2.
    + (* Sp_rcd *)
      pose proof (TWell_rcd_inv D l B0 HTA) as HTB0.
      assert (HBs : size_typ B0 < n) by (simpl in HA; lia).
      destruct (IH (size_typ B0) HBs B0 (le_n _)) as [HSB0 _].
      destruct (HSB0 D C1 C2 HTC HTB0 Hspl0) as [HBC1 HBC2].
      assert (HC1n : size_typ C1 <= n) by
        (pose proof (proj1 (spl_size_ltH B0 C1 C2 Hspl0)); lia).
      assert (HC2n : size_typ C2 <= n) by
        (pose proof (proj2 (spl_size_ltH B0 C1 C2 Hspl0)); lia).
      split.
      * apply (algo_sub_rcd_congr n D l B0 C1 HC1n HTC HBC1).
      * apply (algo_sub_rcd_congr n D l B0 C2 HC2n HTC HBC2).
    + (* Sp_and *)
      destruct (TWell_and_inv D A0 B0 HTA) as [HTA0 HTB0].
      assert (HAs : size_typ A0 < n) by (simpl in HA; lia).
      assert (HBs : size_typ B0 < n) by (simpl in HA; lia).
      destruct (IH (size_typ A0) HAs A0 (le_n _)) as [HSA0 HPA0].
      destruct (IH (size_typ B0) HBs B0 (le_n _)) as [HSB0 HPB0].
      split.
      * (* component A0 *)
        destruct (ord_dec_TWell D A0 HTA0) as [HordA0 | HnoA0].
        -- apply (S_andl D A0 B0 A0 HTB0 HordA0 (HPA0 D HTC HTA0)).
        -- destruct (TWell_coverage_TC D A0 HTC HTA0) as [Ho | (A1 & A2 & HsplA)].
           ++ exfalso. apply HnoA0. exact Ho.
           ++ destruct (HSA0 D A1 A2 HTC HTA0 HsplA) as [HA1 HA2].
              apply (S_and D (t_and A0 B0) A0 A1 A2 HsplA).
              ** apply (algo_sub_and_r_ctx D B0 A0 A1 HTB0 HA1).
              ** apply (algo_sub_and_r_ctx D B0 A0 A2 HTB0 HA2).
      * (* component B0 *)
        destruct (ord_dec_TWell D B0 HTB0) as [HordB0 | HnoB0].
        -- apply (S_andr D A0 B0 B0 HTA0 HordB0 (HPB0 D HTC HTB0)).
        -- destruct (TWell_coverage_TC D B0 HTC HTB0) as [Ho | (B1 & B2 & HsplB)].
           ++ exfalso. apply HnoB0. exact Ho.
           ++ destruct (HSB0 D B1 B2 HTC HTB0 HsplB) as [HB1 HB2].
              apply (S_and D (t_and A0 B0) B0 B1 B2 HsplB).
              ** apply (algo_sub_and_l_ctx D A0 B0 B1 HTA0 HB1).
              ** apply (algo_sub_and_l_ctx D A0 B0 B2 HTA0 HB2).
  }
  split.
  - exact Hsplit.
  - (* reflexivity *)
    intros D HTC HTA.
    destruct (ord_dec_TWell D A HTA) as [Hord | Hno].
    + destruct A as [n0 | X | | | | A0 B0 | A0 B0 | A0 B0 | l A0].
      * inversion HTA.
      * apply (S_var D X HTC HTA).
      * apply (S_int D HTC).
      * apply (S_top D t_top t_top HTA O_top (TL_top D HTC)).
      * apply (S_bot D t_bot HTC HTA O_bot).
      * (* t_forall *)
        assert (HAs : size_typ A0 < n) by (simpl in HA; lia).
        assert (HBs : size_typ B0 < n) by (simpl in HA; lia).
        destruct (IH (size_typ A0) HAs A0 (le_n _)) as [_ HPA0].
        destruct (TWell_all_bodyH D A0 B0 HTA) as (Lbody & HTWbody).
        apply (S_all (Lbody \u dom D) D A0 B0 A0 B0).
        -- intros X HX. exact (proj2 (ord_all_inv A0 B0 Hord) X).
        -- exact (HPA0 D HTC (TWell_all_inv D A0 B0 HTA)).
        -- intros X HX.
           destruct (notin_union X Lbody (dom D) HX) as [HXbody HXD].
           assert (HTCcons : TCWell (cons (X, A0) D)).
           { apply (TCW_cons D X A0 HTC (TWell_all_inv D A0 B0 HTA)).
             apply uniq_cons.
             - apply (TCWell_uniq D HTC).
             - exact HXD. }
           assert (HszBx : size_typ (B0 -^ X) < n).
           { rewrite size_typ_open_typH. simpl in HA. lia. }
           destruct (IH (size_typ (B0 -^ X)) HszBx (B0 -^ X) (le_n _))
             as [_ HPBx].
           exact (HPBx (cons (X, A0) D) HTCcons (HTWbody X HXbody)).
      * (* t_arrow *)
        destruct (ord_arrow_inv A0 B0 Hord) as [HlcA0 HordB0].
        assert (HAs : size_typ A0 < n) by (simpl in HA; lia).
        assert (HBs : size_typ B0 < n) by (simpl in HA; lia).
        destruct (IH (size_typ A0) HAs A0 (le_n _)) as [_ HPA0].
        destruct (IH (size_typ B0) HBs B0 (le_n _)) as [_ HPB0].
        destruct (TWell_arrow_inv D A0 B0 HTA) as [HTA0 HTB0].
        apply (S_arrow D A0 B0 A0 B0 HordB0 (HPA0 D HTC HTA0) (HPB0 D HTC HTB0)).
      * (* t_and *) exfalso. exact (ord_and_false A0 B0 Hord).
      * (* t_rcd *)
        pose proof (ord_rcd_inv l A0 Hord) as HordA0.
        assert (HAs : size_typ A0 < n) by (simpl in HA; lia).
        destruct (IH (size_typ A0) HAs A0 (le_n _)) as [_ HPA0].
        pose proof (TWell_rcd_inv D l A0 HTA) as HTA0.
        apply (S_rcd D l A0 A0 HordA0 (HPA0 D HTC HTA0)).
    + destruct (TWell_coverage_TC D A HTC HTA) as [Ho | (B0 & C0 & Hspl)].
      * exfalso. apply Hno. exact Ho.
      * destruct (Hsplit D B0 C0 HTC HTA Hspl) as [H1 H2].
        exact (S_and D A A B0 C0 Hspl H1 H2).
Qed.

Theorem algo_sub_refl_TWell : forall D A,
  TCWell D -> TWell D A -> algo_sub D A A.
Proof.
  intros D A HTC HTA.
  exact (proj2 (algo_sub_spl_refl_aux (size_typ A) A (le_n _)) D HTC HTA).
Qed.

Theorem algo_sub_refl_nil : forall A, TWell nil A -> algo_sub nil A A.
Proof.
  intros A HTA. exact (algo_sub_refl_TWell nil A TCW_empty HTA).
Qed.

Theorem spl_algo_sub_l : forall D A B C,
  TCWell D -> TWell D A -> spl A B C -> algo_sub D A B.
Proof.
  intros D A B C HTC HTA Hs.
  exact (proj1 ((proj1 (algo_sub_spl_refl_aux (size_typ A) A (le_n _)))
          D B C HTC HTA Hs)).
Qed.

Theorem spl_algo_sub_r : forall D A B C,
  TCWell D -> TWell D A -> spl A B C -> algo_sub D A C.
Proof.
  intros D A B C HTC HTA Hs.
  exact (proj2 ((proj1 (algo_sub_spl_refl_aux (size_typ A) A (le_n _)))
          D B C HTC HTA Hs)).
Qed.

(* ==================================================================== *)
(* From the subsub relation to algorithmic subtyping                     *)
(* ==================================================================== *)

Theorem subsub_algo_sub : forall D A B,
  TCWell D -> TWell D B -> subsub A B -> algo_sub D A B.
Proof.
  intros D A B HTC HTB Hsub. revert D HTC HTB.
  induction Hsub as [ A0 Hlc
                   | A1 A2 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2 ];
    intros D HTC HTB.
  - (* IS_refl *) exact (algo_sub_refl_TWell D A0 HTC HTB).
  - (* IS_and *)
    assert (HTWand : TWell D (t_and A1 A2)) by
      (exact (subsub_TWell D (t_and A1 A2) B0 HTB
               (IS_and A1 A2 B0 B1 B2 Hspl Hsub1 Hsub2))).
    destruct (TWell_and_inv D A1 A2 HTWand) as [HTA1 HTA2].
    destruct (spl_TWell_components D B0 B1 B2 HTB Hspl) as [HTB1 HTB2].
    assert (H1 : algo_sub D A1 B1) by (exact (IH1 D HTC HTB1)).
    assert (H2 : algo_sub D A2 B2) by (exact (IH2 D HTC HTB2)).
    apply (S_and D (t_and A1 A2) B0 B1 B2 Hspl).
    + exact (algo_sub_and_r_ctx D A2 A1 B1 HTA2 H1).
    + exact (algo_sub_and_l_ctx D A1 A2 B2 HTA1 H2).
Qed.

Lemma topLike_all_body_invH : forall D A B, topLike D (t_forall A B) ->
  exists L, forall X, X \notin L -> topLike (cons (X, A) D) (B -^ X).
Proof.
  intros D A B H. inversion H; subst. eauto.
Qed.

Lemma spl_topLike_sourceH : forall B B1 B2, spl B B1 B2 ->
  forall D, topLike D B1 -> topLike D B2 -> topLike D B.
Proof.
  intros B B1 B2 Hs. induction Hs as
    [ A0 P C1 C2 Hlc Hsp IHsp
    | L A0 P C1 C2 Hlc Hbody IHBODY
    | l P C1 C2 Hsp IHsp
    | A0 P HlcA HlcB ];
    intros D HT1 HT2.
  - destruct (topLike_arrow_inv D A0 C1 HT1) as [HTWA HTC1].
    destruct (topLike_arrow_inv D A0 C2 HT2) as [_ HTC2].
    apply (TL_arrow D A0 P HTWA).
    exact (IHsp D HTC1 HTC2).
  - destruct (topLike_all_body_invH D A0 C1 HT1) as [L1 Hb1].
    destruct (topLike_all_body_invH D A0 C2 HT2) as [L2 Hb2].
    apply (TL_all (((L \u L1) \u L2) \u dom D) D A0 P).
    intros X HX.
    destruct (notin_union X ((L \u L1) \u L2) (dom D) HX) as [HX123 HXD].
    destruct (notin_union X (L \u L1) L2 HX123) as [HX12 HXL2].
    destruct (notin_union X L L1 HX12) as [HXL HXL1].
    exact (IHBODY X HXL (cons (X, A0) D) (Hb1 X HXL1) (Hb2 X HXL2)).
  - apply (TL_rcd D l P).
    apply (IHsp D).
    + exact (topLike_rcd_inv D l C1 HT1).
    + exact (topLike_rcd_inv D l C2 HT2).
  - apply (TL_and D A0 P); assumption.
Qed.

Lemma algo_sub_topLike_genH : forall D0 A B, algo_sub D0 A B -> topLike D0 A -> topLike D0 B.
Proof.
  intros D0 A B H. induction H as
    [ D0 X HTC0 HTW
    | D0 HTC0
    | D0 A0 B0 HTW Hord Htop
    | D0 A0 HTC0 HTW Hord
    | D0 A0 B0 C0 HTWB Hord Hsub IHsub
    | D0 A0 B0 C0 HTWA Hord Hsub IHsub
    | D0 A1 B1 A2 B2 Hord Hsub1 IH1 Hsub2 IH2
    | L D0 A1 A2 B1 B2 Hords Hsub1 IH1 Hbody IHB
    | D0 l A0 B0 Hord Hsub IH
    | D0 A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2 ];
    intro HT.
  - exact HT.
  - exfalso. exact (topLike_t_int_false D0 HT).
  - exact Htop.
  - exfalso. exact (topLike_t_bot_false D0 HT).
  - exact (IHsub (proj1 (topLike_and_inv D0 A0 B0 HT))).
  - exact (IHsub (proj2 (topLike_and_inv D0 A0 B0 HT))).
  - destruct (topLike_arrow_inv D0 A1 B1 HT) as [HTWA1 HTLB1].
    apply (TL_arrow D0 A2 B2).
    + exact (algo_sub_TWell_source D0 A2 A1
               (topLike_TCWell D0 (t_arrow A1 B1) HT) Hsub1).
    + exact (IH2 HTLB1).
  - destruct (topLike_all_body_invH D0 A1 A2 HT) as [LL Hb0].
    assert (HTC : TCWell D0) by
      (apply (topLike_TCWell D0 (t_forall A1 A2)); exact HT).
    assert (HTB1 : TWell D0 B1) by
      (apply (algo_sub_TWell_source D0 B1 A1); [exact HTC | exact Hsub1]).
    apply (TL_all ((L \u dom D0) \u LL) D0 B1 B2).
    intros X HX.
    destruct (notin_union X (L \u dom D0) LL HX) as [HX1 HXL0].
    destruct (notin_union X L (dom D0) HX1) as [HXL HXD].
    assert (HTbody : topLike (cons (X,A1) D0) (A2 -^ X))
      by (exact (Hb0 X HXL0)).
    assert (HTC' : TCWell (cons (X,B1) D0)).
    { apply (TCW_cons D0 X B1 HTC HTB1).
      apply uniq_cons.
      - apply (TCWell_uniq D0 HTC).
      - exact HXD. }
    assert (Hmap : map fst (cons (X,A1) D0) = map fst (cons (X,B1) D0))
      by (simpl; reflexivity).
    assert (R : forall Y C, binds Y C (cons (X,A1) D0) ->
               exists C', binds Y C' (cons (X,B1) D0) /\ (botLike C -> botLike C')).
    { intros Y C Hb. apply binds_cons_1 in Hb. destruct Hb as [Hx | Hin].
      - destruct Hx as [HY HC]. subst. exists B1. split;
          [ apply binds_cons_2; reflexivity
          | intro Hbl; exact (algo_sub_botLike_gen D0 B1 A1 Hsub1 Hbl) ].
      - exists C. split; [ apply binds_cons_3; exact Hin | intro Hbl; exact Hbl ]. }
    assert (HTbody' : topLike (cons (X,B1) D0) (A2 -^ X)).
    { exact (topLike_ctx_morph (cons (X,A1) D0) (A2 -^ X)
               HTbody (cons (X,B1) D0) HTC' Hmap R). }
    exact (IHB X HXL HTbody').
  - apply (TL_rcd D0 l B0). exact (IH (topLike_rcd_inv D0 l A0 HT)).
  - apply (spl_topLike_sourceH B0 B1 B2 Hspl D0).
    + exact (IH1 HT).
    + exact (IH2 HT).
Qed.

(* Inversions of algorithmic subtyping with a fixed-shaped source and an
   ordinal target. *)

Lemma algo_sub_ord_arrow_target : forall D X Y C,
  ord C -> algo_sub D (t_arrow X Y) C ->
  topLike D C \/
  (exists A2 B2, C = t_arrow A2 B2 /\ algo_sub D A2 X /\
     algo_sub D Y B2 /\ ord B2).
Proof.
  intros D X Y C Hord H.
  inversion H as
    [ D0 X0 HTC0 HTW
    | D0 HTC0
    | D0 A0 B0 HTW HordB0 Htop
    | D0 A0 HTC0 HTW HordA0
    | D0 A0 B0 C0 HTWB HordC0 Hsub
    | D0 A0 B0 C0 HTWA HordC0 Hsub
    | D0 A1 B1 A2 B2 HordB2 Hsub1 Hsub2
    | L D0 A1 A2 B1 B2 Hords Hsub1 Hbody
    | D0 l A0 B0 HordB0 Hsub
    | D0 A0 B0 B1 B2 Hspl Hsub1 Hsub2 ].
  - (* S_top *) left. assumption.
  - (* S_arrow *) right. exists A2, B2. repeat split; eauto.
  - (* S_and *) exfalso. eapply spl_not_ord; eassumption.
Qed.

Lemma algo_sub_ord_forall_target : forall D X Y C,
  ord C -> algo_sub D (t_forall X Y) C ->
  topLike D C \/
  (exists L A2 B2, C = t_forall A2 B2 /\ algo_sub D A2 X /\
     (forall Z, Z \notin L -> algo_sub (cons (Z,A2) D) (Y -^ Z) (B2 -^ Z)) /\
     (forall Z, Z \notin L -> ord (B2 -^ Z))).
Proof.
  intros D X Y C Hord H.
  inversion H as
    [ D0 X0 HTC0 HTW
    | D0 HTC0
    | D0 A0 B0 HTW HordB0 Htop
    | D0 A0 HTC0 HTW HordA0
    | D0 A0 B0 C0 HTWB HordC0 Hsub
    | D0 A0 B0 C0 HTWA HordC0 Hsub
    | D0 A1 B1 A2 B2 HordB2 Hsub1 Hsub2
    | L D0 A1 A2 B1 B2 Hords Hsub1 Hbody
    | D0 l A0 B0 HordB0 Hsub
    | D0 A0 B0 B1 B2 Hspl Hsub1 Hsub2 ].
  - (* S_top *) left. assumption.
  - (* S_all *) right. exists L, B1, B2. repeat split; eauto.
  - (* S_and *) exfalso. eapply spl_not_ord; eassumption.
Qed.

Lemma algo_sub_ord_rcd_target : forall D l X C,
  ord C -> algo_sub D (t_rcd l X) C ->
  topLike D C \/
  (exists B2, C = t_rcd l B2 /\ algo_sub D X B2 /\ ord B2).
Proof.
  intros D l X C Hord H.
  inversion H as
    [ D0 X0 HTC0 HTW
    | D0 HTC0
    | D0 A0 B0 HTW HordB0 Htop
    | D0 A0 HTC0 HTW HordA0
    | D0 A0 B0 C0 HTWB HordC0 Hsub
    | D0 A0 B0 C0 HTWA HordC0 Hsub
    | D0 A1 B1 A2 B2 HordB2 Hsub1 Hsub2
    | L D0 A1 A2 B1 B2 Hords Hsub1 Hbody
    | D0 l0 A0 B0 HordB0 Hsub
    | D0 A0 B0 B1 B2 Hspl Hsub1 Hsub2 ].
  - (* S_top *) left. assumption.
  - (* S_rcd *) right. exists B0. repeat split; eauto.
  - (* S_and *) exfalso. eapply spl_not_ord; eassumption.
Qed.

Lemma algo_sub_ord_and_source : forall D X Y C,
  TCWell D -> TWell D (t_and X Y) -> ord C ->
  algo_sub D (t_and X Y) C ->
  (algo_sub D X C /\ TWell D Y) \/ (algo_sub D Y C /\ TWell D X).
Proof.
  intros D X Y C HTC HTW Hord H.
  inversion H as
    [ D0 X0 HTC0 HTW0
    | D0 HTC0
    | D0 A0 B0 HTW0 HordB0 Htop
    | D0 A0 HTC0 HTW0 HordA0
    | D0 A0 B0 C0 HTWB HordC0 Hsub
    | D0 A0 B0 C0 HTWA HordC0 Hsub
    | D0 A1 B1 A2 B2 HordB2 Hsub1 Hsub2
    | L D0 A1 A2 B1 B2 Hords Hsub1 Hbody
    | D0 l A0 B0 HordB0 Hsub
    | D0 A0 B0 B1 B2 Hspl Hsub1 Hsub2 ].
  - (* S_top *) destruct (TWell_and_inv D X Y HTW) as [HTX HTY].
    left. split.
    + exact (S_top D X C HTX Hord Htop).
    + exact HTY.
  - (* S_andl *) left. split; assumption.
  - (* S_andr *) right. split; assumption.
  - (* S_and: target split contradiction *) exfalso.
    exact (spl_not_ord C B1 B2 Hspl Hord).
Qed.


(* ==================================================================== *)
(* Status of algorithmic-subtyping transitivity                          *)
(* ==================================================================== *)

(* The target

     algo_sub_trans_TWell :
       forall D A B C,
         TCWell D -> TWell D A -> TWell D B -> TWell D C ->
         algo_sub D A B -> algo_sub D B C -> algo_sub D A C

   is not proved in this file.  The intended route is a strong induction
   on size_typ A + size_typ B + size_typ C (the proof attempt is kept in
   ttrans.v).  The case analysis reduces the problem to the following
   case, where the first derivation ends in

     S_and D A0 B0 B1 B2 Hspl Hsub1 Hsub2

   and the second derivation targets an ordinal type C, with Hspl being
   an Sp_all split:

     Hspl : spl (t_forall X Y) (t_forall X Z1) (t_forall X Z2)
     HsplY : forall W, W \notin Ls -> spl (Y -^ W) (Z1 -^ W) (Z2 -^ W)
     H2    : algo_sub D (t_forall X Y) C
     HordC : ord C

   Inverting H2 (it can only be S_top or S_all) leaves the S_all case
   C = t_forall A3 B3 with

     Hdom : algo_sub D A3 X
     Hb2  : forall W, W \notin L2 -> algo_sub (cons (W,A3) D)
                                        (Y -^ W) (B3 -^ W)
     Hords: forall W, W \notin L2 -> ord (B3 -^ W).

   To finish through the first component B1 = t_forall X Z1 one must
   build

     algosub D (t_forall X Z1) (t_forall A3 B3)

   with S_all, i.e. for every W prove

     algosub (cons (W,A3) D) (Z1 -^ W) (B3 -^ W).

   Pointwise this follows from HsplY W, Hb2 W and HordC by the missing
   lemma

     spl_algo_sub_or :
       forall D Y Z1 Z2 C,
         spl Y Z1 Z2 -> algo_sub D Y C -> ord C ->
         algo_sub D Z1 C \/ algo_sub D Z2 C,

   whose proof for Sp_arrow/Sp_rcd/Sp_and splits is structural, but for
   the Sp_all split only gives a W-dependent disjunct.  A single S_all
   derivation needs one fixed component (Z1 or Z2) to work for all W.
   Resolving this requires a capture-avoiding renaming lemma for
   algorithmic subtyping derivations (algo_sub_ren with ren_ctx), so
   that a choice made at one fresh W can be transported to every other
   W; this is the same S_all/context obstruction recorded in agentE.v.
   No axiom or classical reasoning is used to bridge this gap here. *)
End agentH.
Import agentH.

Module agentH2.
Import ListNotations.

Lemma ren_ctx_id : forall D, ren_ctx (fun X : typevar => X) D = D.
Proof.
  induction D as [|[Y B] D IH]; simpl.
  - reflexivity.
  - rewrite IH. rewrite (ren_typ_id B (fun X : typevar => X)).
    + reflexivity.
    + intros X HX. reflexivity.
Qed.


(* ==================================================================== *)
(* topLike is preserved by algorithmic subtyping                         *)
(* ==================================================================== *)

Lemma topLike_all_body_invH : forall D A B, topLike D (t_forall A B) ->
  exists L, forall X, X \notin L -> topLike (cons (X, A) D) (B -^ X).
Proof.
  intros D A B H. inversion H; subst. eauto.
Qed.

Lemma spl_topLike_sourceH : forall B B1 B2, spl B B1 B2 ->
  forall D, topLike D B1 -> topLike D B2 -> topLike D B.
Proof.
  intros B B1 B2 Hs. induction Hs as
    [ A0 P C1 C2 Hlc Hsp IHsp
    | L A0 P C1 C2 Hlc Hbody IHBODY
    | l P C1 C2 Hsp IHsp
    | A0 P HlcA HlcB ];
    intros D HT1 HT2.
  - destruct (topLike_arrow_inv D A0 C1 HT1) as [HTWA HTC1].
    destruct (topLike_arrow_inv D A0 C2 HT2) as [_ HTC2].
    apply (TL_arrow D A0 P HTWA).
    exact (IHsp D HTC1 HTC2).
  - destruct (topLike_all_body_invH D A0 C1 HT1) as [L1 Hb1].
    destruct (topLike_all_body_invH D A0 C2 HT2) as [L2 Hb2].
    apply (TL_all (((L \u L1) \u L2) \u dom D) D A0 P).
    intros X HX.
    destruct (notin_union X ((L \u L1) \u L2) (dom D) HX) as [HX123 HXD].
    destruct (notin_union X (L \u L1) L2 HX123) as [HX12 HXL2].
    destruct (notin_union X L L1 HX12) as [HXL HXL1].
    exact (IHBODY X HXL (cons (X, A0) D) (Hb1 X HXL1) (Hb2 X HXL2)).
  - apply (TL_rcd D l P).
    apply (IHsp D).
    + exact (topLike_rcd_inv D l C1 HT1).
    + exact (topLike_rcd_inv D l C2 HT2).
  - apply (TL_and D A0 P); assumption.
Qed.

Lemma algo_sub_topLike_genH : forall D0 A B, algo_sub D0 A B -> topLike D0 A -> topLike D0 B.
Proof.
  intros D0 A B H. induction H as
    [ D0 X HTC0 HTW
    | D0 HTC0
    | D0 A0 B0 HTW Hord Htop
    | D0 A0 HTC0 HTW Hord
    | D0 A0 B0 C0 HTWB Hord Hsub IHsub
    | D0 A0 B0 C0 HTWA Hord Hsub IHsub
    | D0 A1 B1 A2 B2 Hord Hsub1 IH1 Hsub2 IH2
    | L D0 A1 A2 B1 B2 Hords Hsub1 IH1 Hbody IHB
    | D0 l A0 B0 Hord Hsub IH
    | D0 A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2 ];
    intro HT.
  - exact HT.
  - exfalso. exact (topLike_t_int_false D0 HT).
  - exact Htop.
  - exfalso. exact (topLike_t_bot_false D0 HT).
  - exact (IHsub (proj1 (topLike_and_inv D0 A0 B0 HT))).
  - exact (IHsub (proj2 (topLike_and_inv D0 A0 B0 HT))).
  - destruct (topLike_arrow_inv D0 A1 B1 HT) as [HTWA1 HTLB1].
    apply (TL_arrow D0 A2 B2).
    + exact (algo_sub_TWell_source D0 A2 A1
               (topLike_TCWell D0 (t_arrow A1 B1) HT) Hsub1).
    + exact (IH2 HTLB1).
  - destruct (topLike_all_body_invH D0 A1 A2 HT) as [LL Hb0].
    assert (HTC : TCWell D0) by
      (apply (topLike_TCWell D0 (t_forall A1 A2)); exact HT).
    assert (HTB1 : TWell D0 B1) by
      (apply (algo_sub_TWell_source D0 B1 A1); [exact HTC | exact Hsub1]).
    apply (TL_all ((L \u dom D0) \u LL) D0 B1 B2).
    intros X HX.
    destruct (notin_union X (L \u dom D0) LL HX) as [HX1 HXL0].
    destruct (notin_union X L (dom D0) HX1) as [HXL HXD].
    assert (HTbody : topLike (cons (X,A1) D0) (A2 -^ X))
      by (exact (Hb0 X HXL0)).
    assert (HTC' : TCWell (cons (X,B1) D0)).
    { apply (TCW_cons D0 X B1 HTC HTB1).
      apply uniq_cons.
      - apply (TCWell_uniq D0 HTC).
      - exact HXD. }
    assert (Hmap : map fst (cons (X,A1) D0) = map fst (cons (X,B1) D0))
      by (simpl; reflexivity).
    assert (R : forall Y C, binds Y C (cons (X,A1) D0) ->
               exists C', binds Y C' (cons (X,B1) D0) /\ (botLike C -> botLike C')).
    { intros Y C Hb. apply binds_cons_1 in Hb. destruct Hb as [Hx | Hin].
      - destruct Hx as [HY HC]. subst. exists B1. split;
          [ apply binds_cons_2; reflexivity
          | intro Hbl; exact (algo_sub_botLike_gen D0 B1 A1 Hsub1 Hbl) ].
      - exists C. split; [ apply binds_cons_3; exact Hin | intro Hbl; exact Hbl ]. }
    assert (HTbody' : topLike (cons (X,B1) D0) (A2 -^ X)).
    { exact (topLike_ctx_morph (cons (X,A1) D0) (A2 -^ X)
               HTbody (cons (X,B1) D0) HTC' Hmap R). }
    exact (IHB X HXL HTbody').
  - apply (TL_rcd D0 l B0). exact (IH (topLike_rcd_inv D0 l A0 HT)).
  - apply (spl_topLike_sourceH B0 B1 B2 Hspl D0).
    + exact (IH1 HT).
    + exact (IH2 HT).
Qed.

(* Inversions of algorithmic subtyping with a fixed-shaped source and an
   ordinal target. *)

Lemma algo_sub_ord_arrow_target : forall D X Y C,
  ord C -> algo_sub D (t_arrow X Y) C ->
  topLike D C \/
  (exists A2 B2, C = t_arrow A2 B2 /\ algo_sub D A2 X /\
     algo_sub D Y B2 /\ ord B2).
Proof.
  intros D X Y C Hord H.
  inversion H as
    [ D0 X0 HTC0 HTW
    | D0 HTC0
    | D0 A0 B0 HTW HordB0 Htop
    | D0 A0 HTC0 HTW HordA0
    | D0 A0 B0 C0 HTWB HordC0 Hsub
    | D0 A0 B0 C0 HTWA HordC0 Hsub
    | D0 A1 B1 A2 B2 HordB2 Hsub1 Hsub2
    | L D0 A1 A2 B1 B2 Hords Hsub1 Hbody
    | D0 l A0 B0 HordB0 Hsub
    | D0 A0 B0 B1 B2 Hspl Hsub1 Hsub2 ].
  - (* S_top *) left. assumption.
  - (* S_arrow *) right. exists A2, B2. repeat split; eauto.
  - (* S_and *) exfalso. eapply spl_not_ord; eassumption.
Qed.

Lemma algo_sub_ord_forall_target : forall D X Y C,
  ord C -> algo_sub D (t_forall X Y) C ->
  topLike D C \/
  (exists L A2 B2, C = t_forall A2 B2 /\ algo_sub D A2 X /\
     (forall Z, Z \notin L -> algo_sub (cons (Z,A2) D) (Y -^ Z) (B2 -^ Z)) /\
     (forall Z, Z \notin L -> ord (B2 -^ Z))).
Proof.
  intros D X Y C Hord H.
  inversion H as
    [ D0 X0 HTC0 HTW
    | D0 HTC0
    | D0 A0 B0 HTW HordB0 Htop
    | D0 A0 HTC0 HTW HordA0
    | D0 A0 B0 C0 HTWB HordC0 Hsub
    | D0 A0 B0 C0 HTWA HordC0 Hsub
    | D0 A1 B1 A2 B2 HordB2 Hsub1 Hsub2
    | L D0 A1 A2 B1 B2 Hords Hsub1 Hbody
    | D0 l A0 B0 HordB0 Hsub
    | D0 A0 B0 B1 B2 Hspl Hsub1 Hsub2 ].
  - (* S_top *) left. assumption.
  - (* S_all *) right. exists L, B1, B2. repeat split; eauto.
  - (* S_and *) exfalso. eapply spl_not_ord; eassumption.
Qed.

Lemma algo_sub_ord_rcd_target : forall D l X C,
  ord C -> algo_sub D (t_rcd l X) C ->
  topLike D C \/
  (exists B2, C = t_rcd l B2 /\ algo_sub D X B2 /\ ord B2).
Proof.
  intros D l X C Hord H.
  inversion H as
    [ D0 X0 HTC0 HTW
    | D0 HTC0
    | D0 A0 B0 HTW HordB0 Htop
    | D0 A0 HTC0 HTW HordA0
    | D0 A0 B0 C0 HTWB HordC0 Hsub
    | D0 A0 B0 C0 HTWA HordC0 Hsub
    | D0 A1 B1 A2 B2 HordB2 Hsub1 Hsub2
    | L D0 A1 A2 B1 B2 Hords Hsub1 Hbody
    | D0 l0 A0 B0 HordB0 Hsub
    | D0 A0 B0 B1 B2 Hspl Hsub1 Hsub2 ].
  - (* S_top *) left. assumption.
  - (* S_rcd *) right. exists B0. repeat split; eauto.
  - (* S_and *) exfalso. eapply spl_not_ord; eassumption.
Qed.

Lemma algo_sub_ord_and_source : forall D X Y C,
  TCWell D -> TWell D (t_and X Y) -> ord C ->
  algo_sub D (t_and X Y) C ->
  (algo_sub D X C /\ TWell D Y) \/ (algo_sub D Y C /\ TWell D X).
Proof.
  intros D X Y C HTC HTW Hord H.
  inversion H as
    [ D0 X0 HTC0 HTW0
    | D0 HTC0
    | D0 A0 B0 HTW0 HordB0 Htop
    | D0 A0 HTC0 HTW0 HordA0
    | D0 A0 B0 C0 HTWB HordC0 Hsub
    | D0 A0 B0 C0 HTWA HordC0 Hsub
    | D0 A1 B1 A2 B2 HordB2 Hsub1 Hsub2
    | L D0 A1 A2 B1 B2 Hords Hsub1 Hbody
    | D0 l A0 B0 HordB0 Hsub
    | D0 A0 B0 B1 B2 Hspl Hsub1 Hsub2 ].
  - (* S_top *) destruct (TWell_and_inv D X Y HTW) as [HTX HTY].
    left. split.
    + exact (S_top D X C HTX Hord Htop).
    + exact HTY.
  - (* S_andl *) left. split; assumption.
  - (* S_andr *) right. split; assumption.
  - (* S_and: target split contradiction *) exfalso.
    exact (spl_not_ord C B1 B2 Hspl Hord).
Qed.

(* ==================================================================== *)

(* ==================================================================== *)
(* Renaming invariance for algorithmic subtyping                        *)
(* ==================================================================== *)

Lemma algo_sub_ren_aux : forall n D A B,
  size_typ A + size_typ B <= n ->
  algo_sub D A B ->
  forall f, uniq (ren_ctx f D) ->
    algo_sub (ren_ctx f D) (ren_typ f A) (ren_typ f B).
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D A B Hle H f Huniq.
  destruct H as
    [ D0 X HTC0 HTW0
    | D0 HTC0
    | D0 A0 B0 HTW0 Hord0 Htop0
    | D0 A0 HTC0 HTW0 Hord0
    | D0 A0 B0 C0 HTWB Hord0 Hsub
    | D0 A0 B0 C0 HTWA Hord0 Hsub
    | D0 A1 B1 A2 B2 Hord0 Hsub1 Hsub2
    | L D0 A1 A2 B1 B2 Hords Hsub1 Hbody
    | D0 l A0 B0 Hord0 Hsub
    | D0 A0 B0 B1 B2 Hspl Hsub1 Hsub2 ].
  - (* S_var *) simpl. apply (S_var (ren_ctx f D0) (f X)).
    + apply (TCWell_ren D0 HTC0 f Huniq).
    + apply (TWell_ren D0 (t_tvar_f X) HTW0 f).
  - (* S_int *) simpl. apply (S_int (ren_ctx f D0)).
    apply (TCWell_ren D0 HTC0 f Huniq).
  - (* S_top *) simpl. apply (S_top (ren_ctx f D0) (ren_typ f A0) (ren_typ f B0)).
    + apply (TWell_ren D0 A0 HTW0 f).
    + apply (ord_ren B0 Hord0 f).
    + apply (topLike_ren D0 B0 Htop0 f Huniq).
  - (* S_bot *) simpl. apply (S_bot (ren_ctx f D0) (ren_typ f A0)).
    + apply (TCWell_ren D0 HTC0 f Huniq).
    + apply (TWell_ren D0 A0 HTW0 f).
    + apply (ord_ren A0 Hord0 f).
  - (* S_andl *) simpl. apply (S_andl (ren_ctx f D0) (ren_typ f A0) (ren_typ f B0) (ren_typ f C0)).
    + apply (TWell_ren D0 B0 HTWB f).
    + apply (ord_ren C0 Hord0 f).
    + assert (Hlt : size_typ A0 + size_typ C0 < n) by (simpl in Hle; lia).
      exact (IH _ Hlt D0 A0 C0 (le_n _) Hsub f Huniq).
  - (* S_andr *) simpl. apply (S_andr (ren_ctx f D0) (ren_typ f A0) (ren_typ f B0) (ren_typ f C0)).
    + apply (TWell_ren D0 A0 HTWA f).
    + apply (ord_ren C0 Hord0 f).
    + assert (Hlt : size_typ B0 + size_typ C0 < n) by (simpl in Hle; lia).
      exact (IH _ Hlt D0 B0 C0 (le_n _) Hsub f Huniq).
  - (* S_arrow *) simpl. apply (S_arrow (ren_ctx f D0) (ren_typ f A1) (ren_typ f B1)
                                         (ren_typ f A2) (ren_typ f B2)).
    + apply (ord_ren B2 Hord0 f).
    + assert (Hlt : size_typ A2 + size_typ A1 < n) by (simpl in Hle; lia).
      exact (IH _ Hlt D0 A2 A1 (le_n _) Hsub1 f Huniq).
    + assert (Hlt : size_typ B1 + size_typ B2 < n) by (simpl in Hle; lia).
      exact (IH _ Hlt D0 B1 B2 (le_n _) Hsub2 f Huniq).
  - (* S_all *)
    simpl.
    pose (bad := L \u [[A2]] \u [[B1]] \u [[B2]] \u dom D0 \u typefv_typ_range D0 \u dom (ren_ctx f D0)).
    pose (Y0 := fresh (AtomSetImpl.elements bad)).
    assert (HY0bad : Y0 \notin bad) by (apply fresh_notin).
    assert (HY0L : Y0 \notin L).
    { intro Hc. apply HY0bad. unfold bad. apply AtomSetImpl.union_2. exact Hc. }
    assert (HY0A2 : Y0 \notin [[A2]]).
    { intro Hc. apply HY0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
    assert (HY0B1 : Y0 \notin [[B1]]).
    { intro Hc. apply HY0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
    assert (HY0B2 : Y0 \notin [[B2]]).
    { intro Hc. apply HY0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
    assert (HY0D : Y0 \notin dom D0).
    { intro Hc. apply HY0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
    assert (HY0R : Y0 \notin typefv_typ_range D0).
    { intro Hc. apply HY0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
    assert (HY0RD : Y0 \notin dom (ren_ctx f D0)).
    { intro Hc. apply HY0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3. exact Hc. }
    assert (Hlecons : size_typ (A2 -^ Y0) + size_typ (B2 -^ Y0) < n).
    { rewrite !size_typ_open_typH. simpl in Hle. lia. }
    assert (Hle1 : size_typ B1 + size_typ A1 < n).
    { simpl in Hle. lia. }
    pose (L' := bad \u (dom (ren_ctx f D0))).
    apply (S_all L' (ren_ctx f D0) (ren_typ f A1) (ren_typ f A2) (ren_typ f B1) (ren_typ f B2)).
    + (* ordinal bodies *)
      intros X HX.
      pose (g := fun W => if eq_dec W Y0 then X else f W).
      assert (HgY : g Y0 = X).
      { unfold g. destruct (eq_dec Y0 Y0) as [Heq | Hne]; [reflexivity | exfalso; apply Hne; reflexivity]. }
      assert (HgB2 : ren_typ g B2 = ren_typ f B2).
      { apply ren_typ_eq_on_fv. intros Z HZ. unfold g.
        destruct (eq_dec Z Y0) as [Heq | Hne].
        - subst Z. exfalso. apply HY0B2. assumption.
        - reflexivity. }
      pose proof (ord_ren (B2 -^ Y0) (Hords Y0 HY0L) g) as Ho.
      rewrite ren_typ_open0 in Ho.
      rewrite HgB2, HgY in Ho.
      exact Ho.
    + (* domain *)
      exact (IH _ Hle1 D0 B1 A1 (le_n _) Hsub1 f Huniq).
    + (* bodies *)
      intros X HX.
      destruct (notin_union X bad (dom (ren_ctx f D0)) HX) as [HXbad HXdom].
      assert (HXL : X \notin L).
      { intro Hc. apply HXbad. unfold bad. apply AtomSetImpl.union_2. exact Hc. }
      assert (HXA2 : X \notin [[A2]]).
      { intro Hc. apply HXbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HXB1 : X \notin [[B1]]).
      { intro Hc. apply HXbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HXB2 : X \notin [[B2]]).
      { intro Hc. apply HXbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HXD : X \notin dom D0).
      { intro Hc. apply HXbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HXR : X \notin typefv_typ_range D0).
      { intro Hc. apply HXbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      pose (g := fun W => if eq_dec W Y0 then X else f W).
      assert (HgY : g Y0 = X).
      { unfold g. destruct (eq_dec Y0 Y0) as [Heq | Hne]; [reflexivity | exfalso; apply Hne; reflexivity]. }
      assert (HgB1 : ren_typ g B1 = ren_typ f B1).
      { apply ren_typ_eq_on_fv. intros Z HZ. unfold g.
        destruct (eq_dec Z Y0) as [Heq | Hne].
        - subst Z. exfalso. apply HY0B1. assumption.
        - reflexivity. }
      assert (HgA2 : ren_typ g A2 = ren_typ f A2).
      { apply ren_typ_eq_on_fv. intros Z HZ. unfold g.
        destruct (eq_dec Z Y0) as [Heq | Hne].
        - subst Z. exfalso. apply HY0A2. assumption.
        - reflexivity. }
      assert (HgB2 : ren_typ g B2 = ren_typ f B2).
      { apply ren_typ_eq_on_fv. intros Z HZ. unfold g.
        destruct (eq_dec Z Y0) as [Heq | Hne].
        - subst Z. exfalso. apply HY0B2. assumption.
        - reflexivity. }
      assert (HgD : ren_ctx g D0 = ren_ctx f D0).
      { apply ren_ctx_eq.
        - intros Z HZ. unfold g. destruct (eq_dec Z Y0) as [Heq | Hne].
          + subst Z. exfalso. apply HY0D. assumption.
          + reflexivity.
        - intros Z HZ. unfold g. destruct (eq_dec Z Y0) as [Heq | Hne].
          + subst Z. exfalso. apply HY0R. assumption.
          + reflexivity. }
      assert (Huniq' : uniq (ren_ctx g (cons (Y0, B1) D0))).
      { rewrite ren_ctx_cons. rewrite HgY, HgB1, HgD.
        apply uniq_cons.
        - exact Huniq.
        - exact HXdom. }
      pose proof (IH _ Hlecons (cons (Y0, B1) D0) (A2 -^ Y0) (B2 -^ Y0)
                    (le_n _) (Hbody Y0 HY0L) g Huniq') as Hres.
      rewrite ren_ctx_cons in Hres.
      rewrite HgY, HgB1, HgD in Hres.
      rewrite !ren_typ_open0 in Hres.
      rewrite HgA2, HgB2, HgY in Hres.
      exact Hres.
  - (* S_rcd *) simpl. apply (S_rcd (ren_ctx f D0) l (ren_typ f A0) (ren_typ f B0)).
    + apply (ord_ren B0 Hord0 f).
    + assert (Hlt : size_typ A0 + size_typ B0 < n) by (simpl in Hle; lia).
      exact (IH _ Hlt D0 A0 B0 (le_n _) Hsub f Huniq).
  - (* S_and *) simpl. apply (S_and (ren_ctx f D0) (ren_typ f A0) (ren_typ f B0)
                                     (ren_typ f B1) (ren_typ f B2)).
    + apply (spl_ren B0 B1 B2 Hspl f).
    + assert (Hlt : size_typ A0 + size_typ B1 < n) by (simpl in Hle; pose proof (proj1 (spl_size_ltH B0 B1 B2 Hspl)); lia).
      exact (IH _ Hlt D0 A0 B1 (le_n _) Hsub1 f Huniq).
    + assert (Hlt : size_typ A0 + size_typ B2 < n) by (simpl in Hle; pose proof (proj2 (spl_size_ltH B0 B1 B2 Hspl)); lia).
      exact (IH _ Hlt D0 A0 B2 (le_n _) Hsub2 f Huniq).
Qed.

Lemma algo_sub_ren : forall D A B, algo_sub D A B ->
  forall f, uniq (ren_ctx f D) ->
    algo_sub (ren_ctx f D) (ren_typ f A) (ren_typ f B).
Proof.
  intros D A B H f Huniq.
  exact (algo_sub_ren_aux (size_typ A + size_typ B) D A B (le_n _) H f Huniq).
Qed.

(* ==================================================================== *)
(* Splitting a source whose target is ordinal: one component suffices.  *)
(* ==================================================================== *)


(* ==================================================================== *)
(* Splitting a source whose target is ordinal: one component suffices.  *)
(* ==================================================================== *)

Lemma algo_sub_spl_source_or_aux : forall n D B C,
  size_typ B + size_typ C <= n ->
  TCWell D -> algo_sub D B C ->
  forall B1 B2, spl B B1 B2 -> ord C ->
    algo_sub D B1 C \/ algo_sub D B2 C.
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D B C Hle HTC HBC B1 B2 Hspl HordC.
  destruct Hspl as
    [ X Y Z1 Z2 HlcX HsplY
    | Ls X Y Z1 Z2 HlcX HsplY
    | l X Z1 Z2 HsplY
    | X Y HlcX HlcY ].
  - (* Sp_arrow *)
    assert (Hspl0 : spl (t_arrow X Y) (t_arrow X Z1) (t_arrow X Z2))
      by (exact (Sp_arrow X Y Z1 Z2 HlcX HsplY)).
    assert (HTB : TWell D (t_arrow X Y))
      by (exact (algo_sub_TWell_source D (t_arrow X Y) C HTC HBC)).
    destruct (spl_TWell_components D (t_arrow X Y) (t_arrow X Z1) (t_arrow X Z2) HTB Hspl0)
      as [HTW1 HTW2].
    destruct (algo_sub_ord_arrow_target D X Y C HordC HBC) as
      [Htop | (A3 & B3 & Heq & Hdom & Hcod & HordB3)].
    + left. exact (S_top D (t_arrow X Z1) C HTW1 HordC Htop).
    + subst C.
      assert (Hlt : size_typ Y + size_typ B3 < n) by (simpl in Hle; lia).
      destruct (IH _ Hlt D Y B3 (le_n _) HTC Hcod Z1 Z2 HsplY HordB3)
        as [HZ1 | HZ2].
      * left. exact (S_arrow D X Z1 A3 B3 HordB3 Hdom HZ1).
      * right. exact (S_arrow D X Z2 A3 B3 HordB3 Hdom HZ2).
  - (* Sp_all *)
    assert (Hspl0 : spl (t_forall X Y) (t_forall X Z1) (t_forall X Z2))
      by (exact (Sp_all Ls X Y Z1 Z2 HlcX HsplY)).
    assert (HTB : TWell D (t_forall X Y))
      by (exact (algo_sub_TWell_source D (t_forall X Y) C HTC HBC)).
    destruct (spl_TWell_components D (t_forall X Y) (t_forall X Z1) (t_forall X Z2) HTB Hspl0)
      as [HTW1 HTW2].
    destruct (algo_sub_ord_forall_target D X Y C HordC HBC) as
      [Htop | (L2 & A3 & B3 & Heq & Hdom & Hbody & Hords)].
    + left. exact (S_top D (t_forall X Z1) C HTW1 HordC Htop).
    + subst C.
      pose (bad := L2 \u [[Z1]] \u [[Z2]] \u [[A3]] \u [[B3]] \u dom D \u typefv_typ_range D \u Ls).
      pose (W0 := fresh (AtomSetImpl.elements bad)).
      assert (HW0bad : W0 \notin bad) by (apply fresh_notin).
      assert (HW0L2 : W0 \notin L2).
      { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_2. exact Hc. }
      assert (HW0Z1 : W0 \notin [[Z1]]).
      { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HW0Z2 : W0 \notin [[Z2]]).
      { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HW0A3 : W0 \notin [[A3]]).
      { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HW0B3 : W0 \notin [[B3]]).
      { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HW0D : W0 \notin dom D).
      { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HW0R : W0 \notin typefv_typ_range D).
      { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HW0LS : W0 \notin Ls).
      { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3. exact Hc. }
      assert (HTWA3 : TWell D A3) by (exact (algo_sub_TWell_source D A3 X HTC Hdom)).
      pose (Dw0 := cons (W0, A3) D).
      assert (HTCw0 : TCWell Dw0).
      { apply (TCW_cons D W0 A3 HTC HTWA3).
        apply uniq_cons; [ apply (TCWell_uniq D HTC) | exact HW0D ]. }
      assert (Hlt0 : size_typ (Y -^ W0) + size_typ (B3 -^ W0) < n).
      { rewrite !size_typ_open_typH. simpl in Hle. lia. }
      assert (Hdist : algo_sub Dw0 (Z1 -^ W0) (B3 -^ W0) \/
                      algo_sub Dw0 (Z2 -^ W0) (B3 -^ W0)).
      { exact (IH _ Hlt0 Dw0 (Y -^ W0) (B3 -^ W0) (le_n _) HTCw0
                 (Hbody W0 HW0L2) (Z1 -^ W0) (Z2 -^ W0)
                 (HsplY W0 HW0LS) (Hords W0 HW0L2)). }
      destruct Hdist as [Hleft | Hright].
      * left.
        pose (L' := bad \u dom D).
        apply (S_all L' D X Z1 A3 B3).
        -- intros W HW. apply Hords.
           destruct (notin_union W bad (dom D) HW) as [HWbad _].
           intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_2. exact Hc.
        -- exact Hdom.
        -- intros W HW.
           destruct (notin_union W bad (dom D) HW) as [HWbad HWD].
           assert (HWL2 : W \notin L2).
           { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_2. exact Hc. }
           assert (HWZ1 : W \notin [[Z1]]).
           { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
           assert (HWA3 : W \notin [[A3]]).
           { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
           assert (HWB3 : W \notin [[B3]]).
           { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
           assert (HWR : W \notin typefv_typ_range D).
           { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
           pose (fren := rename_var W0 W).
           assert (HfW0 : fren W0 = W) by (unfold fren; apply rename_var_eq).
           assert (HfA3 : ren_typ fren A3 = A3).
           { apply ren_typ_id. intros Z HZ. unfold fren.
             apply rename_var_neq. intro Hc. subst Z. apply HW0A3. assumption. }
           assert (HfD : ren_ctx fren D = D).
           { transitivity (ren_ctx (fun X : typevar => X) D).
             - apply ren_ctx_eq.
               + intros Z HZ. unfold fren. apply rename_var_neq. intro Hc. subst Z. apply HW0D. assumption.
               + intros Z HZ. unfold fren. apply rename_var_neq. intro Hc. subst Z. apply HW0R. assumption.
             - apply ren_ctx_id. }
           assert (Huniq' : uniq (ren_ctx fren Dw0)).
           { unfold Dw0. rewrite ren_ctx_cons. rewrite HfW0, HfA3, HfD.
             apply uniq_cons; [ apply (TCWell_uniq D HTC) | exact HWD ]. }
           pose proof (algo_sub_ren Dw0 (Z1 -^ W0) (B3 -^ W0) Hleft fren Huniq') as Hren.
           unfold Dw0 in Hren. rewrite ren_ctx_cons in Hren.
           rewrite HfW0, HfA3, HfD in Hren.
           unfold fren in Hren.
           rewrite !ren_typ_open_rename in Hren; [ | exact HW0B3 | exact HW0Z1 ].
           exact Hren.
      * right.
        pose (L' := bad \u dom D).
        apply (S_all L' D X Z2 A3 B3).
        -- intros W HW. apply Hords.
           destruct (notin_union W bad (dom D) HW) as [HWbad _].
           intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_2. exact Hc.
        -- exact Hdom.
        -- intros W HW.
           destruct (notin_union W bad (dom D) HW) as [HWbad HWD].
           assert (HWL2 : W \notin L2).
           { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_2. exact Hc. }
           assert (HWZ2 : W \notin [[Z2]]).
           { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
           assert (HWA3 : W \notin [[A3]]).
           { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
           assert (HWB3 : W \notin [[B3]]).
           { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
           assert (HWR : W \notin typefv_typ_range D).
           { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
           pose (fren := rename_var W0 W).
           assert (HfW0 : fren W0 = W) by (unfold fren; apply rename_var_eq).
           assert (HfA3 : ren_typ fren A3 = A3).
           { apply ren_typ_id. intros Z HZ. unfold fren.
             apply rename_var_neq. intro Hc. subst Z. apply HW0A3. assumption. }
           assert (HfD : ren_ctx fren D = D).
           { transitivity (ren_ctx (fun X : typevar => X) D).
             - apply ren_ctx_eq.
               + intros Z HZ. unfold fren. apply rename_var_neq. intro Hc. subst Z. apply HW0D. assumption.
               + intros Z HZ. unfold fren. apply rename_var_neq. intro Hc. subst Z. apply HW0R. assumption.
             - apply ren_ctx_id. }
           assert (Huniq' : uniq (ren_ctx fren Dw0)).
           { unfold Dw0. rewrite ren_ctx_cons. rewrite HfW0, HfA3, HfD.
             apply uniq_cons; [ apply (TCWell_uniq D HTC) | exact HWD ]. }
           pose proof (algo_sub_ren Dw0 (Z2 -^ W0) (B3 -^ W0) Hright fren Huniq') as Hren.
           unfold Dw0 in Hren. rewrite ren_ctx_cons in Hren.
           rewrite HfW0, HfA3, HfD in Hren.
           unfold fren in Hren.
           rewrite !ren_typ_open_rename in Hren; [ | exact HW0B3 | exact HW0Z2 ].
           exact Hren.
  - (* Sp_rcd *)
    assert (Hspl0 : spl (t_rcd l X) (t_rcd l Z1) (t_rcd l Z2))
      by (exact (Sp_rcd l X Z1 Z2 HsplY)).
    assert (HTB : TWell D (t_rcd l X))
      by (exact (algo_sub_TWell_source D (t_rcd l X) C HTC HBC)).
    destruct (spl_TWell_components D (t_rcd l X) (t_rcd l Z1) (t_rcd l Z2) HTB Hspl0)
      as [HTW1 HTW2].
    destruct (algo_sub_ord_rcd_target D l X C HordC HBC) as
      [Htop | (B3 & Heq & Hsub & HordB3)].
    + left. exact (S_top D (t_rcd l Z1) C HTW1 HordC Htop).
    + subst C.
      assert (Hlt : size_typ X + size_typ B3 < n) by (simpl in Hle; lia).
      destruct (IH _ Hlt D X B3 (le_n _) HTC Hsub Z1 Z2 HsplY HordB3)
        as [HZ1 | HZ2].
      * left. exact (S_rcd D l Z1 B3 HordB3 HZ1).
      * right. exact (S_rcd D l Z2 B3 HordB3 HZ2).
  - (* Sp_and *)
    assert (Hspl0 : spl (t_and X Y) X Y) by (exact (Sp_and X Y HlcX HlcY)).
    assert (HTB : TWell D (t_and X Y))
      by (exact (algo_sub_TWell_source D (t_and X Y) C HTC HBC)).
    destruct (algo_sub_ord_and_source D X Y C HTC HTB HordC HBC) as [Hleft | Hright].
    + destruct Hleft as [HX _]. left. exact HX.
    + destruct Hright as [HY _]. right. exact HY.
Qed.

Lemma algo_sub_spl_source_or : forall D B C,
  TCWell D -> algo_sub D B C ->
  forall B1 B2, spl B B1 B2 -> ord C ->
    algo_sub D B1 C \/ algo_sub D B2 C.
Proof.
  intros D B C HTC HBC B1 B2 Hspl HordC.
  exact (algo_sub_spl_source_or_aux (size_typ B + size_typ C) D B C
           (le_n _) HTC HBC B1 B2 Hspl HordC).
Qed.

(* ==================================================================== *)
(* Transitivity of algorithmic subtyping, with well-formedness           *)
(* ==================================================================== *)

Lemma algo_sub_trans_aux : forall N D A B C,
  size_typ A + size_typ B + size_typ C <= N ->
  TCWell D -> TWell D A -> TWell D B -> TWell D C ->
  algo_sub D A B -> algo_sub D B C -> algo_sub D A C.
Proof.
  induction N as [N IH] using lt_wf_ind.
  intros D A B C Hle HTC HTA HTB HTCc H1 H2.
  destruct (TWell_coverage_TC D C HTC HTCc) as [HordC | (C1 & C2 & HsplC)].
  - (* target C is ord: inspect the first derivation *)
    destruct H1 as
      [ D0 X0 HTC0 HTW0
      | D0 HTC0
      | D0 A0 B0 HTW0 HordB0 Htop0
      | D0 A0 HTC0 HTW0 HordA0
      | D0 A0 B0 C0 HTWB HordC0 Hsub
      | D0 A0 B0 C0 HTWA HordC0 Hsub
      | D0 A1 B1 A2 B2 HordB2 Hsub1 Hsub2
      | L D0 A1 A2 B1 B2 Hords Hsub1 Hbody
      | D0 l A0 B0 HordB0 Hsub
      | D0 A0 B0 B1 B2 Hspl Hsub1 Hsub2 ].
    + (* S_var *) exact H2.
    + (* S_int *) exact H2.
    + (* S_top *) apply (S_top D0 A0 C HTW0 HordC).
      exact (algo_sub_topLike_genH D0 B0 C H2 Htop0).
    + (* S_bot *) apply (S_bot D0 C HTC0 HTCc HordC).
    + (* S_andl *)
      assert (HTA0 : TWell D0 A0) by (exact (proj1 (TWell_and_inv D0 A0 B0 HTA))).
      assert (HTWC0 : TWell D0 C0) by (exact (algo_sub_TWell_target D0 A0 C0 HTC Hsub)).
      assert (Hlt : size_typ A0 + size_typ C0 + size_typ C < N)
        by (simpl in Hle; lia).
      assert (Ht : algo_sub D0 A0 C) by
        (exact (IH _ Hlt D0 A0 C0 C (le_n _) HTC HTA0 HTWC0 HTCc Hsub H2)).
      exact (S_andl D0 A0 B0 C HTWB HordC Ht).
    + (* S_andr *)
      assert (HTB0 : TWell D0 B0) by (exact (proj2 (TWell_and_inv D0 A0 B0 HTA))).
      assert (HTWC0 : TWell D0 C0) by (exact (algo_sub_TWell_target D0 B0 C0 HTC Hsub)).
      assert (Hlt : size_typ B0 + size_typ C0 + size_typ C < N)
        by (simpl in Hle; lia).
      assert (Ht : algo_sub D0 B0 C) by
        (exact (IH _ Hlt D0 B0 C0 C (le_n _) HTC HTB0 HTWC0 HTCc Hsub H2)).
      exact (S_andr D0 A0 B0 C HTWA HordC Ht).
    + (* S_arrow *)
      destruct (algo_sub_ord_arrow_target D0 A2 B2 C HordC H2) as
        [Htop | (A3 & B3 & Heq & Hda & Hdb & HordB3)].
      * apply (S_top D0 (t_arrow A1 B1) C HTA HordC Htop).
      * subst C.
        assert (HTWA3 : TWell D0 A3) by (exact (algo_sub_TWell_source D0 A3 A2 HTC Hda)).
        assert (HTWA2 : TWell D0 A2) by (exact (algo_sub_TWell_target D0 A3 A2 HTC Hda)).
        assert (HTWA1 : TWell D0 A1) by (exact (algo_sub_TWell_target D0 A2 A1 HTC Hsub1)).
        assert (HTWB1 : TWell D0 B1) by (exact (algo_sub_TWell_source D0 B1 B2 HTC Hsub2)).
        assert (HTWB2 : TWell D0 B2) by (exact (algo_sub_TWell_target D0 B1 B2 HTC Hsub2)).
        assert (HTWB3 : TWell D0 B3) by (exact (algo_sub_TWell_target D0 B2 B3 HTC Hdb)).
        assert (HltA : size_typ A3 + size_typ A2 + size_typ A1 < N)
          by (simpl in Hle; lia).
        assert (HltB : size_typ B1 + size_typ B2 + size_typ B3 < N)
          by (simpl in Hle; lia).
        assert (Hdom : algo_sub D0 A3 A1) by
          (exact (IH _ HltA D0 A3 A2 A1 (le_n _) HTC HTWA3 HTWA2 HTWA1 Hda Hsub1)).
        assert (Hcod : algo_sub D0 B1 B3) by
          (exact (IH _ HltB D0 B1 B2 B3 (le_n _) HTC HTWB1 HTWB2 HTWB3 Hsub2 Hdb)).
        exact (S_arrow D0 A1 B1 A3 B3 HordB3 Hdom Hcod).
    + (* S_all *)
      destruct (algo_sub_ord_forall_target D0 B1 B2 C HordC H2) as
        [Htop | (L2 & C1 & C2 & Heq & Hdom & Hb2 & Hords2)].
      * apply (S_top D0 (t_forall A1 A2) C HTA HordC Htop).
      * subst C.
        assert (HTWC1 : TWell D0 C1) by (exact (algo_sub_TWell_source D0 C1 B1 HTC Hdom)).
        assert (HTWB1 : TWell D0 B1) by (exact (algo_sub_TWell_target D0 C1 B1 HTC Hdom)).
        assert (HTWA1 : TWell D0 A1) by (exact (algo_sub_TWell_target D0 B1 A1 HTC Hsub1)).
        assert (HTWB1' : TWell D0 B1) by (exact (TWell_all_inv D0 B1 B2 HTB)).
        assert (HltD : size_typ C1 + size_typ B1 + size_typ A1 < N)
          by (simpl in Hle; lia).
        assert (HdomT : algo_sub D0 C1 A1) by
          (exact (IH _ HltD D0 C1 B1 A1 (le_n _) HTC HTWC1 HTWB1 HTWA1 Hdom Hsub1)).
        pose (L' := (L \u L2) \u dom D0).
        apply (S_all L' D0 A1 A2 C1 C2).
        -- intros Z HZ. apply Hords2.
           destruct (notin_union Z (L \u L2) (dom D0) HZ) as [HZ12 _].
           destruct (notin_union Z L L2 HZ12) as [_ HZL2]. exact HZL2.
        -- exact HdomT.
        -- intros Z HZ.
           destruct (notin_union Z (L \u L2) (dom D0) HZ) as [HZ12 HZD].
           destruct (notin_union Z L L2 HZ12) as [HZL HZL2].
           assert (Hbody1 : algo_sub (cons (Z,B1) D0) (A2 -^ Z) (B2 -^ Z))
             by (exact (Hbody Z HZL)).
           assert (HTCsrc : TCWell (cons (Z,B1) D0)).
           { apply (TCW_cons D0 Z B1 HTC HTWB1').
             apply uniq_cons; [ apply (TCWell_uniq D0 HTC) | exact HZD ]. }
           assert (HTCtgt : TCWell (cons (Z,C1) D0)).
           { apply (TCW_cons D0 Z C1 HTC HTWC1).
             apply uniq_cons; [ apply (TCWell_uniq D0 HTC) | exact HZD ]. }
           assert (Hmap : map fst (cons (Z,B1) D0) = map fst (cons (Z,C1) D0))
             by (simpl; reflexivity).
           assert (Rm : forall Y T, binds Y T (cons (Z,B1) D0) ->
                      exists T', binds Y T' (cons (Z,C1) D0) /\ (botLike T -> botLike T')).
           { intros Y T Hb. apply binds_cons_1 in Hb. destruct Hb as [Hx | Hin].
             - destruct Hx as [HY HT]. subst. exists C1. split.
               + apply binds_cons_2; reflexivity.
               + intro Hbl. exact (algo_sub_botLike_gen D0 C1 B1 Hdom Hbl).
             - exists T. split.
               + apply binds_cons_3; exact Hin.
               + intro Hbl; exact Hbl. }
           assert (Hbody1' : algo_sub (cons (Z,C1) D0) (A2 -^ Z) (B2 -^ Z))
             by (exact (algo_sub_ctx_morph (cons (Z,B1) D0) (A2 -^ Z) (B2 -^ Z)
                   HTCsrc Hbody1 (cons (Z,C1) D0) HTCtgt Hmap Rm)).
           assert (Hb2Z : algo_sub (cons (Z,C1) D0) (B2 -^ Z) (C2 -^ Z))
             by (exact (Hb2 Z HZL2)).
           assert (HTWbodyA : TWell (cons (Z,C1) D0) (A2 -^ Z))
             by (exact (algo_sub_TWell_source (cons (Z,C1) D0) (A2 -^ Z) (B2 -^ Z)
                   HTCtgt Hbody1')).
           assert (HTWbodyB : TWell (cons (Z,C1) D0) (B2 -^ Z))
             by (exact (algo_sub_TWell_target (cons (Z,C1) D0) (A2 -^ Z) (B2 -^ Z)
                   HTCtgt Hbody1')).
           assert (HTWbodyC : TWell (cons (Z,C1) D0) (C2 -^ Z))
             by (exact (algo_sub_TWell_target (cons (Z,C1) D0) (B2 -^ Z) (C2 -^ Z)
                   HTCtgt Hb2Z)).
           assert (Hltbody : size_typ (A2 -^ Z) + size_typ (B2 -^ Z) + size_typ (C2 -^ Z) < N).
           { rewrite !size_typ_open_typH. simpl in Hle. lia. }
           exact (IH _ Hltbody (cons (Z,C1) D0) (A2 -^ Z) (B2 -^ Z) (C2 -^ Z)
                    (le_n _) HTCtgt HTWbodyA HTWbodyB HTWbodyC Hbody1' Hb2Z).
    + (* S_rcd *)
      destruct (algo_sub_ord_rcd_target D0 l B0 C HordC H2) as
        [Htop | (B2 & Heq & Hsub2 & HordB2)].
      * apply (S_top D0 (t_rcd l A0) C HTA HordC Htop).
      * subst C.
        assert (HTWA0 : TWell D0 A0) by (exact (TWell_rcd_inv D0 l A0 HTA)).
        assert (HTWB0 : TWell D0 B0) by (exact (algo_sub_TWell_source D0 B0 B2 HTC Hsub2)).
        assert (HTWB2 : TWell D0 B2) by (exact (algo_sub_TWell_target D0 B0 B2 HTC Hsub2)).
        assert (Hlt : size_typ A0 + size_typ B0 + size_typ B2 < N)
          by (simpl in Hle; lia).
        assert (Ht : algo_sub D0 A0 B2) by
          (exact (IH _ Hlt D0 A0 B0 B2 (le_n _) HTC HTWA0 HTWB0 HTWB2 Hsub Hsub2)).
        exact (S_rcd D0 l A0 B2 HordB2 Ht).
    + (* S_and: the first derivation splits its target *)
      assert (Hsplit : algo_sub D0 B1 C \/ algo_sub D0 B2 C)
        by (exact (algo_sub_spl_source_or D0 B0 C HTC H2 B1 B2 Hspl HordC)).
      destruct (spl_TWell_components D0 B0 B1 B2 HTB Hspl) as [HTWB1 HTWB2].
      destruct (spl_size_ltH B0 B1 B2 Hspl) as [Hsz1 Hsz2].
      destruct Hsplit as [HB1C | HB2C].
      * assert (Hlt : size_typ A0 + size_typ B1 + size_typ C < N)
          by (simpl in Hle; lia).
        exact (IH _ Hlt D0 A0 B1 C (le_n _) HTC HTA HTWB1 HTCc Hsub1 HB1C).
      * assert (Hlt : size_typ A0 + size_typ B2 + size_typ C < N)
          by (simpl in Hle; lia).
        exact (IH _ Hlt D0 A0 B2 C (le_n _) HTC HTA HTWB2 HTCc Hsub2 HB2C).
  - (* target C splits *)
    destruct (spl_TWell_components D C C1 C2 HTCc HsplC) as [HTW1 HTW2].
    assert (HB1 : algo_sub D B C1) by (exact (algo_sub_spl_l D B C C1 C2 H2 HsplC)).
    assert (HB2 : algo_sub D B C2) by (exact (algo_sub_spl_r D B C C1 C2 H2 HsplC)).
    assert (Hlt1 : size_typ A + size_typ B + size_typ C1 < N).
    { pose proof (proj1 (spl_size_ltH C C1 C2 HsplC)). lia. }
    assert (Hlt2 : size_typ A + size_typ B + size_typ C2 < N).
    { pose proof (proj2 (spl_size_ltH C C1 C2 HsplC)). lia. }
    apply (S_and D A C C1 C2 HsplC).
    + exact (IH _ Hlt1 D A B C1 (le_n _) HTC HTA HTB HTW1 H1 HB1).
    + exact (IH _ Hlt2 D A B C2 (le_n _) HTC HTA HTB HTW2 H1 HB2).
Qed.

Theorem algo_sub_trans_TWell : forall D A B C,
  TCWell D -> TWell D A -> TWell D B -> TWell D C ->
  algo_sub D A B -> algo_sub D B C -> algo_sub D A C.
Proof.
  intros D A B C HTC HTA HTB HTCc H1 H2.
  exact (algo_sub_trans_aux (size_typ A + size_typ B + size_typ C)
           D A B C (le_n _) HTC HTA HTB HTCc H1 H2).
Qed.

(* The three TWell premises are actually derivable from TCWell and the
   two algorithmic-subtyping derivations, so the following form is
   strictly stronger and often more convenient. *)

Theorem algo_sub_trans_TCWell : forall D A B C,
  TCWell D ->
  algo_sub D A B -> algo_sub D B C -> algo_sub D A C.
Proof.
  intros D A B C HTC H1 H2.
  apply (algo_sub_trans_TWell D A B C HTC).
  - exact (algo_sub_TWell_source D A B HTC H1).
  - exact (algo_sub_TWell_target D A B HTC H1).
  - exact (algo_sub_TWell_target D B C HTC H2).
  - exact H1.
  - exact H2.
Qed.
End agentH2.
Import agentH2.

Module agentH3.
Import ListNotations.

(* ==================================================================== *)
(* Renaming invariance for algorithmic subtyping                        *)
(* ==================================================================== *)

Lemma algo_sub_ren_aux : forall n D A B,
  size_typ A + size_typ B <= n ->
  algo_sub D A B ->
  forall f, uniq (ren_ctx f D) ->
    algo_sub (ren_ctx f D) (ren_typ f A) (ren_typ f B).
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D A B Hle H f Huniq.
  destruct H as
    [ D0 X HTC0 HTW0
    | D0 HTC0
    | D0 A0 B0 HTW0 Hord0 Htop0
    | D0 A0 HTC0 HTW0 Hord0
    | D0 A0 B0 C0 HTWB Hord0 Hsub
    | D0 A0 B0 C0 HTWA Hord0 Hsub
    | D0 A1 B1 A2 B2 Hord0 Hsub1 Hsub2
    | L D0 A1 A2 B1 B2 Hords Hsub1 Hbody
    | D0 l A0 B0 Hord0 Hsub
    | D0 A0 B0 B1 B2 Hspl Hsub1 Hsub2 ].
  - (* S_var *) simpl. apply (S_var (ren_ctx f D0) (f X)).
    + apply (TCWell_ren D0 HTC0 f Huniq).
    + apply (TWell_ren D0 (t_tvar_f X) HTW0 f).
  - (* S_int *) simpl. apply (S_int (ren_ctx f D0)).
    apply (TCWell_ren D0 HTC0 f Huniq).
  - (* S_top *) simpl. apply (S_top (ren_ctx f D0) (ren_typ f A0) (ren_typ f B0)).
    + apply (TWell_ren D0 A0 HTW0 f).
    + apply (ord_ren B0 Hord0 f).
    + apply (topLike_ren D0 B0 Htop0 f Huniq).
  - (* S_bot *) simpl. apply (S_bot (ren_ctx f D0) (ren_typ f A0)).
    + apply (TCWell_ren D0 HTC0 f Huniq).
    + apply (TWell_ren D0 A0 HTW0 f).
    + apply (ord_ren A0 Hord0 f).
  - (* S_andl *) simpl. apply (S_andl (ren_ctx f D0) (ren_typ f A0) (ren_typ f B0) (ren_typ f C0)).
    + apply (TWell_ren D0 B0 HTWB f).
    + apply (ord_ren C0 Hord0 f).
    + assert (Hlt : size_typ A0 + size_typ C0 < n) by (simpl in Hle; lia).
      exact (IH _ Hlt D0 A0 C0 (le_n _) Hsub f Huniq).
  - (* S_andr *) simpl. apply (S_andr (ren_ctx f D0) (ren_typ f A0) (ren_typ f B0) (ren_typ f C0)).
    + apply (TWell_ren D0 A0 HTWA f).
    + apply (ord_ren C0 Hord0 f).
    + assert (Hlt : size_typ B0 + size_typ C0 < n) by (simpl in Hle; lia).
      exact (IH _ Hlt D0 B0 C0 (le_n _) Hsub f Huniq).
  - (* S_arrow *) simpl. apply (S_arrow (ren_ctx f D0) (ren_typ f A1) (ren_typ f B1)
                                         (ren_typ f A2) (ren_typ f B2)).
    + apply (ord_ren B2 Hord0 f).
    + assert (Hlt : size_typ A2 + size_typ A1 < n) by (simpl in Hle; lia).
      exact (IH _ Hlt D0 A2 A1 (le_n _) Hsub1 f Huniq).
    + assert (Hlt : size_typ B1 + size_typ B2 < n) by (simpl in Hle; lia).
      exact (IH _ Hlt D0 B1 B2 (le_n _) Hsub2 f Huniq).
  - (* S_all *)
    simpl.
    pose (bad := L \u [[A2]] \u [[B1]] \u [[B2]] \u dom D0 \u typefv_typ_range D0 \u dom (ren_ctx f D0)).
    pose (Y0 := fresh (AtomSetImpl.elements bad)).
    assert (HY0bad : Y0 \notin bad) by (apply fresh_notin).
    assert (HY0L : Y0 \notin L).
    { intro Hc. apply HY0bad. unfold bad. apply AtomSetImpl.union_2. exact Hc. }
    assert (HY0A2 : Y0 \notin [[A2]]).
    { intro Hc. apply HY0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
    assert (HY0B1 : Y0 \notin [[B1]]).
    { intro Hc. apply HY0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
    assert (HY0B2 : Y0 \notin [[B2]]).
    { intro Hc. apply HY0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
    assert (HY0D : Y0 \notin dom D0).
    { intro Hc. apply HY0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
    assert (HY0R : Y0 \notin typefv_typ_range D0).
    { intro Hc. apply HY0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
    assert (HY0RD : Y0 \notin dom (ren_ctx f D0)).
    { intro Hc. apply HY0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3. exact Hc. }
    assert (Hlecons : size_typ (A2 -^ Y0) + size_typ (B2 -^ Y0) < n).
    { rewrite !size_typ_open_typH. simpl in Hle. lia. }
    assert (Hle1 : size_typ B1 + size_typ A1 < n).
    { simpl in Hle. lia. }
    pose (L' := bad \u (dom (ren_ctx f D0))).
    apply (S_all L' (ren_ctx f D0) (ren_typ f A1) (ren_typ f A2) (ren_typ f B1) (ren_typ f B2)).
    + (* ordinal bodies *)
      intros X HX.
      pose (g := fun W => if eq_dec W Y0 then X else f W).
      assert (HgY : g Y0 = X).
      { unfold g. destruct (eq_dec Y0 Y0) as [Heq | Hne]; [reflexivity | exfalso; apply Hne; reflexivity]. }
      assert (HgB2 : ren_typ g B2 = ren_typ f B2).
      { apply ren_typ_eq_on_fv. intros Z HZ. unfold g.
        destruct (eq_dec Z Y0) as [Heq | Hne].
        - subst Z. exfalso. apply HY0B2. assumption.
        - reflexivity. }
      pose proof (ord_ren (B2 -^ Y0) (Hords Y0 HY0L) g) as Ho.
      rewrite ren_typ_open0 in Ho.
      rewrite HgB2, HgY in Ho.
      exact Ho.
    + (* domain *)
      exact (IH _ Hle1 D0 B1 A1 (le_n _) Hsub1 f Huniq).
    + (* bodies *)
      intros X HX.
      destruct (notin_union X bad (dom (ren_ctx f D0)) HX) as [HXbad HXdom].
      assert (HXL : X \notin L).
      { intro Hc. apply HXbad. unfold bad. apply AtomSetImpl.union_2. exact Hc. }
      assert (HXA2 : X \notin [[A2]]).
      { intro Hc. apply HXbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HXB1 : X \notin [[B1]]).
      { intro Hc. apply HXbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HXB2 : X \notin [[B2]]).
      { intro Hc. apply HXbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HXD : X \notin dom D0).
      { intro Hc. apply HXbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HXR : X \notin typefv_typ_range D0).
      { intro Hc. apply HXbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      pose (g := fun W => if eq_dec W Y0 then X else f W).
      assert (HgY : g Y0 = X).
      { unfold g. destruct (eq_dec Y0 Y0) as [Heq | Hne]; [reflexivity | exfalso; apply Hne; reflexivity]. }
      assert (HgB1 : ren_typ g B1 = ren_typ f B1).
      { apply ren_typ_eq_on_fv. intros Z HZ. unfold g.
        destruct (eq_dec Z Y0) as [Heq | Hne].
        - subst Z. exfalso. apply HY0B1. assumption.
        - reflexivity. }
      assert (HgA2 : ren_typ g A2 = ren_typ f A2).
      { apply ren_typ_eq_on_fv. intros Z HZ. unfold g.
        destruct (eq_dec Z Y0) as [Heq | Hne].
        - subst Z. exfalso. apply HY0A2. assumption.
        - reflexivity. }
      assert (HgB2 : ren_typ g B2 = ren_typ f B2).
      { apply ren_typ_eq_on_fv. intros Z HZ. unfold g.
        destruct (eq_dec Z Y0) as [Heq | Hne].
        - subst Z. exfalso. apply HY0B2. assumption.
        - reflexivity. }
      assert (HgD : ren_ctx g D0 = ren_ctx f D0).
      { apply ren_ctx_eq.
        - intros Z HZ. unfold g. destruct (eq_dec Z Y0) as [Heq | Hne].
          + subst Z. exfalso. apply HY0D. assumption.
          + reflexivity.
        - intros Z HZ. unfold g. destruct (eq_dec Z Y0) as [Heq | Hne].
          + subst Z. exfalso. apply HY0R. assumption.
          + reflexivity. }
      assert (Huniq' : uniq (ren_ctx g (cons (Y0, B1) D0))).
      { rewrite ren_ctx_cons. rewrite HgY, HgB1, HgD.
        apply uniq_cons.
        - exact Huniq.
        - exact HXdom. }
      pose proof (IH _ Hlecons (cons (Y0, B1) D0) (A2 -^ Y0) (B2 -^ Y0)
                    (le_n _) (Hbody Y0 HY0L) g Huniq') as Hres.
      rewrite ren_ctx_cons in Hres.
      rewrite HgY, HgB1, HgD in Hres.
      rewrite !ren_typ_open0 in Hres.
      rewrite HgA2, HgB2, HgY in Hres.
      exact Hres.
  - (* S_rcd *) simpl. apply (S_rcd (ren_ctx f D0) l (ren_typ f A0) (ren_typ f B0)).
    + apply (ord_ren B0 Hord0 f).
    + assert (Hlt : size_typ A0 + size_typ B0 < n) by (simpl in Hle; lia).
      exact (IH _ Hlt D0 A0 B0 (le_n _) Hsub f Huniq).
  - (* S_and *) simpl. apply (S_and (ren_ctx f D0) (ren_typ f A0) (ren_typ f B0)
                                     (ren_typ f B1) (ren_typ f B2)).
    + apply (spl_ren B0 B1 B2 Hspl f).
    + assert (Hlt : size_typ A0 + size_typ B1 < n) by (simpl in Hle; pose proof (proj1 (spl_size_ltH B0 B1 B2 Hspl)); lia).
      exact (IH _ Hlt D0 A0 B1 (le_n _) Hsub1 f Huniq).
    + assert (Hlt : size_typ A0 + size_typ B2 < n) by (simpl in Hle; pose proof (proj2 (spl_size_ltH B0 B1 B2 Hspl)); lia).
      exact (IH _ Hlt D0 A0 B2 (le_n _) Hsub2 f Huniq).
Qed.

Lemma algo_sub_ren : forall D A B, algo_sub D A B ->
  forall f, uniq (ren_ctx f D) ->
    algo_sub (ren_ctx f D) (ren_typ f A) (ren_typ f B).
Proof.
  intros D A B H f Huniq.
  exact (algo_sub_ren_aux (size_typ A + size_typ B) D A B (le_n _) H f Huniq).
Qed.

(* ==================================================================== *)
(* Splitting a source whose target is ordinal: one component suffices.  *)
(* ==================================================================== *)

Lemma algo_sub_spl_source_or_aux : forall n D B C,
  size_typ B + size_typ C <= n ->
  TCWell D -> algo_sub D B C ->
  forall B1 B2, spl B B1 B2 -> ord C ->
    algo_sub D B1 C \/ algo_sub D B2 C.
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D B C Hle HTC HBC B1 B2 Hspl HordC.
  destruct Hspl as
    [ X Y Z1 Z2 HlcX HsplY
    | Ls X Y Z1 Z2 HlcX HsplY
    | l X Z1 Z2 HsplY
    | X Y HlcX HlcY ].
  - (* Sp_arrow *)
    assert (Hspl0 : spl (t_arrow X Y) (t_arrow X Z1) (t_arrow X Z2))
      by (exact (Sp_arrow X Y Z1 Z2 HlcX HsplY)).
    assert (HTB : TWell D (t_arrow X Y))
      by (exact (algo_sub_TWell_source D (t_arrow X Y) C HTC HBC)).
    destruct (spl_TWell_components D (t_arrow X Y) (t_arrow X Z1) (t_arrow X Z2) HTB Hspl0)
      as [HTW1 HTW2].
    destruct (algo_sub_ord_arrow_target D X Y C HordC HBC) as
      [Htop | (A3 & B3 & Heq & Hdom & Hcod & HordB3)].
    + left. exact (S_top D (t_arrow X Z1) C HTW1 HordC Htop).
    + subst C.
      assert (Hlt : size_typ Y + size_typ B3 < n) by (simpl in Hle; lia).
      destruct (IH _ Hlt D Y B3 (le_n _) HTC Hcod Z1 Z2 HsplY HordB3)
        as [HZ1 | HZ2].
      * left. exact (S_arrow D X Z1 A3 B3 HordB3 Hdom HZ1).
      * right. exact (S_arrow D X Z2 A3 B3 HordB3 Hdom HZ2).
  - (* Sp_all *)
    assert (Hspl0 : spl (t_forall X Y) (t_forall X Z1) (t_forall X Z2))
      by (exact (Sp_all Ls X Y Z1 Z2 HlcX HsplY)).
    assert (HTB : TWell D (t_forall X Y))
      by (exact (algo_sub_TWell_source D (t_forall X Y) C HTC HBC)).
    destruct (spl_TWell_components D (t_forall X Y) (t_forall X Z1) (t_forall X Z2) HTB Hspl0)
      as [HTW1 HTW2].
    destruct (algo_sub_ord_forall_target D X Y C HordC HBC) as
      [Htop | (L2 & A3 & B3 & Heq & Hdom & Hbody & Hords)].
    + left. exact (S_top D (t_forall X Z1) C HTW1 HordC Htop).
    + subst C.
      pose (bad := L2 \u [[Z1]] \u [[Z2]] \u [[A3]] \u [[B3]] \u dom D \u typefv_typ_range D \u Ls).
      pose (W0 := fresh (AtomSetImpl.elements bad)).
      assert (HW0bad : W0 \notin bad) by (apply fresh_notin).
      assert (HW0L2 : W0 \notin L2).
      { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_2. exact Hc. }
      assert (HW0Z1 : W0 \notin [[Z1]]).
      { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HW0Z2 : W0 \notin [[Z2]]).
      { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HW0A3 : W0 \notin [[A3]]).
      { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HW0B3 : W0 \notin [[B3]]).
      { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HW0D : W0 \notin dom D).
      { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HW0R : W0 \notin typefv_typ_range D).
      { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HW0LS : W0 \notin Ls).
      { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3. exact Hc. }
      assert (HTWA3 : TWell D A3) by (exact (algo_sub_TWell_source D A3 X HTC Hdom)).
      pose (Dw0 := cons (W0, A3) D).
      assert (HTCw0 : TCWell Dw0).
      { apply (TCW_cons D W0 A3 HTC HTWA3).
        apply uniq_cons; [ apply (TCWell_uniq D HTC) | exact HW0D ]. }
      assert (Hlt0 : size_typ (Y -^ W0) + size_typ (B3 -^ W0) < n).
      { rewrite !size_typ_open_typH. simpl in Hle. lia. }
      assert (Hdist : algo_sub Dw0 (Z1 -^ W0) (B3 -^ W0) \/
                      algo_sub Dw0 (Z2 -^ W0) (B3 -^ W0)).
      { exact (IH _ Hlt0 Dw0 (Y -^ W0) (B3 -^ W0) (le_n _) HTCw0
                 (Hbody W0 HW0L2) (Z1 -^ W0) (Z2 -^ W0)
                 (HsplY W0 HW0LS) (Hords W0 HW0L2)). }
      assert (Hidctx : forall D0, ren_ctx (fun Z => Z) D0 = D0).
      { intro D0. induction D0 as [|[Z A] D0 IHD0]; simpl.
        - reflexivity.
        - rewrite IHD0.
          assert (HA : ren_typ (fun Z => Z) A = A)
            by (apply (ren_typ_id A); intros V HV; reflexivity).
          rewrite HA. reflexivity. }
      destruct Hdist as [Hleft | Hright].
      * left.
        pose (L' := bad \u dom D).
        apply (S_all L' D X Z1 A3 B3).
        -- intros W HW. apply Hords.
           destruct (notin_union W bad (dom D) HW) as [HWbad _].
           intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_2. exact Hc.
        -- exact Hdom.
        -- intros W HW.
           destruct (notin_union W bad (dom D) HW) as [HWbad HWD].
           assert (HWL2 : W \notin L2).
           { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_2. exact Hc. }
           assert (HWZ1 : W \notin [[Z1]]).
           { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
           assert (HWA3 : W \notin [[A3]]).
           { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
           assert (HWB3 : W \notin [[B3]]).
           { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
           assert (HWR : W \notin typefv_typ_range D).
           { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
           pose (fren := rename_var W0 W).
           assert (HfW0 : fren W0 = W) by (unfold fren; apply rename_var_eq).
           assert (HfA3 : ren_typ fren A3 = A3).
           { apply (ren_typ_id A3). intros Z HZ. unfold fren.
             apply rename_var_neq. intro Hc. subst Z. exact (HW0A3 HZ). }
           assert (HfD : ren_ctx fren D = D).
           { transitivity (ren_ctx (fun Z => Z) D).
             - apply (ren_ctx_eq D fren (fun Z => Z)).
               + intros Z HZ. unfold fren. apply rename_var_neq.
                 intro Hc. subst Z. exact (HW0D HZ).
               + intros Z HZ. unfold fren. apply rename_var_neq.
                 intro Hc. subst Z. exact (HW0R HZ).
             - apply Hidctx. }
           assert (Huniq' : uniq (ren_ctx fren Dw0)).
           { unfold Dw0. rewrite ren_ctx_cons. rewrite HfW0, HfA3, HfD.
             apply uniq_cons; [ apply (TCWell_uniq D HTC) | exact HWD ]. }
           pose proof (algo_sub_ren Dw0 (Z1 -^ W0) (B3 -^ W0) Hleft fren Huniq') as Hren.
           unfold Dw0 in Hren. rewrite ren_ctx_cons in Hren.
           rewrite HfW0, HfA3, HfD in Hren.
           unfold fren in Hren.
           rewrite ren_typ_open_rename in Hren; [ | exact HW0Z1 ].
           rewrite ren_typ_open_rename in Hren; [ | exact HW0B3 ].
           exact Hren.
      * right.
        pose (L' := bad \u dom D).
        apply (S_all L' D X Z2 A3 B3).
        -- intros W HW. apply Hords.
           destruct (notin_union W bad (dom D) HW) as [HWbad _].
           intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_2. exact Hc.
        -- exact Hdom.
        -- intros W HW.
           destruct (notin_union W bad (dom D) HW) as [HWbad HWD].
           assert (HWL2 : W \notin L2).
           { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_2. exact Hc. }
           assert (HWZ2 : W \notin [[Z2]]).
           { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
           assert (HWA3 : W \notin [[A3]]).
           { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
           assert (HWB3 : W \notin [[B3]]).
           { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
           assert (HWR : W \notin typefv_typ_range D).
           { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
           pose (fren := rename_var W0 W).
           assert (HfW0 : fren W0 = W) by (unfold fren; apply rename_var_eq).
           assert (HfA3 : ren_typ fren A3 = A3).
           { apply (ren_typ_id A3). intros Z HZ. unfold fren.
             apply rename_var_neq. intro Hc. subst Z. exact (HW0A3 HZ). }
           assert (HfD : ren_ctx fren D = D).
           { transitivity (ren_ctx (fun Z => Z) D).
             - apply (ren_ctx_eq D fren (fun Z => Z)).
               + intros Z HZ. unfold fren. apply rename_var_neq.
                 intro Hc. subst Z. exact (HW0D HZ).
               + intros Z HZ. unfold fren. apply rename_var_neq.
                 intro Hc. subst Z. exact (HW0R HZ).
             - apply Hidctx. }
           assert (Huniq' : uniq (ren_ctx fren Dw0)).
           { unfold Dw0. rewrite ren_ctx_cons. rewrite HfW0, HfA3, HfD.
             apply uniq_cons; [ apply (TCWell_uniq D HTC) | exact HWD ]. }
           pose proof (algo_sub_ren Dw0 (Z2 -^ W0) (B3 -^ W0) Hright fren Huniq') as Hren.
           unfold Dw0 in Hren. rewrite ren_ctx_cons in Hren.
           rewrite HfW0, HfA3, HfD in Hren.
           unfold fren in Hren.
           rewrite ren_typ_open_rename in Hren; [ | exact HW0Z2 ].
           rewrite ren_typ_open_rename in Hren; [ | exact HW0B3 ].
           exact Hren.
  - (* Sp_rcd *)
    assert (Hspl0 : spl (t_rcd l X) (t_rcd l Z1) (t_rcd l Z2))
      by (exact (Sp_rcd l X Z1 Z2 HsplY)).
    assert (HTB : TWell D (t_rcd l X))
      by (exact (algo_sub_TWell_source D (t_rcd l X) C HTC HBC)).
    destruct (spl_TWell_components D (t_rcd l X) (t_rcd l Z1) (t_rcd l Z2) HTB Hspl0)
      as [HTW1 HTW2].
    destruct (algo_sub_ord_rcd_target D l X C HordC HBC) as
      [Htop | (B3 & Heq & Hsub & HordB3)].
    + left. exact (S_top D (t_rcd l Z1) C HTW1 HordC Htop).
    + subst C.
      assert (Hlt : size_typ X + size_typ B3 < n) by (simpl in Hle; lia).
      destruct (IH _ Hlt D X B3 (le_n _) HTC Hsub Z1 Z2 HsplY HordB3)
        as [HZ1 | HZ2].
      * left. exact (S_rcd D l Z1 B3 HordB3 HZ1).
      * right. exact (S_rcd D l Z2 B3 HordB3 HZ2).
  - (* Sp_and *)
    assert (Hspl0 : spl (t_and X Y) X Y) by (exact (Sp_and X Y HlcX HlcY)).
    assert (HTB : TWell D (t_and X Y))
      by (exact (algo_sub_TWell_source D (t_and X Y) C HTC HBC)).
    destruct (algo_sub_ord_and_source D X Y C HTC HTB HordC HBC)
      as [Hleft | Hright].
    + destruct Hleft as [HX _]. left. exact HX.
    + destruct Hright as [HY _]. right. exact HY.
Qed.

Lemma algo_sub_spl_source_or : forall D B C,
  TCWell D -> algo_sub D B C ->
  forall B1 B2, spl B B1 B2 -> ord C ->
    algo_sub D B1 C \/ algo_sub D B2 C.
Proof.
  intros D B C HTC HBC B1 B2 Hspl HordC.
  exact (algo_sub_spl_source_or_aux (size_typ B + size_typ C) D B C
           (le_n _) HTC HBC B1 B2 Hspl HordC).
Qed.
(* ==================================================================== *)
(* Uniform choice for a split codomain under a forall                   *)
(* ==================================================================== *)

Lemma algo_sub_forall_spl_source_or : forall D X Y Z1 Z2 Ls L2 A3 B3,
  TCWell D -> TWell D A3 -> algo_sub D A3 X ->
  (forall W, W \notin Ls -> spl (Y -^ W) (Z1 -^ W) (Z2 -^ W)) ->
  (forall W, W \notin L2 ->
     algo_sub (cons (W,A3) D) (Y -^ W) (B3 -^ W)) ->
  (forall W, W \notin L2 -> ord (B3 -^ W)) ->
  algo_sub D (t_forall X Z1) (t_forall A3 B3) \/
  algo_sub D (t_forall X Z2) (t_forall A3 B3).
Proof.
  intros D X Y Z1 Z2 Ls L2 A3 B3 HTC HTWA3 Hdom Hspl Hbody Hords.
  pose (bad := Ls \u L2 \u [[Z1]] \u [[Z2]] \u [[A3]] \u [[B3]]
               \u dom D \u typefv_typ_range D).
  pose (W0 := fresh (AtomSetImpl.elements bad)).
  assert (HW0bad : W0 \notin bad) by (apply fresh_notin).
  assert (HW0LS : W0 \notin Ls).
  { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_2. exact Hc. }
  assert (HW0L2 : W0 \notin L2).
  { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
  assert (HW0Z1 : W0 \notin [[Z1]]).
  { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
  assert (HW0Z2 : W0 \notin [[Z2]]).
  { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
  assert (HW0A3 : W0 \notin [[A3]]).
  { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
  assert (HW0B3 : W0 \notin [[B3]]).
  { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
  assert (HW0D : W0 \notin dom D).
  { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
  assert (HW0R : W0 \notin typefv_typ_range D).
  { intro Hc. apply HW0bad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3. exact Hc. }
  assert (HTCw0 : TCWell (cons (W0,A3) D)).
  { apply (TCW_cons D W0 A3 HTC HTWA3).
    apply uniq_cons; [ apply (TCWell_uniq D HTC) | exact HW0D ]. }
  assert (Hchoice :
    algo_sub (cons (W0,A3) D) (Z1 -^ W0) (B3 -^ W0) \/
    algo_sub (cons (W0,A3) D) (Z2 -^ W0) (B3 -^ W0)).
  { exact (algo_sub_spl_source_or (cons (W0,A3) D) (Y -^ W0) (B3 -^ W0)
             HTCw0 (Hbody W0 HW0L2) (Z1 -^ W0) (Z2 -^ W0)
             (Hspl W0 HW0LS) (Hords W0 HW0L2)). }
  assert (Hidctx : forall D0, ren_ctx (fun Z => Z) D0 = D0).
  { intro D0. induction D0 as [|[Z A] D0 IHD0]; simpl.
    - reflexivity.
    - rewrite IHD0.
      assert (HA : ren_typ (fun Z => Z) A = A)
        by (apply (ren_typ_id A); intros V HV; reflexivity).
      rewrite HA. reflexivity. }
  pose (L' := bad \u dom D).
  destruct Hchoice as [Hleft | Hright].
  - left. apply (S_all L' D X Z1 A3 B3).
    + intros W HW. apply Hords.
      destruct (notin_union W bad (dom D) HW) as [HWbad _].
      intro Hc. apply HWbad. unfold bad.
      apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc.
    + exact Hdom.
    + intros W HW.
      destruct (notin_union W bad (dom D) HW) as [HWbad HWD].
      assert (HWZ1 : W \notin [[Z1]]).
      { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HWA3 : W \notin [[A3]]).
      { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HWB3 : W \notin [[B3]]).
      { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HWR : W \notin typefv_typ_range D).
      { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3. exact Hc. }
      pose (fren := rename_var W0 W).
      assert (HfW0 : fren W0 = W) by (unfold fren; apply rename_var_eq).
      assert (HfA3 : ren_typ fren A3 = A3).
      { apply (ren_typ_id A3). intros Z HZ. unfold fren.
        apply rename_var_neq. intro Hc. subst Z. exact (HW0A3 HZ). }
      assert (HfD : ren_ctx fren D = D).
      { transitivity (ren_ctx (fun Z => Z) D).
        - apply (ren_ctx_eq D fren (fun Z => Z)).
          + intros Z HZ. unfold fren. apply rename_var_neq.
            intro Hc. subst Z. exact (HW0D HZ).
          + intros Z HZ. unfold fren. apply rename_var_neq.
            intro Hc. subst Z. exact (HW0R HZ).
        - apply Hidctx. }
      assert (Huniq' : uniq (ren_ctx fren (cons (W0,A3) D))).
      { rewrite ren_ctx_cons. rewrite HfW0, HfA3, HfD.
        apply uniq_cons; [ apply (TCWell_uniq D HTC) | exact HWD ]. }
      pose proof (algo_sub_ren (cons (W0,A3) D) (Z1 -^ W0) (B3 -^ W0)
                    Hleft fren Huniq') as Hren.
      rewrite ren_ctx_cons in Hren. rewrite HfW0, HfA3, HfD in Hren.
      unfold fren in Hren.
      rewrite ren_typ_open_rename in Hren; [ | exact HW0Z1 ].
      rewrite ren_typ_open_rename in Hren; [ | exact HW0B3 ].
      exact Hren.
  - right. apply (S_all L' D X Z2 A3 B3).
    + intros W HW. apply Hords.
      destruct (notin_union W bad (dom D) HW) as [HWbad _].
      intro Hc. apply HWbad. unfold bad.
      apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc.
    + exact Hdom.
    + intros W HW.
      destruct (notin_union W bad (dom D) HW) as [HWbad HWD].
      assert (HWZ2 : W \notin [[Z2]]).
      { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HWA3 : W \notin [[A3]]).
      { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HWB3 : W \notin [[B3]]).
      { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_2. exact Hc. }
      assert (HWR : W \notin typefv_typ_range D).
      { intro Hc. apply HWbad. unfold bad. apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3; apply AtomSetImpl.union_3. exact Hc. }
      pose (fren := rename_var W0 W).
      assert (HfW0 : fren W0 = W) by (unfold fren; apply rename_var_eq).
      assert (HfA3 : ren_typ fren A3 = A3).
      { apply (ren_typ_id A3). intros Z HZ. unfold fren.
        apply rename_var_neq. intro Hc. subst Z. exact (HW0A3 HZ). }
      assert (HfD : ren_ctx fren D = D).
      { transitivity (ren_ctx (fun Z => Z) D).
        - apply (ren_ctx_eq D fren (fun Z => Z)).
          + intros Z HZ. unfold fren. apply rename_var_neq.
            intro Hc. subst Z. exact (HW0D HZ).
          + intros Z HZ. unfold fren. apply rename_var_neq.
            intro Hc. subst Z. exact (HW0R HZ).
        - apply Hidctx. }
      assert (Huniq' : uniq (ren_ctx fren (cons (W0,A3) D))).
      { rewrite ren_ctx_cons. rewrite HfW0, HfA3, HfD.
        apply uniq_cons; [ apply (TCWell_uniq D HTC) | exact HWD ]. }
      pose proof (algo_sub_ren (cons (W0,A3) D) (Z2 -^ W0) (B3 -^ W0)
                    Hright fren Huniq') as Hren.
      rewrite ren_ctx_cons in Hren. rewrite HfW0, HfA3, HfD in Hren.
      unfold fren in Hren.
      rewrite ren_typ_open_rename in Hren; [ | exact HW0Z2 ].
      rewrite ren_typ_open_rename in Hren; [ | exact HW0B3 ].
      exact Hren.
Qed.

(* ==================================================================== *)
(* Transitivity of algorithmic subtyping, with well-formedness           *)
(* ==================================================================== *)

Lemma algo_sub_trans_aux : forall N D A B C,
  size_typ A + size_typ B + size_typ C <= N ->
  TCWell D -> TWell D A -> TWell D B -> TWell D C ->
  algo_sub D A B -> algo_sub D B C -> algo_sub D A C.
Proof.
  induction N as [N IH] using lt_wf_ind.
  intros D A B C Hle HTC HTA HTB HTCc H1 H2.
  destruct (ord_dec_TWell D C HTCc) as [HordC | HnonordC].
  - (* target C is ord: inspect the first derivation *)
    destruct H1 as
      [ D0 X0 HTC0 HTW0
      | D0 HTC0
      | D0 A0 B0 HTW0 HordB0 Htop0
      | D0 A0 HTC0 HTW0 HordA0
      | D0 A0 B0 C0 HTWB HordC0 Hsub
      | D0 A0 B0 C0 HTWA HordC0 Hsub
      | D0 A1 B1 A2 B2 HordB2 Hsub1 Hsub2
      | L D0 A1 A2 B1 B2 Hords Hsub1 Hbody
      | D0 l A0 B0 HordB0 Hsub
      | D0 A0 B0 B1 B2 Hspl Hsub1 Hsub2 ].
    + (* S_var *) exact H2.
    + (* S_int *) exact H2.
    + (* S_top *) apply (S_top D0 A0 C HTW0 HordC).
      exact (algo_sub_topLike_genH D0 B0 C H2 Htop0).
    + (* S_bot *) apply (S_bot D0 C HTC0 HTCc HordC).
    + (* S_andl *)
      assert (HTA0 : TWell D0 A0) by (exact (proj1 (TWell_and_inv D0 A0 B0 HTA))).
      assert (HTWC0 : TWell D0 C0) by (exact (algo_sub_TWell_target D0 A0 C0 HTC Hsub)).
      assert (Hlt : size_typ A0 + size_typ C0 + size_typ C < N) by (simpl in Hle; lia).
      assert (Ht : algo_sub D0 A0 C) by
        (exact (IH _ Hlt D0 A0 C0 C (le_n _) HTC HTA0 HTWC0 HTCc Hsub H2)).
      exact (S_andl D0 A0 B0 C HTWB HordC Ht).
    + (* S_andr *)
      assert (HTB0 : TWell D0 B0) by (exact (proj2 (TWell_and_inv D0 A0 B0 HTA))).
      assert (HTWC0 : TWell D0 C0) by (exact (algo_sub_TWell_target D0 B0 C0 HTC Hsub)).
      assert (Hlt : size_typ B0 + size_typ C0 + size_typ C < N) by (simpl in Hle; lia).
      assert (Ht : algo_sub D0 B0 C) by
        (exact (IH _ Hlt D0 B0 C0 C (le_n _) HTC HTB0 HTWC0 HTCc Hsub H2)).
      exact (S_andr D0 A0 B0 C HTWA HordC Ht).
    + (* S_arrow *)
      destruct (algo_sub_ord_arrow_target D0 A2 B2 C HordC H2) as
        [Htop | (A3 & B3 & Heq & Hda & Hdb & HordB3)].
      * apply (S_top D0 (t_arrow A1 B1) C HTA HordC Htop).
      * subst C.
        assert (HTWA3 : TWell D0 A3) by (exact (algo_sub_TWell_source D0 A3 A2 HTC Hda)).
        assert (HTWA2 : TWell D0 A2) by (exact (algo_sub_TWell_target D0 A3 A2 HTC Hda)).
        assert (HTWA1 : TWell D0 A1) by (exact (algo_sub_TWell_target D0 A2 A1 HTC Hsub1)).
        assert (HTWB1 : TWell D0 B1) by (exact (algo_sub_TWell_source D0 B1 B2 HTC Hsub2)).
        assert (HTWB2 : TWell D0 B2) by (exact (algo_sub_TWell_target D0 B1 B2 HTC Hsub2)).
        assert (HTWB3 : TWell D0 B3) by (exact (algo_sub_TWell_target D0 B2 B3 HTC Hdb)).
        assert (HltA : size_typ A3 + size_typ A2 + size_typ A1 < N)
          by (simpl in Hle; lia).
        assert (HltB : size_typ B1 + size_typ B2 + size_typ B3 < N)
          by (simpl in Hle; lia).
        assert (Hdom : algo_sub D0 A3 A1) by
          (exact (IH _ HltA D0 A3 A2 A1 (le_n _) HTC HTWA3 HTWA2 HTWA1 Hda Hsub1)).
        assert (Hcod : algo_sub D0 B1 B3) by
          (exact (IH _ HltB D0 B1 B2 B3 (le_n _) HTC HTWB1 HTWB2 HTWB3 Hsub2 Hdb)).
        exact (S_arrow D0 A1 B1 A3 B3 HordB3 Hdom Hcod).
    + (* S_all *)
      destruct (algo_sub_ord_forall_target D0 B1 B2 C HordC H2) as
        [Htop | (L2 & C1 & C2 & Heq & Hdom & Hb2 & Hords2)].
      * apply (S_top D0 (t_forall A1 A2) C HTA HordC Htop).
      * subst C.
        assert (HTWC1 : TWell D0 C1) by (exact (algo_sub_TWell_source D0 C1 B1 HTC Hdom)).
        assert (HTWB1 : TWell D0 B1) by (exact (algo_sub_TWell_target D0 C1 B1 HTC Hdom)).
        assert (HTWA1 : TWell D0 A1) by (exact (algo_sub_TWell_target D0 B1 A1 HTC Hsub1)).
        assert (HTWB1' : TWell D0 B1) by (exact (TWell_all_inv D0 B1 B2 HTB)).
        assert (HltD : size_typ C1 + size_typ B1 + size_typ A1 < N)
          by (simpl in Hle; lia).
        assert (HdomT : algo_sub D0 C1 A1) by
          (exact (IH _ HltD D0 C1 B1 A1 (le_n _) HTC HTWC1 HTWB1 HTWA1 Hdom Hsub1)).
        pose (L' := (L \u L2) \u dom D0).
        apply (S_all L' D0 A1 A2 C1 C2).
        -- intros Z HZ. apply Hords2.
           destruct (notin_union Z (L \u L2) (dom D0) HZ) as [HZ12 _].
           destruct (notin_union Z L L2 HZ12) as [_ HZL2]. exact HZL2.
        -- exact HdomT.
        -- intros Z HZ.
           destruct (notin_union Z (L \u L2) (dom D0) HZ) as [HZ12 HZD].
           destruct (notin_union Z L L2 HZ12) as [HZL HZL2].
           assert (Hbody1 : algo_sub (cons (Z,B1) D0) (A2 -^ Z) (B2 -^ Z))
             by (exact (Hbody Z HZL)).
           assert (HTCsrc : TCWell (cons (Z,B1) D0)).
           { apply (TCW_cons D0 Z B1 HTC HTWB1').
             apply uniq_cons; [ apply (TCWell_uniq D0 HTC) | exact HZD ]. }
           assert (HTCtgt : TCWell (cons (Z,C1) D0)).
           { apply (TCW_cons D0 Z C1 HTC HTWC1).
             apply uniq_cons; [ apply (TCWell_uniq D0 HTC) | exact HZD ]. }
           assert (HTWBA : TWell (cons (Z,B1) D0) (A2 -^ Z))
             by (exact (algo_sub_TWell_source (cons (Z,B1) D0) (A2 -^ Z) (B2 -^ Z)
                   HTCsrc Hbody1)).
           assert (Hmap : map fst (cons (Z,B1) D0) = map fst (cons (Z,C1) D0))
             by (simpl; reflexivity).
           assert (Rm : forall Y T, binds Y T (cons (Z,B1) D0) ->
                      exists T', binds Y T' (cons (Z,C1) D0) /\ (botLike T -> botLike T')).
           { intros Y T Hb. apply binds_cons_1 in Hb. destruct Hb as [Hx | Hin].
             - destruct Hx as [HY HT]. subst. exists C1. split.
               + apply binds_cons_2; reflexivity.
               + intro Hbl. exact (algo_sub_botLike_gen D0 C1 B1 Hdom Hbl).
             - exists T. split.
               + apply binds_cons_3; exact Hin.
               + intro Hbl; exact Hbl. }
           assert (Hbody1' : algo_sub (cons (Z,C1) D0) (A2 -^ Z) (B2 -^ Z))
             by (exact (algo_sub_ctx_morph (cons (Z,B1) D0) (A2 -^ Z) (B2 -^ Z)
                   HTCsrc Hbody1 (cons (Z,C1) D0) HTCtgt Hmap Rm)).
           assert (Hb2Z : algo_sub (cons (Z,C1) D0) (B2 -^ Z) (C2 -^ Z))
             by (exact (Hb2 Z HZL2)).
           assert (HTWbodyA : TWell (cons (Z,C1) D0) (A2 -^ Z))
             by (exact (algo_sub_TWell_source (cons (Z,C1) D0) (A2 -^ Z) (B2 -^ Z)
                   HTCtgt Hbody1')).
           assert (HTWbodyB : TWell (cons (Z,C1) D0) (B2 -^ Z))
             by (exact (algo_sub_TWell_target (cons (Z,C1) D0) (A2 -^ Z) (B2 -^ Z)
                   HTCtgt Hbody1')).
           assert (HTWbodyC : TWell (cons (Z,C1) D0) (C2 -^ Z))
             by (exact (algo_sub_TWell_target (cons (Z,C1) D0) (B2 -^ Z) (C2 -^ Z)
                   HTCtgt Hb2Z)).
           assert (Hltbody : size_typ (A2 -^ Z) + size_typ (B2 -^ Z) + size_typ (C2 -^ Z) < N).
           { rewrite !size_typ_open_typH. simpl in *. lia. }
           exact (IH _ Hltbody (cons (Z,C1) D0) (A2 -^ Z) (B2 -^ Z) (C2 -^ Z)
                    (le_n _) HTCtgt HTWbodyA HTWbodyB HTWbodyC Hbody1' Hb2Z).
    + (* S_rcd *)
      destruct (algo_sub_ord_rcd_target D0 l B0 C HordC H2) as
        [Htop | (B2 & Heq & Hsub2 & HordB2)].
      * apply (S_top D0 (t_rcd l A0) C HTA HordC Htop).
      * subst C.
        assert (HTWA0 : TWell D0 A0) by (exact (TWell_rcd_inv D0 l A0 HTA)).
        assert (HTWB0 : TWell D0 B0) by (exact (algo_sub_TWell_source D0 B0 B2 HTC Hsub2)).
        assert (HTWB2 : TWell D0 B2) by (exact (algo_sub_TWell_target D0 B0 B2 HTC Hsub2)).
        assert (Hlt : size_typ A0 + size_typ B0 + size_typ B2 < N)
          by (simpl in Hle; lia).
        assert (Ht : algo_sub D0 A0 B2) by
          (exact (IH _ Hlt D0 A0 B0 B2 (le_n _) HTC HTWA0 HTWB0 HTWB2 Hsub Hsub2)).
        exact (S_rcd D0 l A0 B2 HordB2 Ht).
    + (* S_and: the first derivation splits its target *)
      assert (HsplB : spl B0 B1 B2) by (exact Hspl).
      destruct Hspl as
        [ X Y Z1 Z2 HlcX HsplY
        | Ls X Y Z1 Z2 HlcX HsplY
        | l X Z1 Z2 HsplY
        | X Y HlcX HlcY ].
      * (* Sp_arrow *)
        assert (Hspl0 : spl (t_arrow X Y) (t_arrow X Z1) (t_arrow X Z2))
          by (exact (Sp_arrow X Y Z1 Z2 HlcX HsplY)).
        destruct (algo_sub_ord_arrow_target D0 X Y C HordC H2) as
          [Htop | (A3 & B3 & Heq & Hda & Hdb & HordB3)].
        -- assert (HTWB1 : TWell D0 (t_arrow X Z1))
             by (exact (proj1 (spl_TWell_components D0 (t_arrow X Y) (t_arrow X Z1) (t_arrow X Z2) HTB Hspl0))).
           assert (HB1C : algo_sub D0 (t_arrow X Z1) C)
             by (exact (S_top D0 (t_arrow X Z1) C HTWB1 HordC Htop)).
           assert (Hsm : size_typ A0 + size_typ (t_arrow X Z1) + size_typ C < N).
           { pose proof (proj1 (spl_size_ltH (t_arrow X Y) (t_arrow X Z1) (t_arrow X Z2) Hspl0)).
             lia. }
           exact (IH _ Hsm D0 A0 (t_arrow X Z1) C (le_n _) HTC HTA HTWB1 HTCc Hsub1 HB1C).
        -- subst C.
           assert (HTWB1 : TWell D0 (t_arrow X Z1))
             by (exact (proj1 (spl_TWell_components D0 (t_arrow X Y) (t_arrow X Z1) (t_arrow X Z2) HTB Hspl0))).
           assert (HTWY : TWell D0 Y) by (exact (proj2 (TWell_arrow_inv D0 X Y HTB))).
           assert (HTWZ1 : TWell D0 Z1)
             by (exact (proj2 (TWell_arrow_inv D0 X Z1 HTWB1))).
           assert (HTWB3 : TWell D0 B3) by (exact (proj2 (TWell_arrow_inv D0 A3 B3 HTCc))).
           destruct (spl_TWell_components D0 Y Z1 Z2 HTWY HsplY) as [HZW1 HZW2].
           destruct (algo_sub_spl_source_or D0 Y B3 HTC Hdb Z1 Z2 HsplY HordB3)
             as [HZ1B3 | HZ2B3].
           ++ assert (HB1C : algo_sub D0 (t_arrow X Z1) (t_arrow A3 B3))
                by (exact (S_arrow D0 X Z1 A3 B3 HordB3 Hda HZ1B3)).
              assert (Hsm : size_typ A0 + size_typ (t_arrow X Z1) + size_typ (t_arrow A3 B3) < N).
              { pose proof (proj1 (spl_size_ltH (t_arrow X Y) (t_arrow X Z1) (t_arrow X Z2) Hspl0)).
                lia. }
              exact (IH _ Hsm D0 A0 (t_arrow X Z1) (t_arrow A3 B3) (le_n _)
                       HTC HTA HTWB1 HTCc Hsub1 HB1C).
           ++ assert (HTWB2 : TWell D0 (t_arrow X Z2))
                by (exact (proj2 (spl_TWell_components D0 (t_arrow X Y) (t_arrow X Z1) (t_arrow X Z2) HTB Hspl0))).
              assert (HB2C : algo_sub D0 (t_arrow X Z2) (t_arrow A3 B3))
                by (exact (S_arrow D0 X Z2 A3 B3 HordB3 Hda HZ2B3)).
              assert (Hsm : size_typ A0 + size_typ (t_arrow X Z2) + size_typ (t_arrow A3 B3) < N).
              { pose proof (proj2 (spl_size_ltH (t_arrow X Y) (t_arrow X Z1) (t_arrow X Z2) Hspl0)).
                lia. }
              exact (IH _ Hsm D0 A0 (t_arrow X Z2) (t_arrow A3 B3) (le_n _)
                       HTC HTA HTWB2 HTCc Hsub2 HB2C).
      * (* Sp_all *)
        assert (Hspl0 : spl (t_forall X Y) (t_forall X Z1) (t_forall X Z2))
          by (exact (Sp_all Ls X Y Z1 Z2 HlcX HsplY)).
        destruct (algo_sub_ord_forall_target D0 X Y C HordC H2) as
          [Htop | (L2 & A3 & B3 & Heq & Hdom & Hb2 & Hords2)].
        -- assert (HTWB1 : TWell D0 (t_forall X Z1))
             by (exact (proj1 (spl_TWell_components D0 (t_forall X Y) (t_forall X Z1) (t_forall X Z2) HTB Hspl0))).
           assert (HB1C : algo_sub D0 (t_forall X Z1) C)
             by (exact (S_top D0 (t_forall X Z1) C HTWB1 HordC Htop)).
           assert (Hsm : size_typ A0 + size_typ (t_forall X Z1) + size_typ C < N).
           { pose proof (proj1 (spl_size_ltH (t_forall X Y) (t_forall X Z1) (t_forall X Z2) Hspl0)).
             lia. }
           exact (IH _ Hsm D0 A0 (t_forall X Z1) C (le_n _) HTC HTA HTWB1 HTCc Hsub1 HB1C).
        -- subst C.
           assert (HTWA3 : TWell D0 A3) by (exact (algo_sub_TWell_source D0 A3 X HTC Hdom)).
           destruct (algo_sub_forall_spl_source_or D0 X Y Z1 Z2 Ls L2 A3 B3
                       HTC HTWA3 Hdom HsplY Hb2 Hords2) as [HB1C | HB2C].
           ++ assert (HTWB1 : TWell D0 (t_forall X Z1))
                by (exact (proj1 (spl_TWell_components D0 (t_forall X Y) (t_forall X Z1) (t_forall X Z2) HTB Hspl0))).
              assert (Hsm : size_typ A0 + size_typ (t_forall X Z1) + size_typ (t_forall A3 B3) < N).
              { pose proof (proj1 (spl_size_ltH (t_forall X Y) (t_forall X Z1) (t_forall X Z2) Hspl0)).
                lia. }
              exact (IH _ Hsm D0 A0 (t_forall X Z1) (t_forall A3 B3) (le_n _)
                       HTC HTA HTWB1 HTCc Hsub1 HB1C).
           ++ assert (HTWB2 : TWell D0 (t_forall X Z2))
                by (exact (proj2 (spl_TWell_components D0 (t_forall X Y) (t_forall X Z1) (t_forall X Z2) HTB Hspl0))).
              assert (Hsm : size_typ A0 + size_typ (t_forall X Z2) + size_typ (t_forall A3 B3) < N).
              { pose proof (proj2 (spl_size_ltH (t_forall X Y) (t_forall X Z1) (t_forall X Z2) Hspl0)).
                lia. }
              exact (IH _ Hsm D0 A0 (t_forall X Z2) (t_forall A3 B3) (le_n _)
                       HTC HTA HTWB2 HTCc Hsub2 HB2C).
      * (* Sp_rcd *)
        assert (Hspl0 : spl (t_rcd l X) (t_rcd l Z1) (t_rcd l Z2))
          by (exact (Sp_rcd l X Z1 Z2 HsplY)).
        destruct (algo_sub_ord_rcd_target D0 l X C HordC H2) as
          [Htop | (B3 & Heq & HRcdSub & HordB3)].
        -- assert (HTWB1 : TWell D0 (t_rcd l Z1))
             by (exact (proj1 (spl_TWell_components D0 (t_rcd l X) (t_rcd l Z1) (t_rcd l Z2) HTB Hspl0))).
           assert (HB1C : algo_sub D0 (t_rcd l Z1) C)
             by (exact (S_top D0 (t_rcd l Z1) C HTWB1 HordC Htop)).
           assert (Hsm : size_typ A0 + size_typ (t_rcd l Z1) + size_typ C < N).
           { pose proof (proj1 (spl_size_ltH (t_rcd l X) (t_rcd l Z1) (t_rcd l Z2) Hspl0)).
             lia. }
           exact (IH _ Hsm D0 A0 (t_rcd l Z1) C (le_n _) HTC HTA HTWB1 HTCc Hsub1 HB1C).
        -- subst C.
           assert (HTWX : TWell D0 X) by (exact (TWell_rcd_inv D0 l X HTB)).
           assert (HTWZ1 : TWell D0 Z1) by (exact (TWell_rcd_inv D0 l Z1
             (proj1 (spl_TWell_components D0 (t_rcd l X) (t_rcd l Z1) (t_rcd l Z2) HTB Hspl0)))).
           assert (HTWB3 : TWell D0 B3) by (exact (TWell_rcd_inv D0 l B3 HTCc)).
           assert (HTWB1 : TWell D0 (t_rcd l Z1))
             by (exact (proj1 (spl_TWell_components D0 (t_rcd l X) (t_rcd l Z1) (t_rcd l Z2) HTB Hspl0))).
           assert (HTWZ2 : TWell D0 Z2) by (exact (TWell_rcd_inv D0 l Z2
             (proj2 (spl_TWell_components D0 (t_rcd l X) (t_rcd l Z1) (t_rcd l Z2) HTB Hspl0)))).
           destruct (algo_sub_spl_source_or D0 X B3 HTC HRcdSub Z1 Z2 HsplY HordB3)
             as [HZ1B3 | HZ2B3].
           ++ assert (HB1C : algo_sub D0 (t_rcd l Z1) (t_rcd l B3))
                by (exact (S_rcd D0 l Z1 B3 HordB3 HZ1B3)).
              assert (Hsm : size_typ A0 + size_typ (t_rcd l Z1) + size_typ (t_rcd l B3) < N).
              { pose proof (proj1 (spl_size_ltH (t_rcd l X) (t_rcd l Z1) (t_rcd l Z2) Hspl0)).
                lia. }
              exact (IH _ Hsm D0 A0 (t_rcd l Z1) (t_rcd l B3) (le_n _)
                       HTC HTA HTWB1 HTCc Hsub1 HB1C).
           ++ assert (HTWB2 : TWell D0 (t_rcd l Z2))
                by (exact (proj2 (spl_TWell_components D0 (t_rcd l X) (t_rcd l Z1) (t_rcd l Z2) HTB Hspl0))).
              assert (HB2C : algo_sub D0 (t_rcd l Z2) (t_rcd l B3))
                by (exact (S_rcd D0 l Z2 B3 HordB3 HZ2B3)).
              assert (Hsm : size_typ A0 + size_typ (t_rcd l Z2) + size_typ (t_rcd l B3) < N).
              { pose proof (proj2 (spl_size_ltH (t_rcd l X) (t_rcd l Z1) (t_rcd l Z2) Hspl0)).
                lia. }
              exact (IH _ Hsm D0 A0 (t_rcd l Z2) (t_rcd l B3) (le_n _)
                       HTC HTA HTWB2 HTCc Hsub2 HB2C).
      * (* Sp_and *)
        assert (Hspl0 : spl (t_and X Y) X Y) by (exact (Sp_and X Y HlcX HlcY)).
        destruct (algo_sub_ord_and_source D0 X Y C HTC HTB HordC H2)
          as [Hleft | Hright].
        -- destruct Hleft as [HXC _].
           destruct (TWell_and_inv D0 X Y HTB) as [HTWX HTWY].
           assert (Hsm : size_typ A0 + size_typ X + size_typ C < N).
           { pose proof (proj1 (spl_size_ltH (t_and X Y) X Y Hspl0)).
             lia. }
           exact (IH _ Hsm D0 A0 X C (le_n _) HTC HTA HTWX HTCc Hsub1 HXC).
        -- destruct Hright as [HYC _].
           destruct (TWell_and_inv D0 X Y HTB) as [HTWX HTWY].
           assert (Hsm : size_typ A0 + size_typ Y + size_typ C < N).
           { pose proof (proj2 (spl_size_ltH (t_and X Y) X Y Hspl0)).
             lia. }
           exact (IH _ Hsm D0 A0 Y C (le_n _) HTC HTA HTWY HTCc Hsub2 HYC).
  - (* target C splits *)
    destruct (TWell_coverage_TC D C HTC HTCc) as [Ho | (C1 & C2 & Hspl)].
    + exfalso. exact (HnonordC Ho).
    + destruct (spl_TWell_components D C C1 C2 HTCc Hspl) as [HTW1 HTW2].
      assert (Hs1 : algo_sub D B C1) by (exact (agentE.algo_sub_spl_l D B C C1 C2 H2 Hspl)).
      assert (Hs2 : algo_sub D B C2) by (exact (agentE.algo_sub_spl_r D B C C1 C2 H2 Hspl)).
      assert (Hlt1 : size_typ A + size_typ B + size_typ C1 < N).
      { pose proof (proj1 (spl_size_ltH C C1 C2 Hspl)). lia. }
      assert (Hlt2 : size_typ A + size_typ B + size_typ C2 < N).
      { pose proof (proj2 (spl_size_ltH C C1 C2 Hspl)). lia. }
      apply (S_and D A C C1 C2 Hspl).
      * exact (IH _ Hlt1 D A B C1 (le_n _) HTC HTA HTB HTW1 H1 Hs1).
      * exact (IH _ Hlt2 D A B C2 (le_n _) HTC HTA HTB HTW2 H1 Hs2).
Qed.

Theorem algo_sub_trans_TWell : forall D A B C,
  TCWell D -> TWell D A -> TWell D B -> TWell D C ->
  algo_sub D A B -> algo_sub D B C -> algo_sub D A C.
Proof.
  intros D A B C HTC HTA HTB HTCc H1 H2.
  exact (algo_sub_trans_aux (size_typ A + size_typ B + size_typ C)
           D A B C (le_n _) HTC HTA HTB HTCc H1 H2).
Qed.
End agentH3.
Import agentH3.

Module agentH4.
Import ListNotations.

(* ==================================================================== *)
(* Changing the type of one type-context binding, at an arbitrary       *)
(* position (a prefix is added by the Typ_tabs induction).              *)
(* ==================================================================== *)

Lemma map_fst_ctx_change : forall (Dpre Dsuf : tctx) (Z:typevar) (Told Tnew:typ),
  map fst (Dpre ++ (Z,Told)::Dsuf) =
  map fst (Dpre ++ (Z,Tnew)::Dsuf).
Proof.
  induction Dpre as [|[W C] Dpre' IH]; intros Dsuf Z Told Tnew; simpl.
  - reflexivity.
  - rewrite (IH Dsuf Z Told Tnew). reflexivity.
Qed.

Lemma uniq_map_fst_irrel : forall (l1 l2 : tctx),
  map fst l1 = map fst l2 -> uniq l1 -> uniq l2.
Proof.
  induction l1 as [|[x a] l1' IH]; intros l2 Hmap Hu.
  - destruct l2 as [|[y b] l2']; [apply uniq_nil | simpl in Hmap; discriminate Hmap].
  - destruct l2 as [|[y b] l2']; [simpl in Hmap; discriminate Hmap |].
    simpl in Hmap. injection Hmap as Hxy Htail. subst y.
    inversion Hu as [| ? ? ? Hu' HxE]; subst.
    apply uniq_cons.
    + apply (IH l2' Htail Hu').
    + intro Hin. apply HxE.
      exact (in_dom_map_fst l2' l1' x (eq_sym Htail) Hin).
Qed.

Lemma TCWell_suffix : forall (Dpre Dsuf : tctx) (Z:typevar) (Told:typ),
  TCWell (Dpre ++ (Z,Told)::Dsuf) -> TCWell Dsuf.
Proof.
  induction Dpre as [|[W C] Dpre' IH]; intros Dsuf Z Told H.
  - simpl in H. exact (proj1 (TCWell_cons_inv Dsuf Z Told H)).
  - simpl in H.
    exact (IH Dsuf Z Told
             (proj1 (TCWell_cons_inv (Dpre' ++ (Z,Told)::Dsuf) W C H))).
Qed.

Lemma TCWell_ctx_change : forall (Dpre Dsuf : tctx) (Z:typevar) (Told Tnew:typ),
  TCWell (Dpre ++ (Z,Told)::Dsuf) ->
  algo_sub Dsuf Tnew Told ->
  TCWell (Dpre ++ (Z,Tnew)::Dsuf).
Proof.
  induction Dpre as [|[W C0] Dpre' IH]; intros Dsuf Z Told Tnew HTC Hrel.
  - simpl in HTC. simpl.
    destruct (TCWell_cons_inv Dsuf Z Told HTC) as [HTCsuf HTold].
    apply (TCW_cons Dsuf Z Tnew HTCsuf).
    + exact (algo_sub_TWell_source Dsuf Tnew Told HTCsuf Hrel).
    + apply uniq_map_fst_irrel with (l1 := (Z,Told)::Dsuf).
      * simpl. reflexivity.
      * apply TCWell_uniq. simpl. exact HTC.
  - simpl in HTC. simpl.
    destruct (TCWell_cons_inv (Dpre' ++ (Z,Told)::Dsuf) W C0 HTC)
      as [HTCtail HTW].
    apply (TCW_cons (Dpre' ++ (Z,Tnew)::Dsuf) W C0).
    + apply (IH Dsuf Z Told Tnew HTCtail Hrel).
    + apply (TWell_dom_irrel (Dpre' ++ (Z,Told)::Dsuf) C0 HTW
             (Dpre' ++ (Z,Tnew)::Dsuf)).
      apply map_fst_ctx_change.
    + apply uniq_map_fst_irrel with
        (l1 := (W,C0)::(Dpre' ++ (Z,Told)::Dsuf)).
      * simpl. rewrite (map_fst_ctx_change Dpre' Dsuf Z Told Tnew).
        reflexivity.
      * apply TCWell_uniq. simpl. exact HTC.
Qed.

Lemma CWell_map_fst : forall D1 G,
  CWell D1 G -> forall D2, map fst D1 = map fst D2 -> CWell D2 G.
Proof.
  intros D1 G H. induction H as [D1 | D1 G x A HCW IH HTW];
    intros D2 Hmap.
  - apply CW_empty.
  - apply CW_cons.
    + apply IH. exact Hmap.
    + apply (TWell_dom_irrel D1 A HTW D2 Hmap).
Qed.

Lemma TCWell_binds_TWell : forall (D:tctx), TCWell D ->
  forall (Y:typevar) (C:typ), binds Y C D -> TWell D C.
Proof.
  intros D HTC. induction HTC as [| D0 X0 A0 HTC0 IH HTW Hu].
  - intros Y C Hb. simpl in Hb. inversion Hb.
  - intros Y C Hb. simpl in Hb.
    apply binds_cons_1 in Hb. destruct Hb as [Heq | Hin].
    + destruct Heq as [HY HC]. subst Y. subst C.
      apply (TWell_weaken D0 (cons (X0,A0) D0) A0 HTW).
      intros A B Hab. apply binds_cons_3. exact Hab.
    + apply (TWell_weaken D0 (cons (X0,A0) D0) C (IH Y C Hin)).
      intros A B Hab. apply binds_cons_3. exact Hab.
Qed.

(* The binding map used for the transport lemmas, strengthened with a
   subtyping relation between the new and the old binding type. *)

Lemma ctx_change_Rsub : forall (Dpre Dsuf : tctx) (Z:typevar) (Told Tnew:typ),
  TCWell (Dpre ++ (Z,Told)::Dsuf) ->
  algo_sub Dsuf Tnew Told ->
  forall Y C, binds Y C (Dpre ++ (Z,Told)::Dsuf) ->
    exists C', binds Y C' (Dpre ++ (Z,Tnew)::Dsuf) /\
      algo_sub (Dpre ++ (Z,Tnew)::Dsuf) C' C.
Proof.
  induction Dpre as [|[W C0] Dpre' IH]; intros Dsuf Z Told Tnew HTC Hrel.
  - intros Y C Hb. simpl in Hb. simpl.
    assert (HTCsuf : TCWell Dsuf).
    { apply (TCWell_suffix nil Dsuf Z Told). simpl. exact HTC. }
    assert (HTCnew : TCWell ((Z,Tnew)::Dsuf)).
    { exact (TCWell_ctx_change nil Dsuf Z Told Tnew HTC Hrel). }
    apply binds_cons_1 in Hb. destruct Hb as [Heq | Hin].
    + destruct Heq as [HY HC]. subst Y. subst C.
      exists Tnew. split.
      * apply binds_cons_2; reflexivity.
      * eapply algo_sub_weaken.
        -- exact HTCsuf.
        -- exact HTCnew.
        -- intros A B Hab. apply binds_cons_3. exact Hab.
        -- exact Hrel.
    + exists C. split.
      * apply binds_cons_3. exact Hin.
      * exact (agentH.algo_sub_refl_TWell ((Z,Tnew)::Dsuf) C HTCnew
                 (TCWell_binds_TWell ((Z,Tnew)::Dsuf) HTCnew Y C
                    (binds_cons_3 typ Y Z C Tnew Dsuf Hin))).
  - intros Y C Hb. simpl in Hb. simpl.
    destruct (TCWell_cons_inv (Dpre' ++ (Z,Told)::Dsuf) W C0 HTC)
      as [HTCtail HTW].
    assert (HTCnew' : TCWell (Dpre' ++ (Z,Tnew)::Dsuf)).
    { exact (TCWell_ctx_change Dpre' Dsuf Z Told Tnew HTCtail Hrel). }
    assert (HTCnew : TCWell ((W,C0)::(Dpre' ++ (Z,Tnew)::Dsuf))).
    { apply TCW_cons.
      - exact HTCnew'.
      - apply (TWell_dom_irrel (Dpre' ++ (Z,Told)::Dsuf) C0 HTW
                 (Dpre' ++ (Z,Tnew)::Dsuf)).
        apply map_fst_ctx_change.
      - apply uniq_map_fst_irrel with
          (l1 := (W,C0)::(Dpre' ++ (Z,Told)::Dsuf)).
        + simpl. rewrite (map_fst_ctx_change Dpre' Dsuf Z Told Tnew).
          reflexivity.
        + apply TCWell_uniq. simpl. exact HTC. }
    apply binds_cons_1 in Hb. destruct Hb as [Heq | Hin].
    + destruct Heq as [HY HC]. subst Y. subst C.
      exists C0. split.
      * apply binds_cons_2; reflexivity.
      * exact (agentH.algo_sub_refl_TWell
                 ((W,C0)::(Dpre' ++ (Z,Tnew)::Dsuf)) C0 HTCnew
                 (TCWell_binds_TWell
                    ((W,C0)::(Dpre' ++ (Z,Tnew)::Dsuf)) HTCnew W C0
                    (binds_cons_2 typ W W C0 C0 (Dpre' ++ (Z,Tnew)::Dsuf) eq_refl eq_refl))).
    + destruct (IH Dsuf Z Told Tnew HTCtail Hrel Y C Hin)
        as (C' & Hb' & Hsub).
      exists C'. split.
      * apply binds_cons_3. exact Hb'.
      * eapply algo_sub_weaken.
        -- exact HTCnew'.
        -- exact HTCnew.
        -- intros A B Hab. apply binds_cons_3. exact Hab.
        -- exact Hsub.
Qed.

Lemma ctx_change_Rbot : forall (Dpre Dsuf : tctx) (Z:typevar) (Told Tnew:typ),
  TCWell (Dpre ++ (Z,Told)::Dsuf) ->
  algo_sub Dsuf Tnew Told ->
  forall Y C, binds Y C (Dpre ++ (Z,Told)::Dsuf) ->
    exists C', binds Y C' (Dpre ++ (Z,Tnew)::Dsuf) /\
      (botLike C -> botLike C').
Proof.
  intros Dpre Dsuf Z Told Tnew HTC Hrel Y C Hb.
  destruct (ctx_change_Rsub Dpre Dsuf Z Told Tnew HTC Hrel Y C Hb)
    as (C' & Hb' & Hsub).
  exists C'. split; [exact Hb' |].
  intro Hbl.
  exact (algo_sub_botLike_gen (Dpre ++ (Z,Tnew)::Dsuf) C' C Hsub Hbl).
Qed.

Lemma algo_sub_ctx_change : forall (Dpre Dsuf : tctx) (Z:typevar) (Told Tnew A B:typ),
  TCWell (Dpre ++ (Z,Told)::Dsuf) ->
  algo_sub Dsuf Tnew Told ->
  algo_sub (Dpre ++ (Z,Told)::Dsuf) A B ->
  algo_sub (Dpre ++ (Z,Tnew)::Dsuf) A B.
Proof.
  intros Dpre Dsuf Z Told Tnew A B HTC Hrel Hsub.
  eapply agentH.algo_sub_ctx_morph.
  - exact HTC.
  - exact Hsub.
  - exact (TCWell_ctx_change Dpre Dsuf Z Told Tnew HTC Hrel).
  - apply map_fst_ctx_change.
  - apply ctx_change_Rbot; assumption.
Qed.

Lemma topLike_ctx_change : forall (Dpre Dsuf : tctx) (Z:typevar) (Told Tnew T:typ),
  TCWell (Dpre ++ (Z,Told)::Dsuf) ->
  algo_sub Dsuf Tnew Told ->
  topLike (Dpre ++ (Z,Told)::Dsuf) T ->
  topLike (Dpre ++ (Z,Tnew)::Dsuf) T.
Proof.
  intros Dpre Dsuf Z Told Tnew T HTC Hrel Htop.
  eapply agentE.topLike_conv.
  - exact Htop.
  - exact (TCWell_ctx_change Dpre Dsuf Z Told Tnew HTC Hrel).
  - apply map_fst_ctx_change.
  - apply ctx_change_Rbot; assumption.
Qed.

(* ==================================================================== *)
(* Disjointness is stable under the change of one binding type          *)
(* ==================================================================== *)

Lemma disjoint_ctx_change_aux : forall (D:tctx) (A B:typ),
  disjoint D A B ->
  forall (Dpre Dsuf : tctx) (Z:typevar) (Told Tnew:typ),
    D = Dpre ++ (Z,Told)::Dsuf ->
    TCWell D ->
    algo_sub Dsuf Tnew Told ->
    disjoint (Dpre ++ (Z,Tnew)::Dsuf) A B.
Proof.
  intros D A B H.
  induction H as
    [D0 A0 B0 HTC0 HTA HTB Hax
    |D0 A0 B0 HTB HtopA
    |D0 A0 B0 HTA HtopB
    |D0 A1 A2 B1 B2 HT1 HT2 Hsub IHsub
    |D0 l A0 B0 Hsub IHsub
    |L D0 A1 B1 A2 B2 HT1 HT2 Hbody IHBODY
    |D0 X B0 A0 Hb Hsub
    |D0 B0 X A0 Hb Hsub
    |D0 A0 B0 A1 A2 Hspl Hsub1 IH1 Hsub2 IH2
    |D0 A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2];
    intros Dpre Dsuf Z Told Tnew Heq HTC Hrel.
  - subst D0.
    apply (D_ax (Dpre ++ (Z,Tnew)::Dsuf) A0 B0).
    + exact (TCWell_ctx_change Dpre Dsuf Z Told Tnew HTC Hrel).
    + apply (TWell_dom_irrel (Dpre ++ (Z,Told)::Dsuf) A0 HTA
               (Dpre ++ (Z,Tnew)::Dsuf)).
      apply map_fst_ctx_change.
    + apply (TWell_dom_irrel (Dpre ++ (Z,Told)::Dsuf) B0 HTB
               (Dpre ++ (Z,Tnew)::Dsuf)).
      apply map_fst_ctx_change.
    + exact Hax.
  - subst D0.
    apply (D_topl (Dpre ++ (Z,Tnew)::Dsuf) A0 B0).
    + apply (TWell_dom_irrel (Dpre ++ (Z,Told)::Dsuf) B0 HTB
               (Dpre ++ (Z,Tnew)::Dsuf)).
      apply map_fst_ctx_change.
    + exact (topLike_ctx_change Dpre Dsuf Z Told Tnew A0 HTC Hrel HtopA).
  - subst D0.
    apply (D_topr (Dpre ++ (Z,Tnew)::Dsuf) A0 B0).
    + apply (TWell_dom_irrel (Dpre ++ (Z,Told)::Dsuf) A0 HTA
               (Dpre ++ (Z,Tnew)::Dsuf)).
      apply map_fst_ctx_change.
    + exact (topLike_ctx_change Dpre Dsuf Z Told Tnew B0 HTC Hrel HtopB).
  - subst D0.
    apply (D_arrow (Dpre ++ (Z,Tnew)::Dsuf) A1 A2 B1 B2).
    + apply (TWell_dom_irrel (Dpre ++ (Z,Told)::Dsuf)
               (t_arrow A1 A2) HT1 (Dpre ++ (Z,Tnew)::Dsuf)).
      apply map_fst_ctx_change.
    + apply (TWell_dom_irrel (Dpre ++ (Z,Told)::Dsuf)
               (t_arrow B1 B2) HT2 (Dpre ++ (Z,Tnew)::Dsuf)).
      apply map_fst_ctx_change.
    + exact (IHsub Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
  - subst D0.
    apply (D_rcdEq (Dpre ++ (Z,Tnew)::Dsuf) l A0 B0).
    exact (IHsub Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
  - subst D0.
    apply (D_all (L \u dom (Dpre ++ (Z,Told)::Dsuf))
             (Dpre ++ (Z,Tnew)::Dsuf) A1 B1 A2 B2).
    + apply (TWell_dom_irrel (Dpre ++ (Z,Told)::Dsuf) A1 HT1
               (Dpre ++ (Z,Tnew)::Dsuf)).
      apply map_fst_ctx_change.
    + apply (TWell_dom_irrel (Dpre ++ (Z,Told)::Dsuf) A2 HT2
               (Dpre ++ (Z,Tnew)::Dsuf)).
      apply map_fst_ctx_change.
    + intros Y HY.
      destruct (notin_union Y L (dom (Dpre ++ (Z,Told)::Dsuf)) HY)
        as [HYL HYD].
      assert (HTCext : TCWell (cons (Y, t_and A1 A2)
                                  (Dpre ++ (Z,Told)::Dsuf))).
      { apply TCW_cons.
        - exact HTC.
        - apply TW_and; assumption.
        - apply uniq_cons.
          + apply TCWell_uniq. exact HTC.
          + exact HYD. }
      exact (IHBODY Y HYL (cons (Y, t_and A1 A2) Dpre) Dsuf Z Told Tnew
               eq_refl HTCext Hrel).
  - subst D0.
    destruct (ctx_change_Rsub Dpre Dsuf Z Told Tnew HTC Hrel X A0 Hb)
      as (A' & Hb' & HsubA).
    assert (Hsub' : algo_sub (Dpre ++ (Z,Tnew)::Dsuf) A0 B0).
    { exact (algo_sub_ctx_change Dpre Dsuf Z Told Tnew A0 B0 HTC Hrel Hsub). }
    apply (D_varl (Dpre ++ (Z,Tnew)::Dsuf) X B0 A' Hb').
    exact (agentH2.algo_sub_trans_TCWell (Dpre ++ (Z,Tnew)::Dsuf)
             A' A0 B0
             (TCWell_ctx_change Dpre Dsuf Z Told Tnew HTC Hrel)
             HsubA Hsub').
  - subst D0.
    destruct (ctx_change_Rsub Dpre Dsuf Z Told Tnew HTC Hrel X A0 Hb)
      as (A' & Hb' & HsubA).
    assert (Hsub' : algo_sub (Dpre ++ (Z,Tnew)::Dsuf) A0 B0).
    { exact (algo_sub_ctx_change Dpre Dsuf Z Told Tnew A0 B0 HTC Hrel Hsub). }
    apply (D_varr (Dpre ++ (Z,Tnew)::Dsuf) B0 X A' Hb').
    exact (agentH2.algo_sub_trans_TCWell (Dpre ++ (Z,Tnew)::Dsuf)
             A' A0 B0
             (TCWell_ctx_change Dpre Dsuf Z Told Tnew HTC Hrel)
             HsubA Hsub').
  - subst D0.
    apply (D_andl (Dpre ++ (Z,Tnew)::Dsuf) A0 B0 A1 A2 Hspl).
    + exact (IH1 Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
    + exact (IH2 Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
  - subst D0.
    apply (D_andr (Dpre ++ (Z,Tnew)::Dsuf) A0 B0 B1 B2 Hspl).
    + exact (IH1 Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
    + exact (IH2 Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
Qed.

Corollary disjoint_ctx_change : forall (Dpre Dsuf : tctx) (Z:typevar) (Told Tnew A B:typ),
  TCWell (Dpre ++ (Z,Told)::Dsuf) ->
  algo_sub Dsuf Tnew Told ->
  disjoint (Dpre ++ (Z,Told)::Dsuf) A B ->
  disjoint (Dpre ++ (Z,Tnew)::Dsuf) A B.
Proof.
  intros. eapply disjoint_ctx_change_aux; [exact H1 | reflexivity | exact H | exact H0].
Qed.

(* ==================================================================== *)
(* Main typing context conversion                                       *)
(* ==================================================================== *)

Lemma typing_ctx_sub_gen : forall (D:tctx) (G:ctx) (e:exp) (d:dirflag) (T:typ),
  Typing D G e d T ->
  forall (Dpre Dsuf : tctx) (Z:typevar) (Told Tnew:typ),
    D = Dpre ++ (Z,Told)::Dsuf ->
    TCWell D ->
    algo_sub Dsuf Tnew Told ->
    Typing (Dpre ++ (Z,Tnew)::Dsuf) G e d T.
Proof.
  intros D G e d T Hty.
  induction Hty as
    [D0 G0 HTC0 HCW Hu
    |D0 G0 i HTC0 HCW Hu
    |D0 G0 x A HTC0 HCW Hb Hu
    |L D0 G0 A e B1 B2 Hsub Hbody IHBODY
    |D0 G0 e1 e2 C A B Ht1 IH1 Hdist Ht2 IH2
    |L D0 G0 e A B HCW Hbody IHBODY
    |D0 G0 e A C2 B C1 Ht IH Hdist Hdisj
    |D0 G0 e l C A Ht IH Hdist
    |D0 G0 l e A Ht IH
    |D0 G0 e1 e2 A B Ht1 IH1 Ht2 IH2 Hdisj
    |D0 G0 e A B Ht1 IH1 Ht2 IH2
    |D0 G0 e A Ht IH
    |L D0 G0 A e Hbody IHBODY
    |D0 G0 u1 u2 A B HTC0 HCW Hu Ht1 IH1 Ht2 IH2 Hcons
    |D0 G0 e B A Ht IH Hsub];
    intros Dpre Dsuf Z Told Tnew Heq HTC Hrel.
  - subst D0.
    apply (Typ_top (Dpre ++ (Z,Tnew)::Dsuf) G0).
    + exact (TCWell_ctx_change Dpre Dsuf Z Told Tnew HTC Hrel).
    + exact (CWell_map_fst (Dpre ++ (Z,Told)::Dsuf) G0 HCW
               (Dpre ++ (Z,Tnew)::Dsuf)
               (map_fst_ctx_change Dpre Dsuf Z Told Tnew)).
    + exact Hu.
  - subst D0.
    apply (Typ_lit (Dpre ++ (Z,Tnew)::Dsuf) G0 i).
    + exact (TCWell_ctx_change Dpre Dsuf Z Told Tnew HTC Hrel).
    + exact (CWell_map_fst (Dpre ++ (Z,Told)::Dsuf) G0 HCW
               (Dpre ++ (Z,Tnew)::Dsuf)
               (map_fst_ctx_change Dpre Dsuf Z Told Tnew)).
    + exact Hu.
  - subst D0.
    apply (Typ_var (Dpre ++ (Z,Tnew)::Dsuf) G0 x A).
    + exact (TCWell_ctx_change Dpre Dsuf Z Told Tnew HTC Hrel).
    + exact (CWell_map_fst (Dpre ++ (Z,Told)::Dsuf) G0 HCW
               (Dpre ++ (Z,Tnew)::Dsuf)
               (map_fst_ctx_change Dpre Dsuf Z Told Tnew)).
    + exact Hb.
    + exact Hu.
  - subst D0.
    apply (Typ_abs L (Dpre ++ (Z,Tnew)::Dsuf) G0 A e B1 B2).
    + exact (algo_sub_ctx_change Dpre Dsuf Z Told Tnew B1 A HTC Hrel Hsub).
    + intros x Hx.
      exact (IHBODY x Hx Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
  - subst D0.
    apply (Typ_app (Dpre ++ (Z,Tnew)::Dsuf) G0 e1 e2 C A B).
    + exact (IH1 Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
    + exact Hdist.
    + exact (IH2 Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
  - subst D0.
    apply (Typ_tabs L (Dpre ++ (Z,Tnew)::Dsuf) G0 e A B).
    + exact (CWell_map_fst (Dpre ++ (Z,Told)::Dsuf) G0 HCW
               (Dpre ++ (Z,Tnew)::Dsuf)
               (map_fst_ctx_change Dpre Dsuf Z Told Tnew)).
    + intros Y HY.
      assert (HTCext : TCWell (cons (Y,A) (Dpre ++ (Z,Told)::Dsuf))).
      { apply (proj1 (typing_env_wf (cons (Y,A) (Dpre ++ (Z,Told)::Dsuf))
                        G0 (open_exp_wrt_typ e (t_tvar_f Y)) Chk
                        (open_typ_wrt_typ B (t_tvar_f Y)) (Hbody Y HY))). }
      exact (IHBODY Y HY (cons (Y,A) Dpre) Dsuf Z Told Tnew
               eq_refl HTCext Hrel).
  - subst D0.
    apply (Typ_tapp (Dpre ++ (Z,Tnew)::Dsuf) G0 e A C2 B C1).
    + exact (IH Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
    + exact Hdist.
    + exact (disjoint_ctx_change_aux (Dpre ++ (Z,Told)::Dsuf) A C1 Hdisj
               Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
  - subst D0.
    apply (Typ_proj (Dpre ++ (Z,Tnew)::Dsuf) G0 e l C A).
    + exact (IH Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
    + exact Hdist.
  - subst D0.
    apply (Typ_rcd (Dpre ++ (Z,Tnew)::Dsuf) G0 l e A).
    exact (IH Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
  - subst D0.
    apply (Typ_merge (Dpre ++ (Z,Tnew)::Dsuf) G0 e1 e2 A B).
    + exact (IH1 Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
    + exact (IH2 Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
    + exact (disjoint_ctx_change_aux (Dpre ++ (Z,Told)::Dsuf) A B Hdisj
               Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
  - subst D0.
    apply (Typ_inter (Dpre ++ (Z,Tnew)::Dsuf) G0 e A B).
    + exact (IH1 Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
    + exact (IH2 Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
  - subst D0.
    apply (Typ_anno (Dpre ++ (Z,Tnew)::Dsuf) G0 e A).
    exact (IH Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
  - subst D0.
    apply (Typ_fix L (Dpre ++ (Z,Tnew)::Dsuf) G0 A e).
    intros x Hx.
    exact (IHBODY x Hx Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
  - subst D0.
    apply (Typ_mergev (Dpre ++ (Z,Tnew)::Dsuf) G0 u1 u2 A B).
    + exact (TCWell_ctx_change Dpre Dsuf Z Told Tnew HTC Hrel).
    + exact (CWell_map_fst (Dpre ++ (Z,Told)::Dsuf) G0 HCW
               (Dpre ++ (Z,Tnew)::Dsuf)
               (map_fst_ctx_change Dpre Dsuf Z Told Tnew)).
    + exact Hu.
    + exact Ht1.
    + exact Ht2.
    + exact Hcons.
  - subst D0.
    apply (Typ_sub (Dpre ++ (Z,Tnew)::Dsuf) G0 e B A).
    + exact (IH Dpre Dsuf Z Told Tnew eq_refl HTC Hrel).
    + exact (algo_sub_ctx_change Dpre Dsuf Z Told Tnew A B HTC Hrel Hsub).
Qed.

(* ==================================================================== *)
(* The statement needed by agentE3.                                    *)
(* ==================================================================== *)

Lemma typing_ctx_sub : forall (D:tctx) (X:typevar) (A1 B1:typ)
    (G:ctx) (e:exp) (d:dirflag) (T:typ),
  TCWell D -> X \notin dom D -> algo_sub D B1 A1 ->
  Typing (cons (X,A1) D) G e d T ->
  Typing (cons (X,B1) D) G e d T.
Proof.
  intros D X A1 B1 G e d T HTC HX Hrel Hty.
  assert (HTCold : TCWell (cons (X,A1) D)).
  { apply (proj1 (typing_env_wf (cons (X,A1) D) G e d T Hty)). }
  exact (typing_ctx_sub_gen (cons (X,A1) D) G e d T Hty
           nil D X A1 B1 eq_refl HTCold Hrel).
Qed.

Print Assumptions typing_ctx_sub.
End agentH4.
Import agentH4.

Module agentK.
Import ListNotations.

(* ==================================================================== *)
(* Small context helpers                                                 *)
(* ==================================================================== *)

Lemma lc_exp_abs_top : lc_exp (e_abs t_top e_top).
Proof. apply lc_e_abs; [apply lc_t_top | intros x; apply lc_e_top]. Qed.

Lemma lc_exp_tabs_top : lc_exp (e_tabs e_top).
Proof. apply lc_e_tabs; intros X; apply lc_e_top. Qed.

Lemma lc_exp_rcd_top : forall l, lc_exp (e_rcd l e_top).
Proof. intros l. apply lc_e_rcd; apply lc_e_top. Qed.

Lemma cwell_nil : CWell nil nil. Proof. apply CW_empty. Qed.

Lemma uniq_nil_ctx : uniq (nil:ctx). Proof. apply uniq_nil. Qed.

Lemma uniq_cons_nil : forall (x:termvar) (A:typ), uniq (cons (x,A) (nil:ctx)).
Proof.
  intros x A. apply uniq_cons; [apply uniq_nil | apply notin_empty].
Qed.

Lemma uniq_tcons_nil : forall (X:typevar) (A:typ), uniq (cons (X,A) (nil:tctx)).
Proof. intros X A. apply uniq_cons; [apply uniq_nil | apply notin_empty]. Qed.

Lemma cwell_cons_nil_top : forall (x:termvar), CWell nil (cons (x,t_top) nil).
Proof. intros x. apply CW_cons; [apply CW_empty | apply TW_top]. Qed.

Lemma tw_top_nil : TWell nil t_top. Proof. apply TW_top. Qed.
Lemma tw_int_nil : TWell nil t_int. Proof. apply TW_int. Qed.
Lemma tl_top_nil : topLike nil t_top. Proof. apply TL_top. apply TCW_empty. Qed.

(* lc_exp inversion lemmas absent from the libraries *)
Lemma lc_exp_anno_inv : forall e A, lc_exp (e_anno e A) -> lc_exp e /\ lc_typ A.
Proof. intros e A H. inversion H; subst. split; assumption. Qed.

Lemma lc_exp_merge_inv : forall e1 e2, lc_exp (e_merge e1 e2) -> lc_exp e1 /\ lc_exp e2.
Proof. intros e1 e2 H. inversion H; subst. split; assumption. Qed.

Lemma lc_exp_abs_inv : forall A e, lc_exp (e_abs A e) -> lc_typ A /\ (forall x, lc_exp (e ^ x)).
Proof. intros A e H. inversion H; subst. split; assumption. Qed.

(* ==================================================================== *)
(* Every wrapping result is a prevalue and (if it is not a merge) has    *)
(* pType equal to its target type.                                       *)
(* ==================================================================== *)

Lemma wrapping_prevalue : forall e A e', wrapping e A e' -> prevalue e'.
Proof.
  intros e A e' H. induction H.
  - apply PV_top.
  - apply PV_anno.
    + apply lc_exp_abs_top.
    + apply ord_lc_typ with (A:=t_arrow A1 A2). assumption.
  - apply PV_anno.
    + apply lc_exp_tabs_top.
    + apply ord_lc_typ with (A:=t_forall A1 A2). assumption.
  - apply PV_anno.
    + apply lc_exp_rcd_top.
    + apply ord_lc_typ with (A:=t_rcd l A). assumption.
  - apply PV_anno.
    + assumption.
    + apply ord_lc_typ with (A:=A). assumption.
  - apply PV_merge; assumption.
Qed.

Lemma wrapping_base_pType : forall e A e', wrapping e A e' ->
  (forall b c, e' <> e_merge b c) -> pType e' A.
Proof.
  intros e A e' H. induction H; intro Hna.
  - apply PT_top.
  - apply PT_anno.
    + apply lc_exp_abs_top.
    + apply ord_lc_typ with (A:=t_arrow A1 A2). assumption.
  - apply PT_anno.
    + apply lc_exp_tabs_top.
    + apply ord_lc_typ with (A:=t_forall A1 A2). assumption.
  - apply PT_anno.
    + apply lc_exp_rcd_top.
    + apply ord_lc_typ with (A:=t_rcd l A). assumption.
  - apply PT_anno.
    + assumption.
    + apply ord_lc_typ with (A:=A). assumption.
  - exfalso. apply (Hna e1 e2). reflexivity.
Qed.

(* ==================================================================== *)
(* Splitting an algorithmic-subtyping derivation at a splitting target   *)
(* (agentI is unavailable because its .vo is inconsistent with agentE).  *)
(* ==================================================================== *)

Lemma algo_sub_spl : forall D A B,
  algo_sub D A B ->
  forall B1 B2, spl B B1 B2 -> algo_sub D A B1 /\ algo_sub D A B2.
Proof.
  intros D A B H. induction H as
    [ D X HTC HTW
    | D HTC
    | D A0 B0 HTW Hord Htop
    | D A0 HTC HTW Hord
    | D A0 B0 C HTWB Hord Hsub IHsub
    | D A0 B0 C HTWA Hord Hsub IHsub
    | D A1 B1 A2 B2 Hord Hsub1 IH1 Hsub2 IH2
    | L D A1 A2 B1 B2 Hord Hsub1 IH1 Hbody IHBODY
    | D l A0 B0 Hord Hsub IHsub
    | D A0 B0 B1 B2 Hspl0 Hsub1 IH1 Hsub2 IH2 ];
    intros C1 C2 Hspl.
  - (* S_var *) inversion Hspl.
  - (* S_int *) inversion Hspl.
  - (* S_top *) exfalso. exact (spl_not_ord B0 C1 C2 Hspl Hord).
  - (* S_bot *) exfalso. exact (spl_not_ord A0 C1 C2 Hspl Hord).
  - (* S_andl *) exfalso. exact (spl_not_ord C C1 C2 Hspl Hord).
  - (* S_andr *) exfalso. exact (spl_not_ord C C1 C2 Hspl Hord).
  - (* S_arrow *)
    exfalso.
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2].
    exact (spl_not_ord B2 q1 q2 Hsplq Hord).
  - (* S_all *)
    exfalso.
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2].
    destruct (atom_fresh (L \u Lq)) as [X HX].
    destruct (notin_union X L Lq HX) as [HXL HXL0].
    exact (spl_not_ord (B2 -^ X) (q1 -^ X) (q2 -^ X) (Hbq X HXL0) (Hord X HXL)).
  - (* S_rcd *)
    exfalso.
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2].
    exact (spl_not_ord B0 q1 q2 Hsplq Hord).
  - (* S_and *)
    destruct (@spl_functional B0 B1 B2 C1 C2 Hspl0 Hspl) as [E1 E2].
    subst C1 C2. split; assumption.
Qed.

(* ==================================================================== *)
(* Splitting a checked type: both components of a split are checked.     *)
(* ==================================================================== *)

Lemma typing_chk_spl : forall D G e d A, Typing D G e d A ->
  forall B0 C0, d = Chk -> spl A B0 C0 ->
  Typing D G e Chk B0 /\ Typing D G e Chk C0.
Proof.
  intros D G e d A Hty.
  induction Hty; intros B0 C0 Ed Hspl.
  - (* Typ_top *) discriminate Ed.
  - (* Typ_lit *) discriminate Ed.
  - (* Typ_var *) discriminate Ed.
  - (* Typ_abs *)
    destruct (spl_arrow_inv B1 B2 B0 C0 Hspl) as (C1 & C2 & E1 & E2 & Hs); subst B0 C0.
    split.
    + apply (Typ_abs L D G A e B1 C1). assumption.
      intros x Hx. exact (proj1 (H1 x Hx C1 C2 eq_refl Hs)).
    + apply (Typ_abs L D G A e B1 C2). assumption.
      intros x Hx. exact (proj2 (H1 x Hx C1 C2 eq_refl Hs)).
  - (* Typ_app *) discriminate Ed.
  - (* Typ_tabs *)
    inversion Hspl as [q0 q1 q2 q3 Hlcq Hsplq | L0 q0 q1 q2 q3 Hlcq Hb | l0 q1 q2 q3 Hsplq | q0 q1 Hlcq Hlcq2]; subst.
    split.
    + apply (Typ_tabs (L \u L0) D G e A q2). assumption.
      intros X HX. destruct (notin_union X L L0 HX) as [HXL HXL0].
      exact (proj1 (H1 X HXL (q2 -^ X) (q3 -^ X) eq_refl (Hb X HXL0))).
    + apply (Typ_tabs (L \u L0) D G e A q3). assumption.
      intros X HX. destruct (notin_union X L L0 HX) as [HXL HXL0].
      exact (proj2 (H1 X HXL (q2 -^ X) (q3 -^ X) eq_refl (Hb X HXL0))).
  - (* Typ_tapp *) discriminate Ed.
  - (* Typ_proj *) discriminate Ed.
  - (* Typ_rcd *)
    destruct (spl_rcd_inv l A B0 C0 Hspl) as (C1 & C2 & E1 & E2 & Hs); subst B0 C0.
    split.
    + apply (Typ_rcd D G l e C1). exact (proj1 (IHHty C1 C2 eq_refl Hs)).
    + apply (Typ_rcd D G l e C2). exact (proj2 (IHHty C1 C2 eq_refl Hs)).
  - (* Typ_merge *) discriminate Ed.
  - (* Typ_inter *)
    destruct (spl_and_inv A B B0 C0 Hspl) as [E1 E2]; subst B0 C0.
    split; assumption.
  - (* Typ_anno *) discriminate Ed.
  - (* Typ_fix *) discriminate Ed.
  - (* Typ_mergev *) discriminate Ed.
  - (* Typ_sub *)
    destruct (algo_sub_spl D A B H B0 C0 Hspl) as [HsB HsC].
    split.
    + exact (Typ_sub D G e B0 A Hty HsB).
    + exact (Typ_sub D G e C0 A Hty HsC).
Qed.



(* ==================================================================== *)
(* Typing the canonical wrappers produced by the base wrapping rules.    *)
(* ==================================================================== *)

Lemma typing_top_chk : forall D G, TCWell D -> CWell D G -> uniq G ->
  forall A, ord A -> topLike D A -> Typing D G e_top Chk A.
Proof.
  intros D G HTC HCW Hu A Ho HT.
  apply (Typ_sub D G e_top A t_top).
  - apply Typ_top; assumption.
  - apply (S_top D t_top A); [apply TW_top | assumption | assumption].
Qed.

Lemma topLike_weaken_nil_cons : forall A (x:termvar) B,
  topLike nil A -> TWell nil B -> topLike (cons (x,B) nil) A.
Proof.
  intros A x B HT HWB.
  apply (topLike_weaken nil (cons (x,B) nil) A HT).
  - apply (TCW_cons nil x B TCW_empty HWB (uniq_cons_nil x B)).
  - intros X C Hb. inversion Hb.
Qed.

Lemma topLike_all_body_nil : forall A B,
  topLike nil (t_forall A B) ->
  exists L, forall X, X \notin L -> topLike (cons (X,A) nil) (open_typ_wrt_typ B (t_tvar_f X)).
Proof.
  intros A B H. inversion H; subst. eexists. eauto.
Qed.

Lemma typing_eabs_top_arrow : forall A1 A2,
  ord (t_arrow A1 A2) -> topLike nil (t_arrow A1 A2) ->
  Typing nil nil (e_abs t_top e_top) Chk (t_arrow A1 A2).
Proof.
  intros A1 A2 Ho HT.
  destruct (ord_arrow_inv A1 A2 Ho) as [HlcA HoB].
  destruct (topLike_arrow_inv nil A1 A2 HT) as [HTWA HTB].
  apply (Typ_abs empty nil nil t_top e_top A1 A2).
  - apply (S_top nil A1 t_top).
    + assumption.
    + apply O_top.
    + apply TL_top. apply TCW_empty.
  - intros x Hx. cbn [open_exp_wrt_exp open_exp_wrt_exp_rec].
    apply (typing_top_chk nil (cons (x,t_top) nil)).
    + apply TCW_empty.
    + apply (CW_cons nil nil x t_top (CW_empty nil) (TW_top nil)).
    + apply (uniq_cons_nil x t_top).
    + assumption.
    + assumption.
Qed.

Lemma typing_etabs_top_all : forall A1 A2,
  ord (t_forall A1 A2) -> topLike nil (t_forall A1 A2) ->
  Typing nil nil (e_tabs e_top) Chk (t_forall A1 A2).
Proof.
  intros A1 A2 Ho HT.
  destruct (ord_all_inv A1 A2 Ho) as [HlcA HoB].
  pose proof (topLike_all_dom nil A1 A2 HT) as HTWA.
  pose proof (topLike_all_body_nil A1 A2 HT) as Hbody.
  destruct Hbody as [L HL].
  apply (Typ_tabs L nil nil e_top A1 A2).
  - apply CW_empty.
  - intros X HX. cbn [open_exp_wrt_typ open_exp_wrt_typ_rec].
    apply (typing_top_chk (cons (X,A1) nil) nil).
    + apply (TCW_cons nil X A1 TCW_empty HTWA (uniq_tcons_nil X A1)).
    + apply CW_empty.
    + apply uniq_nil_ctx.
    + apply HoB.
    + apply HL. assumption.
Qed.

Lemma typing_ercd_top : forall (l:label) A,
  ord (t_rcd l A) -> topLike nil (t_rcd l A) ->
  Typing nil nil (e_rcd l e_top) Chk (t_rcd l A).
Proof.
  intros l A Ho HT.
  apply (Typ_rcd nil nil l e_top A).
  apply (typing_top_chk nil nil).
  - apply TCW_empty.
  - apply CW_empty.
  - apply uniq_nil_ctx.
  - apply (ord_rcd_inv l A Ho).
  - apply (topLike_rcd_inv nil l A HT).
Qed.

(* ==================================================================== *)
(* Consistency of two wrappings of the same expression.                  *)
(* ==================================================================== *)

Lemma consistent_toplike_l_gen : forall (u1 u2:exp) (T1 T2:typ),
  topLike nil T1 -> pType u1 T1 -> pType u2 T2 -> TWell nil T2 ->
  prevalue u1 -> prevalue u2 -> consistent u1 u2.
Proof.
  intros u1 u2 T1 T2 HTL Hp1 Hp2 HTW2 HP1 HP2.
  apply (C_disjoint u1 u2 T1 T2); auto.
  apply (D_topl nil T1 T2); auto.
Qed.

Lemma consistent_toplike_r_anno : forall (e u2:exp) (A T2:typ),
  lc_exp e -> TWell nil A -> topLike nil T2 -> pType u2 T2 -> prevalue u2 ->
  consistent (e_anno e A) u2.
Proof.
  intros e u2 A T2 Hlce HTWA HT2 Hp2 HP2.
  apply (C_disjoint (e_anno e A) u2 A T2).
  - apply PT_anno; [assumption | apply TWell_lc_typ with (D:=nil); assumption].
  - assumption.
  - apply (D_topr nil A T2); assumption.
  - apply PV_anno; [assumption | apply TWell_lc_typ with (D:=nil); assumption].
  - assumption.
Qed.

Lemma wrapping_consistent : forall e A e1, wrapping e A e1 ->
  TWell nil A ->
  forall B e2, wrapping e B e2 -> TWell nil B -> consistent e1 e2.
Proof.
  intros e A e1 H1.
  induction H1 as
    [ e Hlce
    | e A1 A2 Hlce Hord Htop
    | e A1 A2 Hlce Hord Htop
    | e l A Hlce Hord Htop
    | e A Hlce Hord HNTL
    | e A e1 e2 B C Hspl Hw1 IHw1 Hw2 IHw2 ];
    intros TWA B0 e0 H2 TWB.
  - (* H1 = EW_top *)
    revert TWB. induction H2 as
      [ eB HlceB
      | eB B1 B2 HlceB HordB HtopB
      | eB B1 B2 HlceB HordB HtopB
      | eB lB AB HlceB HordB HtopB
      | eB AB HlceB HordB HNTLB
      | eB AB e21 e22 B1 B2 HsplB Hw21 IH21 Hw22 IH22 ];
      intros TWB.
    + apply (consistent_toplike_l_gen e_top e_top t_top t_top).
      * apply (TL_top nil TCW_empty).
      * apply PT_top.
      * apply PT_top.
      * assumption.
      * apply PV_top.
      * apply PV_top.
    + apply (consistent_toplike_l_gen e_top (e_anno (e_abs t_top e_top) (t_arrow B1 B2)) t_top (t_arrow B1 B2)).
      * apply (TL_top nil TCW_empty).
      * apply PT_top.
      * apply PT_anno; [apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow B1 B2); assumption].
      * assumption.
      * apply PV_top.
      * apply PV_anno; [apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow B1 B2); assumption].
    + apply (consistent_toplike_l_gen e_top (e_anno (e_tabs e_top) (t_forall B1 B2)) t_top (t_forall B1 B2)).
      * apply (TL_top nil TCW_empty).
      * apply PT_top.
      * apply PT_anno; [apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall B1 B2); assumption].
      * assumption.
      * apply PV_top.
      * apply PV_anno; [apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall B1 B2); assumption].
    + apply (consistent_toplike_l_gen e_top (e_anno (e_rcd lB e_top) (t_rcd lB AB)) t_top (t_rcd lB AB)).
      * apply (TL_top nil TCW_empty).
      * apply PT_top.
      * apply PT_anno; [apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd lB AB); assumption].
      * assumption.
      * apply PV_top.
      * apply PV_anno; [apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd lB AB); assumption].
    + apply (consistent_toplike_l_gen e_top (e_anno eB AB) t_top AB).
      * apply (TL_top nil TCW_empty).
      * apply PT_top.
      * apply PT_anno; [assumption | apply ord_lc_typ with (A:=AB); assumption].
      * assumption.
      * apply PV_top.
      * apply PV_anno; [assumption | apply ord_lc_typ with (A:=AB); assumption].
    + apply C_merger.
      * apply (IH21 Hlce (proj1 (spl_TWell_nil AB B1 B2 TWB HsplB))).
      * apply (IH22 Hlce (proj2 (spl_TWell_nil AB B1 B2 TWB HsplB))).
  - (* H1 = EW_topArrow *)
    revert TWB. induction H2 as
      [ eB HlceB
      | eB B1 B2 HlceB HordB HtopB
      | eB B1 B2 HlceB HordB HtopB
      | eB lB AB HlceB HordB HtopB
      | eB AB HlceB HordB HNTLB
      | eB AB e21 e22 B1 B2 HsplB Hw21 IH21 Hw22 IH22 ];
      intros TWB.
    + apply (consistent_toplike_l_gen (e_anno (e_abs t_top e_top) (t_arrow A1 A2)) e_top (t_arrow A1 A2) t_top).
      * assumption.
      * apply PT_anno; [apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow A1 A2); assumption].
      * apply PT_top.
      * assumption.
      * apply PV_anno; [apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow A1 A2); assumption].
      * apply PV_top.
    + apply (consistent_toplike_l_gen (e_anno (e_abs t_top e_top) (t_arrow A1 A2)) (e_anno (e_abs t_top e_top) (t_arrow B1 B2)) (t_arrow A1 A2) (t_arrow B1 B2)).
      * assumption.
      * apply PT_anno; [apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow A1 A2); assumption].
      * apply PT_anno; [apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow B1 B2); assumption].
      * assumption.
      * apply PV_anno; [apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow A1 A2); assumption].
      * apply PV_anno; [apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow B1 B2); assumption].
    + apply (consistent_toplike_l_gen (e_anno (e_abs t_top e_top) (t_arrow A1 A2)) (e_anno (e_tabs e_top) (t_forall B1 B2)) (t_arrow A1 A2) (t_forall B1 B2)).
      * assumption.
      * apply PT_anno; [apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow A1 A2); assumption].
      * apply PT_anno; [apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall B1 B2); assumption].
      * assumption.
      * apply PV_anno; [apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow A1 A2); assumption].
      * apply PV_anno; [apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall B1 B2); assumption].
    + apply (consistent_toplike_l_gen (e_anno (e_abs t_top e_top) (t_arrow A1 A2)) (e_anno (e_rcd lB e_top) (t_rcd lB AB)) (t_arrow A1 A2) (t_rcd lB AB)).
      * assumption.
      * apply PT_anno; [apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow A1 A2); assumption].
      * apply PT_anno; [apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd lB AB); assumption].
      * assumption.
      * apply PV_anno; [apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow A1 A2); assumption].
      * apply PV_anno; [apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd lB AB); assumption].
    + apply (consistent_toplike_l_gen (e_anno (e_abs t_top e_top) (t_arrow A1 A2)) (e_anno eB AB) (t_arrow A1 A2) AB).
      * assumption.
      * apply PT_anno; [apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow A1 A2); assumption].
      * apply PT_anno; [assumption | apply ord_lc_typ with (A:=AB); assumption].
      * assumption.
      * apply PV_anno; [apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow A1 A2); assumption].
      * apply PV_anno; [assumption | apply ord_lc_typ with (A:=AB); assumption].
    + apply C_merger.
      * apply (IH21 Hlce (proj1 (spl_TWell_nil AB B1 B2 TWB HsplB))).
      * apply (IH22 Hlce (proj2 (spl_TWell_nil AB B1 B2 TWB HsplB))).
  - (* H1 = EW_topAll *)
    revert TWB. induction H2 as
      [ eB HlceB
      | eB B1 B2 HlceB HordB HtopB
      | eB B1 B2 HlceB HordB HtopB
      | eB lB AB HlceB HordB HtopB
      | eB AB HlceB HordB HNTLB
      | eB AB e21 e22 B1 B2 HsplB Hw21 IH21 Hw22 IH22 ];
      intros TWB.
    + apply (consistent_toplike_l_gen (e_anno (e_tabs e_top) (t_forall A1 A2)) e_top (t_forall A1 A2) t_top).
      * assumption.
      * apply PT_anno; [apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall A1 A2); assumption].
      * apply PT_top.
      * assumption.
      * apply PV_anno; [apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall A1 A2); assumption].
      * apply PV_top.
    + apply (consistent_toplike_l_gen (e_anno (e_tabs e_top) (t_forall A1 A2)) (e_anno (e_abs t_top e_top) (t_arrow B1 B2)) (t_forall A1 A2) (t_arrow B1 B2)).
      * assumption.
      * apply PT_anno; [apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall A1 A2); assumption].
      * apply PT_anno; [apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow B1 B2); assumption].
      * assumption.
      * apply PV_anno; [apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall A1 A2); assumption].
      * apply PV_anno; [apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow B1 B2); assumption].
    + apply (consistent_toplike_l_gen (e_anno (e_tabs e_top) (t_forall A1 A2)) (e_anno (e_tabs e_top) (t_forall B1 B2)) (t_forall A1 A2) (t_forall B1 B2)).
      * assumption.
      * apply PT_anno; [apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall A1 A2); assumption].
      * apply PT_anno; [apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall B1 B2); assumption].
      * assumption.
      * apply PV_anno; [apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall A1 A2); assumption].
      * apply PV_anno; [apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall B1 B2); assumption].
    + apply (consistent_toplike_l_gen (e_anno (e_tabs e_top) (t_forall A1 A2)) (e_anno (e_rcd lB e_top) (t_rcd lB AB)) (t_forall A1 A2) (t_rcd lB AB)).
      * assumption.
      * apply PT_anno; [apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall A1 A2); assumption].
      * apply PT_anno; [apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd lB AB); assumption].
      * assumption.
      * apply PV_anno; [apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall A1 A2); assumption].
      * apply PV_anno; [apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd lB AB); assumption].
    + apply (consistent_toplike_l_gen (e_anno (e_tabs e_top) (t_forall A1 A2)) (e_anno eB AB) (t_forall A1 A2) AB).
      * assumption.
      * apply PT_anno; [apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall A1 A2); assumption].
      * apply PT_anno; [assumption | apply ord_lc_typ with (A:=AB); assumption].
      * assumption.
      * apply PV_anno; [apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall A1 A2); assumption].
      * apply PV_anno; [assumption | apply ord_lc_typ with (A:=AB); assumption].
    + apply C_merger.
      * apply (IH21 Hlce (proj1 (spl_TWell_nil AB B1 B2 TWB HsplB))).
      * apply (IH22 Hlce (proj2 (spl_TWell_nil AB B1 B2 TWB HsplB))).
  - (* H1 = EW_topRcd *)
    revert TWB. induction H2 as
      [ eB HlceB
      | eB B1 B2 HlceB HordB HtopB
      | eB B1 B2 HlceB HordB HtopB
      | eB lB AB HlceB HordB HtopB
      | eB AB HlceB HordB HNTLB
      | eB AB e21 e22 B1 B2 HsplB Hw21 IH21 Hw22 IH22 ];
      intros TWB.
    + apply (consistent_toplike_l_gen (e_anno (e_rcd l e_top) (t_rcd l A)) e_top (t_rcd l A) t_top).
      * assumption.
      * apply PT_anno; [apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd l A); assumption].
      * apply PT_top.
      * assumption.
      * apply PV_anno; [apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd l A); assumption].
      * apply PV_top.
    + apply (consistent_toplike_l_gen (e_anno (e_rcd l e_top) (t_rcd l A)) (e_anno (e_abs t_top e_top) (t_arrow B1 B2)) (t_rcd l A) (t_arrow B1 B2)).
      * assumption.
      * apply PT_anno; [apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd l A); assumption].
      * apply PT_anno; [apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow B1 B2); assumption].
      * assumption.
      * apply PV_anno; [apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd l A); assumption].
      * apply PV_anno; [apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow B1 B2); assumption].
    + apply (consistent_toplike_l_gen (e_anno (e_rcd l e_top) (t_rcd l A)) (e_anno (e_tabs e_top) (t_forall B1 B2)) (t_rcd l A) (t_forall B1 B2)).
      * assumption.
      * apply PT_anno; [apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd l A); assumption].
      * apply PT_anno; [apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall B1 B2); assumption].
      * assumption.
      * apply PV_anno; [apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd l A); assumption].
      * apply PV_anno; [apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall B1 B2); assumption].
    + apply (consistent_toplike_l_gen (e_anno (e_rcd l e_top) (t_rcd l A)) (e_anno (e_rcd lB e_top) (t_rcd lB AB)) (t_rcd l A) (t_rcd lB AB)).
      * assumption.
      * apply PT_anno; [apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd l A); assumption].
      * apply PT_anno; [apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd lB AB); assumption].
      * assumption.
      * apply PV_anno; [apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd l A); assumption].
      * apply PV_anno; [apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd lB AB); assumption].
    + apply (consistent_toplike_l_gen (e_anno (e_rcd l e_top) (t_rcd l A)) (e_anno eB AB) (t_rcd l A) AB).
      * assumption.
      * apply PT_anno; [apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd l A); assumption].
      * apply PT_anno; [assumption | apply ord_lc_typ with (A:=AB); assumption].
      * assumption.
      * apply PV_anno; [apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd l A); assumption].
      * apply PV_anno; [assumption | apply ord_lc_typ with (A:=AB); assumption].
    + apply C_merger.
      * apply (IH21 Hlce (proj1 (spl_TWell_nil AB B1 B2 TWB HsplB))).
      * apply (IH22 Hlce (proj2 (spl_TWell_nil AB B1 B2 TWB HsplB))).
  - (* H1 = EW_anno *)
    revert TWB. induction H2 as
      [ eB HlceB
      | eB B1 B2 HlceB HordB HtopB
      | eB B1 B2 HlceB HordB HtopB
      | eB lB AB HlceB HordB HtopB
      | eB AB HlceB HordB HNTLB
      | eB AB e21 e22 B1 B2 HsplB Hw21 IH21 Hw22 IH22 ];
      intros TWB.
    + apply (consistent_toplike_r_anno eB e_top A t_top).
      * assumption.
      * assumption.
      * apply (TL_top nil TCW_empty).
      * apply PT_top.
      * apply PV_top.
    + apply (consistent_toplike_r_anno eB (e_anno (e_abs t_top e_top) (t_arrow B1 B2)) A (t_arrow B1 B2)).
      * assumption.
      * assumption.
      * assumption.
      * apply PT_anno; [apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow B1 B2); assumption].
      * apply PV_anno; [apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow B1 B2); assumption].
    + apply (consistent_toplike_r_anno eB (e_anno (e_tabs e_top) (t_forall B1 B2)) A (t_forall B1 B2)).
      * assumption.
      * assumption.
      * assumption.
      * apply PT_anno; [apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall B1 B2); assumption].
      * apply PV_anno; [apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall B1 B2); assumption].
    + apply (consistent_toplike_r_anno eB (e_anno (e_rcd lB e_top) (t_rcd lB AB)) A (t_rcd lB AB)).
      * assumption.
      * assumption.
      * assumption.
      * apply PT_anno; [apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd lB AB); assumption].
      * apply PV_anno; [apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd lB AB); assumption].
    + apply (C_anno eB A AB).
      * apply TWell_lc_typ with (D:=nil); assumption.
      * assumption.
      * apply ord_lc_typ with (A:=AB); assumption.
    + apply C_merger.
      * apply (IH21 Hlce (proj1 (spl_TWell_nil AB B1 B2 TWB HsplB))).
      * apply (IH22 Hlce (proj2 (spl_TWell_nil AB B1 B2 TWB HsplB))).
  - (* H1 = EW_and *)
    apply C_mergel.
    + apply (IHw1 (proj1 (spl_TWell_nil A B C TWA Hspl)) B0 e0 H2 TWB).
    + apply (IHw2 (proj2 (spl_TWell_nil A B C TWA Hspl)) B0 e0 H2 TWB).
Qed.

(* ==================================================================== *)
(* Goal A: wrapping preserves typability.                                *)
(* ==================================================================== *)

Lemma wrapping_typing_inf : forall (e:exp) (A:typ) (e':exp),
  wrapping e A e' -> TWell nil A -> Typing nil nil e Chk A ->
  exists P, Typing nil nil e' Inf P /\ subsub P A /\ TWell nil P.
Proof.
  intros e A e' H.
  induction H as
    [ e Hlce
    | e A1 A2 Hlce Hord Htop
    | e A1 A2 Hlce Hord Htop
    | e l A Hlce Hord Htop
    | e A Hlce Hord HNTL
    | e A e1 e2 B C Hspl Hw1 IH1 Hw2 IH2 ];
    intros TWA Hty.
  - exists t_top. split.
    + apply Typ_top.
      * apply TCW_empty.
      * apply CW_empty.
      * apply uniq_nil_ctx.
    + split.
      * apply IS_refl. apply lc_t_top.
      * apply TW_top.
  - exists (t_arrow A1 A2). split.
    + apply Typ_anno. apply (typing_eabs_top_arrow A1 A2 Hord Htop).
    + split.
      * apply IS_refl. apply (ord_lc_typ (t_arrow A1 A2) Hord).
      * assumption.
  - exists (t_forall A1 A2). split.
    + apply Typ_anno. apply (typing_etabs_top_all A1 A2 Hord Htop).
    + split.
      * apply IS_refl. apply (ord_lc_typ (t_forall A1 A2) Hord).
      * assumption.
  - exists (t_rcd l A). split.
    + apply Typ_anno. apply (typing_ercd_top l A Hord Htop).
    + split.
      * apply IS_refl. apply (ord_lc_typ (t_rcd l A) Hord).
      * assumption.
  - exists A. split.
    + apply Typ_anno. assumption.
    + split.
      * apply IS_refl. apply (ord_lc_typ A Hord).
      * assumption.
  - destruct (spl_TWell_nil A B C TWA Hspl) as [TWB TWC].
    destruct (typing_chk_spl nil nil e Chk A Hty B C eq_refl Hspl) as [HtyB HtyC].
    destruct (IH1 TWB HtyB) as (P1 & Hty1 & Hsub1 & HTW1).
    destruct (IH2 TWC HtyC) as (P2 & Hty2 & Hsub2 & HTW2).
    exists (t_and P1 P2). split.
    + apply (Typ_mergev nil nil e1 e2 P1 P2).
      * apply TCW_empty.
      * apply CW_empty.
      * apply uniq_nil_ctx.
      * assumption.
      * assumption.
      * apply (wrapping_consistent e B e1 Hw1 TWB C e2 Hw2 TWC).
    + split.
      * apply (IS_and P1 P2 A B C Hspl Hsub1 Hsub2).
      * apply TW_and; assumption.
Qed.


(* ==================================================================== *)
(* Goal B: the strongest kernel-checked reduction available here.       *)
(*                                                                      *)
(* The induction on [casting] succeeds for every rule except:           *)
(*   * Cast_anno, whose result [e_anno e B] needs [e Chk B] while the    *)
(*     source only supplies [e_anno e A Chk B];                         *)
(*   * Cast_mergel/Cast_merger, whose recursive cast has a component     *)
(*     source for which the top-level typing hypothesis gives no Chk     *)
(*     judgement at the cast target;                                    *)
(*   * Cast_and, where typing the merged result needs consistency of     *)
(*     the two component casts.                                         *)
(* The four hypotheses below isolate exactly those missing facts.       *)
(* ==================================================================== *)

Lemma casting_typing_inf_of_extra :
  (forall (e:exp) (A B:typ),
      Typing nil nil (e_anno e A) Chk B -> Typing nil nil e Chk B) ->
  (forall (v1 v2:exp) (A:typ) (v1':exp),
      Typing nil nil (e_merge v1 v2) Chk A -> TWell nil A ->
      casting v1 A v1' ->
      exists P, Typing nil nil v1' Inf P /\ subsub P A /\ TWell nil P) ->
  (forall (v1 v2:exp) (A:typ) (v2':exp),
      Typing nil nil (e_merge v1 v2) Chk A -> TWell nil A ->
      casting v2 A v2' ->
      exists P, Typing nil nil v2' Inf P /\ subsub P A /\ TWell nil P) ->
  (forall (v:exp) (A B:typ) (v1:exp) (C:typ) (v2:exp),
      Typing nil nil v Chk A -> TWell nil A -> spl A B C ->
      casting v B v1 -> casting v C v2 -> consistent v1 v2) ->
  forall (v:exp) (A:typ) (v':exp),
    casting v A v' -> TWell nil A -> Typing nil nil v Chk A ->
    exists P, Typing nil nil v' Inf P /\ subsub P A /\ TWell nil P.
Proof.
  intros Hanno Hmergel Hmerger Hcons v A v' Hcast.
  induction Hcast as
    [ i
    | v0 Hlce
    | v0 A1 A2 Hlce Hord Htop
    | v0 A1 A2 Hlce Hord Htop
    | v0 l A0 Hlce Hord Htop
    | e A0 B Hlce Hord HNTL Hsub
    | v1 v2 A0 v1' Hlce Hord Hc1 IH1
    | v1 v2 A0 v2' Hlce Hord Hc2 IH2
    | v0 A0 v1 v2 B C Hspl Hc1 IH1 Hc2 IH2 ];
    intros TWV Hty.
  - exists t_int. split.
    + apply (Typ_lit nil nil i).
      * apply TCW_empty.
      * apply CW_empty.
      * apply uniq_nil_ctx.
    + split.
      * apply IS_refl. apply lc_t_int.
      * apply TW_int.
  - exists t_top. split.
    + apply Typ_top.
      * apply TCW_empty.
      * apply CW_empty.
      * apply uniq_nil_ctx.
    + split.
      * apply IS_refl. apply lc_t_top.
      * apply TW_top.
  - exists (t_arrow A1 A2). split.
    + apply Typ_anno. apply (typing_eabs_top_arrow A1 A2 Hord Htop).
    + split.
      * apply IS_refl. apply (ord_lc_typ (t_arrow A1 A2) Hord).
      * assumption.
  - exists (t_forall A1 A2). split.
    + apply Typ_anno. apply (typing_etabs_top_all A1 A2 Hord Htop).
    + split.
      * apply IS_refl. apply (ord_lc_typ (t_forall A1 A2) Hord).
      * assumption.
  - exists (t_rcd l A0). split.
    + apply Typ_anno. apply (typing_ercd_top l A0 Hord Htop).
    + split.
      * apply IS_refl. apply (ord_lc_typ (t_rcd l A0) Hord).
      * assumption.
  - exists B. split.
    + apply Typ_anno. apply (Hanno e A0 B Hty).
    + split.
      * apply IS_refl. apply (ord_lc_typ B Hord).
      * assumption.
  - apply (Hmergel v1 v2 A0 v1' Hty TWV Hc1).
  - apply (Hmerger v1 v2 A0 v2' Hty TWV Hc2).
  - destruct (spl_TWell_nil A0 B C TWV Hspl) as [TWB TWC].
    destruct (typing_chk_spl nil nil v0 Chk A0 Hty B C eq_refl Hspl) as [HtyB HtyC].
    destruct (IH1 TWB HtyB) as (P1 & Hty1 & Hsub1 & HTW1).
    destruct (IH2 TWC HtyC) as (P2 & Hty2 & Hsub2 & HTW2).
    exists (t_and P1 P2). split.
    + apply (Typ_mergev nil nil v1 v2 P1 P2).
      * apply TCW_empty.
      * apply CW_empty.
      * apply uniq_nil_ctx.
      * assumption.
      * assumption.
      * apply (Hcons v0 A0 B v1 C v2 Hty TWV Hspl Hc1 Hc2).
    + split.
      * apply (IS_and P1 P2 A0 B C Hspl Hsub1 Hsub2).
      * apply TW_and; assumption.
Qed.

(* ==================================================================== *)
(* Status of the unconditional casting statement                        *)
(*                                                                      *)
(* No counterexample to the existential/subsub form of                 *)
(* [casting_typing_inf] was found.  (An earlier attempt using           *)
(* Cast_mergel + Cast_int was invalid: Cast_int's target is t_int, so   *)
(* a literal cannot be cast to a record type through Cast_mergel.)      *)
(* The unconditional proof still needs the four hypotheses of           *)
(* [casting_typing_inf_of_extra]:                                      *)
(*                                                                      *)
(* 1. [Typing (e_anno e A) Chk B -> Typing e Chk B].  Inversion reduces *)
(*    this to [Typing e Chk A -> algo_sub nil A B -> Typing e Chk B],   *)
(*    the open [chk_sub_ord_ntl] obstacle recorded in agentE.v (needs    *)
(*    algo_sub transitivity and type-context conversion for S_all).     *)
(* 2. Component typing for Cast_mergel (same for Cast_merger): the      *)
(*    source is only checked as a merge, not at the component's cast    *)
(*    target, so the induction hypothesis is not applicable.            *)
(* 3. Consistency of the two casts produced by Cast_and at the split    *)
(*    components B and C.  Source typing is essential here: for the     *)
(*    untyped term [e_merge (e_lit 0) (e_anno (e_lit 1) t_int)] and     *)
(*    A = t_int & t_int, the two casts to t_int are a literal and an    *)
(*    annotated literal, which are not consistent.  Source typing rules *)
(*    out that term (its components are neither disjoint nor related by *)
(*    C_anno), but turning this into the needed preservation lemma is   *)
(*    not available in the compiled libraries.                          *)
(*                                                                      *)
(* No classical logic, axiom, parameter, or admitted goal is used.      *)
(* ==================================================================== *)
End agentK.
Import agentK.

Module agentL.
Import ListNotations.

(* ================================================================== *)
(* Type-substitution on contexts                                      *)
(* ================================================================== *)

Definition subst_ctx (C:typ) (X:typevar) (G:ctx) : ctx :=
  EnvImpl.map (typsubst_typ C X) G.

Definition subst_tctx (C:typ) (X:typevar) (D:tctx) : tctx :=
  EnvImpl.map (typsubst_typ C X) D.

Lemma subst_ctx_cons : forall C X Z A G,
    subst_ctx C X (cons (Z,A) G) = cons (Z, typsubst_typ C X A) (subst_ctx C X G).
Proof. intros. reflexivity. Qed.

Lemma subst_tctx_cons : forall C X Z A D,
    subst_tctx C X (cons (Z,A) D) = cons (Z, typsubst_typ C X A) (subst_tctx C X D).
Proof. intros. reflexivity. Qed.

Lemma dom_subst_tctx : forall C X D,
    dom (subst_tctx C X D) [=] dom D.
Proof. intros. apply dom_map. Qed.

Lemma dom_subst_ctx : forall C X G,
    dom (subst_ctx C X G) [=] dom G.
Proof. intros. apply dom_map. Qed.

Lemma uniq_app_1 : forall (D E:tctx), uniq (D ++ E) -> uniq D.
Proof.
  intros D. induction D as [|[X A] D IH]; intros E H.
  - apply uniq_nil.
  - simpl in H.
    apply uniq_cons.
    + apply (IH E). apply (uniq_cons_1 typ X A (D ++ E)). exact H.
    + intro Hin.
      apply (uniq_cons_2 typ X A (D ++ E) H).
      rewrite (dom_app typ D E).
      apply AtomSetImpl.union_2. exact Hin.
Qed.

Lemma uniq_subst_tctx : forall C X D,
    uniq D -> uniq (subst_tctx C X D).
Proof. intros. apply uniq_map_2. assumption. Qed.

Lemma uniq_subst_ctx : forall C X G,
    uniq G -> uniq (subst_ctx C X G).
Proof. intros. apply uniq_map_2. assumption. Qed.

Lemma binds_subst_tctx : forall C X D Z A,
    binds Z A D -> binds Z (typsubst_typ C X A) (subst_tctx C X D).
Proof. intros. apply binds_map_2. assumption. Qed.

Lemma binds_subst_tctx_inv : forall C X D Z B,
    binds Z B (subst_tctx C X D) ->
    exists A, binds Z A D /\ B = typsubst_typ C X A.
Proof.
  intros C X D Z B H.
  destruct (@binds_map_3 typ typ (typsubst_typ C X) Z B D H) as [A Hrest].
  destruct Hrest as [Heq Hb].
  exists A. split; [exact Hb | symmetry; exact Heq].
Qed.

Lemma binds_subst_ctx : forall C X G z A,
    binds z A G -> binds z (typsubst_typ C X A) (subst_ctx C X G).
Proof. intros. apply binds_map_2. assumption. Qed.

Lemma binds_subst_ctx_inv : forall C X G z B,
    binds z B (subst_ctx C X G) ->
    exists A, binds z A G /\ B = typsubst_typ C X A.
Proof.
  intros C X G z B H.
  destruct (@binds_map_3 typ typ (typsubst_typ C X) z B G H) as [A Hrest].
  destruct Hrest as [Heq Hb].
  exists A. split; [exact Hb | symmetry; exact Heq].
Qed.

(* Freshness of the substituted variable at the end of a type context. *)

Lemma notin_dom_cons : forall (D:tctx) Z A Y,
    Y <> Z -> Y \notin dom D -> Y \notin dom (cons (Z,A) D).
Proof.
  intros D Z A Y Hne Hnot Hin.
  simpl in Hin.
  exact (Hnot (AtomSetImpl.add_3 (fun Heq => Hne (eq_sym Heq)) Hin)).
Qed.

Lemma notin_dom_cons_inv : forall (D:tctx) Z A Y,
    Y \notin dom (cons (Z,A) D) -> Y \notin dom D.
Proof.
  intros D Z A Y H Hin. apply H. simpl.
  apply AtomSetImpl.add_2. exact Hin.
Qed.

Lemma notin_dom_app_last : forall (D:tctx) Y Dom A,
    Y \notin dom D -> binds Y A (D ++ [(Y,Dom)]) -> A = Dom.
Proof.
  intros D Y Dom A Hnot Hb.
  apply in_app_or in Hb.
  destruct Hb as [Hin | Hin].
  - assert (HY : Y \in dom D) by (exact (@binds_In typ Y A D Hin)). contradiction.
  - simpl in Hin. destruct Hin as [Heq | Hnil].
    + injection Heq. intros. auto.
    + inversion Hnil.
Qed.

Lemma binds_app_neq : forall (D:tctx) Y Dom Z A,
    Z <> Y -> binds Z A (D ++ [(Y,Dom)]) -> binds Z A D.
Proof.
  intros D Y Dom Z A Hne Hb.
  apply in_app_or in Hb. destruct Hb as [Hin | Hin].
  - exact Hin.
  - simpl in Hin. destruct Hin as [Heq | Hnil].
    + inversion Heq; subst; exfalso; exact (Hne eq_refl).
    + inversion Hnil.
Qed.

Lemma binds_app_last_eq : forall (D:tctx) Y Dom,
    binds Y Dom (D ++ [(Y,Dom)]).
Proof. intros. apply in_or_app. right. simpl. left. reflexivity. Qed.

(* ================================================================== *)
(* Commutation of type substitution with opening                      *)
(* ================================================================== *)

Lemma open_typ_lc_id : forall C, lc_typ C ->
    forall k (A:typ), open_typ_wrt_typ_rec k A C = C.
Proof.
  intros C HC k A.
  exact (deg_open_identity C 0 k A (Nat.le_0_l k) (lc_typ_deg C HC)).
Qed.

Lemma typsubst_open_typ_dep : forall C Y, lc_typ C ->
    forall k (Z:typevar) (B:typ),
      typsubst_typ C Y (open_typ_wrt_typ_rec k (t_tvar_f Z) B) =
      open_typ_wrt_typ_rec k (if eq_var Z Y then C else (t_tvar_f Z))
                              (typsubst_typ C Y B).
Proof.
  intros C Y HC k Z B. revert k.
  induction B as [n|X| | | |B1 IH1 B2 IH2|B1 IH1 B2 IH2|B1 IH1 B2 IH2|l B1 IH1];
    intros k; simpl.
  - destruct (lt_eq_lt_dec n k) as [Hleft|Hgt].
    + destruct Hleft as [Hlt|Heq].
      * reflexivity.
      * subst n. reflexivity.
    + reflexivity.
  - destruct (eq_var X Y) as [Heq|Hne]; simpl.
    + subst X. rewrite open_typ_lc_id; [|exact HC].
      destruct (eq_var Z Y) as [HZY|HnZY]; simpl; reflexivity.
    + destruct (eq_var Z Y) as [HZY|HnZY]; simpl; reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite IH1. rewrite IH2. reflexivity.
  - rewrite IH1. rewrite IH2. reflexivity.
  - rewrite IH1. rewrite IH2. reflexivity.
  - rewrite IH1. reflexivity.
Qed.

Lemma typsubst_open_exp_typ_dep : forall C Y, lc_typ C ->
    forall k (Z:typevar) (e:exp),
      typsubst_exp C Y (open_exp_wrt_typ_rec k (t_tvar_f Z) e) =
      open_exp_wrt_typ_rec k (if eq_var Z Y then C else (t_tvar_f Z))
                              (typsubst_exp C Y e).
Proof.
  intros C Y HC k Z e. revert k.
  induction e as [n|x| |i|A e1 IH1|A e1 IH1|e1 IH1 e2 IH2|e1 IH1 e2 IH2|e1 IH1 A|A e1 IH1|e1 IH1 l|e1 IH1|e1 IH1 A];
    intros k; simpl.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite (typsubst_open_typ_dep C Y HC k Z A). rewrite IH1. reflexivity.
  - rewrite (typsubst_open_typ_dep C Y HC k Z A). rewrite IH1. reflexivity.
  - rewrite IH1. rewrite IH2. reflexivity.
  - rewrite IH1. rewrite IH2. reflexivity.
  - rewrite IH1. rewrite (typsubst_open_typ_dep C Y HC k Z A). reflexivity.
  - rewrite IH1. reflexivity.
  - rewrite IH1. reflexivity.
  - rewrite IH1. reflexivity.
  - rewrite IH1. rewrite (typsubst_open_typ_dep C Y HC k Z A). reflexivity.
Qed.

(* Specialisations: substituting the very variable that was opened, and
   substituting a different variable.                                         *)

Lemma typsubst_open_typ_same : forall C Y, lc_typ C ->
    forall (B:typ),
      typsubst_typ C Y (open_typ_wrt_typ B (t_tvar_f Y)) =
      open_typ_wrt_typ (typsubst_typ C Y B) C.
Proof.
  intros C Y HC B.
  unfold open_typ_wrt_typ.
  rewrite (typsubst_open_typ_dep C Y HC 0 Y B).
  destruct (eq_var Y Y) as [Heq|Hne]; [reflexivity|exfalso; apply Hne; reflexivity].
Qed.

Lemma typsubst_open_exp_typ_same : forall C Y, lc_typ C ->
    forall (e:exp),
      typsubst_exp C Y (open_exp_wrt_typ e (t_tvar_f Y)) =
      open_exp_wrt_typ (typsubst_exp C Y e) C.
Proof.
  intros C Y HC e.
  unfold open_exp_wrt_typ.
  rewrite (typsubst_open_exp_typ_dep C Y HC 0 Y e).
  destruct (eq_var Y Y) as [Heq|Hne]; [reflexivity|exfalso; apply Hne; reflexivity].
Qed.

Lemma typsubst_open_typ_neq : forall C Y, lc_typ C ->
    forall Z (B:typ), Z <> Y ->
      typsubst_typ C Y (open_typ_wrt_typ B (t_tvar_f Z)) =
      open_typ_wrt_typ (typsubst_typ C Y B) (t_tvar_f Z).
Proof.
  intros C Y HC Z B Hne.
  unfold open_typ_wrt_typ.
  rewrite (typsubst_open_typ_dep C Y HC 0 Z B).
  destruct (eq_var Z Y) as [Heq|Hne']; [exfalso; apply Hne; exact Heq|reflexivity].
Qed.

Lemma typsubst_open_exp_typ_neq : forall C Y, lc_typ C ->
    forall Z (e:exp), Z <> Y ->
      typsubst_exp C Y (open_exp_wrt_typ e (t_tvar_f Z)) =
      open_exp_wrt_typ (typsubst_exp C Y e) (t_tvar_f Z).
Proof.
  intros C Y HC Z e Hne.
  unfold open_exp_wrt_typ.
  rewrite (typsubst_open_exp_typ_dep C Y HC 0 Z e).
  destruct (eq_var Z Y) as [Heq|Hne']; [exfalso; apply Hne; exact Heq|reflexivity].
Qed.

Lemma typsubst_tvar_same : forall C Y, typsubst_typ C Y (t_tvar_f Y) = C.
Proof.
  intros. simpl.
  destruct (eq_var Y Y) as [Heq|Hne]; [reflexivity|exfalso; apply Hne; reflexivity].
Qed.

Lemma typsubst_tvar_neq : forall C Y Z, Z <> Y ->
    typsubst_typ C Y (t_tvar_f Z) = t_tvar_f Z.
Proof.
  intros. simpl.
  destruct (eq_var Z Y) as [Heq|Hne]; [exfalso; apply H; exact Heq|reflexivity].
Qed.

(* Substitution is the identity on types with no occurrence of the variable. *)

Lemma typsubst_typ_id_notin : forall C Y A,
    Y \notin typefv_typ A -> typsubst_typ C Y A = A.
Proof.
  intros C Y A. induction A as
    [n|X| | | |A1 IH1 A2 IH2|A1 IH1 A2 IH2|A1 IH1 A2 IH2|l A1 IH1];
    intros H; simpl in *.
  - reflexivity.
  - destruct (eq_var X Y) as [Heq|Hne]; [|reflexivity].
    exfalso. exact ((notin_singleton_1 X Y H) Heq).
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - simpl.
    rewrite (IH1 (notin_union_1 Y (typefv_typ A1) (typefv_typ A2) H)).
    rewrite (IH2 (notin_union_2 Y (typefv_typ A1) (typefv_typ A2) H)).
    reflexivity.
  - simpl.
    rewrite (IH1 (notin_union_1 Y (typefv_typ A1) (typefv_typ A2) H)).
    rewrite (IH2 (notin_union_2 Y (typefv_typ A1) (typefv_typ A2) H)).
    reflexivity.
  - simpl.
    rewrite (IH1 (notin_union_1 Y (typefv_typ A1) (typefv_typ A2) H)).
    rewrite (IH2 (notin_union_2 Y (typefv_typ A1) (typefv_typ A2) H)).
    reflexivity.
  - simpl. rewrite (IH1 H). reflexivity.
Qed.

(* ================================================================== *)
(* Type substitution preserves TWell                                   *)
(* ================================================================== *)

Lemma TWell_cons_weaken : forall (D:tctx) A Z B,
    TWell D A -> TWell (cons (Z,B) D) A.
Proof.
  intros D A Z B HT.
  apply (TWell_weaken D (cons (Z,B) D) A HT).
  intros X C Hc. apply binds_cons. exact Hc.
Qed.

Lemma typsubst_TWell_gen : forall (D:tctx) Y Dom A,
    TWell D A ->
    forall Delta, D = Delta ++ [(Y,Dom)] -> Y \notin dom Delta ->
    forall C, TWell (subst_tctx C Y Delta) C ->
      TWell (subst_tctx C Y Delta) (typsubst_typ C Y A).
Proof.
  intros D Y Dom A H.
  induction H as
    [D
    |D
    |D
    |D X A Hb
    |D l A HT IH
    |D A B H1 IH1 H2 IH2
    |D A B H1 IH1 H2 IH2
    |L D A B HA IHA Hbody IHB];
    intros Delta Heq Hfresh C HC.
  - apply TW_top.
  - apply TW_bot.
  - apply TW_int.
  - (* TW_var *)
    subst D.
    destruct (eq_var X Y) as [HeqXY|Hne].
    + subst X. rewrite typsubst_tvar_same. exact HC.
    + rewrite (typsubst_tvar_neq C Y X Hne).
      apply (TW_var (subst_tctx C Y Delta) X (typsubst_typ C Y A)).
      apply (binds_subst_tctx C Y Delta X A).
      apply (binds_app_neq Delta Y Dom X A Hne).
      exact Hb.
  - simpl. apply TW_rcd. eapply IH; eassumption.
  - simpl. apply TW_arrow; [eapply IH1; eassumption | eapply IH2; eassumption].
  - simpl. apply TW_and; [eapply IH1; eassumption | eapply IH2; eassumption].
  - (* TW_all *)
    assert (HlcC : lc_typ C)
      by (apply TWell_lc with (D := subst_tctx C Y Delta); exact HC).
    apply (TW_all (L \u ({{Y}} \u dom Delta))
                  (subst_tctx C Y Delta)
                  (typsubst_typ C Y A) (typsubst_typ C Y B)).
    + eapply IHA; eassumption.
    + intros Z HZ.
      assert (HZL : Z \notin L)
        by (apply (notin_union_1 Z L ({{Y}} \u dom Delta)); exact HZ).
      assert (HZrest : Z \notin ({{Y}} \u dom Delta))
        by (apply (notin_union_2 Z L ({{Y}} \u dom Delta)); exact HZ).
      assert (HZsing : Z \notin {{Y}})
        by (apply (notin_union_1 Z {{Y}} (dom Delta)); exact HZrest).
      assert (HZD : Z \notin dom Delta)
        by (apply (notin_union_2 Z {{Y}} (dom Delta)); exact HZrest).
      assert (HZY : Y <> Z) by (apply (notin_singleton_1 Y Z); exact HZsing).
      assert (HYZ : Z <> Y) by (intro HeqZY; apply HZY; symmetry; exact HeqZY).
      assert (Hfresh' : Y \notin dom (cons (Z,A) Delta)).
      { apply (notin_dom_cons Delta Z A Y HZY). exact Hfresh. }
      assert (HC' : TWell (subst_tctx C Y (cons (Z,A) Delta)) C).
      { rewrite subst_tctx_cons.
        apply (TWell_cons_weaken (subst_tctx C Y Delta) C Z
                                  (typsubst_typ C Y A) HC). }
      assert (Heq' : cons (Z,A) D = cons (Z,A) Delta ++ [(Y,Dom)]).
      { simpl. rewrite Heq. reflexivity. }
      pose proof (IHB Z HZL (cons (Z,A) Delta) Heq' Hfresh' C HC') as Hres.
      rewrite subst_tctx_cons in Hres.
      rewrite (typsubst_open_typ_neq C Y HlcC Z B HYZ) in Hres.
      exact Hres.
Qed.

(* TCWell is preserved when the substituted-variable binder is dropped. *)

(* TCWell is preserved when the substituted-variable binder is dropped,
   provided the replacement type is closed (well formed in the empty
   type context); without that condition the statement is false. *)

Lemma typsubst_TCWell_drop : forall (Delta:tctx) Y Dom,
    Y \notin dom Delta ->
    TCWell (Delta ++ [(Y,Dom)]) ->
    forall C, TWell nil C -> TCWell (subst_tctx C Y Delta).
Proof.
  intros Delta. induction Delta as [|[Z A] Delta IH];
    intros Y Dom Hfresh HTC C HCnil.
  - simpl. apply TCW_empty.
  - simpl in HTC. simpl.
    assert (HnotZ : Y \notin dom Delta).
    { apply (notin_dom_cons_inv Delta Z A Y). exact Hfresh. }
    destruct (TCWell_cons_inv (Delta ++ [(Y,Dom)]) Z A HTC)
      as [HTC0 HT0].
    assert (Huniq0 : uniq (Delta ++ [(Y,Dom)]))
      by (apply TCWell_uniq; exact HTC0).
    assert (HZnotApp : Z \notin dom (Delta ++ [(Y,Dom)]))
      by (apply (uniq_cons_2 typ Z A (Delta ++ [(Y,Dom)]));
          apply TCWell_uniq; exact HTC).
    assert (HZnotDelta : Z \notin dom Delta).
    { intro Hin. apply HZnotApp.
      rewrite (dom_app typ Delta [(Y,Dom)]).
      apply AtomSetImpl.union_2. exact Hin. }
    assert (HC : TWell (subst_tctx C Y Delta) C).
    { apply (TWell_weaken nil (subst_tctx C Y Delta) C HCnil).
      intros W B Hb. destruct Hb. }
    assert (HTCp : TCWell (subst_tctx C Y Delta)).
    { apply (IH Y Dom HnotZ HTC0 C HCnil). }
    assert (HTp : TWell (subst_tctx C Y Delta) (typsubst_typ C Y A)).
    { apply (typsubst_TWell_gen (Delta ++ [(Y,Dom)]) Y Dom A HT0
                                 Delta eq_refl HnotZ C HC). }
    assert (Hu : uniq (cons (Z, typsubst_typ C Y A) (subst_tctx C Y Delta))).
    { apply uniq_cons.
      - apply uniq_subst_tctx. apply (uniq_app_1 Delta [(Y,Dom)]). exact Huniq0.
      - rewrite (dom_subst_tctx C Y Delta). exact HZnotDelta. }
    apply (TCW_cons (subst_tctx C Y Delta) Z (typsubst_typ C Y A) HTCp HTp Hu).
Qed.

(* CWell is preserved. *)

Lemma typsubst_CWell_gen : forall (D:tctx) Y Dom G,
    CWell D G ->
    forall Delta, D = Delta ++ [(Y,Dom)] -> Y \notin dom Delta ->
    forall C, TWell (subst_tctx C Y Delta) C ->
      CWell (subst_tctx C Y Delta) (subst_ctx C Y G).
Proof.
  intros D Y Dom G HCW.
  induction HCW as [D | D G0 x A HCW0 IH HT];
    intros Delta Heq Hfresh C HC.
  - simpl. apply CW_empty.
  - simpl. apply CW_cons.
    + eapply IH; eassumption.
    + apply (typsubst_TWell_gen D Y Dom A HT Delta Heq Hfresh C HC).
Qed.

(* ================================================================== *)
(* Context splitting: the substituted variable may occur in the middle
   of the type context.  D1 binders are substituted, the (X,Dom) binder
   is dropped, and D2 binders are left untouched.                       *)
(* ================================================================== *)

Definition tsubst_mid (C:typ) (X:typevar) (D1 D2:tctx) : tctx :=
  subst_tctx C X D1 ++ D2.

Lemma binds_mid_far : forall (D1 D2:tctx) X Dom Y B,
    Y <> X -> binds Y B (D1 ++ (X,Dom) :: D2) ->
    binds Y B D1 \/ binds Y B D2.
Proof.
  intros D1 D2 X Dom Y B Hne Hb.
  apply in_app_or in Hb. destruct Hb as [Hin | Hin].
  - left. exact Hin.
  - right. simpl in Hin. destruct Hin as [Heq | Hin].
    + inversion Heq; subst. exfalso. exact (Hne eq_refl).
    + exact Hin.
Qed.

Lemma binds_mid_left : forall C X D1 D2 Y B,
    binds Y B D1 ->
    binds Y (typsubst_typ C X B) (tsubst_mid C X D1 D2).
Proof.
  intros. unfold tsubst_mid. apply in_or_app. left.
  apply binds_subst_tctx. exact H.
Qed.

Lemma binds_mid_right : forall C X D1 D2 Y B,
    binds Y B D2 -> binds Y B (tsubst_mid C X D1 D2).
Proof.
  intros. unfold tsubst_mid. apply in_or_app. right. exact H.
Qed.

Lemma notin_dom_mid_cons : forall (D1 D2:tctx) X Z A,
    X \notin dom (D1 ++ D2) -> X <> Z ->
    X \notin dom ((Z,A) :: D1 ++ D2).
Proof.
  intros D1 D2 X Z A HX Hne.
  change (X \notin dom (cons (Z,A) (D1 ++ D2))).
  apply (notin_dom_cons (D1 ++ D2) Z A X Hne HX).
Qed.

Lemma TWell_typsubst_mid_gen : forall (D0:tctx) X A,
    TWell D0 A ->
    forall D1 Dom D2, D0 = D1 ++ (X,Dom) :: D2 ->
      X \notin dom (D1 ++ D2) ->
      forall C, TWell (tsubst_mid C X D1 D2) C ->
        TWell (tsubst_mid C X D1 D2) (typsubst_typ C X A).
Proof.
  intros D0 X A H.
  induction H as
    [D0
    |D0
    |D0
    |D0 Y A0 Hb
    |D0 l A0 HT IH
    |D0 A0 B0 H1 IH1 H2 IH2
    |D0 A0 B0 H1 IH1 H2 IH2
    |L D0 A0 B0 HA IHA Hbody IHB];
    intros D1 Dom D2 Heq Hfresh C HC.
  - apply TW_top.
  - apply TW_bot.
  - apply TW_int.
  - (* TW_var *)
    subst D0.
    destruct (eq_var Y X) as [HeqYX|Hne].
    + subst Y. rewrite typsubst_tvar_same. exact HC.
    + rewrite (typsubst_tvar_neq C X Y Hne).
      destruct (binds_mid_far D1 D2 X Dom Y A0 Hne Hb) as [Hb1|Hb2].
      * apply (TW_var (tsubst_mid C X D1 D2) Y (typsubst_typ C X A0)).
        apply binds_mid_left. exact Hb1.
      * apply (TW_var (tsubst_mid C X D1 D2) Y A0).
        apply binds_mid_right. exact Hb2.
  - simpl. apply TW_rcd. eapply IH; eassumption.
  - simpl. apply TW_arrow; [eapply IH1; eassumption | eapply IH2; eassumption].
  - simpl. apply TW_and; [eapply IH1; eassumption | eapply IH2; eassumption].
  - (* TW_all *)
    assert (HlcC : lc_typ C)
      by (apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HC).
    apply (TW_all (L \u {{X}}) (tsubst_mid C X D1 D2)
                  (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + eapply IHA; eassumption.
    + intros Z HZ.
      assert (HZL : Z \notin L)
        by (apply (notin_union_1 Z L {{X}}); exact HZ).
      assert (HZX : Z \notin {{X}})
        by (apply (notin_union_2 Z L {{X}}); exact HZ).
      assert (HXZ : X <> Z) by (apply (notin_singleton_1 X Z); exact HZX).
      assert (HZX' : Z <> X) by (intro HeqZX; apply HXZ; symmetry; exact HeqZX).
      assert (Hfresh' : X \notin dom ((Z,A0) :: D1 ++ D2)).
      { apply (notin_dom_mid_cons D1 D2 X Z A0 Hfresh HXZ). }
      assert (HC' : TWell (tsubst_mid C X ((Z,A0) :: D1) D2) C).
      { change (TWell (cons (Z, typsubst_typ C X A0)
                            (tsubst_mid C X D1 D2)) C).
        apply (TWell_cons_weaken (tsubst_mid C X D1 D2) C Z
                                  (typsubst_typ C X A0) HC). }
      assert (Heq' : cons (Z,A0) D0 =
                     ((Z,A0) :: D1) ++ (X,Dom) :: D2).
      { simpl. rewrite Heq. reflexivity. }
      pose proof (IHB Z HZL ((Z,A0) :: D1) Dom D2 Heq' Hfresh' C HC')
        as Hres.
      rewrite (typsubst_open_typ_neq C X HlcC Z B0 HZX') in Hres.
      change (TWell (cons (Z, typsubst_typ C X A0)
                          (tsubst_mid C X D1 D2))
                    (open_typ_wrt_typ (typsubst_typ C X B0) (t_tvar_f Z)))
        in Hres.
      exact Hres.
Qed.

(* The common special case: the substituted binder is at the head. *)
Lemma TWell_typsubst_head : forall (D:tctx) X Dom C A,
    X \notin dom D ->
    TWell (cons (X,Dom) D) A ->
    TWell (tsubst_mid C X nil D) C ->
    TWell (tsubst_mid C X nil D) (typsubst_typ C X A).
Proof.
  intros D X Dom C A Hfresh HT HC.
  change (TWell (subst_tctx C X nil ++ D) C) in HC.
  change (TWell (subst_tctx C X nil ++ D)
                (typsubst_typ C X A)).
  apply (TWell_typsubst_mid_gen (cons (X,Dom) D) X A HT nil Dom D
                                 eq_refl Hfresh C HC).
Qed.

(* ================================================================== *)
(* Type substitution preserves CWell (term contexts)                   *)
(* ================================================================== *)

Lemma CWell_typsubst_mid_gen : forall (D0:tctx) G,
    CWell D0 G ->
    forall D1 X Dom D2, D0 = D1 ++ (X,Dom) :: D2 ->
      X \notin dom (D1 ++ D2) ->
      forall C, TWell (tsubst_mid C X D1 D2) C ->
        CWell (tsubst_mid C X D1 D2) (subst_ctx C X G).
Proof.
  intros D0 G H.
  induction H as [D0 | D0 G0 x A HCG IH HTA];
    intros D1 X Dom D2 Heq Hfresh C HC.
  - simpl. apply CW_empty.
  - simpl. apply CW_cons.
    + apply (IH D1 X Dom D2 Heq Hfresh C HC).
    + apply (TWell_typsubst_mid_gen D0 X A HTA D1 Dom D2
                                     Heq Hfresh C HC).
Qed.

Lemma CWell_typsubst_head : forall (D:tctx) X Dom C G,
    X \notin dom D ->
    CWell (cons (X,Dom) D) G ->
    TWell D C ->
    CWell D (subst_ctx C X G).
Proof.
  intros D X Dom C G Hfresh HCW HC.
  change (TWell (tsubst_mid C X nil D) C) in HC.
  change (CWell (tsubst_mid C X nil D) (subst_ctx C X G)).
  apply (CWell_typsubst_mid_gen (cons (X,Dom) D) G HCW
                                 nil X Dom D eq_refl Hfresh C HC).
Qed.

(* ================================================================== *)
(* Context-free relations                                              *)
(* ================================================================== *)

Lemma typsubst_botLike : forall C X, lc_typ C ->
    forall A, botLike A -> botLike (typsubst_typ C X A).
Proof.
  intros C X HC A H. induction H as
    [|A B HlcB HA IHA|A B HlcA HB IHB].
  - simpl. apply BL_bot.
  - simpl. apply BL_andl.
    + apply lc_typ_typsubst; assumption.
    + exact IHA.
  - simpl. apply BL_andr.
    + apply lc_typ_typsubst; assumption.
    + exact IHB.
Qed.

Lemma typsubst_ord : forall C X, lc_typ C -> ord C ->
    forall A, ord A -> ord (typsubst_typ C X A).
Proof.
  intros C X HC HordC A H. induction H as
    [Y| | | |A B HlcA HordB IHB|L A B HlcA Hbody IHbody
    |l B HordB IHB].
  - simpl. destruct (eq_var Y X) as [Heq|Hne].
    + subst Y. simpl. exact HordC.
    + apply O_var.
  - simpl. apply O_top.
  - simpl. apply O_bot.
  - simpl. apply O_int.
  - simpl. apply O_arrow.
    + apply lc_typ_typsubst; assumption.
    + exact IHB.
  - simpl. apply (O_all (L \u {{X}}) (typsubst_typ C X A)
                         (typsubst_typ C X B)).
    + apply lc_typ_typsubst; assumption.
    + intros Z HZ.
      assert (HZL : Z \notin L)
        by (apply (notin_union_1 Z L {{X}}); exact HZ).
      assert (HZX : Z \notin {{X}})
        by (apply (notin_union_2 Z L {{X}}); exact HZ).
      assert (HXZ : X <> Z) by (apply (notin_singleton_1 X Z); exact HZX).
      assert (HZX' : Z <> X) by (intro HeqZX; apply HXZ; symmetry; exact HeqZX).
      rewrite <- (typsubst_open_typ_neq C X HC Z B HZX').
      apply (IHbody Z HZL).
  - simpl. apply O_rcd. exact IHB.
Qed.

Lemma typsubst_spl : forall C X, lc_typ C ->
    forall A B D, spl A B D ->
      spl (typsubst_typ C X A) (typsubst_typ C X B)
          (typsubst_typ C X D).
Proof.
  intros C X HC A B D H. induction H as
    [A B C1 C2 HlcA HB IHB
    |L A B C1 C2 HlcA Hbody IHbody
    |l B C1 C2 HB IHB
    |A B HlcA HlcB].
  - simpl. apply Sp_arrow.
    + apply lc_typ_typsubst; assumption.
    + exact IHB.
  - simpl. apply (Sp_all (L \u {{X}}) (typsubst_typ C X A)
                          (typsubst_typ C X B) (typsubst_typ C X C1)
                          (typsubst_typ C X C2)).
    + apply lc_typ_typsubst; assumption.
    + intros Z HZ.
      assert (HZL : Z \notin L)
        by (apply (notin_union_1 Z L {{X}}); exact HZ).
      assert (HZX : Z \notin {{X}})
        by (apply (notin_union_2 Z L {{X}}); exact HZ).
      assert (HXZ : X <> Z) by (apply (notin_singleton_1 X Z); exact HZX).
      assert (HZX' : Z <> X) by (intro HeqZX; apply HXZ; symmetry; exact HeqZX).
      pose proof (IHbody Z HZL) as Hres.
      rewrite (typsubst_open_typ_neq C X HC Z B HZX') in Hres.
      rewrite (typsubst_open_typ_neq C X HC Z C1 HZX') in Hres.
      rewrite (typsubst_open_typ_neq C X HC Z C2 HZX') in Hres.
      exact Hres.
  - simpl. apply Sp_rcd. exact IHB.
  - simpl. apply Sp_and.
    + apply lc_typ_typsubst; assumption.
    + apply lc_typ_typsubst; assumption.
Qed.

Lemma typsubst_appDist : forall C X, lc_typ C ->
    forall A B, appDist A B ->
      appDist (typsubst_typ C X A) (typsubst_typ C X B).
Proof.
  intros C X HC A B H. induction H as
    [A1 A2 B1 B2 C1 C2 H1 IH1 H2 IH2
    |A1 A2 l B1 B2 H1 IH1 H2 IH2
    |A1 A2 B1 B2 C1 C2 H1 IH1 H2 IH2
    |A HlcA].
  - simpl in IH1, IH2. simpl.
    apply (AD_andArrow (typsubst_typ C X A1) (typsubst_typ C X A2)
                       (typsubst_typ C X B1) (typsubst_typ C X B2)
                       (typsubst_typ C X C1) (typsubst_typ C X C2));
      assumption.
  - simpl in IH1, IH2. simpl.
    apply (AD_andRcd (typsubst_typ C X A1) (typsubst_typ C X A2) l
                     (typsubst_typ C X B1) (typsubst_typ C X B2));
      assumption.
  - simpl in IH1, IH2. simpl.
    apply (AD_andAll (typsubst_typ C X A1) (typsubst_typ C X A2)
                     (typsubst_typ C X B1) (typsubst_typ C X B2)
                     (typsubst_typ C X C1) (typsubst_typ C X C2));
      assumption.
  - simpl. apply AD_refl. apply lc_typ_typsubst; assumption.
Qed.

Lemma typsubst_subsub : forall C X, lc_typ C ->
    forall A B, subsub A B -> subsub (typsubst_typ C X A) (typsubst_typ C X B).
Proof.
  intros C X HC A B H. induction H as
    [A HlcA |A1 A2 B B1 B2 Hspl H1 IH1 H2 IH2].
  - simpl. apply IS_refl. apply lc_typ_typsubst; assumption.
  - simpl. apply (IS_and (typsubst_typ C X A1) (typsubst_typ C X A2)
                         (typsubst_typ C X B) (typsubst_typ C X B1)
                         (typsubst_typ C X B2)).
    + apply (typsubst_spl C X HC B B1 B2 Hspl).
    + exact IH1.
    + exact IH2.
Qed.

(* ================================================================== *)
(* Context-dependent relations: topLike                                *)
(* ================================================================== *)

Lemma topLike_typsubst_mid_gen : forall (D0:tctx) A,
    topLike D0 A ->
    forall D1 X Dom D2, D0 = D1 ++ (X,Dom) :: D2 ->
      X \notin dom (D1 ++ D2) ->
      forall C,
        TCWell (tsubst_mid C X D1 D2) ->
        TWell (tsubst_mid C X D1 D2) C ->
        topLike (tsubst_mid C X D1 D2) C ->
        topLike (tsubst_mid C X D1 D2) (typsubst_typ C X A).
Proof.
  intros D0 A H.
  induction H as
    [D0 HTC
    |D0 A1 B1 HA IHA HB IHB
    |D0 A1 B1 HTA HB IHB
    |D0 l B1 HB IHB
    |L D0 A1 B1 Hbody IHBODY
    |D0 Y A1 HTC Hb Hbot];
    intros D1 X Dom D2 Heq Hfresh C HTCt HCT HtopC.
  - simpl. apply TL_top. exact HTCt.
  - simpl. apply TL_and.
    + apply (IHA D1 X Dom D2 Heq Hfresh C HTCt HCT HtopC).
    + apply (IHB D1 X Dom D2 Heq Hfresh C HTCt HCT HtopC).
  - simpl. apply TL_arrow.
    + apply (TWell_typsubst_mid_gen D0 X A1 HTA D1 Dom D2
                                     Heq Hfresh C HCT).
    + apply (IHB D1 X Dom D2 Heq Hfresh C HTCt HCT HtopC).
  - simpl. apply TL_rcd.
    apply (IHB D1 X Dom D2 Heq Hfresh C HTCt HCT HtopC).
  - (* TL_all *)
    assert (HTA1 : TWell D0 A1).
    { apply (topLike_all_dom D0 A1 B1).
      apply (TL_all L D0 A1 B1 Hbody). }
    assert (HlcC : lc_typ C)
      by (apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT).
    set (Dtg := tsubst_mid C X D1 D2).
    apply (TL_all (L \u ({{X}} \u dom Dtg)) Dtg
                  (typsubst_typ C X A1) (typsubst_typ C X B1)).
    intros Z HZ.
    assert (HZL : Z \notin L)
      by (apply (notin_union_1 Z L ({{X}} \u dom Dtg)); exact HZ).
    assert (HZrest : Z \notin ({{X}} \u dom Dtg))
      by (apply (notin_union_2 Z L ({{X}} \u dom Dtg)); exact HZ).
    assert (HZsing : Z \notin {{X}})
      by (apply (notin_union_1 Z {{X}} (dom Dtg)); exact HZrest).
    assert (HZDtg : Z \notin dom Dtg)
      by (apply (notin_union_2 Z {{X}} (dom Dtg)); exact HZrest).
    assert (HXZ : X <> Z) by (apply (notin_singleton_1 X Z); exact HZsing).
    assert (HZX' : Z <> X) by (intro HeqZX; apply HXZ; symmetry; exact HeqZX).
    assert (Hfresh' : X \notin dom (((Z,A1) :: D1) ++ D2)).
    { apply (notin_dom_mid_cons D1 D2 X Z A1 Hfresh HXZ). }
    assert (HTA1sub : TWell Dtg (typsubst_typ C X A1)).
    { unfold Dtg. apply (TWell_typsubst_mid_gen D0 X A1 HTA1
                          D1 Dom D2 Heq Hfresh C HCT). }
    assert (HuniqT : uniq Dtg) by (apply TCWell_uniq; exact HTCt).
    assert (HTCtg' : TCWell (cons (Z, typsubst_typ C X A1) Dtg)).
    { apply (TCW_cons Dtg Z (typsubst_typ C X A1) HTCt HTA1sub).
      apply (uniq_cons typ Z (typsubst_typ C X A1) Dtg HuniqT HZDtg). }
    assert (HCtg' : TWell (cons (Z, typsubst_typ C X A1) Dtg) C).
    { apply (TWell_cons_weaken Dtg C Z (typsubst_typ C X A1) HCT). }
    assert (HtopC' : topLike (cons (Z, typsubst_typ C X A1) Dtg) C).
    { apply (topLike_weaken Dtg (cons (Z, typsubst_typ C X A1) Dtg) C
                             HtopC HTCtg').
      intros W B Hb. apply binds_cons_3. exact Hb. }
    assert (HeqZ : cons (Z,A1) D0 =
                   ((Z,A1) :: D1) ++ (X,Dom) :: D2).
    { simpl. rewrite Heq. reflexivity. }
    pose proof (IHBODY Z HZL ((Z,A1) :: D1) X Dom D2 HeqZ Hfresh'
                  C HTCtg' HCtg' HtopC') as Hres.
    rewrite (typsubst_open_typ_neq C X HlcC Z B1 HZX') in Hres.
    change (topLike (cons (Z, typsubst_typ C X A1) Dtg)
                    (open_typ_wrt_typ (typsubst_typ C X B1) (t_tvar_f Z)))
      in Hres.
    exact Hres.
  - (* TL_var *)
    subst D0. simpl. destruct (eq_var Y X) as [HeqYX|Hne].
    + subst Y. simpl. exact HtopC.
    + destruct (binds_mid_far D1 D2 X Dom Y A1 Hne Hb) as [Hb1|Hb2].
      * apply (TL_var (tsubst_mid C X D1 D2) Y (typsubst_typ C X A1)).
        -- exact HTCt.
        -- apply binds_mid_left. exact Hb1.
        -- apply typsubst_botLike.
           ++ apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT.
           ++ exact Hbot.
      * apply (TL_var (tsubst_mid C X D1 D2) Y A1).
        -- exact HTCt.
        -- apply binds_mid_right. exact Hb2.
        -- exact Hbot.
Qed.

Lemma topLike_typsubst_head : forall (D:tctx) X Dom C A,
    X \notin dom D ->
    topLike (cons (X,Dom) D) A ->
    TCWell (tsubst_mid C X nil D) ->
    TWell (tsubst_mid C X nil D) C ->
    topLike (tsubst_mid C X nil D) C ->
    topLike (tsubst_mid C X nil D) (typsubst_typ C X A).
Proof.
  intros D X Dom C A Hfresh HT HTC HCT HtopC.
  apply (topLike_typsubst_mid_gen (cons (X,Dom) D) A HT
                                   nil X Dom D eq_refl Hfresh C
                                   HTC HCT HtopC).
Qed.

(* ================================================================== *)
(* Context-dependent relations: algorithmic subtyping                  *)
(* ================================================================== *)

Lemma algo_sub_typsubst_mid_gen : forall (D0:tctx) A B,
    algo_sub D0 A B ->
    forall D1 X Dom D2, D0 = D1 ++ (X,Dom) :: D2 ->
      X \notin dom (D1 ++ D2) ->
      forall C, TCWell D0 ->
        TCWell (tsubst_mid C X D1 D2) ->
        TWell (tsubst_mid C X D1 D2) C ->
        ord C ->
        topLike (tsubst_mid C X D1 D2) C ->
        algo_sub (tsubst_mid C X D1 D2) C C ->
        algo_sub (tsubst_mid C X D1 D2)
                 (typsubst_typ C X A) (typsubst_typ C X B).
Proof.
  intros D0 A B Hsub.
  induction Hsub as
    [D0 Y HTC0 HTA
    |D0 HTC0
    |D0 A0 B0 HTA HordB HtopB
    |D0 A0 HTC0 HTA HordA
    |D0 A0 B0 C0 HTB HordC0 Hsub0 IH0
    |D0 A0 B0 C0 HTA HordC0 Hsub0 IH0
    |D0 A1 B1 A2 B2 HordB2 Hsub1 IH1 Hsub2 IH2
    |L D0 A1 A2 B1 B2 HordBody Hsub1 IH1 Hbody IHBODY
    |D0 l A0 B0 HordB0 Hsub0 IH0
    |D0 A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2];
    intros D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT HordC HtopC Hself.
  - (* S_var *)
    simpl. destruct (eq_var Y X) as [HeqYX|Hne].
    + subst Y. simpl. exact Hself.
    + apply S_var.
      * exact HTCt.
      * rewrite <- (typsubst_tvar_neq C X Y Hne).
        apply (TWell_typsubst_mid_gen D0 X (t_tvar_f Y) HTA
                 D1 Dom D2 Heq Hfresh C HCT).
  - (* S_int *)
    simpl. apply S_int. exact HTCt.
  - (* S_top *)
    simpl. apply S_top.
    + apply (TWell_typsubst_mid_gen D0 X A0 HTA
               D1 Dom D2 Heq Hfresh C HCT).
    + apply (typsubst_ord C X).
      * apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT.
      * exact HordC.
      * exact HordB.
    + apply (topLike_typsubst_mid_gen D0 B0 HtopB
               D1 X Dom D2 Heq Hfresh C HTCt HCT HtopC).
  - (* S_bot *)
    simpl. apply S_bot.
    + exact HTCt.
    + apply (TWell_typsubst_mid_gen D0 X A0 HTA
               D1 Dom D2 Heq Hfresh C HCT).
    + apply (typsubst_ord C X).
      * apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT.
      * exact HordC.
      * exact HordA.
  - (* S_andl *)
    simpl. apply S_andl.
    + apply (TWell_typsubst_mid_gen D0 X B0 HTB
               D1 Dom D2 Heq Hfresh C HCT).
    + apply (typsubst_ord C X).
      * apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT.
      * exact HordC.
      * exact HordC0.
    + apply (IH0 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT
                HordC HtopC Hself).
  - (* S_andr *)
    simpl. apply S_andr.
    + apply (TWell_typsubst_mid_gen D0 X A0 HTA
               D1 Dom D2 Heq Hfresh C HCT).
    + apply (typsubst_ord C X).
      * apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT.
      * exact HordC.
      * exact HordC0.
    + apply (IH0 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT
                HordC HtopC Hself).
  - (* S_arrow *)
    simpl. apply S_arrow.
    + apply (typsubst_ord C X).
      * apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT.
      * exact HordC.
      * exact HordB2.
    + apply (IH1 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT
                HordC HtopC Hself).
    + apply (IH2 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT
                HordC HtopC Hself).
  - (* S_all *)
    assert (HTB1 : TWell D0 B1).
    { apply (algo_sub_TWell_source D0 B1 A1 HTCsrc Hsub1). }
    assert (HlcC : lc_typ C)
      by (apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT).
    set (Dtg := tsubst_mid C X D1 D2).
    apply (S_all (L \u ({{X}} \u (dom D0 \u dom Dtg))) Dtg
                 (typsubst_typ C X A1) (typsubst_typ C X A2)
                 (typsubst_typ C X B1) (typsubst_typ C X B2)).
    + (* ord of the codomain body *)
      intros Z HZ.
      assert (HZL : Z \notin L)
        by (apply (notin_union_1 Z L ({{X}} \u (dom D0 \u dom Dtg))); exact HZ).
      assert (HZrest : Z \notin ({{X}} \u (dom D0 \u dom Dtg)))
        by (apply (notin_union_2 Z L ({{X}} \u (dom D0 \u dom Dtg))); exact HZ).
      assert (HZsing : Z \notin {{X}})
        by (apply (notin_union_1 Z {{X}} (dom D0 \u dom Dtg)); exact HZrest).
      assert (HZdd : Z \notin (dom D0 \u dom Dtg))
        by (apply (notin_union_2 Z {{X}} (dom D0 \u dom Dtg)); exact HZrest).
      assert (HZD0 : Z \notin dom D0)
        by (apply (notin_union_1 Z (dom D0) (dom Dtg)); exact HZdd).
      assert (HZDtg : Z \notin dom Dtg)
        by (apply (notin_union_2 Z (dom D0) (dom Dtg)); exact HZdd).
      assert (HXZ : X <> Z) by (apply (notin_singleton_1 X Z); exact HZsing).
      assert (HZX' : Z <> X) by (intro HeqZX; apply HXZ; symmetry; exact HeqZX).
      rewrite <- (typsubst_open_typ_neq C X HlcC Z B2 HZX').
      apply (typsubst_ord C X HlcC HordC (open_typ_wrt_typ B2 (t_tvar_f Z))).
      apply (HordBody Z HZL).
    + apply (IH1 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT
                HordC HtopC Hself).
    + intros Z HZ.
      assert (HZL : Z \notin L)
        by (apply (notin_union_1 Z L ({{X}} \u (dom D0 \u dom Dtg))); exact HZ).
      assert (HZrest : Z \notin ({{X}} \u (dom D0 \u dom Dtg)))
        by (apply (notin_union_2 Z L ({{X}} \u (dom D0 \u dom Dtg))); exact HZ).
      assert (HZsing : Z \notin {{X}})
        by (apply (notin_union_1 Z {{X}} (dom D0 \u dom Dtg)); exact HZrest).
      assert (HZdd : Z \notin (dom D0 \u dom Dtg))
        by (apply (notin_union_2 Z {{X}} (dom D0 \u dom Dtg)); exact HZrest).
      assert (HZD0 : Z \notin dom D0)
        by (apply (notin_union_1 Z (dom D0) (dom Dtg)); exact HZdd).
      assert (HZDtg : Z \notin dom Dtg)
        by (apply (notin_union_2 Z (dom D0) (dom Dtg)); exact HZdd).
      assert (HXZ : X <> Z) by (apply (notin_singleton_1 X Z); exact HZsing).
      assert (HZX' : Z <> X) by (intro HeqZX; apply HXZ; symmetry; exact HeqZX).
      assert (Hfresh' : X \notin dom (((Z,B1) :: D1) ++ D2)).
      { apply (notin_dom_mid_cons D1 D2 X Z B1 Hfresh HXZ). }
      assert (HTCsrc' : TCWell (cons (Z,B1) D0)).
      { apply (TCW_cons D0 Z B1 HTCsrc HTB1).
        apply (uniq_cons typ Z B1 D0 (TCWell_uniq D0 HTCsrc) HZD0). }
      assert (HTB1sub : TWell Dtg (typsubst_typ C X B1)).
      { unfold Dtg. apply (TWell_typsubst_mid_gen D0 X B1 HTB1
                           D1 Dom D2 Heq Hfresh C HCT). }
      assert (HTCtg' : TCWell (cons (Z, typsubst_typ C X B1) Dtg)).
      { apply (TCW_cons Dtg Z (typsubst_typ C X B1) HTCt HTB1sub).
        apply (uniq_cons typ Z (typsubst_typ C X B1) Dtg
                         (TCWell_uniq Dtg HTCt) HZDtg). }
      assert (HCtg' : TWell (cons (Z, typsubst_typ C X B1) Dtg) C).
      { apply (TWell_cons_weaken Dtg C Z (typsubst_typ C X B1) HCT). }
      assert (HtopC' : topLike (cons (Z, typsubst_typ C X B1) Dtg) C).
      { apply (topLike_weaken Dtg (cons (Z, typsubst_typ C X B1) Dtg) C
                               HtopC HTCtg').
        intros W Bx Hb. apply binds_cons_3. exact Hb. }
      assert (Hself' : algo_sub (cons (Z, typsubst_typ C X B1) Dtg) C C).
      { apply (algo_sub_weaken Dtg (cons (Z, typsubst_typ C X B1) Dtg) C C
                                HTCt HTCtg').
        - intros W Bx Hb. apply binds_cons_3. exact Hb.
        - exact Hself. }
      assert (HeqZ : cons (Z,B1) D0 =
                     ((Z,B1) :: D1) ++ (X,Dom) :: D2).
      { simpl. rewrite Heq. reflexivity. }
      pose proof (IHBODY Z HZL ((Z,B1) :: D1) X Dom D2 HeqZ Hfresh'
                    C HTCsrc' HTCtg' HCtg' HordC HtopC' Hself') as Hres.
      rewrite (typsubst_open_typ_neq C X HlcC Z A2 HZX') in Hres.
      rewrite (typsubst_open_typ_neq C X HlcC Z B2 HZX') in Hres.
      change (algo_sub (cons (Z, typsubst_typ C X B1) Dtg)
                       (open_typ_wrt_typ (typsubst_typ C X A2) (t_tvar_f Z))
                       (open_typ_wrt_typ (typsubst_typ C X B2) (t_tvar_f Z)))
        in Hres.
      exact Hres.
  - (* S_rcd *)
    simpl. apply S_rcd.
    + apply (typsubst_ord C X).
      * apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT.
      * exact HordC.
      * exact HordB0.
    + apply (IH0 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT
                HordC HtopC Hself).
  - (* S_and *)
    simpl.
    apply (S_and (tsubst_mid C X D1 D2)
                 (typsubst_typ C X A0) (typsubst_typ C X B0)
                 (typsubst_typ C X B1) (typsubst_typ C X B2)).
    + apply (typsubst_spl C X).
      * apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT.
      * exact Hspl.
    + apply (IH1 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT
                HordC HtopC Hself).
    + apply (IH2 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT
                HordC HtopC Hself).
Qed.

Lemma algo_sub_typsubst_head : forall (D:tctx) X Dom C A B,
    X \notin dom D ->
    algo_sub (cons (X,Dom) D) A B ->
    TCWell (cons (X,Dom) D) ->
    TCWell (tsubst_mid C X nil D) ->
    TWell (tsubst_mid C X nil D) C ->
    ord C ->
    topLike (tsubst_mid C X nil D) C ->
    algo_sub (tsubst_mid C X nil D) C C ->
    algo_sub (tsubst_mid C X nil D)
             (typsubst_typ C X A) (typsubst_typ C X B).
Proof.
  intros D X Dom C A B Hfresh Hsub HTCsrc HTCt HCT HordC HtopC Hself.
  apply (algo_sub_typsubst_mid_gen (cons (X,Dom) D) A B Hsub
                                    nil X Dom D eq_refl Hfresh C
                                    HTCsrc HTCt HCT HordC HtopC Hself).
Qed.

(* ================================================================== *)
(* Type substitution commutes with opening a term variable             *)
(* (needed for the Typ_abs / Typ_fix cases of typing substitution)     *)
(* ================================================================== *)

Lemma typsubst_open_exp_gen : forall C X k (r b:exp),
    typsubst_exp C X (open_exp_wrt_exp_rec k r b) =
    open_exp_wrt_exp_rec k (typsubst_exp C X r) (typsubst_exp C X b).
Proof.
  intros C X k r b. revert k.
  induction b as
    [n|y| |i|A b IHb|A b IHb|b1 IH1 b2 IH2|b1 IH1 b2 IH2
    |b IHb A|A b IHb|b IHb A|b IHb|b IHb A];
    intros k; simpl.
  - destruct (lt_eq_lt_dec n k) as [ [Hlt|Heq] | Hgt]; simpl; reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite (IHb (S k)). reflexivity.
  - rewrite (IHb (S k)). reflexivity.
  - rewrite (IH1 k), (IH2 k). reflexivity.
  - rewrite (IH1 k), (IH2 k). reflexivity.
  - rewrite (IHb k). reflexivity.
  - rewrite (IHb k). reflexivity.
  - rewrite (IHb k). reflexivity.
  - rewrite (IHb k). reflexivity.
  - rewrite (IHb k). reflexivity.
Qed.

Lemma typsubst_open_exp : forall C X (b r:exp),
    typsubst_exp C X (open_exp_wrt_exp b r) =
    open_exp_wrt_exp (typsubst_exp C X b) (typsubst_exp C X r).
Proof.
  intros. unfold open_exp_wrt_exp. apply typsubst_open_exp_gen.
Qed.

(* ================================================================== *)
(* Disjointness: the axiom layer is substitution-stable                *)
(* ================================================================== *)

Lemma typsubst_disjoint_axiom : forall C X A B,
    lc_typ C -> disjoint_axiom A B ->
    disjoint_axiom (typsubst_typ C X A) (typsubst_typ C X B).
Proof.
  intros C X A B HC Hax.
  induction Hax; simpl; try (econstructor; eauto using lc_typ_typsubst).
  all: match goal with
       | H : lc_typ (t_forall ?U ?V) |- lc_typ (t_forall ?U' ?V') =>
           apply (lc_typ_typsubst C X (t_forall U V)); assumption
       end.
Qed.

(* ================================================================== *)
(* Disjointness implies well-formedness (needed for the type argument   *)
(* of a type application in the PApp_tabs argument)                     *)
(* ================================================================== *)

Lemma disjoint_TWell_source_L : forall (D:tctx) A B,
    TCWell D -> disjoint D A B -> TWell D A.
Proof.
  intros D A B HTC H.
  induction H as
    [D A0 B0 HTC0 HTA HTB Hax
    |D A0 B0 HTB HtopA
    |D A0 B0 HTA HtopB
    |D A1 A2 B1 B2 HT1 HT2 Hsub IHsub
    |D l A0 B0 Hsub IHsub
    |L D A1 B1 A2 B2 HT1 HT2 Hbody IHB
    |D X B0 A0 Hb Hsub
    |D B0 X A0 Hb Hsub
    |D A0 B0 A1 A2 Hspl Hsub1 IH1 Hsub2 IH2
    |D A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2].
  - exact HTA.
  - apply (agentA.topLike_TWell D A0). exact HtopA.
  - exact HTA.
  - exact HT1.
  - apply TW_rcd. exact (IHsub HTC).
  - apply (TW_all (L \u dom D) D A1 B1).
    + exact HT1.
    + intros X HX.
      destruct (notin_union X L (dom D) HX) as [HXL HXD].
      assert (HTCcons : TCWell (cons (X, t_and A1 A2) D)).
      { apply (TCW_cons D X (t_and A1 A2) HTC).
        - apply TW_and; assumption.
        - apply (uniq_cons_3 typ X (t_and A1 A2) D).
          + apply (TCWell_uniq D HTC).
          + exact HXD. }
      pose proof (IHB X HXL HTCcons) as HTB1x.
      apply (TWell_dom_irrel (cons (X, t_and A1 A2) D)
                             (open_typ_wrt_typ B1 (t_tvar_f X))
                             HTB1x (cons (X, A1) D)).
      simpl. reflexivity.
  - apply (TW_var D X A0). exact Hb.
  - apply (algo_sub_TWell_target D A0 B0 HTC). exact Hsub.
  - apply (spl_back_TWell A0 A1 A2 Hspl D (IH1 HTC) (IH2 HTC)).
  - exact (IH1 HTC).
Qed.

Lemma disjoint_TWell_target_L : forall (D:tctx) A B,
    TCWell D -> disjoint D A B -> TWell D B.
Proof.
  intros D A B HTC H.
  induction H as
    [D A0 B0 HTC0 HTA HTB Hax
    |D A0 B0 HTB HtopA
    |D A0 B0 HTA HtopB
    |D A1 A2 B1 B2 HT1 HT2 Hsub IHsub
    |D l A0 B0 Hsub IHsub
    |L D A1 B1 A2 B2 HT1 HT2 Hbody IHB
    |D X B0 A0 Hb Hsub
    |D B0 X A0 Hb Hsub
    |D A0 B0 A1 A2 Hspl Hsub1 IH1 Hsub2 IH2
    |D A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2].
  - exact HTB.
  - exact HTB.
  - apply (agentA.topLike_TWell D B0). exact HtopB.
  - exact HT2.
  - apply TW_rcd. exact (IHsub HTC).
  - apply (TW_all (L \u dom D) D A2 B2).
    + exact HT2.
    + intros X HX.
      destruct (notin_union X L (dom D) HX) as [HXL HXD].
      assert (HTCcons : TCWell (cons (X, t_and A1 A2) D)).
      { apply (TCW_cons D X (t_and A1 A2) HTC).
        - apply TW_and; assumption.
        - apply (uniq_cons_3 typ X (t_and A1 A2) D).
          + apply (TCWell_uniq D HTC).
          + exact HXD. }
      pose proof (IHB X HXL HTCcons) as HTB2x.
      apply (TWell_dom_irrel (cons (X, t_and A1 A2) D)
                             (open_typ_wrt_typ B2 (t_tvar_f X))
                             HTB2x (cons (X, A2) D)).
      simpl. reflexivity.
  - apply (algo_sub_TWell_target D A0 B0 HTC). exact Hsub.
  - apply (TW_var D X A0). exact Hb.
  - exact (IH1 HTC).
  - apply (spl_back_TWell B0 B1 B2 Hspl D (IH1 HTC) (IH2 HTC)).
Qed.

(* ================================================================== *)
(* GAP / WARNING                                                       *)
(* ================================================================== *)
(* Unlike TWell, CWell, topLike and algo_sub, `disjoint` is NOT       *)
(* preserved by an arbitrary type substitution X := C.  Concrete      *)
(* counterexample: D0 = [(X,t_int)].  We have                          *)
(*   disjoint D0 (t_tvar_f X) t_int                                    *)
(* via D_varl (binds X t_int D0) and S_int.  Substituting X := t_int   *)
(* (X is at the head, so D2 = nil and the target context is nil)       *)
(* would require `disjoint nil t_int t_int`, which has no derivation   *)
(* (D_ax has no int/int axiom, D_topl/D_topr need topLike int, and     *)
(* D_varl/D_varr/D_andl/D_andr are inapplicable).  Hence any typing    *)
(* substitution theorem for Typ_merge / Typ_tapp must either carry a   *)
(* disjointness-preservation hypothesis or use additional hypotheses   *)
(* relating C to the type Dom of X.  All side conditions needed for    *)
(* the other relations are collected in the *_mid_gen lemmas above.   *)
(* ================================================================== *)
End agentL.
Import agentL.

Module agentL2.
Import ListNotations.

(* ================================================================== *)
(* General commutation of type substitution with opening.             *)
(* The [lc_typ C] hypothesis is essential: without it the statement    *)
(* fails for C containing dangling bound indices.                     *)
(* ================================================================== *)

Lemma typsubst_open_typ_rec_gen : forall C X, lc_typ C ->
    forall k (r b:typ),
      typsubst_typ C X (open_typ_wrt_typ_rec k r b) =
      open_typ_wrt_typ_rec k (typsubst_typ C X r) (typsubst_typ C X b).
Proof.
  intros C X HC k r b. revert k.
  induction b as
    [n|Y| | | |b1 IH1 b2 IH2|b1 IH1 b2 IH2|b1 IH1 b2 IH2|l b IHb];
    intros k; simpl.
  - destruct (lt_eq_lt_dec n k) as [ [Hlt|Heq] | Hgt]; simpl; reflexivity.
  - destruct (eq_var Y X) as [Heq|Hne].
    + subst Y. simpl. rewrite open_typ_lc_id; [reflexivity|exact HC].
    + simpl. reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite (IH1 k), (IH2 (S k)). reflexivity.
  - rewrite (IH1 k), (IH2 k). reflexivity.
  - rewrite (IH1 k), (IH2 k). reflexivity.
  - rewrite (IHb k). reflexivity.
Qed.

Lemma typsubst_open_typ_any : forall C X, lc_typ C ->
    forall (b r:typ),
      typsubst_typ C X (open_typ_wrt_typ b r) =
      open_typ_wrt_typ (typsubst_typ C X b) (typsubst_typ C X r).
Proof.
  intros. unfold open_typ_wrt_typ. apply typsubst_open_typ_rec_gen; assumption.
Qed.

Lemma typsubst_open_exp_typ_rec_gen : forall C X, lc_typ C ->
    forall k (r:typ) (b:exp),
      typsubst_exp C X (open_exp_wrt_typ_rec k r b) =
      open_exp_wrt_typ_rec k (typsubst_typ C X r) (typsubst_exp C X b).
Proof.
  intros C X HC k r b. revert k.
  induction b as
    [n|x| |i|A b IHb|A b IHb|b1 IH1 b2 IH2|b1 IH1 b2 IH2
    |b IHb A|l b IHb|b IHb l|b IHb|b IHb A];
    intros k; simpl.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite (typsubst_open_typ_rec_gen C X HC k r A).
    rewrite (IHb k). reflexivity.
  - rewrite (typsubst_open_typ_rec_gen C X HC k r A).
    rewrite (IHb k). reflexivity.
  - rewrite (IH1 k), (IH2 k). reflexivity.
  - rewrite (IH1 k), (IH2 k). reflexivity.
  - rewrite (IHb k), (typsubst_open_typ_rec_gen C X HC k r A). reflexivity.
  - rewrite (IHb k). reflexivity.
  - rewrite (IHb k). reflexivity.
  - rewrite (IHb (S k)). reflexivity.
  - rewrite (IHb k), (typsubst_open_typ_rec_gen C X HC k r A). reflexivity.
Qed.

Lemma typsubst_open_exp_typ_any : forall C X, lc_typ C ->
    forall (b:exp) (r:typ),
      typsubst_exp C X (open_exp_wrt_typ b r) =
      open_exp_wrt_typ (typsubst_exp C X b) (typsubst_typ C X r).
Proof.
  intros. unfold open_exp_wrt_typ. apply typsubst_open_exp_typ_rec_gen; assumption.
Qed.

(* ================================================================== *)
(* Binds: membership and uniqueness.                                  *)
(* ================================================================== *)

Lemma binds_in_dom : forall (D:tctx) X a,
    In (X,a) D -> AtomSetImpl.In X (dom D).
Proof.
  intros D. induction D as [|[Y b] D IH]; intros X a H.
  - inversion H.
  - simpl. simpl in H. destruct H as [Heq|Hin].
    + inversion Heq; subst. apply AtomSetImpl.add_1. reflexivity.
    + apply AtomSetImpl.add_2. exact (IH X a Hin).
Qed.

Lemma binds_uniq_eq : forall (D:tctx) X A B,
    uniq D -> binds X A D -> binds X B D -> A = B.
Proof.
  intros D. induction D as [|[Y C] D IH]; intros X A B Hu Hb1 Hb2.
  - inversion Hb1.
  - simpl in Hu.
    pose proof (uniq_cons_1 typ Y C D Hu) as HuD.
    pose proof (uniq_cons_2 typ Y C D Hu) as HYnot.
    simpl in Hb1, Hb2.
    destruct Hb1 as [Heq1|Hb1]; destruct Hb2 as [Heq2|Hb2].
    + inversion Heq1; inversion Heq2; subst; reflexivity.
    + inversion Heq1; subst. exfalso.
      exact (HYnot (binds_in_dom D X B Hb2)).
    + inversion Heq2; subst. exfalso.
      exact (HYnot (binds_in_dom D X A Hb1)).
    + apply (IH X A B HuD Hb1 Hb2).
Qed.

(* ================================================================== *)
(* TWell types mention no type variable that is not bound in the      *)
(* context.  In particular a type well formed in the empty context is  *)
(* closed for free type variables.                                    *)
(* ================================================================== *)

Lemma notin_typefv_open_tvar : forall k (B:typ) X Y,
    X <> Y ->
    X \notin typefv_typ (open_typ_wrt_typ_rec k (t_tvar_f Y) B) ->
    X \notin typefv_typ B.
Proof.
  intros k B. revert k. induction B as
    [n|Z| | | |B1 IH1 B2 IH2|B1 IH1 B2 IH2|B1 IH1 B2 IH2|l B IHB];
    intros k X Y Hne H.
  - simpl. apply AtomSetImpl.empty_1.
  - simpl in H. simpl. exact H.
  - simpl. apply AtomSetImpl.empty_1.
  - simpl. apply AtomSetImpl.empty_1.
  - simpl. apply AtomSetImpl.empty_1.
  - simpl in H. destruct (notin_union X _ _ H)
      as [H1 H2].
    intro Hin.
    destruct (AtomSetImpl.union_1 Hin) as [Hin1|Hin2].
    + exact (IH1 k X Y Hne H1 Hin1).
    + exact (IH2 (S k) X Y Hne H2 Hin2).
  - simpl in H. destruct (notin_union X _ _ H)
      as [H1 H2].
    intro Hin.
    destruct (AtomSetImpl.union_1 Hin) as [Hin1|Hin2].
    + exact (IH1 k X Y Hne H1 Hin1).
    + exact (IH2 k X Y Hne H2 Hin2).
  - simpl in H. destruct (notin_union X _ _ H)
      as [H1 H2].
    intro Hin.
    destruct (AtomSetImpl.union_1 Hin) as [Hin1|Hin2].
    + exact (IH1 k X Y Hne H1 Hin1).
    + exact (IH2 k X Y Hne H2 Hin2).
  - simpl in H. simpl. intro Hin. apply (IHB k X Y Hne H Hin).
Qed.

Lemma TWell_notin_dom_typefv : forall (D:tctx) A,
    TWell D A -> forall X, X \notin dom D -> X \notin typefv_typ A.
Proof.
  intros D A H.
  induction H as
    [D
    |D
    |D
    |D Z A0 Hb
    |D l A0 HA IHA
    |D A0 B0 HA IHA HB IHB
    |D A0 B0 HA IHA HB IHB
    |L D A0 B0 HA IHA Hbody IHBODY];
    intros X HX.
  - simpl. apply AtomSetImpl.empty_1.
  - simpl. apply AtomSetImpl.empty_1.
  - simpl. apply AtomSetImpl.empty_1.
  - simpl. intro Hin.
    pose proof (AtomSetImpl.singleton_1 Hin) as Heq.
    subst Z. exact (HX (binds_in_dom D X A0 Hb)).
  - simpl. intro Hin. exact (IHA X HX Hin).
  - simpl. intro Hin.
    destruct (AtomSetImpl.union_1 Hin) as [Hin1|Hin2].
    + exact (IHA X HX Hin1).
    + exact (IHB X HX Hin2).
  - simpl. intro Hin.
    destruct (AtomSetImpl.union_1 Hin) as [Hin1|Hin2].
    + exact (IHA X HX Hin1).
    + exact (IHB X HX Hin2).
  - simpl. intro Hin.
    destruct (AtomSetImpl.union_1 Hin) as [Hin1|Hin2].
    + exact (IHA X HX Hin1).
    + destruct (atom_fresh (L \u {{X}} \u dom D)) as [Y HY].
      destruct (notin_union Y L ({{X}} \u dom D) HY) as [HYL HYrest].
      destruct (notin_union Y {{X}} (dom D) HYrest) as [HYX HYD].
      assert (HYne : X <> Y) by (apply (notin_singleton_1 X Y); exact HYX).
      assert (HXY : X \notin dom D) by exact HX.
      assert (HXcons : X \notin dom (cons (Y,A0) D)).
      { rewrite dom_cons. intro Hin'.
        destruct (AtomSetImpl.union_1 Hin') as [HinY|HinD].
        - exact (HYne (eq_sym (AtomSetImpl.singleton_1 HinY))).
        - exact (HXY HinD). }
      assert (Hbody' : TWell (cons (Y,A0) D)
                              (open_typ_wrt_typ B0 (t_tvar_f Y)))
        by (apply (Hbody Y HYL)).
      pose proof (IHBODY Y HYL X HXcons) as Hnot.
      exact (notin_typefv_open_tvar 0 B0 X Y HYne Hnot Hin2).
Qed.

(* ================================================================== *)
(* ================================================================== *)
(* Disjointness with a bot-like right-hand type is strong: either the *)
(* left type is top-like, or the right type is not bot-like.  This is *)
(* what replaces the global "C is top-like" hypothesis of agentL's    *)
(* substitution lemmas.                                                *)
(* ================================================================== *)

Lemma disjoint_axiom_not_botLike_right : forall A B,
    disjoint_axiom A B -> botLike B -> False.
Proof.
  intros A B H. induction H; intro HB; simpl in HB; inversion HB.
Qed.

Lemma topLike_all_body_inv_local : forall D A B,
    topLike D (t_forall A B) ->
    exists L, forall X, X \notin L ->
      topLike (cons (X,A) D) (open_typ_wrt_typ B (t_tvar_f X)).
Proof.
  intros D A B H. inversion H; subst. eauto.
Qed.

Lemma spl_topLike_source : forall B B1 B2, spl B B1 B2 ->
    forall D, topLike D B1 -> topLike D B2 -> topLike D B.
Proof.
  intros B B1 B2 Hs. induction Hs as
    [ A0 P C1 C2 Hlc Hsp IHsp
    | L A0 P C1 C2 Hlc Hbody IHBODY
    | l P C1 C2 Hsp IHsp
    | A0 P HlcA HlcB ];
    intros D HT1 HT2.
  - destruct (topLike_arrow_inv D A0 C1 HT1) as [HTWA HTC1].
    destruct (topLike_arrow_inv D A0 C2 HT2) as [_ HTC2].
    apply (TL_arrow D A0 P HTWA).
    exact (IHsp D HTC1 HTC2).
  - destruct (topLike_all_body_inv_local D A0 C1 HT1) as [L1 Hb1].
    destruct (topLike_all_body_inv_local D A0 C2 HT2) as [L2 Hb2].
    apply (TL_all (((L \u L1) \u L2) \u dom D) D A0 P).
    intros X HX.
    destruct (notin_union X ((L \u L1) \u L2) (dom D) HX) as [HX123 HXD].
    destruct (notin_union X (L \u L1) L2 HX123) as [HX12 HXL2].
    destruct (notin_union X L L1 HX12) as [HXL HXL1].
    exact (IHBODY X HXL (cons (X, A0) D) (Hb1 X HXL1) (Hb2 X HXL2)).
  - apply (TL_rcd D l P).
    apply (IHsp D).
    + exact (topLike_rcd_inv D l C1 HT1).
    + exact (topLike_rcd_inv D l C2 HT2).
  - apply (TL_and D A0 P); assumption.
Qed.

Lemma disjoint_nil_topLike_or_not_botLike : forall A B,
    disjoint nil A B -> topLike nil A \/ ~ botLike B.
Proof.
  intros A B H.
  remember nil as D0 eqn:HD in H.
  induction H as
    [D A0 B0 HTC0 HTA HTB Hax
    |D A0 B0 HTB HtopA
    |D A0 B0 HTA HtopB
    |D A1 A2 B1 B2 HT1 HT2 Hsub IHsub
    |D l A0 B0 Hsub IHsub
    |L D A1 B1 A2 B2 HT1 HT2 Hbody IHB
    |D X B0 A0 Hb Hsub
    |D B0 X A0 Hb Hsub
    |D A0 B0 A1 A2 Hspl Hsub1 IH1 Hsub2 IH2
    |D A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2].
  all: subst D.
  - right. intro HB.
    exact (disjoint_axiom_not_botLike_right A0 B0 Hax HB).
  - left. exact HtopA.
  - right. intro HB.
    exact (agentH.botLike_not_topLike B0 HB nil HtopB).
  - right. intro HB. simpl in HB. inversion HB.
  - right. intro HB. simpl in HB. inversion HB.
  - right. intro HB. simpl in HB. inversion HB.
  - right. intro HB. inversion Hb.
  - right. intro HB. simpl in HB. inversion HB.
  - destruct (IH1 eq_refl) as [H1|Hn1].
    + destruct (IH2 eq_refl) as [H2|Hn2].
      * left. exact (spl_topLike_source A0 A1 A2 Hspl nil H1 H2).
      * right. exact Hn2.
    + right. exact Hn1.
  - destruct (IH1 eq_refl) as [H1|Hn1].
    + left. exact H1.
    + destruct (IH2 eq_refl) as [H2|Hn2].
      * left. exact H2.
      * right. intro HB.
        destruct (agentE.botLike_spl B0 B1 B2 HB Hspl) as [HB1|HB2].
        -- exact (Hn1 HB1).
        -- exact (Hn2 HB2).
Qed.

(* ================================================================== *)
(* topLike substitution without a global "C is top-like" hypothesis.  *)
(* The disjunction [topLike nil C \/ ~ botLike Dom] is exactly the     *)
(* information supplied by [disjoint nil C Dom] in the final use.      *)
(* ================================================================== *)

Lemma topLike_typsubst_mid_gen_nobot : forall (D0:tctx) A,
    topLike D0 A ->
    forall D1 X Dom D2, D0 = D1 ++ (X,Dom) :: D2 ->
      X \notin dom (D1 ++ D2) ->
      forall C,
        TCWell (tsubst_mid C X D1 D2) ->
        TWell (tsubst_mid C X D1 D2) C ->
        (topLike nil C \/ ~ botLike Dom) ->
        topLike (tsubst_mid C X D1 D2) (typsubst_typ C X A).
Proof.
  intros D0 A H.
  induction H as
    [D0 HTC
    |D0 A1 B1 HA IHA HB IHB
    |D0 A1 B1 HTA HB IHB
    |D0 l B1 HB IHB
    |L D0 A1 B1 Hbody IHBODY
    |D0 Y A1 HTC Hb Hbot];
    intros D1 X Dom D2 Heq Hfresh C HTCt HCT Htop0.
  - simpl. apply TL_top. exact HTCt.
  - simpl. apply TL_and.
    + apply (IHA D1 X Dom D2 Heq Hfresh C HTCt HCT Htop0).
    + apply (IHB D1 X Dom D2 Heq Hfresh C HTCt HCT Htop0).
  - simpl. apply TL_arrow.
    + apply (TWell_typsubst_mid_gen D0 X A1 HTA D1 Dom D2
                                     Heq Hfresh C HCT).
    + apply (IHB D1 X Dom D2 Heq Hfresh C HTCt HCT Htop0).
  - simpl. apply TL_rcd.
    apply (IHB D1 X Dom D2 Heq Hfresh C HTCt HCT Htop0).
  - (* TL_all *)
    assert (HTA1 : TWell D0 A1).
    { apply (agentA.topLike_all_dom D0 A1 B1).
      apply (TL_all L D0 A1 B1 Hbody). }
    assert (HlcC : lc_typ C)
      by (apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT).
    set (Dtg := tsubst_mid C X D1 D2).
    apply (TL_all (L \u ({{X}} \u dom Dtg)) Dtg
                  (typsubst_typ C X A1) (typsubst_typ C X B1)).
    intros Z HZ.
    assert (HZL : Z \notin L)
      by (apply (notin_union_1 Z L ({{X}} \u dom Dtg)); exact HZ).
    assert (HZrest : Z \notin ({{X}} \u dom Dtg))
      by (apply (notin_union_2 Z L ({{X}} \u dom Dtg)); exact HZ).
    assert (HZsing : Z \notin {{X}})
      by (apply (notin_union_1 Z {{X}} (dom Dtg)); exact HZrest).
    assert (HZDtg : Z \notin dom Dtg)
      by (apply (notin_union_2 Z {{X}} (dom Dtg)); exact HZrest).
    assert (HXZ : X <> Z) by (apply (notin_singleton_1 X Z); exact HZsing).
    assert (HZX' : Z <> X) by (intro HeqZX; apply HXZ; symmetry; exact HeqZX).
    assert (Hfresh' : X \notin dom (((Z,A1) :: D1) ++ D2)).
    { apply (notin_dom_mid_cons D1 D2 X Z A1 Hfresh HXZ). }
    assert (HTA1sub : TWell Dtg (typsubst_typ C X A1)).
    { unfold Dtg. apply (TWell_typsubst_mid_gen D0 X A1 HTA1
                          D1 Dom D2 Heq Hfresh C HCT). }
    assert (HuniqT : uniq Dtg) by (apply agentA.TCWell_uniq; exact HTCt).
    assert (HTCtg' : TCWell (cons (Z, typsubst_typ C X A1) Dtg)).
    { apply (TCW_cons Dtg Z (typsubst_typ C X A1) HTCt HTA1sub).
      apply (uniq_cons typ Z (typsubst_typ C X A1) Dtg HuniqT HZDtg). }
    assert (HCtg' : TWell (cons (Z, typsubst_typ C X A1) Dtg) C).
    { apply (TWell_cons_weaken Dtg C Z (typsubst_typ C X A1) HCT). }
    assert (HeqZ : cons (Z,A1) D0 =
                   ((Z,A1) :: D1) ++ (X,Dom) :: D2).
    { simpl. rewrite Heq. reflexivity. }
    pose proof (IHBODY Z HZL ((Z,A1) :: D1) X Dom D2 HeqZ Hfresh'
                  C HTCtg' HCtg' Htop0) as Hres.
    rewrite (typsubst_open_typ_neq C X HlcC Z B1 HZX') in Hres.
    change (topLike (cons (Z, typsubst_typ C X A1) Dtg)
                    (open_typ_wrt_typ (typsubst_typ C X B1) (t_tvar_f Z)))
      in Hres.
    exact Hres.
  - (* TL_var *)
    subst D0. simpl. destruct (eq_var Y X) as [HeqYX|Hne].
    + subst Y. simpl.
      destruct Htop0 as [Htopnil|Hnbot].
      * apply (agentD.topLike_weaken nil (tsubst_mid C X D1 D2) C
                                     Htopnil HTCt).
        intros W Bx Hmapb. inversion Hmapb.
      * exfalso.
        assert (Huniq0 : uniq (D1 ++ (X,Dom) :: D2)).
        { apply agentA.TCWell_uniq. exact HTC. }
        assert (HbDom : binds X Dom (D1 ++ (X,Dom) :: D2)).
        { apply in_app_iff. right. left. reflexivity. }
        assert (HeqA1 : A1 = Dom).
        { exact (binds_uniq_eq (D1 ++ (X,Dom) :: D2) X A1 Dom
                               Huniq0 Hb HbDom). }
        subst A1. exact (Hnbot Hbot).
    + destruct (binds_mid_far D1 D2 X Dom Y A1 Hne Hb) as [Hb1|Hb2].
      * apply (TL_var (tsubst_mid C X D1 D2) Y (typsubst_typ C X A1)).
        -- exact HTCt.
        -- apply binds_mid_left. exact Hb1.
        -- apply typsubst_botLike.
           ++ apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT.
           ++ exact Hbot.
      * apply (TL_var (tsubst_mid C X D1 D2) Y A1).
        -- exact HTCt.
        -- apply binds_mid_right. exact Hb2.
        -- exact Hbot.
Qed.

(* ================================================================== *)
(* algo_sub substitution without global topLike/self-subtyping of C.   *)
(* ================================================================== *)

Lemma algo_sub_typsubst_mid_gen_nobot : forall (D0:tctx) A B,
    algo_sub D0 A B ->
    forall D1 X Dom D2, D0 = D1 ++ (X,Dom) :: D2 ->
      X \notin dom (D1 ++ D2) ->
      forall C, TCWell D0 ->
        TCWell (tsubst_mid C X D1 D2) ->
        TWell (tsubst_mid C X D1 D2) C ->
        ord C ->
        (topLike nil C \/ ~ botLike Dom) ->
        algo_sub (tsubst_mid C X D1 D2)
                 (typsubst_typ C X A) (typsubst_typ C X B).
Proof.
  intros D0 A B Hsub.
  induction Hsub as
    [D0 Y HTC0 HTA
    |D0 HTC0
    |D0 A0 B0 HTA HordB HtopB
    |D0 A0 HTC0 HTA HordA
    |D0 A0 B0 C0 HTB HordC0 Hsub0 IH0
    |D0 A0 B0 C0 HTA HordC0 Hsub0 IH0
    |D0 A1 B1 A2 B2 HordB2 Hsub1 IH1 Hsub2 IH2
    |L D0 A1 A2 B1 B2 HordBody Hsub1 IH1 Hbody IHBODY
    |D0 l A0 B0 HordB0 Hsub0 IH0
    |D0 A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2];
    intros D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT HordC Htop0.
  - (* S_var *)
    simpl. destruct (eq_var Y X) as [HeqYX|Hne].
    + subst Y. simpl.
      exact (agentH.algo_sub_refl_TWell (tsubst_mid C X D1 D2) C HTCt HCT).
    + apply S_var.
      * exact HTCt.
      * rewrite <- (typsubst_tvar_neq C X Y Hne).
        apply (TWell_typsubst_mid_gen D0 X (t_tvar_f Y) HTA
                 D1 Dom D2 Heq Hfresh C HCT).
  - (* S_int *)
    simpl. apply S_int. exact HTCt.
  - (* S_top *)
    simpl. apply S_top.
    + apply (TWell_typsubst_mid_gen D0 X A0 HTA
               D1 Dom D2 Heq Hfresh C HCT).
    + apply (typsubst_ord C X).
      * apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT.
      * exact HordC.
      * exact HordB.
    + apply (topLike_typsubst_mid_gen_nobot D0 B0 HtopB
               D1 X Dom D2 Heq Hfresh C HTCt HCT Htop0).
  - (* S_bot *)
    simpl. apply S_bot.
    + exact HTCt.
    + apply (TWell_typsubst_mid_gen D0 X A0 HTA
               D1 Dom D2 Heq Hfresh C HCT).
    + apply (typsubst_ord C X).
      * apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT.
      * exact HordC.
      * exact HordA.
  - (* S_andl *)
    simpl. apply S_andl.
    + apply (TWell_typsubst_mid_gen D0 X B0 HTB
               D1 Dom D2 Heq Hfresh C HCT).
    + apply (typsubst_ord C X).
      * apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT.
      * exact HordC.
      * exact HordC0.
    + apply (IH0 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT
                HordC Htop0).
  - (* S_andr *)
    simpl. apply S_andr.
    + apply (TWell_typsubst_mid_gen D0 X A0 HTA
               D1 Dom D2 Heq Hfresh C HCT).
    + apply (typsubst_ord C X).
      * apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT.
      * exact HordC.
      * exact HordC0.
    + apply (IH0 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT
                HordC Htop0).
  - (* S_arrow *)
    simpl. apply S_arrow.
    + apply (typsubst_ord C X).
      * apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT.
      * exact HordC.
      * exact HordB2.
    + apply (IH1 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT
                HordC Htop0).
    + apply (IH2 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT
                HordC Htop0).
  - (* S_all *)
    assert (HTB1 : TWell D0 B1).
    { apply (algo_sub_TWell_source D0 B1 A1 HTCsrc Hsub1). }
    assert (HlcC : lc_typ C)
      by (apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT).
    set (Dtg := tsubst_mid C X D1 D2).
    apply (S_all (L \u ({{X}} \u (dom D0 \u dom Dtg))) Dtg
                 (typsubst_typ C X A1) (typsubst_typ C X A2)
                 (typsubst_typ C X B1) (typsubst_typ C X B2)).
    + (* ord of the codomain body *)
      intros Z HZ.
      assert (HZL : Z \notin L)
        by (apply (notin_union_1 Z L ({{X}} \u (dom D0 \u dom Dtg))); exact HZ).
      assert (HZrest : Z \notin ({{X}} \u (dom D0 \u dom Dtg)))
        by (apply (notin_union_2 Z L ({{X}} \u (dom D0 \u dom Dtg))); exact HZ).
      assert (HZsing : Z \notin {{X}})
        by (apply (notin_union_1 Z {{X}} (dom D0 \u dom Dtg)); exact HZrest).
      assert (HZdd : Z \notin (dom D0 \u dom Dtg))
        by (apply (notin_union_2 Z {{X}} (dom D0 \u dom Dtg)); exact HZrest).
      assert (HZD0 : Z \notin dom D0)
        by (apply (notin_union_1 Z (dom D0) (dom Dtg)); exact HZdd).
      assert (HZDtg : Z \notin dom Dtg)
        by (apply (notin_union_2 Z (dom D0) (dom Dtg)); exact HZdd).
      assert (HXZ : X <> Z) by (apply (notin_singleton_1 X Z); exact HZsing).
      assert (HZX' : Z <> X) by (intro HeqZX; apply HXZ; symmetry; exact HeqZX).
      rewrite <- (typsubst_open_typ_neq C X HlcC Z B2 HZX').
      apply (typsubst_ord C X HlcC HordC (open_typ_wrt_typ B2 (t_tvar_f Z))).
      apply (HordBody Z HZL).
    + apply (IH1 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT
                HordC Htop0).
    + intros Z HZ.
      assert (HZL : Z \notin L)
        by (apply (notin_union_1 Z L ({{X}} \u (dom D0 \u dom Dtg))); exact HZ).
      assert (HZrest : Z \notin ({{X}} \u (dom D0 \u dom Dtg)))
        by (apply (notin_union_2 Z L ({{X}} \u (dom D0 \u dom Dtg))); exact HZ).
      assert (HZsing : Z \notin {{X}})
        by (apply (notin_union_1 Z {{X}} (dom D0 \u dom Dtg)); exact HZrest).
      assert (HZdd : Z \notin (dom D0 \u dom Dtg))
        by (apply (notin_union_2 Z {{X}} (dom D0 \u dom Dtg)); exact HZrest).
      assert (HZD0 : Z \notin dom D0)
        by (apply (notin_union_1 Z (dom D0) (dom Dtg)); exact HZdd).
      assert (HZDtg : Z \notin dom Dtg)
        by (apply (notin_union_2 Z (dom D0) (dom Dtg)); exact HZdd).
      assert (HXZ : X <> Z) by (apply (notin_singleton_1 X Z); exact HZsing).
      assert (HZX' : Z <> X) by (intro HeqZX; apply HXZ; symmetry; exact HeqZX).
      assert (Hfresh' : X \notin dom (((Z,B1) :: D1) ++ D2)).
      { apply (notin_dom_mid_cons D1 D2 X Z B1 Hfresh HXZ). }
      assert (HTCsrc' : TCWell (cons (Z,B1) D0)).
      { apply (TCW_cons D0 Z B1 HTCsrc HTB1).
        apply (uniq_cons typ Z B1 D0 (TCWell_uniq D0 HTCsrc) HZD0). }
      assert (HTB1sub : TWell Dtg (typsubst_typ C X B1)).
      { unfold Dtg. apply (TWell_typsubst_mid_gen D0 X B1 HTB1
                           D1 Dom D2 Heq Hfresh C HCT). }
      assert (HTCtg' : TCWell (cons (Z, typsubst_typ C X B1) Dtg)).
      { apply (TCW_cons Dtg Z (typsubst_typ C X B1) HTCt HTB1sub).
        apply (uniq_cons typ Z (typsubst_typ C X B1) Dtg
                         (TCWell_uniq Dtg HTCt) HZDtg). }
      assert (HCtg' : TWell (cons (Z, typsubst_typ C X B1) Dtg) C).
      { apply (TWell_cons_weaken Dtg C Z (typsubst_typ C X B1) HCT). }
      assert (HeqZ : cons (Z,B1) D0 =
                     ((Z,B1) :: D1) ++ (X,Dom) :: D2).
      { simpl. rewrite Heq. reflexivity. }
      pose proof (IHBODY Z HZL ((Z,B1) :: D1) X Dom D2 HeqZ Hfresh'
                    C HTCsrc' HTCtg' HCtg' HordC Htop0) as Hres.
      rewrite (typsubst_open_typ_neq C X HlcC Z A2 HZX') in Hres.
      rewrite (typsubst_open_typ_neq C X HlcC Z B2 HZX') in Hres.
      change (algo_sub (cons (Z, typsubst_typ C X B1) Dtg)
                       (open_typ_wrt_typ (typsubst_typ C X A2) (t_tvar_f Z))
                       (open_typ_wrt_typ (typsubst_typ C X B2) (t_tvar_f Z)))
        in Hres.
      exact Hres.
  - (* S_rcd *)
    simpl. apply S_rcd.
    + apply (typsubst_ord C X).
      * apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT.
      * exact HordC.
      * exact HordB0.
    + apply (IH0 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT
                HordC Htop0).
  - (* S_and *)
    simpl.
    apply (S_and (tsubst_mid C X D1 D2)
                 (typsubst_typ C X A0) (typsubst_typ C X B0)
                 (typsubst_typ C X B1) (typsubst_typ C X B2)).
    + apply (typsubst_spl C X).
      * apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT.
      * exact Hspl.
    + apply (IH1 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT
                HordC Htop0).
    + apply (IH2 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT
                HordC Htop0).
Qed.

(* ================================================================== *)
(* Free type substitution (the substituted variable is not bound in   *)
(* the source context).  These are the standard substitution lemmas;  *)
(* unlike the "mid" versions, no binder is removed.                   *)
(* ================================================================== *)

Lemma TWell_typsubst_free_aux : forall (D:tctx) A,
    TWell D A ->
    forall C X, lc_typ C -> X \notin dom D ->
      TWell (subst_tctx C X D) (typsubst_typ C X A).
Proof.
  intros D A H.
  induction H as
    [D
    |D
    |D
    |D Z A0 Hb
    |D l A0 HA IHA
    |D A0 B0 HA IHA HB IHB
    |D A0 B0 HA IHA HB IHB
    |L D A0 B0 HA IHA Hbody IHBODY];
    intros C X HC HX.
  - simpl. apply TW_top.
  - simpl. apply TW_bot.
  - simpl. apply TW_int.
  - assert (HZX : Z <> X).
    { intro Heq. subst Z.
      exact (HX (binds_in_dom D X A0 Hb)). }
    rewrite (typsubst_tvar_neq C X Z HZX).
    apply (TW_var (subst_tctx C X D) Z (typsubst_typ C X A0)).
    apply (binds_subst_tctx C X D Z A0 Hb).
  - simpl. apply TW_rcd. apply (IHA C X HC HX).
  - simpl. apply TW_arrow.
    + apply (IHA C X HC HX).
    + apply (IHB C X HC HX).
  - simpl. apply TW_and.
    + apply (IHA C X HC HX).
    + apply (IHB C X HC HX).
  - apply (TW_all (L \u ({{X}} \u dom D))
                  (subst_tctx C X D)
                  (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + apply (IHA C X HC HX).
    + intros Z HZ.
      assert (HZL : Z \notin L)
        by (apply (notin_union_1 Z L ({{X}} \u dom D)); exact HZ).
      assert (HZrest : Z \notin ({{X}} \u dom D))
        by (apply (notin_union_2 Z L ({{X}} \u dom D)); exact HZ).
      assert (HZsing : Z \notin {{X}})
        by (apply (notin_union_1 Z {{X}} (dom D)); exact HZrest).
      assert (HZD : Z \notin dom D)
        by (apply (notin_union_2 Z {{X}} (dom D)); exact HZrest).
      assert (HXZ : X <> Z) by (apply (notin_singleton_1 X Z); exact HZsing).
      assert (HZX : Z <> X) by (intro Heq; apply HXZ; symmetry; exact Heq).
      assert (HXcons : X \notin dom (cons (Z,A0) D)).
      { apply (notin_dom_cons D Z A0 X HXZ HX). }
      pose proof (IHBODY Z HZL C X HC HXcons) as Hres.
      rewrite subst_tctx_cons in Hres.
      rewrite (typsubst_open_typ_neq C X HC Z B0 HZX) in Hres.
      exact Hres.
Qed.

Lemma TWell_typsubst_free : forall C X, lc_typ C ->
    forall (D:tctx) A, X \notin dom D ->
      TWell D A -> TWell (subst_tctx C X D) (typsubst_typ C X A).
Proof.
  intros C X HC D A HX H.
  exact (TWell_typsubst_free_aux D A H C X HC HX).
Qed.

Lemma TCWell_typsubst_free_aux : forall (D:tctx),
    TCWell D ->
    forall C X, lc_typ C -> X \notin dom D ->
      TCWell (subst_tctx C X D).
Proof.
  intros D HTC.
  induction HTC as [|D Z A HTC IH HT Hu];
    intros C X HC HX.
  - simpl. apply TCW_empty.
  - assert (HXD : X \notin dom D)
      by (apply (notin_dom_cons_inv D Z A X); exact HX).
    assert (HTs : TWell (subst_tctx C X D) (typsubst_typ C X A))
      by (apply (TWell_typsubst_free_aux D A HT C X HC HXD)).
    assert (HuD : uniq D) by (apply (uniq_cons_1 typ Z A D); exact Hu).
    assert (HZD : Z \notin dom D)
      by (apply (uniq_cons_2 typ Z A D); exact Hu).
    rewrite subst_tctx_cons.
    apply (TCW_cons (subst_tctx C X D) Z (typsubst_typ C X A)
                    (IH C X HC HXD)).
    + exact HTs.
    + apply uniq_cons.
      * apply (uniq_subst_tctx C X D HuD).
      * rewrite (dom_subst_tctx C X D). exact HZD.
Qed.

Lemma TCWell_typsubst_free : forall C X, lc_typ C ->
    forall (D:tctx), X \notin dom D ->
      TCWell D -> TCWell (subst_tctx C X D).
Proof.
  intros C X HC D HX H.
  exact (TCWell_typsubst_free_aux D H C X HC HX).
Qed.

Lemma CWell_typsubst_free_aux : forall (D:tctx) (G:ctx),
    CWell D G ->
    forall C X, lc_typ C -> X \notin dom D ->
      CWell (subst_tctx C X D) (subst_ctx C X G).
Proof.
  intros D G H.
  induction H as [D|D G x A Hc IH Ht];
    intros C X HC HX.
  - simpl. apply CW_empty.
  - simpl. apply CW_cons.
    + apply (IH C X HC HX).
    + apply (TWell_typsubst_free_aux D A Ht C X HC HX).
Qed.

Lemma CWell_typsubst_free : forall C X, lc_typ C ->
    forall (D:tctx) G, X \notin dom D ->
      CWell D G -> CWell (subst_tctx C X D) (subst_ctx C X G).
Proof.
  intros C X HC D G HX H.
  exact (CWell_typsubst_free_aux D G H C X HC HX).
Qed.

Lemma topLike_typsubst_free_aux : forall (D:tctx) A,
    topLike D A ->
    forall C X, lc_typ C -> X \notin dom D ->
      topLike (subst_tctx C X D) (typsubst_typ C X A).
Proof.
  intros D A H.
  induction H as
    [D HTC
    |D A1 B1 HA IHA HB IHB
    |D A1 B1 HTA HB IHB
    |D l B1 HB IHB
    |L D A1 B1 Hbody IHBODY
    |D Y A1 HTC Hb Hbot];
    intros C X HC HX.
  - simpl. apply TL_top.
    apply (TCWell_typsubst_free_aux D HTC C X HC HX).
  - simpl. apply TL_and.
    + apply (IHA C X HC HX).
    + apply (IHB C X HC HX).
  - simpl. apply TL_arrow.
    + apply (TWell_typsubst_free_aux D A1 HTA C X HC HX).
    + apply (IHB C X HC HX).
  - simpl. apply TL_rcd.
    apply (IHB C X HC HX).
  - apply (TL_all (L \u ({{X}} \u dom D))
                  (subst_tctx C X D)
                  (typsubst_typ C X A1) (typsubst_typ C X B1)).
    intros Z HZ.
    assert (HZL : Z \notin L)
      by (apply (notin_union_1 Z L ({{X}} \u dom D)); exact HZ).
    assert (HZrest : Z \notin ({{X}} \u dom D))
      by (apply (notin_union_2 Z L ({{X}} \u dom D)); exact HZ).
    assert (HZsing : Z \notin {{X}})
      by (apply (notin_union_1 Z {{X}} (dom D)); exact HZrest).
    assert (HZD : Z \notin dom D)
      by (apply (notin_union_2 Z {{X}} (dom D)); exact HZrest).
    assert (HXZ : X <> Z) by (apply (notin_singleton_1 X Z); exact HZsing).
    assert (HZX : Z <> X) by (intro Heq; apply HXZ; symmetry; exact Heq).
    assert (HXcons : X \notin dom (cons (Z,A1) D)).
    { apply (notin_dom_cons D Z A1 X HXZ HX). }
    pose proof (IHBODY Z HZL C X HC HXcons) as Hres.
    rewrite subst_tctx_cons in Hres.
    rewrite (typsubst_open_typ_neq C X HC Z B1 HZX) in Hres.
    exact Hres.
  - assert (HYX : Y <> X).
    { intro Heq. subst Y.
      exact (HX (binds_in_dom D X A1 Hb)). }
    rewrite (typsubst_tvar_neq C X Y HYX).
    apply (TL_var (subst_tctx C X D) Y (typsubst_typ C X A1)).
    + apply (TCWell_typsubst_free_aux D HTC C X HC HX).
    + apply (binds_subst_tctx C X D Y A1 Hb).
    + apply (typsubst_botLike C X HC A1 Hbot).
Qed.

Lemma topLike_typsubst_free : forall C X, lc_typ C ->
    forall (D:tctx) A, X \notin dom D ->
      topLike D A ->
      topLike (subst_tctx C X D) (typsubst_typ C X A).
Proof.
  intros C X HC D A HX H.
  exact (topLike_typsubst_free_aux D A H C X HC HX).
Qed.

Lemma algo_sub_typsubst_free_aux : forall (D:tctx) A B,
    algo_sub D A B ->
    forall C X, lc_typ C -> ord C -> X \notin dom D ->
      algo_sub (subst_tctx C X D)
               (typsubst_typ C X A) (typsubst_typ C X B).
Proof.
  intros D A B H.
  induction H as
    [D Y HTC HTA
    |D HTC
    |D A0 B0 HTA HordB HtopB
    |D A0 HTC HTA HordA
    |D A0 B0 C0 HTB HordC0 Hsub0 IH0
    |D A0 B0 C0 HTA HordC0 Hsub0 IH0
    |D A1 B1 A2 B2 HordB2 Hsub1 IH1 Hsub2 IH2
    |L D A1 A2 B1 B2 HordBody Hsub1 IH1 Hbody IHBODY
    |D l A0 B0 HordB0 Hsub0 IH0
    |D A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2];
    intros C X HC HordC HX.
  - simpl. destruct (eq_var Y X) as [HeqYX|Hne].
    + subst Y. exfalso.
      assert (Hin : X \in typefv_typ (t_tvar_f X))
        by (simpl; apply AtomSetImpl.singleton_2; reflexivity).
      exact ((TWell_notin_dom_typefv D (t_tvar_f X) HTA X HX) Hin).
    + apply (S_var (subst_tctx C X D) Y).
      * apply (TCWell_typsubst_free_aux D HTC C X HC HX).
      * rewrite <- (typsubst_tvar_neq C X Y Hne).
        apply (TWell_typsubst_free_aux D (t_tvar_f Y) HTA C X HC HX).
  - simpl. apply S_int.
    apply (TCWell_typsubst_free_aux D HTC C X HC HX).
  - simpl. apply S_top.
    + apply (TWell_typsubst_free_aux D A0 HTA C X HC HX).
    + apply (typsubst_ord C X HC HordC B0 HordB).
    + apply (topLike_typsubst_free_aux D B0 HtopB C X HC HX).
  - simpl. apply S_bot.
    + apply (TCWell_typsubst_free_aux D HTC C X HC HX).
    + apply (TWell_typsubst_free_aux D A0 HTA C X HC HX).
    + apply (typsubst_ord C X HC HordC A0 HordA).
  - simpl. apply S_andl.
    + apply (TWell_typsubst_free_aux D B0 HTB C X HC HX).
    + apply (typsubst_ord C X HC HordC C0 HordC0).
    + apply (IH0 C X HC HordC HX).
  - simpl. apply S_andr.
    + apply (TWell_typsubst_free_aux D A0 HTA C X HC HX).
    + apply (typsubst_ord C X HC HordC C0 HordC0).
    + apply (IH0 C X HC HordC HX).
  - simpl. apply S_arrow.
    + apply (typsubst_ord C X HC HordC B2 HordB2).
    + apply (IH1 C X HC HordC HX).
    + apply (IH2 C X HC HordC HX).
  - apply (S_all (L \u ({{X}} \u dom D))
                 (subst_tctx C X D)
                 (typsubst_typ C X A1) (typsubst_typ C X A2)
                 (typsubst_typ C X B1) (typsubst_typ C X B2)).
    + intros Z HZ.
      assert (HZL : Z \notin L)
        by (apply (notin_union_1 Z L ({{X}} \u dom D)); exact HZ).
      assert (HZrest : Z \notin ({{X}} \u dom D))
        by (apply (notin_union_2 Z L ({{X}} \u dom D)); exact HZ).
      assert (HZsing : Z \notin {{X}})
        by (apply (notin_union_1 Z {{X}} (dom D)); exact HZrest).
      assert (HZD : Z \notin dom D)
        by (apply (notin_union_2 Z {{X}} (dom D)); exact HZrest).
      assert (HXZ : X <> Z) by (apply (notin_singleton_1 X Z); exact HZsing).
      assert (HZX : Z <> X) by (intro Heq; apply HXZ; symmetry; exact Heq).
      assert (HordZ : ord (typsubst_typ C X
                            (open_typ_wrt_typ B2 (t_tvar_f Z))))
        by (apply (typsubst_ord C X HC HordC
                     (open_typ_wrt_typ B2 (t_tvar_f Z))); apply HordBody; exact HZL).
      rewrite (typsubst_open_typ_neq C X HC Z B2 HZX) in HordZ.
      exact HordZ.
    + apply (IH1 C X HC HordC HX).
    + intros Z HZ.
      assert (HZL : Z \notin L)
        by (apply (notin_union_1 Z L ({{X}} \u dom D)); exact HZ).
      assert (HZrest : Z \notin ({{X}} \u dom D))
        by (apply (notin_union_2 Z L ({{X}} \u dom D)); exact HZ).
      assert (HZsing : Z \notin {{X}})
        by (apply (notin_union_1 Z {{X}} (dom D)); exact HZrest).
      assert (HZD : Z \notin dom D)
        by (apply (notin_union_2 Z {{X}} (dom D)); exact HZrest).
      assert (HXZ : X <> Z) by (apply (notin_singleton_1 X Z); exact HZsing).
      assert (HZX : Z <> X) by (intro Heq; apply HXZ; symmetry; exact Heq).
      assert (HXcons : X \notin dom (cons (Z,B1) D)).
      { apply (notin_dom_cons D Z B1 X HXZ HX). }
      pose proof (IHBODY Z HZL C X HC HordC HXcons) as Hres.
      rewrite subst_tctx_cons in Hres.
      rewrite (typsubst_open_typ_neq C X HC Z A2 HZX) in Hres.
      rewrite (typsubst_open_typ_neq C X HC Z B2 HZX) in Hres.
      exact Hres.
  - simpl. apply S_rcd.
    + apply (typsubst_ord C X HC HordC B0 HordB0).
    + apply (IH0 C X HC HordC HX).
  - simpl. apply (S_and (subst_tctx C X D)
                        (typsubst_typ C X A0) (typsubst_typ C X B0)
                        (typsubst_typ C X B1) (typsubst_typ C X B2)).
    + apply (typsubst_spl C X HC B0 B1 B2 Hspl).
    + apply (IH1 C X HC HordC HX).
    + apply (IH2 C X HC HordC HX).
Qed.

Lemma algo_sub_typsubst_free : forall C X, lc_typ C -> ord C ->
    forall (D:tctx) A B, X \notin dom D ->
      algo_sub D A B ->
      algo_sub (subst_tctx C X D)
               (typsubst_typ C X A) (typsubst_typ C X B).
Proof.
  intros C X HC HordC D A B HX H.
  exact (algo_sub_typsubst_free_aux D A B H C X HC HordC HX).
Qed.

Lemma disjoint_typsubst_free_aux : forall (D:tctx) A B,
    disjoint D A B ->
    forall C X, lc_typ C -> ord C -> X \notin dom D ->
      disjoint (subst_tctx C X D)
               (typsubst_typ C X A) (typsubst_typ C X B).
Proof.
  intros D A B H.
  induction H as
    [D A0 B0 HTC0 HTA HTB Hax
    |D A0 B0 HTB HtopA
    |D A0 B0 HTA HtopB
    |D A1 A2 B1 B2 HT1 HT2 Hsub IHsub
    |D l A0 B0 Hsub IHsub
    |L D A1 B1 A2 B2 HT1 HT2 Hbody IHBODY
    |D Y B0 A0 Hb Hsub
    |D B0 Y A0 Hb Hsub
    |D A0 B0 A1 A2 Hspl Hsub1 IH1 Hsub2 IH2
    |D A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2];
    intros C X HC HordC HX.
  - simpl. apply D_ax.
    + apply (TCWell_typsubst_free_aux D HTC0 C X HC HX).
    + apply (TWell_typsubst_free_aux D A0 HTA C X HC HX).
    + apply (TWell_typsubst_free_aux D B0 HTB C X HC HX).
    + apply (typsubst_disjoint_axiom C X A0 B0 HC Hax).
  - simpl. apply D_topl.
    + apply (TWell_typsubst_free_aux D B0 HTB C X HC HX).
    + apply (topLike_typsubst_free_aux D A0 HtopA C X HC HX).
  - simpl. apply D_topr.
    + apply (TWell_typsubst_free_aux D A0 HTA C X HC HX).
    + apply (topLike_typsubst_free_aux D B0 HtopB C X HC HX).
  - simpl. apply D_arrow.
    + apply (TWell_typsubst_free_aux D (t_arrow A1 A2) HT1 C X HC HX).
    + apply (TWell_typsubst_free_aux D (t_arrow B1 B2) HT2 C X HC HX).
    + apply (IHsub C X HC HordC HX).
  - simpl. apply D_rcdEq.
    apply (IHsub C X HC HordC HX).
  - apply (D_all (L \u ({{X}} \u dom D))
                 (subst_tctx C X D)
                 (typsubst_typ C X A1) (typsubst_typ C X B1)
                 (typsubst_typ C X A2) (typsubst_typ C X B2)).
    + apply (TWell_typsubst_free_aux D A1 HT1 C X HC HX).
    + apply (TWell_typsubst_free_aux D A2 HT2 C X HC HX).
    + intros Z HZ.
      assert (HZL : Z \notin L)
        by (apply (notin_union_1 Z L ({{X}} \u dom D)); exact HZ).
      assert (HZrest : Z \notin ({{X}} \u dom D))
        by (apply (notin_union_2 Z L ({{X}} \u dom D)); exact HZ).
      assert (HZsing : Z \notin {{X}})
        by (apply (notin_union_1 Z {{X}} (dom D)); exact HZrest).
      assert (HZD : Z \notin dom D)
        by (apply (notin_union_2 Z {{X}} (dom D)); exact HZrest).
      assert (HXZ : X <> Z) by (apply (notin_singleton_1 X Z); exact HZsing).
      assert (HZX : Z <> X) by (intro Heq; apply HXZ; symmetry; exact Heq).
      assert (HXcons : X \notin dom (cons (Z,t_and A1 A2) D)).
      { apply (notin_dom_cons D Z (t_and A1 A2) X HXZ HX). }
      pose proof (IHBODY Z HZL C X HC HordC HXcons) as Hres.
      rewrite subst_tctx_cons in Hres.
      rewrite (typsubst_open_typ_neq C X HC Z B1 HZX) in Hres.
      rewrite (typsubst_open_typ_neq C X HC Z B2 HZX) in Hres.
      exact Hres.
  - simpl. destruct (eq_var Y X) as [HeqYX|Hne].
    + subst Y. exfalso.
      exact (HX (binds_in_dom D X A0 Hb)).
    + apply (D_varl (subst_tctx C X D) Y
                    (typsubst_typ C X B0) (typsubst_typ C X A0)).
      * apply (binds_subst_tctx C X D Y A0 Hb).
      * apply (algo_sub_typsubst_free_aux D A0 B0 Hsub C X HC HordC HX).
  - simpl. destruct (eq_var Y X) as [HeqYX|Hne].
    + subst Y. exfalso.
      exact (HX (binds_in_dom D X A0 Hb)).
    + apply (D_varr (subst_tctx C X D) (typsubst_typ C X B0) Y
                    (typsubst_typ C X A0)).
      * apply (binds_subst_tctx C X D Y A0 Hb).
      * apply (algo_sub_typsubst_free_aux D A0 B0 Hsub C X HC HordC HX).
  - simpl. apply (D_andl (subst_tctx C X D)
                         (typsubst_typ C X A0) (typsubst_typ C X B0)
                         (typsubst_typ C X A1) (typsubst_typ C X A2)).
    + apply (typsubst_spl C X HC A0 A1 A2 Hspl).
    + apply (IH1 C X HC HordC HX).
    + apply (IH2 C X HC HordC HX).
  - simpl. apply (D_andr (subst_tctx C X D)
                         (typsubst_typ C X A0) (typsubst_typ C X B0)
                         (typsubst_typ C X B1) (typsubst_typ C X B2)).
    + apply (typsubst_spl C X HC B0 B1 B2 Hspl).
    + apply (IH1 C X HC HordC HX).
    + apply (IH2 C X HC HordC HX).
Qed.

Lemma disjoint_typsubst_free : forall C X, lc_typ C -> ord C ->
    forall (D:tctx) A B, X \notin dom D ->
      disjoint D A B ->
      disjoint (subst_tctx C X D)
               (typsubst_typ C X A) (typsubst_typ C X B).
Proof.
  intros C X HC HordC D A B HX H.
  exact (disjoint_typsubst_free_aux D A B H C X HC HordC HX).
Qed.

(* ================================================================== *)
(* Identity of type substitution on locally closed (X-free) terms.    *)
(* ================================================================== *)

Lemma typsubst_exp_id_notin : forall C X e,
    X \notin typefv_exp e -> typsubst_exp C X e = e.
Proof.
  intros C X e. induction e as
    [m|x| |i|A e IHe|A e IHe|e1 IH1 e2 IH2|e1 IH1 e2 IH2
    |e IH A|l e IHe|e IHe l|e IHe|e IHe A];
    intros H; simpl in *.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite (typsubst_typ_id_notin C X A); [| apply (proj1 (notin_union X _ _ H))].
    rewrite (IHe (proj2 (notin_union X _ _ H))). reflexivity.
  - rewrite (typsubst_typ_id_notin C X A); [| apply (proj1 (notin_union X _ _ H))].
    rewrite (IHe (proj2 (notin_union X _ _ H))). reflexivity.
  - rewrite (IH1 (proj1 (notin_union X _ _ H))).
    rewrite (IH2 (proj2 (notin_union X _ _ H))). reflexivity.
  - rewrite (IH1 (proj1 (notin_union X _ _ H))).
    rewrite (IH2 (proj2 (notin_union X _ _ H))). reflexivity.
  - rewrite (IH (proj1 (notin_union X _ _ H))).
    rewrite (typsubst_typ_id_notin C X A); [reflexivity| apply (proj2 (notin_union X _ _ H))].
  - rewrite (IHe H). reflexivity.
  - rewrite (IHe H). reflexivity.
  - rewrite (IHe H). reflexivity.
  - rewrite (IHe (proj1 (notin_union X _ _ H))).
    rewrite (typsubst_typ_id_notin C X A); [reflexivity| apply (proj2 (notin_union X _ _ H))].
Qed.

Lemma notin_dom_nil : forall X:typevar, X \notin dom (nil:tctx).
Proof.
  intros X H. simpl in H.
  apply AtomSetProperties.Dec.F.empty_iff in H. exact H.
Qed.

Lemma TWell_nil_weaken : forall (D:tctx) C,
    TWell nil C -> TWell D C.
Proof.
  intros D C H.
  apply (TWell_weaken nil D C H).
  intros W B Hb. inversion Hb.
Qed.

(* ================================================================== *)
(* Consistency, prevalues and pType are preserved by type substitution *)
(* ================================================================== *)

Lemma typsubst_pType : forall C X, lc_typ C ->
    forall u A, pType u A ->
      pType (typsubst_exp C X u) (typsubst_typ C X A).
Proof.
  intros C X HC u A H.
  induction H as
    [|i|e A Hlce HlcA|u1 u2 A B H1 IH1 H2 IH2].
  - simpl. apply PT_top.
  - simpl. apply PT_int.
  - simpl. apply PT_anno.
    + apply lc_exp_typsubst; assumption.
    + apply lc_typ_typsubst; assumption.
  - simpl. apply PT_merge; assumption.
Qed.

Lemma typsubst_prevalue : forall C X, lc_typ C ->
    forall u, prevalue u -> prevalue (typsubst_exp C X u).
Proof.
  intros C X HC u H.
  induction H as [i| |e A Hlce HlcA|u1 u2 H1 IH1 H2 IH2].
  - simpl. apply PV_int.
  - simpl. apply PV_top.
  - simpl. apply PV_anno.
    + apply lc_exp_typsubst; assumption.
    + apply lc_typ_typsubst; assumption.
  - simpl. apply PV_merge; assumption.
Qed.

Lemma typsubst_consistent : forall C X, lc_typ C -> ord C ->
    forall u v, consistent u v ->
      consistent (typsubst_exp C X u) (typsubst_exp C X v).
Proof.
  intros C X HC HordC u v H.
  induction H as
    [i
    |e A B HlcA Hlce HlcB
    |u1 u2 A B Hp1 Hp2 Hdisj Hpv1 Hpv2
    |u1 u2 u H1 IH1 H2 IH2
    |u u1 u2 H1 IH1 H2 IH2].
  - simpl. apply C_lit.
  - simpl. apply C_anno.
    + apply lc_typ_typsubst; assumption.
    + apply lc_exp_typsubst; assumption.
    + apply lc_typ_typsubst; assumption.
  - simpl. apply (C_disjoint (typsubst_exp C X u1) (typsubst_exp C X u2)
                              (typsubst_typ C X A) (typsubst_typ C X B)).
    + apply (typsubst_pType C X HC u1 A Hp1).
    + apply (typsubst_pType C X HC u2 B Hp2).
    + apply (disjoint_typsubst_free C X HC HordC nil A B
               (notin_dom_nil X) Hdisj).
    + apply (typsubst_prevalue C X HC u1 Hpv1).
    + apply (typsubst_prevalue C X HC u2 Hpv2).
  - simpl. apply C_mergel; assumption.
  - simpl. apply C_merger; assumption.
Qed.

(* ================================================================== *)
(* Free type substitution for typing.  The source context does not     *)
(* bind X, so no binder is removed.                                    *)
(* ================================================================== *)

Lemma typing_typsubst_free : forall C X, lc_typ C -> ord C ->
    forall (D:tctx) (G:ctx) e d A, Typing D G e d A ->
      X \notin dom D ->
      Typing (subst_tctx C X D) (subst_ctx C X G)
             (typsubst_exp C X e) d (typsubst_typ C X A).
Proof.
  intros C X HC HordC D G e d A Hty.
  induction Hty as
    [D0 G0 HTC0 HCW0 Hu0
    |D0 G0 i HTC0 HCW0 Hu0
    |D0 G0 x A0 HTC0 HCW0 Hb Hu0
    |L D0 G0 A0 e B1 B2 Hsub Hbody IHBODY
    |D0 G0 e1 e2 C0 A0 B0 Ht1 IH1 Hdist Ht2 IH2
    |L D0 G0 e A0 B0 HCW0 Hbody IHBODY
    |D0 G0 e A0 C2 B0 C1 Ht IH Hdist Hdisj
    |D0 G0 e l C0 A0 Ht IH Hdist
    |D0 G0 l e A0 Ht IH
    |D0 G0 e1 e2 A0 B0 Ht1 IH1 Ht2 IH2 Hdisj
    |D0 G0 e A0 B0 Ht1 IH1 Ht2 IH2
    |D0 G0 e A0 Ht IH
    |L D0 G0 A0 e Hbody IHBODY
    |D0 G0 u1 u2 A0 B0 HTC0 HCW0 Hu0 Ht1 IH1 Ht2 IH2 Hcons
    |D0 G0 e B0 A0 Ht IH Hsub];
    intros HX.
  - simpl. apply Typ_top.
    + apply (TCWell_typsubst_free_aux D0 HTC0 C X HC HX).
    + apply (CWell_typsubst_free_aux D0 G0 HCW0 C X HC HX).
    + apply (uniq_subst_ctx C X G0 Hu0).
  - simpl. apply Typ_lit.
    + apply (TCWell_typsubst_free_aux D0 HTC0 C X HC HX).
    + apply (CWell_typsubst_free_aux D0 G0 HCW0 C X HC HX).
    + apply (uniq_subst_ctx C X G0 Hu0).
  - simpl. apply (Typ_var (subst_tctx C X D0) (subst_ctx C X G0)
                          x (typsubst_typ C X A0)).
    + apply (TCWell_typsubst_free_aux D0 HTC0 C X HC HX).
    + apply (CWell_typsubst_free_aux D0 G0 HCW0 C X HC HX).
    + apply (binds_subst_ctx C X G0 x A0 Hb).
    + apply (uniq_subst_ctx C X G0 Hu0).
  - simpl. apply (Typ_abs L (subst_tctx C X D0) (subst_ctx C X G0)
                         (typsubst_typ C X A0) (typsubst_exp C X e)
                         (typsubst_typ C X B1) (typsubst_typ C X B2)).
    + apply (algo_sub_typsubst_free C X HC HordC D0 B1 A0 HX Hsub).
    + intros x Hx.
      pose proof (IHBODY x Hx HX) as Hres.
      rewrite (typsubst_open_exp C X e (e_var_f x)) in Hres.
      simpl in Hres.
      exact Hres.
  - simpl. apply (Typ_app (subst_tctx C X D0) (subst_ctx C X G0)
                          (typsubst_exp C X e1) (typsubst_exp C X e2)
                          (typsubst_typ C X C0) (typsubst_typ C X A0)
                          (typsubst_typ C X B0)).
    + apply (IH1 HX).
    + apply (typsubst_appDist C X HC A0 (t_arrow B0 C0) Hdist).
    + apply (IH2 HX).
  - simpl. apply (Typ_tabs (L \u ({{X}} \u dom D0))
                           (subst_tctx C X D0) (subst_ctx C X G0)
                           (typsubst_exp C X e)
                           (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + apply (CWell_typsubst_free_aux D0 G0 HCW0 C X HC HX).
    + intros Y HY.
      assert (HYL : Y \notin L)
        by (apply (notin_union_1 Y L ({{X}} \u dom D0)); exact HY).
      assert (HYrest : Y \notin ({{X}} \u dom D0))
        by (apply (notin_union_2 Y L ({{X}} \u dom D0)); exact HY).
      assert (HYsing : Y \notin {{X}})
        by (apply (notin_union_1 Y {{X}} (dom D0)); exact HYrest).
      assert (HYD : Y \notin dom D0)
        by (apply (notin_union_2 Y {{X}} (dom D0)); exact HYrest).
      assert (HXY : X <> Y) by (apply (notin_singleton_1 X Y); exact HYsing).
      assert (HYX : Y <> X) by (intro Heq; apply HXY; symmetry; exact Heq).
      assert (HXcons : X \notin dom (cons (Y,A0) D0)).
      { apply (notin_dom_cons D0 Y A0 X HXY HX). }
      pose proof (IHBODY Y HYL HXcons) as Hres.
      rewrite subst_tctx_cons in Hres.
      rewrite (typsubst_open_exp_typ_neq C X HC Y e HYX) in Hres.
      rewrite (typsubst_open_typ_neq C X HC Y B0 HYX) in Hres.
      exact Hres.
  - simpl. rewrite (typsubst_open_typ_any C X HC C2 A0).
    apply (Typ_tapp (subst_tctx C X D0) (subst_ctx C X G0)
                    (typsubst_exp C X e) (typsubst_typ C X A0)
                    (typsubst_typ C X C2) (typsubst_typ C X B0)
                    (typsubst_typ C X C1)).
    + apply (IH HX).
    + apply (typsubst_appDist C X HC B0 (t_forall C1 C2) Hdist).
    + apply (disjoint_typsubst_free C X HC HordC D0 A0 C1 HX Hdisj).
  - simpl. apply (Typ_proj (subst_tctx C X D0) (subst_ctx C X G0)
                           (typsubst_exp C X e) l
                           (typsubst_typ C X C0) (typsubst_typ C X A0)).
    + apply (IH HX).
    + apply (typsubst_appDist C X HC A0 (t_rcd l C0) Hdist).
  - simpl. apply (Typ_rcd (subst_tctx C X D0) (subst_ctx C X G0) l
                          (typsubst_exp C X e) (typsubst_typ C X A0)).
    apply (IH HX).
  - simpl. apply (Typ_merge (subst_tctx C X D0) (subst_ctx C X G0)
                            (typsubst_exp C X e1) (typsubst_exp C X e2)
                            (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + apply (IH1 HX).
    + apply (IH2 HX).
    + apply (disjoint_typsubst_free C X HC HordC D0 A0 B0 HX Hdisj).
  - simpl. apply (Typ_inter (subst_tctx C X D0) (subst_ctx C X G0)
                            (typsubst_exp C X e)
                            (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + apply (IH1 HX).
    + apply (IH2 HX).
  - simpl. apply (Typ_anno (subst_tctx C X D0) (subst_ctx C X G0)
                           (typsubst_exp C X e) (typsubst_typ C X A0)).
    apply (IH HX).
  - simpl. apply (Typ_fix L (subst_tctx C X D0) (subst_ctx C X G0)
                         (typsubst_typ C X A0) (typsubst_exp C X e)).
    intros x Hx.
    pose proof (IHBODY x Hx HX) as Hres.
    rewrite (typsubst_open_exp C X e (e_var_f x)) in Hres.
    simpl in Hres.
    exact Hres.
  - simpl. apply (Typ_mergev (subst_tctx C X D0) (subst_ctx C X G0)
                             (typsubst_exp C X u1) (typsubst_exp C X u2)
                             (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + apply (TCWell_typsubst_free_aux D0 HTC0 C X HC HX).
    + apply (CWell_typsubst_free_aux D0 G0 HCW0 C X HC HX).
    + apply (uniq_subst_ctx C X G0 Hu0).
    + apply (IH1 (notin_dom_nil X)).
    + apply (IH2 (notin_dom_nil X)).
    + apply (typsubst_consistent C X HC HordC u1 u2 Hcons).
  - simpl. apply (Typ_sub (subst_tctx C X D0) (subst_ctx C X G0)
                          (typsubst_exp C X e)
                          (typsubst_typ C X B0) (typsubst_typ C X A0)).
    + apply (IH HX).
    + apply (algo_sub_typsubst_free C X HC HordC D0 A0 B0 HX Hsub).
Qed.

(* ================================================================== *)
(* Context-splitting type substitution for typing.                     *)
(*                                                                     *)
(* The source context is [D1 ++ [(X,T0)]]: the [X] binder is removed   *)
(* and the [D1] part is substituted.  The family [Hdisj] records the    *)
(* preservation of disjointness.  Such an hypothesis is unavoidable:    *)
(* disjointness is *not* preserved by arbitrary type substitution       *)
(* (see the warning at the end of agentL.v).                           *)
(*                                                                     *)
(* [ord C] is used only by the algorithmic-subtyping translation.       *)
(* ================================================================== *)

Lemma tsubst_mid_nil : forall C X (D:tctx),
    tsubst_mid C X D nil = subst_tctx C X D.
Proof. intros. unfold tsubst_mid. apply app_nil_r. Qed.

Lemma typing_typsubst_mid_gen : forall C X T0,
    lc_typ C -> ord C -> TWell nil C ->
    (topLike nil C \/ ~ botLike T0) ->
    (forall (D1:tctx) P Q,
       X \notin dom D1 ->
       disjoint (D1 ++ [(X,T0)]) P Q ->
       disjoint (tsubst_mid C X D1 nil)
                (typsubst_typ C X P) (typsubst_typ C X Q)) ->
    forall (D0:tctx) (G:ctx) e d B, Typing D0 G e d B ->
      forall D1, D0 = D1 ++ [(X,T0)] -> X \notin dom D1 ->
        Typing (tsubst_mid C X D1 nil) (subst_ctx C X G)
               (typsubst_exp C X e) d (typsubst_typ C X B).
Proof.
  intros C X T0 HlcC HordC HCT Htop0 Hdisj D0 G e d B Hty.
  induction Hty as
    [D0 G0 HTC0 HCW0 Hu0
    |D0 G0 i HTC0 HCW0 Hu0
    |D0 G0 x A0 HTC0 HCW0 Hb Hu0
    |L D0 G0 A0 e B1 B2 Hsub Hbody IHBODY
    |D0 G0 e1 e2 C0 A0 B0 Ht1 IH1 HDt Ht2 IH2
    |L D0 G0 e A0 B0 HCW0 Hbody IHBODY
    |D0 G0 e A0 C2 B0 C1 Ht IH HDt HDj
    |D0 G0 e l C0 A0 Ht IH HDt
    |D0 G0 l e A0 Ht IH
    |D0 G0 e1 e2 A0 B0 Ht1 IH1 Ht2 IH2 HDj
    |D0 G0 e A0 B0 Ht1 IH1 Ht2 IH2
    |D0 G0 e A0 Ht IH
    |L D0 G0 A0 e Hbody IHBODY
    |D0 G0 u1 u2 A0 B0 HTC0 HCW0 Hu0 Ht1 IH1 Ht2 IH2 Hcons
    |D0 G0 e B0 A0 Ht IH Hsub];
    intros D1 Heq Hfresh;
    assert (Hfresh_nil : X \notin dom (D1 ++ nil))
      by (rewrite app_nil_r; exact Hfresh).
  - (* Typ_top *)
    simpl. apply (Typ_top (tsubst_mid C X D1 nil) (subst_ctx C X G0)).
    + assert (HTCsplit : TCWell (D1 ++ [(X,T0)])).
      { rewrite <- Heq. exact HTC0. }
      try rewrite tsubst_mid_nil.
      try rewrite app_nil_r.
      exact (typsubst_TCWell_drop D1 X T0 Hfresh HTCsplit C HCT).
    + apply (CWell_typsubst_mid_gen D0 G0 HCW0 D1 X T0 nil Heq Hfresh_nil C
                (TWell_nil_weaken (tsubst_mid C X D1 nil) C HCT)).
    + apply (uniq_subst_ctx C X G0 Hu0).
  - (* Typ_lit *)
    simpl. apply (Typ_lit (tsubst_mid C X D1 nil) (subst_ctx C X G0) i).
    + assert (HTCsplit : TCWell (D1 ++ [(X,T0)])).
      { rewrite <- Heq. exact HTC0. }
      try rewrite tsubst_mid_nil.
      try rewrite app_nil_r.
      exact (typsubst_TCWell_drop D1 X T0 Hfresh HTCsplit C HCT).
    + apply (CWell_typsubst_mid_gen D0 G0 HCW0 D1 X T0 nil Heq Hfresh_nil C
                (TWell_nil_weaken (tsubst_mid C X D1 nil) C HCT)).
    + apply (uniq_subst_ctx C X G0 Hu0).
  - (* Typ_var *)
    simpl. apply (Typ_var (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                          x (typsubst_typ C X A0)).
    + assert (HTCsplit : TCWell (D1 ++ [(X,T0)])).
      { rewrite <- Heq. exact HTC0. }
      try rewrite tsubst_mid_nil.
      try rewrite app_nil_r.
      exact (typsubst_TCWell_drop D1 X T0 Hfresh HTCsplit C HCT).
    + apply (CWell_typsubst_mid_gen D0 G0 HCW0 D1 X T0 nil Heq Hfresh_nil C
                (TWell_nil_weaken (tsubst_mid C X D1 nil) C HCT)).
    + apply (binds_subst_ctx C X G0 x A0 Hb).
    + apply (uniq_subst_ctx C X G0 Hu0).
  - (* Typ_abs *)
    simpl.
    destruct (atom_fresh L) as [x Hx].
    assert (HTCsrc : TCWell D0).
    { exact (proj1 (typing_env_wf D0 (cons (x,A0) G0)
                      (open_exp_wrt_exp e (e_var_f x)) Chk B2 (Hbody x Hx))). }
    assert (HTCsplit : TCWell (D1 ++ [(X,T0)])).
    { rewrite <- Heq. exact HTCsrc. }
    assert (HTCtg : TCWell (tsubst_mid C X D1 nil)).
    { rewrite tsubst_mid_nil.
      exact (typsubst_TCWell_drop D1 X T0 Hfresh HTCsplit C HCT). }
    apply (Typ_abs L (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                   (typsubst_typ C X A0) (typsubst_exp C X e)
                   (typsubst_typ C X B1) (typsubst_typ C X B2)).
    + apply (algo_sub_typsubst_mid_gen_nobot D0 B1 A0 Hsub
               D1 X T0 nil Heq Hfresh_nil C HTCsrc HTCtg
               (TWell_nil_weaken (tsubst_mid C X D1 nil) C HCT)
               HordC Htop0).
    + intros x' Hx'.
      pose proof (IHBODY x' Hx' D1 Heq Hfresh) as Hres.
      rewrite (typsubst_open_exp C X e (e_var_f x')) in Hres.
      simpl in Hres.
      exact Hres.
  - (* Typ_app *)
    simpl. apply (Typ_app (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                          (typsubst_exp C X e1) (typsubst_exp C X e2)
                          (typsubst_typ C X C0) (typsubst_typ C X A0)
                          (typsubst_typ C X B0)).
    + apply (IH1 D1 Heq Hfresh).
    + apply (typsubst_appDist C X HlcC A0 (t_arrow B0 C0) HDt).
    + apply (IH2 D1 Heq Hfresh).
  - (* Typ_tabs *)
    simpl. apply (Typ_tabs (L \u ({{X}} \u dom D1))
                           (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                           (typsubst_exp C X e)
                           (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + apply (CWell_typsubst_mid_gen D0 G0 HCW0 D1 X T0 nil Heq Hfresh_nil C
                (TWell_nil_weaken (tsubst_mid C X D1 nil) C HCT)).
    + intros Y HY.
      assert (HYL : Y \notin L)
        by (apply (notin_union_1 Y L ({{X}} \u dom D1)); exact HY).
      assert (HYrest : Y \notin ({{X}} \u dom D1))
        by (apply (notin_union_2 Y L ({{X}} \u dom D1)); exact HY).
      assert (HYsing : Y \notin {{X}})
        by (apply (notin_union_1 Y {{X}} (dom D1)); exact HYrest).
      assert (HYD1 : Y \notin dom D1)
        by (apply (notin_union_2 Y {{X}} (dom D1)); exact HYrest).
      assert (HXY : X <> Y) by (apply (notin_singleton_1 X Y); exact HYsing).
      assert (HYX : Y <> X) by (intro HeqYX; apply HXY; symmetry; exact HeqYX).
      assert (Hfresh' : X \notin dom ((Y,A0) :: D1)).
      { apply (notin_dom_cons D1 Y A0 X HXY Hfresh). }
      assert (Heq' : cons (Y,A0) D0 = ((Y,A0) :: D1) ++ [(X,T0)]).
      { simpl. rewrite Heq. reflexivity. }
      pose proof (IHBODY Y HYL ((Y,A0) :: D1) Heq' Hfresh') as Hres.
      rewrite (typsubst_open_exp_typ_neq C X HlcC Y e HYX) in Hres.
      rewrite (typsubst_open_typ_neq C X HlcC Y B0 HYX) in Hres.
      exact Hres.
  - (* Typ_tapp *)
    simpl. rewrite (typsubst_open_typ_any C X HlcC C2 A0).
    apply (Typ_tapp (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                    (typsubst_exp C X e) (typsubst_typ C X A0)
                    (typsubst_typ C X C2) (typsubst_typ C X B0)
                    (typsubst_typ C X C1)).
    + apply (IH D1 Heq Hfresh).
    + apply (typsubst_appDist C X HlcC B0 (t_forall C1 C2) HDt).
    + apply (Hdisj D1 A0 C1 Hfresh).
      rewrite Heq in HDj. exact HDj.
  - (* Typ_proj *)
    simpl. apply (Typ_proj (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                           (typsubst_exp C X e) l
                           (typsubst_typ C X C0) (typsubst_typ C X A0)).
    + apply (IH D1 Heq Hfresh).
    + apply (typsubst_appDist C X HlcC A0 (t_rcd l C0) HDt).
  - (* Typ_rcd *)
    simpl. apply (Typ_rcd (tsubst_mid C X D1 nil) (subst_ctx C X G0) l
                          (typsubst_exp C X e) (typsubst_typ C X A0)).
    apply (IH D1 Heq Hfresh).
  - (* Typ_merge *)
    simpl. apply (Typ_merge (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                            (typsubst_exp C X e1) (typsubst_exp C X e2)
                            (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + apply (IH1 D1 Heq Hfresh).
    + apply (IH2 D1 Heq Hfresh).
    + apply (Hdisj D1 A0 B0 Hfresh).
      rewrite Heq in HDj. exact HDj.
  - (* Typ_inter *)
    simpl. apply (Typ_inter (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                            (typsubst_exp C X e)
                            (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + apply (IH1 D1 Heq Hfresh).
    + apply (IH2 D1 Heq Hfresh).
  - (* Typ_anno *)
    simpl. apply (Typ_anno (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                           (typsubst_exp C X e) (typsubst_typ C X A0)).
    apply (IH D1 Heq Hfresh).
  - (* Typ_fix *)
    simpl. apply (Typ_fix L (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                         (typsubst_typ C X A0) (typsubst_exp C X e)).
    intros x Hx.
    pose proof (IHBODY x Hx D1 Heq Hfresh) as Hres.
    rewrite (typsubst_open_exp C X e (e_var_f x)) in Hres.
    simpl in Hres.
    exact Hres.
  - (* Typ_mergev *)
    simpl. apply (Typ_mergev (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                             (typsubst_exp C X u1) (typsubst_exp C X u2)
                             (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + assert (HTCsplit : TCWell (D1 ++ [(X,T0)])).
      { rewrite <- Heq. exact HTC0. }
      try rewrite tsubst_mid_nil.
      try rewrite app_nil_r.
      exact (typsubst_TCWell_drop D1 X T0 Hfresh HTCsplit C HCT).
    + apply (CWell_typsubst_mid_gen D0 G0 HCW0 D1 X T0 nil Heq Hfresh_nil C
                (TWell_nil_weaken (tsubst_mid C X D1 nil) C HCT)).
    + apply (uniq_subst_ctx C X G0 Hu0).
    + apply (typing_typsubst_free C X HlcC HordC nil nil u1 Inf A0 Ht1
                (notin_dom_nil X)).
    + apply (typing_typsubst_free C X HlcC HordC nil nil u2 Inf B0 Ht2
                (notin_dom_nil X)).
    + apply (typsubst_consistent C X HlcC HordC u1 u2 Hcons).
  - (* Typ_sub *)
    simpl. apply (Typ_sub (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                          (typsubst_exp C X e)
                          (typsubst_typ C X B0) (typsubst_typ C X A0)).
    + apply (IH D1 Heq Hfresh).
    + assert (HTCsrc : TCWell D0)
        by (exact (proj1 (typing_env_wf D0 G0 e Inf A0 Ht))).
      assert (HTCsplit : TCWell (D1 ++ [(X,T0)])).
      { rewrite <- Heq. exact HTCsrc. }
      assert (HTCtg : TCWell (tsubst_mid C X D1 nil)).
      { rewrite tsubst_mid_nil.
        exact (typsubst_TCWell_drop D1 X T0 Hfresh HTCsplit C HCT). }
      apply (algo_sub_typsubst_mid_gen_nobot D0 A0 B0 Hsub
               D1 X T0 nil Heq Hfresh_nil C HTCsrc HTCtg
               (TWell_nil_weaken (tsubst_mid C X D1 nil) C HCT)
               HordC Htop0).
Qed.


(* ================================================================== *)
(* Final target lemma for [papp_agent].                                *)
(*                                                                     *)
(* This is the requested type-substitution-under-typing statement for  *)
(* [Typ_tabs], with two explicit premises that we could not remove:    *)
(*                                                                     *)
(*  - [ord C], used by the algorithmic-subtyping translation; and      *)
(*  - [Hdisj], the disjointness-preservation family for the [D_varl]/  *)
(*    [D_varr] cases of the [Typ_tapp]/[Typ_merge] side conditions.    *)
(*                                                                     *)
(* The [topLike nil C \/ ~ botLike A] side condition is *derived* from *)
(* [disjoint nil C A] via [disjoint_nil_topLike_or_not_botLike].       *)
(* ================================================================== *)

Lemma typing_typsubst_tabs_disj : forall body A B2 C X,
    lc_typ C -> ord C ->
    X \notin typefv_exp body ->
    X \notin typefv_typ B2 ->
    disjoint nil C A ->
    TWell nil A ->
    TWell nil C ->
    (forall (D1:tctx) P Q,
       X \notin dom D1 ->
       disjoint (D1 ++ [(X,A)]) P Q ->
       disjoint (tsubst_mid C X D1 nil)
                (typsubst_typ C X P) (typsubst_typ C X Q)) ->
    Typing (cons (X,A) nil) nil
      (open_exp_wrt_typ body (t_tvar_f X)) Chk
      (open_typ_wrt_typ B2 (t_tvar_f X)) ->
    Typing nil nil (open_exp_wrt_typ body C) Chk (open_typ_wrt_typ B2 C).
Proof.
  intros body A B2 C X HlcC HordC HXb HXB HdCA HTA HTC Hdisj Hbody.
  assert (Htop0 : topLike nil C \/ ~ botLike A)
    by (apply (disjoint_nil_topLike_or_not_botLike C A); exact HdCA).
  pose proof (typing_typsubst_mid_gen C X A HlcC HordC HTC Htop0 Hdisj
                (cons (X,A) nil) nil
                (open_exp_wrt_typ body (t_tvar_f X)) Chk
                (open_typ_wrt_typ B2 (t_tvar_f X)) Hbody
                nil eq_refl (notin_dom_nil X)) as Hres.
  change (Typing nil nil
            (typsubst_exp C X (open_exp_wrt_typ body (t_tvar_f X))) Chk
            (typsubst_typ C X (open_typ_wrt_typ B2 (t_tvar_f X)))) in Hres.
  rewrite (typsubst_open_exp_typ_any C X HlcC body (t_tvar_f X)) in Hres.
  rewrite (typsubst_open_typ_any C X HlcC B2 (t_tvar_f X)) in Hres.
  rewrite (typsubst_exp_id_notin C X body HXb) in Hres.
  rewrite (typsubst_typ_id_notin C X B2 HXB) in Hres.
  rewrite (typsubst_tvar_same C X) in Hres.
  exact Hres.
Qed.
End agentL2.
Import agentL2.

Module progress_final.
Import ListNotations.

Section Assumptions.
Definition TWell_lc_typ := @agentA.TWell_lc_typ.
Definition ord_lc_typ := @agentA.ord_lc_typ.
Definition topLike_lc_typ := @agentA.topLike_lc_typ.
Definition spl_lc := @agentA.spl_lc.
Definition algo_sub_lc := @agentA.algo_sub_lc.
Definition algo_sub_TWell_target := @agentA.algo_sub_TWell_target.
Definition typing_lc_exp := @agentB.typing_lc_exp.
Definition typing_lc_typ := @agentB.typing_lc_typ.
Definition disjoint_lc := @agentA.disjoint_lc.

Hint Resolve TWell_lc_typ ord_lc_typ topLike_lc_typ spl_lc algo_sub_lc
  algo_sub_TWell_target typing_lc_exp typing_lc_typ disjoint_lc : core.

(* ============================================================ *)
(* Constructive auxiliaries (no classical logic)                *)
(* ============================================================ *)

Lemma botLike_dec_lc : forall A, lc_typ A -> {botLike A} + {~ botLike A}.
Proof.
  intros A. induction A as
    [n|X| | | | A1 IH1 A2 IH2 | A1 IH1 A2 IH2 | A1 IH1 A2 IH2 | l A1 IH1];
    intro Hlc.
  - right. intro H. inversion H.
  - right. intro H. inversion H.
  - right. intro H. inversion H.
  - right. intro H. inversion H.
  - left. apply BL_bot.
  - right. intro H. inversion H.
  - right. intro H. inversion H.
  - (* t_and *)
    assert (Hlc1 : lc_typ A1) by (inversion Hlc; assumption).
    assert (Hlc2 : lc_typ A2) by (inversion Hlc; assumption).
    destruct (IH1 Hlc1) as [Hb1|Hnb1].
    + left. apply (BL_andl A1 A2 Hlc2 Hb1).
    + destruct (IH2 Hlc2) as [Hb2|Hnb2].
      * left. apply (BL_andr A1 A2 Hlc1 Hb2).
      * right. intro Hb. inversion Hb; subst;
          [contradiction Hnb1 | contradiction Hnb2].
  - right. intro H. inversion H.
Qed.

Lemma binds_uniq_eq : forall (D:tctx) X A B,
  uniq D -> binds X A D -> binds X B D -> A = B.
Proof.
  intros D. induction D as [|[Y C] D IH]; intros X A B Hu H1 H2.
  - apply binds_nil_iff in H1. destruct H1.
  - pose proof (uniq_cons_1 typ Y C D Hu) as HuD.
    pose proof (uniq_cons_2 typ Y C D Hu) as HYdom.
    apply binds_cons_1 in H1. apply binds_cons_1 in H2.
    destruct H1 as [ [HX1 HA1] | Hin1]; destruct H2 as [ [HX2 HB2] | Hin2].
    + subst. reflexivity.
    + subst X. subst A. exfalso. apply HYdom. apply binds_In in Hin2. exact Hin2.
    + subst X. subst B. exfalso. apply HYdom. apply binds_In in Hin1. exact Hin1.
    + exact (IH X A B HuD Hin1 Hin2).
Qed.

Lemma TCWell_binds_lc : forall (D:tctx), TCWell D ->
  forall X A, binds X A D -> lc_typ A.
Proof.
  intros D HTC. induction HTC as [| D X A HTC IH HTW Huniq]; intros X0 A0 Hb.
  - apply binds_nil_iff in Hb. destruct Hb.
  - apply binds_cons_1 in Hb. destruct Hb as [ [HX HA] | Hin].
    + subst. exact (TWell_lc_typ D A HTW).
    + exact (IH X0 A0 Hin).
Qed.

Lemma ren_ctx_id : forall (D:tctx), ren_ctx (fun Z => Z) D = D.
Proof.
  induction D as [|[X A] D IH]; simpl.
  - reflexivity.
  - assert (H : ren_typ (fun Z => Z) A = A).
    { apply ren_typ_id. intros; reflexivity. }
    simpl. rewrite IH. rewrite H. reflexivity.
Qed.

Lemma notin_u_l : forall (x:atom) (s t:atoms), x \notin (s \u t) -> x \notin s.
Proof. intros x s t H. exact (proj1 (notin_union x s t H)). Qed.

Lemma notin_u_r : forall (x:atom) (s t:atoms), x \notin (s \u t) -> x \notin t.
Proof. intros x s t H. exact (proj2 (notin_union x s t H)). Qed.

Lemma topLike_forall_inv_local : forall (D:tctx) (A B:typ),
  topLike D (t_forall A B) ->
  exists L, forall X, X \notin L ->
    topLike (cons (X,A) D) (open_typ_wrt_typ B (t_tvar_f X)).
Proof.
  intros D A B H. inversion H; subst. eexists; eassumption.
Qed.

(* Renaming the freshly opened type variable of a top-like body. *)
Lemma topLike_cons_rename : forall (D:tctx) (A B:typ) (X Y:typevar),
  TCWell D -> TWell D A ->
  X \notin dom D -> Y \notin dom D ->
  X \notin typefv_typ_range D ->
  X \notin [[A]] -> X \notin [[B]] ->
  topLike (cons (X,A) D) (open_typ_wrt_typ B (t_tvar_f X)) ->
  topLike (cons (Y,A) D) (open_typ_wrt_typ B (t_tvar_f Y)).
Proof.
  intros D A B X Y HTC HTWA HXdom HYdom HXrng HXA HXB Htop.
  pose (f := rename_var X Y).
  assert (HfX : f X = Y).
  { unfold f. apply rename_var_eq. }
  assert (HfA : ren_typ f A = A).
  { apply ren_typ_id. intros Z HZ. unfold f. apply rename_var_neq.
    intro Heq. apply HXA. subst Z. exact HZ. }
  assert (HfD : ren_ctx f D = D).
  { rewrite (ren_ctx_eq D f (fun Z => Z)).
    - apply ren_ctx_id.
    - intros Z HZ. unfold f. apply rename_var_neq. intro Heq.
      apply HXdom. subst Z. exact HZ.
    - intros Z HZ. unfold f. apply rename_var_neq. intro Heq.
      apply HXrng. subst Z. exact HZ. }
  assert (Huniq' : uniq (ren_ctx f (cons (X,A) D))).
  { rewrite ren_ctx_cons. rewrite HfA, HfD, HfX.
    apply (TCWell_uniq (cons (Y,A) D)).
    apply TCW_cons.
    - exact HTC.
    - exact HTWA.
    - apply uniq_cons; [ apply (TCWell_uniq D HTC) | exact HYdom ]. }
  pose proof (topLike_ren (cons (X,A) D)
                (open_typ_wrt_typ B (t_tvar_f X)) Htop f Huniq') as Hres.
  rewrite ren_ctx_cons in Hres. rewrite HfA, HfD, HfX in Hres.
  unfold f in Hres.
  rewrite ren_typ_open_rename in Hres; [ exact Hres | exact HXB ].
Qed.

Lemma topLike_forall_intro : forall (D:tctx) (A B:typ) (X:typevar),
  TCWell D -> TWell D A ->
  X \notin dom D -> X \notin typefv_typ_range D ->
  X \notin [[A]] -> X \notin [[B]] ->
  topLike (cons (X,A) D) (open_typ_wrt_typ B (t_tvar_f X)) ->
  topLike D (t_forall A B).
Proof.
  intros D A B X HTC HTWA HXdom HXrng HXA HXB Htop.
  apply (TL_all (dom D) D A B).
  intros Y HYdom.
  exact (topLike_cons_rename D A B X Y HTC HTWA HXdom HYdom
           HXrng HXA HXB Htop).
Qed.

Lemma topLike_forall_elim : forall (D:tctx) (A B:typ) (X:typevar),
  TCWell D -> TWell D A ->
  X \notin dom D -> X \notin typefv_typ_range D ->
  X \notin [[A]] -> X \notin [[B]] ->
  topLike D (t_forall A B) ->
  topLike (cons (X,A) D) (open_typ_wrt_typ B (t_tvar_f X)).
Proof.
  intros D A B X HTC HTWA HXdom HXrng HXA HXB Htop.
  destruct (topLike_forall_inv_local D A B Htop) as [L0 Hbody].
  pose (bad := L0 \u dom D \u typefv_typ_range D \u [[A]] \u [[B]]).
  destruct (atom_fresh bad) as [Y HYbad].
  pose proof (notin_u_l Y _ _ HYbad) as HYL0.
  pose proof (notin_u_r Y _ _ HYbad) as HYrest.
  pose proof (notin_u_l Y _ _ HYrest) as HYdom.
  pose proof (notin_u_r Y _ _ HYrest) as HYrest2.
  pose proof (notin_u_l Y _ _ HYrest2) as HYrng.
  pose proof (notin_u_r Y _ _ HYrest2) as HYrest3.
  pose proof (notin_u_l Y _ _ HYrest3) as HYA.
  pose proof (notin_u_r Y _ _ HYrest3) as HYB.
  exact (topLike_cons_rename D A B Y X HTC HTWA HYdom HXdom
           HYrng HYA HYB (Hbody Y HYL0)).
Qed.

(* Constructive dichotomy of [topLike] for ord well-formed types.
   The conclusion lives in [Prop], which is what the uses below need. *)
Lemma topLike_dec_ord : forall A, ord A ->
  forall D, TCWell D -> TWell D A -> topLike D A \/ ~ topLike D A.
Proof.
  intros A Hord. induction Hord as
    [ X
    |
    |
    |
    | A B HlcA HordB IHB
    | L A B HlcA Hbody IHBODY
    | l B HordB IHB ];
    intros D HTC HTW.
  - (* O_var *)
    inversion HTW; subst.
    match goal with
    | Hb : binds X ?A0 D |- _ =>
        let Hlc := fresh "Hlc" in
        let Hbl := fresh "Hbl" in
        let Hnbl := fresh "Hnbl" in
        assert (Hlc : lc_typ A0) by
          (apply (TCWell_binds_lc D HTC X A0 Hb));
        destruct (botLike_dec_lc A0 Hlc) as [Hbl|Hnbl];
        [ left; apply (TL_var D X A0 HTC Hb Hbl)
        | right; intro Htl; inversion Htl; subst;
          match goal with
          | Hb0 : binds X ?A' D, Hbl0 : botLike ?A' |- _ =>
              assert (Heq : A' = A0) by
                (exact (binds_uniq_eq D X A' A0 (TCWell_uniq D HTC) Hb0 Hb));
              subst A'; exact (Hnbl Hbl0)
          end ]
    end.
  - (* O_top *) left. apply TL_top. exact HTC.
  - (* O_bot *) right. apply topLike_t_bot_false.
  - (* O_int *) right. apply topLike_t_int_false.
  - (* O_arrow *)
    destruct (TWell_arrow_inv D A B HTW) as [HTA HTB].
    destruct (IHB D HTC HTB) as [HtopB|HnB].
    + left. apply TL_arrow; assumption.
    + right. intro Htl. apply HnB.
      exact (proj2 (topLike_arrow_inv D A B Htl)).
  - (* O_all *)
    assert (HTWA : TWell D A) by (apply (TWell_all_inv D A B); exact HTW).
    destruct (TWell_all_body D A B HTW) as [Ltw HbodyTW].
    pose (bad := L \u Ltw \u [[A]] \u [[B]] \u dom D \u typefv_typ_range D).
    destruct (atom_fresh bad) as [X HXbad].
    pose proof (notin_u_l X _ _ HXbad) as HXL.
    pose proof (notin_u_r X _ _ HXbad) as HXrest.
    pose proof (notin_u_l X _ _ HXrest) as HXLtw.
    pose proof (notin_u_r X _ _ HXrest) as HXrest2.
    pose proof (notin_u_l X _ _ HXrest2) as HXA.
    pose proof (notin_u_r X _ _ HXrest2) as HXrest3.
    pose proof (notin_u_l X _ _ HXrest3) as HXB.
    pose proof (notin_u_r X _ _ HXrest3) as HXrest4.
    pose proof (notin_u_l X _ _ HXrest4) as HXdom.
    pose proof (notin_u_r X _ _ HXrest4) as HXrng.
    assert (HTCcons : TCWell (cons (X,A) D)).
    { apply TCW_cons.
      - exact HTC.
      - exact HTWA.
      - apply uniq_cons.
        + apply (TCWell_uniq D HTC).
        + exact HXdom. }
    assert (HTWbody : TWell (cons (X,A) D) (open_typ_wrt_typ B (t_tvar_f X)))
      by (apply (HbodyTW X); exact HXLtw).
    assert (Hordbody : ord (open_typ_wrt_typ B (t_tvar_f X)))
      by (apply (Hbody X); exact HXL).
    destruct (IHBODY X HXL (cons (X,A) D) HTCcons HTWbody)
      as [HtopBody|HnBody].
    + left. exact (topLike_forall_intro D A B X HTC HTWA HXdom HXrng
                     HXA HXB HtopBody).
    + right. intro Htl. apply HnBody.
      exact (topLike_forall_elim D A B X HTC HTWA HXdom HXrng
               HXA HXB Htl).
  - (* O_rcd *)
    destruct (IHB D HTC (TWell_rcd_inv D l B HTW)) as [HtopB|HnB].
    + left. apply TL_rcd. exact HtopB.
    + right. intro Htl. apply HnB.
      exact (topLike_rcd_inv D l B Htl).
Qed.

Lemma topLike_dec_nil : forall (A:typ), ord A -> TWell nil A ->
  topLike nil A \/ ~ topLike nil A.
Proof.
  intros A Hord HTW. exact (topLike_dec_ord A Hord nil TCW_empty HTW).
Qed.

Lemma value_lc : forall e, value e -> lc_exp e.
Proof.
  intros e H. induction H.
  - apply lc_e_top.
  - apply lc_e_lit.
  - apply lc_e_anno; assumption.
  - assumption.
  - apply lc_e_anno; assumption.
  - assumption.
  - apply lc_e_anno; [ apply lc_e_rcd; assumption | assumption ].
  - apply lc_e_rcd; assumption.
  - apply lc_e_merge; assumption.
Qed.

Lemma prevalue_lc : forall e, prevalue e -> lc_exp e.
Proof.
  intros e H. induction H.
  - apply lc_e_lit.
  - apply lc_e_top.
  - apply lc_e_anno; assumption.
  - apply lc_e_merge; assumption.
Qed.

Lemma pType_lc : forall e A, pType e A -> lc_exp e.
Proof.
  intros e A H. induction H.
  - apply lc_e_top.
  - apply lc_e_lit.
  - apply lc_e_anno; assumption.
  - apply lc_e_merge; assumption.
Qed.

Lemma binds_nil_false : forall (x:termvar) (A:typ), binds x A nil -> False.
Proof. intros. apply binds_nil_iff in H. auto. Qed.

Lemma TWell_nil_tvar_false : forall X, TWell nil (t_tvar_f X) -> False.
Proof.
  intros X H. inversion H; subst.
  match goal with H1 : binds _ _ nil |- _ => apply binds_nil_false in H1; auto end.
Qed.

Lemma ord_topLike_shape : forall A, ord A -> topLike nil A ->
  A = t_top \/ (exists X Y, A = t_arrow X Y) \/ (exists X Y, A = t_forall X Y) \/ (exists l X, A = t_rcd l X).
Proof.
  intros A H. induction H; intro Htl.
  - exfalso. inversion Htl; subst.
    match goal with H : binds _ _ nil |- _ => apply binds_nil_false in H; auto end.
  - left; reflexivity.
  - exfalso. inversion Htl.
  - exfalso. inversion Htl.
  - right; left; exists A, B; reflexivity.
  - right; right; left; exists A, B; reflexivity.
  - right; right; right; exists l, B; reflexivity.
Qed.

Lemma casting_topLike_ord : forall A, ord A -> topLike nil A ->
  forall v, lc_exp v -> exists v', casting v A v'.
Proof.
  intros A Hord Htl v Hlc.
  destruct (ord_topLike_shape A Hord Htl) as [ Htop | [ Harrow | [ Hall | Hrcd ] ] ].
  - subst. exists e_top. apply Cast_top; auto.
  - destruct Harrow as [ X [ Y HA ] ]. subst.
    exists (e_anno (e_abs t_top e_top) (t_arrow X Y)). apply Cast_topArrow; auto.
  - destruct Hall as [ X [ Y HA ] ]. subst.
    exists (e_anno (e_tabs e_top) (t_forall X Y)). apply Cast_topAll; auto.
  - destruct Hrcd as [ l [ X HA ] ]. subst.
    exists (e_anno (e_rcd l e_top) (t_rcd l X)). apply Cast_topRcd; auto.
Qed.

Lemma casting_top_sub : forall D S A, D = nil -> algo_sub D S A -> S = t_top ->
  forall v, lc_exp v -> exists v', casting v A v'.
Proof.
  intros D S A ED H. pose proof H as Hrel. induction H; intros ES v Hlc.
  - discriminate ES.
  - discriminate ES.
  - subst. apply casting_topLike_ord; assumption.
  - discriminate ES.
  - discriminate ES.
  - discriminate ES.
  - discriminate ES.
  - discriminate ES.
  - discriminate ES.
  - subst. destruct (IHalgo_sub1 eq_refl H0 eq_refl v Hlc) as [v1 Hc1].
    destruct (IHalgo_sub2 eq_refl H1 eq_refl v Hlc) as [v2 Hc2].
    exists (e_merge v1 v2). apply Cast_and with (B:=B1) (C:=B2); auto.
Qed.

Lemma casting_int_sub : forall D i S A, D = nil -> algo_sub D S A -> S = t_int ->
  exists v', casting (e_lit i) A v'.
Proof.
  intros D i S A ED H. pose proof H as Hrel. induction H; intros ES.
  - discriminate ES.
  - subst. exists (e_lit i). apply Cast_int.
  - subst. apply casting_topLike_ord; auto using lc_e_lit.
  - discriminate ES.
  - discriminate ES.
  - discriminate ES.
  - discriminate ES.
  - discriminate ES.
  - discriminate ES.
  - subst. destruct (IHalgo_sub1 eq_refl H0 eq_refl) as [v1 Hc1].
    destruct (IHalgo_sub2 eq_refl H1 eq_refl) as [v2 Hc2].
    exists (e_merge v1 v2). apply Cast_and with (B:=B1) (C:=B2); auto.
Qed.

Lemma cast_anno_ord : forall (e:exp) (A0 B:typ),
  lc_exp e -> lc_typ A0 -> algo_sub nil A0 B -> ord B -> exists v', casting (e_anno e A0) B v'.
Proof.
  intros e A0 B Hlc HlcA Hsub Hord.
  destruct (topLike_dec_nil B Hord
              (algo_sub_TWell_target nil A0 B TCW_empty Hsub)) as [Htop | Hnt].
  - apply casting_topLike_ord; [assumption|assumption|apply lc_e_anno; assumption].
  - exists (e_anno e B). apply Cast_anno.
    + assumption.
    + assumption.
    + apply NTL.
      * apply TCW_empty.
      * eapply algo_sub_TWell_target; [apply TCW_empty | apply Hsub].
      * auto.
    + assumption.
Qed.

Lemma casting_anno_sub : forall D (e:exp) (A0:typ) (B:typ),
  D = nil -> lc_exp e -> lc_typ A0 -> algo_sub D A0 B -> exists v', casting (e_anno e A0) B v'.
Proof.
  intros D e A0 B ED Hlc HlcA H. pose proof H as Hrel. induction H.
  - (* S_var *) exfalso. subst.
    match goal with H : TWell nil (t_tvar_f _) |- _ => apply TWell_nil_tvar_false in H; auto end.
  - (* S_int *) subst. apply cast_anno_ord; auto. apply O_int.
  - (* S_top *) subst. apply casting_topLike_ord; [assumption|assumption|apply lc_e_anno; assumption].
  - (* S_bot *) subst. apply cast_anno_ord; auto.
  - (* S_andl *) subst. apply cast_anno_ord; auto.
  - (* S_andr *) subst. apply cast_anno_ord; auto.
  - (* S_arrow *) subst. apply cast_anno_ord; auto.
    apply O_arrow; [ apply (proj1 (algo_sub_lc nil A2 A1 H0)) | assumption ].
  - (* S_all *) subst. apply cast_anno_ord; auto.
    apply O_all with (L:=L).
    + apply (proj1 (algo_sub_lc nil B1 A1 H0)).
    + assumption.
  - (* S_rcd *) subst. apply cast_anno_ord; auto. apply O_rcd; assumption.
  - (* S_and *) subst. destruct (IHalgo_sub1 eq_refl HlcA H0) as [v1 Hc1].
    destruct (IHalgo_sub2 eq_refl HlcA H1) as [v2 Hc2].
    exists (e_merge v1 v2). apply Cast_and with (B:=B1) (C:=B2); auto.
Qed.

Lemma casting_merge_sub : forall D A1 A2 S A (v1 v2:exp),
  D = nil -> S = t_and A1 A2 -> lc_exp v1 -> lc_exp v2 ->
  (forall B, algo_sub nil A1 B -> exists v', casting v1 B v') ->
  (forall B, algo_sub nil A2 B -> exists v', casting v2 B v') ->
  algo_sub D S A -> exists v', casting (e_merge v1 v2) A v'.
Proof.
  intros D A1 A2 S A v1 v2 ED ES Hlc1 Hlc2 Hc1 Hc2 H.
  pose proof H as Hrel. induction H; intros.
  - discriminate ES.
  - discriminate ES.
  - subst. apply casting_topLike_ord; [assumption|assumption|apply lc_e_merge; assumption].
  - discriminate ES.
  - subst. inversion ES; subst. destruct (Hc1 C) as [v1' Hv1']; [assumption|].
    exists v1'. apply Cast_mergel; auto.
  - subst. inversion ES; subst. destruct (Hc2 C) as [v2' Hv2']; [assumption|].
    exists v2'. apply Cast_merger; auto.
  - discriminate ES.
  - discriminate ES.
  - discriminate ES.
  - subst. destruct (IHalgo_sub1 eq_refl eq_refl H0) as [v1' Hv1'].
    destruct (IHalgo_sub2 eq_refl eq_refl H1) as [v2' Hv2'].
    exists (e_merge v1' v2'). apply Cast_and with (B:=B1) (C:=B2); auto.
Qed.

Lemma casting_of_inf_value : forall (v:exp), value v ->
  forall (A:typ), Typing nil nil v Inf A ->
  forall B, algo_sub nil A B -> exists v', casting v B v'.
Proof.
  intros v Hval. induction Hval; intros AT Hty BT Hsub.
  - inversion Hty; subst.
    exact (casting_top_sub nil t_top BT eq_refl Hsub eq_refl e_top lc_e_top).
  - inversion Hty; subst.
    exact (casting_int_sub nil i t_int BT eq_refl Hsub eq_refl).
  - inversion Hty; subst.
    match goal with
    | Hsub' : algo_sub nil ?S ?T, Hlc : lc_exp ?E, HlcS : lc_typ ?S
      |- exists v', casting (e_anno ?E ?S) ?T v' =>
        exact (casting_anno_sub nil E S T eq_refl Hlc HlcS Hsub')
    end.
  - inversion Hty.
  - inversion Hty; subst.
    match goal with
    | Hsub' : algo_sub nil ?S ?T, Hlc : lc_exp ?E, HlcS : lc_typ ?S
      |- exists v', casting (e_anno ?E ?S) ?T v' =>
        exact (casting_anno_sub nil E S T eq_refl Hlc HlcS Hsub')
    end.
  - inversion Hty.
  - inversion Hty; subst.
    match goal with
    | Hsub' : algo_sub nil ?S ?T, Hlc : lc_exp ?E0, HlcS : lc_typ ?S
      |- exists v', casting (e_anno (e_rcd ?l ?E0) ?S) ?T v' =>
        exact (casting_anno_sub nil (e_rcd l E0) S T eq_refl (lc_e_rcd l E0 Hlc) HlcS Hsub')
    end.
  - inversion Hty.
  - inversion Hty; subst.
    + match goal with
      | Hsub' : algo_sub nil (t_and ?A1 ?A2) ?T |- exists v', casting (e_merge ?u1 ?u2) ?T v' =>
          let Hty1 := match goal with H : Typing nil nil u1 Inf A1 |- _ => constr:(H) end in
          let Hty2 := match goal with H : Typing nil nil u2 Inf A2 |- _ => constr:(H) end in
          let Hv1 := match goal with H : value u1 |- _ => constr:(H) end in
          let Hv2 := match goal with H : value u2 |- _ => constr:(H) end in
          let IH1 := match goal with H : forall A0, Typing nil nil u1 Inf A0 -> forall B0, algo_sub nil A0 B0 -> exists v', casting u1 B0 v' |- _ => constr:(H) end in
          let IH2 := match goal with H : forall A0, Typing nil nil u2 Inf A0 -> forall B0, algo_sub nil A0 B0 -> exists v', casting u2 B0 v' |- _ => constr:(H) end in
          exact (casting_merge_sub nil A1 A2 (t_and A1 A2) T u1 u2 eq_refl eq_refl
                   (value_lc u1 Hv1) (value_lc u2 Hv2)
                   (fun C Hs => IH1 A1 Hty1 C Hs)
                   (fun C Hs => IH2 A2 Hty2 C Hs) Hsub')
      end.
    + match goal with
      | Hsub' : algo_sub nil (t_and ?A1 ?A2) ?T |- exists v', casting (e_merge ?u1 ?u2) ?T v' =>
          let Hty1 := match goal with H : Typing nil nil u1 Inf A1 |- _ => constr:(H) end in
          let Hty2 := match goal with H : Typing nil nil u2 Inf A2 |- _ => constr:(H) end in
          let Hv1 := match goal with H : value u1 |- _ => constr:(H) end in
          let Hv2 := match goal with H : value u2 |- _ => constr:(H) end in
          let IH1 := match goal with H : forall A0, Typing nil nil u1 Inf A0 -> forall B0, algo_sub nil A0 B0 -> exists v', casting u1 B0 v' |- _ => constr:(H) end in
          let IH2 := match goal with H : forall A0, Typing nil nil u2 Inf A0 -> forall B0, algo_sub nil A0 B0 -> exists v', casting u2 B0 v' |- _ => constr:(H) end in
          exact (casting_merge_sub nil A1 A2 (t_and A1 A2) T u1 u2 eq_refl eq_refl
                   (value_lc u1 Hv1) (value_lc u2 Hv2)
                   (fun C Hs => IH1 A1 Hty1 C Hs)
                   (fun C Hs => IH2 A2 Hty2 C Hs) Hsub')
      end.
Qed.

Lemma inf_value_prevalue : forall (v:exp), value v ->
  forall A, Typing nil nil v Inf A -> prevalue v.
Proof.
  intros v Hval. induction Hval; intros AT Hty.
  - inversion Hty; subst. apply PV_top.
  - inversion Hty; subst. apply PV_int.
  - inversion Hty; subst.
    match goal with
    | Hlc : lc_exp ?E, HlcB : lc_typ ?B |- prevalue (e_anno ?E ?B) => apply PV_anno; assumption
    end.
  - inversion Hty.
  - inversion Hty; subst.
    match goal with
    | Hlc : lc_exp ?E, HlcB : lc_typ ?B |- prevalue (e_anno ?E ?B) => apply PV_anno; assumption
    end.
  - inversion Hty.
  - inversion Hty; subst.
    match goal with
    | Hlc : lc_exp ?E, HlcB : lc_typ ?B |- prevalue (e_anno (e_rcd ?l ?E) ?B) =>
        apply PV_anno; [ apply lc_e_rcd; exact Hlc | exact HlcB ]
    end.
  - inversion Hty.
  - inversion Hty; subst.
    + match goal with
      | H1 : Typing nil nil ?u1 Inf ?A1, H2 : Typing nil nil ?u2 Inf ?A2
        |- prevalue (e_merge ?u1 ?u2) =>
          let IH1 := match goal with H : forall A0, Typing nil nil u1 Inf A0 -> prevalue u1 |- _ => constr:(H) end in
          let IH2 := match goal with H : forall A0, Typing nil nil u2 Inf A0 -> prevalue u2 |- _ => constr:(H) end in
          apply PV_merge; [ exact (IH1 A1 H1) | exact (IH2 A2 H2) ]
      end.
    + match goal with
      | H1 : Typing nil nil ?u1 Inf ?A1, H2 : Typing nil nil ?u2 Inf ?A2
        |- prevalue (e_merge ?u1 ?u2) =>
          let IH1 := match goal with H : forall A0, Typing nil nil u1 Inf A0 -> prevalue u1 |- _ => constr:(H) end in
          let IH2 := match goal with H : forall A0, Typing nil nil u2 Inf A0 -> prevalue u2 |- _ => constr:(H) end in
          apply PV_merge; [ exact (IH1 A1 H1) | exact (IH2 A2 H2) ]
      end.
Qed.

Lemma chk_prevalue_cast : forall (v:exp), value v -> prevalue v ->
  forall A, Typing nil nil v Chk A -> exists v', casting v A v'.
Proof.
  intros v Hval Hpv A Hty. dependent induction Hty.
  - (* Typ_abs *) inversion Hpv.
  - (* Typ_tabs *) inversion Hpv.
  - (* Typ_rcd *) inversion Hpv.
  - (* Typ_inter *)
    destruct (IHHty1 Hval Hpv (JMeq_refl _) (JMeq_refl _) eq_refl) as [v1 Hc1].
    destruct (IHHty2 Hval Hpv (JMeq_refl _) (JMeq_refl _) eq_refl) as [v2 Hc2].
    eexists; eapply Cast_and with (B:=A) (C:=B);
    [ apply Sp_and; [ eapply typing_lc_typ; eauto | eapply typing_lc_typ; eauto ] | exact Hc1 | exact Hc2 ].
  - (* Typ_sub *)
    match goal with
    | Hinf : Typing nil nil ?w Inf ?B, Hsub : algo_sub nil ?B ?T |- _ =>
        exact (casting_of_inf_value w Hval B Hinf T Hsub)
    end.
Qed.

Lemma chk_merge_prevalue : forall (v1 v2:exp), value v1 -> value v2 ->
  forall A, Typing nil nil (e_merge v1 v2) Chk A -> prevalue (e_merge v1 v2).
Proof.
  intros v1 v2 Hv1 Hv2 A Hty. dependent induction Hty.
  - (* Typ_inter *)
    exact (IHHty2 v2 Hv2 v1 Hv1 (JMeq_refl _) (JMeq_refl _) eq_refl eq_refl).
  - (* Typ_sub *)
    match goal with
    | Hinf : Typing nil nil (e_merge v1 v2) Inf ?B |- _ =>
        inversion Hinf; subst;
        (let H1 := match goal with H : Typing nil nil v1 Inf ?A1 |- _ => constr:(H) end in
         let H2 := match goal with H : Typing nil nil v2 Inf ?A2 |- _ => constr:(H) end in
         apply PV_merge;
         [ exact (inf_value_prevalue v1 Hv1 _ H1) | exact (inf_value_prevalue v2 Hv2 _ H2) ])
    end.
Qed.

Lemma chk_value_behavior : forall (v:exp), value v ->
  forall A, Typing nil nil v Chk A ->
  (exists A0 e, v = e_abs A0 e) \/ (exists e, v = e_tabs e) \/
  (exists l e, v = e_rcd l e) \/
  (prevalue v /\ exists v', casting v A v').
Proof.
  intros v Hval. remember Hval as Hv eqn:E. destruct Hval; intros AT Hty.
  - (* V_unit *) right; right; right; split.
    + apply PV_top.
    + exact (chk_prevalue_cast e_top Hv PV_top AT Hty).
  - (* V_lit *) right; right; right; split.
    + apply PV_int.
    + exact (chk_prevalue_cast (e_lit i) Hv (PV_int i) AT Hty).
  - (* V_abs *) right; right; right.
    match goal with |- prevalue ?V /\ (exists v', casting ?V AT v') =>
      assert (HPV : prevalue V) by (apply PV_anno; assumption);
      split; [ exact HPV | exact (chk_prevalue_cast V Hv HPV AT Hty) ]
    end.
  - (* V_bareAbs *) left. eauto.
  - (* V_tabs *) right; right; right.
    match goal with |- prevalue ?V /\ (exists v', casting ?V AT v') =>
      assert (HPV : prevalue V) by (apply PV_anno; assumption);
      split; [ exact HPV | exact (chk_prevalue_cast V Hv HPV AT Hty) ]
    end.
  - (* V_bareTabs *) right; left. eauto.
  - (* V_rcd *) right; right; right.
    match goal with |- prevalue ?V /\ (exists v', casting ?V AT v') =>
      assert (HPV : prevalue V) by (apply PV_anno; [ apply lc_e_rcd; assumption | assumption ]);
      split; [ exact HPV | exact (chk_prevalue_cast V Hv HPV AT Hty) ]
    end.
  - (* V_bareRcd *) right; right; left. eauto.
  - (* V_merge *) right; right; right.
    assert (HPV : prevalue (e_merge v1 v2)) by (exact (chk_merge_prevalue v1 v2 Hval1 Hval2 AT Hty)).
    split; [ exact HPV | exact (chk_prevalue_cast (e_merge v1 v2) Hv HPV AT Hty) ].
Qed.

Lemma algo_sub_and_l : forall D X A B, algo_sub D X (t_and A B) -> algo_sub D X A.
Proof.
  intros D X A B H. remember (t_and A B) as T eqn:ET.
  revert A B ET. induction H; intros A0 B0 ET.
  - discriminate ET.
  - discriminate ET.
  - subst. exfalso. match goal with Ho : ord (t_and _ _) |- _ => inversion Ho end.
  - subst. exfalso. match goal with Ho : ord (t_and _ _) |- _ => inversion Ho end.
  - subst. exfalso. match goal with Ho : ord (t_and _ _) |- _ => inversion Ho end.
  - subst. exfalso. match goal with Ho : ord (t_and _ _) |- _ => inversion Ho end.
  - discriminate ET.
  - discriminate ET.
  - discriminate ET.
  - subst. match goal with Hs : spl (t_and A0 B0) ?C1 ?C2 |- _ =>
      inversion Hs; subst; try assumption;
      try (exfalso; match goal with Ho : ord (t_and _ _) |- _ => inversion Ho end) end.
Qed.

Lemma algo_sub_and_r : forall D X A B, algo_sub D X (t_and A B) -> algo_sub D X B.
Proof.
  intros D X A B H. remember (t_and A B) as T eqn:ET.
  revert A B ET. induction H; intros A0 B0 ET.
  - discriminate ET.
  - discriminate ET.
  - subst. exfalso. match goal with Ho : ord (t_and _ _) |- _ => inversion Ho end.
  - subst. exfalso. match goal with Ho : ord (t_and _ _) |- _ => inversion Ho end.
  - subst. exfalso. match goal with Ho : ord (t_and _ _) |- _ => inversion Ho end.
  - subst. exfalso. match goal with Ho : ord (t_and _ _) |- _ => inversion Ho end.
  - discriminate ET.
  - discriminate ET.
  - discriminate ET.
  - subst. match goal with Hs : spl (t_and A0 B0) ?C1 ?C2 |- _ =>
      inversion Hs; subst; try assumption;
      try (exfalso; match goal with Ho : ord (t_and _ _) |- _ => inversion Ho end) end.
Qed.

Lemma chk_and_l_gen : forall D G e d T, Typing D G e d T ->
  forall A B, T = t_and A B -> d = Chk -> Typing D G e Chk A.
Proof.
  intros D G e d T Hty. induction Hty; intros A0 B0 ET Ed.
  - discriminate Ed. - discriminate Ed. - discriminate Ed.
  - discriminate ET.
  - discriminate Ed.
  - discriminate ET.
  - discriminate Ed. - discriminate Ed.
  - discriminate ET.
  - discriminate Ed.
  - inversion ET; subst. match goal with H1 : Typing D G e Chk A0 |- _ => exact H1 end.
  - discriminate Ed.
  - discriminate Ed.
  - discriminate Ed.
  - inversion ET; subst.
    match goal with Hinf : Typing D G e Inf ?C, Hs : algo_sub D ?C (t_and A0 B0) |- _ =>
      exact (Typ_sub D G e A0 C Hinf (algo_sub_and_l D C A0 B0 Hs)) end.
Qed.

Lemma chk_and_r_gen : forall D G e d T, Typing D G e d T ->
  forall A B, T = t_and A B -> d = Chk -> Typing D G e Chk B.
Proof.
  intros D G e d T Hty. induction Hty; intros A0 B0 ET Ed.
  - discriminate Ed. - discriminate Ed. - discriminate Ed.
  - discriminate ET.
  - discriminate Ed.
  - discriminate ET.
  - discriminate Ed. - discriminate Ed.
  - discriminate ET.
  - discriminate Ed.
  - inversion ET; subst. match goal with H1 : Typing D G e Chk B0 |- _ => exact H1 end.
  - discriminate Ed.
  - discriminate Ed.
  - discriminate Ed.
  - inversion ET; subst.
    match goal with Hinf : Typing D G e Inf ?C, Hs : algo_sub D ?C (t_and A0 B0) |- _ =>
      exact (Typ_sub D G e B0 C Hinf (algo_sub_and_r D C A0 B0 Hs)) end.
Qed.

Lemma chk_and_l : forall D G e A B, Typing D G e Chk (t_and A B) -> Typing D G e Chk A.
Proof. intros. eapply chk_and_l_gen; [ exact H | reflexivity | reflexivity ]. Qed.

Lemma chk_and_r : forall D G e A B, Typing D G e Chk (t_and A B) -> Typing D G e Chk B.
Proof. intros. eapply chk_and_r_gen; [ exact H | reflexivity | reflexivity ]. Qed.

Lemma wrapping_topLike_ord : forall A, ord A -> topLike nil A ->
  forall e, lc_exp e -> exists e', wrapping e A e'.
Proof.
  intros A Hord Htl e Hlc.
  destruct (ord_topLike_shape A Hord Htl) as [ Htop | [ Harrow | [ Hall | Hrcd ] ] ].
  - subst. exists e_top. apply EW_top; auto.
  - destruct Harrow as [ X [ Y HA ] ]. subst.
    exists (e_anno (e_abs t_top e_top) (t_arrow X Y)). apply EW_topArrow; auto.
  - destruct Hall as [ X [ Y HA ] ]. subst.
    exists (e_anno (e_tabs e_top) (t_forall X Y)). apply EW_topAll; auto.
  - destruct Hrcd as [ l [ X HA ] ]. subst.
    exists (e_anno (e_rcd l e_top) (t_rcd l X)). apply EW_topRcd; auto.
Qed.

Lemma wrapping_of_sub : forall D S A, D = nil -> algo_sub D S A ->
  forall e, Typing nil nil e Chk S -> exists e', wrapping e A e'.
Proof.
  intros D S A ED H. pose proof H as Hrel. induction H; intros e Hty.
  - (* S_var *) exfalso. subst.
    match goal with H : TWell nil (t_tvar_f _) |- _ => apply TWell_nil_tvar_false in H; auto end.
  - (* S_int *) subst. exists (e_anno e t_int). apply EW_anno.
    + exact (typing_lc_exp _ _ e _ _ Hty).
    + apply O_int.
    + apply NTL.
      * apply TCW_empty.
      * apply TW_int.
      * intro Htl; inversion Htl.
  - (* S_top *) subst. exact (wrapping_topLike_ord B H0 H1 e (typing_lc_exp _ _ e _ _ Hty)).
  - (* S_bot *) subst.
    destruct (topLike_dec_nil A H1
                (algo_sub_TWell_target nil _ _ TCW_empty Hrel)) as [Htop | Hnt].
    + exact (wrapping_topLike_ord A H1 Htop e (typing_lc_exp _ _ e _ _ Hty)).
    + exists (e_anno e A). apply EW_anno.
      * exact (typing_lc_exp _ _ e _ _ Hty).
      * assumption.
      * apply NTL; [apply TCW_empty | assumption | assumption].
  - (* S_andl *) subst.
    destruct (topLike_dec_nil C H0
                (algo_sub_TWell_target nil _ _ TCW_empty Hrel)) as [Htop | Hnt].
    + exact (wrapping_topLike_ord C H0 Htop e (typing_lc_exp _ _ e _ _ Hty)).
    + exists (e_anno e C). apply EW_anno.
      * exact (typing_lc_exp _ _ e _ _ Hty).
      * assumption.
      * apply NTL; [apply TCW_empty | | assumption].
        eapply algo_sub_TWell_target; [apply TCW_empty | apply Hrel].
  - (* S_andr *) subst.
    destruct (topLike_dec_nil C H0
                (algo_sub_TWell_target nil _ _ TCW_empty Hrel)) as [Htop | Hnt].
    + exact (wrapping_topLike_ord C H0 Htop e (typing_lc_exp _ _ e _ _ Hty)).
    + exists (e_anno e C). apply EW_anno.
      * exact (typing_lc_exp _ _ e _ _ Hty).
      * assumption.
      * apply NTL; [apply TCW_empty | | assumption].
        eapply algo_sub_TWell_target; [apply TCW_empty | apply Hrel].
  - (* S_arrow *) subst.
    destruct (topLike_dec_nil (t_arrow A2 B2)
                (O_arrow A2 B2 (proj1 (algo_sub_lc nil A2 A1 H0)) H)
                (algo_sub_TWell_target nil _ _ TCW_empty Hrel)) as [Htop | Hnt].
    + exact (wrapping_topLike_ord (t_arrow A2 B2)
               (O_arrow A2 B2 (proj1 (algo_sub_lc nil A2 A1 H0)) H)
               Htop e (typing_lc_exp _ _ e _ _ Hty)).
    + exists (e_anno e (t_arrow A2 B2)). apply EW_anno.
      * exact (typing_lc_exp _ _ e _ _ Hty).
      * apply O_arrow; [ apply (proj1 (algo_sub_lc nil A2 A1 H0)) | assumption ].
      * apply NTL; [apply TCW_empty | | assumption].
        eapply algo_sub_TWell_target; [apply TCW_empty | apply Hrel].
  - (* S_all *) subst.
    destruct (topLike_dec_nil (t_forall B1 B2)
                (O_all L B1 B2 (proj1 (algo_sub_lc nil B1 A1 H0)) H)
                (algo_sub_TWell_target nil _ _ TCW_empty Hrel)) as [Htop | Hnt].
    + exact (wrapping_topLike_ord (t_forall B1 B2)
               (O_all L B1 B2 (proj1 (algo_sub_lc nil B1 A1 H0)) H)
               Htop e (typing_lc_exp _ _ e _ _ Hty)).
    + exists (e_anno e (t_forall B1 B2)). apply EW_anno.
      * exact (typing_lc_exp _ _ e _ _ Hty).
      * apply O_all with (L:=L).
        { apply (proj1 (algo_sub_lc nil B1 A1 H0)). }
        { assumption. }
      * apply NTL; [apply TCW_empty | | assumption].
        eapply algo_sub_TWell_target; [apply TCW_empty | apply Hrel].
  - (* S_rcd *) subst.
    destruct (topLike_dec_nil (t_rcd l B) (O_rcd l B H)
                (algo_sub_TWell_target nil _ _ TCW_empty Hrel)) as [Htop | Hnt].
    + exact (wrapping_topLike_ord (t_rcd l B) (O_rcd l B H)
               Htop e (typing_lc_exp _ _ e _ _ Hty)).
    + exists (e_anno e (t_rcd l B)). apply EW_anno.
      * exact (typing_lc_exp _ _ e _ _ Hty).
      * apply O_rcd; assumption.
      * apply NTL; [apply TCW_empty | | assumption].
        eapply algo_sub_TWell_target; [apply TCW_empty | apply Hrel].
  - (* S_and *) subst.
    destruct (IHalgo_sub1 eq_refl H0 e Hty) as [e1 Hw1].
    destruct (IHalgo_sub2 eq_refl H1 e Hty) as [e2 Hw2].
    exists (e_merge e1 e2). apply EW_and with (B:=B1) (C:=B2); auto.
Qed.

Definition TWell_coverage := @agentG.TWell_coverage.
Definition spl_TWell_nil := @agentG.spl_TWell_nil.

End Assumptions.

Lemma InA_In : forall (x:atom) (l:list atom), InA eq x l -> In x l.
Proof. induction 1; [left; auto | right; auto]. Qed.

Lemma fresh_notin : forall (L:atoms), fresh (AtomSetImpl.elements L) \notin L.
Proof.
  intros L Hin.
  apply (Atom.fresh_not_in (AtomSetImpl.elements L)).
  apply InA_In. apply AtomSetImpl.elements_1. exact Hin.
Qed.

Lemma size_typ_open_typ : forall (X:typevar) A,
  size_typ (open_typ_wrt_typ A (t_tvar_f X)) = size_typ A.
Proof. intros. unfold open_typ_wrt_typ. apply size_typ_open_typ_tvar. Qed.

Lemma spl_size_lt : forall A B C, spl A B C -> size_typ B < size_typ A /\ size_typ C < size_typ A.
Proof.
  intros A B C H. induction H.
  - (* Sp_arrow *) simpl. split; lia.
  - (* Sp_all *) simpl.
    assert (Hs := H1 (fresh (AtomSetImpl.elements L)) (fresh_notin L)).
    simpl in Hs. rewrite !size_typ_open_typ in Hs.
    split; lia.
  - (* Sp_rcd *) simpl. split; lia.
  - (* Sp_and *) simpl. split; lia.
Qed.

Lemma wrapping_exists : forall A, TWell nil A -> forall e, lc_exp e -> exists e', wrapping e A e'.
Proof.
  intros A HA e0 Hlc0. pose proof (size_typ_pos A) as Hpos.
  assert (Haux : forall n A, size_typ A <= n -> TWell nil A ->
                   forall e, lc_exp e -> exists e', wrapping e A e').
  { induction n as [|n IH]; intros A' Hle HA' e Hlc.
    - pose proof (size_typ_pos A'); lia.
    - destruct (TWell_coverage A' HA') as [ Hord | [ B [ C Hspl ] ] ].
      + destruct (topLike_dec_nil A' Hord HA') as [Htop | Hnt].
        * exact (wrapping_topLike_ord A' Hord Htop e Hlc).
        * exists (e_anno e A'). apply EW_anno; auto.
          apply NTL; [apply TCW_empty | exact HA' | exact Hnt].
      + destruct (spl_TWell_nil A' B C HA' Hspl) as [HTB HTC].
        destruct (spl_size_lt A' B C Hspl) as [HB HC].
        destruct (IH B ltac:(lia) HTB e Hlc) as [e1 Hw1].
        destruct (IH C ltac:(lia) HTC e Hlc) as [e2 Hw2].
        exists (e_merge e1 e2). apply EW_and with (B:=B) (C:=C); auto.
  }
  exact (Haux (size_typ A) A (le_n (size_typ A)) HA e0 Hlc0).
Qed.

Lemma appDist_arrow_inv : forall (B1 B2 B C:typ),
  appDist (t_arrow B1 B2) (t_arrow B C) -> B1 = B /\ B2 = C.
Proof. intros B1 B2 B C H. inversion H; subst; auto. Qed.

Lemma appDist_all_inv : forall (B1 B2 B C:typ),
  appDist (t_forall B1 B2) (t_forall B C) -> B1 = B /\ B2 = C.
Proof. intros B1 B2 B C H. inversion H; subst; auto. Qed.

Lemma appDist_rcd_inv : forall (l:label) (B1 B:typ),
  appDist (t_rcd l B1) (t_rcd l B) -> B1 = B.
Proof. intros l B1 B H. inversion H; subst; auto. Qed.

Lemma appDist_arrow_not_rcd : forall (A1 A2:typ) (l:label) (B:typ), appDist (t_arrow A1 A2) (t_rcd l B) -> False.
Proof. intros. inversion H. Qed.
Lemma appDist_arrow_not_all : forall (A1 A2:typ) (B1 B2:typ), appDist (t_arrow A1 A2) (t_forall B1 B2) -> False.
Proof. intros. inversion H. Qed.
Lemma appDist_rcd_not_arrow : forall (l:label) (A:typ) (B C:typ), appDist (t_rcd l A) (t_arrow B C) -> False.
Proof. intros. inversion H. Qed.
Lemma appDist_rcd_not_all : forall (l:label) (A:typ) (B1 B2:typ), appDist (t_rcd l A) (t_forall B1 B2) -> False.
Proof. intros. inversion H. Qed.
Lemma appDist_all_not_arrow : forall (A1 A2:typ) (B C:typ), appDist (t_forall A1 A2) (t_arrow B C) -> False.
Proof. intros. inversion H. Qed.
Lemma appDist_all_not_rcd : forall (A1 A2:typ) (l:label) (B:typ), appDist (t_forall A1 A2) (t_rcd l B) -> False.
Proof. intros. inversion H. Qed.
Lemma appDist_top_not_arrow : forall (B C:typ), appDist t_top (t_arrow B C) -> False.
Proof. intros. inversion H. Qed.
Lemma appDist_int_not_arrow : forall (B C:typ), appDist t_int (t_arrow B C) -> False.
Proof. intros. inversion H. Qed.
Lemma appDist_top_not_rcd : forall (l:label) (B:typ), appDist t_top (t_rcd l B) -> False.
Proof. intros. inversion H. Qed.
Lemma appDist_int_not_rcd : forall (l:label) (B:typ), appDist t_int (t_rcd l B) -> False.
Proof. intros. inversion H. Qed.
Lemma appDist_top_not_all : forall (B1 B2:typ), appDist t_top (t_forall B1 B2) -> False.
Proof. intros. inversion H. Qed.
Lemma appDist_int_not_all : forall (B1 B2:typ), appDist t_int (t_forall B1 B2) -> False.
Proof. intros. inversion H. Qed.

Lemma abs_chk_TWell_ann : forall A0 body Bann,
  Typing nil nil (e_abs A0 body) Chk Bann -> TWell nil A0.
Proof.
  intros A0 body Bann Hty. dependent induction Hty.
  - (* Typ_abs *)
    match goal with Hsub : algo_sub nil ?B1 A0 |- _ =>
      exact (algo_sub_TWell_target nil B1 A0 (TCW_empty) Hsub) end.
  - (* Typ_inter *)
    exact (IHHty2 A0 body (JMeq_refl _) (JMeq_refl _) eq_refl eq_refl).
  - (* Typ_sub *)
    exfalso.
    match goal with Hinf : Typing nil nil (e_abs _ _) Inf _ |- _ => inversion Hinf end.
Qed.

Lemma tabs_chk_appDist_arrow_false : forall (e:exp) (T:typ),
  Typing nil nil (e_tabs e) Chk T -> forall Bt Ct, appDist T (t_arrow Bt Ct) -> False.
Proof.
  intros e T Hty. dependent induction Hty; intros Bt Ct Happ.
  - (* Typ_tabs *) inversion Happ; subst; eapply appDist_all_not_arrow; eauto.
  - (* Typ_inter *) inversion Happ; subst.
    + (* andArrow *) eapply IHHty1; eauto.
  - (* Typ_sub *) exfalso.
    match goal with Hinf : Typing nil nil (e_tabs _) Inf _ |- _ => inversion Hinf end.
Qed.

Lemma rcd_chk_appDist_arrow_false : forall (l:label) (e:exp) (T:typ),
  Typing nil nil (e_rcd l e) Chk T -> forall Bt Ct, appDist T (t_arrow Bt Ct) -> False.
Proof.
  intros l e T Hty. dependent induction Hty; intros Bt Ct Happ.
  - (* Typ_rcd *) inversion Happ; subst; eapply appDist_rcd_not_arrow; eauto.
  - (* Typ_inter *) inversion Happ; subst.
    + (* andArrow *) eapply IHHty1; eauto.
  - (* Typ_sub *) exfalso.
    match goal with Hinf : Typing nil nil (e_rcd _ _) Inf _ |- _ => inversion Hinf end.
Qed.



Lemma papp_of_inf_value_arrow : forall (v:exp), value v ->
  forall A, Typing nil nil v Inf A -> forall Bt Ct e0,
  appDist A (t_arrow Bt Ct) -> Typing nil nil e0 Chk Bt ->
  exists e', papp v (arg_exp e0) e'.
Proof.
  intros v Hval. induction Hval; intros AT Hty Bt Ct e0 Happ Harg.
  - (* V_unit *) inversion Hty; subst. exfalso. eapply appDist_top_not_arrow; exact Happ.
  - (* V_lit *) inversion Hty; subst. exfalso. eapply appDist_int_not_arrow; exact Happ.
  - (* V_abs *) inversion Hty; subst.
    match goal with
    | H5 : Typing nil nil (e_abs ?A0 ?body) Chk ?Bann,
      Hlc : lc_exp (e_abs ?A0 ?body),
      Happ1 : appDist ?Bann (t_arrow ?Bt ?Ct)
      |- exists e', papp (e_anno (e_abs ?A0 ?body) ?Bann) (arg_exp ?e0) e' =>
        destruct (wrapping_exists A0 (abs_chk_TWell_ann A0 body Bann H5) e0
                    (typing_lc_exp _ _ e0 _ _ Harg)) as [e2' Hw];
        exists (e_anno (open_exp_wrt_exp body e2') Ct);
        eapply PApp_abs; [ exact Hlc | exact Happ1 | exact Hw ]
    end.
  - (* V_bareAbs *) inversion Hty.
  - (* V_tabs *) inversion Hty; subst. exfalso.
    exact (tabs_chk_appDist_arrow_false e AT H4 Bt Ct Happ).
  - (* V_bareTabs *) inversion Hty.
  - (* V_rcd *) inversion Hty; subst. exfalso.
    exact (rcd_chk_appDist_arrow_false l e AT H4 Bt Ct Happ).
  - (* V_bareRcd *) inversion Hty.
  - (* V_merge *) inversion Hty; subst.
    + match goal with
      | Hv1 : value ?u1, Hv2 : value ?u2,
        HT1 : Typing nil nil ?u1 Inf ?S1, HT2 : Typing nil nil ?u2 Inf ?S2,
        Happ1 : appDist (t_and ?S1 ?S2) (t_arrow ?Bt ?Ct)
        |- exists e', papp (e_merge ?u1 ?u2) (arg_exp ?e0) e' =>
          inversion Happ1; subst;
          match goal with
          | Hd1 : appDist ?Z1 (t_arrow ?B1 ?C1), Hd2 : appDist ?Z2 (t_arrow ?B2 ?C2),
            HTa : Typing nil nil ?uu1 Inf ?Z1, HTb : Typing nil nil ?uu2 Inf ?Z2
            |- exists e', papp (e_merge ?uu1 ?uu2) (arg_exp ?ee) e' =>
              let IH1 := match goal with H : forall A, Typing nil nil uu1 Inf A -> _ |- _ => constr:(H) end in
              let IH2 := match goal with H : forall A, Typing nil nil uu2 Inf A -> _ |- _ => constr:(H) end in
              destruct (IH1 Z1 HTa B1 C1 ee Hd1 (chk_and_l nil nil ee B1 B2 Harg)) as [e1' Hp1];
              destruct (IH2 Z2 HTb B2 C2 ee Hd2 (chk_and_r nil nil ee B1 B2 Harg)) as [e2' Hp2];
              exists (e_merge e1' e2'); apply PApp_merge; auto
          end
      end.
    + match goal with
      | Hv1 : value ?u1, Hv2 : value ?u2,
        HT1 : Typing nil nil ?u1 Inf ?S1, HT2 : Typing nil nil ?u2 Inf ?S2,
        Happ1 : appDist (t_and ?S1 ?S2) (t_arrow ?Bt ?Ct)
        |- exists e', papp (e_merge ?u1 ?u2) (arg_exp ?e0) e' =>
          inversion Happ1; subst;
          match goal with
          | Hd1 : appDist ?Z1 (t_arrow ?B1 ?C1), Hd2 : appDist ?Z2 (t_arrow ?B2 ?C2),
            HTa : Typing nil nil ?uu1 Inf ?Z1, HTb : Typing nil nil ?uu2 Inf ?Z2
            |- exists e', papp (e_merge ?uu1 ?uu2) (arg_exp ?ee) e' =>
              let IH1 := match goal with H : forall A, Typing nil nil uu1 Inf A -> _ |- _ => constr:(H) end in
              let IH2 := match goal with H : forall A, Typing nil nil uu2 Inf A -> _ |- _ => constr:(H) end in
              destruct (IH1 Z1 HTa B1 C1 ee Hd1 (chk_and_l nil nil ee B1 B2 Harg)) as [e1' Hp1];
              destruct (IH2 Z2 HTb B2 C2 ee Hd2 (chk_and_r nil nil ee B1 B2 Harg)) as [e2' Hp2];
              exists (e_merge e1' e2'); apply PApp_merge; auto
          end
      end.
Qed.


Lemma abs_chk_appDist_rcd_false : forall (A0:typ) (body:exp) (T:typ),
  Typing nil nil (e_abs A0 body) Chk T ->
  forall l C, appDist T (t_rcd l C) -> False.
Proof.
  intros A0 body T Hty. dependent induction Hty; intros l C Happ.
  - inversion Happ; subst; eapply appDist_arrow_not_rcd; eauto.
  - inversion Happ; subst. eapply IHHty1; eauto.
  - exfalso. match goal with Hinf : Typing nil nil _ Inf _ |- _ => inversion Hinf; subst; try discriminate end.
Qed.

Lemma tabs_chk_appDist_rcd_false : forall (e:exp) (T:typ),
  Typing nil nil (e_tabs e) Chk T ->
  forall l C, appDist T (t_rcd l C) -> False.
Proof.
  intros e T Hty. dependent induction Hty; intros l C Happ.
  - inversion Happ; subst; eapply appDist_all_not_rcd; eauto.
  - inversion Happ; subst. eapply IHHty1; eauto.
  - exfalso. match goal with Hinf : Typing nil nil _ Inf _ |- _ => inversion Hinf; subst; try discriminate end.
Qed.

Lemma rcd_chk_appDist_rcd_label : forall (l0:label) (e:exp) (T:typ),
  Typing nil nil (e_rcd l0 e) Chk T ->
  forall l C, appDist T (t_rcd l C) -> l = l0.
Proof.
  intros l0 e T Hty. dependent induction Hty; intros l C Happ.
  - inversion Happ; subst; auto.
  - inversion Happ; subst. eapply IHHty1; eauto.
  - exfalso. match goal with Hinf : Typing nil nil _ Inf _ |- _ => inversion Hinf; subst; try discriminate end.
Qed.

Lemma papp_of_inf_value_rcd : forall (v:exp), value v ->
  forall A, Typing nil nil v Inf A -> forall (l:label) (C:typ),
  appDist A (t_rcd l C) -> exists e', papp v (arg_la l) e'.
Proof.
  intros v Hval. induction Hval; intros AT Hty lb CT Happ.
  - inversion Hty; subst. exfalso. eapply appDist_top_not_rcd; exact Happ.
  - inversion Hty; subst. exfalso. eapply appDist_int_not_rcd; exact Happ.
  - (* V_abs *) inversion Hty; subst. exfalso.
    match goal with Hchk : Typing nil nil (e_abs ?A0 ?bd) Chk ?TT |- _ =>
      exact (abs_chk_appDist_rcd_false A0 bd TT Hchk lb CT Happ) end.
  - inversion Hty.
  - (* V_tabs *) inversion Hty; subst. exfalso.
    match goal with Hchk : Typing nil nil (e_tabs ?ee) Chk ?TT |- _ =>
      exact (tabs_chk_appDist_rcd_false ee TT Hchk lb CT Happ) end.
  - inversion Hty.
  - (* V_rcd *) inversion Hty; subst.
    match goal with
    | Hchk : Typing nil nil (e_rcd ?ll ?ee) Chk ?TT, Hlc : lc_exp ?ee |- _ =>
        pose proof (rcd_chk_appDist_rcd_label ll ee TT Hchk lb CT Happ) as Heq;
        subst ll;
        exists (e_anno ee CT);
        eapply PApp_proj; [ exact Hlc | exact Happ ]
    end.
  - inversion Hty.
  - (* V_merge *) inversion Hty; subst.
    + match goal with
      | Hv1 : value ?u1, Hv2 : value ?u2,
        HT1 : Typing nil nil ?u1 Inf ?S1, HT2 : Typing nil nil ?u2 Inf ?S2,
        Happ1 : appDist (t_and ?S1 ?S2) (t_rcd ?lb ?CT)
        |- exists e', papp (e_merge ?u1 ?u2) (arg_la ?lb) e' =>
          inversion Happ1; subst;
          match goal with
          | Hd1 : appDist ?Z1 (t_rcd ?lb ?C1), Hd2 : appDist ?Z2 (t_rcd ?lb ?C2),
            HTa : Typing nil nil ?uu1 Inf ?Z1, HTb : Typing nil nil ?uu2 Inf ?Z2
            |- exists e', papp (e_merge ?uu1 ?uu2) (arg_la ?lb) e' =>
              let IH1 := match goal with H : forall A, Typing nil nil uu1 Inf A -> forall (l:label) (C:typ), appDist A (t_rcd l C) -> exists e', papp uu1 (arg_la l) e' |- _ => constr:(H) end in
              let IH2 := match goal with H : forall A, Typing nil nil uu2 Inf A -> forall (l:label) (C:typ), appDist A (t_rcd l C) -> exists e', papp uu2 (arg_la l) e' |- _ => constr:(H) end in
              destruct (IH1 Z1 HTa lb C1 Hd1) as [e1' Hp1];
              destruct (IH2 Z2 HTb lb C2 Hd2) as [e2' Hp2];
              exists (e_merge e1' e2'); apply PApp_merge; auto
          end
      end.
    + match goal with
      | Hv1 : value ?u1, Hv2 : value ?u2,
        HT1 : Typing nil nil ?u1 Inf ?S1, HT2 : Typing nil nil ?u2 Inf ?S2,
        Happ1 : appDist (t_and ?S1 ?S2) (t_rcd ?lb ?CT)
        |- exists e', papp (e_merge ?u1 ?u2) (arg_la ?lb) e' =>
          inversion Happ1; subst;
          match goal with
          | Hd1 : appDist ?Z1 (t_rcd ?lb ?C1), Hd2 : appDist ?Z2 (t_rcd ?lb ?C2),
            HTa : Typing nil nil ?uu1 Inf ?Z1, HTb : Typing nil nil ?uu2 Inf ?Z2
            |- exists e', papp (e_merge ?uu1 ?uu2) (arg_la ?lb) e' =>
              let IH1 := match goal with H : forall A, Typing nil nil uu1 Inf A -> forall (l:label) (C:typ), appDist A (t_rcd l C) -> exists e', papp uu1 (arg_la l) e' |- _ => constr:(H) end in
              let IH2 := match goal with H : forall A, Typing nil nil uu2 Inf A -> forall (l:label) (C:typ), appDist A (t_rcd l C) -> exists e', papp uu2 (arg_la l) e' |- _ => constr:(H) end in
              destruct (IH1 Z1 HTa lb C1 Hd1) as [e1' Hp1];
              destruct (IH2 Z2 HTb lb C2 Hd2) as [e2' Hp2];
              exists (e_merge e1' e2'); apply PApp_merge; auto
          end
      end.
Qed.

