Lemma papp_of_inf_value_all : forall (v:exp), value v ->
  forall A, Typing nil nil v Inf A -> forall C1 C2 (T:typ),
  appDist A (t_forall C1 C2) -> lc_typ T -> exists e', papp v (arg_typ T) e'.
Proof.
  intros v Hval. induction Hval; intros AT Hty C1 C2 TT Happ HlcT.
  - inversion Hty; subst. exfalso. eapply appDist_top_not_all; exact Happ.
  - inversion Hty; subst. exfalso. eapply appDist_int_not_all; exact Happ.
  - (* V_abs *) inversion Hty; subst. exfalso.
    match goal with Hchk : Typing nil nil (e_abs ?A0 ?bd) Chk ?TT |- _ =>
      exact (abs_chk_appDist_all_false A0 bd TT Hchk C1 C2 Happ) end.
  - inversion Hty.
  - (* V_tabs *) inversion Hty; subst.
    match goal with
    | Hchk : Typing nil nil (e_tabs ?ee) Chk ?T, Hlc : lc_exp (e_tabs ?ee)
      |- exists e', papp (e_anno (e_tabs ?ee) ?T) (arg_typ TT) e' =>
        exists (e_anno (open_exp_wrt_typ ee TT) (open_typ_wrt_typ C2 TT));
        eapply PApp_tabs; [ exact Hlc | exact HlcT | exact Happ ]
    end.
  - inversion Hty.
  - (* V_rcd *) inversion Hty; subst. exfalso.
    match goal with Hchk : Typing nil nil (e_rcd ?ll ?bd) Chk ?TT |- _ =>
      exact (rcd_chk_appDist_all_false ll bd TT Hchk C1 C2 Happ) end.
  - inversion Hty.
  - (* V_merge *) inversion Hty; subst.
    + match goal with
      | Hv1 : value ?u1, Hv2 : value ?u2,
        HT1 : Typing nil nil ?u1 Inf ?S1, HT2 : Typing nil nil ?u2 Inf ?S2,
        Happ1 : appDist (t_and ?S1 ?S2) (t_forall ?C1 ?C2)
        |- exists e', papp (e_merge ?u1 ?u2) (arg_typ TT) e' =>
          inversion Happ1; subst;
          match goal with
          | Hd1 : appDist ?Z1 (t_forall ?B1 ?B2), Hd2 : appDist ?Z2 (t_forall ?B3 ?B4),
            HTa : Typing nil nil ?uu1 Inf ?Z1, HTb : Typing nil nil ?uu2 Inf ?Z2
            |- exists e', papp (e_merge ?uu1 ?uu2) (arg_typ TT) e' =>
              let IH1 := match goal with H : forall A, Typing nil nil uu1 Inf A -> forall C1 C2 T, appDist A (t_forall C1 C2) -> lc_typ T -> exists e', papp uu1 (arg_typ T) e' |- _ => constr:(H) end in
              let IH2 := match goal with H : forall A, Typing nil nil uu2 Inf A -> forall C1 C2 T, appDist A (t_forall C1 C2) -> lc_typ T -> exists e', papp uu2 (arg_typ T) e' |- _ => constr:(H) end in
              destruct (IH1 Z1 HTa B1 B2 TT Hd1 HlcT) as [e1' Hp1];
              destruct (IH2 Z2 HTb B3 B4 TT Hd2 HlcT) as [e2' Hp2];
              exists (e_merge e1' e2'); apply PApp_merge; auto
          end
      end.
    + match goal with
      | Hv1 : value ?u1, Hv2 : value ?u2,
        HT1 : Typing nil nil ?u1 Inf ?S1, HT2 : Typing nil nil ?u2 Inf ?S2,
        Happ1 : appDist (t_and ?S1 ?S2) (t_forall ?C1 ?C2)
        |- exists e', papp (e_merge ?u1 ?u2) (arg_typ TT) e' =>
          inversion Happ1; subst;
          match goal with
          | Hd1 : appDist ?Z1 (t_forall ?B1 ?B2), Hd2 : appDist ?Z2 (t_forall ?B3 ?B4),
            HTa : Typing nil nil ?uu1 Inf ?Z1, HTb : Typing nil nil ?uu2 Inf ?Z2
            |- exists e', papp (e_merge ?uu1 ?uu2) (arg_typ TT) e' =>
              let IH1 := match goal with H : forall A, Typing nil nil uu1 Inf A -> forall C1 C2 T, appDist A (t_forall C1 C2) -> lc_typ T -> exists e', papp uu1 (arg_typ T) e' |- _ => constr:(H) end in
              let IH2 := match goal with H : forall A, Typing nil nil uu2 Inf A -> forall C1 C2 T, appDist A (t_forall C1 C2) -> lc_typ T -> exists e', papp uu2 (arg_typ T) e' |- _ => constr:(H) end in
              destruct (IH1 Z1 HTa B1 B2 TT Hd1 HlcT) as [e1' Hp1];
              destruct (IH2 Z2 HTb B3 B4 TT Hd2 HlcT) as [e2' Hp2];
              exists (e_merge e1' e2'); apply PApp_merge; auto
          end
      end.
Qed.

Lemma typing_progress : forall G e d A, Typing nil G e d A ->
  G = nil -> value e \/ exists e', step e e'.
Proof.
  intros G e d A Hty. dependent induction Hty.
  all: try intros HG.
  all: try (match goal with Heq : ?GG = nil |- _ => subst GG end).
  - (* Typ_top *) left. apply V_unit.
  - (* Typ_lit *) left. apply V_lit.
  - (* Typ_var *) exfalso.
    match goal with H : binds _ _ nil |- _ => apply binds_nil_false in H; auto end.
  - (* Typ_abs *) left. apply V_bareAbs.
    + apply (proj2 (algo_sub_lc nil B1 A H)).
    + apply typing_lc_exp with (D:=nil) (G:=nil) (d:=Chk) (A:=t_arrow B1 B2).
      eapply Typ_abs; eauto.
  - (* Typ_app *)
    match goal with
    | IH1 : [] ~= [] -> [] = [] -> value ?u1 \/ (exists e', step ?u1 e'),
      Hd : appDist ?Av (t_arrow ?Bv ?Cv),
      HT2 : Typing [] [] ?u2 Chk ?Bv,
      Hinf : Typing [] [] ?u1 Inf ?Av
      |- value (e_app ?u1 ?u2) \/ _ =>
        destruct (IH1 (JMeq_refl _) eq_refl) as [ Hv | [ e1' Hs ] ]
        ; [ right; destruct (papp_of_inf_value_arrow u1 Hv Av Hinf Bv Cv u2 Hd HT2) as [ e' Hp ];
            exists e'; eapply Step_papp; eauto
          | right; exists (e_app e1' u2); eapply Step_appl;
            [ exact (typing_lc_exp nil nil u2 Chk Bv HT2) | exact Hs ] ]
    end.
  - (* Typ_tabs *) left. apply V_bareTabs.
    apply typing_lc_exp with (D:=nil) (G:=nil) (d:=Chk) (A:=t_forall A B).
    eapply Typ_tabs; eauto.
  - (* Typ_tapp *)
    let IH := match goal with H : [] ~= [] -> [] = [] -> value ?u \/ (exists e' : exp, step ?u e') |- _ => constr:(H) end in
    match goal with
    | Hinf : Typing [] [] ?u Inf ?B0, Hd : appDist ?B0 (t_forall ?C1 ?C2),
      Hdis : disjoint [] ?A0 ?C1 |- _ =>
        destruct (IH (JMeq_refl _) eq_refl) as [ Hv | [ e1' Hs ] ]
        ; [ right; destruct (papp_of_inf_value_all u Hv B0 Hinf C1 C2 A0 Hd
                              (proj1 (disjoint_lc nil A0 C1 Hdis))) as [ e' Hp ];
            exists e'; eapply Step_ptapp; eauto
          | right; exists (e_tapp e1' A0); eapply Step_tapp; eauto;
            apply (proj1 (disjoint_lc nil A0 C1 Hdis)) ]
    end.
  - (* Typ_proj *)
    let IH := match goal with H : [] ~= [] -> [] = [] -> value ?u \/ (exists e' : exp, step ?u e') |- _ => constr:(H) end in
    match goal with
    | Hinf : Typing [] [] ?u Inf ?B0, Hd : appDist ?B0 (t_rcd ?ll ?CC) |- _ =>
        destruct (IH (JMeq_refl _) eq_refl) as [ Hv | [ e1' Hs ] ]
        ; [ right; destruct (papp_of_inf_value_rcd u Hv B0 Hinf ll CC Hd) as [ e' Hp ];
            exists e'; eapply Step_pproj; eauto
          | right; exists (e_proj e1' ll); eapply Step_proj; eauto ]
    end.
  - (* Typ_rcd *) left. apply V_bareRcd.
    apply typing_lc_exp with (D:=nil) (G:=nil) (d:=Chk) (A:=A).
    exact Hty.
  - (* Typ_merge *)
    match goal with
    | IH1 : [] ~= [] -> [] = [] -> value ?u1 \/ (exists e', step ?u1 e'),
      IH2 : [] ~= [] -> [] = [] -> value ?u2 \/ (exists e', step ?u2 e')
      |- value (e_merge ?u1 ?u2) \/ _ =>
        destruct (IH1 (JMeq_refl _) eq_refl) as [ Hv1 | [ e1' Hs1 ] ];
        destruct (IH2 (JMeq_refl _) eq_refl) as [ Hv2 | [ e2' Hs2 ] ];
        [ left; apply V_merge; assumption
        | right; exists (e_merge u1 e2'); eapply Step_merger; eauto
        | right; exists (e_merge e1' u2); eapply Step_mergel; eauto
        | right; exists (e_merge e1' e2'); eapply Step_merge; eauto ]
    end.
  - (* Typ_inter *)
    match goal with
    | IH1 : [] ~= [] -> [] = [] -> value ?u \/ (exists e', step ?u e')
      |- value ?u \/ _ => exact (IH1 (JMeq_refl _) eq_refl)
    end.
  - (* Typ_anno *)
    match goal with
    | |- value (e_anno ?u ?Av) \/ _ =>
        let IH := match goal with H : [] ~= [] -> [] = [] -> value u \/ (exists e', step u e') |- _ => constr:(H) end in
        let HT := match goal with H : Typing [] [] u Chk Av |- _ => constr:(H) end in
        destruct (IH (JMeq_refl _) eq_refl) as [ Hv | [ e' Hs ] ];
        [ destruct (chk_value_behavior u Hv Av HT)
            as [ [ A0 [ b Heq ] ] | [ [ b Heq ] | [ [ l [ b Heq ] ] | [ Hpv [ v' Hcast ] ] ] ] ]
          ; [ left; subst u; apply V_abs;
              [ apply (TWell_lc_typ nil A0 (abs_chk_TWell_ann A0 b Av HT))
              | exact (typing_lc_exp nil nil (e_abs A0 b) Chk Av HT)
              | exact (typing_lc_typ nil nil (e_abs A0 b) Chk Av HT) ]
            | left; subst u; apply V_tabs;
              [ exact (typing_lc_exp nil nil (e_tabs b) Chk Av HT)
              | exact (typing_lc_typ nil nil (e_tabs b) Chk Av HT) ]
            | left; subst u; apply V_rcd;
              [ exact (match typing_lc_exp nil nil (e_rcd l b) Chk Av HT with Hlc => ltac:(inversion Hlc; assumption) end)
              | exact (typing_lc_typ nil nil (e_rcd l b) Chk Av HT) ]
            | right; exists v'; eapply Step_annov; eauto ]
        | right; exists (e_anno e' Av); eapply Step_anno; eauto;
          exact (typing_lc_typ nil nil u Chk Av HT) ]
    end.
  - (* Typ_fix *) right. exists (e_anno (open_exp_wrt_exp e (e_fixpoint A e)) A).
    eapply Step_fix.
    + apply typing_lc_exp with (D:=nil) (G:=nil) (d:=Inf) (A:=A). eapply Typ_fix; eauto.
    + apply typing_lc_typ with (D:=nil) (G:=nil) (e:=e_fixpoint A e) (d:=Inf) (A:=A). eapply Typ_fix; eauto.
  - (* Typ_mergev *)
    match goal with
    | IH1 : [] ~= [] -> [] = [] -> value ?u1 \/ (exists e', step ?u1 e'),
      IH2 : [] ~= [] -> [] = [] -> value ?u2 \/ (exists e', step ?u2 e')
      |- value (e_merge ?u1 ?u2) \/ _ =>
        destruct (IH1 (JMeq_refl _) eq_refl) as [ Hv1 | [ e1' Hs1 ] ];
        destruct (IH2 (JMeq_refl _) eq_refl) as [ Hv2 | [ e2' Hs2 ] ];
        [ left; apply V_merge; assumption
        | right; exists (e_merge u1 e2'); eapply Step_merger; eauto
        | right; exists (e_merge e1' u2); eapply Step_mergel; eauto
        | right; exists (e_merge e1' e2'); eapply Step_merge; eauto ]
    end.
  - (* Typ_sub *)
    match goal with
    | IH : [] ~= [] -> [] = [] -> value ?u \/ (exists e', step ?u e')
      |- value ?u \/ _ => exact (IH (JMeq_refl _) eq_refl)
    end.
Qed.
End progress_final.
Import progress_final.

Module agentE2.
Import ListNotations.

(* ================================================================== *)
(* Merge / consistency metatheory for subject reduction of Typ_mergev *)
(*                                                                     *)
(* This file contains:                                                 *)
(*   - counterexamples showing the naive preservation statements false *)
(*   - the correct value-indexed consistency preservation lemmas       *)
(*   - a merge preservation helper in the form usable for Typ_mergev   *)
(*                                                                     *)
(* Missing compiled API is kept as Section Variables; no axioms.       *)
(* ================================================================== *)

(* ------------------------------------------------------------------ *)
(* 0. Small consequences of [pType] and [consistent].                  *)
(* ------------------------------------------------------------------ *)

Lemma pType_prevalue : forall e A, pType e A -> prevalue e.
Proof.
  intros e A H. induction H.
  - apply PV_top.
  - apply PV_int.
  - apply PV_anno; assumption.
  - apply PV_merge; assumption.
Qed.

Lemma pType_lc_exp : forall e A, pType e A -> lc_exp e.
Proof.
  intros e A H. induction H.
  - apply lc_e_top.
  - apply lc_e_lit.
  - apply lc_e_anno; assumption.
  - apply lc_e_merge; assumption.
Qed.

Lemma pType_lc_typ : forall e A, pType e A -> lc_typ A.
Proof.
  intros e A H. induction H.
  - apply lc_t_top.
  - apply lc_t_int.
  - assumption.
  - apply lc_t_and; assumption.
Qed.

Lemma consistent_prevalue_l : forall u1 u2, consistent u1 u2 -> prevalue u1.
Proof.
  intros u1 u2 H. induction H.
  - apply PV_int.
  - apply PV_anno; assumption.
  - assumption.
  - apply PV_merge; assumption.
  - assumption.
Qed.

Lemma consistent_prevalue_r : forall u1 u2, consistent u1 u2 -> prevalue u2.
Proof.
  intros u1 u2 H. induction H.
  - apply PV_int.
  - apply PV_anno; assumption.
  - assumption.
  - assumption.
  - apply PV_merge; assumption.
Qed.

Lemma pType_anno_inv : forall e A B, pType (e_anno e A) B -> B = A.
Proof.
  intros e A B H. inversion H; subst; reflexivity.
Qed.

Lemma pType_lit_inv : forall i A, pType (e_lit i) A -> A = t_int.
Proof.
  intros i A H. inversion H; subst; reflexivity.
Qed.

Lemma pType_top_inv : forall A, pType e_top A -> A = t_top.
Proof.
  intros A H. inversion H; subst; reflexivity.
Qed.

Lemma pType_merge_inv : forall u1 u2 A,
  pType (e_merge u1 u2) A ->
  exists A1 A2, A = t_and A1 A2 /\ pType u1 A1 /\ pType u2 A2.
Proof.
  intros u1 u2 A H. inversion H; subst.
  exists A0, B. repeat split; assumption.
Qed.

Lemma topLike_int_false : forall D, ~ topLike D t_int.
Proof.
  intros D H. inversion H.
Qed.

Lemma disjoint_int_int_false : forall D, ~ disjoint D t_int t_int.
Proof.
  intros D H. dependent destruction H.
  - inversion H2.
  - exact (topLike_int_false D H0).
  - exact (topLike_int_false D H0).
  - inversion H.
  - inversion H.
Qed.

Lemma typing_lit_inf_inv : forall G i A,
  Typing nil G (e_lit i) Inf A -> A = t_int.
Proof.
  intros G i A H. inversion H; subst; reflexivity.
Qed.

Lemma typing_anno_int_inf_inv : forall G e A,
  Typing nil G (e_anno e t_int) Inf A -> A = t_int.
Proof.
  intros G e A H. inversion H; subst; reflexivity.
Qed.

Lemma typing_merge_inf_inv : forall u1 u2 A,
  Typing nil nil (e_merge u1 u2) Inf A ->
  exists A1 A2, A = t_and A1 A2 /\
               Typing nil nil u1 Inf A1 /\ Typing nil nil u2 Inf A2.
Proof.
  intros u1 u2 A H. inversion H; subst.
  - exists A0, B. repeat split; assumption.
  - exists A0, B. repeat split; assumption.
Qed.

Lemma consistent_lit_anno_int_false : forall i e,
  ~ consistent (e_lit i) (e_anno e t_int).
Proof.
  intros i e H. inversion H; subst.
  apply pType_lit_inv in H0. subst A.
  apply pType_anno_inv in H1. subst B.
  exact (disjoint_int_int_false nil H2).
Qed.

Lemma typing_merge_lit_anno_int_false : forall C,
  ~ Typing nil nil (e_merge (e_lit 0) (e_anno (e_lit 0) t_int)) Inf C.
Proof.
  intros C H. inversion H; subst.
  - apply typing_lit_inf_inv in H2. subst A.
    apply typing_anno_int_inf_inv in H5. subst B.
    exact (disjoint_int_int_false nil H6).
  - apply typing_lit_inf_inv in H5. subst A.
    apply typing_anno_int_inf_inv in H8. subst B.
    exact (consistent_lit_anno_int_false 0 (e_lit 0) H9).
Qed.

(* ------------------------------------------------------------------ *)
(* 1. Concrete counterexamples.                                        *)
(* ------------------------------------------------------------------ *)

Lemma typing_anno_lit_int : forall i,
  Typing nil nil (e_anno (e_lit i) t_int) Inf t_int.
Proof.
  intros i. apply Typ_anno.
  eapply Typ_sub.
  - apply Typ_lit; [ apply TCW_empty | apply CW_empty | apply (@uniq_nil typ) ].
  - apply S_int. apply TCW_empty.
Qed.

Lemma step_anno_lit_int : forall i,
  step (e_anno (e_lit i) t_int) (e_lit i).
Proof.
  intros i. eapply Step_annov.
  - apply V_lit.
  - apply PV_int.
  - apply Cast_int.
Qed.

Lemma consistent_anno_int_self : forall i,
  consistent (e_anno (e_lit i) t_int) (e_anno (e_lit i) t_int).
Proof.
  intros i. apply C_anno; [apply lc_t_int | apply lc_e_lit | apply lc_t_int].
Qed.

Theorem consistent_step_l_unrestricted_false :
  ~ (forall u1 u2 u1' A B,
       Typing nil nil u1 Inf A ->
       Typing nil nil u2 Inf B ->
       consistent u1 u2 ->
       step u1 u1' ->
       consistent u1' u2).
Proof.
  intros H.
  pose proof (H (e_anno (e_lit 0) t_int)
                 (e_anno (e_lit 0) t_int)
                 (e_lit 0) t_int t_int
                 (typing_anno_lit_int 0)
                 (typing_anno_lit_int 0)
                 (consistent_anno_int_self 0)
                 (step_anno_lit_int 0)) as Hbad.
  exact (consistent_lit_anno_int_false 0 (e_lit 0) Hbad).
Qed.

Theorem consistency_disjoint_unrestricted_false :
  ~ (forall u1 u2 A B,
       Typing nil nil u1 Inf A ->
       Typing nil nil u2 Inf B ->
       consistent u1 u2 ->
       disjoint nil A B).
Proof.
  intros H.
  pose proof (H (e_anno (e_lit 0) t_int)
                 (e_anno (e_lit 0) t_int)
                 t_int t_int
                 (typing_anno_lit_int 0)
                 (typing_anno_lit_int 0)
                 (consistent_anno_int_self 0)) as Hbad.
  exact (disjoint_int_int_false nil Hbad).
Qed.

Theorem merge_pres_helper_unrestricted_false :
  ~ (forall u1 u2 A B,
       Typing nil nil u1 Inf A ->
       Typing nil nil u2 Inf B ->
       consistent u1 u2 ->
       forall u1' u2',
         (step u1 u1' \/ u1' = u1) ->
         (step u2 u2' \/ u2' = u2) ->
         ~ (u1' = u1 /\ u2' = u2) ->
         exists C,
           Typing nil nil (e_merge u1' u2') Inf C /\ subsub C (t_and A B)).
Proof.
  intros H.
  pose proof (H (e_anno (e_lit 0) t_int)
                 (e_anno (e_lit 0) t_int)
                 t_int t_int
                 (typing_anno_lit_int 0)
                 (typing_anno_lit_int 0)
                 (consistent_anno_int_self 0)
                 (e_lit 0)
                 (e_anno (e_lit 0) t_int)
                 (or_introl (step_anno_lit_int 0))
                 (or_intror eq_refl)) as Hbad.
  assert (Hnot : ~ (e_lit 0 = e_anno (e_lit 0) t_int /\
                    e_anno (e_lit 0) t_int =
                    e_anno (e_lit 0) t_int)).
  { intros Hboth. destruct Hboth as [Heq _]. discriminate Heq. }
  pose proof (Hbad Hnot) as Hex.
  destruct Hex as [C HC]. destruct HC as [Hty Hsub].
  exact (typing_merge_lit_anno_int_false C Hty).
Qed.

(* ------------------------------------------------------------------ *)
(* 2. Casting and pType: pType is preserved up to [subsub].            *)
(* ------------------------------------------------------------------ *)

Lemma lc_exp_abs_top_top : lc_exp (e_abs t_top e_top).
Proof.
  apply lc_e_abs.
  - apply lc_t_top.
  - intros x. apply lc_e_top.
Qed.

Lemma lc_exp_tabs_top : lc_exp (e_tabs e_top).
Proof.
  apply lc_e_tabs. intros X. apply lc_e_top.
Qed.

Lemma casting_pType_subsub : forall v A v',
  casting v A v' -> exists A', pType v' A' /\ subsub A' A.
Proof.
  intros v A v' H. induction H.
  - (* Cast_int *)
    exists t_int. split; [ apply PT_int | apply IS_refl; apply lc_t_int ].
  - (* Cast_top *)
    exists t_top. split; [ apply PT_top | apply IS_refl; apply lc_t_top ].
  - (* Cast_topArrow *)
    exists (t_arrow A1 A2). split.
    + apply PT_anno.
      * apply lc_exp_abs_top_top.
      * apply ord_lc_typ; assumption.
    + apply IS_refl. apply ord_lc_typ; assumption.
  - (* Cast_topAll *)
    exists (t_forall A1 A2). split.
    + apply PT_anno.
      * apply lc_exp_tabs_top.
      * apply ord_lc_typ; assumption.
    + apply IS_refl. apply ord_lc_typ; assumption.
  - (* Cast_topRcd *)
    exists (t_rcd l A). split.
    + apply PT_anno.
      * apply lc_e_rcd. apply lc_e_top.
      * apply ord_lc_typ; assumption.
    + apply IS_refl. apply ord_lc_typ; assumption.
  - (* Cast_anno *)
    exists B. split.
    + apply PT_anno; [ assumption | apply ord_lc_typ; assumption ].
    + apply IS_refl. apply ord_lc_typ; assumption.
  - (* Cast_mergel *)
    destruct IHcasting as [A' HA']. destruct HA' as [Hp Hs].
    exists A'. split; assumption.
  - (* Cast_merger *)
    destruct IHcasting as [A' HA']. destruct HA' as [Hp Hs].
    exists A'. split; assumption.
  - (* Cast_and *)
    destruct IHcasting1 as [B' HB']. destruct HB' as [HpB HsB].
    destruct IHcasting2 as [C' HC']. destruct HC' as [HpC HsC].
    exists (t_and B' C'). split.
    + apply PT_merge; assumption.
    + eapply IS_and; [ exact H | exact HsB | exact HsC ].
Qed.

(* ------------------------------------------------------------------ *)
(* 3. Restricted consistency preservation.                             *)
(*                                                                     *)
(* [step_lc_exp] is the only generic step API not yet available.       *)
(* The disjoint/subsub facts are the ones already proved in agentI.v,  *)
(* which cannot be imported because its compiled interface was built   *)
(* against an older agentE.vo.                                         *)
(* ------------------------------------------------------------------ *)

Section RestrictedStepPreservation.

Variable step_lc_exp : forall e e',
  lc_exp e -> step e e' -> lc_exp e'.

Variable disjoint_subsub_l : forall D A A' B,
  disjoint D A B -> subsub A' A -> disjoint D A' B.
Variable disjoint_subsub_r : forall D A B B',
  disjoint D A B -> subsub B' B -> disjoint D A B'.

(* Inf-typing preservation for one step.  This is the generic          *)
(* subject-reduction fact for [Inf] (pres_agent's [PresRes]); it is     *)
(* not available as a compiled library lemma here.                      *)
Variable pres_inf : forall u A u',
  Typing nil nil u Inf A ->
  step u u' ->
  exists A', Typing nil nil u' Inf A' /\ subsub A' A.

Lemma pType_step_subsub : forall u A u',
  pType u A -> step u u' -> exists A', pType u' A' /\ subsub A' A.
Proof.
  intros u A u' Hp Hs. revert A Hp.
  induction Hs; intros A0 Hp.
  - (* Step_papp *) inversion Hp.
  - (* Step_pproj *) inversion Hp.
  - (* Step_ptapp *) inversion Hp.
  - (* Step_annov *)
    apply pType_anno_inv in Hp. subst A0.
    apply casting_pType_subsub in H1. exact H1.
  - (* Step_appl *) inversion Hp.
  - (* Step_merge *)
    apply pType_merge_inv in Hp.
    destruct Hp as [A1 HA1]. destruct HA1 as [A2 HA2].
    destruct HA2 as [Heq HA12]. destruct HA12 as [Hp1 Hp2]. subst A0.
    destruct (IHHs1 A1 Hp1) as [A1' HA1'].
    destruct HA1' as [Hp1' Hsub1].
    destruct (IHHs2 A2 Hp2) as [A2' HA2'].
    destruct HA2' as [Hp2' Hsub2].
    exists (t_and A1' A2'). split.
    + apply PT_merge; assumption.
    + apply IS_and with (B := t_and A1 A2) (B1 := A1) (B2 := A2).
      * apply Sp_and; [ eapply pType_lc_typ; eassumption | eapply pType_lc_typ; eassumption ].
      * exact Hsub1.
      * exact Hsub2.
  - (* Step_mergel *)
    apply pType_merge_inv in Hp.
    destruct Hp as [A1 HA1]. destruct HA1 as [A2 HA2].
    destruct HA2 as [Heq HA12]. destruct HA12 as [Hp1 Hp2]. subst A0.
    destruct (IHHs A1 Hp1) as [A1' HA1'].
    destruct HA1' as [Hp1' Hsub1].
    exists (t_and A1' A2). split.
    + apply PT_merge; [ exact Hp1' | exact Hp2 ].
    + apply IS_and with (B := t_and A1 A2) (B1 := A1) (B2 := A2).
      * apply Sp_and; [ eapply pType_lc_typ; eassumption | eapply pType_lc_typ; eassumption ].
      * exact Hsub1.
      * apply IS_refl. eapply pType_lc_typ; eassumption.
  - (* Step_merger *)
    apply pType_merge_inv in Hp.
    destruct Hp as [A1 HA1]. destruct HA1 as [A2 HA2].
    destruct HA2 as [Heq HA12]. destruct HA12 as [Hp1 Hp2]. subst A0.
    destruct (IHHs A2 Hp2) as [A2' HA2'].
    destruct HA2' as [Hp2' Hsub2].
    exists (t_and A1 A2'). split.
    + apply PT_merge; [ exact Hp1 | exact Hp2' ].
    + apply IS_and with (B := t_and A1 A2) (B1 := A1) (B2 := A2).
      * apply Sp_and; [ eapply pType_lc_typ; eassumption | eapply pType_lc_typ; eassumption ].
      * apply IS_refl. eapply pType_lc_typ; eassumption.
      * exact Hsub2.
  - (* Step_anno *)
    pose proof Hp as Hp0.
    apply pType_anno_inv in Hp. subst A0.
    apply pType_lc_exp in Hp0. inversion Hp0; subst.
    exists A. split.
    + apply PT_anno.
      * apply step_lc_exp with (e := e); assumption.
      * assumption.
    + apply IS_refl; assumption.
  - (* Step_fix *) inversion Hp.
  - (* Step_proj *) inversion Hp.
  - (* Step_tapp *) inversion Hp.
Qed.

Lemma value_anno_inner_prevalue_false : forall (e:exp) (A B:typ),
  value (e_anno e B) -> prevalue e -> False.
Proof.
  intros e A B Hv Hp. inversion Hv; subst; inversion Hp.
Qed.

Lemma value_anno_inner_step_false : forall (e:exp) (A B:typ) (e':exp),
  value (e_anno e B) -> step e e' -> False.
Proof.
  intros e A B e' Hv Hs. inversion Hv; subst; inversion Hs.
Qed.

(* All values are irreducible.  This is the key fact that excludes the   *)
(* counterexample [anno (lit 0) int] on the non-stepping side: it is not *)
(* a value.                                                              *)
Lemma value_no_step : forall v v', value v -> step v v' -> False.
Proof.
  intros v v' Hv. revert v'.
  induction Hv; intros v' Hs.
  all: try (inversion Hs).
  all: try solve [inversion H4].
  all: try solve [inversion H5].
  all: try solve [inversion H6].
  - exact (IHHv1 e1' H1).
  - exact (IHHv1 e1' H3).
  - exact (IHHv2 e2' H3).
Qed.

Lemma consistent_anno_step_l_value : forall e A B u1',
  value (e_anno e B) ->
  step (e_anno e A) u1' ->
  consistent u1' (e_anno e B).
Proof.
  intros e A B u1' Hv Hs. exfalso.
  inversion Hv; subst.
  all: dependent destruction Hs.
  - inversion H0.
  - inversion Hs.
  - inversion H0.
  - inversion Hs.
  - inversion H0.
  - inversion Hs.
Qed.

Lemma consistent_anno_step_r_value : forall e A B u2',
  value (e_anno e A) ->
  step (e_anno e B) u2' ->
  consistent (e_anno e A) u2'.
Proof.
  intros e A B u2' Hv Hs. exfalso.
  inversion Hv; subst.
  all: dependent destruction Hs.
  - inversion H0.
  - inversion Hs.
  - inversion H0.
  - inversion Hs.
  - inversion H0.
  - inversion Hs.
Qed.

(* If the right-hand term is a value (hence irreducible), consistency is  *)
(* preserved when the left-hand term steps.                              *)
Lemma consistent_step_l_value : forall u1 u2 u1',
  value u2 -> consistent u1 u2 -> step u1 u1' -> consistent u1' u2.
Proof.
  intros u1 u2 u1' Hv Hc. revert u1' Hv.
  induction Hc; intros u1' Hv Hstep.
  - (* C_lit *) inversion Hstep.
  - (* C_anno *)
    apply (consistent_anno_step_l_value e A B u1'); assumption.
  - (* C_disjoint *)
    destruct (pType_step_subsub u1 A u1' H Hstep) as [A' HA'].
    destruct HA' as [Hp' Hs'].
    apply C_disjoint with (A := A') (B := B).
    + exact Hp'.
    + exact H0.
    + apply (disjoint_subsub_l nil A A' B); assumption.
    + apply pType_prevalue with (A := A'). exact Hp'.
    + exact H3.
  - (* C_mergel *)
    inversion Hstep; subst.
    + apply C_mergel.
      * apply (IHHc1 e1' Hv H1).
      * apply (IHHc2 e2' Hv H3).
    + apply C_mergel.
      * apply (IHHc1 e1' Hv H3).
      * exact Hc2.
    + apply C_mergel.
      * exact Hc1.
      * apply (IHHc2 e2' Hv H3).
  - (* C_merger *)
    inversion Hv; subst.
    apply C_merger.
    + apply (IHHc1 u1' H1 Hstep).
    + apply (IHHc2 u1' H2 Hstep).
Qed.

(* Symmetric version: if the left-hand term is a value, consistency is   *)
(* preserved when the right-hand term steps.                              *)
Lemma consistent_step_r_value : forall u1 u2 u2',
  value u1 -> consistent u1 u2 -> step u2 u2' -> consistent u1 u2'.
Proof.
  intros u1 u2 u2' Hv Hc. revert u2' Hv.
  induction Hc; intros u2' Hv Hstep.
  - inversion Hstep.
  - apply (consistent_anno_step_r_value e A B u2'); assumption.
  - destruct (pType_step_subsub u2 B u2' H0 Hstep) as [B' HB'].
    destruct HB' as [Hp' Hs'].
    apply C_disjoint with (A := A) (B := B').
    + exact H.
    + exact Hp'.
    + apply (disjoint_subsub_r nil A B B'); assumption.
    + exact H2.
    + apply pType_prevalue with (A := B'). exact Hp'.
  - inversion Hv; subst.
    apply C_mergel.
    + apply (IHHc1 u2' H1 Hstep).
    + apply (IHHc2 u2' H2 Hstep).
  - inversion Hstep; subst.
    + apply C_merger.
      * apply (IHHc1 e1' Hv H1).
      * apply (IHHc2 e2' Hv H3).
    + apply C_merger.
      * apply (IHHc1 e1' Hv H3).
      * exact Hc2.
    + apply C_merger.
      * exact Hc1.
      * apply (IHHc2 e2' Hv H3).
Qed.

(* ------------------------------------------------------------------ *)
(* 4. Merge preservation in each concrete step shape.                  *)
(* ------------------------------------------------------------------ *)

Lemma subsub_refl_local : forall A, lc_typ A -> subsub A A.
Proof.
  intros A HA. apply IS_refl. exact HA.
Qed.

Lemma subsub_and_intro : forall A' B' A B,
  lc_typ A -> lc_typ B ->
  subsub A' A -> subsub B' B ->
  subsub (t_and A' B') (t_and A B).
Proof.
  intros A' B' A B HlcA HlcB HsubA HsubB.
  apply IS_and with (B := t_and A B) (B1 := A) (B2 := B).
  - apply Sp_and; assumption.
  - exact HsubA.
  - exact HsubB.
Qed.

(* Both operands step.  [consistent u1' u2'] is exactly the extra     *)
(* invariant needed by [Typ_mergev]; it is NOT implied by the literal   *)
(* untyped statement (see [consistent_step_both_unrestricted_false]).   *)
Lemma merge_pres_both_consistent : forall u1 u2 A B u1' u2',
  Typing nil nil u1 Inf A ->
  Typing nil nil u2 Inf B ->
  consistent u1 u2 ->
  step u1 u1' ->
  step u2 u2' ->
  consistent u1' u2' ->
  exists C,
    Typing nil nil (e_merge u1' u2') Inf C /\ subsub C (t_and A B).
Proof.
  intros u1 u2 A B u1' u2' Hty1 Hty2 Hc Hs1 Hs2 Hc'.
  destruct (pres_inf u1 A u1' Hty1 Hs1) as [A' HA'].
  destruct HA' as [HtyA' HsubA].
  destruct (pres_inf u2 B u2' Hty2 Hs2) as [B' HB'].
  destruct HB' as [HtyB' HsubB].
  exists (t_and A' B'). split.
  - apply (Typ_mergev nil nil u1' u2' A' B').
    + apply TCW_empty.
    + apply CW_empty.
    + apply uniq_nil.
    + exact HtyA'.
    + exact HtyB'.
    + exact Hc'.
  - apply subsub_and_intro.
    + apply (typing_lc_typ nil nil u1 Inf A Hty1).
    + apply (typing_lc_typ nil nil u2 Inf B Hty2).
    + exact HsubA.
    + exact HsubB.
Qed.

(* The left operand steps while the right operand is a value.          *)
Lemma merge_pres_mergel_value : forall u1 u2 A B u1',
  Typing nil nil u1 Inf A ->
  Typing nil nil u2 Inf B ->
  value u2 ->
  consistent u1 u2 ->
  step u1 u1' ->
  exists C,
    Typing nil nil (e_merge u1' u2) Inf C /\ subsub C (t_and A B).
Proof.
  intros u1 u2 A B u1' Hty1 Hty2 Hv Hc Hs.
  destruct (pres_inf u1 A u1' Hty1 Hs) as [A' HA'].
  destruct HA' as [HtyA' HsubA].
  assert (Hc' : consistent u1' u2)
    by (apply (consistent_step_l_value u1 u2 u1' Hv Hc Hs)).
  exists (t_and A' B). split.
  - apply (Typ_mergev nil nil u1' u2 A' B).
    + apply TCW_empty.
    + apply CW_empty.
    + apply uniq_nil.
    + exact HtyA'.
    + exact Hty2.
    + exact Hc'.
  - apply subsub_and_intro.
    + apply (typing_lc_typ nil nil u1 Inf A Hty1).
    + apply (typing_lc_typ nil nil u2 Inf B Hty2).
    + exact HsubA.
    + apply subsub_refl_local.
      apply (typing_lc_typ nil nil u2 Inf B Hty2).
Qed.

(* The right operand steps while the left operand is a value.          *)
Lemma merge_pres_merger_value : forall u1 u2 A B u2',
  Typing nil nil u1 Inf A ->
  Typing nil nil u2 Inf B ->
  value u1 ->
  consistent u1 u2 ->
  step u2 u2' ->
  exists C,
    Typing nil nil (e_merge u1 u2') Inf C /\ subsub C (t_and A B).
Proof.
  intros u1 u2 A B u2' Hty1 Hty2 Hv Hc Hs.
  destruct (pres_inf u2 B u2' Hty2 Hs) as [B' HB'].
  destruct HB' as [HtyB' HsubB].
  assert (Hc' : consistent u1 u2')
    by (apply (consistent_step_r_value u1 u2 u2' Hv Hc Hs)).
  exists (t_and A B'). split.
  - apply (Typ_mergev nil nil u1 u2' A B').
    + apply TCW_empty.
    + apply CW_empty.
    + apply uniq_nil.
    + exact Hty1.
    + exact HtyB'.
    + exact Hc'.
  - apply subsub_and_intro.
    + apply (typing_lc_typ nil nil u1 Inf A Hty1).
    + apply (typing_lc_typ nil nil u2 Inf B Hty2).
    + apply subsub_refl_local.
      apply (typing_lc_typ nil nil u1 Inf A Hty1).
    + exact HsubB.
Qed.

End RestrictedStepPreservation.

(* ------------------------------------------------------------------ *)
(* 5. The literal (untyped) both-step statement is false.              *)
(*                                                                     *)
(* The counterexample uses a consistent pair of annotations whose      *)
(* common inner expression is a merge of two literals.  Casting that   *)
(* merge at [t_int] may choose either branch, so the two reducts are   *)
(* the inconsistent literals [0] and [1].                              *)
(* ------------------------------------------------------------------ *)

Lemma consistent_lit_lit_false : forall i j, i <> j ->
  ~ consistent (e_lit i) (e_lit j).
Proof.
  intros i j Hij H. inversion H; subst.
  - exact (Hij eq_refl).
  - apply pType_lit_inv in H0. subst A.
    apply pType_lit_inv in H1. subst B.
    exact (disjoint_int_int_false nil H2).
Qed.

Lemma step_anno_merge_lit0 :
  step (e_anno (e_merge (e_lit 0) (e_lit 1)) t_int) (e_lit 0).
Proof.
  eapply Step_annov.
  - apply V_merge; apply V_lit.
  - apply PV_merge; apply PV_int.
  - eapply Cast_mergel.
    + apply lc_e_lit.
    + apply O_int.
    + apply Cast_int.
Qed.

Lemma step_anno_merge_lit1 :
  step (e_anno (e_merge (e_lit 0) (e_lit 1)) t_int) (e_lit 1).
Proof.
  eapply Step_annov.
  - apply V_merge; apply V_lit.
  - apply PV_merge; apply PV_int.
  - eapply Cast_merger.
    + apply lc_e_lit.
    + apply O_int.
    + apply Cast_int.
Qed.

Lemma consistent_anno_merge_self :
  consistent (e_anno (e_merge (e_lit 0) (e_lit 1)) t_int)
             (e_anno (e_merge (e_lit 0) (e_lit 1)) t_int).
Proof.
  apply C_anno.
  - apply lc_t_int.
  - apply lc_e_merge; apply lc_e_lit.
  - apply lc_t_int.
Qed.

Theorem consistent_step_both_unrestricted_false :
  ~ (forall u1 u2 u1' u2',
       consistent u1 u2 -> step u1 u1' -> step u2 u2' ->
       consistent u1' u2').
Proof.
  intros H.
  pose proof (H (e_anno (e_merge (e_lit 0) (e_lit 1)) t_int)
                 (e_anno (e_merge (e_lit 0) (e_lit 1)) t_int)
                 (e_lit 0) (e_lit 1)
                 consistent_anno_merge_self
                 step_anno_merge_lit0
                 step_anno_merge_lit1) as Hbad.
  exact (consistent_lit_lit_false 0 1
           (fun H01 => Nat.neq_succ_0 0 (eq_sym H01)) Hbad).
Qed.

(* The inner merge used above has no [Inf] typing, which is why the     *)
(* untyped counterexample does not refute the typed version.            *)
Lemma typing_merge_lits_inf_false : forall C,
  ~ Typing nil nil (e_merge (e_lit 0) (e_lit 1)) Inf C.
Proof.
  intros C H. inversion H; subst.
  - apply typing_lit_inf_inv in H2. subst A.
    apply typing_lit_inf_inv in H5. subst B.
    exact (disjoint_int_int_false nil H6).
  - apply (consistent_lit_lit_false 0 1
             (fun H01 => Nat.neq_succ_0 0 (eq_sym H01))).
    exact H9.
Qed.
End agentE2.
Import agentE2.

Module agentK2.
Import ListNotations.

(* ==================================================================== *)
(* Cast_and consistency, exact status.                                  *)
(*                                                                      *)
(* This file proves the disjoint-target case of                          *)
(*                                                                      *)
(*   casting_consistent_split : forall v A B C v1 v2,                    *)
(*     Typing nil nil v Chk A -> TWell nil A -> spl A B C ->             *)
(*     casting v B v1 -> casting v C v2 -> consistent v1 v2.             *)
(*                                                                      *)
(* The subsub/disjoint transfer lemmas below are copied verbatim from    *)
(* the self-contained development in agentI.v (whose .vo was built       *)
(* against an older agentE.vo and is therefore not importable).         *)
(* ==================================================================== *)

(* Splitting and (topLike / algo_sub / disjoint_axiom) components      *)
(* ================================================================== *)

Lemma topLike_forall_inv : forall D A B,
  topLike D (t_forall A B) ->
  exists L, forall X, X \notin L ->
    topLike (cons (X, A) D) (open_typ_wrt_typ B (t_tvar_f X)).
Proof.
  intros D A B H. inversion H; subst. eexists; eassumption.
Qed.

Lemma topLike_spl : forall D B B1 B2,
  spl B B1 B2 -> topLike D B -> topLike D B1 /\ topLike D B2.
Proof.
  intros D B B1 B2 Hspl. revert D.
  induction Hspl as
    [ A B C1 C2 HlcA Hsub IHsub
    | L A B C1 C2 HlcA Hbody IHBODY
    | l B C1 C2 Hsub IHsub
    | A B HlcA HlcB ];
    intros D Htop.
  - apply topLike_arrow_inv in Htop. destruct Htop as [HTA HtopB].
    destruct (IHsub D HtopB) as [H1 H2].
    split; apply TL_arrow; assumption.
  - destruct (topLike_forall_inv D A B Htop) as [L0 Hbody0].
    split.
    + apply (TL_all ((L \u L0))).
      intros X HX. destruct (notin_union X L L0 HX) as [HXL HXL0].
      apply (proj1 (IHBODY X HXL (cons (X, A) D) (Hbody0 X HXL0))).
    + apply (TL_all ((L \u L0))).
      intros X HX. destruct (notin_union X L L0 HX) as [HXL HXL0].
      apply (proj2 (IHBODY X HXL (cons (X, A) D) (Hbody0 X HXL0))).
  - apply topLike_rcd_inv in Htop.
    destruct (IHsub D Htop) as [H1 H2].
    split; apply TL_rcd; assumption.
  - apply topLike_and_inv in Htop. destruct Htop as [H1 H2].
    split; assumption.
Qed.

Lemma lc_forall_of_body : forall A B L,
  lc_typ A ->
  (forall X, X \notin L -> lc_typ (open_typ_wrt_typ B (t_tvar_f X))) ->
  lc_typ (t_forall A B).
Proof.
  intros A B L HlcA Hbody.
  apply lc_t_forall; [ assumption | ].
  apply (lc_open_all B L). assumption.
Qed.

Lemma spl_lcA : forall A B C, spl A B C -> lc_typ A.
Proof. intros A B C H. apply (proj1 (spl_lc A B C H)). Qed.
Lemma spl_lcB : forall A B C, spl A B C -> lc_typ B.
Proof. intros A B C H. apply (proj1 (proj2 (spl_lc A B C H))). Qed.
Lemma spl_lcC : forall A B C, spl A B C -> lc_typ C.
Proof. intros A B C H. apply (proj2 (proj2 (spl_lc A B C H))). Qed.

(* Splitting the target of a disjointness axiom keeps an axiom. *)
Lemma disjoint_axiom_spl_r : forall A B B1 B2,
  disjoint_axiom A B -> spl B B1 B2 -> disjoint_axiom A B1.
Proof.
  intros A B B1 B2 Hax. revert B1 B2.
  induction Hax as
    [ A1 A2 Hlc1 Hlc2
    | l A0 HlcA
    | A0 B0 HlcA HlcAll
    | A1 A2 l A0 Hlc1 Hlc2 HlcA
    | A1 A2 A0 B0 Hlc1 Hlc2 HlcA HlcAll
    | l C0 A0 B0 HlcC HlcA HlcAll
    | A1 A2 Hlc1 Hlc2
    | l A0 HlcA
    | A0 B0 HlcA HlcAll
    | l A0 A1 A2 HlcA Hlc1 Hlc2
    | A0 B0 A1 A2 HlcA HlcAll Hlc1 Hlc2
    | A0 B0 l C0 HlcA HlcAll HlcC
    | l1 A0 l2 B0 HlcA HlcB Hneq ];
    intros B1 B2 Hspl.
  - (* Dax_intArrow *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_intArrow; [ assumption | apply (spl_lcB A2 q1 q2 Hsplq) ].
  - (* Dax_intRcd *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_intRcd. apply (spl_lcB A0 q1 q2 Hsplq).
  - (* Dax_intAll *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_intAll; [ assumption | ].
    apply (lc_forall_of_body A0 q1 Lq HlcA).
    intros X HX. apply (spl_lcB (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_arrowRcd *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_arrowRcd; [ assumption | assumption | apply (spl_lcB A0 q1 q2 Hsplq) ].
  - (* Dax_arrowAll *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_arrowAll; [ assumption | assumption | assumption | ].
    apply (lc_forall_of_body A0 q1 Lq HlcA).
    intros X HX. apply (spl_lcB (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_rcdAll *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdAll; [ assumption | assumption | ].
    apply (lc_forall_of_body A0 q1 Lq HlcA).
    intros X HX. apply (spl_lcB (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_arrowInt *) inversion Hspl.
  - (* Dax_rcdInt *) inversion Hspl.
  - (* Dax_allInt *) inversion Hspl.
  - (* Dax_rcdArrow *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdArrow; [ assumption | assumption | apply (spl_lcB A2 q1 q2 Hsplq) ].
  - (* Dax_allArrow *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_allArrow; [ assumption | assumption | assumption | apply (spl_lcB A2 q1 q2 Hsplq) ].
  - (* Dax_allRcd *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_allRcd; [ assumption | assumption | apply (spl_lcB C0 q1 q2 Hsplq) ].
  - (* Dax_rcdNeq *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdNeq; [ assumption | apply (spl_lcB B0 q1 q2 Hsplq) | assumption ].
Qed.

(* Splitting the target of a disjointness axiom, second component. *)
Lemma disjoint_axiom_spl_r2 : forall A B B1 B2,
  disjoint_axiom A B -> spl B B1 B2 -> disjoint_axiom A B2.
Proof.
  intros A B B1 B2 Hax. revert B1 B2.
  induction Hax as
    [ A1 A2 Hlc1 Hlc2
    | l A0 HlcA
    | A0 B0 HlcA HlcAll
    | A1 A2 l A0 Hlc1 Hlc2 HlcA
    | A1 A2 A0 B0 Hlc1 Hlc2 HlcA HlcAll
    | l C0 A0 B0 HlcC HlcA HlcAll
    | A1 A2 Hlc1 Hlc2
    | l A0 HlcA
    | A0 B0 HlcA HlcAll
    | l A0 A1 A2 HlcA Hlc1 Hlc2
    | A0 B0 A1 A2 HlcA HlcAll Hlc1 Hlc2
    | A0 B0 l C0 HlcA HlcAll HlcC
    | l1 A0 l2 B0 HlcA HlcB Hneq ];
    intros B1 B2 Hspl.
  - (* Dax_intArrow *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_intArrow; [ assumption | apply (spl_lcC A2 q1 q2 Hsplq) ].
  - (* Dax_intRcd *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_intRcd. apply (spl_lcC A0 q1 q2 Hsplq).
  - (* Dax_intAll *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_intAll; [ assumption | ].
    apply (lc_forall_of_body A0 q2 Lq HlcA).
    intros X HX. apply (spl_lcC (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_arrowRcd *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_arrowRcd; [ assumption | assumption | apply (spl_lcC A0 q1 q2 Hsplq) ].
  - (* Dax_arrowAll *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_arrowAll; [ assumption | assumption | assumption | ].
    apply (lc_forall_of_body A0 q2 Lq HlcA).
    intros X HX. apply (spl_lcC (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_rcdAll *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdAll; [ assumption | assumption | ].
    apply (lc_forall_of_body A0 q2 Lq HlcA).
    intros X HX. apply (spl_lcC (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_arrowInt *) inversion Hspl.
  - (* Dax_rcdInt *) inversion Hspl.
  - (* Dax_allInt *) inversion Hspl.
  - (* Dax_rcdArrow *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdArrow; [ assumption | assumption | apply (spl_lcC A2 q1 q2 Hsplq) ].
  - (* Dax_allArrow *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_allArrow; [ assumption | assumption | assumption | apply (spl_lcC A2 q1 q2 Hsplq) ].
  - (* Dax_allRcd *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_allRcd; [ assumption | assumption | apply (spl_lcC C0 q1 q2 Hsplq) ].
  - (* Dax_rcdNeq *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdNeq; [ assumption | apply (spl_lcC B0 q1 q2 Hsplq) | assumption ].
Qed.

(* ============================================================ *)
(* Decomposing disjointness along the split (right-hand side)   *)
(* ============================================================ *)

Lemma disjoint_spl_r : forall D A B B1 B2,
  spl B B1 B2 -> disjoint D A B -> disjoint D A B1 /\ disjoint D A B2.
Proof.
  intros D A B B1 B2 Hspl Hd. revert B1 B2 Hspl.
  induction Hd as
    [ D0 A0 B0 Htc HtwA HtwB Hax
    | D0 A0 B0 HtwB Htop
    | D0 A0 B0 HtwA Htop
    | D0 A1 A2 B0_1 B0_2 Htw1 Htw2 Hdd IHd
    | D0 l A0 B0 Hdd IHd
    | L D0 A1 B1 A2 B2 Htw1 Htw2 Hbody IHb
    | D0 X B0 A0 Hb Ha
    | D0 B0 X A0 Hb Ha
    | D0 A0 B0 A1 A2 Hspl0 Hd1 IH1 Hd2 IH2
    | D0 A0 B0 C1 C2 Hspl0 Hd1 IH1 Hd2 IH2 ];
    intros E1 E2 Hsplit.
  - (* D_ax *)
    destruct (agentA.spl_TWell D0 B0 E1 E2 HtwB Hsplit) as [HtwE1 HtwE2].
    split.
    + apply D_ax; [ exact Htc | exact HtwA | exact HtwE1 | apply (disjoint_axiom_spl_r A0 B0 E1 E2 Hax Hsplit) ].
    + apply D_ax; [ exact Htc | exact HtwA | exact HtwE2 | apply (disjoint_axiom_spl_r2 A0 B0 E1 E2 Hax Hsplit) ].
  - (* D_topl *)
    destruct (agentA.spl_TWell D0 B0 E1 E2 HtwB Hsplit) as [HtwE1 HtwE2].
    split; apply D_topl; [ exact HtwE1 | exact Htop | exact HtwE2 | exact Htop ].
  - (* D_topr *)
    destruct (topLike_spl D0 B0 E1 E2 Hsplit Htop) as [Htop1 Htop2].
    split; apply D_topr; [ exact HtwA | exact Htop1 | exact HtwA | exact Htop2 ].
  - (* D_arrow *)
    inversion Hsplit as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    destruct (agentA.spl_TWell D0 (t_arrow B0_1 B0_2) (t_arrow B0_1 q1) (t_arrow B0_1 q2) Htw2 Hsplit) as [HtwE1 HtwE2].
    destruct (IHd q1 q2 Hsplq) as [Hq1 Hq2].
    split.
    + apply D_arrow; [ exact Htw1 | exact HtwE1 | exact Hq1 ].
    + apply D_arrow; [ exact Htw1 | exact HtwE2 | exact Hq2 ].
  - (* D_rcdEq *)
    inversion Hsplit as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    destruct (IHd q1 q2 Hsplq) as [Hq1 Hq2].
    split; [ apply D_rcdEq; exact Hq1 | apply D_rcdEq; exact Hq2 ].
  - (* D_all *)
    inversion Hsplit as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    split.
    + apply (D_all (L \u Lq) D0 A1 B1 A2 q1); [ exact Htw1 | exact Htw2 | ].
      intros X HX. destruct (notin_union X L Lq HX) as [HXL HXLq].
      exact (proj1 (IHb X HXL (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HXLq))).
    + apply (D_all (L \u Lq) D0 A1 B1 A2 q2); [ exact Htw1 | exact Htw2 | ].
      intros X HX. destruct (notin_union X L Lq HX) as [HXL HXLq].
      exact (proj2 (IHb X HXL (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HXLq))).
  - (* D_varl *)
    destruct (algo_sub_spl D0 A0 B0 Ha E1 E2 Hsplit) as [Ha1 Ha2].
    split; [ apply (D_varl D0 X E1 A0 Hb Ha1) | apply (D_varl D0 X E2 A0 Hb Ha2) ].
  - (* D_varr *)
    inversion Hsplit.
  - (* D_andl *)
    destruct (IH1 E1 E2 Hsplit) as [H11 H12].
    destruct (IH2 E1 E2 Hsplit) as [H21 H22].
    split; [ apply (D_andl D0 A0 E1 A1 A2 Hspl0 H11 H21) | apply (D_andl D0 A0 E2 A1 A2 Hspl0 H12 H22) ].
  - (* D_andr *)
    destruct (@spl_functional B0 C1 C2 E1 E2 Hspl0 Hsplit) as [EQ1 EQ2].
    subst E1 E2.
    split; assumption.
Qed.

(* Splitting the source of a disjointness axiom. *)
Lemma disjoint_axiom_spl_l : forall A B A1 A2,
  disjoint_axiom A B -> spl A A1 A2 -> disjoint_axiom A1 B.
Proof.
  intros A B A1 A2 Hax. revert A1 A2.
  induction Hax as
    [ A0_1 A0_2 Hlc1 Hlc2
    | l A0 HlcA
    | A0 B0 HlcA HlcAll
    | A1 A2 l A0 Hlc1 Hlc2 HlcA
    | A1 A2 A0 B0 Hlc1 Hlc2 HlcA HlcAll
    | l C0 A0 B0 HlcC HlcA HlcAll
    | A1 A2 Hlc1 Hlc2
    | l A0 HlcA
    | A0 B0 HlcA HlcAll
    | l A0 A1 A2 HlcA Hlc1 Hlc2
    | A0 B0 A1 A2 HlcA HlcAll Hlc1 Hlc2
    | A0 B0 l C0 HlcA HlcAll HlcC
    | l1 A0 l2 B0 HlcA HlcB Hneq ];
    intros C1 C2 Hspl.
  - (* Dax_intArrow *) inversion Hspl.
  - (* Dax_intRcd *) inversion Hspl.
  - (* Dax_intAll *) inversion Hspl.
  - (* Dax_arrowRcd *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_arrowRcd; [ assumption | apply (spl_lcB A2 q1 q2 Hsplq) | assumption ].
  - (* Dax_arrowAll *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_arrowAll; [ assumption | apply (spl_lcB A2 q1 q2 Hsplq) | assumption | assumption ].
  - (* Dax_rcdAll *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdAll; [ apply (spl_lcB C0 q1 q2 Hsplq) | assumption | assumption ].
  - (* Dax_arrowInt *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_arrowInt; [ assumption | apply (spl_lcB A2 q1 q2 Hsplq) ].
  - (* Dax_rcdInt *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdInt. apply (spl_lcB A0 q1 q2 Hsplq).
  - (* Dax_allInt *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_allInt; [ assumption | ].
    apply (lc_forall_of_body A0 q1 Lq HlcA).
    intros X HX. apply (spl_lcB (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_rcdArrow *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdArrow; [ apply (spl_lcB A0 q1 q2 Hsplq) | assumption | assumption ].
  - (* Dax_allArrow *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_allArrow; [ assumption | | assumption | assumption ].
    apply (lc_forall_of_body A0 q1 Lq HlcA).
    intros X HX. apply (spl_lcB (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_allRcd *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_allRcd; [ assumption | | assumption ].
    apply (lc_forall_of_body A0 q1 Lq HlcA).
    intros X HX. apply (spl_lcB (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_rcdNeq *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdNeq; [ apply (spl_lcB A0 q1 q2 Hsplq) | assumption | assumption ].
Qed.


(* Splitting the source of a disjointness axiom, second component. *)
Lemma disjoint_axiom_spl_l2 : forall A B A1 A2,
  disjoint_axiom A B -> spl A A1 A2 -> disjoint_axiom A2 B.
Proof.
  intros A B A1 A2 Hax. revert A1 A2.
  induction Hax as
    [ A0_1 A0_2 Hlc1 Hlc2
    | l A0 HlcA
    | A0 B0 HlcA HlcAll
    | A1 A2 l A0 Hlc1 Hlc2 HlcA
    | A1 A2 A0 B0 Hlc1 Hlc2 HlcA HlcAll
    | l C0 A0 B0 HlcC HlcA HlcAll
    | A1 A2 Hlc1 Hlc2
    | l A0 HlcA
    | A0 B0 HlcA HlcAll
    | l A0 A1 A2 HlcA Hlc1 Hlc2
    | A0 B0 A1 A2 HlcA HlcAll Hlc1 Hlc2
    | A0 B0 l C0 HlcA HlcAll HlcC
    | l1 A0 l2 B0 HlcA HlcB Hneq ];
    intros C1 C2 Hspl.
  - (* Dax_intArrow *) inversion Hspl.
  - (* Dax_intRcd *) inversion Hspl.
  - (* Dax_intAll *) inversion Hspl.
  - (* Dax_arrowRcd *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_arrowRcd; [ assumption | apply (spl_lcC A2 q1 q2 Hsplq) | assumption ].
  - (* Dax_arrowAll *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_arrowAll; [ assumption | apply (spl_lcC A2 q1 q2 Hsplq) | assumption | assumption ].
  - (* Dax_rcdAll *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdAll; [ apply (spl_lcC C0 q1 q2 Hsplq) | assumption | assumption ].
  - (* Dax_arrowInt *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_arrowInt; [ assumption | apply (spl_lcC A2 q1 q2 Hsplq) ].
  - (* Dax_rcdInt *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdInt. apply (spl_lcC A0 q1 q2 Hsplq).
  - (* Dax_allInt *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_allInt; [ assumption | ].
    apply (lc_forall_of_body A0 q2 Lq HlcA).
    intros X HX. apply (spl_lcC (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_rcdArrow *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdArrow; [ apply (spl_lcC A0 q1 q2 Hsplq) | assumption | assumption ].
  - (* Dax_allArrow *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_allArrow; [ assumption | | assumption | assumption ].
    apply (lc_forall_of_body A0 q2 Lq HlcA).
    intros X HX. apply (spl_lcC (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_allRcd *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_allRcd; [ assumption | | assumption ].
    apply (lc_forall_of_body A0 q2 Lq HlcA).
    intros X HX. apply (spl_lcC (open_typ_wrt_typ B0 (t_tvar_f X)) (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HX)).
  - (* Dax_rcdNeq *)
    inversion Hspl as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    apply Dax_rcdNeq; [ apply (spl_lcC A0 q1 q2 Hsplq) | assumption | assumption ].
Qed.

(* ============================================================ *)
(* Decomposing disjointness along the split (left-hand side)    *)
(* ============================================================ *)

Lemma disjoint_spl_l : forall D A A1 A2 B,
  spl A A1 A2 -> disjoint D A B -> disjoint D A1 B /\ disjoint D A2 B.
Proof.
  intros D A A1 A2 B Hspl Hd. revert A1 A2 Hspl.
  induction Hd as
    [ D0 A0 B0 Htc HtwA HtwB Hax
    | D0 A0 B0 HtwB Htop
    | D0 A0 B0 HtwA Htop
    | D0 A1 A2 B1 B2 Htw1 Htw2 Hdd IHd
    | D0 l A0 B0 Hdd IHd
    | L D0 A1 B1 A2 B2 Htw1 Htw2 Hbody IHb
    | D0 X B0 A0 Hb Ha
    | D0 B0 X A0 Hb Ha
    | D0 A0 B0 A1 A2 Hspl0 Hd1 IH1 Hd2 IH2
    | D0 A0 B0 B1 B2 Hspl0 Hd1 IH1 Hd2 IH2 ];
    intros E1 E2 Hsplit.
  - (* D_ax *)
    destruct (agentA.spl_TWell D0 A0 E1 E2 HtwA Hsplit) as [HtwE1 HtwE2].
    split.
    + apply D_ax; [ exact Htc | exact HtwE1 | exact HtwB | apply (disjoint_axiom_spl_l A0 B0 E1 E2 Hax Hsplit) ].
    + apply D_ax; [ exact Htc | exact HtwE2 | exact HtwB | apply (disjoint_axiom_spl_l2 A0 B0 E1 E2 Hax Hsplit) ].
  - (* D_topl *)
    destruct (topLike_spl D0 A0 E1 E2 Hsplit Htop) as [Htop1 Htop2].
    split; apply D_topl; [ exact HtwB | exact Htop1 | exact HtwB | exact Htop2 ].
  - (* D_topr *)
    destruct (agentA.spl_TWell D0 A0 E1 E2 HtwA Hsplit) as [HtwE1 HtwE2].
    split; apply D_topr; [ exact HtwE1 | exact Htop | exact HtwE2 | exact Htop ].
  - (* D_arrow *)
    inversion Hsplit as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    destruct (agentA.spl_TWell D0 (t_arrow A1 A2) (t_arrow A1 q1) (t_arrow A1 q2) Htw1 Hsplit) as [HtwE1 HtwE2].
    destruct (IHd q1 q2 Hsplq) as [Hq1 Hq2].
    split.
    + apply D_arrow; [ exact HtwE1 | exact Htw2 | exact Hq1 ].
    + apply D_arrow; [ exact HtwE2 | exact Htw2 | exact Hq2 ].
  - (* D_rcdEq *)
    inversion Hsplit as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    destruct (IHd q1 q2 Hsplq) as [Hq1 Hq2].
    split; [ apply D_rcdEq; exact Hq1 | apply D_rcdEq; exact Hq2 ].
  - (* D_all *)
    inversion Hsplit as [qA qB q1 q2 Hlcq Hsplq | Lq qA qB q1 q2 Hlcq Hbq | lq qB q1 q2 Hsplq | qA qB Hlcq Hlcq2]; subst.
    split.
    + apply (D_all (L \u Lq) D0 A1 q1 A2 B2); [ exact Htw1 | exact Htw2 | ].
      intros X HX. destruct (notin_union X L Lq HX) as [HXL HXLq].
      exact (proj1 (IHb X HXL (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HXLq))).
    + apply (D_all (L \u Lq) D0 A1 q2 A2 B2); [ exact Htw1 | exact Htw2 | ].
      intros X HX. destruct (notin_union X L Lq HX) as [HXL HXLq].
      exact (proj2 (IHb X HXL (open_typ_wrt_typ q1 (t_tvar_f X)) (open_typ_wrt_typ q2 (t_tvar_f X)) (Hbq X HXLq))).
  - (* D_varl *)
    inversion Hsplit.
  - (* D_varr *)
    destruct (algo_sub_spl D0 A0 B0 Ha E1 E2 Hsplit) as [Ha1 Ha2].
    split; [ apply (D_varr D0 E1 X A0 Hb Ha1) | apply (D_varr D0 E2 X A0 Hb Ha2) ].
  - (* D_andl *)
    destruct (@spl_functional A0 A1 A2 E1 E2 Hspl0 Hsplit) as [EQ1 EQ2].
    subst E1 E2.
    split; assumption.
  - (* D_andr *)
    destruct (IH1 E1 E2 Hsplit) as [H11 H12].
    destruct (IH2 E1 E2 Hsplit) as [H21 H22].
    split; [ apply (D_andr D0 E1 B0 B1 B2 Hspl0 H11 H21) | apply (D_andr D0 E2 B0 B1 B2 Hspl0 H12 H22) ].
Qed.

(* ============================================================ *)
(* subsub: local closedness and disjointness transfer           *)
(* ============================================================ *)

Lemma subsub_lc : forall A B, subsub A B -> lc_typ A /\ lc_typ B.
Proof.
  intros A B H. induction H as
    [ A0 Hlc
    | A1 A2 B0 B1 B2 Hspl Hss1 IH1 Hss2 IH2 ].
  - split; assumption.
  - destruct (spl_lc B0 B1 B2 Hspl) as [HlcB0 _].
    split.
    + apply lc_t_and; [ apply (proj1 IH1) | apply (proj1 IH2) ].
    + exact HlcB0.
Qed.

Lemma disjoint_subsub_r : forall D A B B',
  disjoint D A B -> subsub B' B -> disjoint D A B'.
Proof.
  intros D A B B' Hd Hss. revert D A Hd.
  induction Hss as
    [ B0 Hlc
    | A1 A2 B0 B1 B2 Hspl Hss1 IH1 Hss2 IH2 ];
    intros D0 X Hd.
  - exact Hd.
  - destruct (disjoint_spl_r D0 X B0 B1 B2 Hspl Hd) as [Hd1 Hd2].
    apply (D_andr D0 X (t_and A1 A2) A1 A2).
    + apply Sp_and; [ apply (proj1 (subsub_lc A1 B1 Hss1)) | apply (proj1 (subsub_lc A2 B2 Hss2)) ].
    + exact (IH1 D0 X Hd1).
    + exact (IH2 D0 X Hd2).
Qed.

Lemma disjoint_subsub_l : forall D A A' B,
  disjoint D A B -> subsub A' A -> disjoint D A' B.
Proof.
  intros D A A' B Hd Hss. revert D B Hd.
  induction Hss as
    [ A0 Hlc
    | A1 A2 B0 B1 B2 Hspl Hss1 IH1 Hss2 IH2 ];
    intros D0 Y Hd.
  - exact Hd.
  - destruct (disjoint_spl_l D0 B0 B1 B2 Y Hspl Hd) as [Hd1 Hd2].
    apply (D_andl D0 (t_and A1 A2) Y A1 A2).
    + apply Sp_and; [ apply (proj1 (subsub_lc A1 B1 Hss1)) | apply (proj1 (subsub_lc A2 B2 Hss2)) ].
    + exact (IH1 D0 Y Hd1).
    + exact (IH2 D0 Y Hd2).
Qed.

(* ============================================================ *)
(* Opening a locally closed type does not change it             *)

(* ==================================================================== *)
(* Disjoint / top-like target cases                                     *)
(* ==================================================================== *)

Lemma casting_consistent_split_disjoint :
  forall (v:exp) (B C:typ) (v1 v2:exp),
    disjoint nil B C ->
    casting v B v1 -> casting v C v2 ->
    consistent v1 v2.
Proof.
  intros v B C v1 v2 Hd Hc1 Hc2.
  destruct (agentE2.casting_pType_subsub v B v1 Hc1) as (P1 & Hp1 & Hs1).
  destruct (agentE2.casting_pType_subsub v C v2 Hc2) as (P2 & Hp2 & Hs2).
  apply (C_disjoint v1 v2 P1 P2).
  - exact Hp1.
  - exact Hp2.
  - apply (disjoint_subsub_r nil P1 C P2).
    + apply (disjoint_subsub_l nil B P1 C Hd Hs1).
    + exact Hs2.
  - apply agentE2.pType_prevalue with (A := P1). exact Hp1.
  - apply agentE2.pType_prevalue with (A := P2). exact Hp2.
Qed.

Lemma casting_consistent_split_of_disjoint_or_topLike :
  forall (v:exp) (A B C:typ) (v1 v2:exp),
    TWell nil A -> spl A B C ->
    casting v B v1 -> casting v C v2 ->
    (disjoint nil B C \/ topLike nil B \/ topLike nil C) ->
    consistent v1 v2.
Proof.
  intros v A B C v1 v2 HTW Hspl Hc1 Hc2 Hcase.
  destruct (spl_TWell_nil A B C HTW Hspl) as [HTWB HTWC].
  apply (casting_consistent_split_disjoint v B C v1 v2).
  - destruct Hcase as [Hd | Hrest].
    + exact Hd.
    + destruct Hrest as [HtopB | HtopC].
      * apply (D_topl nil B C HTWC HtopB).
      * apply (D_topr nil B C HTWB HtopC).
  - exact Hc1.
  - exact Hc2.
Qed.

Lemma casting_consistent_same_target_topLike :
  forall (v:exp) (B:typ) (v1 v2:exp),
    TWell nil B -> topLike nil B ->
    casting v B v1 -> casting v B v2 ->
    consistent v1 v2.
Proof.
  intros v B v1 v2 HTW Htop Hc1 Hc2.
  apply (casting_consistent_split_disjoint v B B v1 v2).
  - apply (D_topl nil B B HTW Htop).
  - exact Hc1.
  - exact Hc2.
Qed.

(*** NEW LEMMAS ***)

(* ==================================================================== *)
(* Casts whose source is a literal are merge trees of the same literal  *)
(* and top-like leaves.  They are pairwise consistent.                  *)
(* ==================================================================== *)

Lemma pType_det : forall (e:exp) (A B:typ),
  pType e A -> pType e B -> A = B.
Proof.
  intros e A B H. revert B. induction H as
    [ | i | e0 A0 HlcE HlcA | u1 u2 A1 A2 H1 IH1 H2 IH2 ];
    intros B0 HB.
  - inversion HB. reflexivity.
  - inversion HB. reflexivity.
  - inversion HB. reflexivity.
  - apply agentE2.pType_merge_inv in HB.
    destruct HB as (A1' & A2' & Heq & Hp1 & Hp2). subst B0.
    f_equal.
    + apply (IH1 A1' Hp1).
    + apply (IH2 A2' Hp2).
Qed.

Inductive lit_value (i:int) : exp -> Prop :=
 | LV_lit : lit_value i (e_lit i)
 | LV_top : forall (e:exp) (A:typ),
     pType e A -> topLike nil A -> prevalue e -> lit_value i e
 | LV_merge : forall (u1 u2:exp),
     lit_value i u1 -> lit_value i u2 -> lit_value i (e_merge u1 u2).
Arguments LV_lit {i}.
Arguments LV_top {i} e A _ _ _.
Arguments LV_merge {i} u1 u2 _ _.

Lemma lit_value_TWell : forall i u, lit_value i u ->
  forall A, pType u A -> TWell nil A.
Proof.
  intros i u H. induction H as
    [ | e A Hp Htop Hpv | u1 u2 H1 IH1 H2 IH2 ];
    intros B HB.
  - apply agentE2.pType_lit_inv in HB. subst B. apply (TW_int nil).
  - assert (Heq : A = B) by (apply (pType_det e A B Hp HB)).
    subst B.
    exact (topLike_TWell nil A Htop TCW_empty).
  - apply agentE2.pType_merge_inv in HB.
    destruct HB as (A1 & A2 & Heq & Hp1 & Hp2). subst B.
    apply TW_and; [ exact (IH1 A1 Hp1) | exact (IH2 A2 Hp2) ].
Qed.

Lemma lit_value_prevalue : forall i u, lit_value i u -> prevalue u.
Proof.
  intros i u H. induction H.
  - apply PV_int.
  - assumption.
  - apply PV_merge; assumption.
Qed.

Lemma lit_value_consistent : forall i u v,
  lit_value i u -> lit_value i v -> consistent u v.
Proof.
  intros i u v Hu. revert v. induction Hu as
    [ | e A Hp Htop Hpv | u1 u2 H1 IH1 H2 IH2 ];
    intros w Hw.
  - (* literal *)
    induction Hw as
      [ | e2 B Hp2 Htop2 Hpv2 | w1 w2 Hw1 IHW1 Hw2 IHW2 ].
    + apply C_lit.
    + apply (C_disjoint (e_lit i) e2 t_int B).
      * apply PT_int.
      * exact Hp2.
      * apply (D_topr nil t_int B (TW_int nil) Htop2).
      * apply PV_int.
      * exact Hpv2.
    + apply (C_merger (e_lit i) w1 w2).
      * apply IHW1.
      * apply IHW2.
  - (* top-like leaf *)
    induction Hw as
      [ | e2 B Hp2 Htop2 Hpv2 | w1 w2 Hw1 IHW1 Hw2 IHW2 ].
    + apply (C_disjoint e (e_lit i) A t_int).
      * exact Hp.
      * apply PT_int.
      * apply (D_topl nil A t_int (TW_int nil) Htop).
      * exact Hpv.
      * apply PV_int.
    + apply (C_disjoint e e2 A B).
      * exact Hp.
      * exact Hp2.
      * apply (D_topl nil A B (topLike_TWell nil B Htop2 TCW_empty) Htop).
      * exact Hpv.
      * exact Hpv2.
    + apply (C_merger e w1 w2).
      * apply IHW1.
      * apply IHW2.
  - (* merge *)
    apply (C_mergel u1 u2 w); [ apply IH1 | apply IH2 ]; exact Hw.
Qed.

Lemma casting_lit_value : forall (i:int) (A:typ) (v':exp),
  casting (e_lit i) A v' -> lit_value i v'.
Proof.
  intros i A v' H. dependent induction H.
  - apply LV_lit.
  - apply (LV_top e_top t_top).
    + apply PT_top.
    + apply TL_top. apply TCW_empty.
    + apply PV_top.
  - (* Cast_topArrow *)
    apply (LV_top (e_anno (e_abs t_top e_top) (t_arrow A1 A2))
                  (t_arrow A1 A2)).
    + apply PT_anno.
      * apply agentE2.lc_exp_abs_top_top.
      * apply ord_lc_typ. exact H0.
    + exact H1.
    + apply PV_anno.
      * apply agentE2.lc_exp_abs_top_top.
      * apply ord_lc_typ. exact H0.
  - (* Cast_topAll *)
    apply (LV_top (e_anno (e_tabs e_top) (t_forall A1 A2))
                  (t_forall A1 A2)).
    + apply PT_anno.
      * apply agentE2.lc_exp_tabs_top.
      * apply ord_lc_typ. exact H0.
    + exact H1.
    + apply PV_anno.
      * apply agentE2.lc_exp_tabs_top.
      * apply ord_lc_typ. exact H0.
  - (* Cast_topRcd *)
    apply (LV_top (e_anno (e_rcd l e_top) (t_rcd l A))
                  (t_rcd l A)).
    + apply PT_anno.
      * apply lc_e_rcd. apply lc_e_top.
      * apply ord_lc_typ. exact H0.
    + exact H1.
    + apply PV_anno.
      * apply lc_e_rcd. apply lc_e_top.
      * apply ord_lc_typ. exact H0.
  - (* Cast_and : the only recursive case surviving dependent induction *)
    apply LV_merge.
    + match goal with
      | IH : forall i0, e_lit i = e_lit i0 -> lit_value i0 v1 |- _ =>
          exact (IH i eq_refl)
      end.
    + match goal with
      | IH : forall i0, e_lit i = e_lit i0 -> lit_value i0 v2 |- _ =>
          exact (IH i eq_refl)
      end.
Qed.

(* ==================================================================== *)
(* Casting preserves the wrapping relation for sources which are        *)
(* neither literals nor merges.                                         *)
(* ==================================================================== *)

Lemma casting_wrapping_other : forall (v:exp) (A:typ) (v':exp),
  casting v A v' ->
  (forall i, v <> e_lit i) ->
  (forall e B, v <> e_anno e B) ->
  (forall u1 u2, v <> e_merge u1 u2) ->
  wrapping v A v'.
Proof.
  intros v A v' H. induction H as
    [ i
    | v0 Hlc
    | v0 A1 A2 Hlc Hord Htop
    | v0 A1 A2 Hlc Hord Htop
    | v0 l A0 Hlc Hord Htop
    | e A B Hlc Hord Hntl Hsub
    | v1 v2 A0 v1' Hlc Hord Hc IHc
    | v1 v2 A0 v2' Hlc Hord Hc IHc
    | v A0 v1 v2 B C Hspl Hc1 IH1 Hc2 IH2 ];
    intros Hlit Hanno Hnm.
  - exfalso. apply (Hlit i). reflexivity.
  - apply EW_top. exact Hlc.
  - apply EW_topArrow; [ exact Hlc | exact Hord | exact Htop ].
  - apply EW_topAll; [ exact Hlc | exact Hord | exact Htop ].
  - apply EW_topRcd; [ exact Hlc | exact Hord | exact Htop ].
  - exfalso. apply (Hanno e A). reflexivity.
  - exfalso. apply (Hnm v1 v2). reflexivity.
  - exfalso. apply (Hnm v1 v2). reflexivity.
  - apply (EW_and v A0 v1 v2 B C Hspl).
    + apply (IH1 Hlit Hanno Hnm).
    + apply (IH2 Hlit Hanno Hnm).
Qed.

Lemma casting_notmerge_TWell : forall (v:exp) (A:typ) (v':exp),
  casting v A v' ->
  (forall u1 u2, v <> e_merge u1 u2) ->
  TWell nil A.
Proof.
  intros v A v' H. induction H as
    [ i
    | v0 Hlc
    | v0 A1 A2 Hlc Hord Htop
    | v0 A1 A2 Hlc Hord Htop
    | v0 l A0 Hlc Hord Htop
    | e A B Hlc Hord Hntl Hsub
    | v1 v2 A0 v1' Hlc Hord Hc IHc
    | v1 v2 A0 v2' Hlc Hord Hc IHc
    | v A0 v1 v2 B C Hspl Hc1 IH1 Hc2 IH2 ];
    intros Hnm.
  - apply TW_int.
  - apply TW_top.
  - apply (topLike_TWell nil (t_arrow A1 A2) Htop TCW_empty).
  - apply (topLike_TWell nil (t_forall A1 A2) Htop TCW_empty).
  - apply (topLike_TWell nil (t_rcd l A0) Htop TCW_empty).
  - inversion Hntl; subst. assumption.
  - exfalso. apply (Hnm v1 v2). reflexivity.
  - exfalso. apply (Hnm v1 v2). reflexivity.
  - apply (spl_back_TWell A0 B C Hspl nil); [ apply IH1; assumption | apply IH2; assumption ].
Qed.

(* ==================================================================== *)
(* The split-consistency statement for all sources except merges.       *)
(* ==================================================================== *)



(* Exact remaining gap: both targets are non-topLike and not disjoint.  *)
(* This includes B = C non-topLike (e.g. B = C = t_int), where the      *)
(* pType route is unavailable.  No counterexample was found.  The       *)
(* missing ingredient is a cast-coherence lemma: casts of one source v  *)
(* at two non-disjoint split components must share their anno/int/top   *)
(* leaves or decompose into pairwise consistent merges.                 *)

(* ==================================================================== *)
(* Every cast target is well-formed.                                    *)
(* ==================================================================== *)

Lemma casting_TWell_target : forall (v:exp) (A:typ) (v':exp),
  casting v A v' -> TWell nil A.
Proof.
  intros v A v' H. induction H as
    [ i
    | v0 Hlc
    | v0 A1 A2 Hlc Hord Htop
    | v0 A1 A2 Hlc Hord Htop
    | v0 l A0 Hlc Hord Htop
    | e A0 B Hlc Hord Hntl Hsub
    | v1 v2 A0 v1' Hlc Hord Hc IHc
    | v1 v2 A0 v2' Hlc Hord Hc IHc
    | v0 A0 v1 v2 B C Hspl Hc1 IH1 Hc2 IH2 ].
  - apply TW_int.
  - apply TW_top.
  - apply (topLike_TWell nil (t_arrow A1 A2) Htop TCW_empty).
  - apply (topLike_TWell nil (t_forall A1 A2) Htop TCW_empty).
  - apply (topLike_TWell nil (t_rcd l A0) Htop TCW_empty).
  - inversion Hntl; subst. assumption.
  - exact IHc.
  - exact IHc.
  - apply (spl_back_TWell A0 B C Hspl nil); assumption.
Qed.

Lemma casting_pType_TWell : forall (v:exp) (A:typ) (v':exp),
  casting v A v' ->
  forall P, pType v' P -> TWell nil P.
Proof.
  intros v A v' Hc P Hp.
  destruct (agentE2.casting_pType_subsub v A v' Hc) as (P0 & Hp0 & Hss).
  assert (Heq : P0 = P) by (apply (pType_det v' P0 P Hp0 Hp)).
  subst P0.
  exact (agentH.subsub_TWell nil P A (casting_TWell_target v A v' Hc) Hss).
Qed.

Inductive anno_value (e:exp) : exp -> Prop :=
 | AV_anno : forall A, lc_exp e -> TWell nil A -> anno_value e (e_anno e A)
 | AV_top : forall (u:exp) (A:typ),
     pType u A -> topLike nil A -> prevalue u -> anno_value e u
 | AV_merge : forall u1 u2,
     anno_value e u1 -> anno_value e u2 -> anno_value e (e_merge u1 u2).
Arguments AV_anno {e} A _ _.
Arguments AV_top {e} u A _ _ _.
Arguments AV_merge {e} u1 u2 _ _.

Lemma anno_value_consistent : forall (e:exp) (u v:exp),
  anno_value e u -> anno_value e v -> consistent u v.
Proof.
  intros e u v Hu. revert v. induction Hu as
    [ A Hlc HTW
    | u0 A Hp Htop Hpv
    | u1 u2 H1 IH1 H2 IH2 ];
    intros w Hw.
  - induction Hw as [ B HlcB HTWB | u2 B Hp2 Htop2 Hpv2 | w1 w2 Hw1 IHW1 Hw2 IHW2 ].
    + apply (C_anno e A B).
      * apply (TWell_lc_typ nil A); assumption.
      * exact Hlc.
      * apply (TWell_lc_typ nil B); assumption.
    + apply (C_disjoint (e_anno e A) u2 A B).
      * apply PT_anno; [ exact Hlc | apply (TWell_lc_typ nil A); assumption ].
      * exact Hp2.
      * apply (D_topr nil A B); [ assumption | exact Htop2 ].
      * apply PV_anno; [ exact Hlc | apply (TWell_lc_typ nil A); assumption ].
      * exact Hpv2.
    + apply (C_merger (e_anno e A) w1 w2); assumption.
  - induction Hw as [ B HlcB HTWB | u2 B Hp2 Htop2 Hpv2 | w1 w2 Hw1 IHW1 Hw2 IHW2 ].
    + apply (C_disjoint u0 (e_anno e B) A B).
      * exact Hp.
      * apply PT_anno; [ exact HlcB | apply (TWell_lc_typ nil B); assumption ].
      * apply (D_topl nil A B); [ assumption | exact Htop ].
      * exact Hpv.
      * apply PV_anno; [ exact HlcB | apply (TWell_lc_typ nil B); assumption ].
    + apply (agentK.consistent_toplike_l_gen u0 u2 A B);
      [ exact Htop | exact Hp | exact Hp2 |
        apply (topLike_TWell nil B Htop2 TCW_empty) | exact Hpv | exact Hpv2 ].
    + apply (C_merger u0 w1 w2); assumption.
  - apply (C_mergel u1 u2 w); [ apply IH1 | apply IH2 ]; exact Hw.
Qed.

Lemma casting_anno_value : forall (e:exp) (A0:typ) (A:typ) (v':exp),
  casting (e_anno e A0) A v' -> anno_value e v'.
Proof.
  intros e A0 A v' H. dependent induction H.
  - (* Cast_top *)
    apply (AV_top e_top t_top).
    + apply PT_top.
    + apply TL_top. apply TCW_empty.
    + apply PV_top.
  - (* Cast_topArrow *)
    apply (AV_top (e_anno (e_abs t_top e_top) (t_arrow A1 A2)) (t_arrow A1 A2)).
    + apply PT_anno.
      * apply agentK.lc_exp_abs_top.
      * apply ord_lc_typ. exact H0.
    + exact H1.
    + apply PV_anno.
      * apply agentK.lc_exp_abs_top.
      * apply ord_lc_typ. exact H0.
  - (* Cast_topAll *)
    apply (AV_top (e_anno (e_tabs e_top) (t_forall A1 A2)) (t_forall A1 A2)).
    + apply PT_anno.
      * apply agentK.lc_exp_tabs_top.
      * apply ord_lc_typ. exact H0.
    + exact H1.
    + apply PV_anno.
      * apply agentK.lc_exp_tabs_top.
      * apply ord_lc_typ. exact H0.
  - (* Cast_topRcd *)
    apply (AV_top (e_anno (e_rcd l e_top) (t_rcd l A)) (t_rcd l A)).
    + apply PT_anno.
      * apply lc_e_rcd. apply lc_e_top.
      * apply ord_lc_typ. exact H0.
    + exact H1.
    + apply PV_anno.
      * apply lc_e_rcd. apply lc_e_top.
      * apply ord_lc_typ. exact H0.
  - (* Cast_anno *)
    apply (AV_anno B H).
    inversion H1; subst. assumption.
  - (* Cast_and *)
    apply AV_merge.
    + exact (IHcasting1 e A0 eq_refl).
    + exact (IHcasting2 e A0 eq_refl).
Qed.


Lemma casting_consistent_other : forall (v:exp) (B C:typ) (v1 v2:exp),
  casting v B v1 -> casting v C v2 ->
  (forall i, v <> e_lit i) ->
  (forall e A, v <> e_anno e A) ->
  (forall u1 u2, v <> e_merge u1 u2) ->
  consistent v1 v2.
Proof.
  intros v B C v1 v2 Hc1 Hc2 Hlit Hanno Hnm.
  apply (agentK.wrapping_consistent v B v1
           (casting_wrapping_other v B v1 Hc1 Hlit Hanno Hnm)
           (casting_TWell_target v B v1 Hc1)
           C v2
           (casting_wrapping_other v C v2 Hc2 Hlit Hanno Hnm)
           (casting_TWell_target v C v2 Hc2)).
Qed.

Lemma casting_consistent_split_nonmerge :
  forall (v:exp) (A B C:typ) (v1 v2:exp),
    spl A B C ->
    casting v B v1 -> casting v C v2 ->
    (forall u1 u2, v <> e_merge u1 u2) ->
    consistent v1 v2.
Proof.
  intros v A B C v1 v2 Hspl Hc1 Hc2 Hnm.
  destruct v as [ n | x | | i | A0 e | A0 e | e1 e2 | e1 e2 | e A0 | l e | e l | e | e A0 ].
  all: try solve [ apply (casting_consistent_other _ B C v1 v2 Hc1 Hc2);
                   intros; discriminate ].
  - apply (agentK2.lit_value_consistent i v1 v2).
    + exact (agentK2.casting_lit_value i B v1 Hc1).
    + exact (agentK2.casting_lit_value i C v2 Hc2).
  - exfalso. apply (Hnm e1 e2). reflexivity.
  - apply (agentK2.anno_value_consistent e v1 v2).
    + exact (agentK2.casting_anno_value e A0 B v1 Hc1).
    + exact (agentK2.casting_anno_value e A0 C v2 Hc2).
Qed.


(* ============================================================ *)
(* Type-level disjointness preservation under algorithmic subtyping *)
(* ============================================================ *)

Lemma algo_sub_ord_int_target : forall D C,
  ord C -> algo_sub D t_int C ->
  C = t_int \/ topLike D C.
Proof.
  intros D C Hord H.
  inversion H; subst.
  all: try (left; reflexivity).
  all: try (right; assumption).
  all: try (exfalso; eapply spl_not_ord; eassumption).
  all: try discriminate.
Qed.


Lemma arrow_shape_ord : forall D A B P,
  ord P -> algo_sub D (t_arrow A B) P ->
  topLike D P \/ (exists P1 P2, P = t_arrow P1 P2).
Proof.
  intros D A B P Ho H.
  destruct (agentH.algo_sub_ord_arrow_target D A B P Ho H) as [Htop | Hr].
  - left. assumption.
  - right. destruct Hr as (P1 & P2 & Heq & _). exists P1, P2. assumption.
Qed.

Lemma rcd_shape_ord : forall D l A P,
  ord P -> algo_sub D (t_rcd l A) P ->
  topLike D P \/ (exists P2, P = t_rcd l P2).
Proof.
  intros D l A P Ho H.
  destruct (agentH.algo_sub_ord_rcd_target D l A P Ho H) as [Htop | Hr].
  - left. assumption.
  - right. destruct Hr as (P2 & Heq & _). exists P2. assumption.
Qed.

Lemma all_shape_ord : forall D A B P,
  ord P -> algo_sub D (t_forall A B) P ->
  topLike D P \/ (exists P1 P2, P = t_forall P1 P2).
Proof.
  intros D A B P Ho H.
  destruct (agentH.algo_sub_ord_forall_target D A B P Ho H) as [Htop | Hr].
  - left. assumption.
  - right. destruct Hr as (L & P1 & P2 & Heq & _). exists P1, P2. assumption.
Qed.

Lemma disjoint_axiom_ord_target : forall (D:tctx) (A B P Q:typ),
  disjoint_axiom A B ->
  TCWell D -> TWell D A -> TWell D B ->
  algo_sub D A P -> algo_sub D B Q ->
  ord P -> ord Q -> TWell D P -> TWell D Q ->
  disjoint D P Q.
Proof.
  intros D A B P Q Hax HTC HTA HTB HAP HBQ HoP HoQ HTWP HTWQ.
  destruct Hax as
    [ A1 A2 HlcA1 HlcA2
    | l A HlcA
    | A Bf HlcA HlcAll
    | A1 A2 l A HlcA1 HlcA2 HlcA
    | A1 A2 A Bf HlcA1 HlcA2 HlcA HlcAll
    | l C A Bf HlcC HlcA HlcAll
    | A1 A2 HlcA1 HlcA2
    | l A HlcA
    | A Bf HlcA HlcAll
    | l A A1 A2 HlcA HlcA1 HlcA2
    | A Bf A1 A2 HlcA HlcAll HlcA1 HlcA2
    | A Bf l C HlcA HlcAll HlcC
    | l1 A l2 B HlcA HlcB Hneq ].
  - (* int arrow *)
    destruct (algo_sub_ord_int_target D P HoP HAP) as [HeqP | HtopP].
    + subst P.
      destruct (arrow_shape_ord D A1 A2 Q HoQ HBQ) as [HtopQ | (Q1 & Q2 & HeqQ)].
      * apply (D_topr D t_int Q HTWP HtopQ).
      * subst Q.
        apply (D_ax D t_int (t_arrow Q1 Q2) HTC HTWP HTWQ).
        apply Dax_intArrow.
        -- apply (TWell_lc_typ D Q1 (proj1 (TWell_arrow_inv D Q1 Q2 HTWQ))).
        -- apply (TWell_lc_typ D Q2 (proj2 (TWell_arrow_inv D Q1 Q2 HTWQ))).
    + apply (D_topl D P Q HTWQ HtopP).
  - (* int rcd *)
    destruct (algo_sub_ord_int_target D P HoP HAP) as [HeqP | HtopP].
    + subst P.
      destruct (rcd_shape_ord D l A Q HoQ HBQ) as [HtopQ | (Q2 & HeqQ)].
      * apply (D_topr D t_int Q HTWP HtopQ).
      * subst Q.
        apply (D_ax D t_int (t_rcd l Q2) HTC HTWP HTWQ).
        apply Dax_intRcd.
        apply (TWell_lc_typ D Q2 (TWell_rcd_inv D l Q2 HTWQ)).
    + apply (D_topl D P Q HTWQ HtopP).
  - (* int all *)
    destruct (algo_sub_ord_int_target D P HoP HAP) as [HeqP | HtopP].
    + subst P.
      destruct (all_shape_ord D A Bf Q HoQ HBQ) as [HtopQ | (Q1 & Q2 & HeqQ)].
      * apply (D_topr D t_int Q HTWP HtopQ).
      * subst Q.
        apply (D_ax D t_int (t_forall Q1 Q2) HTC HTWP HTWQ).
        apply Dax_intAll.
        -- apply (TWell_lc_typ D Q1 (TWell_all_inv D Q1 Q2 HTWQ)).
        -- apply (TWell_lc_typ D (t_forall Q1 Q2) HTWQ).
    + apply (D_topl D P Q HTWQ HtopP).
  - (* arrow rcd *)
    destruct (arrow_shape_ord D A1 A2 P HoP HAP) as [HtopP | (P1 & P2 & HeqP)].
    + apply (D_topl D P Q HTWQ HtopP).
    + subst P.
      destruct (rcd_shape_ord D l A Q HoQ HBQ) as [HtopQ | (Q2 & HeqQ)].
      * apply (D_topr D (t_arrow P1 P2) Q HTWP HtopQ).
      * subst Q.
        apply (D_ax D (t_arrow P1 P2) (t_rcd l Q2) HTC HTWP HTWQ).
        apply Dax_arrowRcd.
        -- apply (TWell_lc_typ D P1 (proj1 (TWell_arrow_inv D P1 P2 HTWP))).
        -- apply (TWell_lc_typ D P2 (proj2 (TWell_arrow_inv D P1 P2 HTWP))).
        -- apply (TWell_lc_typ D Q2 (TWell_rcd_inv D l Q2 HTWQ)).
  - (* arrow all *)
    destruct (arrow_shape_ord D A1 A2 P HoP HAP) as [HtopP | (P1 & P2 & HeqP)].
    + apply (D_topl D P Q HTWQ HtopP).
    + subst P.
      destruct (all_shape_ord D A Bf Q HoQ HBQ) as [HtopQ | (Q1 & Q2 & HeqQ)].
      * apply (D_topr D (t_arrow P1 P2) Q HTWP HtopQ).
      * subst Q.
        apply (D_ax D (t_arrow P1 P2) (t_forall Q1 Q2) HTC HTWP HTWQ).
        apply Dax_arrowAll.
        -- apply (TWell_lc_typ D P1 (proj1 (TWell_arrow_inv D P1 P2 HTWP))).
        -- apply (TWell_lc_typ D P2 (proj2 (TWell_arrow_inv D P1 P2 HTWP))).
        -- apply (TWell_lc_typ D Q1 (TWell_all_inv D Q1 Q2 HTWQ)).
        -- apply (TWell_lc_typ D (t_forall Q1 Q2) HTWQ).
  - (* rcd all *)
    destruct (rcd_shape_ord D l C P HoP HAP) as [HtopP | (P2 & HeqP)].
    + apply (D_topl D P Q HTWQ HtopP).
    + subst P.
      destruct (all_shape_ord D A Bf Q HoQ HBQ) as [HtopQ | (Q1 & Q2 & HeqQ)].
      * apply (D_topr D (t_rcd l P2) Q HTWP HtopQ).
      * subst Q.
        apply (D_ax D (t_rcd l P2) (t_forall Q1 Q2) HTC HTWP HTWQ).
        apply Dax_rcdAll.
        -- apply (TWell_lc_typ D P2 (TWell_rcd_inv D l P2 HTWP)).
        -- apply (TWell_lc_typ D Q1 (TWell_all_inv D Q1 Q2 HTWQ)).
        -- apply (TWell_lc_typ D (t_forall Q1 Q2) HTWQ).
  - (* arrow int *)
    destruct (arrow_shape_ord D A1 A2 P HoP HAP) as [HtopP | (P1 & P2 & HeqP)].
    + apply (D_topl D P Q HTWQ HtopP).
    + subst P.
      destruct (algo_sub_ord_int_target D Q HoQ HBQ) as [HeqQ | HtopQ].
      * subst Q.
        apply (D_ax D (t_arrow P1 P2) t_int HTC HTWP HTWQ).
        apply Dax_arrowInt.
        -- apply (TWell_lc_typ D P1 (proj1 (TWell_arrow_inv D P1 P2 HTWP))).
        -- apply (TWell_lc_typ D P2 (proj2 (TWell_arrow_inv D P1 P2 HTWP))).
      * apply (D_topr D (t_arrow P1 P2) Q HTWP HtopQ).
  - (* rcd int *)
    destruct (rcd_shape_ord D l A P HoP HAP) as [HtopP | (P2 & HeqP)].
    + apply (D_topl D P Q HTWQ HtopP).
    + subst P.
      destruct (algo_sub_ord_int_target D Q HoQ HBQ) as [HeqQ | HtopQ].
      * subst Q.
        apply (D_ax D (t_rcd l P2) t_int HTC HTWP HTWQ).
        apply Dax_rcdInt.
        apply (TWell_lc_typ D P2 (TWell_rcd_inv D l P2 HTWP)).
      * apply (D_topr D (t_rcd l P2) Q HTWP HtopQ).
  - (* all int *)
    destruct (all_shape_ord D A Bf P HoP HAP) as [HtopP | (P1 & P2 & HeqP)].
    + apply (D_topl D P Q HTWQ HtopP).
    + subst P.
      destruct (algo_sub_ord_int_target D Q HoQ HBQ) as [HeqQ | HtopQ].
      * subst Q.
        apply (D_ax D (t_forall P1 P2) t_int HTC HTWP HTWQ).
        apply Dax_allInt.
        -- apply (TWell_lc_typ D P1 (TWell_all_inv D P1 P2 HTWP)).
        -- apply (TWell_lc_typ D (t_forall P1 P2) HTWP).
      * apply (D_topr D (t_forall P1 P2) Q HTWP HtopQ).
  - (* rcd arrow *)
    destruct (rcd_shape_ord D l A P HoP HAP) as [HtopP | (P2 & HeqP)].
    + apply (D_topl D P Q HTWQ HtopP).
    + subst P.
      destruct (arrow_shape_ord D A1 A2 Q HoQ HBQ) as [HtopQ | (Q1 & Q2 & HeqQ)].
      * apply (D_topr D (t_rcd l P2) Q HTWP HtopQ).
      * subst Q.
        apply (D_ax D (t_rcd l P2) (t_arrow Q1 Q2) HTC HTWP HTWQ).
        apply Dax_rcdArrow.
        -- apply (TWell_lc_typ D P2 (TWell_rcd_inv D l P2 HTWP)).
        -- apply (TWell_lc_typ D Q1 (proj1 (TWell_arrow_inv D Q1 Q2 HTWQ))).
        -- apply (TWell_lc_typ D Q2 (proj2 (TWell_arrow_inv D Q1 Q2 HTWQ))).
  - (* all arrow *)
    destruct (all_shape_ord D A Bf P HoP HAP) as [HtopP | (P1 & P2 & HeqP)].
    + apply (D_topl D P Q HTWQ HtopP).
    + subst P.
      destruct (arrow_shape_ord D A1 A2 Q HoQ HBQ) as [HtopQ | (Q1 & Q2 & HeqQ)].
      * apply (D_topr D (t_forall P1 P2) Q HTWP HtopQ).
      * subst Q.
        apply (D_ax D (t_forall P1 P2) (t_arrow Q1 Q2) HTC HTWP HTWQ).
        apply Dax_allArrow.
        -- apply (TWell_lc_typ D P1 (TWell_all_inv D P1 P2 HTWP)).
        -- apply (TWell_lc_typ D (t_forall P1 P2) HTWP).
        -- apply (TWell_lc_typ D Q1 (proj1 (TWell_arrow_inv D Q1 Q2 HTWQ))).
        -- apply (TWell_lc_typ D Q2 (proj2 (TWell_arrow_inv D Q1 Q2 HTWQ))).
  - (* all rcd *)
    destruct (all_shape_ord D A Bf P HoP HAP) as [HtopP | (P1 & P2 & HeqP)].
    + apply (D_topl D P Q HTWQ HtopP).
    + subst P.
      destruct (rcd_shape_ord D l C Q HoQ HBQ) as [HtopQ | (Q2 & HeqQ)].
      * apply (D_topr D (t_forall P1 P2) Q HTWP HtopQ).
      * subst Q.
        apply (D_ax D (t_forall P1 P2) (t_rcd l Q2) HTC HTWP HTWQ).
        apply Dax_allRcd.
        -- apply (TWell_lc_typ D P1 (TWell_all_inv D P1 P2 HTWP)).
        -- apply (TWell_lc_typ D (t_forall P1 P2) HTWP).
        -- apply (TWell_lc_typ D Q2 (TWell_rcd_inv D l Q2 HTWQ)).
  - (* rcd neq *)
    destruct (rcd_shape_ord D l1 A P HoP HAP) as [HtopP | (P2 & HeqP)].
    + apply (D_topl D P Q HTWQ HtopP).
    + subst P.
      destruct (rcd_shape_ord D l2 B Q HoQ HBQ) as [HtopQ | (Q2 & HeqQ)].
      * apply (D_topr D (t_rcd l1 P2) Q HTWP HtopQ).
      * subst Q.
        apply (D_ax D (t_rcd l1 P2) (t_rcd l2 Q2) HTC HTWP HTWQ).
        apply (Dax_rcdNeq l1 P2 l2 Q2).
        -- apply (TWell_lc_typ D P2 (TWell_rcd_inv D l1 P2 HTWP)).
        -- apply (TWell_lc_typ D Q2 (TWell_rcd_inv D l2 Q2 HTWQ)).
        -- exact Hneq.
Qed.

Lemma algo_sub_disjoint_ord_aux : forall (n:nat) (D:tctx) (A B P Q:typ),
  size_typ A + size_typ B + size_typ P + size_typ Q <= n ->
  TCWell D -> TWell D A -> TWell D B ->
  disjoint D A B ->
  algo_sub D A P -> algo_sub D B Q ->
  ord P -> ord Q -> TWell D P -> TWell D Q ->
  disjoint D P Q.
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D A B P Q Hle HTC HTA HTB Hd.
  destruct Hd as
    [ D0 A0 B0 HTC0 HTWA HTWB Hax
    | D0 A0 B0 HTWB HtopA
    | D0 A0 B0 HTWA HtopB
    | D0 A1 A2 B1 B2 HTWA HTWB Hd2
    | D0 l A0 B0 Hd2
    | L D0 A1 B1 A2 B2 HTWA1 HTWA2 Hbody
    | D0 X B0 A0 Hb Ha
    | D0 B0 X A0 Hb Ha
    | D0 A0 B0 A1 A2 Hspl Hd1 Hd2
    | D0 A0 B0 B1 B2 Hspl Hd1 Hd2 ];
    intros HAP HBQ HoP HoQ HTWP HTWQ.
  - (* D_ax *)
    exact (disjoint_axiom_ord_target D0 A0 B0 P Q Hax HTC0 HTWA HTWB
             HAP HBQ HoP HoQ HTWP HTWQ).
  - (* D_topl *)
    apply (D_topl D0 P Q HTWQ).
    exact (agentH.algo_sub_topLike_genH D0 A0 P HAP HtopA).
  - (* D_topr *)
    apply (D_topr D0 P Q HTWP).
    exact (agentH.algo_sub_topLike_genH D0 B0 Q HBQ HtopB).
  - (* D_arrow *)
    destruct (agentH.algo_sub_ord_arrow_target D0 A1 A2 P HoP HAP)
      as [HtopP | (P1 & P2 & HeqP & HAPdomP & HAP2 & HordP2)].
    + apply (D_topl D0 P Q HTWQ HtopP).
    + subst P.
      destruct (agentH.algo_sub_ord_arrow_target D0 B1 B2 Q HoQ HBQ)
        as [HtopQ | (Q1 & Q2 & HeqQ & HBQdomQ & HBQ2 & HordQ2)].
      * apply (D_topr D0 (t_arrow P1 P2) Q HTWP HtopQ).
      * subst Q.
        apply (D_arrow D0 P1 P2 Q1 Q2 HTWP HTWQ).
        assert (Hlt : size_typ A2 + size_typ B2 + size_typ P2 + size_typ Q2 < n)
          by (simpl in Hle; lia).
        exact (IH (size_typ A2 + size_typ B2 + size_typ P2 + size_typ Q2)
                 Hlt D0 A2 B2 P2 Q2 (le_n _) HTC
                 (proj2 (TWell_arrow_inv D0 A1 A2 HTWA))
                 (proj2 (TWell_arrow_inv D0 B1 B2 HTWB))
                 Hd2 HAP2 HBQ2 HordP2 HordQ2
                 (proj2 (TWell_arrow_inv D0 P1 P2 HTWP))
                 (proj2 (TWell_arrow_inv D0 Q1 Q2 HTWQ))).
  - (* D_rcdEq *)
    destruct (agentH.algo_sub_ord_rcd_target D0 l A0 P HoP HAP)
      as [HtopP | (P2 & HeqP & HAP2 & HordP2)].
    + apply (D_topl D0 P Q HTWQ HtopP).
    + subst P.
      destruct (agentH.algo_sub_ord_rcd_target D0 l B0 Q HoQ HBQ)
        as [HtopQ | (Q2 & HeqQ & HBQ2 & HordQ2)].
      * apply (D_topr D0 (t_rcd l P2) Q HTWP HtopQ).
      * subst Q.
        apply (D_rcdEq D0 l P2 Q2).
        assert (Hlt : size_typ A0 + size_typ B0 + size_typ P2 + size_typ Q2 < n)
          by (simpl in Hle; lia).
        exact (IH (size_typ A0 + size_typ B0 + size_typ P2 + size_typ Q2)
                 Hlt D0 A0 B0 P2 Q2 (le_n _) HTC
                 (TWell_rcd_inv D0 l A0 HTA)
                 (TWell_rcd_inv D0 l B0 HTB)
                 Hd2 HAP2 HBQ2 HordP2 HordQ2
                 (TWell_rcd_inv D0 l P2 HTWP)
                 (TWell_rcd_inv D0 l Q2 HTWQ)).
  - (* D_all *)
    destruct (agentH.algo_sub_ord_forall_target D0 A1 B1 P HoP HAP)
      as [HtopP | (L1 & P1 & P2 & HeqP & HAPdom & HAPbody & HordP2)].
    + apply (D_topl D0 P Q HTWQ HtopP).
    + subst P.
      destruct (agentH.algo_sub_ord_forall_target D0 A2 B2 Q HoQ HBQ)
        as [HtopQ | (L2 & Q1 & Q2 & HeqQ & HBQdom & HBQbody & HordQ2)].
      * apply (D_topr D0 (t_forall P1 P2) Q HTWP HtopQ).
      * subst Q.
        pose proof (TWell_all_inv D0 P1 P2 HTWP) as HTWP1.
        pose proof (TWell_all_inv D0 Q1 Q2 HTWQ) as HTWQ1.
        destruct (TWell_all_body D0 A1 B1 HTA) as (Lb1 & HB1).
        destruct (TWell_all_body D0 A2 B2 HTB) as (Lb2 & HB2).
        destruct (TWell_all_body D0 P1 P2 HTWP) as (Lp & HPb).
        destruct (TWell_all_body D0 Q1 Q2 HTWQ) as (Lq & HQb).
        pose (Lt := (((((((L \u L1) \u L2) \u dom D0) \u Lb1)
                        \u Lb2) \u Lp) \u Lq)).
        apply (D_all Lt D0 P1 P2 Q1 Q2 HTWP1 HTWQ1).
        intros X HX.
        unfold Lt in HX.
        destruct (notin_union X ((((((L \u L1) \u L2) \u dom D0) \u Lb1)
                     \u Lb2) \u Lp) Lq HX) as [HX1 HXLq].
        destruct (notin_union X (((((L \u L1) \u L2) \u dom D0) \u Lb1)
                     \u Lb2) Lp HX1) as [HX2 HXLp].
        destruct (notin_union X ((((L \u L1) \u L2) \u dom D0) \u Lb1)
                     Lb2 HX2) as [HX3 HXLb2].
        destruct (notin_union X (((L \u L1) \u L2) \u dom D0) Lb1 HX3)
          as [HX4 HXLb1].
        destruct (notin_union X ((L \u L1) \u L2) (dom D0) HX4)
          as [HX5 HXdom].
        destruct (notin_union X (L \u L1) L2 HX5) as [HX6 HXL2].
        destruct (notin_union X L L1 HX6) as [HXL HXL1].
        assert (HuniqOld : uniq ((X, t_and A1 A2) :: D0)).
        { apply uniq_cons; [ apply (TCWell_uniq D0 HTC) | exact HXdom ]. }
        assert (HTCold : TCWell ((X, t_and A1 A2) :: D0)).
        { apply (TCW_cons D0 X (t_and A1 A2) HTC).
          - apply TW_and; assumption.
          - exact HuniqOld. }
        assert (HuniqP : uniq ((X, P1) :: D0)).
        { apply uniq_cons; [ apply (TCWell_uniq D0 HTC) | exact HXdom ]. }
        assert (HTColdP : TCWell ((X, P1) :: D0)).
        { apply (TCW_cons D0 X P1 HTC HTWP1 HuniqP). }
        assert (HuniqQ : uniq ((X, Q1) :: D0)).
        { apply uniq_cons; [ apply (TCWell_uniq D0 HTC) | exact HXdom ]. }
        assert (HTColdQ : TCWell ((X, Q1) :: D0)).
        { apply (TCW_cons D0 X Q1 HTC HTWQ1 HuniqQ). }
        assert (Hrel : algo_sub D0 (t_and P1 Q1) (t_and A1 A2)).
        { apply (S_and D0 (t_and P1 Q1) (t_and A1 A2) A1 A2).
          - apply Sp_and.
            + apply (TWell_lc_typ D0 A1 HTWA1).
            + apply (TWell_lc_typ D0 A2 HTWA2).
          - apply (agentH.algo_sub_and_r_ctx D0 Q1 P1 A1 HTWQ1 HAPdom).
          - apply (agentH.algo_sub_and_l_ctx D0 P1 Q1 A2 HTWP1 HBQdom). }
        assert (HTCnew : TCWell ((X, t_and P1 Q1) :: D0)).
        { exact (agentH4.TCWell_ctx_change [] D0 X (t_and A1 A2)
                   (t_and P1 Q1) HTCold Hrel). }
        assert (HbodyX : disjoint ((X, t_and A1 A2) :: D0)
                           (B1 -^ X) (B2 -^ X)).
        { exact (Hbody X HXL). }
        assert (HsrcNew : disjoint ((X, t_and P1 Q1) :: D0)
                            (B1 -^ X) (B2 -^ X)).
        { apply (agentH4.disjoint_ctx_change [] D0 X (t_and A1 A2)
                   (t_and P1 Q1) (B1 -^ X) (B2 -^ X) HTCold Hrel HbodyX). }
        assert (HTWB1new : TWell ((X, t_and P1 Q1) :: D0) (B1 -^ X)).
        { apply (TWell_dom_irrel ((X, A1) :: D0) (B1 -^ X) (HB1 X HXLb1)
                   ((X, t_and P1 Q1) :: D0)). simpl. reflexivity. }
        assert (HTWB2new : TWell ((X, t_and P1 Q1) :: D0) (B2 -^ X)).
        { apply (TWell_dom_irrel ((X, A2) :: D0) (B2 -^ X) (HB2 X HXLb2)
                   ((X, t_and P1 Q1) :: D0)). simpl. reflexivity. }
        assert (HrelP : algo_sub D0 (t_and P1 Q1) P1).
        { apply (agentH.algo_sub_and_r_ctx D0 Q1 P1 P1 HTWQ1).
          apply (agentH.algo_sub_refl_TWell D0 P1 HTC HTWP1). }
        assert (HrelQ : algo_sub D0 (t_and P1 Q1) Q1).
        { apply (agentH.algo_sub_and_l_ctx D0 P1 Q1 Q1 HTWP1).
          apply (agentH.algo_sub_refl_TWell D0 Q1 HTC HTWQ1). }
        assert (HAPbodyX : algo_sub ((X, t_and P1 Q1) :: D0)
                             (B1 -^ X) (P2 -^ X)).
        { apply (agentH4.algo_sub_ctx_change [] D0 X P1 (t_and P1 Q1)
                   (B1 -^ X) (P2 -^ X) HTColdP HrelP).
          exact (HAPbody X HXL1). }
        assert (HBQbodyX : algo_sub ((X, t_and P1 Q1) :: D0)
                             (B2 -^ X) (Q2 -^ X)).
        { apply (agentH4.algo_sub_ctx_change [] D0 X Q1 (t_and P1 Q1)
                   (B2 -^ X) (Q2 -^ X) HTColdQ HrelQ).
          exact (HBQbody X HXL2). }
        assert (HTWPbody : TWell ((X, t_and P1 Q1) :: D0) (P2 -^ X)).
        { apply (TWell_dom_irrel ((X, P1) :: D0) (P2 -^ X) (HPb X HXLp)
                   ((X, t_and P1 Q1) :: D0)). simpl. reflexivity. }
        assert (HTWQbody : TWell ((X, t_and P1 Q1) :: D0) (Q2 -^ X)).
        { apply (TWell_dom_irrel ((X, Q1) :: D0) (Q2 -^ X) (HQb X HXLq)
                   ((X, t_and P1 Q1) :: D0)). simpl. reflexivity. }
        assert (Hlt : size_typ (B1 -^ X) + size_typ (B2 -^ X)
                    + size_typ (P2 -^ X) + size_typ (Q2 -^ X) < n).
        { rewrite !size_typ_open_typ. simpl in Hle. lia. }
        exact (IH (size_typ (B1 -^ X) + size_typ (B2 -^ X)
                   + size_typ (P2 -^ X) + size_typ (Q2 -^ X)) Hlt
                 ((X, t_and P1 Q1) :: D0) (B1 -^ X) (B2 -^ X)
                 (P2 -^ X) (Q2 -^ X) (le_n _)
                 HTCnew HTWB1new HTWB2new HsrcNew HAPbodyX HBQbodyX
                 (HordP2 X HXL1) (HordQ2 X HXL2) HTWPbody HTWQbody).
  - (* D_varl *)
    assert (HQ : algo_sub D0 A0 Q).
    { apply (agentH2.algo_sub_trans_TCWell D0 A0 B0 Q HTC); assumption. }
    inversion HAP; subst.
    all: try (apply (D_varl D0 X Q A0 Hb); exact HQ).
    all: try (apply (D_topl D0 P Q HTWQ); assumption).
    all: try (exfalso; eapply spl_not_ord; eassumption).
    all: try discriminate.
  - (* D_varr *)
    assert (HP : algo_sub D0 A0 P).
    { apply (agentH2.algo_sub_trans_TCWell D0 A0 B0 P HTC); assumption. }
    inversion HBQ; subst.
    all: try (apply (D_varr D0 P X A0 Hb); exact HP).
    all: try (apply (D_topr D0 P Q HTWP); assumption).
    all: try (exfalso; eapply spl_not_ord; eassumption).
    all: try discriminate.
  - (* D_andl *)
    destruct (agentH.spl_TWell_components D0 A0 A1 A2 HTA Hspl) as [HTA1 HTA2].
    destruct (agentH2.algo_sub_spl_source_or D0 A0 P HTC HAP A1 A2 Hspl HoP)
      as [HAP1 | HAP2].
    + assert (Hlt : size_typ A1 + size_typ B0 + size_typ P + size_typ Q < n).
      { destruct (spl_size_lt A0 A1 A2 Hspl) as [Hs1 _].
        simpl in Hle. lia. }
      exact (IH (size_typ A1 + size_typ B0 + size_typ P + size_typ Q)
               Hlt D0 A1 B0 P Q (le_n _) HTC HTA1 HTB Hd1
               HAP1 HBQ HoP HoQ HTWP HTWQ).
    + assert (Hlt : size_typ A2 + size_typ B0 + size_typ P + size_typ Q < n).
      { destruct (spl_size_lt A0 A1 A2 Hspl) as [_ Hs2].
        simpl in Hle. lia. }
      exact (IH (size_typ A2 + size_typ B0 + size_typ P + size_typ Q)
               Hlt D0 A2 B0 P Q (le_n _) HTC HTA2 HTB Hd2
               HAP2 HBQ HoP HoQ HTWP HTWQ).
  - (* D_andr *)
    destruct (agentH.spl_TWell_components D0 B0 B1 B2 HTB Hspl) as [HTB1 HTB2].
    destruct (agentH2.algo_sub_spl_source_or D0 B0 Q HTC HBQ B1 B2 Hspl HoQ)
      as [HBQ1 | HBQ2].
    + assert (Hlt : size_typ A0 + size_typ B1 + size_typ P + size_typ Q < n).
      { destruct (spl_size_lt B0 B1 B2 Hspl) as [Hs1 _].
        simpl in Hle. lia. }
      exact (IH (size_typ A0 + size_typ B1 + size_typ P + size_typ Q)
               Hlt D0 A0 B1 P Q (le_n _) HTC HTA HTB1 Hd1
               HAP HBQ1 HoP HoQ HTWP HTWQ).
    + assert (Hlt : size_typ A0 + size_typ B2 + size_typ P + size_typ Q < n).
      { destruct (spl_size_lt B0 B1 B2 Hspl) as [_ Hs2].
        simpl in Hle. lia. }
      exact (IH (size_typ A0 + size_typ B2 + size_typ P + size_typ Q)
               Hlt D0 A0 B2 P Q (le_n _) HTC HTA HTB2 Hd2
               HAP HBQ2 HoP HoQ HTWP HTWQ).
Qed.

Lemma algo_sub_disjoint_ord : forall (D:tctx) (A B P Q:typ),
  TCWell D -> TWell D A -> TWell D B ->
  disjoint D A B ->
  algo_sub D A P -> algo_sub D B Q ->
  ord P -> ord Q -> TWell D P -> TWell D Q ->
  disjoint D P Q.
Proof.
  intros. exact (algo_sub_disjoint_ord_aux
    (size_typ A + size_typ B + size_typ P + size_typ Q)
    D A B P Q (le_n _) H H0 H1 H2 H3 H4 H5 H6 H7 H8).
Qed.

Lemma merge_inf_components : forall (v1 v2:exp) (C:typ),
  Typing nil nil (e_merge v1 v2) Inf C ->
  exists A B, C = t_and A B /\
              Typing nil nil v1 Inf A /\ Typing nil nil v2 Inf B.
Proof.
  intros v1 v2 C H. inversion H; subst.
  - exists A, B. repeat split; assumption.
  - exists A, B. repeat split; assumption.
Qed.

Inductive src_compat (A:typ) : exp -> typ -> Prop :=
 | SC_top : forall v P, topLike nil P -> src_compat A v P
 | SC_alg : forall v P, algo_sub nil A P -> ord P -> TWell nil P ->
               src_compat A v P
 | SC_merge : forall v1 v2 P1 P2,
               src_compat A v1 P1 -> src_compat A v2 P2 ->
               src_compat A (e_merge v1 v2) (t_and P1 P2).
Arguments SC_top {A} v P _.
Arguments SC_alg {A} v P _ _ _.
Arguments SC_merge {A} v1 v2 P1 P2 _ _.

Definition compat_weight (d:exp) (P:typ) (e:exp) (Q:typ) : nat :=
  size_exp d + size_typ P + size_exp e + size_typ Q.

Lemma src_compat_add_right : forall (A1 A2:typ) (v:exp) (P:typ),
  TWell nil A2 -> src_compat A1 v P -> src_compat (t_and A1 A2) v P.
Proof.
  intros A1 A2 v P HTW2 H. induction H.
  - apply (SC_top v P). assumption.
  - apply (SC_alg v P).
    + apply (agentH.algo_sub_and_r_ctx nil A2 A1 P HTW2 H).
    + assumption.
    + assumption.
  - apply (SC_merge v1 v2 P1 P2); assumption.
Qed.

Lemma src_compat_add_left : forall (A1 A2:typ) (v:exp) (P:typ),
  TWell nil A1 -> src_compat A2 v P -> src_compat (t_and A1 A2) v P.
Proof.
  intros A1 A2 v P HTW1 H. induction H.
  - apply (SC_top v P). assumption.
  - apply (SC_alg v P).
    + apply (agentH.algo_sub_and_l_ctx nil A1 A2 P HTW1 H).
    + assumption.
    + assumption.
  - apply (SC_merge v1 v2 P1 P2); assumption.
Qed.

Lemma casting_type_compat : forall (v:exp) (A:typ) (d:exp) (D:typ),
  Typing nil nil v Inf A ->
  casting v D d ->
  forall P, pType d P -> TWell nil P -> src_compat A d P.
Proof.
  intros v A d D Hty Hc. revert A Hty.
  induction Hc as
    [ i
    | v0 Hlc
    | v0 A1 A2 Hlc Hord Htop
    | v0 A1 A2 Hlc Hord Htop
    | v0 l A0 Hlc Hord Htop
    | e A0 B Hlc Hord Hntl Hsub
    | v1 v2 A0 v1' Hlc Hord Hc1 IH1
    | v1 v2 A0 v2' Hlc Hord Hc2 IH2
    | v0 A0 v1 v2 B C Hspl Hc1 IH1 Hc2 IH2 ];
    intros A0src Hty P Hp HTW.
  - inversion Hty; subst.
    apply agentE2.pType_lit_inv in Hp. subst P.
    apply (SC_alg (e_lit i) t_int);
      [ apply (S_int nil TCW_empty) | apply O_int | apply TW_int ].
  - apply agentE2.pType_top_inv in Hp. subst P.
    apply (SC_top e_top t_top). apply TL_top. apply TCW_empty.
  - apply agentE2.pType_anno_inv in Hp. subst P.
    apply (SC_top (e_anno (e_abs t_top e_top) (t_arrow A1 A2)) (t_arrow A1 A2)).
    exact Htop.
  - apply agentE2.pType_anno_inv in Hp. subst P.
    apply (SC_top (e_anno (e_tabs e_top) (t_forall A1 A2)) (t_forall A1 A2)).
    exact Htop.
  - apply agentE2.pType_anno_inv in Hp. subst P.
    apply (SC_top (e_anno (e_rcd l e_top) (t_rcd l A0)) (t_rcd l A0)).
    exact Htop.
  - inversion Hty; subst.
    apply agentE2.pType_anno_inv in Hp. subst P.
    apply (SC_alg (e_anno e B) B); assumption.
  - destruct (merge_inf_components v1 v2 A0src Hty)
      as (B1 & B2 & Heq & Ht1 & Ht2). inversion Heq; subst.
    apply (src_compat_add_right B1 B2 v1' P).
    + exact (agentI2.typing_TWell v2 Inf B2 Ht2).
    + exact (IH1 B1 Ht1 P Hp HTW).
  - destruct (merge_inf_components v1 v2 A0src Hty)
      as (B1 & B2 & Heq & Ht1 & Ht2). inversion Heq; subst.
    apply (src_compat_add_left B1 B2 v2' P).
    + exact (agentI2.typing_TWell v1 Inf B1 Ht1).
    + exact (IH2 B2 Ht2 P Hp HTW).
  - apply agentE2.pType_merge_inv in Hp.
    destruct Hp as (P1 & P2 & Heq & Hp1 & Hp2). subst P.
    destruct (TWell_and_inv nil P1 P2 HTW) as [HTW1 HTW2].
    apply (SC_merge v1 v2 P1 P2).
    + exact (IH1 A0src Hty P1 Hp1 HTW1).
    + exact (IH2 A0src Hty P2 Hp2 HTW2).
Qed.

Lemma casting_pType_compat : forall (v:exp) (A:typ) (d:exp) (D:typ),
  pType v A -> TWell nil A ->
  casting v D d ->
  forall P, pType d P -> TWell nil P -> src_compat A d P.
Proof.
  intros v A d D Hpt HTWA Hc. revert A Hpt HTWA.
  induction Hc as
    [ i
    | v0 Hlc
    | v0 A1 A2 Hlc Hord Htop
    | v0 A1 A2 Hlc Hord Htop
    | v0 l A0 Hlc Hord Htop
    | e A0 B Hlc Hord Hntl Hsub
    | v1 v2 A0 v1' Hlc Hord Hc1 IH1
    | v1 v2 A0 v2' Hlc Hord Hc2 IH2
    | v0 A0 v1 v2 B C Hspl Hc1 IH1 Hc2 IH2 ];
    intros A0src Hpt HTWA P Hp HTW.
  - apply agentE2.pType_lit_inv in Hpt. subst A0src.
    apply agentE2.pType_lit_inv in Hp. subst P.
    apply (SC_alg (e_lit i) t_int);
      [ apply (S_int nil TCW_empty) | apply O_int | apply TW_int ].
  - apply agentE2.pType_top_inv in Hp. subst P.
    apply (SC_top e_top t_top). apply TL_top. apply TCW_empty.
  - apply agentE2.pType_anno_inv in Hp. subst P.
    apply (SC_top (e_anno (e_abs t_top e_top) (t_arrow A1 A2)) (t_arrow A1 A2)).
    exact Htop.
  - apply agentE2.pType_anno_inv in Hp. subst P.
    apply (SC_top (e_anno (e_tabs e_top) (t_forall A1 A2)) (t_forall A1 A2)).
    exact Htop.
  - apply agentE2.pType_anno_inv in Hp. subst P.
    apply (SC_top (e_anno (e_rcd l e_top) (t_rcd l A0)) (t_rcd l A0)).
    exact Htop.
  - apply agentE2.pType_anno_inv in Hpt. subst A0src.
    apply agentE2.pType_anno_inv in Hp. subst P.
    apply (SC_alg (e_anno e B) B); assumption.
  - destruct (agentE2.pType_merge_inv v1 v2 A0src Hpt)
      as (B1 & B2 & Heq & Ht1 & Ht2). inversion Heq; subst.
    destruct (TWell_and_inv nil B1 B2 HTWA) as [HTW1 HTW2].
    apply (src_compat_add_right B1 B2 v1' P).
    + exact HTW2.
    + exact (IH1 B1 Ht1 HTW1 P Hp HTW).
  - destruct (agentE2.pType_merge_inv v1 v2 A0src Hpt)
      as (B1 & B2 & Heq & Ht1 & Ht2). inversion Heq; subst.
    destruct (TWell_and_inv nil B1 B2 HTWA) as [HTW1 HTW2].
    apply (src_compat_add_left B1 B2 v2' P).
    + exact HTW1.
    + exact (IH2 B2 Ht2 HTW2 P Hp HTW).
  - apply agentE2.pType_merge_inv in Hp.
    destruct Hp as (P1 & P2 & Heq & Hp1 & Hp2). subst P.
    destruct (TWell_and_inv nil P1 P2 HTW) as [HTW1 HTW2].
    apply (SC_merge v1 v2 P1 P2).
    + exact (IH1 A0src Hpt HTWA P1 Hp1 HTW1).
    + exact (IH2 A0src Hpt HTWA P2 Hp2 HTW2).
Qed.

(*** Cross-source consistency ***)

Lemma consistent_of_src_compat_aux :
  forall (n:nat) (A B:typ) (d e:exp) (P Q:typ),
    TWell nil A -> TWell nil B -> disjoint nil A B ->
    forall (HPC:src_compat A d P) (HQC:src_compat B e Q),
      compat_weight d P e Q <= n ->
      pType d P -> pType e Q -> TWell nil P -> TWell nil Q ->
      consistent d e.
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros A B d e P Q HTWA HTWB HD HPC.
  destruct HPC as [ d0 P0 Htop | d0 P0 Halg HordP HTWP | d1 d2 P1 P2 HPC1 HPC2 ].
  - (* SC_top on the left *)
    intros HQC Hle Hpd Hpe HTWP0 HTWQ.
    apply (C_disjoint d0 e P0 Q Hpd Hpe).
    + apply (D_topl nil P0 Q HTWQ Htop).
    + apply agentE2.pType_prevalue with (A := P0). exact Hpd.
    + apply agentE2.pType_prevalue with (A := Q). exact Hpe.
  - (* SC_alg on the left *)
    intros HQC Hle Hpd Hpe HTWPdup HTWQ.
    destruct HQC as [ e0 Q0 Htop | e0 Q0 HalgQ HordQ HTWQ0 | e1 e2 Q1 Q2 HQC1 HQC2 ].
    + (* SC_top on the right *)
      apply (C_disjoint d0 e0 P0 Q0 Hpd Hpe).
      * apply (D_topr nil P0 Q0 HTWP Htop).
      * apply agentE2.pType_prevalue with (A := P0). exact Hpd.
      * apply agentE2.pType_prevalue with (A := Q0). exact Hpe.
    + (* SC_alg / SC_alg *)
      apply (C_disjoint d0 e0 P0 Q0 Hpd Hpe).
      * apply (algo_sub_disjoint_ord nil A B P0 Q0 TCW_empty HTWA HTWB HD
                 Halg HalgQ HordP HordQ HTWP HTWQ0).
      * apply agentE2.pType_prevalue with (A := P0). exact Hpd.
      * apply agentE2.pType_prevalue with (A := Q0). exact Hpe.
    + (* SC_alg left / SC_merge right *)
      destruct (agentE2.pType_merge_inv e1 e2 (t_and Q1 Q2) Hpe)
        as (R1 & R2 & Heq & Hpe1 & Hpe2). inversion Heq; subst.
      destruct (TWell_and_inv nil R1 R2 HTWQ) as [HTWQ1 HTWQ2].
      apply C_merger.
      * assert (Hlt1 : compat_weight d0 P0 e1 R1 < n).
        { unfold compat_weight in *. simpl in *.
          pose proof (size_exp_pos e2). pose proof (size_typ_pos R2). lia. }
        exact (IH (compat_weight d0 P0 e1 R1) Hlt1
                 A B d0 e1 P0 R1 HTWA HTWB HD
                 (SC_alg d0 P0 Halg HordP HTWP) HQC1 (le_n _)
                 Hpd Hpe1 HTWP HTWQ1).
      * assert (Hlt2 : compat_weight d0 P0 e2 R2 < n).
        { unfold compat_weight in *. simpl in *.
          pose proof (size_exp_pos e1). pose proof (size_typ_pos R1). lia. }
        exact (IH (compat_weight d0 P0 e2 R2) Hlt2
                 A B d0 e2 P0 R2 HTWA HTWB HD
                 (SC_alg d0 P0 Halg HordP HTWP) HQC2 (le_n _)
                 Hpd Hpe2 HTWP HTWQ2).
  - (* SC_merge on the left *)
    intros HQC Hle Hpd Hpe HTWP HTWQ.
    destruct (agentE2.pType_merge_inv d1 d2 (t_and P1 P2) Hpd)
      as (S1 & S2 & Heq & Hpd1 & Hpd2). inversion Heq; subst.
    destruct (TWell_and_inv nil S1 S2 HTWP) as [HTWP1 HTWP2].
    apply (C_mergel d1 d2 e).
    + assert (Hlt1 : compat_weight d1 S1 e Q < n).
      { unfold compat_weight in *. simpl in *.
        pose proof (size_exp_pos d2). pose proof (size_typ_pos S2). lia. }
      exact (IH (compat_weight d1 S1 e Q) Hlt1
               A B d1 e S1 Q HTWA HTWB HD HPC1 HQC (le_n _)
               Hpd1 Hpe HTWP1 HTWQ).
    + assert (Hlt2 : compat_weight d2 S2 e Q < n).
      { unfold compat_weight in *. simpl in *.
        pose proof (size_exp_pos d1). pose proof (size_typ_pos S1). lia. }
      exact (IH (compat_weight d2 S2 e Q) Hlt2
               A B d2 e S2 Q HTWA HTWB HD HPC2 HQC (le_n _)
               Hpd2 Hpe HTWP2 HTWQ).
Qed.

Lemma consistent_of_src_compat :
  forall (A B:typ) (d e:exp) (P Q:typ),
    TWell nil A -> TWell nil B -> disjoint nil A B ->
    src_compat A d P -> src_compat B e Q ->
    pType d P -> pType e Q -> TWell nil P -> TWell nil Q ->
    consistent d e.
Proof.
  intros A B d e P Q HTWA HTWB HD HPC HQC Hpd Hpe HTWP HTWQ.
  exact (consistent_of_src_compat_aux
           (compat_weight d P e Q)
           A B d e P Q HTWA HTWB HD HPC HQC (le_n _) Hpd Hpe HTWP HTWQ).
Qed.

Lemma consistent_toplike_r_gen : forall (u1 u2:exp) (T1 T2:typ),
  pType u1 T1 -> TWell nil T1 -> topLike nil T2 -> pType u2 T2 ->
  prevalue u1 -> prevalue u2 -> consistent u1 u2.
Proof.
  intros u1 u2 T1 T2 Hp1 HTW1 Htop Hp2 HP1 HP2.
  apply (C_disjoint u1 u2 T1 T2); auto.
  apply (D_topr nil T1 T2); auto.
Qed.

Lemma casting_output_pType_TWell : forall (v:exp) (D:typ) (v':exp),
  casting v D v' -> exists P, pType v' P /\ TWell nil P.
Proof.
  intros v D v' Hc.
  destruct (agentE2.casting_pType_subsub v D v' Hc) as (P & Hp & Hss).
  exists P. split; [ exact Hp | exact (casting_pType_TWell v D v' Hc P Hp) ].
Qed.

Lemma casting_consistent_consistent :
  forall (u w:exp), consistent u w ->
  forall (D:typ) (u':exp),
    casting u D u' ->
  forall (E:typ) (w':exp),
    casting w E w' -> consistent u' w'.
Proof.
  intros u w Hc.
  induction Hc as
    [ i
    | e A B HlcA Hlce HlcB
    | u0 w0 A B Hpu Hpw Hd Hpvu Hpvw
    | u1 u2 u0 Hcu1 IH1 Hcu2 IH2
    | u0 u1 u2 Hcu1 IH1 Hcu2 IH2 ];
    intros D u' Hcast E w' Hcastw.
  - (* lit *)
    apply (lit_value_consistent i u' w').
    + exact (casting_lit_value i D u' Hcast).
    + exact (casting_lit_value i E w' Hcastw).
  - (* anno *)
    apply (anno_value_consistent e u' w').
    + exact (casting_anno_value e A D u' Hcast).
    + exact (casting_anno_value e B E w' Hcastw).
  - (* disjoint *)
    assert (HTWA : TWell nil A) by
      (apply (agentI2.disjoint_TWell_l nil A B TCW_empty); exact Hd).
    assert (HTWB : TWell nil B) by
      (apply (agentL.disjoint_TWell_target_L nil A B TCW_empty); exact Hd).
    destruct (casting_output_pType_TWell u0 D u' Hcast) as (P & HpP & HTWP).
    destruct (casting_output_pType_TWell w0 E w' Hcastw) as (Q & HpQ & HTWQ).
    assert (HCu : src_compat A u' P) by
      (apply (casting_pType_compat u0 A u' D Hpu HTWA Hcast P HpP HTWP)).
    assert (HCw : src_compat B w' Q) by
      (apply (casting_pType_compat w0 B w' E Hpw HTWB Hcastw Q HpQ HTWQ)).
    exact (consistent_of_src_compat A B u' w' P Q HTWA HTWB Hd HCu HCw
             HpP HpQ HTWP HTWQ).
  - (* mergel: u = e_merge u1 u2, w = u0 *)
    assert (Haux : forall (n:nat) (D:typ) (u':exp),
              size_exp (e_merge u1 u2) + size_typ D <= n ->
              casting (e_merge u1 u2) D u' ->
              forall (E:typ) (w':exp), casting u0 E w' -> consistent u' w').
    { intros n. induction n as [|n IHn].
      - intros D0 u0' Hle Hc0 E0 w0' Hcw. exfalso.
        pose proof (size_exp_pos (e_merge u1 u2)). pose proof (size_typ_pos D0). lia.
      - intros D0 u0' Hle Hc0 E0 w0' Hcw.
        dependent destruction Hc0.
      + (* Cast_top *)
        destruct (casting_output_pType_TWell u0 E0 w0' Hcw) as (Q & HpQ & HTWQ).
        apply (consistent_toplike_l_gen e_top w0' t_top Q).
        * apply (TL_top nil TCW_empty).
        * apply PT_top.
        * exact HpQ.
        * exact HTWQ.
        * apply PV_top.
        * apply agentE2.pType_prevalue with (A := Q). exact HpQ.
      + (* Cast_topArrow *)
        destruct (casting_output_pType_TWell u0 E0 w0' Hcw) as (Q & HpQ & HTWQ).
        apply (consistent_toplike_l_gen
                 (e_anno (e_abs t_top e_top) (t_arrow A1 A2)) w0'
                 (t_arrow A1 A2) Q).
        * exact H1.
        * apply PT_anno; [ apply agentE2.lc_exp_abs_top_top | apply ord_lc_typ; exact H0 ].
        * exact HpQ.
        * exact HTWQ.
        * apply PV_anno; [ apply agentE2.lc_exp_abs_top_top | apply ord_lc_typ; exact H0 ].
        * apply agentE2.pType_prevalue with (A := Q). exact HpQ.
      + (* Cast_topAll *)
        destruct (casting_output_pType_TWell u0 E0 w0' Hcw) as (Q & HpQ & HTWQ).
        apply (consistent_toplike_l_gen
                 (e_anno (e_tabs e_top) (t_forall A1 A2)) w0'
                 (t_forall A1 A2) Q).
        * exact H1.
        * apply PT_anno; [ apply agentE2.lc_exp_tabs_top | apply ord_lc_typ; exact H0 ].
        * exact HpQ.
        * exact HTWQ.
        * apply PV_anno; [ apply agentE2.lc_exp_tabs_top | apply ord_lc_typ; exact H0 ].
        * apply agentE2.pType_prevalue with (A := Q). exact HpQ.
      + (* Cast_topRcd *)
        destruct (casting_output_pType_TWell u0 E0 w0' Hcw) as (Q & HpQ & HTWQ).
        apply (consistent_toplike_l_gen
                 (e_anno (e_rcd l e_top) (t_rcd l A)) w0'
                 (t_rcd l A) Q).
        * exact H1.
        * apply PT_anno; [ apply lc_e_rcd; apply lc_e_top | apply ord_lc_typ; exact H0 ].
        * exact HpQ.
        * exact HTWQ.
        * apply PV_anno; [ apply lc_e_rcd; apply lc_e_top | apply ord_lc_typ; exact H0 ].
        * apply agentE2.pType_prevalue with (A := Q). exact HpQ.
      + (* Cast_mergel *)
        exact (IH1 A v1' Hc0 E0 w0' Hcw).
      + (* Cast_merger *)
        exact (IH2 A v2' Hc0 E0 w0' Hcw).
      + (* Cast_and *)
        destruct (agentH.spl_size_ltH A B C H) as [HltB HltC].
        apply (C_mergel v1 v2 w0').
        * assert (HleB : size_exp (e_merge u1 u2) + size_typ B <= n) by lia.
          exact (IHn B v1 HleB Hc0_1 E0 w0' Hcw).
        * assert (HleC : size_exp (e_merge u1 u2) + size_typ C <= n) by lia.
          exact (IHn C v2 HleC Hc0_2 E0 w0' Hcw). }
    exact (Haux (size_exp (e_merge u1 u2) + size_typ D) D u' (le_n _) Hcast E w' Hcastw).
  - (* merger: u = u0, w = e_merge u1 u2 *)
    assert (Haux : forall (n:nat) (D:typ) (u':exp),
              casting u0 D u' ->
              forall (E:typ) (w':exp),
                size_exp (e_merge u1 u2) + size_typ E <= n ->
                casting (e_merge u1 u2) E w' -> consistent u' w').
    { intros n. induction n as [|n IHn].
      - intros D0 u0' Hc0 E0 w0' Hle Hc1. exfalso.
        pose proof (size_exp_pos (e_merge u1 u2)). pose proof (size_typ_pos E0). lia.
      - intros D0 u0' Hc0 E0 w0' Hle Hc1.
        dependent destruction Hc1.
      + (* Cast_top *)
        destruct (casting_output_pType_TWell u0 D0 u0' Hc0) as (P & HpP & HTWP).
        apply (consistent_toplike_r_gen u0' e_top P t_top HpP HTWP).
        * apply (TL_top nil TCW_empty).
        * apply PT_top.
        * apply agentE2.pType_prevalue with (A := P). exact HpP.
        * apply PV_top.
      + (* Cast_topArrow *)
        destruct (casting_output_pType_TWell u0 D0 u0' Hc0) as (P & HpP & HTWP).
        apply (consistent_toplike_r_gen u0'
                 (e_anno (e_abs t_top e_top) (t_arrow A1 A2)) P (t_arrow A1 A2)
                 HpP HTWP).
        * exact H1.
        * apply PT_anno; [ apply agentE2.lc_exp_abs_top_top | apply ord_lc_typ; exact H0 ].
        * apply agentE2.pType_prevalue with (A := P). exact HpP.
        * apply PV_anno; [ apply agentE2.lc_exp_abs_top_top | apply ord_lc_typ; exact H0 ].
      + (* Cast_topAll *)
        destruct (casting_output_pType_TWell u0 D0 u0' Hc0) as (P & HpP & HTWP).
        apply (consistent_toplike_r_gen u0'
                 (e_anno (e_tabs e_top) (t_forall A1 A2)) P (t_forall A1 A2)
                 HpP HTWP).
        * exact H1.
        * apply PT_anno; [ apply agentE2.lc_exp_tabs_top | apply ord_lc_typ; exact H0 ].
        * apply agentE2.pType_prevalue with (A := P). exact HpP.
        * apply PV_anno; [ apply agentE2.lc_exp_tabs_top | apply ord_lc_typ; exact H0 ].
      + (* Cast_topRcd *)
        destruct (casting_output_pType_TWell u0 D0 u0' Hc0) as (P & HpP & HTWP).
        apply (consistent_toplike_r_gen u0'
                 (e_anno (e_rcd l e_top) (t_rcd l A)) P (t_rcd l A)
                 HpP HTWP).
        * exact H1.
        * apply PT_anno; [ apply lc_e_rcd; apply lc_e_top | apply ord_lc_typ; exact H0 ].
        * apply agentE2.pType_prevalue with (A := P). exact HpP.
        * apply PV_anno; [ apply lc_e_rcd; apply lc_e_top | apply ord_lc_typ; exact H0 ].
      + (* Cast_mergel *)
        exact (IH1 D0 u0' Hc0 A v1' Hc1).
      + (* Cast_merger *)
        exact (IH2 D0 u0' Hc0 A v2' Hc1).
      + (* Cast_and *)
        destruct (agentH.spl_size_ltH A B C H) as [HltB HltC].
        apply (C_merger u0' v1 v2).
        * assert (HleB : size_exp (e_merge u1 u2) + size_typ B <= n) by lia.
          exact (IHn D0 u0' Hc0 B v1 HleB Hc1_1).
        * assert (HleC : size_exp (e_merge u1 u2) + size_typ C <= n) by lia.
          exact (IHn D0 u0' Hc0 C v2 HleC Hc1_2). }
    exact (Haux (size_exp (e_merge u1 u2) + size_typ E) D u' Hcast E w' (le_n _) Hcastw).
Qed.
Lemma algo_sub_TCWell : forall D A B, algo_sub D A B -> TCWell D.
Proof.
  intros D A B H. induction H as
    [ D0 X HTC HTW
    | D0 HTC
    | D0 A0 B0 HTW Hord Htop
    | D0 A0 HTC HTW Hord
    | D0 A0 B0 C0 HTWB Hord Hsub IH
    | D0 A0 B0 C0 HTWA Hord Hsub IH
    | D0 A1 B1 A2 B2 Hord Hsub1 IH1 Hsub2 IH2
    | L D0 A1 A2 B1 B2 Hords Hsub1 IH1 Hbody IHBODY
    | D0 l A0 B0 Hord Hsub IH
    | D0 A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2 ].
  - exact HTC.
  - exact HTC.
  - exact (agentA.topLike_TCWell D0 B0 Htop).
  - exact HTC.
  - exact IH.
  - exact IH.
  - exact IH1.
  - exact IH1.
  - exact IH.
  - exact IH1.
Qed.

Lemma disjoint_TCWell : forall D A B, disjoint D A B -> TCWell D.
Proof.
  intros D A B H. induction H as
    [D0 A0 B0 HTC0 HTA HTB Hax
    |D0 A0 B0 HTB HtopA
    |D0 A0 B0 HTA HtopB
    |D0 A1 A2 B1 B2 HT1 HT2 Hsub IHsub
    |D0 l A0 B0 Hsub IHsub
    |L D0 A1 B1 A2 B2 HT1 HT2 Hbody IHBODY
    |D0 X B0 A0 Hb Hsub
    |D0 B0 X A0 Hb Hsub
    |D0 A0 B0 A1 A2 Hspl Hsub1 IH1 Hsub2 IH2
    |D0 A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2 ].
  - exact HTC0.
  - exact (agentA.topLike_TCWell D0 A0 HtopA).
  - exact (agentA.topLike_TCWell D0 B0 HtopB).
  - exact IHsub.
  - exact IHsub.
  - destruct (atom_fresh (L \u dom D0)) as [X HX].
    apply (agentA.TCWell_cons_inv D0 X (t_and A1 A2)).
    apply (IHBODY X).
    exact (proj1 (agentA.notin_union X L (dom D0) HX)).
  - exact (algo_sub_TCWell D0 A0 B0 Hsub).
  - exact (algo_sub_TCWell D0 A0 B0 Hsub).
  - exact IH1.
  - exact IH1.
Qed.

Lemma disjoint_axiom_sym : forall A B, disjoint_axiom A B -> disjoint_axiom B A.
Proof.
  intros A B H. inversion H; subst.
  - apply Dax_arrowInt; assumption.
  - apply Dax_rcdInt; assumption.
  - apply Dax_allInt; assumption.
  - apply Dax_rcdArrow; assumption.
  - apply Dax_allArrow; assumption.
  - apply Dax_allRcd; assumption.
  - apply Dax_intArrow; assumption.
  - apply Dax_intRcd; assumption.
  - apply Dax_intAll; assumption.
  - apply Dax_arrowRcd; assumption.
  - apply Dax_arrowAll; assumption.
  - apply Dax_rcdAll; assumption.
  - apply Dax_rcdNeq; try assumption; intro Heq; exact (H2 (eq_sym Heq)).
Qed.

Lemma disjoint_sym : forall D A B, disjoint D A B -> disjoint D B A.
Proof.
  intros D A B H. induction H as
    [D0 A0 B0 HTC0 HTA HTB Hax
    |D0 A0 B0 HTB HtopA
    |D0 A0 B0 HTA HtopB
    |D0 A1 A2 B1 B2 HT1 HT2 Hsub IHsub
    |D0 l A0 B0 Hsub IHsub
    |L D0 A1 B1 A2 B2 HT1 HT2 Hbody IHBODY
    |D0 X B0 A0 Hb Hsub
    |D0 B0 X A0 Hb Hsub
    |D0 A0 B0 A1 A2 Hspl Hsub1 IH1 Hsub2 IH2
    |D0 A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2 ].
  - apply (D_ax D0 B0 A0 HTC0 HTB HTA).
    apply disjoint_axiom_sym. exact Hax.
  - apply (D_topr D0 B0 A0 HTB HtopA).
  - apply (D_topl D0 B0 A0 HTA HtopB).
  - apply (D_arrow D0 B1 B2 A1 A2 HT2 HT1 IHsub).
  - apply (D_rcdEq D0 l B0 A0 IHsub).
  - apply (D_all (L \u dom D0) D0 A2 B2 A1 B1 HT2 HT1).
    intros X HX.
    destruct (agentA.notin_union X L (dom D0) HX) as [HXL HXD].
    assert (HTCx : TCWell (cons (X, t_and A1 A2) D0))
      by (exact (disjoint_TCWell (cons (X, t_and A1 A2) D0)
                  (open_typ_wrt_typ B1 (t_tvar_f X))
                  (open_typ_wrt_typ B2 (t_tvar_f X))
                  (Hbody X HXL))).
    assert (HTC0 : TCWell D0) by (apply (agentA.TCWell_cons_inv D0 X (t_and A1 A2)); exact HTCx).
    assert (Hsw : disjoint (cons (X, t_and A1 A2) D0)
                       (open_typ_wrt_typ B2 (t_tvar_f X))
                       (open_typ_wrt_typ B1 (t_tvar_f X)))
      by (apply (IHBODY X HXL)).
    assert (Hrel : algo_sub D0 (t_and A2 A1) (t_and A1 A2)).
    { apply (S_and D0 (t_and A2 A1) (t_and A1 A2) A1 A2).
      - apply Sp_and.
        + apply (agentA.TWell_lc_typ D0 A1 HT1).
        + apply (agentA.TWell_lc_typ D0 A2 HT2).
      - apply (agentH.algo_sub_and_l_ctx D0 A2 A1 A1 HT2).
        apply (agentH.algo_sub_refl_TWell D0 A1 HTC0 HT1).
      - apply (agentH.algo_sub_and_r_ctx D0 A1 A2 A2 HT1).
        apply (agentH.algo_sub_refl_TWell D0 A2 HTC0 HT2). }
    change (disjoint (nil ++ (X, t_and A2 A1) :: D0)
              (open_typ_wrt_typ B2 (t_tvar_f X))
              (open_typ_wrt_typ B1 (t_tvar_f X))).
    eapply agentH4.disjoint_ctx_change.
    + exact HTCx.
    + exact Hrel.
    + exact Hsw.
  - apply (D_varr D0 B0 X A0 Hb Hsub).
  - apply (D_varl D0 X B0 A0 Hb Hsub).
  - apply (D_andr D0 B0 A0 A1 A2 Hspl IH1 IH2).
  - apply (D_andl D0 B0 A0 B1 B2 Hspl IH1 IH2).
Qed.

Lemma consistent_sym : forall u v, consistent u v -> consistent v u.
Proof.
  intros u v H. induction H as
    [ i
    | e A B HlcA Hlce HlcB
    | u1 u2 A B Hp1 Hp2 Hd Hpv1 Hpv2
    | u1 u2 u H1 IH1 H2 IH2
    | u u1 u2 H1 IH1 H2 IH2 ].
  - apply C_lit.
  - apply C_anno; assumption.
  - apply (C_disjoint u2 u1 B A Hp2 Hp1).
    + apply (disjoint_sym nil A B). exact Hd.
    + exact Hpv2.
    + exact Hpv1.
  - apply (C_merger u u1 u2); assumption.
  - apply (C_mergel u1 u2 u); assumption.
Qed.
Lemma casting_consistent_toplike_l :
  forall (v:exp) (A B:typ) (v1 v2:exp),
    casting v A v1 -> topLike nil A ->
    casting v B v2 -> consistent v1 v2.
Proof.
  intros v A B v1 v2 Hc1 Htop Hc2.
  destruct (agentE2.casting_pType_subsub v A v1 Hc1) as (P & Hp & Hss).
  destruct (casting_output_pType_TWell v B v2 Hc2) as (Q & Hq & HTWQ).
  apply (C_disjoint v1 v2 P Q Hp Hq).
  - apply (disjoint_subsub_l nil A P Q).
    + apply (D_topl nil A Q HTWQ Htop).
    + exact Hss.
  - apply (agentE2.pType_prevalue v1 P Hp).
  - apply (agentE2.pType_prevalue v2 Q Hq).
Qed.

Lemma casting_consistent_toplike_r :
  forall (v:exp) (A B:typ) (v1 v2:exp),
    casting v A v1 ->
    casting v B v2 -> topLike nil B -> consistent v1 v2.
Proof.
  intros v A B v1 v2 Hc1 Hc2 Htop.
  destruct (agentE2.casting_pType_subsub v B v2 Hc2) as (Q & Hq & Hss).
  destruct (casting_output_pType_TWell v A v1 Hc1) as (P & Hp & HTWP).
  apply (C_disjoint v1 v2 P Q Hp Hq).
  - apply (disjoint_subsub_r nil P B Q).
    + apply (D_topr nil P B HTWP Htop).
    + exact Hss.
  - apply (agentE2.pType_prevalue v1 P Hp).
  - apply (agentE2.pType_prevalue v2 Q Hq).
Qed.

Lemma merge_cross_consistent :
  forall (u w:exp) (Au Aw:typ),
    Typing nil nil u Inf Au ->
    Typing nil nil w Inf Aw ->
    (disjoint nil Au Aw \/ consistent u w) ->
    forall (A B:typ) (x y:exp),
      casting u A x -> casting w B y -> consistent x y.
Proof.
  intros u w Au Aw Htu Htw Hcase A B x y Hcu Hcw.
  destruct Hcase as [Hd | Hc].
  - destruct (casting_output_pType_TWell u A x Hcu) as (P & Hpx & HTWP).
    destruct (casting_output_pType_TWell w B y Hcw) as (Q & Hpy & HTWQ).
    exact (consistent_of_src_compat Au Aw x y P Q
             (agentI2.typing_TWell u Inf Au Htu)
             (agentI2.typing_TWell w Inf Aw Htw)
             Hd
             (casting_type_compat u Au x A Htu Hcu P Hpx HTWP)
             (casting_type_compat w Aw y B Htw Hcw Q Hpy HTWQ)
             Hpx Hpy HTWP HTWQ).
  - exact (casting_consistent_consistent u w Hc A x Hcu B y Hcw).
Qed.

Lemma merge_cross_consistent_rev :
  forall (u w:exp) (Au Aw:typ),
    Typing nil nil u Inf Au ->
    Typing nil nil w Inf Aw ->
    (disjoint nil Au Aw \/ consistent u w) ->
    forall (A B:typ) (x y:exp),
      casting u A x -> casting w B y -> consistent y x.
Proof.
  intros u w Au Aw Htu Htw Hcase A B x y Hcu Hcw.
  apply consistent_sym.
  exact (merge_cross_consistent u w Au Aw Htu Htw Hcase A B x y Hcu Hcw).
Qed.

Lemma consistent_output_toplike_r : forall (x y:exp) (P Q:typ),
  pType x P -> TWell nil P -> pType y Q -> topLike nil Q -> consistent x y.
Proof.
  intros x y P Q Hpx HTWP Hpy Htop.
  apply (consistent_toplike_r_gen x y P Q Hpx HTWP Htop Hpy).
  - apply (agentE2.pType_prevalue x P Hpx).
  - apply (agentE2.pType_prevalue y Q Hpy).
Qed.

Lemma merge_casts_consistent_aux :
  forall (u w:exp) (Au Aw:typ),
    Typing nil nil u Inf Au ->
    Typing nil nil w Inf Aw ->
    (disjoint nil Au Aw \/ consistent u w) ->
    (forall (X:exp) (P:typ), size_exp X < size_exp (e_merge u w) ->
       Typing nil nil X Inf P ->
       forall A B v1 v2, casting X A v1 -> casting X B v2 -> consistent v1 v2) ->
    forall A B v1 v2,
      casting (e_merge u w) A v1 -> casting (e_merge u w) B v2 -> consistent v1 v2.
Proof.
  intros u w Au Aw Htu Htw Hcase IHcomp A B v1 v2 Hc1 Hc2.
  assert (Hinner : forall m (A B:typ) (v1 v2:exp),
     size_typ A + size_typ B <= m ->
     casting (e_merge u w) A v1 -> casting (e_merge u w) B v2 -> consistent v1 v2).
  { induction m as [|m IHm].
    - intros A0 B0 v1' v2' Hle Hcc1 Hcc2.
      pose proof (support.size_typ_pos A0). pose proof (support.size_typ_pos B0). lia.
    - intros A0 B0 v1' v2' Hle Hcc1 Hcc2.
      pose proof Hcc1 as Hcc1keep.
      pose proof Hcc2 as Hcc2keep.
      dependent destruction Hcc1.
      + apply (casting_consistent_toplike_l (e_merge u w) t_top B0 e_top v2'
                 Hcc1keep (TL_top nil TCW_empty) Hcc2).
      + apply (casting_consistent_toplike_l (e_merge u w) (t_arrow A1 A2) B0
                 (e_anno (e_abs t_top e_top) (t_arrow A1 A2)) v2' Hcc1keep H1 Hcc2).
      + apply (casting_consistent_toplike_l (e_merge u w) (t_forall A1 A2) B0
                 (e_anno (e_tabs e_top) (t_forall A1 A2)) v2' Hcc1keep H1 Hcc2).
      + apply (casting_consistent_toplike_l (e_merge u w) (t_rcd l A0) B0
                 (e_anno (e_rcd l e_top) (t_rcd l A0)) v2' Hcc1keep H1 Hcc2).
      + (* first mergel; inspect second *)
        dependent destruction Hcc2.
        * destruct (casting_output_pType_TWell u A0 v1' Hcc1) as (P & HpP & HTWP).
          apply (consistent_output_toplike_r v1' e_top P t_top HpP HTWP PT_top).
          apply (TL_top nil TCW_empty).
        * destruct (casting_output_pType_TWell u A0 v1' Hcc1) as (P & HpP & HTWP).
          apply (consistent_output_toplike_r v1'
                   (e_anno (e_abs t_top e_top) (t_arrow A1 A2)) P (t_arrow A1 A2)
                   HpP HTWP).
          -- apply PT_anno.
             ++ apply agentE2.lc_exp_abs_top_top.
             ++ exact (agentA.ord_lc_typ _ H2).
          -- exact H3.
        * destruct (casting_output_pType_TWell u A0 v1' Hcc1) as (P & HpP & HTWP).
          apply (consistent_output_toplike_r v1'
                   (e_anno (e_tabs e_top) (t_forall A1 A2)) P (t_forall A1 A2)
                   HpP HTWP).
          -- apply PT_anno.
             ++ apply agentE2.lc_exp_tabs_top.
             ++ exact (agentA.ord_lc_typ _ H2).
          -- exact H3.
        * destruct (casting_output_pType_TWell u A0 v1' Hcc1) as (P & HpP & HTWP).
          apply (consistent_output_toplike_r v1'
                   (e_anno (e_rcd l e_top) (t_rcd l A1)) P (t_rcd l A1)
                   HpP HTWP).
          -- apply PT_anno.
             ++ apply lc_e_rcd. apply lc_e_top.
             ++ exact (agentA.ord_lc_typ _ H2).
          -- exact H3.
        * assert (Hszu : size_exp u < size_exp (e_merge u w)) by (simpl; lia).
          exact (IHcomp u Au Hszu Htu A0 A1 v1' v1'0 Hcc1 Hcc2).
        * exact (merge_cross_consistent u w Au Aw Htu Htw Hcase
                   A0 A1 v1' v2' Hcc1 Hcc2).
        * apply (C_merger v1' v0 v3).
          -- assert (Hle1 : size_typ A0 + size_typ B0 <= m)
               by (destruct (agentH.spl_size_ltH A1 B0 C H1); lia).
             exact (IHm A0 B0 v1' v0 Hle1 Hcc1keep Hcc2_1).
          -- assert (Hle2 : size_typ A0 + size_typ C <= m)
               by (destruct (agentH.spl_size_ltH A1 B0 C H1); lia).
             exact (IHm A0 C v1' v3 Hle2 Hcc1keep Hcc2_2).
      + (* first merger; inspect second *)
        dependent destruction Hcc2.
        * destruct (casting_output_pType_TWell w A0 v2'0 Hcc1) as (P & HpP & HTWP).
          apply (consistent_output_toplike_r v2'0 e_top P t_top HpP HTWP PT_top).
          apply (TL_top nil TCW_empty).
        * destruct (casting_output_pType_TWell w A0 v2'0 Hcc1) as (P & HpP & HTWP).
          apply (consistent_output_toplike_r v2'0
                   (e_anno (e_abs t_top e_top) (t_arrow A1 A2)) P (t_arrow A1 A2)
                   HpP HTWP).
          -- apply PT_anno.
             ++ apply agentE2.lc_exp_abs_top_top.
             ++ exact (agentA.ord_lc_typ _ H2).
          -- exact H3.
        * destruct (casting_output_pType_TWell w A0 v2'0 Hcc1) as (P & HpP & HTWP).
          apply (consistent_output_toplike_r v2'0
                   (e_anno (e_tabs e_top) (t_forall A1 A2)) P (t_forall A1 A2)
                   HpP HTWP).
          -- apply PT_anno.
             ++ apply agentE2.lc_exp_tabs_top.
             ++ exact (agentA.ord_lc_typ _ H2).
          -- exact H3.
        * destruct (casting_output_pType_TWell w A0 v2'0 Hcc1) as (P & HpP & HTWP).
          apply (consistent_output_toplike_r v2'0
                   (e_anno (e_rcd l e_top) (t_rcd l A1)) P (t_rcd l A1)
                   HpP HTWP).
          -- apply PT_anno.
             ++ apply lc_e_rcd. apply lc_e_top.
             ++ exact (agentA.ord_lc_typ _ H2).
          -- exact H3.
        * exact (merge_cross_consistent_rev u w Au Aw Htu Htw Hcase
                   A1 A0 v1' v2'0 Hcc2 Hcc1).
        * assert (Hszw : size_exp w < size_exp (e_merge u w)) by (simpl; lia).
          exact (IHcomp w Aw Hszw Htw A0 A1 v2'0 v2' Hcc1 Hcc2).
        * apply (C_merger v2'0 v0 v3).
          -- assert (Hle1 : size_typ A0 + size_typ B0 <= m)
               by (destruct (agentH.spl_size_ltH A1 B0 C H1); lia).
             exact (IHm A0 B0 v2'0 v0 Hle1 Hcc1keep Hcc2_1).
          -- assert (Hle2 : size_typ A0 + size_typ C <= m)
               by (destruct (agentH.spl_size_ltH A1 B0 C H1); lia).
             exact (IHm A0 C v2'0 v3 Hle2 Hcc1keep Hcc2_2).
      + (* first Cast_and *)
        apply (C_mergel v0 v3 v2').
        * assert (Hle1 : size_typ B1 + size_typ B0 <= m).
          { destruct (agentH.spl_size_ltH A0 B1 C H). simpl in Hle. lia. }
          exact (IHm B1 B0 v0 v2' Hle1 Hcc1_1 Hcc2keep).
        * assert (Hle2 : size_typ C + size_typ B0 <= m).
          { destruct (agentH.spl_size_ltH A0 B1 C H). simpl in Hle. lia. }
          exact (IHm C B0 v3 v2' Hle2 Hcc1_2 Hcc2keep).
  }
  exact (Hinner (size_typ A + size_typ B) A B v1 v2 (le_n _) Hc1 Hc2).
Qed.

Lemma casting_consistent_nonmerge : forall (v:exp) (A B:typ) (v1 v2:exp),
  casting v A v1 -> casting v B v2 ->
  (forall u1 u2, v <> e_merge u1 u2) -> consistent v1 v2.
Proof.
  intros v A B v1 v2 Hc1 Hc2 Hnm.
  apply (casting_consistent_split_nonmerge v (t_and A B) A B v1 v2).
  - apply Sp_and.
    + apply (agentA.TWell_lc_typ nil A). apply (casting_TWell_target v A v1 Hc1).
    + apply (agentA.TWell_lc_typ nil B). apply (casting_TWell_target v B v2 Hc2).
  - exact Hc1.
  - exact Hc2.
  - exact Hnm.
Qed.

Lemma casting_consistent_inf_source_aux :
  forall n (v:exp) (P:typ),
    size_exp v <= n ->
    Typing nil nil v Inf P ->
    forall A B v1 v2,
      casting v A v1 -> casting v B v2 -> consistent v1 v2.
Proof.
  intros n. induction n as [n IH] using lt_wf_ind.
  intros v P Hs Hty A B v1 v2 Hc1 Hc2.
  destruct v as [nvar|x| |i|Aabs e|Afix e|e1 e2|u w|e A0|l e|e l|e|e A0].
  - inversion Hty.
  - apply (casting_consistent_nonmerge (e_var_f x) A B v1 v2 Hc1 Hc2).
    intros u1 u2 Heq; discriminate Heq.
  - apply (casting_consistent_nonmerge e_top A B v1 v2 Hc1 Hc2).
    intros u1 u2 Heq; discriminate Heq.
  - apply (casting_consistent_nonmerge (e_lit i) A B v1 v2 Hc1 Hc2).
    intros u1 u2 Heq; discriminate Heq.
  - inversion Hty.
  - apply (casting_consistent_nonmerge (e_fixpoint Afix e) A B v1 v2 Hc1 Hc2).
    intros u1 u2 Heq; discriminate Heq.
  - apply (casting_consistent_nonmerge (e_app e1 e2) A B v1 v2 Hc1 Hc2).
    intros u1 u2 Heq; discriminate Heq.
  - inversion Hty; subst.
    + apply (merge_casts_consistent_aux u w A0 B0 H1 H4 (or_introl H5)
               (fun X P0 Hsz HtyX A' B' x y Hcx Hcy =>
                  IH (size_exp X) ltac:(lia) X P0 (le_n _) HtyX A' B' x y Hcx Hcy)
               A B v1 v2 Hc1 Hc2).
    + apply (merge_casts_consistent_aux u w A0 B0 H4 H7 (or_intror H8)
               (fun X P0 Hsz HtyX A' B' x y Hcx Hcy =>
                  IH (size_exp X) ltac:(lia) X P0 (le_n _) HtyX A' B' x y Hcx Hcy)
               A B v1 v2 Hc1 Hc2).
  - apply (casting_consistent_nonmerge (e_anno e A0) A B v1 v2 Hc1 Hc2).
    intros u1 u2 Heq; discriminate Heq.
  - inversion Hty.
  - apply (casting_consistent_nonmerge (e_proj e l) A B v1 v2 Hc1 Hc2).
    intros u1 u2 Heq; discriminate Heq.
  - inversion Hty.
  - apply (casting_consistent_nonmerge (e_tapp e A0) A B v1 v2 Hc1 Hc2).
    intros u1 u2 Heq; discriminate Heq.
Qed.

Lemma casting_consistent_inf_source :
  forall (v:exp) (P:typ),
    Typing nil nil v Inf P ->
    forall A B v1 v2,
      casting v A v1 -> casting v B v2 -> consistent v1 v2.
Proof.
  intros v P Hty A B v1 v2 Hc1 Hc2.
  exact (casting_consistent_inf_source_aux (size_exp v) v P (le_n _)
           Hty A B v1 v2 Hc1 Hc2).
Qed.

Lemma casting_consistent_split_inf :
  forall (v:exp) (A0:typ),
    Typing nil nil v Inf A0 ->
    forall (A B C:typ), spl A B C ->
    forall v1 v2,
      casting v B v1 -> casting v C v2 -> consistent v1 v2.
Proof.
  intros v A0 Hty A B C Hspl v1 v2 Hc1 Hc2.
  exact (casting_consistent_inf_source v A0 Hty B C v1 v2 Hc1 Hc2).
Qed.
(* ------------------------------------------------------------------ *)
(* pType of an Inf-typed prevalue                                     *)
(* ------------------------------------------------------------------ *)
Lemma prevalue_inf_pTypeK : forall (v:exp), prevalue v ->
  forall A, Typing nil nil v Inf A -> pType v A.
Proof.
  intros v Hpv.
  induction Hpv as
    [ i
    |
    | e A Hlce HlcA
    | u1 u2 Hp1 IH1 Hp2 IH2 ];
    intros T Hty.
  - inversion Hty; subst. apply PT_int.
  - inversion Hty; subst. apply PT_top.
  - inversion Hty; subst. eapply PT_anno; eassumption.
  - destruct (agentK2.merge_inf_components u1 u2 T Hty)
      as (A1 & A2 & Heq & H1 & H2).
    subst T. apply (PT_merge u1 u2 A1 A2).
    + apply (IH1 A1 H1).
    + apply (IH2 A2 H2).
Qed.


Lemma prevalue_merge_invK : forall (u v:exp),
  prevalue (e_merge u v) -> prevalue u /\ prevalue v.
Proof. intros u v H. inversion H; subst; auto. Qed.
(* ------------------------------------------------------------------ *)
(* A cast at an ord target gives an algorithmic supertype.            *)
(* ------------------------------------------------------------------ *)
Lemma typing_inf_casting_algo_subK : forall (v:exp) (A:typ) (x:exp),
  casting v A x ->
  forall P, Typing nil nil v Inf P -> prevalue v -> ord A ->
    algo_sub nil P A.
Proof.
  intros v A x Hc.
  induction Hc as
    [ i
    | v0 Hlc
    | v0 A1 A2 Hlc Hord Htop
    | v0 A1 A2 Hlc Hord Htop
    | v0 l A0 Hlc Hord Htop
    | e A0 B Hlc Hord Hntl Hsub
    | v1 v2 A0 v1' Hlc Hord Hc1 IH1
    | v1 v2 A0 v2' Hlc Hord Hc2 IH2
    | v0 A0 v1 v2 B C Hspl Hc1 IH1 Hc2 IH2 ];
    intros P Hty Hpv HordA.
  - inversion Hty; subst.
    apply (S_int nil TCW_empty).
  - apply (S_top nil P t_top).
    + exact (agentI2.typing_TWell v0 Inf P Hty).
    + apply O_top.
    + apply (TL_top nil TCW_empty).
  - apply (S_top nil P (t_arrow A1 A2)).
    + exact (agentI2.typing_TWell v0 Inf P Hty).
    + exact Hord.
    + exact Htop.
  - apply (S_top nil P (t_forall A1 A2)).
    + exact (agentI2.typing_TWell v0 Inf P Hty).
    + exact Hord.
    + exact Htop.
  - apply (S_top nil P (t_rcd l A0)).
    + exact (agentI2.typing_TWell v0 Inf P Hty).
    + exact Hord.
    + exact Htop.
  - inversion Hty; subst.
    exact Hsub.
  - destruct (agentK2.merge_inf_components v1 v2 P Hty)
      as (B1 & B2 & Heq & Ht1 & Ht2).
    destruct (prevalue_merge_invK v1 v2 Hpv) as [Hpv1 Hpv2].
    subst P.
    apply (S_andl nil B1 B2 A0).
    + exact (agentI2.typing_TWell v2 Inf B2 Ht2).
    + exact Hord.
    + apply (IH1 B1 Ht1 Hpv1 HordA).
  - destruct (agentK2.merge_inf_components v1 v2 P Hty)
      as (B1 & B2 & Heq & Ht1 & Ht2).
    destruct (prevalue_merge_invK v1 v2 Hpv) as [Hpv1 Hpv2].
    subst P.
    apply (S_andr nil B1 B2 A0).
    + exact (agentI2.typing_TWell v1 Inf B1 Ht1).
    + exact Hord.
    + apply (IH2 B2 Ht2 Hpv2 HordA).
  - exfalso. eapply spl_not_ord; eassumption.
Qed.

(* Right/left splitting of disjointness at the target. *)
Lemma disjoint_split_targetK : forall D P Q Q1 Q2,
    spl Q Q1 Q2 -> disjoint D P Q1 -> disjoint D P Q2 ->
    disjoint D P Q.
Proof.
  intros. exact (D_andr D P Q Q1 Q2 H H0 H1).
Qed.

Lemma disjoint_split_sourceK : forall D P P1 P2 Q,
    spl P P1 P2 -> disjoint D P1 Q -> disjoint D P2 Q ->
    disjoint D P Q.
Proof.
  intros. exact (D_andl D P Q P1 P2 H H0 H1).
Qed.

Lemma algo_sub_disjoint_ordfree_auxK : forall (n:nat) (D:tctx) (A B P Q:typ),
    size_typ A + size_typ B + size_typ P + size_typ Q <= n ->
    TCWell D -> TWell D A -> TWell D B ->
    disjoint D A B ->
    algo_sub D A P -> algo_sub D B Q ->
    TWell D P -> TWell D Q ->
    disjoint D P Q.
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D A B P Q Hle HTC HTA HTB Hd HAP HBQ HTP HTQ.
  destruct (agentG.ord_dec_TWell D P HTP) as [HoP | HnP].
  - (* P is ord: split Q if it is not *)
    destruct (agentG.ord_dec_TWell D Q HTQ) as [HoQ | HnQ].
    + (* both ord: agentK2's result *)
      exact (algo_sub_disjoint_ord D A B P Q HTC HTA HTB Hd
               HAP HBQ HoP HoQ HTP HTQ).
    + (* Q non-ord: split it *)
      assert (HleQ : size_typ Q <= n) by lia.
      assert (Hspl : exists Q1 Q2, spl Q Q1 Q2).
      { destruct (agentG.coverage_gen_aux n D Q HleQ HTC HTQ)
          as [Hord' | Hrest].
        - exfalso; exact (HnQ Hord').
        - destruct Hrest as [Htop | Hspl].
          + exact (agentG.topLike_not_ord_spl D Q Htop HnQ).
          + exact Hspl. }
      destruct Hspl as (Q1 & Q2 & Hspl).
      destruct (agentA.spl_TWell D Q Q1 Q2 HTQ Hspl) as [HTQ1 HTQ2].
      destruct (agentK.algo_sub_spl D B Q HBQ Q1 Q2 Hspl) as [HBQ1 HBQ2].
      destruct (agentH.spl_size_ltH Q Q1 Q2 Hspl) as [Hlt1 Hlt2].
      apply (disjoint_split_targetK D P Q Q1 Q2 Hspl).
      * apply (IH (size_typ A + size_typ B + size_typ P + size_typ Q1) ltac:(lia) D A B P Q1).
        -- lia.
        -- exact HTC.
        -- exact HTA.
        -- exact HTB.
        -- exact Hd.
        -- exact HAP.
        -- exact HBQ1.
        -- exact HTP.
        -- exact HTQ1.
      * apply (IH (size_typ A + size_typ B + size_typ P + size_typ Q2) ltac:(lia) D A B P Q2).
        -- lia.
        -- exact HTC.
        -- exact HTA.
        -- exact HTB.
        -- exact Hd.
        -- exact HAP.
        -- exact HBQ2.
        -- exact HTP.
        -- exact HTQ2.
  - (* P non-ord: split it *)
    assert (HleP : size_typ P <= n) by lia.
    assert (Hspl : exists P1 P2, spl P P1 P2).
    { destruct (agentG.coverage_gen_aux n D P HleP HTC HTP)
        as [Hord' | Hrest].
      - exfalso; exact (HnP Hord').
      - destruct Hrest as [Htop | Hspl].
        + exact (agentG.topLike_not_ord_spl D P Htop HnP).
        + exact Hspl. }
    destruct Hspl as (P1 & P2 & Hspl).
    destruct (agentA.spl_TWell D P P1 P2 HTP Hspl) as [HTP1 HTP2].
    destruct (agentK.algo_sub_spl D A P HAP P1 P2 Hspl) as [HAP1 HAP2].
    destruct (agentH.spl_size_ltH P P1 P2 Hspl) as [Hlt1 Hlt2].
    apply (disjoint_split_sourceK D P P1 P2 Q Hspl).
    + apply (IH (size_typ A + size_typ B + size_typ P1 + size_typ Q) ltac:(lia) D A B P1 Q).
      * lia.
      * exact HTC.
      * exact HTA.
      * exact HTB.
      * exact Hd.
      * exact HAP1.
      * exact HBQ.
      * exact HTP1.
      * exact HTQ.
    + apply (IH (size_typ A + size_typ B + size_typ P2 + size_typ Q) ltac:(lia) D A B P2 Q).
      * lia.
      * exact HTC.
      * exact HTA.
      * exact HTB.
      * exact Hd.
      * exact HAP2.
      * exact HBQ.
      * exact HTP2.
      * exact HTQ.
Qed.

Lemma algo_sub_disjoint_ordfreeK : forall (D:tctx) (A B P Q:typ),
    TCWell D -> TWell D A -> TWell D B ->
    disjoint D A B ->
    algo_sub D A P -> algo_sub D B Q ->
    TWell D P -> TWell D Q ->
    disjoint D P Q.
Proof.
  intros.
  exact (algo_sub_disjoint_ordfree_auxK
           (size_typ A + size_typ B + size_typ P + size_typ Q)
           D A B P Q (le_n _) H H0 H1 H2 H3 H4 H5 H6).
Qed.




(* ------------------------------------------------------------------ *)
(* The canonical output of a cast at an ord top-like type.            *)
(* ------------------------------------------------------------------ *)
Definition top_outputK (A:typ) : exp :=
  match A with
  | t_top => e_top
  | t_arrow _ _ => e_anno (e_abs t_top e_top) A
  | t_forall _ _ => e_anno (e_tabs e_top) A
  | t_rcd l _ => e_anno (e_rcd l e_top) A
  | _ => e_top
  end.

Lemma lc_merge_invK : forall (u v:exp), lc_exp (e_merge u v) -> lc_exp u /\ lc_exp v.
Proof. intros u v H. inversion H; subst; auto. Qed.

Lemma notTopLike_contraK : forall D A, notTopLike D A -> topLike D A -> False.
Proof. intros D A H Ht. destruct H as [D0 A0 HTC HTW Hnot]. exact (Hnot Ht). Qed.

Lemma casting_toplike_ord_outputK :
  forall n (v:exp) (A:typ),
    size_exp v <= n -> lc_exp v -> ord A -> topLike nil A ->
    forall c, casting v A c -> c = top_outputK A.
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros v A Hle Hlc Hord Htop c Hc.
  destruct (progress_final.ord_topLike_shape A Hord Htop) as [HA | Hrest].
  - subst A. dependent destruction Hc.
    + reflexivity.
    + exfalso. eapply notTopLike_contraK; eassumption.
    + match goal with
      | Hm : lc_exp (e_merge ?a ?b), Hc1 : casting ?a ?T ?cc |- _ =>
          let Hlca := fresh "Hlca" in
          destruct (lc_merge_invK a b Hm) as [Hlca _];
          assert (Hlt : size_exp a < n) by (simpl in Hle; lia);
          exact (IH (size_exp a) Hlt a T (le_n _) Hlca Hord Htop cc Hc1)
      end.
    + match goal with
      | Hm : lc_exp (e_merge ?a ?b), Hc2 : casting ?b ?T ?cc |- _ =>
          let Hlcb := fresh "Hlcb" in
          destruct (lc_merge_invK a b Hm) as [_ Hlcb];
          assert (Hlt : size_exp b < n) by (simpl in Hle; lia);
          exact (IH (size_exp b) Hlt b T (le_n _) Hlcb Hord Htop cc Hc2)
      end.
    + exfalso. eapply spl_not_ord; eassumption.
  - destruct Hrest as [Harrow | Hrest2].
  + destruct Harrow as (X & Y & HA). subst A. dependent destruction Hc.
    * reflexivity.
    * exfalso. eapply notTopLike_contraK; eassumption.
    * match goal with
        | Hm : lc_exp (e_merge ?a ?b), Hc1 : casting ?a ?T ?cc |- _ =>
            let Hlca := fresh "Hlca" in
            destruct (lc_merge_invK a b Hm) as [Hlca _];
            assert (Hlt : size_exp a < n) by (simpl in Hle; lia);
            exact (IH (size_exp a) Hlt a T (le_n _) Hlca Hord Htop cc Hc1)
        end.
    * match goal with
        | Hm : lc_exp (e_merge ?a ?b), Hc2 : casting ?b ?T ?cc |- _ =>
            let Hlcb := fresh "Hlcb" in
            destruct (lc_merge_invK a b Hm) as [_ Hlcb];
            assert (Hlt : size_exp b < n) by (simpl in Hle; lia);
            exact (IH (size_exp b) Hlt b T (le_n _) Hlcb Hord Htop cc Hc2)
        end.
    * exfalso. eapply spl_not_ord; eassumption.
  + destruct Hrest2 as [Hall | Hrcd].
    * destruct Hall as (X & Y & HA). subst A. dependent destruction Hc.
      -- reflexivity.
      -- exfalso. eapply notTopLike_contraK; eassumption.
      -- match goal with
         | Hm : lc_exp (e_merge ?a ?b), Hc1 : casting ?a ?T ?cc |- _ =>
             let Hlca := fresh "Hlca" in
             destruct (lc_merge_invK a b Hm) as [Hlca _];
             assert (Hlt : size_exp a < n) by (simpl in Hle; lia);
             exact (IH (size_exp a) Hlt a T (le_n _) Hlca Hord Htop cc Hc1)
         end.
      -- match goal with
         | Hm : lc_exp (e_merge ?a ?b), Hc2 : casting ?b ?T ?cc |- _ =>
             let Hlcb := fresh "Hlcb" in
             destruct (lc_merge_invK a b Hm) as [_ Hlcb];
             assert (Hlt : size_exp b < n) by (simpl in Hle; lia);
             exact (IH (size_exp b) Hlt b T (le_n _) Hlcb Hord Htop cc Hc2)
         end.
      -- exfalso. eapply spl_not_ord; eassumption.
    * destruct Hrcd as (l & X & HA). subst A. dependent destruction Hc.
      -- reflexivity.
      -- exfalso. eapply notTopLike_contraK; eassumption.
      -- match goal with
         | Hm : lc_exp (e_merge ?a ?b), Hc1 : casting ?a ?T ?cc |- _ =>
             let Hlca := fresh "Hlca" in
             destruct (lc_merge_invK a b Hm) as [Hlca _];
             assert (Hlt : size_exp a < n) by (simpl in Hle; lia);
             exact (IH (size_exp a) Hlt a T (le_n _) Hlca Hord Htop cc Hc1)
         end.
      -- match goal with
         | Hm : lc_exp (e_merge ?a ?b), Hc2 : casting ?b ?T ?cc |- _ =>
             let Hlcb := fresh "Hlcb" in
             destruct (lc_merge_invK a b Hm) as [_ Hlcb];
             assert (Hlt : size_exp b < n) by (simpl in Hle; lia);
             exact (IH (size_exp b) Hlt b T (le_n _) Hlcb Hord Htop cc Hc2)
         end.
      -- exfalso. eapply spl_not_ord; eassumption.
Qed.

(* No well-formed type context binds a type variable to itself. *)
Lemma TCWell_no_self_tvarK : forall (D:tctx) (X:typevar),
  TCWell D -> binds X (t_tvar_f X) D -> False.
Proof.
  intros D. induction D as [| [Y A] D IH]; intros X HTC Hb.
  - simpl in Hb. inversion Hb.
  - inversion HTC as [| D0 X0 A0 HTC0 HTW0 Hu0]; subst.
    apply binds_cons_1 in Hb. destruct Hb as [Heq | Hin].
    + destruct Heq as [HXY HA]. subst Y. subst A.
      assert (Hnot : X \notin dom D).
      { inversion Hu0; subst. assumption. }
      assert (Hin0 : X \in typefv_typ (t_tvar_f X))
        by (simpl; apply AtomSetImpl.singleton_2; reflexivity).
      exact ((agentL2.TWell_notin_dom_typefv D (t_tvar_f X) HTW0 X Hnot) Hin0).
    + apply (IH X HTC0 Hin).
Qed.

(* A well-formed context does not bind [X] to a type mentioning [X]. *)
Lemma TCWell_binds_notin_selfK : forall (D:tctx) (X:typevar) (A:typ),
  TCWell D -> binds X A D -> X \notin typefv_typ A.
Proof.
  intros D. induction D as [| [Y B] D IH]; intros X A HTC Hb.
  - simpl in Hb. inversion Hb.
  - inversion HTC as [| D0 X0 B0 HTC0 HTW0 Hu0]; subst.
    apply binds_cons_1 in Hb. destruct Hb as [Heq | Hin].
    + destruct Heq as [HXY HA]. subst Y. subst B.
      assert (Hnot : X \notin dom D).
      { inversion Hu0; subst. assumption. }
      exact (agentL2.TWell_notin_dom_typefv D A HTW0 X Hnot).
    + apply (IH X A HTC0 Hin).
Qed.

(* The relation "is an iterated left/right component of a conjunction". *)
Inductive and_compK : typ -> typ -> Prop :=
 | AC_reflK : forall A, and_compK A A
 | AC_andlK : forall A B C, and_compK A B -> and_compK A (t_and B C)
 | AC_andrK : forall A B C, and_compK A C -> and_compK A (t_and B C).

Lemma and_compK_typefv : forall A B,
  and_compK A B -> forall X, X \in typefv_typ A -> X \in typefv_typ B.
Proof.
  intros A B H. induction H as [A0 | A0 B0 C0 Hc IH | A0 B0 C0 Hc IH];
    intros X Hin.
  - exact Hin.
  - simpl in *. apply AtomSetImpl.union_2. exact (IH X Hin).
  - simpl in *. apply AtomSetImpl.union_3. exact (IH X Hin).
Qed.

Lemma and_compK_botLike : forall (D:tctx) A B,
  and_compK A B -> TWell D B -> botLike A -> botLike B.
Proof.
  intros D A B H. induction H as [A0 | A0 B0 C0 Hc IH | A0 B0 C0 Hc IH];
    intros HTW Hbl.
  - exact Hbl.
  - destruct (agentA.TWell_and_inv D B0 C0 HTW) as [HTB HTC].
    apply (BL_andl B0 C0).
    + apply (agentA.TWell_lc_typ D C0). exact HTC.
    + exact (IH HTB Hbl).
  - destruct (agentA.TWell_and_inv D B0 C0 HTW) as [HTB HTC].
    apply (BL_andr B0 C0).
    + apply (agentA.TWell_lc_typ D B0). exact HTB.
    + exact (IH HTC Hbl).
Qed.


Lemma and_compK_left : forall A B C,
  and_compK (t_and A B) C -> and_compK A C.
Proof.
  intros A B C H.
  remember (t_and A B) as T eqn:E.
  revert A B E.
  induction H as [T0 | T0 B0 C0 Hc IH | T0 B0 C0 Hc IH];
    intros A B E.
  - subst T0. apply (AC_andlK A A B (AC_reflK A)).
  - apply (AC_andlK A B0 C0). apply (IH A B E).
  - apply (AC_andrK A B0 C0). apply (IH A B E).
Qed.

Lemma and_compK_right : forall A B C,
  and_compK (t_and A B) C -> and_compK B C.
Proof.
  intros A B C H.
  remember (t_and A B) as T eqn:E.
  revert A B E.
  induction H as [T0 | T0 B0 C0 Hc IH | T0 B0 C0 Hc IH];
    intros A B E.
  - subst T0. apply (AC_andrK B A B (AC_reflK B)).
  - apply (AC_andlK B B0 C0). apply (IH A B E).
  - apply (AC_andrK B B0 C0). apply (IH A B E).
Qed.

Lemma bound_tvar_notTopLike_compK_aux : forall (n:nat) (D:tctx) (X:typevar)
  (A0 A:typ),
  size_typ A <= n ->
  TCWell D -> binds X A0 D ->
  ~ topLike D (t_tvar_f X) ->
  and_compK A A0 ->
  algo_sub D A (t_tvar_f X) -> botLike A0.
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D X A0 A Hle HTC Hb Hnt Hac Hsub.
  inversion Hsub; subst; clear Hsub.
  - (* S_var *)
    exfalso.
    match goal with
    | Hac0 : and_compK (t_tvar_f X) A0 |- _ =>
        assert (Hin : X \in typefv_typ A0) by
          (apply (and_compK_typefv (t_tvar_f X) A0 Hac0 X);
           simpl; apply AtomSetImpl.singleton_2; reflexivity);
        exact ((TCWell_binds_notin_selfK D X A0 HTC Hb) Hin)
    end.
  - (* S_top *)
    exfalso. exact (Hnt H1).
  - (* S_bot *)
    match goal with
    | Hac0 : and_compK t_bot A0 |- _ =>
        apply (and_compK_botLike D t_bot A0 Hac0);
        [ exact (agentH4.TCWell_binds_TWell D HTC X A0 Hb) | apply BL_bot ]
    end.
  - (* S_andl *)
    assert (Hlt : size_typ A1 < n) by (simpl in Hle; lia).
    apply (IH (size_typ A1) Hlt D X A0 A1
             ltac:(simpl; lia) HTC Hb Hnt
             (and_compK_left A1 B A0 Hac) H1).
  - (* S_andr *)
    assert (Hlt : size_typ B < n) by (simpl in Hle; lia).
    apply (IH (size_typ B) Hlt D X A0 B
             ltac:(simpl; lia) HTC Hb Hnt
             (and_compK_right A1 B A0 Hac) H1).
  - (* S_and : impossible, spl at a type variable *)
    exfalso.
    match goal with
    | Hs : spl (t_tvar_f X) ?B1 ?B2 |- _ => inversion Hs
    end.
Qed.

Lemma algo_sub_bound_tvar_botLikeK : forall (D:tctx) (X:typevar) (A0:typ),
  TCWell D -> binds X A0 D ->
  algo_sub D A0 (t_tvar_f X) -> botLike A0.
Proof.
  intros D X A0 HTC Hb Hsub.
  assert (HTWvar : TWell D (t_tvar_f X)) by (apply (TW_var D X A0); exact Hb).
  destruct (progress_final.topLike_dec_ord (t_tvar_f X) (O_var X) D HTC HTWvar)
    as [Htop | Hnt].
  - inversion Htop; subst.
    match goal with
    | Hb' : binds X ?A D, Hbl : botLike ?A |- _ =>
        assert (Heq : A = A0) by
          (apply (binds_uniq_eq D X A A0 (TCWell_uniq D HTC) Hb' Hb));
        subst A; exact Hbl
    end.
  - apply (bound_tvar_notTopLike_compK_aux (size_typ A0) D X A0 A0
             (le_n _) HTC Hb Hnt (AC_reflK A0) Hsub).
Qed.

Lemma ord_disjoint_self_topLikeK : forall (D:tctx) (A:typ),
  TCWell D -> ord A -> disjoint D A A -> topLike D A.
Proof.
  intros D A HTC Hord.
  generalize dependent D.
  induction Hord; intros D HTC Hd.
  - (* O_var *)
    inversion Hd; subst.
    + inversion H2.
    + exact H0.
    + exact H0.
    + eapply TL_var; [exact HTC | exact H0 |].
      eapply algo_sub_bound_tvar_botLikeK; eassumption.
    + eapply TL_var; [exact HTC | exact H0 |].
      eapply algo_sub_bound_tvar_botLikeK; eassumption.
    + exfalso. match goal with Hs : spl (t_tvar_f X) ?P ?Q |- _ =>
        exact (spl_not_ord (t_tvar_f X) P Q Hs (O_var X)) end.
    + exfalso. match goal with Hs : spl (t_tvar_f X) ?P ?Q |- _ =>
        exact (spl_not_ord (t_tvar_f X) P Q Hs (O_var X)) end.
  - (* O_top *) apply TL_top; exact HTC.
  - (* O_bot *) inversion Hd; subst.
    + inversion H2.
    + exact H0.
    + exact H0.
    + exfalso. match goal with Hs : spl t_bot ?P ?Q |- _ =>
        exact (spl_not_ord t_bot P Q Hs O_bot) end.
    + exfalso. match goal with Hs : spl t_bot ?P ?Q |- _ =>
        exact (spl_not_ord t_bot P Q Hs O_bot) end.
  - (* O_int *) inversion Hd; subst.
    + inversion H2.
    + exact H0.
    + exact H0.
    + exfalso. match goal with Hs : spl t_int ?P ?Q |- _ =>
        exact (spl_not_ord t_int P Q Hs O_int) end.
    + exfalso. match goal with Hs : spl t_int ?P ?Q |- _ =>
        exact (spl_not_ord t_int P Q Hs O_int) end.
  - (* O_arrow *) inversion Hd; subst.
    + exfalso. match goal with Hax : disjoint_axiom _ _ |- _ => inversion Hax; subst; try contradiction end.
    + match goal with Htop : topLike _ _ |- _ => exact Htop end.
    + match goal with Htop : topLike _ _ |- _ => exact Htop end.
    + apply TL_arrow.
      * match goal with HT : TWell D (t_arrow A B) |- _ =>
          inversion HT; subst; assumption end.
      * apply IHHord; assumption.
    + exfalso. match goal with Hs : spl (t_arrow A B) ?P ?Q |- _ =>
        exact (spl_not_ord (t_arrow A B) P Q Hs (O_arrow A B H Hord)) end.
    + exfalso. match goal with Hs : spl (t_arrow A B) ?P ?Q |- _ =>
        exact (spl_not_ord (t_arrow A B) P Q Hs (O_arrow A B H Hord)) end.
  - (* O_all *)
    inversion Hd; subst.
    + exfalso. match goal with Hax : disjoint_axiom _ _ |- _ => inversion Hax; subst; try contradiction end.
    + match goal with Htop : topLike _ _ |- _ => exact Htop end.
    + match goal with Htop : topLike _ _ |- _ => exact Htop end.
    + pose (bad := L \u L0 \u dom D \u typefv_typ_range D \u [[A]] \u [[B]]).
      apply (TL_all bad D A B).
      intros X HXbad.
      pose proof (notin_u_l X L (L0 \u dom D \u typefv_typ_range D \u [[A]] \u [[B]]) HXbad) as HXL.
      pose proof (notin_u_r X L (L0 \u dom D \u typefv_typ_range D \u [[A]] \u [[B]]) HXbad) as HX1.
      pose proof (notin_u_l X L0 (dom D \u typefv_typ_range D \u [[A]] \u [[B]]) HX1) as HXL0.
      pose proof (notin_u_r X L0 (dom D \u typefv_typ_range D \u [[A]] \u [[B]]) HX1) as HX2.
      pose proof (notin_u_l X (dom D) (typefv_typ_range D \u [[A]] \u [[B]]) HX2) as HXdom.
      pose proof (notin_u_r X (dom D) (typefv_typ_range D \u [[A]] \u [[B]]) HX2) as HX3.
      pose proof (notin_u_l X (typefv_typ_range D) ([[A]] \u [[B]]) HX3) as HXrng.
      pose proof (notin_u_r X (typefv_typ_range D) ([[A]] \u [[B]]) HX3) as HX4.
      pose proof (notin_u_l X [[A]] [[B]] HX4) as HXA.
      pose proof (notin_u_r X [[A]] [[B]] HX4) as HXB.
      assert (HTWand : TWell D (t_and A A)) by (apply TW_and; exact H7).
      assert (HTCconsAA : TCWell (cons (X, t_and A A) D)).
      { apply TCW_cons.
        - exact HTC.
        - exact HTWand.
        - apply uniq_cons.
          + apply (TCWell_uniq D HTC).
          + exact HXdom. }
      assert (HbodyX : disjoint (cons (X, t_and A A) D) (B -^ X) (B -^ X))
        by (apply H9; exact HXL0).
      assert (HtopAA : topLike (cons (X, t_and A A) D) (B -^ X))
        by (apply (H1 X HXL (cons (X, t_and A A) D) HTCconsAA HbodyX)).
      assert (HTCconsA : TCWell (cons (X, A) D)).
      { apply TCW_cons.
        - exact HTC.
        - exact H7.
        - apply uniq_cons.
          + apply (TCWell_uniq D HTC).
          + exact HXdom. }
      eapply (topLike_conv (cons (X, t_and A A) D) (B -^ X) HtopAA
                (cons (X, A) D) HTCconsA).
      * simpl. reflexivity.
      * intros Y C Hb. apply binds_cons_1 in Hb.
        destruct Hb as [ [HY HC] | Hin].
        -- subst Y. subst C. exists A. split.
           ++ apply binds_cons_2; auto.
           ++ intro Hbl. inversion Hbl; subst; assumption.
        -- exists C. split.
           ++ apply binds_cons_3. exact Hin.
           ++ intro Hbl. exact Hbl.
    + exfalso. match goal with Hs : spl (t_forall A B) ?P ?Q |- _ =>
        exact (spl_not_ord (t_forall A B) P Q Hs (O_all L A B H H0)) end.
    + exfalso. match goal with Hs : spl (t_forall A B) ?P ?Q |- _ =>
        exact (spl_not_ord (t_forall A B) P Q Hs (O_all L A B H H0)) end.
  - (* O_rcd *) inversion Hd; subst.
    + exfalso. match goal with Hax : disjoint_axiom _ _ |- _ => inversion Hax; subst; try contradiction end.
    + match goal with Htop : topLike _ _ |- _ => exact Htop end.
    + match goal with Htop : topLike _ _ |- _ => exact Htop end.
    + apply TL_rcd. apply IHHord; assumption.
    + exfalso. match goal with Hs : spl (t_rcd l B) ?P ?Q |- _ =>
        exact (spl_not_ord (t_rcd l B) P Q Hs (O_rcd l B Hord)) end.
    + exfalso. match goal with Hs : spl (t_rcd l B) ?P ?Q |- _ =>
        exact (spl_not_ord (t_rcd l B) P Q Hs (O_rcd l B Hord)) end.
Qed.

Lemma disjoint_self_topLike_nilK : forall (A:typ),
  ord A -> disjoint nil A A -> topLike nil A.
Proof.
  intros A Hord Hd. apply (ord_disjoint_self_topLikeK nil A TCW_empty); assumption.
Qed.

Lemma casting_target_casesK : forall (v:exp) (A:typ) (x:exp),
  casting v A x -> ord A \/ (exists B C, spl A B C).
Proof.
  intros v A x Hc. induction Hc.
  - left. apply O_int.
  - left. apply O_top.
  - left. eassumption.
  - left. eassumption.
  - left. eassumption.
  - left. eassumption.
  - left. eassumption.
  - left. eassumption.
  - right. exists B, C. exact H.
Qed.

Lemma casting_lit_eqK : forall (i:int) (A:typ) (x:exp),
  ord A -> ~ topLike nil A -> casting (e_lit i) A x -> x = e_lit i.
Proof.
  intros i A x Hord Hnt Hc. dependent destruction Hc.
  - reflexivity.
  - exfalso. apply Hnt. apply TL_top. exact TCW_empty.
  - exfalso. apply Hnt. eassumption.
  - exfalso. apply Hnt. eassumption.
  - exfalso. apply Hnt. eassumption.
  - exfalso. eapply spl_not_ord; eassumption.
Qed.

Lemma casting_anno_eqK : forall (e:exp) (A0 A:typ) (x:exp),
  ord A -> ~ topLike nil A -> casting (e_anno e A0) A x -> x = e_anno e A.
Proof.
  intros e A0 A x Hord Hnt Hc. dependent destruction Hc.
  - exfalso. apply Hnt. apply TL_top. exact TCW_empty.
  - exfalso. apply Hnt. eassumption.
  - exfalso. apply Hnt. eassumption.
  - exfalso. apply Hnt. eassumption.
  - reflexivity.
  - exfalso. eapply spl_not_ord; eassumption.
Qed.

Lemma casting_top_ord_nonTopLike_falseK : forall (A:typ) (x:exp),
  ord A -> ~ topLike nil A -> casting e_top A x -> False.
Proof.
  intros A x Hord Hnt Hc. dependent destruction Hc.
  - apply Hnt. apply TL_top. exact TCW_empty.
  - apply Hnt. eassumption.
  - apply Hnt. eassumption.
  - apply Hnt. eassumption.
  - eapply spl_not_ord; eassumption.
Qed.

Lemma casting_merge_ord_casesK : forall (u1 u2:exp) (A:typ) (x:exp),
  ord A -> ~ topLike nil A -> casting (e_merge u1 u2) A x ->
  (exists x1, x = x1 /\ casting u1 A x1) \/
  (exists x2, x = x2 /\ casting u2 A x2).
Proof.
  intros u1 u2 A x Hord Hnt Hc. dependent destruction Hc.
  - exfalso. apply Hnt. apply TL_top. exact TCW_empty.
  - exfalso. apply Hnt. eassumption.
  - exfalso. apply Hnt. eassumption.
  - exfalso. apply Hnt. eassumption.
  - left. exists v1'. split; [reflexivity | exact Hc].
  - right. exists v2'. split; [reflexivity | exact Hc].
  - exfalso. eapply spl_not_ord; eassumption.
Qed.

Lemma casting_spl_eqK : forall (v:exp) (A:typ) (x:exp) (B C:typ),
  spl A B C -> casting v A x ->
  exists v1 v2, x = e_merge v1 v2 /\ casting v B v1 /\ casting v C v2.
Proof.
  intros v A x B C Hspl Hc. dependent destruction Hc.
  - exfalso. eapply spl_not_ord; [exact Hspl | apply O_int].
  - exfalso. eapply spl_not_ord; [exact Hspl | apply O_top].
  - exfalso. eapply spl_not_ord; eassumption.
  - exfalso. eapply spl_not_ord; eassumption.
  - exfalso. eapply spl_not_ord; eassumption.
  - exfalso. eapply spl_not_ord; eassumption.
  - exfalso. eapply spl_not_ord; eassumption.
  - exfalso. eapply spl_not_ord; eassumption.
  - destruct (@spl_functional A B C B0 C0 Hspl H) as [HB HC].
    subst B0. subst C0. exists v1, v2. repeat split; assumption.
Qed.

Lemma casting_functional_consistentK :
  forall (n:nat) (u w:exp) (A Pu Pw:typ),
    size_exp u + size_exp w + size_typ A <= n ->
    Typing nil nil u Inf Pu ->
    Typing nil nil w Inf Pw ->
    prevalue u -> prevalue w -> consistent u w ->
    forall x y, casting u A x -> casting w A y -> x = y.
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros u w A Pu Pw Hle Htu Htw Hpvu Hpvw Hcon x y Hu Hw.
  destruct (casting_target_casesK u A x Hu) as [Hord | (B & C & Hspl)].
  - (* A is ord *)
    assert (HTWA : TWell nil A) by (eapply agentK2.casting_TWell_target; eassumption).
    destruct (progress_final.topLike_dec_ord A Hord nil TCW_empty HTWA) as [Htop | Hnt].
    + (* topLike target: canonical outputs *)
      assert (Hxu : x = top_outputK A)
        by (apply (casting_toplike_ord_outputK (size_exp u) u A (le_n _)
                    (progress_final.prevalue_lc u Hpvu) Hord Htop x Hu)).
      assert (Hyu : y = top_outputK A)
        by (apply (casting_toplike_ord_outputK (size_exp w) w A (le_n _)
                    (progress_final.prevalue_lc w Hpvw) Hord Htop y Hw)).
      exact (eq_trans Hxu (eq_sym Hyu)).
    + (* ord but not top-like *)
      dependent destruction Hcon.
      * (* C_lit *)
        rewrite (casting_lit_eqK i A x Hord Hnt Hu).
        rewrite (casting_lit_eqK i A y Hord Hnt Hw).
        reflexivity.
      * (* C_anno *)
        rewrite (casting_anno_eqK e A0 A x Hord Hnt Hu).
        rewrite (casting_anno_eqK e B A y Hord Hnt Hw).
        reflexivity.
      * (* C_disjoint *)
        exfalso.
        match goal with
        | Hp1 : pType u1 ?A1, Hp2 : pType u2 ?A2, Hdj : disjoint nil ?A1 ?A2 |- _ =>
          assert (Heq1 : Pu = A1) by
            (exact (eq_sym (agentK2.pType_det u1 A1 Pu Hp1
                              (prevalue_inf_pTypeK u1 Hpvu Pu Htu))));
          assert (Heq2 : Pw = A2) by
            (exact (eq_sym (agentK2.pType_det u2 A2 Pw Hp2
                              (prevalue_inf_pTypeK u2 Hpvw Pw Htw))));
          subst Pu; subst Pw;
          assert (Hsu : algo_sub nil A1 A) by
            (exact (typing_inf_casting_algo_subK u1 A x Hu A1 Htu Hpvu Hord));
          assert (Hsw : algo_sub nil A2 A) by
            (exact (typing_inf_casting_algo_subK u2 A y Hw A2 Htw Hpvw Hord));
          assert (HTW1 : TWell nil A1) by (exact (agentI2.typing_TWell u1 Inf A1 Htu));
          assert (HTW2 : TWell nil A2) by (exact (agentI2.typing_TWell u2 Inf A2 Htw));
          assert (HdAA : disjoint nil A A) by
            (exact (algo_sub_disjoint_ordfreeK nil A1 A2 A A TCW_empty
                      HTW1 HTW2 Hdj Hsu Hsw HTWA HTWA));
          exact (Hnt (disjoint_self_topLike_nilK A Hord HdAA))
        end.
      * (* C_mergel *)
        destruct (agentK2.merge_inf_components u1 u2 Pu Htu)
          as (P1 & P2 & Heq & Htu1 & Htu2).
        destruct (prevalue_merge_invK u1 u2 Hpvu) as [Hpvu1 Hpvu2].
        destruct (casting_merge_ord_casesK u1 u2 A x Hord Hnt Hu)
          as [(x1 & Hx & Hc1) | (x2 & Hx & Hc2)].
        -- rewrite Hx.
           assert (Hlt : size_exp u1 + size_exp u + size_typ A < n)
             by (simpl in Hle; lia).
           exact (IH (size_exp u1 + size_exp u + size_typ A) Hlt
                    u1 u A P1 Pw (le_n _) Htu1 Htw Hpvu1 Hpvw Hcon1
                    x1 y Hc1 Hw).
        -- rewrite Hx.
           assert (Hlt : size_exp u2 + size_exp u + size_typ A < n)
             by (simpl in Hle; lia).
           exact (IH (size_exp u2 + size_exp u + size_typ A) Hlt
                    u2 u A P2 Pw (le_n _) Htu2 Htw Hpvu2 Hpvw Hcon2
                    x2 y Hc2 Hw).
      * (* C_merger *)
        destruct (agentK2.merge_inf_components u1 u2 Pw Htw)
          as (P1 & P2 & Heq & Htw1 & Htw2).
        destruct (prevalue_merge_invK u1 u2 Hpvw) as [Hpvw1 Hpvw2].
        destruct (casting_merge_ord_casesK u1 u2 A y Hord Hnt Hw)
          as [(y1 & Hy & Hc1) | (y2 & Hy & Hc2)].
        -- rewrite Hy.
           assert (Hlt : size_exp u + size_exp u1 + size_typ A < n)
             by (simpl in Hle; lia).
           exact (IH (size_exp u + size_exp u1 + size_typ A) Hlt
                    u u1 A Pu P1 (le_n _) Htu Htw1 Hpvu Hpvw1 Hcon1
                    x y1 Hu Hc1).
        -- rewrite Hy.
           assert (Hlt : size_exp u + size_exp u2 + size_typ A < n)
             by (simpl in Hle; lia).
           exact (IH (size_exp u + size_exp u2 + size_typ A) Hlt
                    u u2 A Pu P2 (le_n _) Htu Htw2 Hpvu Hpvw2 Hcon2
                    x y2 Hu Hc2).
  - (* A splits: both casts go through Cast_and *)
    destruct (agentH.spl_size_ltH A B C Hspl) as [HltB HltC].
    destruct (casting_spl_eqK u A x B C Hspl Hu)
      as (u1 & u2 & Hx & Hu1 & Hu2).
    destruct (casting_spl_eqK w A y B C Hspl Hw)
      as (w1 & w2 & Hy & Hw1 & Hw2).
    rewrite Hx. rewrite Hy.
    assert (Hlt1 : size_exp u + size_exp w + size_typ B < n) by lia.
    assert (Hlt2 : size_exp u + size_exp w + size_typ C < n) by lia.
    assert (Hueq : u1 = w1) by
      (exact (IH (size_exp u + size_exp w + size_typ B) Hlt1
               u w B Pu Pw (le_n _) Htu Htw Hpvu Hpvw Hcon u1 w1 Hu1 Hw1)).
    assert (Hweq : u2 = w2) by
      (exact (IH (size_exp u + size_exp w + size_typ C) Hlt2
               u w C Pu Pw (le_n _) Htu Htw Hpvu Hpvw Hcon u2 w2 Hu2 Hw2)).
    rewrite Hueq. rewrite Hweq. reflexivity.
Qed.

Lemma merge_inf_components_orK : forall (u1 u2:exp) (C:typ),
  Typing nil nil (e_merge u1 u2) Inf C ->
  exists A B, C = t_and A B /\
    Typing nil nil u1 Inf A /\ Typing nil nil u2 Inf B /\
    (disjoint nil A B \/ consistent u1 u2).
Proof.
  intros u1 u2 C H. inversion H; subst.
  - exists A, B. split.
    + reflexivity.
    + split.
      * assumption.
      * split.
        -- assumption.
        -- left. assumption.
  - exists A, B. split.
    + reflexivity.
    + split.
      * assumption.
      * split.
        -- assumption.
        -- right. assumption.
Qed.

Lemma casting_functional_prevalue_infK :
  forall (n:nat) (v:exp) (P0 A:typ),
    size_exp v + size_typ A <= n ->
    Typing nil nil v Inf P0 -> prevalue v ->
    forall x y, casting v A x -> casting v A y -> x = y.
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros v P0 A Hle Htv Hpv x y Hx Hy.
  destruct (casting_target_casesK v A x Hx) as [Hord | (B & C & Hspl)].
  - assert (HTWA : TWell nil A) by (eapply agentK2.casting_TWell_target; eassumption).
    destruct (progress_final.topLike_dec_ord A Hord nil TCW_empty HTWA) as [Htop | Hnt].
    + assert (Hxu : x = top_outputK A)
        by (apply (casting_toplike_ord_outputK (size_exp v) v A (le_n _)
                    (progress_final.prevalue_lc v Hpv) Hord Htop x Hx)).
      assert (Hyu : y = top_outputK A)
        by (apply (casting_toplike_ord_outputK (size_exp v) v A (le_n _)
                    (progress_final.prevalue_lc v Hpv) Hord Htop y Hy)).
      exact (eq_trans Hxu (eq_sym Hyu)).
    + destruct Hpv as [i | | e A0 Hlce HlcA | u1 u2 Hpvu1 Hpvu2].
      * rewrite (casting_lit_eqK i A x Hord Hnt Hx).
        rewrite (casting_lit_eqK i A y Hord Hnt Hy). reflexivity.
      * exact (False_ind _ (casting_top_ord_nonTopLike_falseK A x Hord Hnt Hx)).
      * rewrite (casting_anno_eqK e A0 A x Hord Hnt Hx).
        rewrite (casting_anno_eqK e A0 A y Hord Hnt Hy). reflexivity.
      * destruct (merge_inf_components_orK u1 u2 P0 Htv)
          as (A1 & A2 & Heq & Htu1 & Htu2 & Hor).
        destruct (casting_merge_ord_casesK u1 u2 A x Hord Hnt Hx)
          as [(x1 & Hx1 & Hcx1) | (x2 & Hx2 & Hcx2)];
        destruct (casting_merge_ord_casesK u1 u2 A y Hord Hnt Hy)
          as [(y1 & Hy1 & Hcy1) | (y2 & Hy2 & Hcy2)].
        -- rewrite Hx1. rewrite Hy1.
           assert (Hlt : size_exp u1 + size_typ A < n)
             by (simpl in Hle; lia).
           exact (IH (size_exp u1 + size_typ A) Hlt u1 A1 A (le_n _)
                    Htu1 Hpvu1 x1 y1 Hcx1 Hcy1).
        -- rewrite Hx1. rewrite Hy2.
           destruct Hor as [Hdisj | Hcc].
           ++ exfalso.
              assert (Hsu : algo_sub nil A1 A) by
                (exact (typing_inf_casting_algo_subK u1 A x1 Hcx1 A1 Htu1 Hpvu1 Hord)).
              assert (Hsw : algo_sub nil A2 A) by
                (exact (typing_inf_casting_algo_subK u2 A y2 Hcy2 A2 Htu2 Hpvu2 Hord)).
              assert (HTW1 : TWell nil A1) by (exact (agentI2.typing_TWell u1 Inf A1 Htu1)).
              assert (HTW2 : TWell nil A2) by (exact (agentI2.typing_TWell u2 Inf A2 Htu2)).
              assert (HdAA : disjoint nil A A) by
                (exact (algo_sub_disjoint_ordfreeK nil A1 A2 A A TCW_empty
                          HTW1 HTW2 Hdisj Hsu Hsw HTWA HTWA)).
              exact (Hnt (disjoint_self_topLike_nilK A Hord HdAA)).
           ++ assert (Hlt : size_exp u1 + size_exp u2 + size_typ A < n)
                by (simpl in Hle; lia).
              exact (casting_functional_consistentK
                       (size_exp u1 + size_exp u2 + size_typ A) u1 u2 A A1 A2
                       (le_n _) Htu1 Htu2 Hpvu1 Hpvu2 Hcc x1 y2 Hcx1 Hcy2).
        -- rewrite Hx2. rewrite Hy1.
           destruct Hor as [Hdisj | Hcc].
           ++ exfalso.
              assert (Hsu : algo_sub nil A1 A) by
                (exact (typing_inf_casting_algo_subK u1 A y1 Hcy1 A1 Htu1 Hpvu1 Hord)).
              assert (Hsw : algo_sub nil A2 A) by
                (exact (typing_inf_casting_algo_subK u2 A x2 Hcx2 A2 Htu2 Hpvu2 Hord)).
              assert (HTW1 : TWell nil A1) by (exact (agentI2.typing_TWell u1 Inf A1 Htu1)).
              assert (HTW2 : TWell nil A2) by (exact (agentI2.typing_TWell u2 Inf A2 Htu2)).
              assert (HdAA : disjoint nil A A) by
                (exact (algo_sub_disjoint_ordfreeK nil A1 A2 A A TCW_empty
                          HTW1 HTW2 Hdisj Hsu Hsw HTWA HTWA)).
              exact (Hnt (disjoint_self_topLike_nilK A Hord HdAA)).
           ++ assert (Hlt : size_exp u1 + size_exp u2 + size_typ A < n)
                by (simpl in Hle; lia).
              exact (eq_sym (casting_functional_consistentK
                       (size_exp u1 + size_exp u2 + size_typ A) u1 u2 A A1 A2
                       (le_n _) Htu1 Htu2 Hpvu1 Hpvu2 Hcc y1 x2 Hcy1 Hcx2)).
        -- rewrite Hx2. rewrite Hy2.
           assert (Hlt : size_exp u2 + size_typ A < n)
             by (simpl in Hle; lia).
           exact (IH (size_exp u2 + size_typ A) Hlt u2 A2 A (le_n _)
                    Htu2 Hpvu2 x2 y2 Hcx2 Hcy2).
  - destruct (agentH.spl_size_ltH A B C Hspl) as [HltB HltC].
    destruct (casting_spl_eqK v A x B C Hspl Hx)
      as (v1 & v2 & Hx' & Hx1 & Hx2).
    destruct (casting_spl_eqK v A y B C Hspl Hy)
      as (w1 & w2 & Hy' & Hy1 & Hy2).
    rewrite Hx'. rewrite Hy'.
    assert (Hlt1 : size_exp v + size_typ B < n) by lia.
    assert (Hlt2 : size_exp v + size_typ C < n) by lia.
    assert (Heq1 : v1 = w1) by
      (exact (IH (size_exp v + size_typ B) Hlt1 v P0 B (le_n _) Htv Hpv v1 w1 Hx1 Hy1)).
    assert (Heq2 : v2 = w2) by
      (exact (IH (size_exp v + size_typ C) Hlt2 v P0 C (le_n _) Htv Hpv v2 w2 Hx2 Hy2)).
    rewrite Heq1. rewrite Heq2. reflexivity.
Qed.

(* Exact requested form, specialized from the measured induction. *)
Lemma casting_functional_inf_pre :
  forall (v:exp) (P:typ),
    Typing nil nil v Inf P -> prevalue v ->
    forall (A:typ) (x y:exp),
      casting v A x -> casting v A y -> x = y.
Proof.
  intros v P Hty Hpv A x y Hx Hy.
  exact (casting_functional_prevalue_infK (size_exp v + size_typ A)
           v P A (le_n _) Hty Hpv x y Hx Hy).
Qed.
(* A Chk-typable expression that can step is also Inf-typable. *)
Lemma chk_steppable_inf_aux : forall (D:tctx) (G:ctx) (e:exp) (d:dirflag) (A:typ),
  Typing D G e d A -> d = Chk ->
  (exists e', step e e') ->
  exists P, Typing D G e Inf P.
Proof.
  intros D G e d A H.
  induction H; intros Hd Hex; subst; try discriminate Hd.
  - (* Typ_abs *) destruct Hex as [e' Hs]; inversion Hs.
  - (* Typ_tabs *) destruct Hex as [e' Hs]; inversion Hs.
  - (* Typ_rcd *) destruct Hex as [e' Hs]; inversion Hs.
  - (* Typ_inter *) exact (IHTyping1 eq_refl Hex).
  - (* Typ_sub *) exists A. assumption.
Qed.

Lemma chk_steppable_infK : forall (e:exp) (P0:typ),
  Typing nil nil e Chk P0 ->
  (exists e', step e e') ->
  exists P, Typing nil nil e Inf P.
Proof.
  intros e P0 Ht Hex.
  exact (chk_steppable_inf_aux nil nil e Chk P0 Ht eq_refl Hex).
Qed.


(* Copied from agentE3 (which cannot be imported here). *)
Lemma chk_prevalue_inf_auxK : forall (D:tctx) (G:ctx) (v:exp) (d:dirflag) (A:typ),
  Typing D G v d A -> d = Chk -> prevalue v ->
  exists A0, Typing D G v Inf A0.
Proof.
  intros D G v d A H.
  induction H; intros Hd Hpv; subst; try discriminate Hd.
  - (* Typ_abs *) exfalso. inversion Hpv.
  - (* Typ_tabs *) exfalso. inversion Hpv.
  - (* Typ_rcd *) exfalso. inversion Hpv.
  - (* Typ_inter *) exact (IHTyping1 eq_refl Hpv).
  - (* Typ_sub *) exists A. assumption.
Qed.

Lemma prevalue_chk_infK : forall (v:exp), prevalue v ->
  forall A, Typing nil nil v Chk A ->
  exists A0, Typing nil nil v Inf A0.
Proof.
  intros v Hpv A Hty.
  exact (chk_prevalue_inf_auxK nil nil v Chk A Hty eq_refl Hpv).
Qed.

(* Casting to a fixed target is deterministic. *)
Lemma wrapping_detK : forall (e:exp) (A:typ) (e1:exp),
  wrapping e A e1 -> forall z, wrapping e A z -> e1 = z.
Proof.
  intros e A e1 Hw.
  induction Hw; intros z H2.
  - (* EW_top *)
    inversion H2; subst; try reflexivity;
      try (exfalso; match goal with
           | Hs : spl t_top ?Y ?Z |- _ => inversion Hs end);
      try (exfalso; eapply notTopLike_contraK;
           [ eassumption | apply TL_top; apply TCW_empty ]).
  - (* EW_topArrow *)
    inversion H2; subst; try reflexivity;
      try (exfalso; eapply spl_not_ord; eassumption);
      try (exfalso; eapply notTopLike_contraK; eassumption).
  - (* EW_topAll *)
    inversion H2; subst; try reflexivity;
      try (exfalso; eapply spl_not_ord; eassumption);
      try (exfalso; eapply notTopLike_contraK; eassumption).
  - (* EW_topRcd *)
    inversion H2; subst; try reflexivity;
      try (exfalso; eapply spl_not_ord; eassumption);
      try (exfalso; eapply notTopLike_contraK; eassumption).
  - (* EW_anno *)
    inversion H2; subst; try reflexivity;
      try (exfalso; eapply notTopLike_contraK; eassumption);
      try (exfalso; eapply spl_not_ord; eassumption);
      try (exfalso; eapply notTopLike_contraK;
           [ eassumption | apply TL_top; apply TCW_empty ]).
  - (* EW_and *)
    inversion H2; subst; try reflexivity;
      try (exfalso; eapply spl_not_ord; eassumption);
      try (exfalso; match goal with
           | Hs : spl t_top ?Y ?Z |- _ => inversion Hs end).
    (* EW_and / EW_and *)
    assert (HBC : B = B0 /\ C = C0) by (eapply spl_functional; eassumption).
    destruct HBC as [HB HC]. subst.
    rewrite (IHHw1 e3 H1). rewrite (IHHw2 e4 H3). reflexivity.
Qed.




(* appDist uniqueness (copied from appdist_uniq.v, K-renamed). *)
Lemma appDist_arrow_uniqueK : forall A B C B' C',
  appDist A (t_arrow B C) -> appDist A (t_arrow B' C') -> B = B' /\ C = C'.
Proof.
  intros A. induction A as [n|X| | | |A1 IHA1 A2 IHA2|A1 IHA1 A2 IHA2|A1 IHA1 A2 IHA2|l A1 IHA1];
    intros B C B' C' H1 H2.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - (* arrow *) inversion H1; subst. inversion H2; subst. split; reflexivity.
  - (* and *) inversion H1; subst. inversion H2; subst.
    match goal with
    | H1a : appDist A1 (t_arrow ?X1 ?Y1), H1b : appDist A2 (t_arrow ?X2 ?Y2),
      H2a : appDist A1 (t_arrow ?X1' ?Y1'), H2b : appDist A2 (t_arrow ?X2' ?Y2') |- _ =>
      destruct (IHA1 X1 Y1 X1' Y1' H1a H2a) as [E1 E2];
      destruct (IHA2 X2 Y2 X2' Y2' H1b H2b) as [E3 E4]; subst; split; reflexivity end.
  - (* rcd *) inversion H1.
Qed.

Lemma appDist_rcd_uniqueK : forall A l C l' C',
  appDist A (t_rcd l C) -> appDist A (t_rcd l' C') -> l = l' /\ C = C'.
Proof.
  intros A. induction A as [n|X| | | |A1 IHA1 A2 IHA2|A1 IHA1 A2 IHA2|A1 IHA1 A2 IHA2|l0 A1 IHA1];
    intros l C l' C' H1 H2.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - (* arrow *) inversion H1.
  - (* and *) inversion H1; subst. inversion H2; subst.
    match goal with
    | H1a : appDist A1 (t_rcd ?L1 ?X1), H1b : appDist A2 (t_rcd ?L2 ?X2),
      H2a : appDist A1 (t_rcd ?L1' ?X1'), H2b : appDist A2 (t_rcd ?L2' ?X2') |- _ =>
      destruct (IHA1 L1 X1 L1' X1' H1a H2a) as [E1 E2];
      destruct (IHA2 L2 X2 L2' X2' H1b H2b) as [E3 E4]; subst; split; reflexivity end.
  - (* rcd *) inversion H1; subst. inversion H2; subst. split; reflexivity.
Qed.

Lemma appDist_all_uniqueK : forall A B C B' C',
  appDist A (t_forall B C) -> appDist A (t_forall B' C') -> B = B' /\ C = C'.
Proof.
  intros A. induction A as [n|X| | | |A1 IHA1 A2 IHA2|A1 IHA1 A2 IHA2|A1 IHA1 A2 IHA2|l A1 IHA1];
    intros B C B' C' H1 H2.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - inversion H1.
  - (* forall *) inversion H1; subst. inversion H2; subst. split; reflexivity.
  - (* arrow *) inversion H1.
  - (* and *) inversion H1; subst. inversion H2; subst.
    match goal with
    | H1a : appDist A1 (t_forall ?X1 ?Y1), H1b : appDist A2 (t_forall ?X2 ?Y2),
      H2a : appDist A1 (t_forall ?X1' ?Y1'), H2b : appDist A2 (t_forall ?X2' ?Y2') |- _ =>
      destruct (IHA1 X1 Y1 X1' Y1' H1a H2a) as [E1 E2];
      destruct (IHA2 X2 Y2 X2' Y2' H1b H2b) as [E3 E4]; subst; split; reflexivity end.
  - (* rcd *) inversion H1.
Qed.

(* Partial application is deterministic for a fixed value and argument. *)
Lemma papp_detK : forall (v:exp) (a:arg) (e1:exp),
  papp v a e1 -> forall z, papp v a z -> e1 = z.
Proof.
  intros v a e1 Hp.
  induction Hp; intros z H2.
  - (* PApp_abs *)
    inversion H2; subst.
    destruct (appDist_arrow_uniqueK B C1 C2 C3 C0 H0 H9) as [HC1 HC2].
    assert (He : e2' = e2'0) by exact (wrapping_detK e2 A e2' H1 e2'0 H10).
    subst. reflexivity.
  - (* PApp_tabs *)
    inversion H2; subst.
    destruct (appDist_all_uniqueK A B1 B2 B3 B0 H1 H9) as [HB1 HB2].
    subst. reflexivity.
  - (* PApp_proj *)
    inversion H2; subst.
    destruct (appDist_rcd_uniqueK A l B l B0 H0 H7) as [_ HB].
    subst. reflexivity.
  - (* PApp_merge *)
    inversion H2; subst.
    rewrite (IHHp1 e0 H1). rewrite (IHHp2 e3 H5). reflexivity.
Qed.

(* Determinism of one step for Inf-typable expressions. *)
Lemma step_det_infK : forall (e:exp) (P:typ),
  Typing nil nil e Inf P ->
  forall x y, step e x -> step e y -> x = y.
Proof.
  intros e.
  induction e as
    [n|X| |i|A e IHe|A e IHe|e1 IHe1 e2 IHe2|e1 IHe1 e2 IHe2
    |e IHe A|l e IHe|e IHe l|e IHe|e IHe A];
    intros P Hty x y Hs1 Hs2.
  - (* var_b *) inversion Hs1.
  - (* var_f *) inversion Hs1.
  - (* top *) inversion Hs1.
  - (* lit *) inversion Hs1.
  - (* abs *) inversion Hty.
  - (* fixpoint *)
    inversion Hty; subst. inversion Hs1; subst. inversion Hs2; subst. reflexivity.
  - (* app *)
    inversion Hty; subst.
    inversion Hs1; subst; inversion Hs2; subst.
    + (* papp / papp *)
      exact (papp_detK e1 (arg_exp e2) x H6 y H8).
    + (* papp / appl *)
      exfalso. exact (value_no_step e1 e1' H2 H8).
    + (* appl / papp *)
      exfalso. exact (value_no_step e1 e1' H3 H6).
    + (* appl / appl *)
      rewrite (IHe1 A H1 e1' e1'0 H6 H8). reflexivity.
  - (* merge *)
    assert (Ht1 : exists A0, Typing nil nil e1 Inf A0).
    { inversion Hty; eauto. }
    destruct Ht1 as [A0 HtA].
    assert (Ht2 : exists B0, Typing nil nil e2 Inf B0).
    { inversion Hty; eauto. }
    destruct Ht2 as [B0 HtB].
    inversion Hs1; subst; inversion Hs2; subst.
    all: try (exfalso; match goal with
              | Hst : step ?v ?w |- _ =>
                  match goal with
                  | Hv : value v |- _ => exact (value_no_step v w Hv Hst)
                  end
              end).
    + rewrite (IHe1 A0 HtA e1' e1'0 H1 H2).
      rewrite (IHe2 B0 HtB e2' e2'0 H3 H5). reflexivity.
    + rewrite (IHe1 A0 HtA e1' e1'0 H3 H5). reflexivity.
    + rewrite (IHe2 B0 HtB e2' e2'0 H3 H5). reflexivity.
  - (* anno *)
    inversion Hty; subst. inversion Hs1; subst; inversion Hs2; subst.
    + destruct (prevalue_chk_infK e H3 P H2) as [P0 Hinf].
      exact (casting_functional_inf_pre e P0 Hinf H3 P x y H5 H8).
    + exfalso. exact (value_no_step e e' H1 H7).
    + exfalso. exact (value_no_step e e' H3 H4).
    + destruct (chk_steppable_infK e P H2 (ex_intro (fun z => step e z) e' H4))
        as [P0 Hinf].
      rewrite (IHe P0 Hinf e' e'0 H4 H6). reflexivity.
  - (* rcd *) inversion Hty.
  - (* proj *)
    assert (HtE : exists P0, Typing nil nil e Inf P0).
    { inversion Hty; eauto. }
    destruct HtE as [P0 HtP].
    inversion Hs1; subst; inversion Hs2; subst.
    + exact (papp_detK e (arg_la l) x H3 y H5).
    + exfalso. exact (value_no_step e e' H1 H4).
    + exfalso. exact (value_no_step e e' H1 H2).
    + rewrite (IHe P0 HtP e' e'0 H2 H3). reflexivity.
  - (* tabs *) inversion Hty.
  - (* tapp *)
    assert (HtE : exists P0, Typing nil nil e Inf P0).
    { inversion Hty; eauto. }
    destruct HtE as [P0 HtP].
    inversion Hs1; subst; inversion Hs2; subst.
    + exact (papp_detK e (arg_typ A) x H3 y H5).
    + exfalso. exact (value_no_step e e' H1 H5).
    + exfalso. exact (value_no_step e e' H2 H3).
    + rewrite (IHe P0 HtP e' e'0 H3 H5). reflexivity.
Qed.


(* Local-closure inversion helpers (copied from agentE4 with K names). *)
Lemma lc_exp_app_invK : forall e1 e2,
  lc_exp (e_app e1 e2) -> lc_exp e1 /\ lc_exp e2.
Proof. intros e1 e2 H. inversion H; subst; auto. Qed.

Lemma lc_exp_proj_invK : forall e l,
  lc_exp (e_proj e l) -> lc_exp e.
Proof. intros e l H. inversion H; subst; auto. Qed.

Lemma lc_exp_tapp_invK : forall e A,
  lc_exp (e_tapp e A) -> lc_exp e /\ lc_typ A.
Proof. intros e A H. inversion H; subst; auto. Qed.

Lemma lc_exp_abs_invK : forall A e,
  lc_exp (e_abs A e) -> lc_typ A /\ (forall x, lc_exp (open_exp_wrt_exp e (e_var_f x))).
Proof. intros A e H. inversion H; subst; auto. Qed.

Lemma lc_exp_tabs_invK : forall e,
  lc_exp (e_tabs e) -> (forall X, lc_exp (open_exp_wrt_typ e (t_tvar_f X))).
Proof. intros e H. inversion H; subst; auto. Qed.

Lemma lc_exp_fixpoint_invK : forall A e,
  lc_exp (e_fixpoint A e) -> lc_typ A /\ (forall x, lc_exp (open_exp_wrt_exp e (e_var_f x))).
Proof. intros A e H. inversion H; subst; auto. Qed.

Lemma lc_exp_open_exp_bodyK : forall e v,
  (forall x, lc_exp (open_exp_wrt_exp e (e_var_f x))) ->
  lc_exp v ->
  lc_exp (open_exp_wrt_exp e v).
Proof.
  intros e v Hbody Hv.
  destruct (atom_fresh (termfv_exp e)) as [x Hx].
  change (lc_exp (open_exp_wrt_exp_rec 0 v e)).
  rewrite <- (agentC.subst_open_exp_exp_fresh 0 x v e Hx).
  apply agentC.lc_exp_subst_exp.
  - exact Hv.
  - exact (Hbody x).
Qed.

Lemma lc_exp_open_exp_typ_bodyK : forall e C,
  (forall X, lc_exp (open_exp_wrt_typ e (t_tvar_f X))) ->
  lc_typ C ->
  lc_exp (open_exp_wrt_typ e C).
Proof.
  intros e C Hbody HC.
  destruct (atom_fresh (typefv_exp e)) as [X HX].
  change (lc_exp (open_exp_wrt_typ_rec 0 C e)).
  rewrite <- (agentC.typsubst_open_exp_typ 0 X C e HC HX).
  apply agentC.lc_exp_typsubst.
  - exact HC.
  - exact (Hbody X).
Qed.

Lemma wrapping_lcK : forall e A e',
  lc_exp e -> wrapping e A e' -> lc_exp e'.
Proof.
  intros e A e' He Hw. revert He.
  induction Hw; intros He.
  - apply lc_e_top.
  - apply lc_e_anno.
    + apply agentK.lc_exp_abs_top.
    + apply agentA.ord_lc_typ. exact H0.
  - apply lc_e_anno.
    + apply agentK.lc_exp_tabs_top.
    + apply agentA.ord_lc_typ. exact H0.
  - apply lc_e_anno.
    + apply agentK.lc_exp_rcd_top.
    + apply agentA.ord_lc_typ. exact H0.
  - apply lc_e_anno.
    + exact He.
    + apply agentA.ord_lc_typ. assumption.
  - apply lc_e_merge; [apply IHHw1; assumption | apply IHHw2; assumption].
Qed.

Lemma casting_lcK : forall v A v',
  lc_exp v -> casting v A v' -> lc_exp v'.
Proof.
  intros v A v' Hv Hc. revert Hv.
  induction Hc; intros Hv.
  - exact Hv.
  - apply lc_e_top.
  - apply lc_e_anno.
    + apply agentK.lc_exp_abs_top.
    + apply agentA.ord_lc_typ. exact H0.
  - apply lc_e_anno.
    + apply agentK.lc_exp_tabs_top.
    + apply agentA.ord_lc_typ. exact H0.
  - apply lc_e_anno.
    + apply agentK.lc_exp_rcd_top.
    + apply agentA.ord_lc_typ. exact H0.
  - apply lc_e_anno.
    + assumption.
    + apply agentA.ord_lc_typ. exact H0.
  - destruct (lc_merge_invK _ _ Hv) as [Hv1 _].
    exact (IHHc Hv1).
  - destruct (lc_merge_invK _ _ Hv) as [_ Hv2].
    exact (IHHc Hv2).
  - apply lc_e_merge; [apply IHHc1; assumption | apply IHHc2; assumption].
Qed.

Lemma papp_lc_typ_arrow_cod_lK : forall A B C,
  appDist A (t_arrow B C) -> lc_typ C.
Proof.
  intros A B C H.
  exact (proj2 (agentB.lc_typ_arrow_inv B C
    (proj2 (agentB.appDist_lc A (t_arrow B C) H)))).
Qed.

Lemma papp_lc_typ_rcd_codK : forall A l C,
  appDist A (t_rcd l C) -> lc_typ C.
Proof.
  intros A l C H.
  exact (agentB.lc_typ_rcd_inv l C
    (proj2 (agentB.appDist_lc A (t_rcd l C) H))).
Qed.

Lemma papp_lc_typ_all_cod_openK : forall A B C,
  lc_typ (t_forall A B) -> lc_typ C ->
  lc_typ (open_typ_wrt_typ B C).
Proof.
  intros A B C Hforall HC.
  destruct (agentB.lc_typ_forall_inv A B Hforall) as [_ HB].
  destruct (atom_fresh (typefv_typ B)) as [X HX].
  change (lc_typ (open_typ_wrt_typ_rec 0 C B)).
  rewrite <- (agentC.typsubst_open_typ 0 X C B HC HX).
  apply agentC.lc_typ_typsubst; [ exact HC | exact (HB X) ].
Qed.

Lemma papp_lcK : forall v arg e,
  lc_exp v -> lc_arg arg -> papp v arg e -> lc_exp e.
Proof.
  intros v arg e Hv Harg Hp. revert Hv Harg.
  induction Hp as
    [ A e1 B e2 e2' C2 C1 Hlcsrc Hdist Hwr
    | e A C B2 B1 Hlcsrc HC Hdist
    | l e A B Hlcsrc Hdist
    | v1 v2 arg5 e1 e2 Hp1 IH1 Hp2 IH2 ];
    intros Hv Harg.
  - (* PApp_abs *)
    destruct (lc_exp_anno_inv _ _ Hv) as [Hinner _].
    destruct (lc_exp_abs_invK _ _ Hinner) as [_ Hbody].
    inversion Harg; subst.
    apply lc_e_anno.
    + apply (lc_exp_open_exp_bodyK e1); [exact Hbody|].
      apply (wrapping_lcK e2 A e2'); assumption.
    + apply (papp_lc_typ_arrow_cod_lK B C1 C2). exact Hdist.
  - (* PApp_tabs *)
    destruct (lc_exp_anno_inv _ _ Hv) as [Hinner _].
    pose proof (lc_exp_tabs_invK e Hinner) as Hbody.
    inversion Harg; subst.
    apply lc_e_anno.
    + apply (lc_exp_open_exp_typ_bodyK e C); [exact Hbody|exact HC].
    + apply (papp_lc_typ_all_cod_openK B1 B2 C).
      * exact (proj2 (agentB.appDist_lc A (t_forall B1 B2) Hdist)).
      * exact HC.
  - (* PApp_proj *)
    destruct (lc_exp_anno_inv _ _ Hv) as [Hinner _].
    inversion Hinner; subst.
    inversion Harg.
    apply lc_e_anno.
    + assumption.
    + apply (papp_lc_typ_rcd_codK A l B). exact Hdist.
  - (* PApp_merge *)
    destruct (lc_merge_invK _ _ Hv) as [Hv1 Hv2].
    apply lc_e_merge.
    + apply (IH1 Hv1 Harg).
    + apply (IH2 Hv2 Harg).
Qed.

Lemma step_lc_expK : forall e e',
  lc_exp e -> step e e' -> lc_exp e'.
Proof.
  intros e e' He Hs. revert He.
  induction Hs; intros He.
  - (* Step_papp *)
    destruct (lc_exp_app_invK _ _ He) as [Hv Hin].
    apply (papp_lcK v (arg_exp e) e').
    + exact Hv.
    + apply lc_arg_exp. exact Hin.
    + exact H0.
  - (* Step_pproj *)
    apply (papp_lcK v (arg_la l) e).
    + apply lc_exp_proj_invK in He. exact He.
    + apply lc_arg_la.
    + exact H0.
  - (* Step_ptapp *)
    destruct (lc_exp_tapp_invK _ _ He) as [Hv HA].
    apply (papp_lcK v (arg_typ A) e).
    + exact Hv.
    + apply lc_arg_typ. exact HA.
    + exact H0.
  - (* Step_annov *)
    destruct (lc_exp_anno_inv _ _ He) as [Hv _].
    apply (casting_lcK v A v'); assumption.
  - (* Step_appl *)
    destruct (lc_exp_app_invK _ _ He) as [He1 He2].
    apply lc_e_app.
    + apply IHHs. exact He1.
    + exact He2.
  - (* Step_merge *)
    destruct (lc_merge_invK _ _ He) as [He1 He2].
    apply lc_e_merge.
    + apply IHHs1. exact He1.
    + apply IHHs2. exact He2.
  - (* Step_mergel *)
    destruct (lc_merge_invK _ _ He) as [He1 He2].
    apply lc_e_merge.
    + apply IHHs. exact He1.
    + exact He2.
  - (* Step_merger *)
    destruct (lc_merge_invK _ _ He) as [He1 He2].
    apply lc_e_merge.
    + exact He1.
    + apply IHHs. exact He2.
  - (* Step_anno *)
    destruct (lc_exp_anno_inv _ _ He) as [He0 _].
    apply lc_e_anno.
    + apply IHHs. exact He0.
    + exact H.
  - (* Step_fix *)
    destruct (lc_exp_fixpoint_invK _ _ H) as [_ Hbody].
    apply lc_e_anno.
    + apply (lc_exp_open_exp_bodyK e (e_fixpoint A e)).
      * exact Hbody.
      * exact H.
    + exact H0.
  - (* Step_proj *)
    apply lc_e_proj.
    apply IHHs.
    apply lc_exp_proj_invK in He. exact He.
  - (* Step_tapp *)
    destruct (lc_exp_tapp_invK _ _ He) as [He0 HA].
    apply lc_e_tapp.
    + apply IHHs. exact He0.
    + exact HA.
Qed.

(* E4's auxiliary B, proved explicitly. *)
Lemma anno_step_anno_consistent_typedK :
  forall e A0 B0 P0 e1' e2',
    lc_typ A0 ->
    lc_typ B0 ->
    Typing nil nil e Chk P0 ->
    step (e_anno e A0) (e_anno e1' A0) ->
    step (e_anno e B0) (e_anno e2' B0) ->
    consistent (e_anno e1' A0) (e_anno e2' B0).
Proof.
  intros e A0 B0 P0 e1' e2' HlcA HlcB Hchk Hs1 Hs2.
  inversion Hs1 as [ v e1 e1'' Hval Hpapp
                   | v l e1 Hval Hpapp
                   | v T1 e1 Hval Hpapp
                   | v T1 v1' Hval Hpv Hcast
                   | e1 e2 e1'' Hlce2 Hstep
                   | e1 e2 e1'' e2'' Hstep1 Hstep2
                   | e1 v2 e1'' Hval Hstep
                   | v1 e2 e2'' Hval Hstep
                   | e1 T1 e1'' HlcT Hstep
                   | T1 e1 Hlcfix HlcT
                   | e1 l e1'' Hstep
                   | e1 T1 e1'' HlcT Hstep ]; subst.
  - (* Step_annov left *)
    inversion Hs2 as [ v2 e2 e2'' Hval2 Hpapp2
                     | v2 l e2 Hval2 Hpapp2
                     | v2 T2 e2 Hval2 Hpapp2
                     | v2 T2 v2' Hval2 Hpv2 Hcast2
                     | e2 e3 e2'' Hlce3 Hstep2
                     | e2 e3 e2'' e3'' Hstep2 Hstep2'
                     | e2 v3 e2'' Hval3 Hstep2
                     | v3 e3 e3'' Hval3 Hstep2
                     | e2 T2 e2'' HlcT2 Hstep2
                     | T2 e2 Hlcfix2 HlcT2
                     | e2 l e2'' Hstep2
                     | e2 T2 e2'' HlcT2 Hstep2 ]; subst.
    + (* both Step_annov *)
      destruct (prevalue_chk_infK e Hpv P0 Hchk) as [Pinf HPinf].
      exact (casting_consistent_inf_source e Pinf HPinf
               A0 B0 (e_anno e1' A0) (e_anno e2' B0) Hcast Hcast2).
    + (* right Step_anno: e is a value and steps *)
      exfalso. exact (value_no_step e e2' Hval Hstep2).
  - (* Step_anno left *)
    inversion Hs2 as [ v2 e2 e2'' Hval2 Hpapp2
                     | v2 l e2 Hval2 Hpapp2
                     | v2 T2 e2 Hval2 Hpapp2
                     | v2 T2 v2' Hval2 Hpv2 Hcast2
                     | e2 e3 e2'' Hlce3 Hstep2
                     | e2 e3 e2'' e3'' Hstep2 Hstep2'
                     | e2 v3 e2'' Hval3 Hstep2
                     | v3 e3 e3'' Hval3 Hstep2
                     | e2 T2 e2'' HlcT2 Hstep2
                     | T2 e2 Hlcfix2 HlcT2
                     | e2 l e2'' Hstep2
                     | e2 T2 e2'' HlcT2 Hstep2 ]; subst.
    + (* right Step_annov: e is a value and steps *)
      exfalso. exact (value_no_step e e1' Hval2 Hstep).
    + (* both Step_anno *)
      destruct (chk_steppable_infK e P0 Hchk
                 (ex_intro (fun z => step e z) e1' Hstep)) as [Pinf HPinf].
      assert (Heq : e1' = e2') by
        exact (step_det_infK e Pinf HPinf e1' e2' Hstep Hstep2).
      subst e2'.
      apply (C_anno e1' A0 B0 HlcA).
      * apply (step_lc_expK e e1' (agentB.typing_lc_exp nil nil e Chk P0 Hchk) Hstep).
      * exact HlcB.
Qed.

(* E4-facing exact name.  agentE4 currently shadows it with a Section
   Variable; deleting that Variable makes E4 use this theorem. *)
Lemma anno_step_anno_consistent_typed :
  forall e A0 B0 P0 e1' e2',
    lc_typ A0 ->
    lc_typ B0 ->
    Typing nil nil e Chk P0 ->
    step (e_anno e A0) (e_anno e1' A0) ->
    step (e_anno e B0) (e_anno e2' B0) ->
    consistent (e_anno e1' A0) (e_anno e2' B0).
Proof.
  exact anno_step_anno_consistent_typedK.
Qed.
End agentK2.
Import agentK2.

Module agentL3.
Import ListNotations.

(* ================================================================== *)
(* Ord-free algorithmic-subtyping substitution.                       *)
(*                                                                    *)
(* The existing [algo_sub_typsubst_mid_gen_nobot] requires [ord C]    *)
(* because it translates ord side conditions through [typsubst_ord].  *)
(* Here we remove that hypothesis.  The strategy is: when a target    *)
(* side condition is not ord, split the target with [TWell_coverage]  *)
(* (or [topLike_not_ord_spl]) and reassemble with [S_and]; splitting  *)
(* preserves well-formedness and decreases [size_typ], so a strong    *)
(* induction on the size of the target closes every constructor.      *)
(* ================================================================== *)

Lemma topLike_forall_inv : forall D A B,
  topLike D (t_forall A B) ->
  exists L, forall X, X \notin L ->
    topLike (cons (X, A) D) (open_typ_wrt_typ B (t_tvar_f X)).
Proof.
  intros D A B H. inversion H; subst. eexists; eassumption.
Qed.

Lemma topLike_spl : forall D B B1 B2,
  spl B B1 B2 -> topLike D B -> topLike D B1 /\ topLike D B2.
Proof.
  intros D B B1 B2 Hspl. revert D.
  induction Hspl as
    [ A B C1 C2 HlcA Hsub IHsub
    | L A B C1 C2 HlcA Hbody IHBODY
    | l B C1 C2 Hsub IHsub
    | A B HlcA HlcB ];
    intros D Htop.
  - apply topLike_arrow_inv in Htop. destruct Htop as [HTA HtopB].
    destruct (IHsub D HtopB) as [H1 H2].
    split; apply TL_arrow; assumption.
  - destruct (topLike_forall_inv D A B Htop) as [L0 Hbody0].
    split.
    + apply (TL_all ((L \u L0))).
      intros X HX. destruct (notin_union X L L0 HX) as [HXL HXL0].
      apply (proj1 (IHBODY X HXL (cons (X, A) D) (Hbody0 X HXL0))).
    + apply (TL_all ((L \u L0))).
      intros X HX. destruct (notin_union X L L0 HX) as [HXL HXL0].
      apply (proj2 (IHBODY X HXL (cons (X, A) D) (Hbody0 X HXL0))).
  - apply topLike_rcd_inv in Htop.
    destruct (IHsub D Htop) as [H1 H2].
    split; apply TL_rcd; assumption.
  - apply topLike_and_inv in Htop. destruct Htop as [H1 H2].
    split; assumption.
Qed.

(* S_top, ord-free: any well-formed source is a subtype of a top-like
   well-formed target. *)
Lemma algo_sub_topL_ordfree : forall n (D:tctx) A B,
    size_typ B <= n ->
    TCWell D -> TWell D A -> topLike D B ->
    algo_sub D A B.
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D A B Hle HTC HTA Htop.
  assert (HTB : TWell D B)
    by (exact (agentA.topLike_TWell D B Htop)).
  destruct (agentG.ord_dec_TWell D B HTB) as [Hord | Hnord];
    [ exact (S_top D A B HTA Hord Htop) | ].
  assert (Hspl : exists B1 B2, spl B B1 B2).
  { exact (agentG.topLike_not_ord_spl D B Htop Hnord). }
  destruct Hspl as (B1 & B2 & Hspl).
  destruct (agentA.spl_TWell D B B1 B2 HTB Hspl) as [HTB1 HTB2].
  destruct (topLike_spl D B B1 B2 Hspl Htop) as [Htop1 Htop2].
  destruct (agentH.spl_size_ltH B B1 B2 Hspl) as [Hlt1 Hlt2].
  apply (S_and D A B B1 B2 Hspl).
  - apply (IH (size_typ B1)); [lia | lia | assumption | assumption | assumption].
  - apply (IH (size_typ B2)); [lia | lia | assumption | assumption | assumption].
Qed.

(* S_bot, ord-free: bottom is a subtype of every well-formed type. *)
Lemma algo_sub_botL_ordfree : forall n (D:tctx) A,
    size_typ A <= n ->
    TCWell D -> TWell D A ->
    algo_sub D t_bot A.
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D A Hle HTC HTA.
  destruct (agentG.ord_dec_TWell D A HTA) as [Hord | Hnord].
  - exact (S_bot D A HTC HTA Hord).
  - assert (Hspl : exists A1 A2, spl A A1 A2).
    { destruct (agentG.coverage_gen_aux n D A Hle HTC HTA)
        as [Hord' | Hrest].
      - exfalso; exact (Hnord Hord').
      - destruct Hrest as [Htop | Hspl].
        + exact (agentG.topLike_not_ord_spl D A Htop Hnord).
        + exact Hspl. }
    destruct Hspl as (A1 & A2 & Hspl).
    destruct (agentA.spl_TWell D A A1 A2 HTA Hspl) as [HTA1 HTA2].
    destruct (agentH.spl_size_ltH A A1 A2 Hspl) as [Hlt1 Hlt2].
    apply (S_and D t_bot A A1 A2 Hspl).
    + apply (IH (size_typ A1)); [lia | lia | assumption | assumption].
    + apply (IH (size_typ A2)); [lia | lia | assumption | assumption].
Qed.

(* S_andl, ord-free.  Given [A <: C], we get [(A ∧ B) <: C] without
   assuming [ord C]. *)
Lemma algo_sub_andlL_ordfree : forall n (D:tctx) A B C,
    size_typ C <= n ->
    TCWell D -> TWell D B -> TWell D C ->
    algo_sub D A C ->
    algo_sub D (t_and A B) C.
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D A B C Hle HTC HTB HTCw HAC.
  destruct (agentG.ord_dec_TWell D C HTCw) as [Hord | Hnord].
  - apply (S_andl D A B C HTB Hord HAC).
  - assert (Hspl : exists C1 C2, spl C C1 C2).
    { destruct (agentG.coverage_gen_aux n D C Hle HTC HTCw)
        as [Hord' | Hrest].
      - exfalso; exact (Hnord Hord').
      - destruct Hrest as [Htop | Hspl].
        + exact (agentG.topLike_not_ord_spl D C Htop Hnord).
        + exact Hspl. }
    destruct Hspl as (C1 & C2 & Hspl).
    destruct (agentA.spl_TWell D C C1 C2 HTCw Hspl) as [HTC1 HTC2].
    destruct (agentK.algo_sub_spl D A C HAC C1 C2 Hspl) as [HAC1 HAC2].
    destruct (agentH.spl_size_ltH C C1 C2 Hspl) as [Hlt1 Hlt2].
    apply (S_and D (t_and A B) C C1 C2 Hspl).
    + apply (IH (size_typ C1)); [lia | lia | assumption | assumption | assumption | assumption].
    + apply (IH (size_typ C2)); [lia | lia | assumption | assumption | assumption | assumption].
Qed.

(* S_andr, ord-free. *)
Lemma algo_sub_andrL_ordfree : forall n (D:tctx) A B C,
    size_typ C <= n ->
    TCWell D -> TWell D A -> TWell D C ->
    algo_sub D B C ->
    algo_sub D (t_and A B) C.
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D A B C Hle HTC HTA HTCw HBC.
  destruct (agentG.ord_dec_TWell D C HTCw) as [Hord | Hnord].
  - apply (S_andr D A B C HTA Hord HBC).
  - assert (Hspl : exists C1 C2, spl C C1 C2).
    { destruct (agentG.coverage_gen_aux n D C Hle HTC HTCw)
        as [Hord' | Hrest].
      - exfalso; exact (Hnord Hord').
      - destruct Hrest as [Htop | Hspl].
        + exact (agentG.topLike_not_ord_spl D C Htop Hnord).
        + exact Hspl. }
    destruct Hspl as (C1 & C2 & Hspl).
    destruct (agentA.spl_TWell D C C1 C2 HTCw Hspl) as [HTC1 HTC2].
    destruct (agentK.algo_sub_spl D B C HBC C1 C2 Hspl) as [HBC1 HBC2].
    destruct (agentH.spl_size_ltH C C1 C2 Hspl) as [Hlt1 Hlt2].
    apply (S_and D (t_and A B) C C1 C2 Hspl).
    + apply (IH (size_typ C1)); [lia | lia | assumption | assumption | assumption | assumption].
    + apply (IH (size_typ C2)); [lia | lia | assumption | assumption | assumption | assumption].
Qed.

(* S_arrow, ord-free.  If the substituted codomain is not ord, split it. *)
Lemma algo_sub_arrowL_ordfree : forall n (D:tctx) A1 B1 A2 B2,
    size_typ (t_arrow A2 B2) <= n ->
    TCWell D -> TWell D (t_arrow A1 B1) -> TWell D (t_arrow A2 B2) ->
    algo_sub D A2 A1 -> algo_sub D B1 B2 ->
    algo_sub D (t_arrow A1 B1) (t_arrow A2 B2).
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D A1 B1 A2 B2 Hle HTC HTWsrc HTWtgt HA2A1 HB1B2.
  destruct (agentA.TWell_arrow_inv D A2 B2 HTWtgt) as [HTWA2 HTWB2].
  assert (HleB2 : size_typ B2 <= n) by (simpl in Hle; lia).
  destruct (agentG.ord_dec_TWell D B2 HTWB2) as [Hord | Hnord].
  - exact (S_arrow D A1 B1 A2 B2 Hord HA2A1 HB1B2).
  - assert (Hspl : exists B21 B22, spl B2 B21 B22).
    { destruct (agentG.coverage_gen_aux n D B2 HleB2 HTC HTWB2)
        as [Hord' | Hrest].
      - exfalso; exact (Hnord Hord').
      - destruct Hrest as [Htop | Hspl].
        + exact (agentG.topLike_not_ord_spl D B2 Htop Hnord).
        + exact Hspl. }
    destruct Hspl as (B21 & B22 & Hspl).
    destruct (agentA.spl_TWell D B2 B21 B22 HTWB2 Hspl) as [HTB21 HTB22].
    destruct (agentK.algo_sub_spl D B1 B2 HB1B2 B21 B22 Hspl) as [HB121 HB122].
    destruct (agentH.spl_size_ltH B2 B21 B22 Hspl) as [Hlt1 Hlt2].
    assert (HlcA2 : lc_typ A2)
      by (exact (agentA.TWell_lc_typ D A2 HTWA2)).
    apply (S_and D (t_arrow A1 B1) (t_arrow A2 B2)
                 (t_arrow A2 B21) (t_arrow A2 B22)).
    + exact (Sp_arrow A2 B2 B21 B22 HlcA2 Hspl).
    + apply (IH (size_typ (t_arrow A2 B21))).
      * simpl in Hle; simpl; lia.
      * simpl; lia.
      * exact HTC.
      * exact HTWsrc.
      * exact (TW_arrow D A2 B21 HTWA2 HTB21).
      * exact HA2A1.
      * exact HB121.
    + apply (IH (size_typ (t_arrow A2 B22))).
      * simpl in Hle; simpl; lia.
      * simpl; lia.
      * exact HTC.
      * exact HTWsrc.
      * exact (TW_arrow D A2 B22 HTWA2 HTB22).
      * exact HA2A1.
      * exact HB122.
Qed.

(* S_rcd, ord-free.  If the substituted body is not ord, split it. *)
Lemma algo_sub_rcdL_ordfree : forall n (D:tctx) l A B,
    size_typ (t_rcd l B) <= n ->
    TCWell D -> TWell D (t_rcd l A) -> TWell D (t_rcd l B) ->
    algo_sub D A B ->
    algo_sub D (t_rcd l A) (t_rcd l B).
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D l A B Hle HTC HTWsrc HTWtgt HAB.
  pose proof (agentA.TWell_rcd_inv D l B HTWtgt) as HTWB.
  assert (HleB : size_typ B <= n) by (simpl in Hle; lia).
  destruct (agentG.ord_dec_TWell D B HTWB) as [Hord | Hnord].
  - exact (S_rcd D l A B Hord HAB).
  - assert (Hspl : exists B1 B2, spl B B1 B2).
    { destruct (agentG.coverage_gen_aux n D B HleB HTC HTWB)
        as [Hord' | Hrest].
      - exfalso; exact (Hnord Hord').
      - destruct Hrest as [Htop | Hspl].
        + exact (agentG.topLike_not_ord_spl D B Htop Hnord).
        + exact Hspl. }
    destruct Hspl as (B1 & B2 & Hspl).
    destruct (agentA.spl_TWell D B B1 B2 HTWB Hspl) as [HTB1 HTB2].
    destruct (agentK.algo_sub_spl D A B HAB B1 B2 Hspl) as [HAB1 HAB2].
    destruct (agentH.spl_size_ltH B B1 B2 Hspl) as [Hlt1 Hlt2].
    apply (S_and D (t_rcd l A) (t_rcd l B)
                 (t_rcd l B1) (t_rcd l B2)).
    + exact (Sp_rcd l B B1 B2 Hspl).
    + apply (IH (size_typ (t_rcd l B1))).
      * simpl in Hle; simpl; lia.
      * simpl; lia.
      * exact HTC.
      * exact (TW_rcd D l A (agentA.TWell_rcd_inv D l A HTWsrc)).
      * exact (TW_rcd D l B1 HTB1).
      * exact HAB1.
    + apply (IH (size_typ (t_rcd l B2))).
      * simpl in Hle; simpl; lia.
      * simpl; lia.
      * exact HTC.
      * exact (TW_rcd D l A (agentA.TWell_rcd_inv D l A HTWsrc)).
      * exact (TW_rcd D l B2 HTB2).
      * exact HAB2.
Qed.

(* Invert a splitting of a forall type. *)
Lemma spl_all_inv : forall A B C1 C2,
    spl (t_forall A B) C1 C2 ->
    exists B1 B2 L,
      C1 = t_forall A B1 /\ C2 = t_forall A B2 /\ lc_typ A /\
      (forall X, X \notin L ->
         spl (open_typ_wrt_typ B (t_tvar_f X))
             (open_typ_wrt_typ B1 (t_tvar_f X))
             (open_typ_wrt_typ B2 (t_tvar_f X))).
Proof.
  intros A B C1 C2 H. inversion H; subst.
  eauto 8.
Qed.

(* S_all, ord-free.  If the substituted target forall is not ord, split
   it with [Sp_all] and use the induction hypothesis on the two forall
   components.  Their bodies split componentwise by [algo_sub_spl]. *)
Lemma algo_sub_allL_ordfree : forall n (D:tctx) A1 B1 A2 B2 (Lb:vars),
    size_typ (t_forall A2 B2) <= n ->
    TCWell D -> TWell D (t_forall A1 B1) -> TWell D (t_forall A2 B2) ->
    algo_sub D A2 A1 ->
    (forall X, X \notin Lb ->
       algo_sub (cons (X,A2) D)
         (open_typ_wrt_typ B1 (t_tvar_f X))
         (open_typ_wrt_typ B2 (t_tvar_f X))) ->
    algo_sub D (t_forall A1 B1) (t_forall A2 B2).
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D A1 B1 A2 B2 Lb Hle HTC HTWsrc HTWtgt HA2A1 Hbody.
  destruct (agentG.ord_dec_TWell D (t_forall A2 B2) HTWtgt)
    as [Hord | Hnord].
  - destruct (agentA.ord_all_inv A2 B2 Hord) as [HlcA2 HordB2].
    exact (S_all Lb D A1 B1 A2 B2
             (fun X _ => HordB2 X) HA2A1 Hbody).
  - assert (Hspl : exists C1 C2, spl (t_forall A2 B2) C1 C2).
    { destruct (agentG.coverage_gen_aux n D (t_forall A2 B2) Hle HTC HTWtgt)
        as [Hord' | Hrest].
      - exfalso; exact (Hnord Hord').
      - destruct Hrest as [Htop | Hspl].
        + exact (agentG.topLike_not_ord_spl D (t_forall A2 B2) Htop Hnord).
        + exact Hspl. }
    destruct Hspl as (C1 & C2 & Hspl).
    destruct (spl_all_inv A2 B2 C1 C2 Hspl)
      as (B21 & B22 & Lsp & Heq1 & Heq2 & HlcA2 & Hspbody).
    subst C1; subst C2.
    destruct (agentA.spl_TWell D (t_forall A2 B2) (t_forall A2 B21)
                (t_forall A2 B22) HTWtgt Hspl) as [HTW1 HTW2].
    destruct (agentH.spl_size_ltH (t_forall A2 B2) (t_forall A2 B21)
                (t_forall A2 B22) Hspl) as [Hlt1 Hlt2].
    apply (S_and D (t_forall A1 B1) (t_forall A2 B2)
                 (t_forall A2 B21) (t_forall A2 B22) Hspl).
    + apply (IH (size_typ (t_forall A2 B21)) ltac:(lia)
               D A1 B1 A2 B21 (Lb \u Lsp)).
      * lia.
      * exact HTC.
      * exact HTWsrc.
      * exact HTW1.
      * exact HA2A1.
      * intros X HX. destruct (notin_union X Lb Lsp HX) as [HX1 HX2].
        exact (proj1 (agentK.algo_sub_spl (cons (X,A2) D)
          (open_typ_wrt_typ B1 (t_tvar_f X))
          (open_typ_wrt_typ B2 (t_tvar_f X))
          (Hbody X HX1)
          (open_typ_wrt_typ B21 (t_tvar_f X))
          (open_typ_wrt_typ B22 (t_tvar_f X))
          (Hspbody X HX2))).
    + apply (IH (size_typ (t_forall A2 B22)) ltac:(lia)
               D A1 B1 A2 B22 (Lb \u Lsp)).
      * lia.
      * exact HTC.
      * exact HTWsrc.
      * exact HTW2.
      * exact HA2A1.
      * intros X HX. destruct (notin_union X Lb Lsp HX) as [HX1 HX2].
        exact (proj2 (agentK.algo_sub_spl (cons (X,A2) D)
          (open_typ_wrt_typ B1 (t_tvar_f X))
          (open_typ_wrt_typ B2 (t_tvar_f X))
          (Hbody X HX1)
          (open_typ_wrt_typ B21 (t_tvar_f X))
          (open_typ_wrt_typ B22 (t_tvar_f X))
          (Hspbody X HX2))).
Qed.

(* ================================================================== *)
(* Algorithmic-subtyping substitution, with no [ord C] hypothesis.    *)
(* Every constructor whose side condition mentions [ord] is replaced  *)
(* by the corresponding ord-free helper above.                        *)
(* ================================================================== *)

Lemma algo_sub_typsubst_mid_ordfree : forall (D0:tctx) A B,
    algo_sub D0 A B ->
    forall D1 X Dom D2, D0 = D1 ++ (X,Dom) :: D2 ->
      X \notin dom (D1 ++ D2) ->
      forall C, TCWell D0 ->
        TCWell (tsubst_mid C X D1 D2) ->
        TWell (tsubst_mid C X D1 D2) C ->
        (topLike nil C \/ ~ botLike Dom) ->
        algo_sub (tsubst_mid C X D1 D2)
                 (typsubst_typ C X A) (typsubst_typ C X B).
Proof.
  intros D0 A B Hsub.
  induction Hsub as
    [D0 Y HTC0 HTA
    |D0 HTC0
    |D0 A0 B0 HTA HordB HtopB
    |D0 A0 HTC0 HTA HordA
    |D0 A0 B0 C0 HTB HordC0 Hsub0 IH0
    |D0 A0 B0 C0 HTA HordC0 Hsub0 IH0
    |D0 A1 B1 A2 B2 HordB2 Hsub1 IH1 Hsub2 IH2
    |L D0 A1 A2 B1 B2 HordBody Hsub1 IH1 Hbody IHBODY
    |D0 l A0 B0 HordB0 Hsub0 IH0
    |D0 A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2];
    intros D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT Htop0.
  - (* S_var *)
    simpl. destruct (eq_var Y X) as [HeqYX|Hne].
    + subst Y. simpl.
      exact (agentH.algo_sub_refl_TWell (tsubst_mid C X D1 D2) C HTCt HCT).
    + apply S_var.
      * exact HTCt.
      * rewrite <- (typsubst_tvar_neq C X Y Hne).
        apply (TWell_typsubst_mid_gen D0 X (t_tvar_f Y) HTA
                 D1 Dom D2 Heq Hfresh C HCT).
  - (* S_int *)
    simpl. apply S_int. exact HTCt.
  - (* S_top *)
    simpl.
    apply (algo_sub_topL_ordfree (size_typ (typsubst_typ C X B0))
             (tsubst_mid C X D1 D2)
             (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + lia.
    + exact HTCt.
    + apply (TWell_typsubst_mid_gen D0 X A0 HTA
               D1 Dom D2 Heq Hfresh C HCT).
    + apply (topLike_typsubst_mid_gen_nobot D0 B0 HtopB
               D1 X Dom D2 Heq Hfresh C HTCt HCT Htop0).
  - (* S_bot *)
    simpl.
    apply (algo_sub_botL_ordfree (size_typ (typsubst_typ C X A0))
             (tsubst_mid C X D1 D2) (typsubst_typ C X A0)).
    + lia.
    + exact HTCt.
    + apply (TWell_typsubst_mid_gen D0 X A0 HTA
               D1 Dom D2 Heq Hfresh C HCT).
  - (* S_andl *)
    simpl.
    assert (HC0 : TWell D0 C0)
      by (apply (algo_sub_TWell_target D0 A0 C0 HTCsrc Hsub0)).
    apply (algo_sub_andlL_ordfree (size_typ (typsubst_typ C X C0))
             (tsubst_mid C X D1 D2)
             (typsubst_typ C X A0) (typsubst_typ C X B0)
             (typsubst_typ C X C0)).
    + lia.
    + exact HTCt.
    + apply (TWell_typsubst_mid_gen D0 X B0 HTB
               D1 Dom D2 Heq Hfresh C HCT).
    + apply (TWell_typsubst_mid_gen D0 X C0 HC0
               D1 Dom D2 Heq Hfresh C HCT).
    + apply (IH0 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT Htop0).
  - (* S_andr *)
    simpl.
    assert (HC0 : TWell D0 C0)
      by (apply (algo_sub_TWell_target D0 B0 C0 HTCsrc Hsub0)).
    apply (algo_sub_andrL_ordfree (size_typ (typsubst_typ C X C0))
             (tsubst_mid C X D1 D2)
             (typsubst_typ C X A0) (typsubst_typ C X B0)
             (typsubst_typ C X C0)).
    + lia.
    + exact HTCt.
    + apply (TWell_typsubst_mid_gen D0 X A0 HTA
               D1 Dom D2 Heq Hfresh C HCT).
    + apply (TWell_typsubst_mid_gen D0 X C0 HC0
               D1 Dom D2 Heq Hfresh C HCT).
    + apply (IH0 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT Htop0).
  - (* S_arrow *)
    simpl.
    set (Dtg := tsubst_mid C X D1 D2).
    pose proof (S_arrow D0 A1 B1 A2 B2 HordB2 Hsub1 Hsub2) as HsubArr.
    destruct (algo_sub_TWell_both D0 (t_arrow A1 B1) (t_arrow A2 B2)
                HTCsrc HsubArr) as [HTWsrc0 HTWtgt0].
    assert (HTWsrcSub : TWell Dtg (t_arrow (typsubst_typ C X A1)
                                           (typsubst_typ C X B1))).
    { unfold Dtg. apply (TWell_typsubst_mid_gen D0 X (t_arrow A1 B1) HTWsrc0
                          D1 Dom D2 Heq Hfresh C HCT). }
    assert (HTWtgtSub : TWell Dtg (t_arrow (typsubst_typ C X A2)
                                           (typsubst_typ C X B2))).
    { unfold Dtg. apply (TWell_typsubst_mid_gen D0 X (t_arrow A2 B2) HTWtgt0
                          D1 Dom D2 Heq Hfresh C HCT). }
    apply (algo_sub_arrowL_ordfree
             (size_typ (t_arrow (typsubst_typ C X A2) (typsubst_typ C X B2)))
             Dtg
             (typsubst_typ C X A1) (typsubst_typ C X B1)
             (typsubst_typ C X A2) (typsubst_typ C X B2)).
    + lia.
    + exact HTCt.
    + exact HTWsrcSub.
    + exact HTWtgtSub.
    + apply (IH1 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT Htop0).
    + apply (IH2 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT Htop0).
  - (* S_all *)
    simpl.
    set (Dtg := tsubst_mid C X D1 D2).
    pose proof (S_all L D0 A1 A2 B1 B2 HordBody Hsub1 Hbody) as HsubAll.
    destruct (algo_sub_TWell_both D0 (t_forall A1 A2) (t_forall B1 B2)
                HTCsrc HsubAll) as [HTWsrc0 HTWtgt0].
    assert (HlcC : lc_typ C) by (apply (TWell_lc Dtg C); exact HCT).
    assert (HTWsrcSub : TWell Dtg (t_forall (typsubst_typ C X A1)
                                            (typsubst_typ C X A2))).
    { unfold Dtg. apply (TWell_typsubst_mid_gen D0 X (t_forall A1 A2) HTWsrc0
                          D1 Dom D2 Heq Hfresh C HCT). }
    assert (HTWtgtSub : TWell Dtg (t_forall (typsubst_typ C X B1)
                                            (typsubst_typ C X B2))).
    { unfold Dtg. apply (TWell_typsubst_mid_gen D0 X (t_forall B1 B2) HTWtgt0
                          D1 Dom D2 Heq Hfresh C HCT). }
    assert (Hdom : algo_sub Dtg (typsubst_typ C X B1) (typsubst_typ C X A1)).
    { unfold Dtg. apply (IH1 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT Htop0). }
    assert (HTB1 : TWell D0 B1)
      by (apply (algo_sub_TWell_source D0 B1 A1 HTCsrc Hsub1)).
    set (Lb := L \u ({{X}} \u (dom D0 \u dom Dtg))).
    assert (HbodySub : forall Z, Z \notin Lb ->
      algo_sub (cons (Z, typsubst_typ C X B1) Dtg)
        (open_typ_wrt_typ (typsubst_typ C X A2) (t_tvar_f Z))
        (open_typ_wrt_typ (typsubst_typ C X B2) (t_tvar_f Z))).
    { intros Z HZ.
      assert (HZL : Z \notin L)
        by (apply (notin_union_1 Z L ({{X}} \u (dom D0 \u dom Dtg))); exact HZ).
      assert (HZrest : Z \notin ({{X}} \u (dom D0 \u dom Dtg)))
        by (apply (notin_union_2 Z L ({{X}} \u (dom D0 \u dom Dtg))); exact HZ).
      assert (HZsing : Z \notin {{X}})
        by (apply (notin_union_1 Z {{X}} (dom D0 \u dom Dtg)); exact HZrest).
      assert (HZdd : Z \notin (dom D0 \u dom Dtg))
        by (apply (notin_union_2 Z {{X}} (dom D0 \u dom Dtg)); exact HZrest).
      assert (HZD0 : Z \notin dom D0)
        by (apply (notin_union_1 Z (dom D0) (dom Dtg)); exact HZdd).
      assert (HZDtg : Z \notin dom Dtg)
        by (apply (notin_union_2 Z (dom D0) (dom Dtg)); exact HZdd).
      assert (HXZ : X <> Z) by (apply (notin_singleton_1 X Z); exact HZsing).
      assert (HZX' : Z <> X) by (intro HeqZX; apply HXZ; symmetry; exact HeqZX).
      assert (Hfresh' : X \notin dom (((Z,B1) :: D1) ++ D2)).
      { apply (notin_dom_mid_cons D1 D2 X Z B1 Hfresh HXZ). }
      assert (HTCsrc' : TCWell (cons (Z,B1) D0)).
      { apply (TCW_cons D0 Z B1 HTCsrc HTB1).
        apply (uniq_cons typ Z B1 D0 (TCWell_uniq D0 HTCsrc) HZD0). }
      assert (HTB1sub : TWell Dtg (typsubst_typ C X B1)).
      { unfold Dtg. apply (TWell_typsubst_mid_gen D0 X B1 HTB1
                           D1 Dom D2 Heq Hfresh C HCT). }
      assert (HTCtg' : TCWell (cons (Z, typsubst_typ C X B1) Dtg)).
      { apply (TCW_cons Dtg Z (typsubst_typ C X B1) HTCt HTB1sub).
        apply (uniq_cons typ Z (typsubst_typ C X B1) Dtg
                         (TCWell_uniq Dtg HTCt) HZDtg). }
      assert (HCtg' : TWell (cons (Z, typsubst_typ C X B1) Dtg) C).
      { apply (TWell_cons_weaken Dtg C Z (typsubst_typ C X B1) HCT). }
      assert (HeqZ : cons (Z,B1) D0 =
                     ((Z,B1) :: D1) ++ (X,Dom) :: D2).
      { simpl. rewrite Heq. reflexivity. }
      pose proof (IHBODY Z HZL ((Z,B1) :: D1) X Dom D2 HeqZ Hfresh'
                    C HTCsrc' HTCtg' HCtg' Htop0) as Hres.
      rewrite (typsubst_open_typ_neq C X HlcC Z A2 HZX') in Hres.
      rewrite (typsubst_open_typ_neq C X HlcC Z B2 HZX') in Hres.
      change (algo_sub (cons (Z, typsubst_typ C X B1) Dtg)
                       (open_typ_wrt_typ (typsubst_typ C X A2) (t_tvar_f Z))
                       (open_typ_wrt_typ (typsubst_typ C X B2) (t_tvar_f Z)))
        in Hres.
      exact Hres. }
    apply (algo_sub_allL_ordfree
             (size_typ (t_forall (typsubst_typ C X B1) (typsubst_typ C X B2)))
             Dtg
             (typsubst_typ C X A1) (typsubst_typ C X A2)
             (typsubst_typ C X B1) (typsubst_typ C X B2) Lb).
    + lia.
    + exact HTCt.
    + exact HTWsrcSub.
    + exact HTWtgtSub.
    + exact Hdom.
    + exact HbodySub.
  - (* S_rcd *)
    simpl.
    set (Dtg := tsubst_mid C X D1 D2).
    pose proof (S_rcd D0 l A0 B0 HordB0 Hsub0) as HsubR.
    destruct (algo_sub_TWell_both D0 (t_rcd l A0) (t_rcd l B0)
                HTCsrc HsubR) as [HTWsrc0 HTWtgt0].
    assert (HTWsrcSub : TWell Dtg (t_rcd l (typsubst_typ C X A0))).
    { unfold Dtg. apply (TWell_typsubst_mid_gen D0 X (t_rcd l A0) HTWsrc0
                          D1 Dom D2 Heq Hfresh C HCT). }
    assert (HTWtgtSub : TWell Dtg (t_rcd l (typsubst_typ C X B0))).
    { unfold Dtg. apply (TWell_typsubst_mid_gen D0 X (t_rcd l B0) HTWtgt0
                          D1 Dom D2 Heq Hfresh C HCT). }
    apply (algo_sub_rcdL_ordfree (size_typ (t_rcd l (typsubst_typ C X B0)))
             Dtg l (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + lia.
    + exact HTCt.
    + exact HTWsrcSub.
    + exact HTWtgtSub.
    + apply (IH0 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT Htop0).
  - (* S_and *)
    simpl.
    apply (S_and (tsubst_mid C X D1 D2)
                 (typsubst_typ C X A0) (typsubst_typ C X B0)
                 (typsubst_typ C X B1) (typsubst_typ C X B2)).
    + apply (typsubst_spl C X).
      * apply (TWell_lc (tsubst_mid C X D1 D2) C); exact HCT.
      * exact Hspl.
    + apply (IH1 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT Htop0).
    + apply (IH2 D1 X Dom D2 Heq Hfresh C HTCsrc HTCt HCT Htop0).
Qed.
End agentL3.
Import agentL3.

Module agentL4.
Import ListNotations.

(* ================================================================== *)
(* Ord-free disjointness preservation under algorithmic subtyping.    *)
(*                                                                    *)
(* agentK2.algo_sub_disjoint_ord needs [ord P] and [ord Q].  Here we  *)
(* remove those: if P (or Q) is not ord, split it with [spl] and      *)
(* recurse on the components, which are strictly smaller.             *)
(* ================================================================== *)

Lemma TCWell_last_TWell_nil : forall (D1:tctx) X Dom,
    TCWell (D1 ++ [(X,Dom)]) -> TWell nil Dom.
Proof.
  induction D1 as [|[Y B] D1 IH]; intros X Dom H.
  - simpl in H. exact (agentA.TCWell_cons_TWell nil X Dom H).
  - simpl in H.
    exact (IH X Dom
             (agentA.TCWell_cons_inv (D1 ++ [(X,Dom)]) Y B H)).
Qed.

Lemma TCWell_last_X_notin_Dom : forall (D1:tctx) X Dom,
    TCWell (D1 ++ [(X,Dom)]) -> X \notin dom D1 ->
    X \notin typefv_typ Dom.
Proof.
  intros D1 X Dom HTC Hfresh.
  assert (HTW : TWell nil Dom)
    by (exact (TCWell_last_TWell_nil D1 X Dom HTC)).
  exact (agentL2.TWell_notin_dom_typefv nil Dom HTW X (notin_dom_nil X)).
Qed.

(* Right/left splitting of disjointness at the target. *)
Lemma disjoint_split_target : forall D P Q Q1 Q2,
    spl Q Q1 Q2 -> disjoint D P Q1 -> disjoint D P Q2 ->
    disjoint D P Q.
Proof.
  intros. exact (D_andr D P Q Q1 Q2 H H0 H1).
Qed.

Lemma disjoint_split_source : forall D P P1 P2 Q,
    spl P P1 P2 -> disjoint D P1 Q -> disjoint D P2 Q ->
    disjoint D P Q.
Proof.
  intros. exact (D_andl D P Q P1 P2 H H0 H1).
Qed.

Lemma algo_sub_disjoint_ordfree_aux : forall (n:nat) (D:tctx) (A B P Q:typ),
    size_typ A + size_typ B + size_typ P + size_typ Q <= n ->
    TCWell D -> TWell D A -> TWell D B ->
    disjoint D A B ->
    algo_sub D A P -> algo_sub D B Q ->
    TWell D P -> TWell D Q ->
    disjoint D P Q.
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D A B P Q Hle HTC HTA HTB Hd HAP HBQ HTP HTQ.
  destruct (agentG.ord_dec_TWell D P HTP) as [HoP | HnP].
  - (* P is ord: split Q if it is not *)
    destruct (agentG.ord_dec_TWell D Q HTQ) as [HoQ | HnQ].
    + (* both ord: agentK2's result *)
      exact (agentK2.algo_sub_disjoint_ord D A B P Q HTC HTA HTB Hd
               HAP HBQ HoP HoQ HTP HTQ).
    + (* Q non-ord: split it *)
      assert (HleQ : size_typ Q <= n) by lia.
      assert (Hspl : exists Q1 Q2, spl Q Q1 Q2).
      { destruct (agentG.coverage_gen_aux n D Q HleQ HTC HTQ)
          as [Hord' | Hrest].
        - exfalso; exact (HnQ Hord').
        - destruct Hrest as [Htop | Hspl].
          + exact (agentG.topLike_not_ord_spl D Q Htop HnQ).
          + exact Hspl. }
      destruct Hspl as (Q1 & Q2 & Hspl).
      destruct (agentA.spl_TWell D Q Q1 Q2 HTQ Hspl) as [HTQ1 HTQ2].
      destruct (agentK.algo_sub_spl D B Q HBQ Q1 Q2 Hspl) as [HBQ1 HBQ2].
      destruct (agentH.spl_size_ltH Q Q1 Q2 Hspl) as [Hlt1 Hlt2].
      apply (disjoint_split_target D P Q Q1 Q2 Hspl).
      * apply (IH (size_typ A + size_typ B + size_typ P + size_typ Q1) ltac:(lia) D A B P Q1).
        -- lia.
        -- exact HTC.
        -- exact HTA.
        -- exact HTB.
        -- exact Hd.
        -- exact HAP.
        -- exact HBQ1.
        -- exact HTP.
        -- exact HTQ1.
      * apply (IH (size_typ A + size_typ B + size_typ P + size_typ Q2) ltac:(lia) D A B P Q2).
        -- lia.
        -- exact HTC.
        -- exact HTA.
        -- exact HTB.
        -- exact Hd.
        -- exact HAP.
        -- exact HBQ2.
        -- exact HTP.
        -- exact HTQ2.
  - (* P non-ord: split it *)
    assert (HleP : size_typ P <= n) by lia.
    assert (Hspl : exists P1 P2, spl P P1 P2).
    { destruct (agentG.coverage_gen_aux n D P HleP HTC HTP)
        as [Hord' | Hrest].
      - exfalso; exact (HnP Hord').
      - destruct Hrest as [Htop | Hspl].
        + exact (agentG.topLike_not_ord_spl D P Htop HnP).
        + exact Hspl. }
    destruct Hspl as (P1 & P2 & Hspl).
    destruct (agentA.spl_TWell D P P1 P2 HTP Hspl) as [HTP1 HTP2].
    destruct (agentK.algo_sub_spl D A P HAP P1 P2 Hspl) as [HAP1 HAP2].
    destruct (agentH.spl_size_ltH P P1 P2 Hspl) as [Hlt1 Hlt2].
    apply (disjoint_split_source D P P1 P2 Q Hspl).
    + apply (IH (size_typ A + size_typ B + size_typ P1 + size_typ Q) ltac:(lia) D A B P1 Q).
      * lia.
      * exact HTC.
      * exact HTA.
      * exact HTB.
      * exact Hd.
      * exact HAP1.
      * exact HBQ.
      * exact HTP1.
      * exact HTQ.
    + apply (IH (size_typ A + size_typ B + size_typ P2 + size_typ Q) ltac:(lia) D A B P2 Q).
      * lia.
      * exact HTC.
      * exact HTA.
      * exact HTB.
      * exact Hd.
      * exact HAP2.
      * exact HBQ.
      * exact HTP2.
      * exact HTQ.
Qed.

Lemma algo_sub_disjoint_ordfree : forall (D:tctx) (A B P Q:typ),
    TCWell D -> TWell D A -> TWell D B ->
    disjoint D A B ->
    algo_sub D A P -> algo_sub D B Q ->
    TWell D P -> TWell D Q ->
    disjoint D P Q.
Proof.
  intros.
  exact (algo_sub_disjoint_ordfree_aux
           (size_typ A + size_typ B + size_typ P + size_typ Q)
           D A B P Q (le_n _) H H0 H1 H2 H3 H4 H5 H6).
Qed.

(* ================================================================== *)
(* Symmetry of disjointness (used when the substituted variable is    *)
(* the head variable of a [D_varr] premise).                          *)
(* ================================================================== *)

Lemma disjoint_axiom_comm : forall A B,
    disjoint_axiom A B -> disjoint_axiom B A.
Proof.
  intros A B H. destruct H as
    [ A1 A2 H1 H2
    | l A0 H0
    | A0 B0 H0 Hf
    | A1 A2 l A0 H1 H2 H0
    | A1 A2 A0 B0 H1 H2 H0 Hf
    | l C A0 B0 Hc H0 Hf
    | A1 A2 H1 H2
    | l A0 H0
    | A0 B0 H0 Hf
    | l A0 A1 A2 H0 H1 H2
    | A0 B0 A1 A2 H0 Hf H1 H2
    | A0 B0 l C H0 Hf Hc
    | l1 A0 l2 B0 H0 HB0 Hneq ].
  - apply Dax_arrowInt; assumption.
  - apply Dax_rcdInt; assumption.
  - apply Dax_allInt; assumption.
  - apply Dax_rcdArrow; assumption.
  - apply Dax_allArrow; assumption.
  - apply Dax_allRcd; assumption.
  - apply Dax_intArrow; assumption.
  - apply Dax_intRcd; assumption.
  - apply Dax_intAll; assumption.
  - apply Dax_arrowRcd; assumption.
  - apply Dax_arrowAll; assumption.
  - apply Dax_rcdAll; assumption.
  - apply Dax_rcdNeq.
    + exact HB0.
    + exact H0.
    + intro Heq; apply Hneq; symmetry; exact Heq.
Qed.

(* [t_and A2 A1] and [t_and A1 A2] are algorithmically mutually
   subtypes; used to transport disjointness across the intersection
   binder that [D_all] introduces. *)
Lemma algo_sub_and_swap : forall (D:tctx) A1 A2,
    TCWell D -> TWell D A1 -> TWell D A2 ->
    algo_sub D (t_and A2 A1) (t_and A1 A2).
Proof.
  intros D A1 A2 HTC HT1 HT2.
  pose proof (agentA.TWell_lc_typ D A1 HT1) as Hlc1.
  pose proof (agentA.TWell_lc_typ D A2 HT2) as Hlc2.
  assert (Hspl : spl (t_and A1 A2) A1 A2) by (apply Sp_and; assumption).
  assert (Hto1 : algo_sub D (t_and A2 A1) A1).
  { apply (algo_sub_andrL_ordfree (size_typ A1) D A2 A1 A1).
    - lia.
    - exact HTC.
    - exact HT2.
    - exact HT1.
    - apply (agentH.algo_sub_refl_TWell D A1 HTC HT1). }
  assert (Hto2 : algo_sub D (t_and A2 A1) A2).
  { apply (algo_sub_andlL_ordfree (size_typ A2) D A2 A1 A2).
    - lia.
    - exact HTC.
    - exact HT1.
    - exact HT2.
    - apply (agentH.algo_sub_refl_TWell D A2 HTC HT2). }
  exact (S_and D (t_and A2 A1) (t_and A1 A2) A1 A2 Hspl Hto1 Hto2).
Qed.

(* Symmetry of disjointness, requiring the context to be well formed
   (the [D_all] case needs to rebuild the extended binder context and
   transport across the swapped intersection binder). *)
Lemma disjoint_comm_TCWell : forall (D:tctx) A B,
    TCWell D -> disjoint D A B -> disjoint D B A.
Proof.
  intros D A B HTC H. revert HTC.
  induction H as
    [ D0 A0 B0 HTC0 HTA HTB Hax
    | D0 A0 B0 HTB HtopA
    | D0 A0 B0 HTA HtopB
    | D0 A1 A2 B1 B2 HT1 HT2 Hbody IH
    | D0 l A0 B0 Hbody IH
    | L D0 A1 B1 A2 B2 HT1 HT2 Hbody IHBODY
    | D0 Y B0 A0 Hb Hsub
    | D0 B0 Y A0 Hb Hsub
    | D0 A0 B0 A1 A2 Hspl Hsub1 IH1 Hsub2 IH2
    | D0 A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2 ];
    intros HTC.
  - apply (D_ax D0 B0 A0 HTC0 HTB HTA).
    exact (disjoint_axiom_comm A0 B0 Hax).
  - apply (D_topr D0 B0 A0 HTB). exact HtopA.
  - apply (D_topl D0 B0 A0 HTA). exact HtopB.
  - apply (D_arrow D0 B1 B2 A1 A2 HT2 HT1). exact (IH HTC).
  - apply (D_rcdEq D0 l B0 A0). exact (IH HTC).
  - apply (D_all (L \u dom D0) D0 A2 B2 A1 B1 HT2 HT1).
    intros X HX.
    destruct (notin_union X L (dom D0) HX) as [HXL HXD].
    assert (HTCext : TCWell (cons (X, t_and A1 A2) D0)).
    { apply (TCW_cons D0 X (t_and A1 A2)).
      - exact HTC.
      - apply TW_and; assumption.
      - apply (uniq_cons_3 typ X (t_and A1 A2) D0).
        + apply (agentA.TCWell_uniq D0 HTC).
        + exact HXD. }
    assert (Hswap : algo_sub D0 (t_and A2 A1) (t_and A1 A2)).
    { exact (algo_sub_and_swap D0 A1 A2 HTC HT1 HT2). }
    exact (agentH4.disjoint_ctx_change nil D0 X (t_and A1 A2) (t_and A2 A1)
             (open_typ_wrt_typ B2 (t_tvar_f X))
             (open_typ_wrt_typ B1 (t_tvar_f X))
             HTCext Hswap (IHBODY X HXL HTCext)).
  - apply (D_varr D0 B0 Y A0 Hb Hsub).
  - apply (D_varl D0 Y B0 A0 Hb Hsub).
  - apply (D_andr D0 B0 A0 A1 A2 Hspl). exact (IH1 HTC). exact (IH2 HTC).
  - apply (D_andl D0 B0 A0 B1 B2 Hspl). exact (IH1 HTC). exact (IH2 HTC).
Qed.

Lemma disjoint_comm_nil : forall A B,
    disjoint nil A B -> disjoint nil B A.
Proof.
  intros A B Hd.
  exact (disjoint_comm_TCWell nil A B TCW_empty Hd).
Qed.

(* ================================================================== *)
(* Ord-free disjointness preservation under type substitution in a    *)
(* context split [D0 = D1 ++ [(X,A)]].  This is the [D2 = nil]       *)
(* version used by the typing induction; the side conditions are      *)
(* exactly those derived from the outer hypothesis [disjoint nil C A].*)
(* ================================================================== *)

Lemma disjoint_typsubst_mid_ordfree : forall C X A,
    lc_typ C ->
    TWell nil C ->
    disjoint nil C A ->
    forall (D0:tctx) P Q,
      disjoint D0 P Q ->
      forall D1, D0 = D1 ++ [(X,A)] ->
        X \notin dom D1 ->
        TCWell D0 ->
        disjoint (subst_tctx C X D1)
                 (typsubst_typ C X P) (typsubst_typ C X Q).
Proof.
  intros C X A Hlc HCT HdCA D0 P Q Hd.
  assert (Htop0 : topLike nil C \/ ~ botLike A)
    by (apply (agentL2.disjoint_nil_topLike_or_not_botLike C A); exact HdCA).
  induction Hd as
    [ D0 A0 B0 HTCax HTA HTB Hax
    | D0 A0 B0 HTB HtopA
    | D0 A0 B0 HTA HtopB
    | D0 A1 A2 B1 B2 HT1 HT2 Hsub IHsub
    | D0 l A0 B0 Hsub IHsub
    | L D0 A1 B1 A2 B2 HT1 HT2 Hbody IHBODY
    | D0 Y B0 A0 Hb Hsub
    | D0 B0 Y A0 Hb Hsub
    | D0 A0 B0 A1 A2 Hspl Hsub1 IH1 Hsub2 IH2
    | D0 A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2 ];
    intros D1 Heq Hfresh HTC0;
    assert (Hfresh_nil : X \notin dom (D1 ++ nil)) by (rewrite app_nil_r; exact Hfresh);
    assert (HTWtgCmid : TWell (tsubst_mid C X D1 nil) C)
      by (apply (agentL2.TWell_nil_weaken (tsubst_mid C X D1 nil)); exact HCT);
    assert (HTCtgmid : TCWell (tsubst_mid C X D1 nil))
      by (rewrite agentL2.tsubst_mid_nil;
          exact (agentL.typsubst_TCWell_drop D1 X A Hfresh
                   ltac:(rewrite <- Heq; exact HTC0) C HCT)).
  - (* D_ax *)
    assert (HTCsplit : TCWell (D1 ++ [(X,A)]))
      by (rewrite <- Heq; exact HTC0).
    assert (HTCtg : TCWell (subst_tctx C X D1))
      by (exact (agentL.typsubst_TCWell_drop D1 X A Hfresh HTCsplit C HCT)).
    assert (HTWtgC : TWell (subst_tctx C X D1) C)
      by (apply (agentL2.TWell_nil_weaken (subst_tctx C X D1)); exact HCT).
    assert (HTP : TWell (subst_tctx C X D1) (typsubst_typ C X A0)).
    { pose proof (agentL.TWell_typsubst_mid_gen D0 X A0 HTA
                    D1 A nil Heq Hfresh_nil C HTWtgCmid) as H'.
      rewrite agentL2.tsubst_mid_nil in H'. exact H'. }
    assert (HTQ : TWell (subst_tctx C X D1) (typsubst_typ C X B0)).
    { pose proof (agentL.TWell_typsubst_mid_gen D0 X B0 HTB
                    D1 A nil Heq Hfresh_nil C HTWtgCmid) as H'.
      rewrite agentL2.tsubst_mid_nil in H'. exact H'. }
    apply (D_ax (subst_tctx C X D1) (typsubst_typ C X A0)
                (typsubst_typ C X B0) HTCtg HTP HTQ).
    apply (agentL.typsubst_disjoint_axiom C X A0 B0 Hlc Hax).
  - (* D_topl *)
    assert (HTCsplit : TCWell (D1 ++ [(X,A)]))
      by (rewrite <- Heq; exact HTC0).
    assert (HTCtg : TCWell (subst_tctx C X D1))
      by (exact (agentL.typsubst_TCWell_drop D1 X A Hfresh HTCsplit C HCT)).
    assert (HTWtgC : TWell (subst_tctx C X D1) C)
      by (apply (agentL2.TWell_nil_weaken (subst_tctx C X D1)); exact HCT).
    assert (HTQ : TWell (subst_tctx C X D1) (typsubst_typ C X B0)).
    { pose proof (agentL.TWell_typsubst_mid_gen D0 X B0 HTB
                    D1 A nil Heq Hfresh_nil C HTWtgCmid) as H'.
      rewrite agentL2.tsubst_mid_nil in H'. exact H'. }
    assert (Htop : topLike (subst_tctx C X D1) (typsubst_typ C X A0)).
    { pose proof (agentL2.topLike_typsubst_mid_gen_nobot D0 A0 HtopA
                    D1 X A nil Heq Hfresh_nil C HTCtgmid HTWtgCmid Htop0) as H'.
      rewrite agentL2.tsubst_mid_nil in H'. exact H'. }
    exact (D_topl (subst_tctx C X D1) (typsubst_typ C X A0)
                  (typsubst_typ C X B0) HTQ Htop).
  - (* D_topr *)
    assert (HTCsplit : TCWell (D1 ++ [(X,A)]))
      by (rewrite <- Heq; exact HTC0).
    assert (HTCtg : TCWell (subst_tctx C X D1))
      by (exact (agentL.typsubst_TCWell_drop D1 X A Hfresh HTCsplit C HCT)).
    assert (HTWtgC : TWell (subst_tctx C X D1) C)
      by (apply (agentL2.TWell_nil_weaken (subst_tctx C X D1)); exact HCT).
    assert (HTP : TWell (subst_tctx C X D1) (typsubst_typ C X A0)).
    { pose proof (agentL.TWell_typsubst_mid_gen D0 X A0 HTA
                    D1 A nil Heq Hfresh_nil C HTWtgCmid) as H'.
      rewrite agentL2.tsubst_mid_nil in H'. exact H'. }
    assert (Htop : topLike (subst_tctx C X D1) (typsubst_typ C X B0)).
    { pose proof (agentL2.topLike_typsubst_mid_gen_nobot D0 B0 HtopB
                    D1 X A nil Heq Hfresh_nil C HTCtgmid HTWtgCmid Htop0) as H'.
      rewrite agentL2.tsubst_mid_nil in H'. exact H'. }
    exact (D_topr (subst_tctx C X D1) (typsubst_typ C X A0)
                  (typsubst_typ C X B0) HTP Htop).
  - (* D_arrow *)
    assert (HTCsplit : TCWell (D1 ++ [(X,A)]))
      by (rewrite <- Heq; exact HTC0).
    assert (HTCtg : TCWell (subst_tctx C X D1))
      by (exact (agentL.typsubst_TCWell_drop D1 X A Hfresh HTCsplit C HCT)).
    assert (HTWtgC : TWell (subst_tctx C X D1) C)
      by (apply (agentL2.TWell_nil_weaken (subst_tctx C X D1)); exact HCT).
    assert (HT1' : TWell (subst_tctx C X D1)
                     (typsubst_typ C X (t_arrow A1 A2))).
    { pose proof (agentL.TWell_typsubst_mid_gen D0 X (t_arrow A1 A2) HT1
                    D1 A nil Heq Hfresh_nil C HTWtgCmid) as H'.
      rewrite agentL2.tsubst_mid_nil in H'. exact H'. }
    assert (HT2' : TWell (subst_tctx C X D1)
                     (typsubst_typ C X (t_arrow B1 B2))).
    { pose proof (agentL.TWell_typsubst_mid_gen D0 X (t_arrow B1 B2) HT2
                    D1 A nil Heq Hfresh_nil C HTWtgCmid) as H'.
      rewrite agentL2.tsubst_mid_nil in H'. exact H'. }
    apply (D_arrow (subst_tctx C X D1)
                   (typsubst_typ C X A1) (typsubst_typ C X A2)
                   (typsubst_typ C X B1) (typsubst_typ C X B2) HT1' HT2').
    exact (IHsub D1 Heq Hfresh HTC0).
  - (* D_rcdEq *)
    apply (D_rcdEq (subst_tctx C X D1) l
                   (typsubst_typ C X A0) (typsubst_typ C X B0)).
    exact (IHsub D1 Heq Hfresh HTC0).
  - (* D_all *)
    assert (HTCsplit : TCWell (D1 ++ [(X,A)]))
      by (rewrite <- Heq; exact HTC0).
    assert (HTWtgC : TWell (subst_tctx C X D1) C)
      by (apply (agentL2.TWell_nil_weaken (subst_tctx C X D1)); exact HCT).
    assert (HT1' : TWell (subst_tctx C X D1) (typsubst_typ C X A1)).
    { pose proof (agentL.TWell_typsubst_mid_gen D0 X A1 HT1
                    D1 A nil Heq Hfresh_nil C HTWtgCmid) as H'.
      rewrite agentL2.tsubst_mid_nil in H'. exact H'. }
    assert (HT2' : TWell (subst_tctx C X D1) (typsubst_typ C X A2)).
    { pose proof (agentL.TWell_typsubst_mid_gen D0 X A2 HT2
                    D1 A nil Heq Hfresh_nil C HTWtgCmid) as H'.
      rewrite agentL2.tsubst_mid_nil in H'. exact H'. }
    apply (D_all (L \u ({{X}} \u dom D1)) (subst_tctx C X D1)
                 (typsubst_typ C X A1) (typsubst_typ C X B1)
                 (typsubst_typ C X A2) (typsubst_typ C X B2) HT1' HT2').
    intros Z HZ.
    assert (HZL : Z \notin L)
      by (apply (notin_union_1 Z L ({{X}} \u dom D1)); exact HZ).
    assert (HZrest : Z \notin ({{X}} \u dom D1))
      by (apply (notin_union_2 Z L ({{X}} \u dom D1)); exact HZ).
    assert (HZsing : Z \notin {{X}})
      by (apply (notin_union_1 Z {{X}} (dom D1)); exact HZrest).
    assert (HZD1 : Z \notin dom D1)
      by (apply (notin_union_2 Z {{X}} (dom D1)); exact HZrest).
    assert (HXZ : X <> Z) by (exact (notin_singleton_1 X Z HZsing)).
    assert (HZX : Z <> X) by (intro Hxz; exact (HXZ (eq_sym Hxz))).
    assert (HZD0 : Z \notin dom D0).
    { intro Hin. rewrite Heq in Hin.
      rewrite (dom_app typ D1 [(X,A)]) in Hin.
      destruct (AtomSetImpl.union_1 Hin)
        as [Hin1 | Hin2].
      - exact (HZD1 Hin1).
      - simpl in Hin2. rewrite add_iff in Hin2.
        destruct Hin2 as [HeqXZ | Hempty].
        + apply HZsing. rewrite singleton_iff. exact HeqXZ.
        + apply AtomSetProperties.Dec.F.empty_iff in Hempty. exact Hempty. }
    assert (Heq' : cons (Z, t_and A1 A2) D0 =
                   cons (Z, t_and A1 A2) D1 ++ [(X,A)]).
    { simpl. rewrite Heq. reflexivity. }
    assert (Hfresh' : X \notin dom (cons (Z, t_and A1 A2) D1))
      by (apply (notin_dom_cons D1 Z (t_and A1 A2) X HXZ Hfresh)).
    assert (HTCext : TCWell (cons (Z, t_and A1 A2) D0)).
    { apply (TCW_cons D0 Z (t_and A1 A2) HTC0).
      - apply TW_and; assumption.
      - apply (uniq_cons_3 typ Z (t_and A1 A2) D0).
        + apply (agentA.TCWell_uniq D0 HTC0).
        + exact HZD0. }
    pose proof (IHBODY Z HZL (cons (Z, t_and A1 A2) D1)
                  Heq' Hfresh' HTCext) as Hres.
    rewrite subst_tctx_cons in Hres.
    simpl in Hres.
    rewrite (agentL.typsubst_open_typ_neq C X Hlc Z B1 HZX) in Hres.
    rewrite (agentL.typsubst_open_typ_neq C X Hlc Z B2 HZX) in Hres.
    exact Hres.
  - (* D_varl *)
    simpl.
    destruct (eq_var Y X) as [HeqYX | Hne].
    + (* the substituted variable is the head binder *)
      subst Y.
      assert (Hb' : binds X A0 (D1 ++ [(X,A)])) by (rewrite <- Heq; exact Hb).
      assert (HA0 : A0 = A)
        by (exact (agentL.notin_dom_app_last D1 X A A0 Hfresh Hb')).
      subst A0.
      try rewrite (agentL.typsubst_tvar_same C X).
      assert (HTCsplit : TCWell (D1 ++ [(X,A)]))
        by (rewrite <- Heq; exact HTC0).
      assert (HTCtg : TCWell (subst_tctx C X D1))
        by (exact (agentL.typsubst_TCWell_drop D1 X A Hfresh HTCsplit C HCT)).
      assert (HTWtgC : TWell (subst_tctx C X D1) C)
        by (apply (agentL2.TWell_nil_weaken (subst_tctx C X D1)); exact HCT).
      assert (HsubT : algo_sub (subst_tctx C X D1) A
                        (typsubst_typ C X B0)).
      { pose proof (agentL3.algo_sub_typsubst_mid_ordfree D0 A B0 Hsub
                      D1 X A nil Heq Hfresh_nil C HTC0 HTCtgmid HTWtgCmid Htop0) as H'.
        rewrite agentL2.tsubst_mid_nil in H'.
        rewrite (agentL.typsubst_typ_id_notin C X A
                   (TCWell_last_X_notin_Dom D1 X A HTCsplit Hfresh)) in H'.
        exact H'. }
      assert (HTAnil : TWell nil A)
        by (exact (TCWell_last_TWell_nil D1 X A HTCsplit)).
      assert (HTWA : TWell (subst_tctx C X D1) A)
        by (apply (agentL2.TWell_nil_weaken (subst_tctx C X D1)); exact HTAnil).
      assert (Hres : disjoint (subst_tctx C X D1)
                       (typsubst_typ C X B0) C).
      { assert (HdAC : disjoint nil A C)
          by (apply (disjoint_comm_nil C A); exact HdCA).
        assert (HdAC' : disjoint (subst_tctx C X D1) A C).
        { apply (agentD.disjoint_weaken nil (subst_tctx C X D1) A C
                   TCW_empty HTCtg).
          - intros W B Hbw. inversion Hbw.
          - exact HdAC. }
        assert (HTWres : TWell (subst_tctx C X D1) (typsubst_typ C X B0))
          by (exact (agentA.algo_sub_TWell_target (subst_tctx C X D1) A
                       (typsubst_typ C X B0) HTCtg HsubT)).
        assert (HreflC : algo_sub (subst_tctx C X D1) C C)
          by (exact (agentH.algo_sub_refl_TWell (subst_tctx C X D1) C
                       HTCtg HTWtgC)).
        exact (algo_sub_disjoint_ordfree (subst_tctx C X D1) A C
                 (typsubst_typ C X B0) C HTCtg HTWA HTWtgC HdAC'
                 HsubT HreflC HTWres HTWtgC). }
      exact (disjoint_comm_TCWell (subst_tctx C X D1)
               (typsubst_typ C X B0) C HTCtg Hres).
    + (* an ordinary remaining binding *)
      try try rewrite (agentL.typsubst_tvar_neq C X Y Hne).
      assert (Hb' : binds Y A0 (D1 ++ [(X,A)])) by (rewrite <- Heq; exact Hb).
      assert (Hb1 : binds Y A0 D1)
        by (exact (agentL.binds_app_neq D1 X A Y A0 Hne Hb')).
      assert (HTCsplit : TCWell (D1 ++ [(X,A)]))
        by (rewrite <- Heq; exact HTC0).
      assert (HTCtg : TCWell (subst_tctx C X D1))
        by (exact (agentL.typsubst_TCWell_drop D1 X A Hfresh HTCsplit C HCT)).
      assert (HTWtgC : TWell (subst_tctx C X D1) C)
        by (apply (agentL2.TWell_nil_weaken (subst_tctx C X D1)); exact HCT).
      assert (HsubT : algo_sub (subst_tctx C X D1)
                        (typsubst_typ C X A0) (typsubst_typ C X B0)).
      { pose proof (agentL3.algo_sub_typsubst_mid_ordfree D0 A0 B0 Hsub
                      D1 X A nil Heq Hfresh_nil C HTC0 HTCtgmid HTWtgCmid Htop0) as H'.
        rewrite agentL2.tsubst_mid_nil in H'. exact H'. }
      apply (D_varl (subst_tctx C X D1) Y
                    (typsubst_typ C X B0) (typsubst_typ C X A0)).
      * apply (agentL.binds_subst_tctx C X D1 Y A0 Hb1).
      * exact HsubT.
  - (* D_varr *)
    simpl.
    destruct (eq_var Y X) as [HeqYX | Hne].
    + subst Y.
      assert (Hb' : binds X A0 (D1 ++ [(X,A)])) by (rewrite <- Heq; exact Hb).
      assert (HA0 : A0 = A)
        by (exact (agentL.notin_dom_app_last D1 X A A0 Hfresh Hb')).
      subst A0.
      try rewrite (agentL.typsubst_tvar_same C X).
      assert (HTCsplit : TCWell (D1 ++ [(X,A)]))
        by (rewrite <- Heq; exact HTC0).
      assert (HTCtg : TCWell (subst_tctx C X D1))
        by (exact (agentL.typsubst_TCWell_drop D1 X A Hfresh HTCsplit C HCT)).
      assert (HTWtgC : TWell (subst_tctx C X D1) C)
        by (apply (agentL2.TWell_nil_weaken (subst_tctx C X D1)); exact HCT).
      assert (HsubT : algo_sub (subst_tctx C X D1) A
                        (typsubst_typ C X B0)).
      { pose proof (agentL3.algo_sub_typsubst_mid_ordfree D0 A B0 Hsub
                      D1 X A nil Heq Hfresh_nil C HTC0 HTCtgmid HTWtgCmid Htop0) as H'.
        rewrite agentL2.tsubst_mid_nil in H'.
        rewrite (agentL.typsubst_typ_id_notin C X A
                   (TCWell_last_X_notin_Dom D1 X A HTCsplit Hfresh)) in H'.
        exact H'. }
      assert (HTAnil : TWell nil A)
        by (exact (TCWell_last_TWell_nil D1 X A HTCsplit)).
      assert (HTWA : TWell (subst_tctx C X D1) A)
        by (apply (agentL2.TWell_nil_weaken (subst_tctx C X D1)); exact HTAnil).
      assert (HdAC : disjoint nil A C)
        by (apply (disjoint_comm_nil C A); exact HdCA).
      assert (HdAC' : disjoint (subst_tctx C X D1) A C).
      { apply (agentD.disjoint_weaken nil (subst_tctx C X D1) A C
                 TCW_empty HTCtg).
        - intros W B Hbw. inversion Hbw.
        - exact HdAC. }
      assert (HTWres : TWell (subst_tctx C X D1) (typsubst_typ C X B0))
        by (exact (agentA.algo_sub_TWell_target (subst_tctx C X D1) A
                     (typsubst_typ C X B0) HTCtg HsubT)).
      assert (HreflC : algo_sub (subst_tctx C X D1) C C)
        by (exact (agentH.algo_sub_refl_TWell (subst_tctx C X D1) C
                     HTCtg HTWtgC)).
      exact (algo_sub_disjoint_ordfree (subst_tctx C X D1) A C
               (typsubst_typ C X B0) C HTCtg HTWA HTWtgC HdAC'
               HsubT HreflC HTWres HTWtgC).
    + try rewrite (agentL.typsubst_tvar_neq C X Y Hne).
      assert (Hb' : binds Y A0 (D1 ++ [(X,A)])) by (rewrite <- Heq; exact Hb).
      assert (Hb1 : binds Y A0 D1)
        by (exact (agentL.binds_app_neq D1 X A Y A0 Hne Hb')).
      assert (HTCsplit : TCWell (D1 ++ [(X,A)]))
        by (rewrite <- Heq; exact HTC0).
      assert (HTCtg : TCWell (subst_tctx C X D1))
        by (exact (agentL.typsubst_TCWell_drop D1 X A Hfresh HTCsplit C HCT)).
      assert (HTWtgC : TWell (subst_tctx C X D1) C)
        by (apply (agentL2.TWell_nil_weaken (subst_tctx C X D1)); exact HCT).
      assert (HsubT : algo_sub (subst_tctx C X D1)
                        (typsubst_typ C X A0) (typsubst_typ C X B0)).
      { pose proof (agentL3.algo_sub_typsubst_mid_ordfree D0 A0 B0 Hsub
                      D1 X A nil Heq Hfresh_nil C HTC0 HTCtgmid HTWtgCmid Htop0) as H'.
        rewrite agentL2.tsubst_mid_nil in H'. exact H'. }
      apply (D_varr (subst_tctx C X D1)
                    (typsubst_typ C X B0) Y (typsubst_typ C X A0)).
      * apply (agentL.binds_subst_tctx C X D1 Y A0 Hb1).
      * exact HsubT.
  - (* D_andl *)
    apply (D_andl (subst_tctx C X D1)
                  (typsubst_typ C X A0) (typsubst_typ C X B0)
                  (typsubst_typ C X A1) (typsubst_typ C X A2)).
    + apply (agentL.typsubst_spl C X Hlc A0 A1 A2 Hspl).
    + exact (IH1 D1 Heq Hfresh HTC0).
    + exact (IH2 D1 Heq Hfresh HTC0).
  - (* D_andr *)
    apply (D_andr (subst_tctx C X D1)
                  (typsubst_typ C X A0) (typsubst_typ C X B0)
                  (typsubst_typ C X B1) (typsubst_typ C X B2)).
    + apply (agentL.typsubst_spl C X Hlc B0 B1 B2 Hspl).
    + exact (IH1 D1 Heq Hfresh HTC0).
    + exact (IH2 D1 Heq Hfresh HTC0).
Qed.


(* ================================================================== *)
(* Ord-free free (context-preserving) algorithm-subtyping             *)
(* substitution.  Direct induction, using the ord-free reconstruction  *)
(* lemmas from agentL3 in place of the [ord] cases.                    *)
(* ================================================================== *)

Lemma algo_sub_typsubst_free_ordfree : forall (D:tctx) A B,
    algo_sub D A B ->
    forall C X, lc_typ C -> X \notin dom D ->
      TCWell D ->
      TCWell (subst_tctx C X D) ->
      TWell (subst_tctx C X D) C ->
      algo_sub (subst_tctx C X D)
               (typsubst_typ C X A) (typsubst_typ C X B).
Proof.
  intros D A B H.
  induction H as
    [ D Y HTC0 HTA
    | D HTC0
    | D A0 B0 HTA HordB HtopB
    | D A0 HTC0 HTA HordA
    | D A0 B0 C0 HTB HordC0 Hsub0 IH0
    | D A0 B0 C0 HTA HordC0 Hsub0 IH0
    | D A1 B1 A2 B2 HordB2 Hsub1 IH1 Hsub2 IH2
    | L D A1 A2 B1 B2 HordBody Hsub1 IH1 Hbody IHBODY
    | D l A0 B0 HordB0 Hsub0 IH0
    | D A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2 ];
    intros C X HC HX HTCsrc HTCt HCT.
  - (* S_var *)
    simpl. destruct (eq_var Y X) as [HeqYX | Hne].
    + subst Y. exfalso.
      assert (Hin : X \in typefv_typ (t_tvar_f X))
        by (simpl; apply AtomSetImpl.singleton_2; reflexivity).
      exact ((agentL2.TWell_notin_dom_typefv D (t_tvar_f X) HTA X HX) Hin).
    + apply (S_var (subst_tctx C X D) Y).
      * exact HTCt.
      * rewrite <- (agentL.typsubst_tvar_neq C X Y Hne).
        apply (agentL2.TWell_typsubst_free_aux D (t_tvar_f Y) HTA C X HC HX).
  - (* S_int *)
    simpl. apply S_int. exact HTCt.
  - (* S_top *)
    simpl.
    apply (agentL3.algo_sub_topL_ordfree (size_typ (typsubst_typ C X B0))
             (subst_tctx C X D)
             (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + lia.
    + exact HTCt.
    + apply (agentL2.TWell_typsubst_free_aux D A0 HTA C X HC HX).
    + apply (agentL2.topLike_typsubst_free_aux D B0 HtopB C X HC HX).
  - (* S_bot *)
    simpl.
    apply (agentL3.algo_sub_botL_ordfree (size_typ (typsubst_typ C X A0))
             (subst_tctx C X D) (typsubst_typ C X A0)).
    + lia.
    + exact HTCt.
    + apply (agentL2.TWell_typsubst_free_aux D A0 HTA C X HC HX).
  - (* S_andl *)
    simpl.
    assert (HC0 : TWell D C0)
      by (apply (agentA.algo_sub_TWell_target D A0 C0 HTCsrc Hsub0)).
    apply (agentL3.algo_sub_andlL_ordfree (size_typ (typsubst_typ C X C0))
             (subst_tctx C X D)
             (typsubst_typ C X A0) (typsubst_typ C X B0)
             (typsubst_typ C X C0)).
    + lia.
    + exact HTCt.
    + apply (agentL2.TWell_typsubst_free_aux D B0 HTB C X HC HX).
    + apply (agentL2.TWell_typsubst_free_aux D C0 HC0 C X HC HX).
    + apply (IH0 C X HC HX HTCsrc HTCt HCT).
  - (* S_andr *)
    simpl.
    assert (HC0 : TWell D C0)
      by (apply (agentA.algo_sub_TWell_target D B0 C0 HTCsrc Hsub0)).
    apply (agentL3.algo_sub_andrL_ordfree (size_typ (typsubst_typ C X C0))
             (subst_tctx C X D)
             (typsubst_typ C X A0) (typsubst_typ C X B0)
             (typsubst_typ C X C0)).
    + lia.
    + exact HTCt.
    + apply (agentL2.TWell_typsubst_free_aux D A0 HTA C X HC HX).
    + apply (agentL2.TWell_typsubst_free_aux D C0 HC0 C X HC HX).
    + apply (IH0 C X HC HX HTCsrc HTCt HCT).
  - (* S_arrow *)
    simpl.
    pose proof (S_arrow D A1 B1 A2 B2 HordB2 Hsub1 Hsub2) as HsubArr.
    destruct (agentA.algo_sub_TWell_both D (t_arrow A1 B1) (t_arrow A2 B2)
                HTCsrc HsubArr) as [HTWsrc0 HTWtgt0].
    apply (agentL3.algo_sub_arrowL_ordfree
             (size_typ (t_arrow (typsubst_typ C X A2) (typsubst_typ C X B2)))
             (subst_tctx C X D)
             (typsubst_typ C X A1) (typsubst_typ C X B1)
             (typsubst_typ C X A2) (typsubst_typ C X B2)).
    + lia.
    + exact HTCt.
    + apply (agentL2.TWell_typsubst_free_aux D (t_arrow A1 B1) HTWsrc0 C X HC HX).
    + apply (agentL2.TWell_typsubst_free_aux D (t_arrow A2 B2) HTWtgt0 C X HC HX).
    + apply (IH1 C X HC HX HTCsrc HTCt HCT).
    + apply (IH2 C X HC HX HTCsrc HTCt HCT).
  - (* S_all *)
    set (Dtg := subst_tctx C X D).
    assert (HTB1 : TWell D B1)
      by (apply (agentA.algo_sub_TWell_source D B1 A1 HTCsrc Hsub1)).
    pose proof (S_all L D A1 A2 B1 B2 HordBody Hsub1 Hbody) as HsubAll.
    destruct (agentA.algo_sub_TWell_both D (t_forall A1 A2) (t_forall B1 B2)
                HTCsrc HsubAll) as [HTWsrc0 HTWtgt0].
    assert (HTWsrcSub : TWell Dtg (t_forall (typsubst_typ C X A1)
                                            (typsubst_typ C X A2))).
    { unfold Dtg. apply (agentL2.TWell_typsubst_free_aux D (t_forall A1 A2)
                          HTWsrc0 C X HC HX). }
    assert (HTWtgtSub : TWell Dtg (t_forall (typsubst_typ C X B1)
                                            (typsubst_typ C X B2))).
    { unfold Dtg. apply (agentL2.TWell_typsubst_free_aux D (t_forall B1 B2)
                          HTWtgt0 C X HC HX). }
    set (Lb := L \u ({{X}} \u (dom D \u dom Dtg))).
    assert (HbodySub : forall Z, Z \notin Lb ->
      algo_sub (cons (Z, typsubst_typ C X B1) Dtg)
        (open_typ_wrt_typ (typsubst_typ C X A2) (t_tvar_f Z))
        (open_typ_wrt_typ (typsubst_typ C X B2) (t_tvar_f Z))).
    { intros Z HZ.
      assert (HZL : Z \notin L)
        by (apply (notin_union_1 Z L ({{X}} \u (dom D \u dom Dtg))); exact HZ).
      assert (HZrest : Z \notin ({{X}} \u (dom D \u dom Dtg)))
        by (apply (notin_union_2 Z L ({{X}} \u (dom D \u dom Dtg))); exact HZ).
      assert (HZsing : Z \notin {{X}})
        by (apply (notin_union_1 Z {{X}} (dom D \u dom Dtg)); exact HZrest).
      assert (HZdd : Z \notin (dom D \u dom Dtg))
        by (apply (notin_union_2 Z {{X}} (dom D \u dom Dtg)); exact HZrest).
      assert (HZD : Z \notin dom D)
        by (apply (notin_union_1 Z (dom D) (dom Dtg)); exact HZdd).
      assert (HZDtg : Z \notin dom Dtg)
        by (apply (notin_union_2 Z (dom D) (dom Dtg)); exact HZdd).
      assert (HXZ : X <> Z) by (exact (notin_singleton_1 X Z HZsing)).
      assert (HZX : Z <> X) by (intro Hxz; exact (HXZ (eq_sym Hxz))).
      assert (HTCsrc' : TCWell (cons (Z,B1) D)).
      { apply (TCW_cons D Z B1 HTCsrc HTB1).
        apply (uniq_cons typ Z B1 D (agentA.TCWell_uniq D HTCsrc) HZD). }
      assert (HTB1sub : TWell Dtg (typsubst_typ C X B1)).
      { unfold Dtg. apply (agentL2.TWell_typsubst_free_aux D B1 HTB1 C X HC HX). }
      assert (HTCtg' : TCWell (cons (Z, typsubst_typ C X B1) Dtg)).
      { apply (TCW_cons Dtg Z (typsubst_typ C X B1) HTCt HTB1sub).
        apply (uniq_cons typ Z (typsubst_typ C X B1) Dtg
                         (agentA.TCWell_uniq Dtg HTCt) HZDtg). }
      assert (HCtg' : TWell (cons (Z, typsubst_typ C X B1) Dtg) C)
        by (apply (agentI2.TWell_cons_weaken Dtg C Z (typsubst_typ C X B1) HCT)).
      assert (Hfresh' : X \notin dom (cons (Z,B1) D))
        by (apply (notin_dom_cons D Z B1 X HXZ HX)).
      pose proof (IHBODY Z HZL C X HC Hfresh' HTCsrc' HTCtg' HCtg') as Hres.
      rewrite (agentL.typsubst_open_typ_neq C X HC Z A2 HZX) in Hres.
      rewrite (agentL.typsubst_open_typ_neq C X HC Z B2 HZX) in Hres.
      change (algo_sub (cons (Z, typsubst_typ C X B1) Dtg)
                       (open_typ_wrt_typ (typsubst_typ C X A2) (t_tvar_f Z))
                       (open_typ_wrt_typ (typsubst_typ C X B2) (t_tvar_f Z)))
        in Hres.
      exact Hres. }
    apply (agentL3.algo_sub_allL_ordfree
             (size_typ (t_forall (typsubst_typ C X B1) (typsubst_typ C X B2)))
             Dtg
             (typsubst_typ C X A1) (typsubst_typ C X A2)
             (typsubst_typ C X B1) (typsubst_typ C X B2) Lb).
    + lia.
    + exact HTCt.
    + exact HTWsrcSub.
    + exact HTWtgtSub.
    + apply (IH1 C X HC HX HTCsrc HTCt HCT).
    + exact HbodySub.
  - (* S_rcd *)
    simpl.
    pose proof (S_rcd D l A0 B0 HordB0 Hsub0) as HsubR.
    destruct (agentA.algo_sub_TWell_both D (t_rcd l A0) (t_rcd l B0)
                HTCsrc HsubR) as [HTWsrc0 HTWtgt0].
    apply (agentL3.algo_sub_rcdL_ordfree
             (size_typ (t_rcd l (typsubst_typ C X B0))) (subst_tctx C X D) l
             (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + lia.
    + exact HTCt.
    + apply (agentL2.TWell_typsubst_free_aux D (t_rcd l A0) HTWsrc0 C X HC HX).
    + apply (agentL2.TWell_typsubst_free_aux D (t_rcd l B0) HTWtgt0 C X HC HX).
    + apply (IH0 C X HC HX HTCsrc HTCt HCT).
  - (* S_and *)
    simpl. apply (S_and (subst_tctx C X D)
                        (typsubst_typ C X A0) (typsubst_typ C X B0)
                        (typsubst_typ C X B1) (typsubst_typ C X B2)).
    + apply (agentL.typsubst_spl C X HC B0 B1 B2 Hspl).
    + apply (IH1 C X HC HX HTCsrc HTCt HCT).
    + apply (IH2 C X HC HX HTCsrc HTCt HCT).
Qed.

(* ================================================================== *)
(* Ord-free free disjointness preservation under type substitution.   *)
(* ================================================================== *)

Lemma disjoint_typsubst_free_ordfree : forall (D:tctx) A B,
    disjoint D A B ->
    forall C X, lc_typ C -> X \notin dom D ->
      TCWell D ->
      TCWell (subst_tctx C X D) ->
      TWell (subst_tctx C X D) C ->
      disjoint (subst_tctx C X D)
               (typsubst_typ C X A) (typsubst_typ C X B).
Proof.
  intros D A B H.
  induction H as
    [ D A0 B0 HTC0 HTA HTB Hax
    | D A0 B0 HTB HtopA
    | D A0 B0 HTA HtopB
    | D A1 A2 B1 B2 HT1 HT2 Hsub IHsub
    | D l A0 B0 Hsub IHsub
    | L D A1 B1 A2 B2 HT1 HT2 Hbody IHBODY
    | D Y B0 A0 Hb Hsub
    | D B0 Y A0 Hb Hsub
    | D A0 B0 A1 A2 Hspl Hsub1 IH1 Hsub2 IH2
    | D A0 B0 B1 B2 Hspl Hsub1 IH1 Hsub2 IH2 ];
    intros C X HC HX HTCsrc HTCt HCT.
  - (* D_ax *)
    simpl. apply D_ax.
    + exact HTCt.
    + apply (agentL2.TWell_typsubst_free_aux D A0 HTA C X HC HX).
    + apply (agentL2.TWell_typsubst_free_aux D B0 HTB C X HC HX).
    + apply (agentL.typsubst_disjoint_axiom C X A0 B0 HC Hax).
  - (* D_topl *)
    simpl. apply D_topl.
    + apply (agentL2.TWell_typsubst_free_aux D B0 HTB C X HC HX).
    + apply (agentL2.topLike_typsubst_free_aux D A0 HtopA C X HC HX).
  - (* D_topr *)
    simpl. apply D_topr.
    + apply (agentL2.TWell_typsubst_free_aux D A0 HTA C X HC HX).
    + apply (agentL2.topLike_typsubst_free_aux D B0 HtopB C X HC HX).
  - (* D_arrow *)
    simpl. apply D_arrow.
    + apply (agentL2.TWell_typsubst_free_aux D (t_arrow A1 A2) HT1 C X HC HX).
    + apply (agentL2.TWell_typsubst_free_aux D (t_arrow B1 B2) HT2 C X HC HX).
    + apply (IHsub C X HC HX HTCsrc HTCt HCT).
  - (* D_rcdEq *)
    simpl. apply D_rcdEq.
    apply (IHsub C X HC HX HTCsrc HTCt HCT).
  - (* D_all *)
    set (Dtg := subst_tctx C X D).
    apply (D_all (L \u ({{X}} \u (dom D \u dom Dtg))) Dtg
                 (typsubst_typ C X A1) (typsubst_typ C X B1)
                 (typsubst_typ C X A2) (typsubst_typ C X B2)).
    + apply (agentL2.TWell_typsubst_free_aux D A1 HT1 C X HC HX).
    + apply (agentL2.TWell_typsubst_free_aux D A2 HT2 C X HC HX).
    + intros Z HZ.
      assert (HZL : Z \notin L)
        by (apply (notin_union_1 Z L ({{X}} \u (dom D \u dom Dtg))); exact HZ).
      assert (HZrest : Z \notin ({{X}} \u (dom D \u dom Dtg)))
        by (apply (notin_union_2 Z L ({{X}} \u (dom D \u dom Dtg))); exact HZ).
      assert (HZsing : Z \notin {{X}})
        by (apply (notin_union_1 Z {{X}} (dom D \u dom Dtg)); exact HZrest).
      assert (HZdd : Z \notin (dom D \u dom Dtg))
        by (apply (notin_union_2 Z {{X}} (dom D \u dom Dtg)); exact HZrest).
      assert (HZD : Z \notin dom D)
        by (apply (notin_union_1 Z (dom D) (dom Dtg)); exact HZdd).
      assert (HZDtg : Z \notin dom Dtg)
        by (apply (notin_union_2 Z (dom D) (dom Dtg)); exact HZdd).
      assert (HXZ : X <> Z) by (exact (notin_singleton_1 X Z HZsing)).
      assert (HZX : Z <> X) by (intro Hxz; exact (HXZ (eq_sym Hxz))).
      assert (HTCsrc' : TCWell (cons (Z, t_and A1 A2) D)).
      { apply (TCW_cons D Z (t_and A1 A2) HTCsrc).
        - apply TW_and; assumption.
        - apply (uniq_cons typ Z (t_and A1 A2) D
                         (agentA.TCWell_uniq D HTCsrc) HZD). }
      assert (HTWtg' : TWell Dtg (typsubst_typ C X (t_and A1 A2))).
      { unfold Dtg. apply (agentL2.TWell_typsubst_free_aux D (t_and A1 A2)
                            (TW_and D A1 A2 HT1 HT2) C X HC HX). }
      assert (HTCtg' : TCWell (cons (Z, typsubst_typ C X (t_and A1 A2)) Dtg)).
      { apply (TCW_cons Dtg Z (typsubst_typ C X (t_and A1 A2)) HTCt HTWtg').
        apply (uniq_cons typ Z (typsubst_typ C X (t_and A1 A2)) Dtg
                         (agentA.TCWell_uniq Dtg HTCt) HZDtg). }
      assert (HCtg' : TWell (cons (Z, typsubst_typ C X (t_and A1 A2)) Dtg) C)
        by (apply (agentI2.TWell_cons_weaken Dtg C Z
                     (typsubst_typ C X (t_and A1 A2)) HCT)).
      assert (HXcons : X \notin dom (cons (Z, t_and A1 A2) D))
        by (apply (notin_dom_cons D Z (t_and A1 A2) X HXZ HX)).
      pose proof (IHBODY Z HZL C X HC HXcons HTCsrc' HTCtg' HCtg') as Hres.
      rewrite subst_tctx_cons in Hres.
      simpl in Hres.
      rewrite (agentL.typsubst_open_typ_neq C X HC Z B1 HZX) in Hres.
      rewrite (agentL.typsubst_open_typ_neq C X HC Z B2 HZX) in Hres.
      exact Hres.
  - (* D_varl *)
    simpl. destruct (eq_var Y X) as [HeqYX | Hne].
    + subst Y. exfalso.
      assert (Hin : X \in typefv_typ (t_tvar_f X))
        by (simpl; apply AtomSetImpl.singleton_2; reflexivity).
      assert (HTW : TWell D (t_tvar_f X)) by (apply (TW_var D X A0 Hb)).
      exact ((agentL2.TWell_notin_dom_typefv D (t_tvar_f X) HTW X HX) Hin).
    + apply (D_varl (subst_tctx C X D) Y
                    (typsubst_typ C X B0) (typsubst_typ C X A0)).
      * apply (agentL.binds_subst_tctx C X D Y A0 Hb).
      * apply (algo_sub_typsubst_free_ordfree D A0 B0 Hsub C X HC HX
                 HTCsrc HTCt HCT).
  - (* D_varr *)
    simpl. destruct (eq_var Y X) as [HeqYX | Hne].
    + subst Y. exfalso.
      assert (Hin : X \in typefv_typ (t_tvar_f X))
        by (simpl; apply AtomSetImpl.singleton_2; reflexivity).
      assert (HTW : TWell D (t_tvar_f X)) by (apply (TW_var D X A0 Hb)).
      exact ((agentL2.TWell_notin_dom_typefv D (t_tvar_f X) HTW X HX) Hin).
    + apply (D_varr (subst_tctx C X D)
                    (typsubst_typ C X B0) Y (typsubst_typ C X A0)).
      * apply (agentL.binds_subst_tctx C X D Y A0 Hb).
      * apply (algo_sub_typsubst_free_ordfree D A0 B0 Hsub C X HC HX
                 HTCsrc HTCt HCT).
  - (* D_andl *)
    simpl. apply (D_andl (subst_tctx C X D)
                         (typsubst_typ C X A0) (typsubst_typ C X B0)
                         (typsubst_typ C X A1) (typsubst_typ C X A2)).
    + apply (agentL.typsubst_spl C X HC A0 A1 A2 Hspl).
    + apply (IH1 C X HC HX HTCsrc HTCt HCT).
    + apply (IH2 C X HC HX HTCsrc HTCt HCT).
  - (* D_andr *)
    simpl. apply (D_andr (subst_tctx C X D)
                         (typsubst_typ C X A0) (typsubst_typ C X B0)
                         (typsubst_typ C X B1) (typsubst_typ C X B2)).
    + apply (agentL.typsubst_spl C X HC B0 B1 B2 Hspl).
    + apply (IH1 C X HC HX HTCsrc HTCt HCT).
    + apply (IH2 C X HC HX HTCsrc HTCt HCT).
Qed.

(* ================================================================== *)
(* Consistency preservation without [ord C].                           *)
(* ================================================================== *)

Lemma typsubst_consistent_ordfree : forall C X,
    lc_typ C -> TWell nil C ->
    forall u v, consistent u v ->
      consistent (typsubst_exp C X u) (typsubst_exp C X v).
Proof.
  intros C X HC HCT u v H.
  induction H as
    [ i
    | e A B HlcA Hlce HlcB
    | u1 u2 A B Hp1 Hp2 Hdisj Hpv1 Hpv2
    | u1 u2 u H1 IH1 H2 IH2
    | u u1 u2 H1 IH1 H2 IH2 ].
  - simpl. apply C_lit.
  - simpl. apply C_anno.
    + apply lc_typ_typsubst; assumption.
    + apply lc_exp_typsubst; assumption.
    + apply lc_typ_typsubst; assumption.
  - simpl. apply (C_disjoint (typsubst_exp C X u1) (typsubst_exp C X u2)
                              (typsubst_typ C X A) (typsubst_typ C X B)).
    + apply (agentL2.typsubst_pType C X HC u1 A Hp1).
    + apply (agentL2.typsubst_pType C X HC u2 B Hp2).
    + apply (disjoint_typsubst_free_ordfree nil A B Hdisj C X HC
               (agentL2.notin_dom_nil X)).
      * simpl. exact TCW_empty.
      * simpl. exact TCW_empty.
      * simpl. exact HCT.
    + apply (agentL2.typsubst_prevalue C X HC u1 Hpv1).
    + apply (agentL2.typsubst_prevalue C X HC u2 Hpv2).
  - simpl. apply C_mergel; assumption.
  - simpl. apply C_merger; assumption.
Qed.

(* ================================================================== *)
(* Ord-free free typing substitution (the source context does not     *)
(* bind the substituted variable).                                    *)
(* ================================================================== *)

Lemma typing_typsubst_free_ordfree : forall C X,
    lc_typ C -> TWell nil C ->
    forall (D0:tctx) (G0:ctx) e d A, Typing D0 G0 e d A ->
      X \notin dom D0 ->
      Typing (subst_tctx C X D0) (subst_ctx C X G0)
             (typsubst_exp C X e) d (typsubst_typ C X A).
Proof.
  intros C X HC HCT D0 G0 e d A Hty.
  induction Hty as
    [ D0 G0 HTC0 HCW0 Hu0
    | D0 G0 i HTC0 HCW0 Hu0
    | D0 G0 x A0 HTC0 HCW0 Hb Hu0
    | L D0 G0 A0 e B1 B2 Hsub Hbody IHBODY
    | D0 G0 e1 e2 C0 A0 B0 Ht1 IH1 Hdist Ht2 IH2
    | L D0 G0 e A0 B0 HCW0 Hbody IHBODY
    | D0 G0 e A0 C2 B0 C1 Ht IH Hdist Hdisj
    | D0 G0 e l C0 A0 Ht IH Hdist
    | D0 G0 l e A0 Ht IH
    | D0 G0 e1 e2 A0 B0 Ht1 IH1 Ht2 IH2 Hdisj
    | D0 G0 e A0 B0 Ht1 IH1 Ht2 IH2
    | D0 G0 e A0 Ht IH
    | L D0 G0 A0 e Hbody IHBODY
    | D0 G0 u1 u2 A0 B0 HTC0 HCW0 Hu0 Ht1 IH1 Ht2 IH2 Hcons
    | D0 G0 e B0 A0 Ht IH Hsub ];
    intros HX;
    assert (HCTt : TWell (subst_tctx C X D0) C)
      by (apply (agentL2.TWell_nil_weaken (subst_tctx C X D0)); exact HCT).
  - (* Typ_top *)
    simpl. apply Typ_top.
    + apply (agentL2.TCWell_typsubst_free_aux D0 HTC0 C X HC HX).
    + apply (agentL2.CWell_typsubst_free_aux D0 G0 HCW0 C X HC HX).
    + apply (agentL.uniq_subst_ctx C X G0 Hu0).
  - (* Typ_lit *)
    simpl. apply Typ_lit.
    + apply (agentL2.TCWell_typsubst_free_aux D0 HTC0 C X HC HX).
    + apply (agentL2.CWell_typsubst_free_aux D0 G0 HCW0 C X HC HX).
    + apply (agentL.uniq_subst_ctx C X G0 Hu0).
  - (* Typ_var *)
    simpl. apply (Typ_var (subst_tctx C X D0) (subst_ctx C X G0)
                          x (typsubst_typ C X A0)).
    + apply (agentL2.TCWell_typsubst_free_aux D0 HTC0 C X HC HX).
    + apply (agentL2.CWell_typsubst_free_aux D0 G0 HCW0 C X HC HX).
    + apply (agentL.binds_subst_ctx C X G0 x A0 Hb).
    + apply (agentL.uniq_subst_ctx C X G0 Hu0).
  - (* Typ_abs *)
    simpl.
    destruct (atom_fresh L) as [x Hx].
    assert (HTCsrc : TCWell D0).
    { exact (proj1 (typing_env_wf D0 (cons (x,A0) G0)
                      (open_exp_wrt_exp e (e_var_f x)) Chk B2 (Hbody x Hx))). }
    assert (HTCt : TCWell (subst_tctx C X D0))
      by (apply (agentL2.TCWell_typsubst_free_aux D0 HTCsrc C X HC HX)).
    apply (Typ_abs L (subst_tctx C X D0) (subst_ctx C X G0)
                   (typsubst_typ C X A0) (typsubst_exp C X e)
                   (typsubst_typ C X B1) (typsubst_typ C X B2)).
    + apply (algo_sub_typsubst_free_ordfree D0 B1 A0 Hsub C X HC HX
               HTCsrc HTCt HCTt).
    + intros x' Hx'.
      pose proof (IHBODY x' Hx' HX) as Hres.
      rewrite (agentL.typsubst_open_exp C X e (e_var_f x')) in Hres.
      simpl in Hres. exact Hres.
  - (* Typ_app *)
    simpl. apply (Typ_app (subst_tctx C X D0) (subst_ctx C X G0)
                          (typsubst_exp C X e1) (typsubst_exp C X e2)
                          (typsubst_typ C X C0) (typsubst_typ C X A0)
                          (typsubst_typ C X B0)).
    + apply (IH1 HX).
    + apply (agentL.typsubst_appDist C X HC A0 (t_arrow B0 C0) Hdist).
    + apply (IH2 HX).
  - (* Typ_tabs *)
    simpl. apply (Typ_tabs (L \u ({{X}} \u dom D0))
                           (subst_tctx C X D0) (subst_ctx C X G0)
                           (typsubst_exp C X e)
                           (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + apply (agentL2.CWell_typsubst_free_aux D0 G0 HCW0 C X HC HX).
    + intros Y HY.
      assert (HYL : Y \notin L)
        by (apply (notin_union_1 Y L ({{X}} \u dom D0)); exact HY).
      assert (HYrest : Y \notin ({{X}} \u dom D0))
        by (apply (notin_union_2 Y L ({{X}} \u dom D0)); exact HY).
      assert (HYsing : Y \notin {{X}})
        by (apply (notin_union_1 Y {{X}} (dom D0)); exact HYrest).
      assert (HYD : Y \notin dom D0)
        by (apply (notin_union_2 Y {{X}} (dom D0)); exact HYrest).
      assert (HXY : X <> Y) by (exact (notin_singleton_1 X Y HYsing)).
      assert (HYX : Y <> X) by (intro Hxy; exact (HXY (eq_sym Hxy))).
      assert (HXcons : X \notin dom (cons (Y,A0) D0))
        by (apply (notin_dom_cons D0 Y A0 X HXY HX)).
      pose proof (IHBODY Y HYL HXcons) as Hres.
      rewrite subst_tctx_cons in Hres.
      rewrite (agentL.typsubst_open_exp_typ_neq C X HC Y e HYX) in Hres.
      rewrite (agentL.typsubst_open_typ_neq C X HC Y B0 HYX) in Hres.
      exact Hres.
  - (* Typ_tapp *)
    simpl. rewrite (agentL2.typsubst_open_typ_any C X HC C2 A0).
    apply (Typ_tapp (subst_tctx C X D0) (subst_ctx C X G0)
                    (typsubst_exp C X e) (typsubst_typ C X A0)
                    (typsubst_typ C X C2) (typsubst_typ C X B0)
                    (typsubst_typ C X C1)).
    + apply (IH HX).
    + apply (agentL.typsubst_appDist C X HC B0 (t_forall C1 C2) Hdist).
    + assert (HTCsrc : TCWell D0)
        by (exact (proj1 (typing_env_wf D0 G0 e Inf B0 Ht))).
      assert (HTCt : TCWell (subst_tctx C X D0))
        by (apply (agentL2.TCWell_typsubst_free_aux D0 HTCsrc C X HC HX)).
      exact (disjoint_typsubst_free_ordfree D0 A0 C1 Hdisj C X HC HX
               HTCsrc HTCt HCTt).
  - (* Typ_proj *)
    simpl. apply (Typ_proj (subst_tctx C X D0) (subst_ctx C X G0)
                           (typsubst_exp C X e) l
                           (typsubst_typ C X C0) (typsubst_typ C X A0)).
    + apply (IH HX).
    + apply (agentL.typsubst_appDist C X HC A0 (t_rcd l C0) Hdist).
  - (* Typ_rcd *)
    simpl. apply (Typ_rcd (subst_tctx C X D0) (subst_ctx C X G0) l
                          (typsubst_exp C X e) (typsubst_typ C X A0)).
    apply (IH HX).
  - (* Typ_merge *)
    simpl. apply (Typ_merge (subst_tctx C X D0) (subst_ctx C X G0)
                            (typsubst_exp C X e1) (typsubst_exp C X e2)
                            (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + apply (IH1 HX).
    + apply (IH2 HX).
    + assert (HTCsrc : TCWell D0)
        by (exact (proj1 (typing_env_wf D0 G0 e1 Inf A0 Ht1))).
      assert (HTCt : TCWell (subst_tctx C X D0))
        by (apply (agentL2.TCWell_typsubst_free_aux D0 HTCsrc C X HC HX)).
      exact (disjoint_typsubst_free_ordfree D0 A0 B0 Hdisj C X HC HX
               HTCsrc HTCt HCTt).
  - (* Typ_inter *)
    simpl. apply (Typ_inter (subst_tctx C X D0) (subst_ctx C X G0)
                            (typsubst_exp C X e)
                            (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + apply (IH1 HX).
    + apply (IH2 HX).
  - (* Typ_anno *)
    simpl. apply (Typ_anno (subst_tctx C X D0) (subst_ctx C X G0)
                           (typsubst_exp C X e) (typsubst_typ C X A0)).
    apply (IH HX).
  - (* Typ_fix *)
    simpl. apply (Typ_fix L (subst_tctx C X D0) (subst_ctx C X G0)
                         (typsubst_typ C X A0) (typsubst_exp C X e)).
    intros x Hx.
    pose proof (IHBODY x Hx HX) as Hres.
    rewrite (agentL.typsubst_open_exp C X e (e_var_f x)) in Hres.
    simpl in Hres. exact Hres.
  - (* Typ_mergev *)
    simpl. apply (Typ_mergev (subst_tctx C X D0) (subst_ctx C X G0)
                             (typsubst_exp C X u1) (typsubst_exp C X u2)
                             (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + apply (agentL2.TCWell_typsubst_free_aux D0 HTC0 C X HC HX).
    + apply (agentL2.CWell_typsubst_free_aux D0 G0 HCW0 C X HC HX).
    + apply (agentL.uniq_subst_ctx C X G0 Hu0).
    + apply (IH1 (agentL2.notin_dom_nil X)).
    + apply (IH2 (agentL2.notin_dom_nil X)).
    + apply (typsubst_consistent_ordfree C X HC HCT u1 u2 Hcons).
  - (* Typ_sub *)
    simpl. apply (Typ_sub (subst_tctx C X D0) (subst_ctx C X G0)
                          (typsubst_exp C X e)
                          (typsubst_typ C X B0) (typsubst_typ C X A0)).
    + apply (IH HX).
    + assert (HTCsrc : TCWell D0)
        by (exact (proj1 (typing_env_wf D0 G0 e Inf A0 Ht))).
      assert (HTCt : TCWell (subst_tctx C X D0))
        by (apply (agentL2.TCWell_typsubst_free_aux D0 HTCsrc C X HC HX)).
      exact (algo_sub_typsubst_free_ordfree D0 A0 B0 Hsub C X HC HX
               HTCsrc HTCt HCTt).
Qed.

(* ================================================================== *)
(* Ord-free context-splitting typing substitution.                    *)
(* The disjointness-preservation family of agentL2 is derived here    *)
(* from the single outer hypothesis [disjoint nil C T0].               *)
(* ================================================================== *)

Lemma typing_typsubst_mid_ordfree : forall C X T0,
    lc_typ C -> TWell nil C -> disjoint nil C T0 ->
    forall (D0:tctx) (G0:ctx) e d B, Typing D0 G0 e d B ->
      forall D1, D0 = D1 ++ [(X,T0)] -> X \notin dom D1 ->
        Typing (tsubst_mid C X D1 nil) (subst_ctx C X G0)
               (typsubst_exp C X e) d (typsubst_typ C X B).
Proof.
  intros C X T0 HlcC HCT HdCA D0 G0 e d B Hty.
  induction Hty as
    [ D0 G0 HTC0 HCW0 Hu0
    | D0 G0 i HTC0 HCW0 Hu0
    | D0 G0 x A0 HTC0 HCW0 Hb Hu0
    | L D0 G0 A0 e B1 B2 Hsub Hbody IHBODY
    | D0 G0 e1 e2 C0 A0 B0 Ht1 IH1 Hdist Ht2 IH2
    | L D0 G0 e A0 B0 HCW0 Hbody IHBODY
    | D0 G0 e A0 C2 B0 C1 Ht IH Hdist Hdisj
    | D0 G0 e l C0 A0 Ht IH Hdist
    | D0 G0 l e A0 Ht IH
    | D0 G0 e1 e2 A0 B0 Ht1 IH1 Ht2 IH2 Hdisj
    | D0 G0 e A0 B0 Ht1 IH1 Ht2 IH2
    | D0 G0 e A0 Ht IH
    | L D0 G0 A0 e Hbody IHBODY
    | D0 G0 u1 u2 A0 B0 HTC0 HCW0 Hu0 Ht1 IH1 Ht2 IH2 Hcons
    | D0 G0 e B0 A0 Ht IH Hsub ];
    intros D1 Heq Hfresh;
    assert (Hfresh_nil : X \notin dom (D1 ++ nil))
      by (rewrite app_nil_r; exact Hfresh);
    assert (HCTmid : TWell (tsubst_mid C X D1 nil) C)
      by (apply (agentL2.TWell_nil_weaken (tsubst_mid C X D1 nil)); exact HCT);
    assert (Htop0 : topLike nil C \/ ~ botLike T0)
      by (apply (agentL2.disjoint_nil_topLike_or_not_botLike C T0); exact HdCA).
  - (* Typ_top *)
    simpl. apply (Typ_top (tsubst_mid C X D1 nil) (subst_ctx C X G0)).
    + assert (HTCsplit : TCWell (D1 ++ [(X,T0)]))
        by (rewrite <- Heq; exact HTC0).
      rewrite agentL2.tsubst_mid_nil.
      exact (agentL.typsubst_TCWell_drop D1 X T0 Hfresh HTCsplit C HCT).
    + apply (agentL.CWell_typsubst_mid_gen D0 G0 HCW0 D1 X T0 nil
               Heq Hfresh_nil C HCTmid).
    + apply (agentL.uniq_subst_ctx C X G0 Hu0).
  - (* Typ_lit *)
    simpl. apply (Typ_lit (tsubst_mid C X D1 nil) (subst_ctx C X G0) i).
    + assert (HTCsplit : TCWell (D1 ++ [(X,T0)]))
        by (rewrite <- Heq; exact HTC0).
      rewrite agentL2.tsubst_mid_nil.
      exact (agentL.typsubst_TCWell_drop D1 X T0 Hfresh HTCsplit C HCT).
    + apply (agentL.CWell_typsubst_mid_gen D0 G0 HCW0 D1 X T0 nil
               Heq Hfresh_nil C HCTmid).
    + apply (agentL.uniq_subst_ctx C X G0 Hu0).
  - (* Typ_var *)
    simpl. apply (Typ_var (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                          x (typsubst_typ C X A0)).
    + assert (HTCsplit : TCWell (D1 ++ [(X,T0)]))
        by (rewrite <- Heq; exact HTC0).
      rewrite agentL2.tsubst_mid_nil.
      exact (agentL.typsubst_TCWell_drop D1 X T0 Hfresh HTCsplit C HCT).
    + apply (agentL.CWell_typsubst_mid_gen D0 G0 HCW0 D1 X T0 nil
               Heq Hfresh_nil C HCTmid).
    + apply (agentL.binds_subst_ctx C X G0 x A0 Hb).
    + apply (agentL.uniq_subst_ctx C X G0 Hu0).
  - (* Typ_abs *)
    simpl.
    destruct (atom_fresh L) as [x Hx].
    assert (HTCsrc : TCWell D0).
    { exact (proj1 (typing_env_wf D0 (cons (x,A0) G0)
                      (open_exp_wrt_exp e (e_var_f x)) Chk B2 (Hbody x Hx))). }
    assert (HTCsplit : TCWell (D1 ++ [(X,T0)]))
      by (rewrite <- Heq; exact HTCsrc).
    assert (HTCt : TCWell (tsubst_mid C X D1 nil)).
    { rewrite agentL2.tsubst_mid_nil.
      exact (agentL.typsubst_TCWell_drop D1 X T0 Hfresh HTCsplit C HCT). }
    apply (Typ_abs L (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                   (typsubst_typ C X A0) (typsubst_exp C X e)
                   (typsubst_typ C X B1) (typsubst_typ C X B2)).
    + apply (agentL3.algo_sub_typsubst_mid_ordfree D0 B1 A0 Hsub
               D1 X T0 nil Heq Hfresh_nil C HTCsrc HTCt HCTmid Htop0).
    + intros x' Hx'.
      pose proof (IHBODY x' Hx' D1 Heq Hfresh) as Hres.
      rewrite (agentL.typsubst_open_exp C X e (e_var_f x')) in Hres.
      simpl in Hres. exact Hres.
  - (* Typ_app *)
    simpl. apply (Typ_app (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                          (typsubst_exp C X e1) (typsubst_exp C X e2)
                          (typsubst_typ C X C0) (typsubst_typ C X A0)
                          (typsubst_typ C X B0)).
    + apply (IH1 D1 Heq Hfresh).
    + apply (agentL.typsubst_appDist C X HlcC A0 (t_arrow B0 C0) Hdist).
    + apply (IH2 D1 Heq Hfresh).
  - (* Typ_tabs *)
    simpl. apply (Typ_tabs (L \u ({{X}} \u dom D1))
                           (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                           (typsubst_exp C X e)
                           (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + apply (agentL.CWell_typsubst_mid_gen D0 G0 HCW0 D1 X T0 nil
               Heq Hfresh_nil C HCTmid).
    + intros Y HY.
      assert (HYL : Y \notin L)
        by (apply (notin_union_1 Y L ({{X}} \u dom D1)); exact HY).
      assert (HYrest : Y \notin ({{X}} \u dom D1))
        by (apply (notin_union_2 Y L ({{X}} \u dom D1)); exact HY).
      assert (HYsing : Y \notin {{X}})
        by (apply (notin_union_1 Y {{X}} (dom D1)); exact HYrest).
      assert (HYD1 : Y \notin dom D1)
        by (apply (notin_union_2 Y {{X}} (dom D1)); exact HYrest).
      assert (HXY : X <> Y) by (exact (notin_singleton_1 X Y HYsing)).
      assert (HYX : Y <> X) by (intro Hyx; exact (HXY (eq_sym Hyx))).
      assert (Hfresh' : X \notin dom ((Y,A0) :: D1))
        by (apply (notin_dom_cons D1 Y A0 X HXY Hfresh)).
      assert (Heq' : cons (Y,A0) D0 = ((Y,A0) :: D1) ++ [(X,T0)]).
      { simpl. rewrite Heq. reflexivity. }
      pose proof (IHBODY Y HYL ((Y,A0) :: D1) Heq' Hfresh') as Hres.
      rewrite (agentL.typsubst_open_exp_typ_neq C X HlcC Y e HYX) in Hres.
      rewrite (agentL.typsubst_open_typ_neq C X HlcC Y B0 HYX) in Hres.
      exact Hres.
  - (* Typ_tapp *)
    simpl. rewrite (agentL2.typsubst_open_typ_any C X HlcC C2 A0).
    apply (Typ_tapp (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                    (typsubst_exp C X e) (typsubst_typ C X A0)
                    (typsubst_typ C X C2) (typsubst_typ C X B0)
                    (typsubst_typ C X C1)).
    + apply (IH D1 Heq Hfresh).
    + apply (agentL.typsubst_appDist C X HlcC B0 (t_forall C1 C2) Hdist).
    + assert (HTCsrc : TCWell D0)
        by (exact (proj1 (typing_env_wf D0 G0 e Inf B0 Ht))).
      assert (Hdsub : disjoint (subst_tctx C X D1)
                        (typsubst_typ C X A0) (typsubst_typ C X C1)).
      { exact (disjoint_typsubst_mid_ordfree C X T0 HlcC HCT HdCA
                 D0 A0 C1 Hdisj D1 Heq Hfresh HTCsrc). }
      rewrite agentL2.tsubst_mid_nil. exact Hdsub.
  - (* Typ_proj *)
    simpl. apply (Typ_proj (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                           (typsubst_exp C X e) l
                           (typsubst_typ C X C0) (typsubst_typ C X A0)).
    + apply (IH D1 Heq Hfresh).
    + apply (agentL.typsubst_appDist C X HlcC A0 (t_rcd l C0) Hdist).
  - (* Typ_rcd *)
    simpl. apply (Typ_rcd (tsubst_mid C X D1 nil) (subst_ctx C X G0) l
                          (typsubst_exp C X e) (typsubst_typ C X A0)).
    apply (IH D1 Heq Hfresh).
  - (* Typ_merge *)
    simpl. apply (Typ_merge (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                            (typsubst_exp C X e1) (typsubst_exp C X e2)
                            (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + apply (IH1 D1 Heq Hfresh).
    + apply (IH2 D1 Heq Hfresh).
    + assert (HTCsrc : TCWell D0)
        by (exact (proj1 (typing_env_wf D0 G0 e1 Inf A0 Ht1))).
      assert (Hdsub : disjoint (subst_tctx C X D1)
                        (typsubst_typ C X A0) (typsubst_typ C X B0)).
      { exact (disjoint_typsubst_mid_ordfree C X T0 HlcC HCT HdCA
                 D0 A0 B0 Hdisj D1 Heq Hfresh HTCsrc). }
      rewrite agentL2.tsubst_mid_nil. exact Hdsub.
  - (* Typ_inter *)
    simpl. apply (Typ_inter (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                            (typsubst_exp C X e)
                            (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + apply (IH1 D1 Heq Hfresh).
    + apply (IH2 D1 Heq Hfresh).
  - (* Typ_anno *)
    simpl. apply (Typ_anno (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                           (typsubst_exp C X e) (typsubst_typ C X A0)).
    apply (IH D1 Heq Hfresh).
  - (* Typ_fix *)
    simpl. apply (Typ_fix L (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                         (typsubst_typ C X A0) (typsubst_exp C X e)).
    intros x Hx.
    pose proof (IHBODY x Hx D1 Heq Hfresh) as Hres.
    rewrite (agentL.typsubst_open_exp C X e (e_var_f x)) in Hres.
    simpl in Hres. exact Hres.
  - (* Typ_mergev *)
    simpl. apply (Typ_mergev (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                             (typsubst_exp C X u1) (typsubst_exp C X u2)
                             (typsubst_typ C X A0) (typsubst_typ C X B0)).
    + assert (HTCsplit : TCWell (D1 ++ [(X,T0)]))
        by (rewrite <- Heq; exact HTC0).
      rewrite agentL2.tsubst_mid_nil.
      exact (agentL.typsubst_TCWell_drop D1 X T0 Hfresh HTCsplit C HCT).
    + apply (agentL.CWell_typsubst_mid_gen D0 G0 HCW0 D1 X T0 nil
               Heq Hfresh_nil C HCTmid).
    + apply (agentL.uniq_subst_ctx C X G0 Hu0).
    + apply (typing_typsubst_free_ordfree C X HlcC HCT nil nil u1 Inf A0 Ht1
               (agentL2.notin_dom_nil X)).
    + apply (typing_typsubst_free_ordfree C X HlcC HCT nil nil u2 Inf B0 Ht2
               (agentL2.notin_dom_nil X)).
    + apply (typsubst_consistent_ordfree C X HlcC HCT u1 u2 Hcons).
  - (* Typ_sub *)
    simpl. apply (Typ_sub (tsubst_mid C X D1 nil) (subst_ctx C X G0)
                          (typsubst_exp C X e)
                          (typsubst_typ C X B0) (typsubst_typ C X A0)).
    + apply (IH D1 Heq Hfresh).
    + assert (HTCsrc : TCWell D0)
        by (exact (proj1 (typing_env_wf D0 G0 e Inf A0 Ht))).
      assert (HTCsplit : TCWell (D1 ++ [(X,T0)]))
        by (rewrite <- Heq; exact HTCsrc).
      assert (HTCt : TCWell (tsubst_mid C X D1 nil)).
      { rewrite agentL2.tsubst_mid_nil.
        exact (agentL.typsubst_TCWell_drop D1 X T0 Hfresh HTCsplit C HCT). }
      exact (agentL3.algo_sub_typsubst_mid_ordfree D0 A0 B0 Hsub
               D1 X T0 nil Heq Hfresh_nil C HTCsrc HTCt HCTmid Htop0).
Qed.

(* ================================================================== *)
(* Final target lemma, exact shape required by [papp_agent], with no  *)
(* [ord] hypothesis and no assumed disjointness-preservation family.  *)
(* ================================================================== *)

Lemma typing_typsubst_tabs : forall body A B2 C X,
    lc_typ C ->
    X \notin typefv_exp body ->
    X \notin typefv_typ B2 ->
    disjoint nil C A ->
    TWell nil A ->
    TWell nil C ->
    Typing (cons (X,A) nil) nil
      (open_exp_wrt_typ body (t_tvar_f X)) Chk
      (open_typ_wrt_typ B2 (t_tvar_f X)) ->
    Typing nil nil (open_exp_wrt_typ body C) Chk (open_typ_wrt_typ B2 C).
Proof.
  intros body A B2 C X HlcC HXb HXB HdCA HTA HTC Hbody.
  pose proof (typing_typsubst_mid_ordfree C X A HlcC HTC HdCA
                (cons (X,A) nil) nil
                (open_exp_wrt_typ body (t_tvar_f X)) Chk
                (open_typ_wrt_typ B2 (t_tvar_f X)) Hbody
                nil eq_refl (agentL2.notin_dom_nil X)) as Hres.
  change (Typing nil nil
            (typsubst_exp C X (open_exp_wrt_typ body (t_tvar_f X))) Chk
            (typsubst_typ C X (open_typ_wrt_typ B2 (t_tvar_f X)))) in Hres.
  rewrite (agentL2.typsubst_open_exp_typ_any C X HlcC body (t_tvar_f X)) in Hres.
  rewrite (agentL2.typsubst_open_typ_any C X HlcC B2 (t_tvar_f X)) in Hres.
  rewrite (agentL2.typsubst_exp_id_notin C X body HXb) in Hres.
  rewrite (agentL.typsubst_typ_id_notin C X B2 HXB) in Hres.
  rewrite (agentL.typsubst_tvar_same C X) in Hres.
  exact Hres.
Qed.

Print typing_typsubst_tabs.
End agentL4.
Import agentL4.

Module subst_agent.
Import ListNotations.


Lemma degree_typ_open_self : forall n A, degree_typ_wrt_typ n A ->
  forall k B, k >= n -> open_typ_wrt_typ_rec k B A = A.
Proof.
  intros n A H. induction H; intros k B0 Hk; simpl; try reflexivity.
  - (* tvar_b *) destruct (lt_eq_lt_dec n2 k) as [ [ Hlt | Heq ] | Hgt ]; [reflexivity|lia|lia].
  - (* forall *) rewrite (IHdegree_typ_wrt_typ1 k B0 Hk). rewrite (IHdegree_typ_wrt_typ2 (S k) B0); [reflexivity|lia].
  - rewrite (IHdegree_typ_wrt_typ1 k B0 Hk). rewrite (IHdegree_typ_wrt_typ2 k B0 Hk). reflexivity.
  - rewrite (IHdegree_typ_wrt_typ1 k B0 Hk). rewrite (IHdegree_typ_wrt_typ2 k B0 Hk). reflexivity.
  - rewrite (IHdegree_typ_wrt_typ k B0 Hk). reflexivity.
Qed.

Lemma lc_typ_open_self : forall A, lc_typ A -> forall k B, open_typ_wrt_typ_rec k B A = A.
Proof. intros A H k B0. apply (degree_typ_open_self 0 A). apply (lc_typ_deg A); assumption. lia. Qed.

Lemma degree_exp_open_exp_self : forall n e, degree_exp_wrt_exp n e ->
  forall k u, k >= n -> open_exp_wrt_exp_rec k u e = e.
Proof.
  intros n e H. induction H; intros k u0 Hk; simpl; try reflexivity.
  - (* var_b *) destruct (lt_eq_lt_dec n2 k) as [ [ Hlt | Heq ] | Hgt ]; [reflexivity|lia|lia].
  - rewrite (IHdegree_exp_wrt_exp (S k) u0); [reflexivity|lia].
  - rewrite (IHdegree_exp_wrt_exp (S k) u0); [reflexivity|lia].
  - rewrite (IHdegree_exp_wrt_exp1 k u0 Hk), (IHdegree_exp_wrt_exp2 k u0 Hk). reflexivity.
  - rewrite (IHdegree_exp_wrt_exp1 k u0 Hk), (IHdegree_exp_wrt_exp2 k u0 Hk). reflexivity.
  - rewrite (IHdegree_exp_wrt_exp k u0 Hk). reflexivity.
  - rewrite (IHdegree_exp_wrt_exp k u0 Hk). reflexivity.
  - rewrite (IHdegree_exp_wrt_exp k u0 Hk). reflexivity.
  - rewrite (IHdegree_exp_wrt_exp k u0 Hk). reflexivity.
  - rewrite (IHdegree_exp_wrt_exp k u0 Hk). reflexivity.
Qed.

Lemma lc_open_exp_self : forall e, lc_exp e -> forall k u, open_exp_wrt_exp_rec k u e = e.
Proof. intros e H k u0. apply (degree_exp_open_exp_self 0 e). apply lc_exp_deg_exp; assumption. lia. Qed.

Lemma degree_exp_typ_open_self : forall n e, degree_exp_wrt_typ n e ->
  forall k A, k >= n -> open_exp_wrt_typ_rec k A e = e.
Proof.
  intros n e H. induction H as
    [n x|n n2|n|n i|n A1 e1 HA He IH1|n A1 e1 HA He IH1|n e1 e2 H1 IH1 H2 IH2|n e1 e2 H1 IH1 H2 IH2|n e1 A1 He IH1 HA|n l e1 H1 IH1|n e1 l H1 IH1|n e1 H1 IH1|n e1 A1 He IH1 HA];
    intros k A0 Hk; simpl; try reflexivity.
  - rewrite (degree_typ_open_self n A1 HA k A0 Hk). rewrite (IH1 k A0 Hk). reflexivity.
  - rewrite (degree_typ_open_self n A1 HA k A0 Hk). rewrite (IH1 k A0 Hk). reflexivity.
  - rewrite (IH1 k A0 Hk), (IH2 k A0 Hk). reflexivity.
  - rewrite (IH1 k A0 Hk), (IH2 k A0 Hk). reflexivity.
  - rewrite (IH1 k A0 Hk). rewrite (degree_typ_open_self n A1 HA k A0 Hk). reflexivity.
  - rewrite (IH1 k A0 Hk). reflexivity.
  - rewrite (IH1 k A0 Hk). reflexivity.
  - rewrite (IH1 (S k) A0); [reflexivity|lia].
  - rewrite (IH1 k A0 Hk). rewrite (degree_typ_open_self n A1 HA k A0 Hk). reflexivity.
Qed.

Lemma lc_open_typ_self : forall e, lc_exp e -> forall k A, open_exp_wrt_typ_rec k A e = e.
Proof. intros e H k A0. apply (degree_exp_typ_open_self 0 e). apply lc_exp_deg; assumption. lia. Qed.

Lemma open_exp_subst_exp_comm : forall k u v x e,
  lc_exp v -> ~ AtomSetImpl.In x (termfv_exp u) ->
  open_exp_wrt_exp_rec k u (subst_exp v x e) = subst_exp v x (open_exp_wrt_exp_rec k u e).
Proof.
  intros k u v x e Hlc Hfresh. revert k u Hfresh.
  induction e as [n|x0| |i|A e0 IHe|A e0 IHe|e1 IH1 e2 IH2|e1 IH1 e2 IH2|e0 IHe A|lb e0 IHe|e0 IHe lb|e0 IHe|e0 IHe A];
    intros k u0 Hf; simpl.
  - destruct (lt_eq_lt_dec n k) as [ [ Hlt | Heq ] | Hgt ]; simpl.
    + reflexivity.
    + rewrite (subst_exp_notin v x u0 Hf). reflexivity.
    + reflexivity.
  - destruct (eq_var x0 x) as [Heq|Hneq].
    + rewrite (lc_open_exp_self v Hlc k u0). reflexivity.
    + reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite (IHe (S k) u0 Hf). reflexivity.
  - rewrite (IHe (S k) u0 Hf). reflexivity.
  - rewrite (IH1 k u0 Hf), (IH2 k u0 Hf). reflexivity.
  - rewrite (IH1 k u0 Hf), (IH2 k u0 Hf). reflexivity.
  - rewrite (IHe k u0 Hf). reflexivity.
  - rewrite (IHe k u0 Hf). reflexivity.
  - rewrite (IHe k u0 Hf). reflexivity.
  - rewrite (IHe k u0 Hf). reflexivity.
  - rewrite (IHe k u0 Hf). reflexivity.
Qed.

Lemma open_typ_subst_exp_comm : forall k A v x e,
  lc_exp v ->
  open_exp_wrt_typ_rec k A (subst_exp v x e) = subst_exp v x (open_exp_wrt_typ_rec k A e).
Proof.
  intros k A v x e Hlc. revert k A.
  induction e as [n|x0| |i|A0 e0 IHe|A0 e0 IHe|e1 IH1 e2 IH2|e1 IH1 e2 IH2|e0 IHe A0|lb e0 IHe|e0 IHe lb|e0 IHe|e0 IHe A0];
    intros k A1; simpl.
  - reflexivity.
  - destruct (eq_var x0 x) as [Heq|Hneq].
    + rewrite (lc_open_typ_self v Hlc k A1). reflexivity.
    + reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite IHe. reflexivity.
  - rewrite IHe. reflexivity.
  - rewrite IH1, IH2. reflexivity.
  - rewrite IH1, IH2. reflexivity.
  - rewrite IHe. reflexivity.
  - rewrite IHe. reflexivity.
  - rewrite IHe. reflexivity.
  - rewrite IHe. reflexivity.
  - rewrite IHe. reflexivity.
Qed.

Lemma notin_union_l : forall (x:atom) (s s':atoms), x \notin (s \u s') -> x \notin s.
Proof. intros x s s' H Hin. apply H. rewrite union_iff. left; exact Hin. Qed.
Lemma notin_union_r : forall (x:atom) (s s':atoms), x \notin (s \u s') -> x \notin s'.
Proof. intros x s s' H Hin. apply H. rewrite union_iff. right; exact Hin. Qed.
Lemma notin_singleton_imp : forall (x y:atom), y \notin AtomSetImpl.singleton x -> y <> x.
Proof. intros x y H Heq. apply H. rewrite singleton_iff. symmetry; exact Heq. Qed.

Lemma notin_termfv_var : forall (x y:termvar), y <> x -> x \notin termfv_exp (e_var_f y).
Proof. intros x y H Hin. simpl in Hin. rewrite singleton_iff in Hin. apply H. exact Hin. Qed.

Lemma In_dom : forall (A:Type) (x:atom) (a:A) (E:list (atom*A)),
  In (x,a) E -> AtomSetImpl.In x (dom E).
Proof.
  intros A x a E H. induction E as [|[y b] E IH].
  - inversion H.
  - simpl. inversion H as [HE|HE].
    + inversion HE; subst. apply add_iff. left. reflexivity.
    + apply add_iff. right. apply IH. assumption.
Qed.

Lemma subst_var_same : forall v x, subst_exp v x (e_var_f x) = v.
Proof. intros. simpl. destruct (eq_var x x) as [H|H]. reflexivity. exfalso. apply H. reflexivity. Qed.

Lemma subst_var_neq : forall v x z, z <> x -> subst_exp v x (e_var_f z) = e_var_f z.
Proof. intros v x z Hne. simpl. destruct (eq_var z x) as [Heq|Hneq].
  - exfalso. apply Hne. exact Heq.
  - reflexivity. Qed.

Lemma if_eq_var_same : forall v x, (if eq_var x x then v else e_var_f x) = v.
Proof. intros. destruct (eq_var x x) as [H|H]; [reflexivity|exfalso; apply H; reflexivity]. Qed.

Lemma if_eq_var_neq : forall v x z, z <> x -> (if eq_var z x then v else e_var_f z) = e_var_f z.
Proof. intros v x z Hne. destruct (eq_var z x) as [H|H]; [exfalso; apply Hne; exact H|reflexivity]. Qed.

Section Subst.
Variable chk_and_l : forall D G e A B, Typing D G e Chk (t_and A B) -> Typing D G e Chk A.
Variable chk_and_r : forall D G e A B, Typing D G e Chk (t_and A B) -> Typing D G e Chk B.
Variable spl_open : forall A B C X, spl A B C ->
  spl (open_typ_wrt_typ A (t_tvar_f X)) (open_typ_wrt_typ B (t_tvar_f X)) (open_typ_wrt_typ C (t_tvar_f X)).
Variable spl_all_open : forall L A B C,
  (forall X, X \notin L -> spl (open_typ_wrt_typ A (t_tvar_f X)) (open_typ_wrt_typ B (t_tvar_f X)) (open_typ_wrt_typ C (t_tvar_f X))) ->
  forall X, spl (open_typ_wrt_typ A (t_tvar_f X)) (open_typ_wrt_typ B (t_tvar_f X)) (open_typ_wrt_typ C (t_tvar_f X)).
Variable algo_sub_trans : forall D A B C,
  TCWell D -> TWell D A -> TWell D B -> TWell D C ->
  algo_sub D A B -> algo_sub D B C -> algo_sub D A C.
Variable subsub_algo_sub : forall D A B, TCWell D -> TWell D B -> subsub A B -> algo_sub D A B.
Variable disjoint_DT_r : forall D A B B', disjoint D A B -> DuplicatedType B' B -> disjoint D A B'.
Variable disjoint_subsub2 : forall D A1 A1' A2 A2', subsub A1' A1 -> subsub A2' A2 -> disjoint D A1 A2 -> disjoint D A1' A2'.
Variable typing_nil_notin : forall x e d A, Typing nil nil e d A -> ~ AtomSetImpl.In x (termfv_exp e).


Lemma binds_app_l : forall (A:Type) (x:atom) (a:A) (G1 G2:list (atom*A)),
  binds x a G1 -> binds x a (G1 ++ G2).
Proof. intros. apply in_app_iff. left. assumption. Qed.

Lemma binds_app_r : forall (A:Type) (x:atom) (a:A) (G1 G2:list (atom*A)),
  binds x a G2 -> binds x a (G1 ++ G2).
Proof. intros. apply in_app_iff. right. assumption. Qed.

Lemma binds_app_inv : forall (A:Type) (x:atom) (a:A) (G1 G2:list (atom*A)),
  binds x a (G1 ++ G2) -> binds x a G1 \/ binds x a G2.
Proof. intros. apply in_app_iff in H. exact H. Qed.

Lemma CWell_app : forall D (G1 G2:ctx), CWell D G1 -> CWell D G2 -> CWell D (G1 ++ G2).
Proof.
  intros D G1. induction G1 as [|[x A] G1 IH]; intros G2 H1 H2; simpl.
  - exact H2.
  - inversion H1; subst. apply CW_cons; [apply (IH G2); assumption|assumption].
Qed.

Lemma CWell_take : forall D (G1 G2:ctx), CWell D (G1 ++ G2) -> CWell D G1.
Proof.
  intros D G1. induction G1 as [|[x A] G1 IH]; intros G2 H; simpl in *.
  - apply CW_empty.
  - inversion H; subst. apply CW_cons; [apply (IH G2); assumption|assumption].
Qed.

Lemma CWell_drop : forall D (G1 G2:ctx), CWell D (G1 ++ G2) -> CWell D G2.
Proof.
  intros D G1. induction G1 as [|[x A] G1 IH]; intros G2 H; simpl in *.
  - exact H.
  - inversion H; subst. apply (IH G2). assumption.
Qed.

Definition SubRes (D:tctx) (G:ctx) (x:termvar) (A0:typ) (v:exp) (P:typ) (body:exp) (d:dirflag) (B:typ) : Prop :=
  match d with
  | Inf => exists B', Typing D G (subst_exp v x body) Inf B' /\ subsub B' B
  | Chk => Typing D G (subst_exp v x body) Chk B
  end.

Lemma notin_union_intro : forall (x:atom) (s t:atoms),
  x \notin s -> x \notin t -> x \notin (s \u t).
Proof. intros x s t Hs Ht Hin. rewrite union_iff in Hin. destruct Hin as [ H|H ]; [ apply Hs|apply Ht ]; exact H. Qed.

Lemma notin_singleton_intro : forall (x y:atom), x <> y -> x \notin AtomSetImpl.singleton y.
Proof. intros x y H Hin. rewrite singleton_iff in Hin. apply H. symmetry. exact Hin. Qed.

Lemma notin_dom_cons : forall (x y:atom) (A:Type) (a:A) (G:list (atom*A)),
  x \notin dom G -> x <> y -> x \notin dom ((y,a)::G).
Proof. intros x y A a G HG Hxy. simpl. apply (notin_add y x (dom G)); [symmetry; exact Hxy|exact HG]. Qed.

Lemma notin_dom_app : forall (x:atom) (A:Type) (G1 G2:list (atom*A)),
  x \notin dom G1 -> x \notin dom G2 -> x \notin dom (G1 ++ G2).
Proof.
  intros x A G1. induction G1 as [|[y b] G1 IH]; intros G2 H1 H2.
  - simpl. exact H2.
  - simpl in *.
    assert (Hyx : y <> x) by (intro E; apply H1; rewrite add_iff; left; exact E).
    assert (Hx1 : x \notin dom G1) by (intro Hin; apply H1; rewrite add_iff; right; exact Hin).
    apply (notin_add y x (dom (G1 ++ G2))); [exact Hyx | apply (IH G2 Hx1 H2)].
Qed.

Lemma notin_four : forall (x:atom) (a b c d:atoms),
  x \notin (a \u b \u c \u d) -> x \notin a /\ x \notin b /\ x \notin c /\ x \notin d.
Proof.
  intros x a b c d H.
  assert (Ha : x \notin a) by exact (notin_union_l x a (b \u c \u d) H).
  assert (Hb1 : x \notin (b \u c \u d)) by exact (notin_union_r x a (b \u c \u d) H).
  assert (Hb : x \notin b) by exact (notin_union_l x b (c \u d) Hb1).
  assert (Hc1 : x \notin (c \u d)) by exact (notin_union_r x b (c \u d) Hb1).
  assert (Hc : x \notin c) by exact (notin_union_l x c d Hc1).
  assert (Hd : x \notin d) by exact (notin_union_r x c d Hc1).
  repeat split; assumption.
Qed.

Lemma CWell_mid : forall D Gout xsub Asub Gsub,
  CWell D (Gout ++ (xsub,Asub)::Gsub) -> CWell D (Gout ++ Gsub).
Proof.
  intros D Gout xsub Asub Gsub H.
  apply CWell_app.
  - apply (CWell_take D Gout ((xsub,Asub)::Gsub) H).
  - apply (proj1 (CWell_cons_inv D Gsub xsub Asub (CWell_drop D Gout ((xsub,Asub)::Gsub) H))).
Qed.

Lemma uniq_mid : forall (A:Type) (Gout:list (atom*A)) (xsub:atom) (Asub:A) Gsub,
  uniq (Gout ++ (xsub,Asub)::Gsub) -> uniq (Gout ++ Gsub).
Proof.
  intros. apply (uniq_remove_mid A Gout ((xsub,Asub)::nil) Gsub). exact H.
Qed.

Lemma typsubst_open_typ_fresh : forall k (Y:typevar) (A0:typ) (X:typevar) B,
  lc_typ A0 ->
  Y \notin typefv_typ A0 ->
  Y <> X ->
  typsubst_typ A0 X (open_typ_wrt_typ_rec k (t_tvar_f Y) B)
  = open_typ_wrt_typ_rec k (t_tvar_f Y) (typsubst_typ A0 X B).
Proof.
  intros k Y A0 X B HA HY HYX. revert k Y A0 X HA HY HYX.
  induction B as [m|X0| | | |D IHD E IHE|D IHD E IHE|D IHD E IHE|l D IHD];
    intros k Y A0 X HA HY HYX; simpl.
  - destruct (lt_eq_lt_dec m k) as [ [ Hlt | Heq ] | Hgt ]; simpl.
    + reflexivity.
    + subst m. destruct (eq_var Y X) as [ HE | HNE ].
      * exfalso. apply HYX. exact HE.
      * reflexivity.
    + reflexivity.
  - destruct (eq_var X0 X) as [ HE | HNE ].
    + symmetry. apply (lc_typ_open_self A0 HA k (t_tvar_f Y)).
    + reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - rewrite (IHD k Y A0 X HA HY HYX). rewrite (IHE (S k) Y A0 X HA HY HYX). reflexivity.
  - rewrite (IHD k Y A0 X HA HY HYX). rewrite (IHE k Y A0 X HA HY HYX). reflexivity.
  - rewrite (IHD k Y A0 X HA HY HYX). rewrite (IHE k Y A0 X HA HY HYX). reflexivity.
  - rewrite (IHD k Y A0 X HA HY HYX). reflexivity.
Qed.

Lemma spl_typsubst : forall (Asubst:typ) X B C D,
  lc_typ Asubst -> spl B C D ->
  spl (typsubst_typ Asubst X B) (typsubst_typ Asubst X C) (typsubst_typ Asubst X D).
Proof.
  intros Asubst X B C D HA Hspl. revert Asubst X HA.
  induction Hspl as [A0 B0 C1 C2 HlcA Hspl IH
                  | L A0 B0 C1 C2 HlcA Hbody IH
                  | l B0 C1 C2 Hspl IH
                  | A0 B0 HlcA HlcB];
    intros Asubst X HA; simpl.
  - apply Sp_arrow.
    + apply (lc_typ_typsubst Asubst X A0 HA HlcA).
    + apply (IH Asubst X HA).
  - apply (Sp_all (L \u typefv_typ Asubst \u AtomSetImpl.singleton X)
             (typsubst_typ Asubst X A0) (typsubst_typ Asubst X B0)
             (typsubst_typ Asubst X C1) (typsubst_typ Asubst X C2)).
    + apply (lc_typ_typsubst Asubst X A0 HA HlcA).
    + intros Y HY.
      assert (HY1 : Y \notin (typefv_typ Asubst \u AtomSetImpl.singleton X))
        by exact (notin_union_r Y L (typefv_typ Asubst \u AtomSetImpl.singleton X) HY).
      assert (HYL : Y \notin L) by exact (notin_union_l Y L (typefv_typ Asubst \u AtomSetImpl.singleton X) HY).
      assert (HYA : Y \notin typefv_typ Asubst) by exact (notin_union_l Y (typefv_typ Asubst) (AtomSetImpl.singleton X) HY1).
      assert (HYX : Y <> X) by exact (notin_singleton_imp X Y (notin_union_r Y (typefv_typ Asubst) (AtomSetImpl.singleton X) HY1)).
      unfold open_typ_wrt_typ.
      rewrite <- (typsubst_open_typ_fresh 0 Y Asubst X B0 HA HYA HYX).
      rewrite <- (typsubst_open_typ_fresh 0 Y Asubst X C1 HA HYA HYX).
      rewrite <- (typsubst_open_typ_fresh 0 Y Asubst X C2 HA HYA HYX).
      exact (IH Y HYL Asubst X HA).
  - apply Sp_rcd. apply (IH Asubst X HA).
  - apply Sp_and.
    + apply (lc_typ_typsubst Asubst X A0 HA HlcA).
    + apply (lc_typ_typsubst Asubst X B0 HA HlcB).
Qed.

Lemma subsub_typsubst : forall (Asubst:typ) X B C,
  lc_typ Asubst -> subsub B C ->
  subsub (typsubst_typ Asubst X B) (typsubst_typ Asubst X C).
Proof.
  intros Asubst X B C HA Hss. induction Hss as [B0 HlcB | A1 A2 Bt B1 B2 Hspl Hss1 IH1 Hss2 IH2].
  - simpl. apply IS_refl. apply (lc_typ_typsubst Asubst X B0 HA HlcB).
  - simpl. apply IS_and with (B := typsubst_typ Asubst X Bt)
        (B1 := typsubst_typ Asubst X B1) (B2 := typsubst_typ Asubst X B2).
    + apply (spl_typsubst Asubst X _ _ _ HA Hspl).
    + exact IH1.
    + exact IH2.
Qed.

Lemma typing_subst_gen : forall D Gbody body d B, Typing D Gbody body d B ->
  forall xsub Asub Gout Gsub,
    Gbody = Gout ++ (xsub,Asub) :: Gsub ->
    xsub # Gout ->
  forall v P, lc_exp v -> TWell D P -> Typing D (Gout ++ Gsub) v Inf P -> subsub P Asub ->
  SubRes D (Gout ++ Gsub) xsub Asub v P body d B.
Proof.
  intros D Gbody body d B Hty.
  induction Hty; intros xsub Asub Gout Gsub Heq Hfresh v P Hlcv HTW Hv Hss.
  - (* Typ_top *) match goal with Heq : ?GG = Gout ++ (xsub,Asub) :: Gsub |- _ => subst GG end. simpl.
    match goal with
    | HTC : TCWell D |- _ =>
      match goal with
      | HCW : CWell D _ |- _ =>
        match goal with
        | Hu : uniq _ |- _ =>
          let HCWout := constr:(CWell_take D Gout ((xsub,Asub)::Gsub) HCW) in
          let HCWtail := constr:(CWell_drop D Gout ((xsub,Asub)::Gsub) HCW) in
          let HCWg := constr:(proj1 (CWell_cons_inv D Gsub xsub Asub HCWtail)) in
          let HCWres := constr:(CWell_app D Gout Gsub HCWout HCWg) in
          let Hures := constr:(uniq_remove_mid typ Gout ((xsub,Asub)::nil) Gsub Hu) in
          exists t_top; split;
          [ apply Typ_top; [exact HTC | exact HCWres | exact Hures]
          | apply IS_refl; apply lc_t_top ]
        end
      end
    end.
  - (* Typ_lit *) match goal with Heq : ?GG = Gout ++ (xsub,Asub) :: Gsub |- _ => subst GG end. simpl.
    match goal with
    | HTC : TCWell D |- _ =>
      match goal with
      | HCW : CWell D _ |- _ =>
        match goal with
        | Hu : uniq _ |- _ =>
          let HCWout := constr:(CWell_take D Gout ((xsub,Asub)::Gsub) HCW) in
          let HCWtail := constr:(CWell_drop D Gout ((xsub,Asub)::Gsub) HCW) in
          let HCWg := constr:(proj1 (CWell_cons_inv D Gsub xsub Asub HCWtail)) in
          let HCWres := constr:(CWell_app D Gout Gsub HCWout HCWg) in
          let Hures := constr:(uniq_remove_mid typ Gout ((xsub,Asub)::nil) Gsub Hu) in
          exists t_int; split;
          [ apply Typ_lit; [exact HTC | exact HCWres | exact Hures]
          | apply IS_refl; apply lc_t_int ]
        end
      end
    end.
  - (* Typ_var *) match goal with Heq : ?GG = Gout ++ (xsub,Asub) :: Gsub |- _ => subst GG end.
    pose proof (CWell_take D Gout ((xsub,Asub)::Gsub) H0) as HCWout.
    pose proof (CWell_drop D Gout ((xsub,Asub)::Gsub) H0) as HCWtail.
    pose proof (proj1 (CWell_cons_inv D Gsub xsub Asub HCWtail)) as HCWg.
    pose proof (CWell_app D Gout Gsub HCWout HCWg) as HCWres.
    pose proof (uniq_remove_mid typ Gout ((xsub,Asub)::nil) Gsub H2) as Hures.
    destruct (binds_app_uniq_1 typ x A Gout ((xsub,Asub)::Gsub) H2 H1) as [ [Hbout HnotF] | [Hbtail HnotOut] ].
    + assert (Hxne : x <> xsub).
      { intro HEQ. apply HnotF. simpl. apply add_iff. left. symmetry. exact HEQ. }
      simpl. rewrite (if_eq_var_neq v xsub x Hxne). exists A. split.
      * exact (Typ_var D (Gout ++ Gsub) x A H HCWres (binds_app_l typ x A Gout Gsub Hbout) Hures).
      * apply IS_refl. exact (CWell_TWell_all D Gout x A HCWout Hbout).
    + destruct (binds_cons_1 typ x xsub A Asub Gsub Hbtail) as [ [Hx HAx] | Hbg ].
      * subst x; subst A. simpl. rewrite if_eq_var_same. exists P. split; [exact Hv | exact Hss].
      * assert (Hxne : x <> xsub).
        { intro HEQ. subst x. pose proof (uniq_app_2 typ Gout ((xsub,Asub)::Gsub) H2) as HuF.
          pose proof (uniq_cons_2 typ xsub Asub Gsub HuF) as HfreshF.
          apply HfreshF. apply (In_dom typ xsub A Gsub). exact Hbg. }
        simpl. rewrite (if_eq_var_neq v xsub x Hxne). exists A. split.
        -- exact (Typ_var D (Gout ++ Gsub) x A H HCWres (binds_app_r typ x A Gout Gsub Hbg) Hures).
        -- apply IS_refl. exact (CWell_TWell_all D Gsub x A HCWg Hbg).

  - (* Typ_abs *)
    simpl.
    set (L' := L \u dom Gout \u dom Gsub \u AtomSetImpl.singleton xsub).
    apply (Typ_abs L' D (Gout ++ Gsub) A (subst_exp v xsub e) B1 B2 H).
    intros y Hy.
    destruct (notin_four y L (dom Gout) (dom Gsub) (AtomSetImpl.singleton xsub) Hy) as [ HyL [ HyGout [ HyGsub HySing ] ] ].
    assert (Hyne : y <> xsub) by exact (notin_singleton_imp xsub y HySing).
    assert (Hyctx : y \notin dom (Gout ++ Gsub)) by (apply notin_dom_app; [exact HyGout|exact HyGsub]).
    assert (Hxcons : xsub \notin dom ((y, A) :: Gout)) by (apply notin_dom_cons; [exact Hfresh | symmetry; exact Hyne]).
    pose proof (H0 y HyL) as Hbody.
    destruct (typing_env_wf D ((y, A) :: G) (e ^ y) Chk B2 Hbody) as [ HTCb [ HCWb Huniqb ] ].
    destruct (CWell_cons_inv D G y A HCWb) as [ _ HTWA ].
    destruct (typing_env_wf D (Gout ++ Gsub) v Inf P Hv) as [ HTCv [ HCWv Huniqv ] ].
    pose proof (typing_weaken_G_cons D (Gout ++ Gsub) y A v Inf P Hv HTCv HCWv Huniqv Hyctx HTWA) as Hv'.
    assert (Heq' : (y, A) :: G = ((y, A) :: Gout) ++ (xsub, Asub) :: Gsub).
    { simpl. rewrite Heq. reflexivity. }
    pose proof (H1 y HyL xsub Asub ((y, A) :: Gout) Gsub Heq' Hxcons v P Hlcv HTW Hv' Hss) as Hsub.
    simpl in Hsub.
    unfold open_exp_wrt_exp.
    rewrite (open_exp_subst_exp_comm 0 (e_var_f y) v xsub e Hlcv (notin_termfv_var xsub y Hyne)).
    exact Hsub.
  - (* Typ_app *)
    simpl.
    pose proof (IHHty1 xsub Asub Gout Gsub Heq Hfresh v P Hlcv HTW Hv Hss) as Hres1.
    simpl in Hres1. destruct Hres1 as [ A' [ Ht1 HssA ] ].
    destruct (appDist_subsub_arrow A' A HssA B C H) as [ B' [ C' [ Happ [ Hdt HssC ] ] ] ].
    pose proof (IHHty2 xsub Asub Gout Gsub Heq Hfresh v P Hlcv HTW Hv Hss) as Ht2.
    simpl in Ht2.
    pose proof (chk_dup chk_and_l chk_and_r B' B Hdt D (Gout ++ Gsub) (subst_exp v xsub e2) Ht2) as Ht2'.
    exists C'. split.
    + apply (Typ_app D (Gout ++ Gsub) (subst_exp v xsub e1) (subst_exp v xsub e2) C' A' B' Ht1 Happ Ht2').
    + exact HssC.
  - (* Typ_tabs *)
    simpl.
    rewrite Heq in H.
    pose proof (CWell_mid D Gout xsub Asub Gsub H) as HCWres.
    apply (Typ_tabs L D (Gout ++ Gsub) (subst_exp v xsub e) A B HCWres).
    intros X HX.
    pose proof (H0 X HX) as Hbody.
    destruct (typing_env_wf ((X, A) :: D) G (open_exp_wrt_typ e (t_tvar_f X)) Chk (B -^ X) Hbody) as [ HTC' [ HCW' Huniq' ] ].
    pose proof (typing_weaken_D_cons D X A (Gout ++ Gsub) v Inf P Hv HTC') as Hv'.
    assert (HTW' : TWell ((X, A) :: D) P).
    { apply (TWell_weaken D ((X, A) :: D) P HTW). intros Y Bt Hb. apply (binds_cons typ Y X Bt A D Hb). }
    pose proof (H1 X HX xsub Asub Gout Gsub Heq Hfresh v P Hlcv HTW' Hv' Hss) as Hsub.
    simpl in Hsub.
    unfold open_exp_wrt_typ.
    rewrite (open_typ_subst_exp_comm 0 (t_tvar_f X) v xsub e Hlcv).
    exact Hsub.
  - (* Typ_tapp *)
    simpl.
    pose proof (IHHty xsub Asub Gout Gsub Heq Hfresh v P Hlcv HTW Hv Hss) as Hres.
    simpl in Hres. destruct Hres as [ B' [ Ht HssB ] ].
    destruct (appDist_subsub_all spl_all_open B' B HssB C1 C2 H) as [ C1' [ C2' [ Happ [ Hdt HssC ] ] ] ].
    pose proof (disjoint_DT_r D A C1 C1' H0 Hdt) as Hdis.
    exists (open_typ_wrt_typ C2' A). split.
    + apply (Typ_tapp D (Gout ++ Gsub) (subst_exp v xsub e) A C2' B' C1' Ht Happ Hdis).
    + destruct (disjoint_lc D A C1 H0) as [ HlcA _ ].
      destruct (atom_fresh ([[C2']] \u [[C2]])) as [ Y HY ].
      assert (HY1 : Y \notin [[C2']]) by exact (notin_union_l Y [[C2']] [[C2]] HY).
      assert (HY2 : Y \notin [[C2]]) by exact (notin_union_r Y [[C2']] [[C2]] HY).
      pose proof (HssC Y) as HssY.
      pose proof (subsub_typsubst A Y (open_typ_wrt_typ C2' (t_tvar_f Y)) (open_typ_wrt_typ C2 (t_tvar_f Y)) HlcA HssY) as HssTs.
      unfold open_typ_wrt_typ in HssTs.
      rewrite (typsubst_open_typ 0 Y A C2' HlcA HY1) in HssTs.
      rewrite (typsubst_open_typ 0 Y A C2 HlcA HY2) in HssTs.
      unfold open_typ_wrt_typ.
      exact HssTs.
  - (* Typ_proj *)
    simpl.
    pose proof (IHHty xsub Asub Gout Gsub Heq Hfresh v P Hlcv HTW Hv Hss) as Hres.
    simpl in Hres. destruct Hres as [ A' [ Ht HssA ] ].
    destruct (appDist_subsub_rcd A' A HssA l C H) as [ C' [ Happ HssC ] ].
    exists C'. split.
    + apply (Typ_proj D (Gout ++ Gsub) (subst_exp v xsub e) l C' A' Ht Happ).
    + exact HssC.
  - (* Typ_rcd *)
    simpl.
    pose proof (IHHty xsub Asub Gout Gsub Heq Hfresh v P Hlcv HTW Hv Hss) as Ht.
    simpl in Ht.
    apply (Typ_rcd D (Gout ++ Gsub) l (subst_exp v xsub e) A Ht).
  - (* Typ_merge *)
    simpl.
    pose proof (IHHty1 xsub Asub Gout Gsub Heq Hfresh v P Hlcv HTW Hv Hss) as Hres1.
    simpl in Hres1. destruct Hres1 as [ A' [ Ht1 Hss1 ] ].
    pose proof (IHHty2 xsub Asub Gout Gsub Heq Hfresh v P Hlcv HTW Hv Hss) as Hres2.
    simpl in Hres2. destruct Hres2 as [ B' [ Ht2 Hss2 ] ].
    pose proof (disjoint_subsub2 D A A' B B' Hss1 Hss2 H) as Hdis.
    exists (A' & B'). split.
    + apply (Typ_merge D (Gout ++ Gsub) (subst_exp v xsub e1) (subst_exp v xsub e2) A' B' Ht1 Ht2 Hdis).
    + apply IS_and with (B := A & B) (B1 := A) (B2 := B).
      * apply Sp_and.
        -- apply (typing_lc_typ D G e1 Inf A Hty1).
        -- apply (typing_lc_typ D G e2 Inf B Hty2).
      * exact Hss1.
      * exact Hss2.
  - (* Typ_inter *)
    simpl.
    pose proof (IHHty1 xsub Asub Gout Gsub Heq Hfresh v P Hlcv HTW Hv Hss) as Ht1.
    simpl in Ht1.
    pose proof (IHHty2 xsub Asub Gout Gsub Heq Hfresh v P Hlcv HTW Hv Hss) as Ht2.
    simpl in Ht2.
    apply (Typ_inter D (Gout ++ Gsub) (subst_exp v xsub e) A B Ht1 Ht2).
  - (* Typ_anno *)
    simpl.
    pose proof (IHHty xsub Asub Gout Gsub Heq Hfresh v P Hlcv HTW Hv Hss) as Ht.
    simpl in Ht.
    exists A. split.
    + apply (Typ_anno D (Gout ++ Gsub) (subst_exp v xsub e) A Ht).
    + apply IS_refl. apply (typing_lc_typ D G e Chk A Hty).
  - (* Typ_fix *)
    simpl.
    set (L' := L \u dom Gout \u dom Gsub \u AtomSetImpl.singleton xsub).
    destruct (atom_fresh L') as [ y0 Hy0 ].
    destruct (notin_four y0 L (dom Gout) (dom Gsub) (AtomSetImpl.singleton xsub) Hy0) as [ Hy0L _ ].
    pose proof (H y0 Hy0L) as Hbody0.
    assert (HlcA : lc_typ A) by exact (typing_lc_typ D ((y0, A) :: G) (e ^ y0) Chk A Hbody0).
    exists A. split.
    + apply (Typ_fix L' D (Gout ++ Gsub) A (subst_exp v xsub e)).
      intros y Hy.
      destruct (notin_four y L (dom Gout) (dom Gsub) (AtomSetImpl.singleton xsub) Hy) as [ HyL [ HyGout [ HyGsub HySing ] ] ].
      assert (Hyne : y <> xsub) by exact (notin_singleton_imp xsub y HySing).
      assert (Hyctx : y \notin dom (Gout ++ Gsub)) by (apply notin_dom_app; [exact HyGout|exact HyGsub]).
      assert (Hxcons : xsub \notin dom ((y, A) :: Gout)) by (apply notin_dom_cons; [exact Hfresh | symmetry; exact Hyne]).
      pose proof (H y HyL) as Hbody.
      destruct (typing_env_wf D ((y, A) :: G) (e ^ y) Chk A Hbody) as [ HTCb [ HCWb Huniqb ] ].
      destruct (CWell_cons_inv D G y A HCWb) as [ _ HTWA ].
      destruct (typing_env_wf D (Gout ++ Gsub) v Inf P Hv) as [ HTCv [ HCWv Huniqv ] ].
      pose proof (typing_weaken_G_cons D (Gout ++ Gsub) y A v Inf P Hv HTCv HCWv Huniqv Hyctx HTWA) as Hv'.
      assert (Heq' : (y, A) :: G = ((y, A) :: Gout) ++ (xsub, Asub) :: Gsub).
      { simpl. rewrite Heq. reflexivity. }
      pose proof (H0 y HyL xsub Asub ((y, A) :: Gout) Gsub Heq' Hxcons v P Hlcv HTW Hv' Hss) as Hsub.
      simpl in Hsub.
      unfold open_exp_wrt_exp.
      rewrite (open_exp_subst_exp_comm 0 (e_var_f y) v xsub e Hlcv (notin_termfv_var xsub y Hyne)).
      exact Hsub.
    + apply IS_refl. exact HlcA.
  - (* Typ_mergev *)
    simpl.
    rewrite (subst_exp_notin v xsub u1 (typing_nil_notin xsub u1 Inf A Hty1)).
    rewrite (subst_exp_notin v xsub u2 (typing_nil_notin xsub u2 Inf B Hty2)).
    exists (A & B). split.
    + rewrite Heq in H0. rewrite Heq in H1.
      pose proof (CWell_mid D Gout xsub Asub Gsub H0) as HCWres.
      pose proof (uniq_mid typ Gout xsub Asub Gsub H1) as Hures.
      apply (Typ_mergev D (Gout ++ Gsub) u1 u2 A B H HCWres Hures Hty1 Hty2 H2).
    + apply IS_refl. apply lc_t_and.
      * apply (typing_lc_typ nil nil u1 Inf A Hty1).
      * apply (typing_lc_typ nil nil u2 Inf B Hty2).
  - (* Typ_sub *)
    simpl.
    pose proof (IHHty xsub Asub Gout Gsub Heq Hfresh v P Hlcv HTW Hv Hss) as Hres.
    simpl in Hres. destruct Hres as [ A' [ Ht HssA ] ].
    destruct (typing_env_wf D G e Inf A Hty) as [ HTC _ ].
    pose proof (algo_sub_TWell_source D A B HTC H) as HTWA.
    pose proof (subsub_algo_sub D A' A HTC HTWA HssA) as Hasub.
    pose proof (algo_sub_TWell_source D A' A HTC Hasub) as HTWA'.
    pose proof (algo_sub_TWell_target D A B HTC H) as HTWB.
    pose proof (algo_sub_trans D A' A B HTC HTWA' HTWA HTWB Hasub H) as HAB.
    apply (Typ_sub D (Gout ++ Gsub) (subst_exp v xsub e) B A' Ht HAB).
Qed.

