   The compiled /workspace/.pscratch/agentI.vo currently predates the
   current agentE.vo (agentI.vo is from 20:06, agentE.vo from 20:08), so
   [Require Import agentI] fails with "inconsistent assumptions over
   library agentE".  Loading the source re-elaborates the very same
   complete development against the current consistent environment,
   without modifying any file.  *)

(* Note on [Require Import agentI2]:
   agentI2.vo provides the previously pending [typing_nil_notin], so it is
   no longer a Section Variable.  agentH2/algo_sub_trans_TWell and
   agentH/subsub_algo_sub provide the remaining subtyping metatheory, so
   this file has no Section Variables at all. *)

Definition disjoint_subsub2_concrete : forall D A1 A1' A2 A2', subsub A1' A1 -> subsub A2' A2 -> disjoint D A1 A2 -> disjoint D A1' A2' :=
  fun D A1 A1' A2 A2' H1 H2 Hd => disjoint_subsub_r D A1' A2 A2' (disjoint_subsub_l D A1 A1' A2 Hd H1) H2.

Definition subst_gen_inst :
  forall (D : tctx) (Gbody : ctx) (body : exp) (d : dirflag) (B : typ),
    Typing D Gbody body d B ->
    forall (xsub : atom) (Asub : typ) (Gout Gsub : ctx),
      Gbody = Gout ++ (xsub, Asub) :: Gsub ->
      xsub # Gout ->
      forall (v : exp) (P : typ),
        lc_exp v ->
        TWell D P ->
        Typing D (Gout ++ Gsub) v Inf P ->
        subsub P Asub ->
        SubRes D (Gout ++ Gsub) xsub Asub v P body d B :=
  fun D Gbody body d B Hty xsub Asub Gout Gsub Heq Hfresh v P Hlc HTW Hv Hss =>
    typing_subst_gen chk_and_l chk_and_r spl_all_open
      agentH2.algo_sub_trans_TWell agentH.subsub_algo_sub
      disjoint_DT_r disjoint_subsub2_concrete typing_nil_notin
      D Gbody body d B Hty xsub Asub Gout Gsub Heq Hfresh v P Hlc HTW Hv Hss.

Check subst_gen_inst.
Print subst_gen_inst.
End subst_inst.
Import subst_inst.

Module agentE3.
Import ListNotations.

(* ==================================================================== *)
(* Restricted checked subsumption.                                      *)
(*                                                                      *)
(* The general statement                                                *)
(*   Typing D G e Chk A -> algo_sub D A B -> Typing D G e Chk B         *)
(* is false: the annotation wrapper can step to a top-like/top-level    *)
(* checked type which the bare underlying expression need not have.     *)
(* For the uses in Cast_anno, B is required to be ordinal and not       *)
(* top-like.  Under those restrictions the subsumption is provable.      *)
(*                                                                      *)
(* Algorithmic-subtyping transitivity is not assumed: it is obtained    *)
(* from agentH3.algo_sub_trans_aux.  The S_all type-context conversion   *)
(* is imported from agentH4.typing_ctx_sub, so this section is           *)
(* unconditional.                                                        *)
(* ==================================================================== *)

Section ChkSubsumption.

(* Transitivity of algorithmic subtyping, discharged from agentH3. *)
Lemma algo_sub_trans : forall (D:tctx) (A B C:typ),
  TCWell D -> TWell D A -> TWell D B -> TWell D C ->
  algo_sub D A B -> algo_sub D B C -> algo_sub D A C.
Proof.
  intros D A B C HTC HTA HTB HTCc HAB HBC.
  exact (algo_sub_trans_aux
           (size_typ A + size_typ B + size_typ C)
           D A B C (le_n _) HTC HTA HTB HTCc HAB HBC).
Qed.

(* Inversion of notTopLike. *)
Lemma notTopLike_inv : forall D A,
  notTopLike D A -> TCWell D /\ TWell D A /\ ~ topLike D A.
Proof.
  intros D A H. inversion H; subst. repeat split; assumption.
Qed.

(* The codomain of a non-top-like arrow is non-top-like. *)
Lemma notTopLike_arrow_cod : forall D A B,
  notTopLike D (t_arrow A B) -> TWell D A -> notTopLike D B.
Proof.
  intros D A B Hntl HTWA.
  destruct (notTopLike_inv D (t_arrow A B) Hntl) as [HTC Hrest].
  destruct Hrest as [HTW Hn].
  destruct (TWell_arrow_inv D A B HTW) as [_ HTWB].
  apply NTL.
  - assumption.
  - assumption.
  - intro HtopB. apply Hn. apply (TL_arrow D A B); assumption.
Qed.

(* The body of a non-top-like record is non-top-like. *)
Lemma notTopLike_rcd_body : forall D l B,
  notTopLike D (t_rcd l B) -> notTopLike D B.
Proof.
  intros D l B Hntl.
  destruct (notTopLike_inv D (t_rcd l B) Hntl) as [HTC Hrest].
  destruct Hrest as [HTW Hn].
  apply NTL.
  - assumption.
  - apply (TWell_rcd_inv D l B); assumption.
  - intro HtopB. apply Hn. apply (TL_rcd D l B); assumption.
Qed.

(* A freshly opened body of a non-top-like universal is non-top-like. *)
Lemma notTopLike_all_body_at : forall D A B X,
  TCWell D -> TWell D (t_forall A B) -> ~ topLike D (t_forall A B) ->
  TWell (cons (X,A) D) (open_typ_wrt_typ B (t_tvar_f X)) ->
  X \notin dom D -> X \notin typefv_typ_range D ->
  X \notin [[A]] -> X \notin [[B]] ->
  notTopLike (cons (X,A) D) (open_typ_wrt_typ B (t_tvar_f X)).
Proof.
  intros D A B X HTC HTWALL Hn HTWBODY HXdom HXrng HXA HXB.
  assert (HTWA : TWell D A) by (apply (TWell_all_inv D A B); assumption).
  assert (HTCcons : TCWell (cons (X,A) D)).
  { apply (TCW_cons D X A HTC HTWA).
    apply uniq_cons; [ apply (TCWell_uniq D HTC) | exact HXdom ]. }
  apply NTL.
  - assumption.
  - assumption.
  - intro Htop.
    apply Hn.
    apply (topLike_forall_intro D A B X HTC HTWA HXdom HXrng HXA HXB Htop).
Qed.

(* ==================================================================== *)
(* Checked subsumption into an ordinal, non-top-like type.               *)
(*                                                                      *)
(* The proof is by nested well-founded induction: outer on an expression *)
(* size bound (decreased by the bodies of abstractions, type             *)
(* abstractions and records), inner on the size of the source type       *)
(* (decreased by the Typ_inter rule).                                   *)
(* ==================================================================== *)

Lemma chk_sub_ord_ntl_aux : forall n e,
  size_exp e <= n ->
  forall m D G A B,
    size_typ A <= m ->
    TCWell D ->
    Typing D G e Chk A ->
    algo_sub D A B -> ord B -> notTopLike D B ->
    Typing D G e Chk B.
Proof.
  induction n as [n IHn] using lt_wf_ind.
  intros e He.
  induction m as [m IHm] using lt_wf_ind.
  intros D G A B HA HTC Hty Hsub Hord Hntl.
  inversion Hty; subst; clear Hty.

  - (* Typ_abs *)
    inversion Hsub as
      [ pD pX pHTC pHTW
      | pD pHTC
      | pD pA pBt pHTW pHo pHtop
      | pD pA pHTC pHTW pHo
      | pD pA pBt pC pHTW pHo pHsu
      | pD pA pBt pC pHTW pHo pHsu
      | pD pA1 pB1 pA2 pB2 pHo pHsub1 pHsub2
      | pL pD pA1 pA2 pB1 pB2 pHords pHsub1 pHbody
      | pD pl pA pBt pHo pHsu
      | pD pA pBt pB1 pB2 pHspl pHsu1 pHsu2 ]; subst.
    + (* S_top *) exfalso.
      match goal with
      | Ht : topLike D ?T |- _ =>
          exact (proj2 (proj2 (notTopLike_inv D T Hntl)) Ht)
      end.
    + (* S_arrow *)
      assert (HTWA2 : TWell D pA2)
        by (apply (algo_sub_TWell_source D pA2 B1); [exact HTC | exact pHsub1]).
      assert (HTWB1 : TWell D B1)
        by (apply (algo_sub_TWell_target D pA2 B1); [exact HTC | exact pHsub1]).
      assert (HTWA0 : TWell D A0)
        by (apply (algo_sub_TWell_target D B1 A0); [exact HTC | exact H]).
      assert (Htrans : algo_sub D pA2 A0)
        by (apply (algo_sub_trans D pA2 B1 A0);
            [ exact HTC | exact HTWA2 | exact HTWB1 | exact HTWA0
            | exact pHsub1 | exact H ]).
      assert (HntlB2 : notTopLike D pB2)
        by (apply (notTopLike_arrow_cod D pA2 pB2); assumption).
      apply (Typ_abs L D G A0 e0 pA2 pB2 Htrans).
      intros x Hx.
      assert (Hlt : size_exp (open_exp_wrt_exp e0 (e_var_f x)) < n).
      { rewrite size_exp_open_term_f. cbn in He. lia. }
      exact (IHn (size_exp (open_exp_wrt_exp e0 (e_var_f x))) Hlt
               (open_exp_wrt_exp e0 (e_var_f x)) (le_n _)
               (size_typ B2) D ((x, A0) :: G) B2 pB2 (le_n _)
               HTC (H0 x Hx) pHsub2 pHo HntlB2).
    + (* S_and has a non-ordinal target *)
      exfalso.
      match goal with
      | Hs : spl ?T ?C1 ?C2 |- _ => exact (spl_not_ord T C1 C2 Hs Hord)
      end.

  - (* Typ_tabs *)
    inversion Hsub as
      [ pD pX pHTC pHTW
      | pD pHTC
      | pD pA pBt pHTW pHo pHtop
      | pD pA pHTC pHTW pHo
      | pD pA pBt pC pHTW pHo pHsu
      | pD pA pBt pC pHTW pHo pHsu
      | pD pA1 pB1 pA2 pB2 pHo pHsub1 pHsub2
      | pL pD pA1 pA2 pB1 pB2 pHords pHsub1 pHbody
      | pD pl pA pBt pHo pHsu
      | pD pA pBt pB1 pB2 pHspl pHsu1 pHsu2 ]; subst.
    + (* S_top *) exfalso.
      match goal with
      | Ht : topLike D ?T |- _ =>
          exact (proj2 (proj2 (notTopLike_inv D T Hntl)) Ht)
      end.
    + (* S_all *)
      assert (HTWtgt : TWell D (t_forall pB1 pB2))
        by (apply (algo_sub_TWell_target D (t_forall A0 B0) (t_forall pB1 pB2));
            [exact HTC | exact Hsub]).
      destruct (notTopLike_inv D (t_forall pB1 pB2) Hntl) as [HTCt Hrest].
      destruct Hrest as [HTWt HnTop].
      assert (HTWpB1 : TWell D pB1)
        by (apply (algo_sub_TWell_source D pB1 A0); [exact HTC | exact pHsub1]).
      pose (Lnew := ((((L \u pL) \u dom D) \u typefv_typ_range D)
                       \u [[pB1]]) \u [[pB2]]).
      apply (Typ_tabs Lnew D G e0 pB1 pB2 H).
      intros X HX.
      unfold Lnew in HX.
      destruct (notin_union X ((((L \u pL) \u dom D) \u typefv_typ_range D)
                  \u [[pB1]]) [[pB2]] HX) as [HX1 HXB2].
      destruct (notin_union X (((L \u pL) \u dom D) \u typefv_typ_range D)
                  [[pB1]] HX1) as [HX2 HXB1].
      destruct (notin_union X ((L \u pL) \u dom D) (typefv_typ_range D) HX2)
        as [HX3 HXrng].
      destruct (notin_union X (L \u pL) (dom D) HX3) as [HX4 HXdom].
      destruct (notin_union X L pL HX4) as [HXL HXpL].
      assert (HTCX : TCWell ((X,pB1)::D)).
      { apply (TCW_cons D X pB1 HTC HTWpB1).
        apply uniq_cons; [ apply (TCWell_uniq D HTC) | exact HXdom ]. }
      assert (HtyX : Typing ((X,pB1)::D) G
                       (open_exp_wrt_typ e0 (t_tvar_f X))
                       Chk (open_typ_wrt_typ B0 (t_tvar_f X))).
      { apply (agentH4.typing_ctx_sub D X A0 pB1 G
                 (open_exp_wrt_typ e0 (t_tvar_f X)) Chk
                 (open_typ_wrt_typ B0 (t_tvar_f X))).
        - exact HTC.
        - exact HXdom.
        - exact pHsub1.
        - exact (H0 X HXL). }
      assert (HTWbody : TWell ((X,pB1)::D)
                          (open_typ_wrt_typ pB2 (t_tvar_f X)))
        by (apply (algo_sub_TWell_target ((X,pB1)::D)
                     (open_typ_wrt_typ B0 (t_tvar_f X))
                     (open_typ_wrt_typ pB2 (t_tvar_f X)));
            [exact HTCX | exact (pHbody X HXpL)]).
      assert (HbodyN : notTopLike ((X,pB1)::D)
                          (open_typ_wrt_typ pB2 (t_tvar_f X)))
        by (apply (notTopLike_all_body_at D pB1 pB2 X HTC HTWtgt HnTop HTWbody
                     HXdom HXrng HXB1 HXB2)).
      assert (Hlt : size_exp (open_exp_wrt_typ e0 (t_tvar_f X)) < n).
      { rewrite size_exp_open_typ_f. cbn in He. lia. }
      exact (IHn (size_exp (open_exp_wrt_typ e0 (t_tvar_f X))) Hlt
               (open_exp_wrt_typ e0 (t_tvar_f X)) (le_n _)
               (size_typ (open_typ_wrt_typ B0 (t_tvar_f X)))
               ((X,pB1)::D) G
               (open_typ_wrt_typ B0 (t_tvar_f X))
               (open_typ_wrt_typ pB2 (t_tvar_f X)) (le_n _)
               HTCX HtyX (pHbody X HXpL) (pHords X HXpL) HbodyN).
    + (* S_and has a non-ordinal target *)
      exfalso.
      match goal with
      | Hs : spl ?T ?C1 ?C2 |- _ => exact (spl_not_ord T C1 C2 Hs Hord)
      end.

  - (* Typ_rcd *)
    inversion Hsub as
      [ pD pX pHTC pHTW
      | pD pHTC
      | pD pA pBt pHTW pHo pHtop
      | pD pA pHTC pHTW pHo
      | pD pA pBt pC pHTW pHo pHsu
      | pD pA pBt pC pHTW pHo pHsu
      | pD pA1 pB1 pA2 pB2 pHo pHsub1 pHsub2
      | pL pD pA1 pA2 pB1 pB2 pHords pHsub1 pHbody
      | pD pl pA pBt pHo pHsu
      | pD pA pBt pB1 pB2 pHspl pHsu1 pHsu2 ]; subst.
    + (* S_top *) exfalso.
      match goal with
      | Ht : topLike D ?T |- _ =>
          exact (proj2 (proj2 (notTopLike_inv D T Hntl)) Ht)
      end.
    + (* S_rcd *)
      assert (HntlB : notTopLike D pBt)
        by (apply (notTopLike_rcd_body D l pBt); exact Hntl).
      assert (Hlt : size_exp e0 < n) by (cbn in He; lia).
      exact (Typ_rcd D G l e0 pBt
               (IHn (size_exp e0) Hlt e0 (le_n _) (size_typ A0)
                    D G A0 pBt (le_n _) HTC H pHsu pHo HntlB)).
    + (* S_and has a non-ordinal target *)
      exfalso.
      match goal with
      | Hs : spl ?T ?C1 ?C2 |- _ => exact (spl_not_ord T C1 C2 Hs Hord)
      end.

  - (* Typ_inter *)
    inversion Hsub as
      [ pD pX pHTC pHTW
      | pD pHTC
      | pD pA pBt pHTW pHo pHtop
      | pD pA pHTC pHTW pHo
      | pD pA pBt pC pHTW pHo pHsu
      | pD pA pBt pC pHTW pHo pHsu
      | pD pA1 pB1 pA2 pB2 pHo pHsub1 pHsub2
      | pL pD pA1 pA2 pB1 pB2 pHords pHsub1 pHbody
      | pD pl pA pBt pHo pHsu
      | pD pA pBt pB1 pB2 pHspl pHsu1 pHsu2 ]; subst.
    + (* S_top *) exfalso.
      match goal with
      | Ht : topLike D ?T |- _ =>
          exact (proj2 (proj2 (notTopLike_inv D T Hntl)) Ht)
      end.
    + (* S_andl *)
      assert (Hlt : size_typ A0 < m) by (cbn in HA; lia).
      exact (IHm (size_typ A0) Hlt D G A0 B (le_n _) HTC H pHsu Hord Hntl).
    + (* S_andr *)
      assert (Hlt : size_typ B0 < m) by (cbn in HA; lia).
      exact (IHm (size_typ B0) Hlt D G B0 B (le_n _) HTC H0 pHsu Hord Hntl).
    + (* S_and has a non-ordinal target *)
      exfalso.
      match goal with
      | Hs : spl ?T ?C1 ?C2 |- _ => exact (spl_not_ord T C1 C2 Hs Hord)
      end.

  - (* Typ_sub *)
    assert (HTWA0 : TWell D A0)
      by (apply (algo_sub_TWell_source D A0 A);
          [exact HTC | exact H0]).
    assert (HTWA : TWell D A)
      by (apply (algo_sub_TWell_target D A0 A);
          [exact HTC | exact H0]).
    assert (HTWB : TWell D B)
      by (apply (algo_sub_TWell_target D A B);
          [exact HTC | exact Hsub]).
    assert (Htrans : algo_sub D A0 B)
      by (apply (algo_sub_trans D A0 A B);
          [ exact HTC | exact HTWA0 | exact HTWA | exact HTWB
          | exact H0 | exact Hsub ]).
    exact (Typ_sub D G e B A0 H Htrans).
Qed.

Lemma chk_sub_ord_ntl : forall D G e A B,
  TCWell D ->
  Typing D G e Chk A ->
  algo_sub D A B -> ord B -> notTopLike D B ->
  Typing D G e Chk B.
Proof.
  intros D G e A B HTC Hty Hsub Hord Hntl.
  exact (chk_sub_ord_ntl_aux (size_exp e) e (le_n _)
           (size_typ A) D G A B (le_n _) HTC Hty Hsub Hord Hntl).
Qed.

(* Target 1, restricted form.  This lemma is proved inside the section
   because its S_all case uses the type-context conversion variable.  It
   is exported with that variable as an additional parameter. *)
Lemma chk_anno_inv_ord_ntl : forall (e:exp) (A B:typ),
  Typing nil nil (e_anno e A) Chk B ->
  ord B -> notTopLike nil B ->
  Typing nil nil e Chk B.
Proof.
  intros e A B Hty Hord Hntl.
  assert (HTC : TCWell nil)
    by (apply (proj1 (notTopLike_inv nil B Hntl))).
  inversion Hty; subst.
  - exfalso. exact (ord_and_false A0 B0 Hord).
  - inversion H; subst.
    apply (chk_sub_ord_ntl nil nil e A0 B HTC H4 H0 Hord Hntl).
Qed.

End ChkSubsumption.

(* ==================================================================== *)
(* Target 1: annotation inversion.                                      *)
(*                                                                      *)
(* The unrestricted statement is false.  The restricted form needed by  *)
(* Cast_anno follows from [chk_sub_ord_ntl] after inverting the implicit *)
(* subsumption that wraps the annotation typing.                        *)
(* ==================================================================== *)

Lemma typing_eabs_inf_false : forall A,
  ~ Typing nil nil (e_abs t_top e_top) Inf A.
Proof.
  intros A H. inversion H.
Qed.

Lemma typing_eabs_chk_top_false :
  ~ Typing nil nil (e_abs t_top e_top) Chk t_top.
Proof.
  intros H. inversion H; subst.
  match goal with
  | Hinf : Typing nil nil (e_abs t_top e_top) Inf ?A |- _ =>
      exact (typing_eabs_inf_false A Hinf)
  end.
Qed.

Lemma chk_anno_inv_false :
  ~ (forall (e:exp) (A B:typ),
        Typing nil nil (e_anno e A) Chk B -> Typing nil nil e Chk B).
Proof.
  intro H.
  assert (Hty : Typing nil nil
                  (e_anno (e_abs t_top e_top) (t_arrow t_top t_top))
                  Chk t_top).
  { apply (Typ_sub nil nil
             (e_anno (e_abs t_top e_top) (t_arrow t_top t_top))
             t_top (t_arrow t_top t_top)).
    - apply Typ_anno.
      apply (typing_eabs_top_arrow t_top t_top).
      + apply O_arrow; [ apply lc_t_top | apply O_top ].
      + apply (TL_arrow nil t_top t_top);
          [ apply TW_top | apply TL_top; apply TCW_empty ].
    - apply (S_top nil (t_arrow t_top t_top) t_top).
      + apply (TW_arrow nil t_top t_top); apply TW_top.
      + apply O_top.
      + apply TL_top. apply TCW_empty.
  }
  exact (typing_eabs_chk_top_false (H _ _ _ Hty)).
Qed.

(* ==================================================================== *)
(* Target 2: checked merge components.                                  *)
(*                                                                      *)
(* The component statements are false even when the merge is a value:   *)
(* a subsumed check of a merge can select one ordinal conjunct while    *)
(* the other component is an annotated abstraction.  The true residue  *)
(* is at the Inf conjunction produced by Typ_merge / Typ_mergev.        *)
(* ==================================================================== *)

Lemma topLike_int_nil_false : ~ topLike nil t_int.
Proof. intro H. inversion H. Qed.

Lemma ord_attr : ord (t_arrow t_top t_top).
Proof. apply O_arrow; [apply lc_t_top | apply O_top]. Qed.

Lemma tw_attr : TWell nil (t_arrow t_top t_top).
Proof. apply TW_arrow; apply TW_top. Qed.

Lemma tl_attr : topLike nil (t_arrow t_top t_top).
Proof. apply (TL_arrow nil t_top t_top); [apply TW_top | apply TL_top; apply TCW_empty]. Qed.

Lemma algo_sub_arrow_int_false : forall A B, ~ algo_sub nil (t_arrow A B) t_int.
Proof.
  intros A B H. inversion H; subst.
  - match goal with Htop : topLike nil t_int |- _ => exact (topLike_int_nil_false Htop) end.
  - match goal with Hs : spl t_int _ _ |- _ => inversion Hs end.
Qed.

Lemma typing_anno_arrow_chk_int_false : forall e A B,
  ~ Typing nil nil (e_anno e (t_arrow A B)) Chk t_int.
Proof.
  intros e A B H. inversion H; subst.
  inversion H0; subst.
  exact (algo_sub_arrow_int_false A B H1).
Qed.

Lemma merge_chk_component_l_false :
  ~ (forall (v1 v2:exp) (A:typ),
        Typing nil nil (e_merge v1 v2) Chk A ->
        value (e_merge v1 v2) ->
        Typing nil nil v1 Chk A).
Proof.
  intro H.
  assert (Hty : Typing nil nil
      (e_merge (e_anno (e_abs t_top e_top) (t_arrow t_top t_top)) (e_lit 0))
      Chk t_int).
  { apply (Typ_sub nil nil
             (e_merge (e_anno (e_abs t_top e_top) (t_arrow t_top t_top)) (e_lit 0))
             t_int (t_and (t_arrow t_top t_top) t_int)).
    - apply (Typ_merge nil nil
               (e_anno (e_abs t_top e_top) (t_arrow t_top t_top)) (e_lit 0)
               (t_arrow t_top t_top) t_int).
      + apply Typ_anno. apply (typing_eabs_top_arrow t_top t_top ord_attr tl_attr).
      + apply (Typ_lit nil nil 0); [ apply TCW_empty | apply CW_empty | apply uniq_nil_ctx ].
      + apply (D_ax nil (t_arrow t_top t_top) t_int TCW_empty tw_attr (TW_int nil)).
        apply (Dax_arrowInt t_top t_top); apply lc_t_top.
    - apply (S_andr nil (t_arrow t_top t_top) t_int t_int).
      + exact tw_attr.
      + apply O_int.
      + apply (S_int nil TCW_empty).
  }
  assert (Hval : value (e_merge (e_anno (e_abs t_top e_top) (t_arrow t_top t_top)) (e_lit 0))).
  { apply V_merge.
    - apply (V_abs t_top e_top (t_arrow t_top t_top)).
      + apply lc_t_top.
      + apply lc_exp_abs_top.
      + apply ord_lc_typ. exact ord_attr.
    - apply V_lit. }
  assert (Hcomp := H _ _ _ Hty Hval).
  exact (typing_anno_arrow_chk_int_false (e_abs t_top e_top) t_top t_top Hcomp).
Qed.

Lemma merge_chk_component_r_false :
  ~ (forall (v1 v2:exp) (A:typ),
        Typing nil nil (e_merge v1 v2) Chk A ->
        value (e_merge v1 v2) ->
        Typing nil nil v2 Chk A).
Proof.
  intro H.
  assert (Hty : Typing nil nil
      (e_merge (e_lit 0) (e_anno (e_abs t_top e_top) (t_arrow t_top t_top)))
      Chk t_int).
  { apply (Typ_sub nil nil
             (e_merge (e_lit 0) (e_anno (e_abs t_top e_top) (t_arrow t_top t_top)))
             t_int (t_and t_int (t_arrow t_top t_top))).
    - apply (Typ_merge nil nil
               (e_lit 0) (e_anno (e_abs t_top e_top) (t_arrow t_top t_top))
               t_int (t_arrow t_top t_top)).
      + apply (Typ_lit nil nil 0); [ apply TCW_empty | apply CW_empty | apply uniq_nil_ctx ].
      + apply Typ_anno. apply (typing_eabs_top_arrow t_top t_top ord_attr tl_attr).
      + apply (D_ax nil t_int (t_arrow t_top t_top) TCW_empty (TW_int nil) tw_attr).
        apply (Dax_intArrow t_top t_top); apply lc_t_top.
    - apply (S_andl nil t_int (t_arrow t_top t_top) t_int).
      + exact tw_attr.
      + apply O_int.
      + apply (S_int nil TCW_empty).
  }
  assert (Hval : value (e_merge (e_lit 0) (e_anno (e_abs t_top e_top) (t_arrow t_top t_top)))).
  { apply V_merge.
    - apply V_lit.
    - apply (V_abs t_top e_top (t_arrow t_top t_top)).
      + apply lc_t_top.
      + apply lc_exp_abs_top.
      + apply ord_lc_typ. exact ord_attr. }
  assert (Hcomp := H _ _ _ Hty Hval).
  exact (typing_anno_arrow_chk_int_false (e_abs t_top e_top) t_top t_top Hcomp).
Qed.

Lemma merge_inf_components : forall (v1 v2:exp) (C:typ),
  Typing nil nil (e_merge v1 v2) Inf C ->
  exists A B, C = t_and A B /\
              Typing nil nil v1 Inf A /\ Typing nil nil v2 Inf B.
Proof.
  intros v1 v2 C H. inversion H; subst.
  - exists A, B. repeat split; assumption.
  - exists A, B. repeat split; assumption.
Qed.

Lemma merge_inf_components_chk : forall (v1 v2:exp) (A B:typ),
  Typing nil nil (e_merge v1 v2) Inf (t_and A B) ->
  TWell nil A -> TWell nil B ->
  Typing nil nil v1 Chk A /\ Typing nil nil v2 Chk B.
Proof.
  intros v1 v2 A B H HTA HTB.
  destruct (merge_inf_components v1 v2 (t_and A B) H)
    as (A0 & B0 & Heq & H1 & H2).
  inversion Heq; subst.
  split.
  - apply (Typ_sub nil nil v1 A0 A0); [ exact H1 | apply algo_sub_refl_nil; assumption ].
  - apply (Typ_sub nil nil v2 B0 B0); [ exact H2 | apply algo_sub_refl_nil; assumption ].
Qed.

(* ==================================================================== *)
(* Inf-source casting typing.                                           *)
(*                                                                      *)
(* The Chk-source component statements are false, but the component Inf  *)
(* typing is enough for the Cast_mergel/Cast_merger recursion.  The      *)
(* Cast_and case needs self-consistency of the source; for prevalues     *)
(* this follows from their Inf typing (see below).                       *)
(* The annotation case uses the restricted inversion/subsumption from   *)
(* Target 1, now unconditional via agentH4.typing_ctx_sub.               *)
(* ==================================================================== *)

(* A prevalue with an Inf typing has a pType.  This is the small bridge
   needed to compare the two children of an Inf-typed merge. *)
Lemma prevalue_inf_pType : forall (v:exp), prevalue v ->
  forall A, Typing nil nil v Inf A -> pType v A.
Proof.
  intros v Hpv.
  induction Hpv as
    [ i
    |
    | e A Hlce HlcA
    | u1 u2 Hp1 IH1 Hp2 IH2 ];
    intros T Hty.
  - (* literal *) inversion Hty; subst. apply PT_int.
  - (* top *) inversion Hty; subst. apply PT_top.
  - (* annotation *) inversion Hty; subst. eapply PT_anno; eassumption.
  - (* merge *)
    destruct (merge_inf_components u1 u2 T Hty)
      as (A1 & A2 & Heq & H1 & H2).
    subst T. apply (PT_merge u1 u2 A1 A2).
    + apply (IH1 A1 H1).
    + apply (IH2 A2 H2).
Qed.

(* Pointwise self-consistency of a prevalue that is Inf-typable.
   The untyped statement [prevalue v -> consistent v v] is FALSE: take
   [merge (lit 0) (lit 1)], which has no common component.  Inf typing
   rules out exactly this situation. *)
Lemma prevalue_inf_consistent_self : forall (v:exp), prevalue v ->
  forall A, Typing nil nil v Inf A -> consistent v v.
Proof.
  intros v Hpv.
  induction Hpv as
    [ i
    |
    | e A Hlce HlcA
    | u1 u2 Hp1 IH1 Hp2 IH2 ];
    intros T Hty.
  - (* literal *) apply C_lit.
  - (* top *) apply (C_disjoint e_top e_top t_top t_top PT_top PT_top).
    + apply (D_topl nil t_top t_top).
      * apply agentK.tw_top_nil.
      * apply TL_top. apply TCW_empty.
    + apply PV_top.
    + apply PV_top.
  - (* annotation *) apply (C_anno e A A HlcA Hlce HlcA).
  - (* merge *)
    destruct (merge_inf_components u1 u2 T Hty)
      as (A1 & A2 & Heq & HA1 & HA2).
    subst T.
    assert (HS1 : consistent u1 u1) by exact (IH1 A1 HA1).
    assert (HS2 : consistent u2 u2) by exact (IH2 A2 HA2).
    assert (H12 : consistent u1 u2).
    { inversion Hty; subst.
      - (* Typ_merge: disjoint Inf types *)
        apply (C_disjoint u1 u2 A1 A2).
        + apply (prevalue_inf_pType u1 Hp1 A1 HA1).
        + apply (prevalue_inf_pType u2 Hp2 A2 HA2).
        + match goal with Hd : disjoint nil A1 A2 |- _ => exact Hd end.
        + exact Hp1.
        + exact Hp2.
      - (* Typ_mergev: consistency is a premise *)
        match goal with Hc : consistent u1 u2 |- _ => exact Hc end. }
    apply (C_mergel u1 u2 (e_merge u1 u2)).
    + apply (C_merger u1 u1 u2); [ exact HS1 | exact H12 ].
    + apply (C_merger u2 u1 u2).
      * apply consistent_sym. exact H12.
      * exact HS2.
Qed.

Section CastingInfSource.

Lemma casting_typing_inf_src : forall (v:exp) (A:typ) (v':exp),
  casting v A v' ->
  forall A0, Typing nil nil v Inf A0 ->
  TWell nil A ->
  exists P, Typing nil nil v' Inf P /\ subsub P A /\ TWell nil P.
Proof.
  intros v A v' Hcast.
  induction Hcast as
    [ i
    | v0 Hlce
    | v0 A1 A2 Hlce Hord Htop
    | v0 A1 A2 Hlce Hord Htop
    | v0 l A0 Hlce Hord Htop
    | e A0 B Hlce Hord HNTL Hsub
    | v1 v2 A0 v1' Hlce Hord Hc1 IH1
    | v1 v2 A0 v2' Hlce Hord Hc2 IH2
    | v0 A0 v1 v2 B C Hspl Hc1 IH1 Hc2 IH2 ];
    intros A0src Hty TWA.
  - (* Cast_int *)
    exists t_int. split.
    + apply (Typ_lit nil nil i); [ apply TCW_empty | apply CW_empty | apply uniq_nil_ctx ].
    + split.
      * apply (IS_refl t_int). apply lc_t_int.
      * apply TW_int.
  - (* Cast_top *)
    exists t_top. split.
    + apply (Typ_top nil nil); [ apply TCW_empty | apply CW_empty | apply uniq_nil_ctx ].
    + split.
      * apply (IS_refl t_top). apply lc_t_top.
      * apply TW_top.
  - (* Cast_topArrow *)
    exists (t_arrow A1 A2). split.
    + apply Typ_anno. apply (typing_eabs_top_arrow A1 A2 Hord Htop).
    + split.
      * apply (IS_refl (t_arrow A1 A2)). apply (ord_lc_typ (t_arrow A1 A2) Hord).
      * assumption.
  - (* Cast_topAll *)
    exists (t_forall A1 A2). split.
    + apply Typ_anno. apply (typing_etabs_top_all A1 A2 Hord Htop).
    + split.
      * apply (IS_refl (t_forall A1 A2)). apply (ord_lc_typ (t_forall A1 A2) Hord).
      * assumption.
  - (* Cast_topRcd *)
    exists (t_rcd l A0). split.
    + apply Typ_anno. apply (typing_ercd_top l A0 Hord Htop).
    + split.
      * apply (IS_refl (t_rcd l A0)). apply (ord_lc_typ (t_rcd l A0) Hord).
      * assumption.
  - (* Cast_anno *)
    assert (Htye : Typing nil nil e Chk A0).
    { inversion Hty; subst. assumption. }
    assert (HtyB : Typing nil nil e Chk B).
    { apply (chk_sub_ord_ntl nil nil e A0 B).
      - apply TCW_empty.
      - exact Htye.
      - exact Hsub.
      - exact Hord.
      - exact HNTL. }
    exists B. split.
    + apply Typ_anno. exact HtyB.
    + split.
      * apply (IS_refl B). apply (ord_lc_typ B Hord).
      * assumption.
  - (* Cast_mergel *)
    destruct (merge_inf_components v1 v2 A0src Hty) as (B1 & B2 & Heq & Ht1 & Ht2).
    inversion Heq; subst.
    exact (IH1 B1 Ht1 TWA).
  - (* Cast_merger *)
    destruct (merge_inf_components v1 v2 A0src Hty) as (B1 & B2 & Heq & Ht1 & Ht2).
    inversion Heq; subst.
    exact (IH2 B2 Ht2 TWA).
  - (* Cast_and *)
    destruct (spl_TWell_nil A0 B C TWA Hspl) as [TWB TWC].
    destruct (IH1 A0src Hty TWB) as (P1 & Hty1 & Hsub1 & HTW1).
    destruct (IH2 A0src Hty TWC) as (P2 & Hty2 & Hsub2 & HTW2).
    exists (t_and P1 P2). split.
    + apply (Typ_mergev nil nil v1 v2 P1 P2).
      * apply TCW_empty.
      * apply CW_empty.
      * apply uniq_nil_ctx.
      * exact Hty1.
      * exact Hty2.
      * exact (@agentK2.casting_consistent_inf_source v0 A0src Hty
                 B C v1 v2 Hc1 Hc2).
    + split.
      * apply (IS_and P1 P2 A0 B C Hspl Hsub1 Hsub2).
      * apply (TW_and nil P1 P2 HTW1 HTW2).
Qed.


Lemma casting_component_l_typing_ord : forall (v1 v2:exp) (A:typ) (v1':exp),
  Typing nil nil (e_merge v1 v2) Chk A ->
  ord A -> TWell nil A ->
  casting v1 A v1' ->
  exists P, Typing nil nil v1' Inf P /\ subsub P A /\ TWell nil P.
Proof.
  intros v1 v2 A v1' Hty Hord HTW Hc.
  inversion Hty; subst.
  - (* Typ_inter: A is a conjunction, contradicting ord A *)
    exfalso. exact (ord_and_false A0 B Hord).
  - (* Typ_sub from an Inf merge typing *)
    destruct (merge_inf_components v1 v2 A0 H)
      as (P1 & P2 & Heq & Hinf1 & Hinf2).
    inversion Heq; subst.
    exact (casting_typing_inf_src v1 A v1' Hc P1 Hinf1 HTW).
Qed.

Lemma casting_component_r_typing_ord : forall (v1 v2:exp) (A:typ) (v2':exp),
  Typing nil nil (e_merge v1 v2) Chk A ->
  ord A -> TWell nil A ->
  casting v2 A v2' ->
  exists P, Typing nil nil v2' Inf P /\ subsub P A /\ TWell nil P.
Proof.
  intros v1 v2 A v2' Hty Hord HTW Hc.
  inversion Hty; subst.
  - exfalso. exact (ord_and_false A0 B Hord).
  - destruct (merge_inf_components v1 v2 A0 H)
      as (P1 & P2 & Heq & Hinf1 & Hinf2).
    inversion Heq; subst.
    exact (casting_typing_inf_src v2 A v2' Hc P2 Hinf2 HTW).
Qed.

(* ==================================================================== *)
(* Prevalues that are checked always have an Inf typing.                *)
(*                                                                      *)
(* This is the source-Inf bridge needed for Step_annov: the prevalue    *)
(* forms that can occur are lit, top, anno and merge.  Chk inversion    *)
(* either gives a subderivation that is already Inf (Typ_sub), recurses *)
(* into a component (Typ_inter), or contradicts prevalue (the bare     *)
(* abs/tabs/rcd constructors).                                          *)
(* ==================================================================== *)
Lemma chk_prevalue_inf_aux : forall (D:tctx) (G:ctx) (v:exp) (d:dirflag) (A:typ),
  Typing D G v d A -> d = Chk -> prevalue v ->
  exists A0, Typing D G v Inf A0.
Proof.
  intros D G v d A H.
  induction H; intros Hd Hpv; subst; try discriminate Hd.
  - (* Typ_abs *)
    exfalso. inversion Hpv.
  - (* Typ_tabs *)
    exfalso. inversion Hpv.
  - (* Typ_rcd *)
    exfalso. inversion Hpv.
  - (* Typ_inter *)
    exact (IHTyping1 eq_refl Hpv).
  - (* Typ_sub *)
    exists A. assumption.
Qed.

Lemma prevalue_chk_inf : forall (v:exp), prevalue v ->
  forall A, Typing nil nil v Chk A ->
  exists A0, Typing nil nil v Inf A0.
Proof.
  intros v Hpv A Hty.
  exact (chk_prevalue_inf_aux nil nil v Chk A Hty eq_refl Hpv).
Qed.


(* Step_annov bridge: value + prevalue check typing supplies an Inf source,
   after which the Inf-source casting theorem applies. *)
Lemma casting_typing_inf_value_chk : forall (v:exp),
  value v -> prevalue v ->
  forall (A:typ) (v':exp),
    Typing nil nil v Chk A -> TWell nil A -> casting v A v' ->
    exists P, Typing nil nil v' Inf P /\ subsub P A /\ TWell nil P.
Proof.
  intros v Hval Hpv A v' Hty HTW Hc.
  destruct (prevalue_chk_inf v Hpv A Hty) as [A0 Hinf].
  exact (casting_typing_inf_src v A v' Hc A0 Hinf HTW).
Qed.

End CastingInfSource.

(* ==================================================================== *)
(* Target 3: the special cases also available from agentK2.            *)
(* The general cast-coherence statement is now unconditional in         *)
(* agentK2.casting_consistent_inf_source (and its split corollary       *)
(* agentK2.casting_consistent_split_inf); this lemma keeps the explicit  *)
(* disjoint/top-like case distinction useful to callers.                 *)
(* ==================================================================== *)

Lemma casting_consistent_split_disjoint_or_topLike :
  forall (v:exp) (A B C:typ) (v1 v2:exp),
    Typing nil nil v Chk A ->
    TWell nil A ->
    spl A B C ->
    casting v B v1 ->
    casting v C v2 ->
    (disjoint nil B C \/ topLike nil B \/ topLike nil C) ->
    consistent v1 v2.
Proof.
  intros v A B C v1 v2 Hty HTW Hspl Hc1 Hc2 Hcase.
  exact (agentK2.casting_consistent_split_of_disjoint_or_topLike
           v A B C v1 v2 HTW Hspl Hc1 Hc2 Hcase).
Qed.
End agentE3.
Import agentE3.

Module papp_agent.
Import ListNotations.

(* ================================================================== *)
(* Preliminary: no Inf typing for bare abstractions / type abstractions *)
(* / records.                                                          *)
(* ================================================================== *)

Lemma papp_abs_inf_impossible : forall (D:tctx) (G:ctx) (A:typ) (e:exp) (B:typ),
  Typing D G (e_abs A e) Inf B -> False.
Proof. intros D G A e B H. inversion H. Qed.

Lemma papp_tabs_inf_impossible : forall (D:tctx) (G:ctx) (e:exp) (B:typ),
  Typing D G (e_tabs e) Inf B -> False.
Proof. intros D G e B H. inversion H. Qed.

Lemma papp_rcd_inf_impossible : forall (D:tctx) (G:ctx) (l:label) (e:exp) (B:typ),
  Typing D G (e_rcd l e) Inf B -> False.
Proof. intros D G l e B H. inversion H. Qed.

(* ================================================================== *)
(* Wrapping the argument at the abstraction annotation.                *)
(* The requested componentwise [abs_chk_appDist_arg] is false; the     *)
(* combined statement below is proved from domain subtyping and the    *)
(* wrapping structure.                                                 *)
(* ================================================================== *)

Lemma algo_sub_and_intro_lc : forall D A B C,
  TCWell D -> lc_typ C ->
  algo_sub D A C -> algo_sub D B C ->
  algo_sub D (t_and A B) C.
Proof.
  intros D A B C HTC Hlc H1.
  revert Hlc B.
  induction H1; intros Hlc BB H2sub.
  - (* S_var *) eapply S_andl.
    + eapply algo_sub_TWell_source; eassumption.
    + apply O_var.
    + eapply S_var; eassumption.
  - (* S_int *) eapply S_andl.
    + eapply algo_sub_TWell_source; eassumption.
    + apply O_int.
    + eapply S_int; eassumption.
  - (* S_top *) eapply S_andl.
    + eapply algo_sub_TWell_source; eassumption.
    + eassumption.
    + eapply S_top; eassumption.
  - (* S_bot *) eapply S_andl.
    + eapply algo_sub_TWell_source; eassumption.
    + eassumption.
    + eapply S_bot; eassumption.
  - (* S_andl *) eapply S_andl.
    + eapply algo_sub_TWell_source; eassumption.
    + eassumption.
    + eapply S_andl; eassumption.
  - (* S_andr *) eapply S_andl.
    + eapply algo_sub_TWell_source; eassumption.
    + eassumption.
    + eapply S_andr; eassumption.
  - (* S_arrow *) eapply S_andl.
    + eapply algo_sub_TWell_source; eassumption.
    + eapply O_arrow.
      * match goal with H : lc_typ (t_arrow ?X ?Y) |- _ => exact (proj1 (lc_typ_arrow_inv X Y H)) end.
      * eassumption.
    + eapply S_arrow; eassumption.
  - (* S_all *) eapply S_andl.
    + eapply algo_sub_TWell_source; eassumption.
    + eapply O_all.
      * match goal with H : lc_typ (t_forall ?X ?Y) |- _ => exact (proj1 (lc_typ_forall_inv X Y H)) end.
      * eassumption.
    + eapply S_all; eassumption.
  - (* S_rcd *) eapply S_andl.
    + eapply algo_sub_TWell_source; eassumption.
    + eapply O_rcd; eassumption.
    + eapply S_rcd; eassumption.
  - (* S_and *) eapply S_and.
    + exact H.
    + eapply IHalgo_sub1.
      * exact HTC.
      * apply (proj1 (proj2 (spl_lc B B1 B2 H))).
      * eapply algo_sub_spl_l; eassumption.
    + eapply IHalgo_sub2.
      * exact HTC.
      * apply (proj2 (proj2 (spl_lc B B1 B2 H))).
      * eapply algo_sub_spl_r; eassumption.
Qed.

Lemma papp_abs_appDist_domain_sub : forall A0 body B,
  lc_typ A0 ->
  Typing nil nil (e_abs A0 body) Chk B ->
  forall C1 C2, appDist B (t_arrow C1 C2) -> algo_sub nil C1 A0.
Proof.
  intros A0 body B Hlc H.
  dependent induction H; intros C1 C2 Hdist.
  - inversion Hdist; subst; assumption.
  - inversion Hdist; subst.
    assert (H1' : algo_sub nil B1 A0)
      by exact (IHTyping1 body A0 Hlc (JMeq_refl _) (JMeq_refl _)
                  eq_refl eq_refl B1 C0 H4).
    assert (H2' : algo_sub nil B2 A0)
      by exact (IHTyping2 body A0 Hlc (JMeq_refl _) (JMeq_refl _)
                  eq_refl eq_refl B2 C3 H6).
    exact (algo_sub_and_intro_lc nil B1 B2 A0 TCW_empty Hlc H1' H2').
  - exfalso. exact (papp_abs_inf_impossible nil nil A0 body A H).
Qed.

Lemma papp_wrapping_typing_inf_sub : forall e A e',
  wrapping e A e' ->
  forall T, algo_sub nil T A -> Typing nil nil e Chk T ->
  exists P, Typing nil nil e' Inf P /\ subsub P A /\ TWell nil P.
Proof.
  intros e A e' H.
  induction H as
    [ e Hlce
    | e A1 A2 Hlce Hord Htop
    | e A1 A2 Hlce Hord Htop
    | e l A Hlce Hord Htop
    | e A Hlce Hord HNTL
    | e A e1 e2 B C Hspl Hw1 IH1 Hw2 IH2 ];
    intros T Hsub Hty.
  - exists t_top. split.
    + apply Typ_top.
      * apply TCW_empty.
      * apply CW_empty.
      * apply uniq_nil_ctx.
    + split.
      * apply IS_refl. apply lc_t_top.
      * apply TW_top.
  - exists (t_arrow A1 A2). split.
    + apply Typ_anno. apply (typing_eabs_top_arrow A1 A2 Hord Htop).
    + split.
      * apply IS_refl. apply (ord_lc_typ (t_arrow A1 A2) Hord).
      * apply (algo_sub_TWell_target nil T (t_arrow A1 A2) TCW_empty Hsub).
  - exists (t_forall A1 A2). split.
    + apply Typ_anno. apply (typing_etabs_top_all A1 A2 Hord Htop).
    + split.
      * apply IS_refl. apply (ord_lc_typ (t_forall A1 A2) Hord).
      * apply (algo_sub_TWell_target nil T (t_forall A1 A2) TCW_empty Hsub).
  - exists (t_rcd l A). split.
    + apply Typ_anno. apply (typing_ercd_top l A Hord Htop).
    + split.
      * apply IS_refl. apply (ord_lc_typ (t_rcd l A) Hord).
      * apply (algo_sub_TWell_target nil T (t_rcd l A) TCW_empty Hsub).
  - exists A. split.
    + apply Typ_anno.
      apply (chk_sub_ord_ntl nil nil e T A TCW_empty Hty Hsub Hord HNTL).
    + split.
      * apply IS_refl. apply (ord_lc_typ A Hord).
      * apply (algo_sub_TWell_target nil T A TCW_empty Hsub).
  - (* EW_and *)
    assert (HsubB : algo_sub nil T B) by (apply (algo_sub_spl_l nil T A B C Hsub Hspl)).
    assert (HsubC : algo_sub nil T C) by (apply (algo_sub_spl_r nil T A B C Hsub Hspl)).
    destruct (IH1 T HsubB Hty) as (P1 & Hty1 & Hsub1 & HTW1).
    destruct (IH2 T HsubC Hty) as (P2 & Hty2 & Hsub2 & HTW2).
    exists (t_and P1 P2). split.
    + apply (Typ_mergev nil nil e1 e2 P1 P2).
      * apply TCW_empty.
      * apply CW_empty.
      * apply uniq_nil_ctx.
      * assumption.
      * assumption.
      * apply (wrapping_consistent e B e1 Hw1
                 (algo_sub_TWell_target nil T B TCW_empty HsubB)
                 C e2 Hw2
                 (algo_sub_TWell_target nil T C TCW_empty HsubC)).
    + split.
      * apply (IS_and P1 P2 A B C Hspl Hsub1 Hsub2).
      * apply TW_and; assumption.
Qed.

Lemma wrapping_lc_source : forall e A e',
  wrapping e A e' -> lc_typ A.
Proof.
  intros e A e' H.
  induction H as
    [ e Hlce
    | e A1 A2 Hlce Hord Htop
    | e A1 A2 Hlce Hord Htop
    | e l A Hlce Hord Htop
    | e A Hlce Hord HNTL
    | e A e1 e2 B C Hspl Hw1 IH1 Hw2 IH2 ].
  - apply lc_t_top.
  - apply (ord_lc_typ (t_arrow A1 A2) Hord).
  - apply (ord_lc_typ (t_forall A1 A2) Hord).
  - apply (ord_lc_typ (t_rcd l A) Hord).
  - apply (ord_lc_typ A Hord).
  - apply (proj1 (spl_lc A B C Hspl)).
Qed.

Lemma papp_abs_arg_inf_lc : forall A0 body B e2 e2' C1 C2,
  Typing nil nil (e_abs A0 body) Chk B ->
  appDist B (t_arrow C1 C2) ->
  wrapping e2 A0 e2' ->
  Typing nil nil e2 Chk C1 ->
  exists P, Typing nil nil e2' Inf P /\ subsub P A0 /\ TWell nil P.
Proof.
  intros A0 body B e2 e2' C1 C2 HtyB Happ Hwrap Hty2.
  pose proof (wrapping_lc_source e2 A0 e2' Hwrap) as HlcA.
  pose proof (papp_abs_appDist_domain_sub A0 body B HlcA HtyB C1 C2 Happ) as Hdom.
  exact (papp_wrapping_typing_inf_sub e2 A0 e2' Hwrap C1 Hdom Hty2).
Qed.

Lemma papp_abs_arg_inf : forall A0 body B e2 e2' C1 C2,
  Typing nil nil (e_abs A0 body) Chk B ->
  appDist B (t_arrow C1 C2) ->
  wrapping e2 A0 e2' ->
  Typing nil nil e2 Chk C1 ->
  exists P, Typing nil nil e2' Inf P /\ subsub P A0 /\ TWell nil P.
Proof.
  intros. eapply papp_abs_arg_inf_lc; eassumption.
Qed.


(* ================================================================== *)
(* Disjointness inversion for intersections.                           *)
(* ================================================================== *)

Lemma papp_disjoint_and_r_gen : forall D A BC,
  disjoint D A BC -> forall B C, BC = t_and B C ->
  disjoint D A B /\ disjoint D A C.
Proof.
  intros D A BC H.
  induction H as
    [ D0 TA TB HTC HTA HTB Hax
    | D0 TA TB HTWB HtopA
    | D0 TA TB HTWA HtopB
    | D0 TA1 TA2 TB1 TB2 HTW1 HTW2 Hd IHd
    | D0 l TA TB Hd IHd
    | L D0 TA1 TB1 TA2 TB2 HTW1 HTW2 Hbody IHB
    | D0 X TB TA Hb Hsub
    | D0 TB X TA Hb Hsub
    | D0 TA TB TA1 TA2 Hspl Hd1 IH1 Hd2 IH2
    | D0 TA TB TB1 TB2 Hspl Hd1 IH1 Hd2 IH2 ];
    intros BB CC E; subst; try discriminate.
  - (* D_ax *) inversion Hax.
  - (* D_topl *)
    destruct (TWell_and_inv D0 BB CC HTWB) as [HB HC].
    split; [ apply (D_topl D0 TA BB HB HtopA)
           | apply (D_topl D0 TA CC HC HtopA) ].
  - (* D_topr *)
    destruct (topLike_and_inv D0 BB CC HtopB) as [HB HC].
    split; [ apply (D_topr D0 TA BB HTWA HB)
           | apply (D_topr D0 TA CC HTWA HC) ].
  - (* D_varl *)
    split.
    + apply (D_varl D0 X BB TA Hb).
      apply (algo_sub_and_l D0 TA BB CC); exact Hsub.
    + apply (D_varl D0 X CC TA Hb).
      apply (algo_sub_and_r D0 TA BB CC); exact Hsub.
  - (* D_andl *)
    destruct (IH1 BB CC eq_refl) as [H1B H1C].
    destruct (IH2 BB CC eq_refl) as [H2B H2C].
    split.
    + apply (D_andl D0 TA BB TA1 TA2 Hspl); assumption.
    + apply (D_andl D0 TA CC TA1 TA2 Hspl); assumption.
  - (* D_andr *)
    inversion Hspl; subst. split; assumption.
Qed.

Lemma papp_disjoint_and_r_inv : forall D A B C,
  disjoint D A (t_and B C) -> disjoint D A B /\ disjoint D A C.
Proof. intros. eapply papp_disjoint_and_r_gen; [ exact H | reflexivity ]. Qed.

Lemma papp_disjoint_and_l_gen : forall D AB C,
  disjoint D AB C -> forall A B, AB = t_and A B ->
  disjoint D A C /\ disjoint D B C.
Proof.
  intros D AB C H.
  induction H as
    [ D0 TA TB HTC HTA HTB Hax
    | D0 TA TB HTWB HtopA
    | D0 TA TB HTWA HtopB
    | D0 TA1 TA2 TB1 TB2 HTW1 HTW2 Hd IHd
    | D0 l TA TB Hd IHd
    | L D0 TA1 TB1 TA2 TB2 HTW1 HTW2 Hbody IHB
    | D0 X TB TA Hb Hsub
    | D0 TB X TA Hb Hsub
    | D0 TA TB TA1 TA2 Hspl Hd1 IH1 Hd2 IH2
    | D0 TA TB TB1 TB2 Hspl Hd1 IH1 Hd2 IH2 ];
    intros AA BB E; subst; try discriminate.
  - (* D_ax *) inversion Hax.
  - (* D_topl *)
    destruct (topLike_and_inv D0 AA BB HtopA) as [HA HB].
    split; [ apply (D_topl D0 AA TB HTWB HA)
           | apply (D_topl D0 BB TB HTWB HB) ].
  - (* D_topr *)
    destruct (TWell_and_inv D0 AA BB HTWA) as [HA HB].
    split; [ apply (D_topr D0 AA TB HA HtopB)
           | apply (D_topr D0 BB TB HB HtopB) ].
  - (* D_varr *)
    split.
    + apply (D_varr D0 AA X TA Hb).
      apply (algo_sub_and_l D0 TA AA BB); exact Hsub.
    + apply (D_varr D0 BB X TA Hb).
      apply (algo_sub_and_r D0 TA AA BB); exact Hsub.
  - (* D_andl *)
    inversion Hspl; subst. split; assumption.
  - (* D_andr *)
    destruct (IH1 AA BB eq_refl) as [H1A H1B].
    destruct (IH2 AA BB eq_refl) as [H2A H2B].
    split.
    + apply (D_andr D0 AA TB TB1 TB2 Hspl); assumption.
    + apply (D_andr D0 BB TB TB1 TB2 Hspl); assumption.
Qed.

Lemma papp_disjoint_and_l_inv : forall D A B C,
  disjoint D (t_and A B) C -> disjoint D A C /\ disjoint D B C.
Proof. intros. eapply papp_disjoint_and_l_gen; [ exact H | reflexivity ]. Qed.

(* ================================================================== *)
(* Goal A: body / argument extraction for abstractions.                *)
(* ================================================================== *)

Lemma papp_abs_chk_appDist_body_gen : forall D G A0 body B,
  Typing D G (e_abs A0 body) Chk B ->
  forall C1 C2, appDist B (t_arrow C1 C2) ->
  exists L, forall x, x \notin L ->
    Typing D (cons (x,A0) G)
      (open_exp_wrt_exp body (e_var_f x)) Chk C2.
Proof.
  intros D G A0 body B H C1 C2 Hdist.
  remember (e_abs A0 body) as e eqn:Ee.
  remember Chk as d eqn:Ed.
  revert A0 body C1 C2 Hdist Ee Ed.
  induction H;
    intros Ainit bodyinit PP QQ Hdist0 Eex Edd; subst; try discriminate.
  - (* Typ_abs *)
    inversion Eex; subst. inversion Hdist0; subst.
    exists L; intros x Hx. apply (H0 x Hx).
  - (* Typ_inter *)
    inversion Hdist0; subst.
    destruct (IHTyping1 Ainit bodyinit B1 C1 H4 eq_refl eq_refl)
      as [L1 HL1].
    destruct (IHTyping2 Ainit bodyinit B2 C2 H6 eq_refl eq_refl)
      as [L2 HL2].
    exists (L1 \u L2). intros x Hx. apply Typ_inter.
    + apply HL1. apply (notin_union_1 x L1 L2); exact Hx.
    + apply HL2. apply (notin_union_2 x L1 L2); exact Hx.
  - (* Typ_sub *)
    exfalso. exact (papp_abs_inf_impossible D G Ainit bodyinit A H).
Qed.

Lemma papp_abs_chk_appDist_body : forall A0 body B,
  Typing nil nil (e_abs A0 body) Chk B ->
  forall C1 C2, appDist B (t_arrow C1 C2) ->
  exists L, forall x, x \notin L ->
    Typing nil (cons (x,A0) nil)
      (open_exp_wrt_exp body (e_var_f x)) Chk C2.
Proof.
  intros. eapply papp_abs_chk_appDist_body_gen; eassumption.
Qed.

(* ================================================================== *)
(* Goal B: body extraction for type abstractions.                      *)
(* ================================================================== *)

Section TabsSubst.

Lemma papp_tabs_chk_appDist_body : forall body B,
  Typing nil nil (e_tabs body) Chk B ->
  forall C1 C2 C, appDist B (t_forall C1 C2) ->
  disjoint nil C C1 ->
  Typing nil nil (open_exp_wrt_typ body C) Chk (open_typ_wrt_typ C2 C).
Proof.
  intros body B Hty.
  dependent induction Hty; intros C1 C2 C Happ Hdisj.
  - (* Typ_tabs *)
    inversion Happ; subst.
    destruct (disjoint_lc nil C C1 Hdisj) as [HlcC _].
    destruct (atom_fresh
      (L \u (typefv_exp body \u (typefv_typ C2 \u typefv_typ C))))
      as [X HX].
    assert (HXL : X \notin L)
      by (apply (notin_union_1 X L
            (typefv_exp body \u (typefv_typ C2 \u typefv_typ C))); exact HX).
    assert (HXR : X \notin (typefv_exp body \u (typefv_typ C2 \u typefv_typ C)))
      by (apply (notin_union_2 X L
            (typefv_exp body \u (typefv_typ C2 \u typefv_typ C))); exact HX).
    assert (HXb : X \notin typefv_exp body)
      by (apply (notin_union_1 X (typefv_exp body)
            (typefv_typ C2 \u typefv_typ C)); exact HXR).
    assert (HXR2 : X \notin (typefv_typ C2 \u typefv_typ C))
      by (apply (notin_union_2 X (typefv_exp body)
            (typefv_typ C2 \u typefv_typ C)); exact HXR).
    assert (HXB : X \notin typefv_typ C2)
      by (apply (notin_union_1 X (typefv_typ C2) (typefv_typ C)); exact HXR2).
    assert (HTWC : TWell nil C)
      by (apply (disjoint_TWell_source_L nil C C1 TCW_empty); exact Hdisj).
    assert (HTWA : TWell nil C1)
      by (apply (disjoint_TWell_target_L nil C C1 TCW_empty); exact Hdisj).
    exact (agentL4.typing_typsubst_tabs body C1 C2 C X HlcC HXb HXB
             Hdisj HTWA HTWC (H0 X HXL)).
  - (* Typ_inter *)
    inversion Happ; subst.
    destruct (papp_disjoint_and_r_inv nil C B1 B2 Hdisj) as [Hd1 Hd2].
    pose proof (IHHty1 body (JMeq_refl _) (JMeq_refl _) eq_refl eq_refl B1 C0 C H2 Hd1)
      as HT1.
    pose proof (IHHty2 body (JMeq_refl _) (JMeq_refl _) eq_refl eq_refl B2 C3 C H4 Hd2)
      as HT2.
    apply Typ_inter; assumption.
  - (* Typ_sub *)
    exfalso. exact (papp_tabs_inf_impossible nil nil body A Hty).
Qed.

End TabsSubst.

(* ================================================================== *)
(* Type well-formedness of an abstraction annotation.                  *)
(* ================================================================== *)

Lemma papp_abs_chk_TWell_ann : forall A0 body Bann,
  Typing nil nil (e_abs A0 body) Chk Bann -> TWell nil A0.
Proof.
  intros A0 body Bann Hty. dependent induction Hty.
  - (* Typ_abs *)
    match goal with Hsub : algo_sub nil ?B1 A0 |- _ =>
      exact (algo_sub_TWell_target nil B1 A0 TCW_empty Hsub) end.
  - (* Typ_inter *)
    exact (IHHty2 A0 body (JMeq_refl _) (JMeq_refl _) eq_refl eq_refl).
  - (* Typ_sub *)
    exfalso.
    match goal with Hinf : Typing nil nil (e_abs _ _) Inf _ |- _ =>
      exact (papp_abs_inf_impossible nil nil _ _ _ Hinf) end.
Qed.

(* ================================================================== *)
(* Goal A2 (corrected): body extraction for record projections.        *)
(* ================================================================== *)

Lemma papp_rcd_chk_appDist_body : forall l0 e B,
  Typing nil nil (e_rcd l0 e) Chk B ->
  forall l C, appDist B (t_rcd l C) ->
  l = l0 /\ Typing nil nil e Chk C.
Proof.
  intros l0 e B Hty.
  dependent induction Hty; intros l C Happ.
  - (* Typ_rcd *)
    inversion Happ; subst. split; [ reflexivity | assumption ].
  - (* Typ_inter *)
    inversion Happ; subst.
    destruct (IHHty1 l0 e (JMeq_refl _) (JMeq_refl _) eq_refl eq_refl
                l B1 H2) as [E1 H1].
    destruct (IHHty2 l0 e (JMeq_refl _) (JMeq_refl _) eq_refl eq_refl
                l B2 H4) as [E2 H2'].
    split; [ exact E1 | apply Typ_inter; assumption ].
  - (* Typ_sub *)
    exfalso.
    match goal with Hinf : Typing nil nil (e_rcd _ _) Inf _ |- _ =>
      exact (papp_rcd_inf_impossible nil nil _ _ _ Hinf) end.
Qed.

(* ================================================================== *)
(* Small [subsub] helpers (not exported by the compiled libraries).    *)
(* ================================================================== *)

Lemma papp_subsub_refl : forall A, lc_typ A -> subsub A A.
Proof. intros A H. apply IS_refl. exact H. Qed.

Lemma papp_subsub_and_intro : forall A' B' A B,
  lc_typ A -> lc_typ B ->
  subsub A' A -> subsub B' B -> subsub (t_and A' B') (t_and A B).
Proof.
  intros A' B' A B HlcA HlcB HsubA HsubB.
  eapply IS_and.
  - apply Sp_and; assumption.
  - exact HsubA.
  - exact HsubB.
Qed.

Lemma papp_lc_typ_arrow_cod_l : forall A B C,
  appDist A (t_arrow B C) -> lc_typ C.
Proof.
  intros A B C H.
  exact (proj2 (lc_typ_arrow_inv B C (proj2 (appDist_lc A (t_arrow B C) H)))).
Qed.

Lemma papp_lc_typ_rcd_cod : forall A l C,
  appDist A (t_rcd l C) -> lc_typ C.
Proof.
  intros A l C H.
  exact (lc_typ_rcd_inv l C (proj2 (appDist_lc A (t_rcd l C) H))).
Qed.

Lemma papp_arg_typ_lc : forall v A r,
  papp v (arg_typ A) r -> lc_typ A.
Proof.
  intros v A r H. dependent induction H; try discriminate.
  - (* PApp_tabs *) assumption.
  - (* PApp_merge *) exact (IHpapp1 A eq_refl).
Qed.

Lemma papp_lc_typ_all_cod_open : forall A B C,
  lc_typ (t_forall A B) -> lc_typ C ->
  lc_typ (open_typ_wrt_typ B C).
Proof.
  intros A B C Hforall HC.
  destruct (lc_typ_forall_inv A B Hforall) as [_ HB].
  destruct (atom_fresh (typefv_typ B)) as [X HX].
  change (lc_typ (open_typ_wrt_typ_rec 0 C B)).
  rewrite <- (typsubst_open_typ 0 X C B HC HX).
  apply lc_typ_typsubst; [ exact HC | exact (HB X) ].
Qed.

(* ================================================================== *)
(* Goal C: typing of the results of papp.                              *)
(* ================================================================== *)

Section PappTyping.

(* The generic expression substitution lemma, instantiated concretely
   from subst_inst (no Section parameter). *)
Definition subst_gen : forall D Gbody body d B,
  Typing D Gbody body d B ->
  forall xsub Asub Gout Gsub,
    Gbody = Gout ++ (xsub,Asub)::Gsub ->
    xsub # Gout ->
  forall v P,
    lc_exp v -> TWell D P ->
    Typing D (Gout++Gsub) v Inf P ->
    subsub P Asub ->
    (match d with
     | Inf => exists B',
         Typing D (Gout++Gsub) (subst_exp v xsub body) Inf B' /\ subsub B' B
     | Chk => Typing D (Gout++Gsub) (subst_exp v xsub body) Chk B
     end)
  := fun D Gbody body d B Hty xsub Asub Gout Gsub Heq Hfresh v P Hlc HTW Hv Hss =>
       subst_inst.subst_gen_inst D Gbody body d B Hty xsub Asub Gout Gsub Heq Hfresh v P Hlc HTW Hv Hss.

(* Top-like codomains under distributivity. *)
Lemma papp_topA_arrow_cod : forall A B C,
  topLike nil A -> appDist A (t_arrow B C) -> topLike nil C.
Proof.
  intros A B C Htop Hdist.
  dependent induction Hdist.
  - apply topLike_and_inv in Htop as [H1 H2].
    apply TL_and.
    + exact (IHHdist1 B1 C1 H1 eq_refl).
    + exact (IHHdist2 B2 C2 H2 eq_refl).
  - apply topLike_arrow_inv in Htop. tauto.
Qed.

Lemma papp_topA_rcd_cod : forall A l C,
  topLike nil A -> appDist A (t_rcd l C) -> topLike nil C.
Proof.
  intros A l C Htop Hdist.
  dependent induction Hdist.
  - apply topLike_and_inv in Htop as [H1 H2].
    apply TL_and.
    + exact (IHHdist1 l B1 H1 eq_refl).
    + exact (IHHdist2 l B2 H2 eq_refl).
  - apply topLike_rcd_inv in Htop. exact Htop.
Qed.

(* Codomains of disjoint arrow distributivity targets are disjoint. *)
Lemma appDist_arrow_cod_disjoint : forall A1 A2 B1 C1 B2 C2,
  disjoint nil A1 A2 ->
  appDist A1 (t_arrow B1 C1) ->
  appDist A2 (t_arrow B2 C2) ->
  disjoint nil C1 C2.
Proof.
  intros pA1 pA2 pB1 pC1 pB2 pC2 Hd.
  revert pB1 pC1 pB2 pC2.
  dependent induction Hd; intros pB1 pC1 pB2 pC2 Happ1 Happ2.
  - (* D_ax *) destruct H2; inversion Happ1; inversion Happ2.
  - (* D_topl *)
    pose proof (appDist_TWell nil B (t_arrow pB2 pC2) H Happ2) as HTW2.
    destruct (TWell_arrow_inv nil pB2 pC2 HTW2) as [_ HTWC2].
    apply (D_topl nil pC1 pC2 HTWC2).
    apply (papp_topA_arrow_cod A pB1 pC1 H0 Happ1).
  - (* D_topr *)
    pose proof (appDist_TWell nil A (t_arrow pB1 pC1) H Happ1) as HTW1.
    destruct (TWell_arrow_inv nil pB1 pC1 HTW1) as [_ HTWC1].
    apply (D_topr nil pC1 pC2 HTWC1).
    apply (papp_topA_arrow_cod B pB2 pC2 H0 Happ2).
  - (* D_arrow *)
    inversion Happ1; subst. inversion Happ2; subst. assumption.
  - (* D_rcdEq *) inversion Happ1.
  - (* D_all *) inversion Happ1; inversion Happ2.
  - (* D_varl *) inversion Happ1; inversion Happ2.
  - (* D_varr *) inversion Happ1; inversion Happ2.
  - (* D_andl *)
    inversion Happ1; subst.
    + (* AD_andArrow *)
      inversion H; subst.
      destruct (appDist_lc A1 (t_arrow B1 C1) H3) as [_ Hlc1].
      destruct (lc_typ_arrow_inv B1 C1 Hlc1) as [HlcB1 HlcC1].
      destruct (appDist_lc A2 (t_arrow B2 C2) H4) as [_ Hlc2].
      destruct (lc_typ_arrow_inv B2 C2 Hlc2) as [HlcB2 HlcC2].
      apply (D_andl nil (t_and C1 C2) pC2 C1 C2 (Sp_and C1 C2 HlcC1 HlcC2)).
      * exact (IHHd1 (JMeq_refl _) B1 C1 pB2 pC2 H3 Happ2).
      * exact (IHHd2 (JMeq_refl _) B2 C2 pB2 pC2 H4 Happ2).
    + inversion H; subst.
      assert (HD1 : appDist (t_arrow pB1 C1) (t_arrow pB1 C1))
        by (apply AD_refl; apply lc_t_arrow;
            [ exact H3 | apply (spl_lcB pC1 C1 C2 H6) ]).
      assert (HD2 : appDist (t_arrow pB1 C2) (t_arrow pB1 C2))
        by (apply AD_refl; apply lc_t_arrow;
            [ exact H3 | apply (spl_lcC pC1 C1 C2 H6) ]).
      apply (D_andl nil pC1 pC2 C1 C2 H6).
      * exact (IHHd1 (JMeq_refl _) pB1 C1 pB2 pC2 HD1 Happ2).
      * exact (IHHd2 (JMeq_refl _) pB1 C2 pB2 pC2 HD2 Happ2).
  - (* D_andr *)
    inversion Happ2; subst.
    + (* AD_andArrow *)
      inversion H; subst.
      destruct (appDist_lc B1 (t_arrow B0 C1) H3) as [_ Hlc1].
      destruct (lc_typ_arrow_inv B0 C1 Hlc1) as [HlcB0 HlcC1].
      destruct (appDist_lc B2 (t_arrow B3 C2) H4) as [_ Hlc2].
      destruct (lc_typ_arrow_inv B3 C2 Hlc2) as [HlcB3 HlcC2].
      apply (D_andr nil pC1 (t_and C1 C2) C1 C2 (Sp_and C1 C2 HlcC1 HlcC2)).
      * exact (IHHd1 (JMeq_refl _) pB1 pC1 B0 C1 Happ1 H3).
      * exact (IHHd2 (JMeq_refl _) pB1 pC1 B3 C2 Happ1 H4).
    + inversion H; subst.
      assert (HD1 : appDist (t_arrow pB2 C1) (t_arrow pB2 C1))
        by (apply AD_refl; apply lc_t_arrow;
            [ exact H3 | apply (spl_lcB pC2 C1 C2 H6) ]).
      assert (HD2 : appDist (t_arrow pB2 C2) (t_arrow pB2 C2))
        by (apply AD_refl; apply lc_t_arrow;
            [ exact H3 | apply (spl_lcC pC2 C1 C2 H6) ]).
      apply (D_andr nil pC1 pC2 C1 C2 H6).
      * exact (IHHd1 (JMeq_refl _) pB1 pC1 pB2 C1 Happ1 HD1).
      * exact (IHHd2 (JMeq_refl _) pB1 pC1 pB2 C2 Happ1 HD2).
Qed.

(* Codomains of disjoint record distributivity targets are disjoint. *)
Lemma appDist_rcd_cod_disjoint : forall A1 A2 l C1 C2,
  disjoint nil A1 A2 ->
  appDist A1 (t_rcd l C1) ->
  appDist A2 (t_rcd l C2) ->
  disjoint nil C1 C2.
Proof.
  intros pA1 pA2 lab pC1 pC2 Hd.
  revert lab pC1 pC2.
  dependent induction Hd; intros lab pC1 pC2 Happ1 Happ2.
  - (* D_ax *) destruct H2; inversion Happ1; inversion Happ2; subst; try discriminate.
    contradiction.
  - (* D_topl *)
    pose proof (appDist_TWell nil B (t_rcd lab pC2) H Happ2) as HTW2.
    pose proof (TWell_rcd_inv nil lab pC2 HTW2) as HTWC2.
    apply (D_topl nil pC1 pC2 HTWC2).
    apply (papp_topA_rcd_cod A lab pC1 H0 Happ1).
  - (* D_topr *)
    pose proof (appDist_TWell nil A (t_rcd lab pC1) H Happ1) as HTW1.
    pose proof (TWell_rcd_inv nil lab pC1 HTW1) as HTWC1.
    apply (D_topr nil pC1 pC2 HTWC1).
    apply (papp_topA_rcd_cod B lab pC2 H0 Happ2).
  - (* D_arrow *) inversion Happ1.
  - (* D_rcdEq *)
    inversion Happ1; subst. inversion Happ2; subst. assumption.
  - (* D_all *) inversion Happ1.
  - (* D_varl *) inversion Happ1.
  - (* D_varr *) inversion Happ2.
  - (* D_andl *)
    inversion Happ1; subst.
    + (* AD_andRcd *)
      inversion H; subst.
      destruct (appDist_lc A1 (t_rcd lab B1) H3) as [_ Hlc1].
      pose proof (lc_typ_rcd_inv lab B1 Hlc1) as HlcB1.
      destruct (appDist_lc A2 (t_rcd lab B2) H4) as [_ Hlc2].
      pose proof (lc_typ_rcd_inv lab B2 Hlc2) as HlcB2.
      apply (D_andl nil (t_and B1 B2) pC2 B1 B2 (Sp_and B1 B2 HlcB1 HlcB2)).
      * exact (IHHd1 (JMeq_refl _) lab B1 pC2 H3 Happ2).
      * exact (IHHd2 (JMeq_refl _) lab B2 pC2 H4 Happ2).
    + (* AD_refl *)
      inversion H; subst.
      assert (HD1 : appDist (t_rcd lab C1) (t_rcd lab C1))
        by (apply AD_refl; apply lc_t_rcd;
            apply (spl_lcB pC1 C1 C2 H5)).
      assert (HD2 : appDist (t_rcd lab C2) (t_rcd lab C2))
        by (apply AD_refl; apply lc_t_rcd;
            apply (spl_lcC pC1 C1 C2 H5)).
      apply (D_andl nil pC1 pC2 C1 C2 H5).
      * exact (IHHd1 (JMeq_refl _) lab C1 pC2 HD1 Happ2).
      * exact (IHHd2 (JMeq_refl _) lab C2 pC2 HD2 Happ2).
  - (* D_andr *)
    inversion Happ2; subst.
    + (* AD_andRcd *)
      inversion H; subst.
      destruct (appDist_lc B1 (t_rcd lab B0) H3) as [_ Hlc1].
      pose proof (lc_typ_rcd_inv lab B0 Hlc1) as HlcB0.
      destruct (appDist_lc B2 (t_rcd lab B3) H4) as [_ Hlc2].
      pose proof (lc_typ_rcd_inv lab B3 Hlc2) as HlcB3.
      apply (D_andr nil pC1 (t_and B0 B3) B0 B3 (Sp_and B0 B3 HlcB0 HlcB3)).
      * exact (IHHd1 (JMeq_refl _) lab pC1 B0 Happ1 H3).
      * exact (IHHd2 (JMeq_refl _) lab pC1 B3 Happ1 H4).
    + (* AD_refl *)
      inversion H; subst.
      assert (HD1 : appDist (t_rcd lab C1) (t_rcd lab C1))
        by (apply AD_refl; apply lc_t_rcd;
            apply (spl_lcB pC2 C1 C2 H5)).
      assert (HD2 : appDist (t_rcd lab C2) (t_rcd lab C2))
        by (apply AD_refl; apply lc_t_rcd;
            apply (spl_lcC pC2 C1 C2 H5)).
      apply (D_andr nil pC1 pC2 C1 C2 H5).
      * exact (IHHd1 (JMeq_refl _) lab pC1 C1 Happ1 HD1).
      * exact (IHHd2 (JMeq_refl _) lab pC1 C2 Happ1 HD2).
Qed.

Lemma TWell_all_body_open_nil : forall B2 C2 C,
  TWell nil (t_forall B2 C2) -> TWell nil C ->
  TWell nil (open_typ_wrt_typ C2 C).
Proof.
  intros B2 C2 C HT HCT.
  destruct (TWell_all_body nil B2 C2 HT) as [L HB].
  destruct (atom_fresh (L \u typefv_typ C2)) as [X HX].
  destruct (notin_union X L (typefv_typ C2) HX) as [HXL HXfv].
  assert (HX0 : X \notin dom (nil:tctx)) by (apply agentL2.notin_dom_nil).
  pose proof (agentL.TWell_typsubst_head (nil:tctx) X B2 C
                (open_typ_wrt_typ C2 (t_tvar_f X)) HX0 (HB X HXL) HCT) as Hres.
  rewrite agentL2.tsubst_mid_nil in Hres.
  simpl in Hres.
  rewrite (agentL.typsubst_open_typ_same C X (TWell_lc nil C HCT) C2) in Hres.
  rewrite (agentL.typsubst_typ_id_notin C X C2 HXfv) in Hres.
  exact Hres.
Qed.

Lemma topLike_all_body_open_nil : forall B2 C2 C,
  topLike nil (t_forall B2 C2) ->
  TWell nil C ->
  (topLike nil C \/ ~ botLike B2) ->
  topLike nil (open_typ_wrt_typ C2 C).
Proof.
  intros B2 C2 C HT HCT Hside.
  destruct (agentL2.topLike_all_body_inv_local nil B2 C2 HT) as [L HB].
  destruct (atom_fresh (L \u typefv_typ C2)) as [X HX].
  destruct (notin_union X L (typefv_typ C2) HX) as [HXL HXfv].
  assert (HX0 : X \notin dom (nil:tctx)) by (apply agentL2.notin_dom_nil).
  assert (HTCt : TCWell (tsubst_mid C X nil nil)).
  { rewrite agentL2.tsubst_mid_nil. simpl. exact TCW_empty. }
  assert (HCTt : TWell (tsubst_mid C X nil nil) C).
  { rewrite agentL2.tsubst_mid_nil. simpl. exact HCT. }
  pose proof (agentL2.topLike_typsubst_mid_gen_nobot
     (cons (X,B2) nil) (open_typ_wrt_typ C2 (t_tvar_f X)) (HB X HXL)
     nil X B2 nil eq_refl HX0 C HTCt HCTt Hside) as Hres.
  rewrite agentL2.tsubst_mid_nil in Hres.
  simpl in Hres.
  rewrite (agentL.typsubst_open_typ_same C X (TWell_lc nil C HCT) C2) in Hres.
  rewrite (agentL.typsubst_typ_id_notin C X C2 HXfv) in Hres.
  exact Hres.
Qed.

Lemma disjoint_all_open_cod_base : forall B1 C1 B2 C2 C,
  disjoint nil (t_forall B1 C1) (t_forall B2 C2) ->
  disjoint nil C B1 -> disjoint nil C B2 ->
  disjoint nil (open_typ_wrt_typ C1 C) (open_typ_wrt_typ C2 C).
Proof.
  intros B1 C1 B2 C2 C Hd.
  dependent induction Hd; intros HdC1 HdC2.
  - (* D_ax *) match goal with Hax0 : disjoint_axiom _ _ |- _ => inversion Hax0 end.
  - (* D_topl *)
    apply D_topl.
    + apply (TWell_all_body_open_nil B2 C2 C); [ assumption | apply (disjoint_TWell_l nil C B1 TCW_empty HdC1) ].
    + apply (topLike_all_body_open_nil B1 C1 C); [ assumption | apply (disjoint_TWell_l nil C B1 TCW_empty HdC1) | apply (agentL2.disjoint_nil_topLike_or_not_botLike C B1 HdC1) ].
  - (* D_topr *)
    apply D_topr.
    + apply (TWell_all_body_open_nil B1 C1 C); [ assumption | apply (disjoint_TWell_l nil C B2 TCW_empty HdC2) ].
    + apply (topLike_all_body_open_nil B2 C2 C); [ assumption | apply (disjoint_TWell_l nil C B2 TCW_empty HdC2) | apply (agentL2.disjoint_nil_topLike_or_not_botLike C B2 HdC2) ].
  - (* D_all *)
    destruct (atom_fresh (L \u typefv_typ C1 \u typefv_typ C2)) as [X HX].
    destruct (notin_union X L (typefv_typ C1 \u typefv_typ C2) HX) as [HXL HX12].
    destruct (notin_union X (typefv_typ C1) (typefv_typ C2) HX12) as [HXfv1 HXfv2].
    destruct (disjoint_lc nil C B1 HdC1) as [HlcC _].
    assert (HCT : TWell nil C)
      by (apply (disjoint_TWell_l nil C B1 TCW_empty); exact HdC1).
    assert (HlcB1 : lc_typ B1) by (apply (TWell_lc nil B1); exact H).
    assert (HlcB2 : lc_typ B2) by (apply (TWell_lc nil B2); exact H0).
    assert (HdCand : disjoint nil C (t_and B1 B2))
      by (apply (D_andr nil C (t_and B1 B2) B1 B2 (Sp_and B1 B2 HlcB1 HlcB2));
          assumption).
    assert (HTC0 : TCWell (cons (X, t_and B1 B2) (nil:tctx)))
      by (apply (TCW_cons nil X (t_and B1 B2) TCW_empty (TW_and nil B1 B2 H H0)
                 (uniq_tcons_nil X (t_and B1 B2)))).
    assert (Hbody : disjoint (cons (X, t_and B1 B2) nil)
                       (open_typ_wrt_typ C1 (t_tvar_f X))
                       (open_typ_wrt_typ C2 (t_tvar_f X)))
      by (apply H1; exact HXL).
    pose proof (agentL4.disjoint_typsubst_mid_ordfree C X (t_and B1 B2)
                  HlcC HCT HdCand
                  (cons (X, t_and B1 B2) nil)
                  (open_typ_wrt_typ C1 (t_tvar_f X))
                  (open_typ_wrt_typ C2 (t_tvar_f X))
                  Hbody nil eq_refl (agentL2.notin_dom_nil X) HTC0) as Hres.
    simpl in Hres.
    rewrite (agentL.typsubst_open_typ_same C X HlcC C1) in Hres.
    rewrite (agentL.typsubst_open_typ_same C X HlcC C2) in Hres.
    rewrite (agentL.typsubst_typ_id_notin C X C1 HXfv1) in Hres.
    rewrite (agentL.typsubst_typ_id_notin C X C2 HXfv2) in Hres.
    exact Hres.
  - (* D_andl *)
    destruct (agentL3.spl_all_inv B1 C1 A1 A2 H) as [B1a Hrest].
    destruct Hrest as [B1b Hrest]. destruct Hrest as [Ls Hrest].
    destruct Hrest as [HA1 Hrest]. destruct Hrest as [HA2 Hrest].
    destruct Hrest as [HlcB1 Hbody].
    subst A1. subst A2.
    assert (Hr1 : disjoint nil (open_typ_wrt_typ B1a C) (open_typ_wrt_typ C2 C)).
    { apply (IHHd1 B1 B1a B2 C2); try reflexivity; assumption. }
    assert (Hr2 : disjoint nil (open_typ_wrt_typ B1b C) (open_typ_wrt_typ C2 C)).
    { apply (IHHd2 B1 B1b B2 C2); try reflexivity; assumption. }
    destruct (disjoint_lc nil C B1 HdC1) as [HlcC _].
    destruct (atom_fresh (Ls \u typefv_typ C1 \u typefv_typ B1a \u typefv_typ B1b))
      as [Y HY].
    destruct (notin_union Y Ls (typefv_typ C1 \u typefv_typ B1a \u typefv_typ B1b) HY)
      as [HYL HY123].
    destruct (notin_union Y (typefv_typ C1) (typefv_typ B1a \u typefv_typ B1b) HY123)
      as [HY1 HY12].
    destruct (notin_union Y (typefv_typ B1a) (typefv_typ B1b) HY12) as [HYa HYb].
    pose proof (Hbody Y HYL) as HsplY.
    pose proof (agentL.typsubst_spl C Y HlcC
                  (open_typ_wrt_typ C1 (t_tvar_f Y))
                  (open_typ_wrt_typ B1a (t_tvar_f Y))
                  (open_typ_wrt_typ B1b (t_tvar_f Y)) HsplY) as HsplC.
    rewrite (agentL.typsubst_open_typ_same C Y HlcC C1) in HsplC.
    rewrite (agentL.typsubst_open_typ_same C Y HlcC B1a) in HsplC.
    rewrite (agentL.typsubst_open_typ_same C Y HlcC B1b) in HsplC.
    rewrite (agentL.typsubst_typ_id_notin C Y C1 HY1) in HsplC.
    rewrite (agentL.typsubst_typ_id_notin C Y B1a HYa) in HsplC.
    rewrite (agentL.typsubst_typ_id_notin C Y B1b HYb) in HsplC.
    exact (D_andl nil (open_typ_wrt_typ C1 C) (open_typ_wrt_typ C2 C)
             (open_typ_wrt_typ B1a C) (open_typ_wrt_typ B1b C)
             HsplC Hr1 Hr2).
  - (* D_andr *)
    destruct (agentL3.spl_all_inv B2 C2 B0 B3 H) as [B2a Hrest].
    destruct Hrest as [B2b Hrest]. destruct Hrest as [Ls Hrest].
    destruct Hrest as [HB0 Hrest]. destruct Hrest as [HB3 Hrest].
    destruct Hrest as [HlcB2 Hbody].
    subst B0. subst B3.
    assert (Hr1 : disjoint nil (open_typ_wrt_typ C1 C) (open_typ_wrt_typ B2a C)).
    { apply (IHHd1 B1 C1 B2 B2a); try reflexivity; assumption. }
    assert (Hr2 : disjoint nil (open_typ_wrt_typ C1 C) (open_typ_wrt_typ B2b C)).
    { apply (IHHd2 B1 C1 B2 B2b); try reflexivity; assumption. }
    destruct (disjoint_lc nil C B2 HdC2) as [HlcC _].
    destruct (atom_fresh (Ls \u typefv_typ C2 \u typefv_typ B2a \u typefv_typ B2b))
      as [Y HY].
    destruct (notin_union Y Ls (typefv_typ C2 \u typefv_typ B2a \u typefv_typ B2b) HY)
      as [HYL HY123].
    destruct (notin_union Y (typefv_typ C2) (typefv_typ B2a \u typefv_typ B2b) HY123)
      as [HY2 HY12].
    destruct (notin_union Y (typefv_typ B2a) (typefv_typ B2b) HY12) as [HYa HYb].
    pose proof (Hbody Y HYL) as HsplY.
    pose proof (agentL.typsubst_spl C Y HlcC
                  (open_typ_wrt_typ C2 (t_tvar_f Y))
                  (open_typ_wrt_typ B2a (t_tvar_f Y))
                  (open_typ_wrt_typ B2b (t_tvar_f Y)) HsplY) as HsplC.
    rewrite (agentL.typsubst_open_typ_same C Y HlcC C2) in HsplC.
    rewrite (agentL.typsubst_open_typ_same C Y HlcC B2a) in HsplC.
    rewrite (agentL.typsubst_open_typ_same C Y HlcC B2b) in HsplC.
    rewrite (agentL.typsubst_typ_id_notin C Y C2 HY2) in HsplC.
    rewrite (agentL.typsubst_typ_id_notin C Y B2a HYa) in HsplC.
    rewrite (agentL.typsubst_typ_id_notin C Y B2b HYb) in HsplC.
    exact (D_andr nil (open_typ_wrt_typ C1 C) (open_typ_wrt_typ C2 C)
             (open_typ_wrt_typ B2a C) (open_typ_wrt_typ B2b C)
             HsplC Hr1 Hr2).
Qed.

Lemma appDist_all_cod_disjoint_open_nil : forall A1 A2 B1 C1 B2 C2 C,
    disjoint nil A1 A2 ->
    appDist A1 (t_forall B1 C1) ->
    appDist A2 (t_forall B2 C2) ->
    disjoint nil C B1 ->
    disjoint nil C B2 ->
    disjoint nil (open_typ_wrt_typ C1 C) (open_typ_wrt_typ C2 C).
Proof.
  intros A1 A2 B1 C1 B2 C2 C HdA H1 H2 HdC1 HdC2.
  dependent induction H1.
  - (* andAll *)
    assert (HdA1 : disjoint nil A1 A2)
      by exact (proj1 (papp_disjoint_and_l_inv nil A1 A0 A2 HdA)).
    assert (HdA0 : disjoint nil A0 A2)
      by exact (proj2 (papp_disjoint_and_l_inv nil A1 A0 A2 HdA)).
    destruct (papp_disjoint_and_r_inv nil C B3 B0 HdC1) as [HdC1a HdC1b].
    destruct (disjoint_lc nil C B3 HdC1a) as [HlcC _].
    cbn.
    apply (D_andl nil (t_and (open_typ_wrt_typ C3 C) (open_typ_wrt_typ C0 C))
              (open_typ_wrt_typ C2 C)
              (open_typ_wrt_typ C3 C) (open_typ_wrt_typ C0 C)).
    + apply Sp_and.
      * exact (papp_lc_typ_all_cod_open B3 C3 C
                 (proj2 (appDist_lc A1 (t_forall B3 C3) H1_)) HlcC).
      * exact (papp_lc_typ_all_cod_open B0 C0 C
                 (proj2 (appDist_lc A0 (t_forall B0 C0) H1_0)) HlcC).
    + apply (IHappDist1 B3 C3 HdA1 eq_refl H2 HdC1a HdC2).
    + apply (IHappDist2 B0 C0 HdA0 eq_refl H2 HdC1b HdC2).
  - (* refl *)
    dependent induction H2.
    + (* andAll right *)
      destruct (papp_disjoint_and_r_inv nil (t_forall B1 C1) A1 A2 HdA) as [HdA1 HdA2].
      destruct (papp_disjoint_and_r_inv nil C B0 B3 HdC2) as [HdC2a HdC2b].
      destruct (disjoint_lc nil C B1 HdC1) as [HlcC _].
      assert (Hr1 : disjoint nil (open_typ_wrt_typ C1 C) (open_typ_wrt_typ C0 C))
        by exact (IHappDist1 B0 C0 H HdA1 eq_refl HdC1 HdC2a).
      assert (Hr2 : disjoint nil (open_typ_wrt_typ C1 C) (open_typ_wrt_typ C3 C))
        by exact (IHappDist2 B3 C3 H HdA2 eq_refl HdC1 HdC2b).
      cbn.
      apply (D_andr nil (open_typ_wrt_typ C1 C)
              (t_and (open_typ_wrt_typ C0 C) (open_typ_wrt_typ C3 C))
              (open_typ_wrt_typ C0 C) (open_typ_wrt_typ C3 C)).
      * apply Sp_and.
        -- exact (papp_lc_typ_all_cod_open B0 C0 C
                    (proj2 (appDist_lc A1 (t_forall B0 C0) H2_)) HlcC).
        -- exact (papp_lc_typ_all_cod_open B3 C3 C
                    (proj2 (appDist_lc A2 (t_forall B3 C3) H2_0)) HlcC).
      * exact Hr1.
      * exact Hr2.
    + (* refl right *)
      apply (disjoint_all_open_cod_base B1 C1 B2 C2 C); assumption.
Qed.

Definition appDist_all_cod_disjoint_open_disj := appDist_all_cod_disjoint_open_nil.

Ltac solve_spl_top := exfalso; eapply spl_not_ord; [eassumption | apply O_top].
Ltac solve_spl_ord := exfalso; eapply spl_not_ord; eassumption.
Ltac solve_ntl_top :=
  exfalso;
  match goal with
  | Hn : notTopLike nil ?T, Ht : topLike nil ?T |- _ =>
    destruct (notTopLike_inv nil T Hn) as [Htc Hrest];
    destruct Hrest as [Htw Hn'];
    exact (Hn' Ht)
  end.

Lemma papp_wrapping_functional : forall e A e1 e2,
  wrapping e A e1 -> wrapping e A e2 -> e1 = e2.
Proof.
  intros e A e1 e2 H1.
  revert e2.
  induction H1; intros e2x H2.
  all: try (inversion H2; subst; try reflexivity).
  all: try solve_spl_top.
  all: try solve_spl_ord.
  all: try solve_ntl_top.
  all: try (exfalso;
    match goal with
    | Hn : notTopLike nil t_top |- _ =>
      destruct (notTopLike_inv nil t_top Hn) as [Htc Hrest];
      destruct Hrest as [Htw Hn'];
      exact (Hn' (TL_top nil TCW_empty))
    end).
  all: try (
    match goal with
    | Hs1 : spl ?A ?B ?C, Hs2 : spl ?A ?B2 ?C2,
      Hw1 : wrapping ?e ?B ?u, Hw1' : wrapping ?e ?B2 ?u',
      Hw2 : wrapping ?e ?C ?v, Hw2' : wrapping ?e ?C2 ?v',
      IH1 : forall t, wrapping ?e ?B t -> ?u = t,
      IH2 : forall t, wrapping ?e ?C t -> ?v = t |- _ =>
      let E1 := fresh in let E2 := fresh in
      destruct (spl_functional A B C B2 C2 Hs1 Hs2) as [E1 E2];
      subst B2; subst C2;
      rewrite (IH1 u' Hw1'); rewrite (IH2 v' Hw2'); reflexivity
    end).
Qed.

Lemma papp_wrapping_lc_output : forall e A e',
  wrapping e A e' -> lc_exp e'.
Proof.
  intros e A e' H. induction H.
  - apply lc_e_top.
  - apply lc_e_anno; [ apply lc_exp_abs_top | apply ord_lc_typ with (A:=t_arrow A1 A2); assumption ].
  - apply lc_e_anno; [ apply lc_exp_tabs_top | apply ord_lc_typ with (A:=t_forall A1 A2); assumption ].
  - apply lc_e_anno; [ apply lc_exp_rcd_top | apply ord_lc_typ with (A:=t_rcd l A); assumption ].
  - apply lc_e_anno; [ assumption | apply ord_lc_typ; assumption ].
  - apply lc_e_merge; assumption.
Qed.

Lemma papp_lc_exp_open_exp_body : forall e v,
  (forall x, lc_exp (open_exp_wrt_exp e (e_var_f x))) ->
  lc_exp v ->
  lc_exp (open_exp_wrt_exp e v).
Proof.
  intros e v Hbody Hv.
  destruct (atom_fresh (termfv_exp e)) as [x Hx].
  change (lc_exp (open_exp_wrt_exp_rec 0 v e)).
  rewrite <- (agentC.subst_open_exp_exp_fresh 0 x v e Hx).
  apply agentC.lc_exp_subst_exp.
  - exact Hv.
  - exact (Hbody x).
Qed.

Lemma papp_lc_exp_open_exp_typ_body : forall e C,
  (forall X, lc_exp (open_exp_wrt_typ e (t_tvar_f X))) ->
  lc_typ C ->
  lc_exp (open_exp_wrt_typ e C).
Proof.
  intros e C Hbody HC.
  destruct (atom_fresh (typefv_exp e)) as [X HX].
  change (lc_exp (open_exp_wrt_typ_rec 0 C e)).
  rewrite <- (agentC.typsubst_open_exp_typ 0 X C e HC HX).
  apply agentC.lc_exp_typsubst.
  - exact HC.
  - exact (Hbody X).
Qed.

Lemma papp_lc_exp_tabs_inv : forall e,
  lc_exp (e_tabs e) -> (forall X, lc_exp (open_exp_wrt_typ e (t_tvar_f X))).
Proof. intros e H. inversion H; subst. assumption. Qed.

Lemma papp_source_pType : forall v arg e,
  papp v arg e ->
  forall A, Typing nil nil v Inf A -> pType v A.
Proof.
  intros v arg e Hp.
  dependent induction Hp.
  - (* abs *)
    intros Aty Hty.
    inversion Hty; subst.
    apply PT_anno.
    + exact H.
    + apply (proj1 (appDist_lc Aty (t_arrow C1 C2) H0)).
  - (* tabs *)
    intros Aty Hty.
    inversion Hty; subst.
    apply PT_anno.
    + exact H.
    + apply (proj1 (appDist_lc Aty (t_forall B1 B2) H1)).
  - (* proj *)
    intros Aty Hty.
    inversion Hty; subst.
    apply PT_anno.
    + apply lc_e_rcd. exact H.
    + apply (proj1 (appDist_lc Aty (t_rcd l B) H0)).
  - (* merge *)
    intros Aty Hty.
    inversion Hty; subst.
    + apply PT_merge.
      * apply (IHHp1 A). assumption.
      * apply (IHHp2 B). assumption.
    + apply PT_merge.
      * apply (IHHp1 A). assumption.
      * apply (IHHp2 B). assumption.
Qed.

Lemma papp_result_pType_prevalue_lc_exists : forall v arg r,
  papp v arg r ->
  exists C, pType r C /\ prevalue r /\ lc_exp r.
Proof.
  intros v arg r Hp.
  dependent induction Hp.
  - (* PApp_abs *)
    destruct (lc_exp_abs_inv A e1 H) as [HlcA Hbody].
    pose proof (papp_wrapping_lc_output e2 A e2' H1) as Hlce2.
    pose proof (papp_lc_typ_arrow_cod_l B C1 C2 H0) as HlcC2.
    exists C2. repeat split.
    + apply PT_anno.
      * apply (papp_lc_exp_open_exp_body e1 e2'); assumption.
      * exact HlcC2.
    + apply PV_anno.
      * apply (papp_lc_exp_open_exp_body e1 e2'); assumption.
      * exact HlcC2.
    + apply lc_e_anno.
      * apply (papp_lc_exp_open_exp_body e1 e2'); assumption.
      * exact HlcC2.
  - (* PApp_tabs *)
    pose proof (papp_lc_exp_tabs_inv e H) as Hbody.
    pose proof (papp_lc_typ_all_cod_open B1 B2 C
                  (proj2 (appDist_lc A (t_forall B1 B2) H1)) H0) as HlcC.
    exists (open_typ_wrt_typ B2 C). repeat split.
    + apply PT_anno.
      * apply (papp_lc_exp_open_exp_typ_body e C); assumption.
      * exact HlcC.
    + apply PV_anno.
      * apply (papp_lc_exp_open_exp_typ_body e C); assumption.
      * exact HlcC.
    + apply lc_e_anno.
      * apply (papp_lc_exp_open_exp_typ_body e C); assumption.
      * exact HlcC.
  - (* PApp_proj *)
    pose proof (papp_lc_typ_rcd_cod A l B H0) as HlcB.
    exists B. repeat split.
    + apply PT_anno; assumption.
    + apply PV_anno; assumption.
    + apply lc_e_anno; assumption.
  - (* PApp_merge *)
    destruct IHHp1 as (C1 & Hpt1 & Hpv1 & Hlc1).
    destruct IHHp2 as (C2 & Hpt2 & Hpv2 & Hlc2).
    exists (t_and C1 C2). repeat split.
    + apply PT_merge; assumption.
    + apply PV_merge; assumption.
    + apply lc_e_merge; assumption.
Qed.

Lemma arrow_result_disjoint : forall v1 e r1,
  papp v1 (arg_exp e) r1 ->
  forall v2 r2,
  papp v2 (arg_exp e) r2 ->
  forall A1 A2 C1r C2r,
  pType v1 A1 -> pType v2 A2 ->
  pType r1 C1r -> pType r2 C2r ->
  disjoint nil A1 A2 -> disjoint nil C1r C2r.
Proof.
  intros v1 e r1 Hp1.
  dependent induction Hp1.
  - (* outer abs *)
    intros v2 r2 Hp2 A1 A2 C1r C2r Hptv1 Hptv2 Hpte1 Hpte2 Hd.
    dependent induction Hp2.
    + (* inner abs *)
      inversion Hptv1; subst. inversion Hptv2; subst.
      inversion Hpte1; subst. inversion Hpte2; subst.
      eapply appDist_arrow_cod_disjoint; eassumption.
    + (* inner merge *)
      inversion Hptv1; subst. inversion Hptv2; subst.
      inversion Hpte1; subst. inversion Hpte2; subst.
      destruct (papp_disjoint_and_r_inv nil A1 A0 B Hd) as [Hd1 Hd2].
      assert (Hres1 : disjoint nil C1r A2).
      { exact (IHHp2_1 e H H0 H1 eq_refl A1 A0 C1r A2 Hptv1 H5 Hpte1 H9 Hd1). }
      assert (Hres2 : disjoint nil C1r B0).
      { exact (IHHp2_2 e H H0 H1 eq_refl A1 B C1r B0 Hptv1 H8 Hpte1 H12 Hd2). }
      apply (D_andr nil C1r (t_and A2 B0) A2 B0).
      * apply Sp_and.
        -- apply (pType_lc_typ e0 A2 H9).
        -- apply (pType_lc_typ e2 B0 H12).
      * exact Hres1.
      * exact Hres2.
  - (* outer merge *)
    intros v2x r2x Hp2x A1 A2 C1r C2r Hptv1 Hptv2 Hpte1 Hpte2 Hd.
    dependent induction Hp2x.
    + (* inner abs *)
      inversion Hptv1; subst. inversion Hptv2; subst.
      inversion Hpte1; subst. inversion Hpte2; subst.
      destruct (papp_disjoint_and_l_inv nil A0 B0 A2 Hd) as [Hd1 Hd2].
      assert (Hres1 : disjoint nil A1 C2r).
      { exact (IHHp1_1 e eq_refl
                 (e_anno (e_abs A e0) A2) (e_anno (e0 ^^ e2') C2r)
                 (PApp_abs A e0 A2 e e2' C2r C1 H5 H0 H1)
                 A0 A2 A1 C2r H4 Hptv2 H7 Hpte2 Hd1). }
      assert (Hres2 : disjoint nil B C2r).
      { exact (IHHp1_2 e eq_refl
                 (e_anno (e_abs A e0) A2) (e_anno (e0 ^^ e2') C2r)
                 (PApp_abs A e0 A2 e e2' C2r C1 H5 H0 H1)
                 B0 A2 B C2r H6 Hptv2 H10 Hpte2 Hd2). }
      apply (D_andl nil (t_and A1 B) C2r A1 B).
      * apply Sp_and.
        -- apply (pType_lc_typ e1 A1 H7).
        -- apply (pType_lc_typ e2 B H10).
      * exact Hres1.
      * exact Hres2.
    + (* both merge *)
      inversion Hptv1; subst. inversion Hptv2; subst.
      inversion Hpte1; subst. inversion Hpte2; subst.
      destruct (papp_disjoint_and_r_inv nil (t_and A B) A0 B0 Hd) as [HdA HdB].
      destruct (papp_disjoint_and_l_inv nil A B A0 HdA) as [HdAA0 HdBA0].
      destruct (papp_disjoint_and_l_inv nil A B B0 HdB) as [HdAB0 HdBB0].
      assert (HresAA0 : disjoint nil A1 A2).
      { exact (IHHp1_1 e eq_refl v0 e0 Hp2x1 A A0 A1 A2 H1 H2 H4 H6 HdAA0). }
      assert (HresAB0 : disjoint nil A1 B2).
      { exact (IHHp1_1 e eq_refl v3 e3 Hp2x2 A B0 A1 B2 H1 H5 H4 H9 HdAB0). }
      assert (HresBA0 : disjoint nil B1 A2).
      { exact (IHHp1_2 e eq_refl v0 e0 Hp2x1 B A0 B1 A2 H3 H2 H7 H6 HdBA0). }
      assert (HresBB0 : disjoint nil B1 B2).
      { exact (IHHp1_2 e eq_refl v3 e3 Hp2x2 B B0 B1 B2 H3 H5 H7 H9 HdBB0). }
      apply (D_andl nil (t_and A1 B1) (t_and A2 B2) A1 B1).
      * apply Sp_and.
        -- apply (pType_lc_typ e1 A1 H4).
        -- apply (pType_lc_typ e2 B1 H7).
      * apply (D_andr nil A1 (t_and A2 B2) A2 B2).
        -- apply Sp_and.
           ++ apply (pType_lc_typ e0 A2 H6).
           ++ apply (pType_lc_typ e3 B2 H9).
        -- exact HresAA0.
        -- exact HresAB0.
      * apply (D_andr nil B1 (t_and A2 B2) A2 B2).
        -- apply Sp_and.
           ++ apply (pType_lc_typ e0 A2 H6).
           ++ apply (pType_lc_typ e3 B2 H9).
        -- exact HresBA0.
        -- exact HresBB0.
Qed.

Lemma arrow_consistent_disjoint : forall v1 e r1,
  papp v1 (arg_exp e) r1 ->
  forall v2 r2,
  papp v2 (arg_exp e) r2 ->
  forall A1 A2,
  Typing nil nil v1 Inf A1 ->
  Typing nil nil v2 Inf A2 ->
  disjoint nil A1 A2 ->
  consistent r1 r2.
Proof.
  intros v1 e r1 Hp1 v2 r2 Hp2 A1 A2 Ht1 Ht2 Hdis.
  destruct (papp_result_pType_prevalue_lc_exists v1 (arg_exp e) r1 Hp1) as [C1 Hrest1].
  destruct Hrest1 as [Hpt1 Hrest1]. destruct Hrest1 as [Hpv1 Hlc1].
  destruct (papp_result_pType_prevalue_lc_exists v2 (arg_exp e) r2 Hp2) as [C2 Hrest2].
  destruct Hrest2 as [Hpt2 Hrest2]. destruct Hrest2 as [Hpv2 Hlc2].
  pose proof (papp_source_pType v1 (arg_exp e) r1 Hp1 A1 Ht1) as Hptv1.
  pose proof (papp_source_pType v2 (arg_exp e) r2 Hp2 A2 Ht2) as Hptv2.
  apply (C_disjoint r1 r2 C1 C2 Hpt1 Hpt2).
  - exact (arrow_result_disjoint v1 e r1 Hp1 v2 r2 Hp2
             A1 A2 C1 C2 Hptv1 Hptv2 Hpt1 Hpt2 Hdis).
  - exact Hpv1.
  - exact Hpv2.
Qed.

Lemma papp_consistent_arrow_true : forall v1 v2 e e1 e2,
  papp v1 (arg_exp e) e1 ->
  papp v2 (arg_exp e) e2 ->
  forall A1 A2 B1 C1 B2 C2,
  Typing nil nil v1 Inf A1 ->
  Typing nil nil v2 Inf A2 ->
  consistent v1 v2 ->
  appDist A1 (t_arrow B1 C1) ->
  appDist A2 (t_arrow B2 C2) ->
  consistent e1 e2.
Proof.
  intros v1 v2 e e1 e2 Hp1.
  revert v2 e2.
  dependent induction Hp1.
  - (* v1 abs *)
    rename C1 into C1src. rename C2 into C2src. rename e into earg.
    intros v2x e2x Hp2x.
    dependent induction Hp2x.
    + (* v2 abs *)
      intros A1x A2x B1x C1x B2x C2x Ht1 Ht2 Hc Hd1 Hd2.
      inversion Hc; subst.
      * (* C_anno *)
        match goal with
        | Hw1 : wrapping earg A0 e2', Hw2 : wrapping earg A0 e2'0 |- _ =>
          assert (Hout : e2' = e2'0) by exact (papp_wrapping_functional earg A0 e2' e2'0 Hw1 Hw2);
          subst e2'0
        end.
        apply (C_anno (open_exp_wrt_exp e0 e2') C2src C2).
        -- apply (papp_lc_typ_arrow_cod_l B C1src C2src H0).
        -- apply (papp_lc_exp_open_exp_body e0 e2').
           ++ apply (proj2 (lc_exp_abs_inv A0 e0 H)).
           ++ apply (papp_wrapping_lc_output earg A0 e2' H1).
        -- apply (papp_lc_typ_arrow_cod_l B0 C1 C2 H3).
      * (* C_disjoint *)
        pose proof (PApp_abs A e1 B earg e2' C2src C1src H H0 H1) as HpA.
        pose proof (PApp_abs A0 e0 B0 earg e2'0 C2 C1 H2 H3 H4) as HpB.
        apply (arrow_consistent_disjoint (e_anno (e_abs A e1) B) earg
                 (e_anno (e1 ^^ e2') C2src) HpA
                 (e_anno (e_abs A0 e0) B0) (e_anno (e0 ^^ e2'0) C2) HpB
                 A1x A2x Ht1 Ht2).
        match goal with
        | Hd : disjoint nil ?P ?Q |- _ =>
          pose proof (papp_source_pType (e_anno (e_abs A e1) B) (arg_exp earg)
                        (e_anno (e1 ^^ e2') C2src) HpA A1x Ht1) as HP1;
          pose proof (papp_source_pType (e_anno (e_abs A0 e0) B0) (arg_exp earg)
                        (e_anno (e0 ^^ e2'0) C2) HpB A2x Ht2) as HP2;
          assert (P = A1x) by (eapply pType_det; eassumption);
          assert (Q = A2x) by (eapply pType_det; eassumption);
          subst P; subst Q; exact Hd
        end.
    + (* v2 merge *)
      intros A1x A2x B1x C1x B2x C2x Ht1 Ht2 Hc Hd1 Hd2.
      inversion Hc; subst.
      * (* C_disjoint *)
        pose proof (PApp_abs A e1 B earg e2' C2src C1src H H0 H1) as HpA.
        pose proof (PApp_merge v1 v2 (arg_exp earg) e0 e2 Hp2x1 Hp2x2) as HpB.
        apply (arrow_consistent_disjoint (e_anno (e_abs A e1) B) earg
                 (e_anno (e1 ^^ e2') C2src) HpA
                 (e_merge v1 v2) (e_merge e0 e2) HpB
                 A1x A2x Ht1 Ht2).
        match goal with
        | Hd : disjoint nil ?P ?Q |- _ =>
          pose proof (papp_source_pType (e_anno (e_abs A e1) B) (arg_exp earg)
                        (e_anno (e1 ^^ e2') C2src) HpA A1x Ht1) as HP1;
          pose proof (papp_source_pType (e_merge v1 v2) (arg_exp earg)
                        (e_merge e0 e2) HpB A2x Ht2) as HP2;
          assert (P = A1x) by (eapply pType_det; eassumption);
          assert (Q = A2x) by (eapply pType_det; eassumption);
          subst P; subst Q; exact Hd
        end.
      * (* C_merger *)
        destruct (merge_inf_components v1 v2 A2x Ht2) as [A2a Hrest].
        destruct Hrest as [A2b Hrest].
        destruct Hrest as [HeqA Hrest].
        destruct Hrest as [Hta Htb].
        subst A2x.
        inversion Hd2; subst.
        apply C_merger.
        -- eapply IHHp2x1; eauto 8.
        -- eapply IHHp2x2; eauto 8.
  - (* v1 merge *)
    rename e into earg.
    intros v3x e3x Hp2x.
    dependent induction Hp2x.
    + (* v2 abs *)
      intros A1x A2x B1x C1x B2x C2x Ht1 Ht2 Hc Hd1 Hd2.
      inversion Hc; subst.
      * (* C_disjoint *)
        apply (arrow_consistent_disjoint (e_merge v1 v2) earg (e_merge e1 e2)
                 (PApp_merge v1 v2 (arg_exp earg) e1 e2 Hp1_1 Hp1_2)
                 (e_anno (e_abs A e0) B) (e_anno (e0 ^^ e2') C2)
                 (PApp_abs A e0 B earg e2' C2 C1 H H0 H1)
                 A1x A2x Ht1 Ht2).
        match goal with
        | Hd : disjoint nil ?P ?Q |- _ =>
          pose proof (papp_source_pType (e_merge v1 v2) (arg_exp earg) (e_merge e1 e2)
                        (PApp_merge v1 v2 (arg_exp earg) e1 e2 Hp1_1 Hp1_2) A1x Ht1) as HP1;
          pose proof (papp_source_pType (e_anno (e_abs A e0) B) (arg_exp earg)
                        (e_anno (e0 ^^ e2') C2)
                        (PApp_abs A e0 B earg e2' C2 C1 H H0 H1) A2x Ht2) as HP2;
          assert (P = A1x) by (eapply pType_det; eassumption);
          assert (Q = A2x) by (eapply pType_det; eassumption);
          subst P; subst Q; exact Hd
        end.
      * (* C_mergel *)
        destruct (merge_inf_components v1 v2 A1x Ht1) as [A1a Hrest].
        destruct Hrest as [A1b Hrest].
        destruct Hrest as [HeqA Hrest].
        destruct Hrest as [Hta Htb].
        subst A1x.
        inversion Hd1; subst.
        apply C_mergel.
        -- eapply (IHHp1_1 earg eq_refl (e_anno (e_abs A e0) B)
                     (e_anno (e0 ^^ e2') C2)
                     (PApp_abs A e0 B earg e2' C2 C1 H H0 H1)); eauto 8.
        -- eapply (IHHp1_2 earg eq_refl (e_anno (e_abs A e0) B)
                     (e_anno (e0 ^^ e2') C2)
                     (PApp_abs A e0 B earg e2' C2 C1 H H0 H1)); eauto 8.
    + (* both merge *)
      intros A1x A2x B1x C1x B2x C2x Ht1 Ht2 Hc Hd1 Hd2.
      inversion Hc; subst.
      * (* C_disjoint *)
        apply (arrow_consistent_disjoint (e_merge v1 v2) earg (e_merge e1 e2)
                 (PApp_merge v1 v2 (arg_exp earg) e1 e2 Hp1_1 Hp1_2)
                 (e_merge v0 v3) (e_merge e0 e3)
                 (PApp_merge v0 v3 (arg_exp earg) e0 e3 Hp2x1 Hp2x2)
                 A1x A2x Ht1 Ht2).
        match goal with
        | Hd : disjoint nil ?P ?Q |- _ =>
          pose proof (papp_source_pType (e_merge v1 v2) (arg_exp earg) (e_merge e1 e2)
                        (PApp_merge v1 v2 (arg_exp earg) e1 e2 Hp1_1 Hp1_2) A1x Ht1) as HP1;
          pose proof (papp_source_pType (e_merge v0 v3) (arg_exp earg) (e_merge e0 e3)
                        (PApp_merge v0 v3 (arg_exp earg) e0 e3 Hp2x1 Hp2x2) A2x Ht2) as HP2;
          assert (P = A1x) by (eapply pType_det; eassumption);
          assert (Q = A2x) by (eapply pType_det; eassumption);
          subst P; subst Q; exact Hd
        end.
      * (* C_mergel *)
        destruct (merge_inf_components v1 v2 A1x Ht1) as [A1a Hrest].
        destruct Hrest as [A1b Hrest].
        destruct Hrest as [HeqA Hrest].
        destruct Hrest as [Hta Htb].
        subst A1x.
        inversion Hd1; subst.
        apply C_mergel.
        -- eapply (IHHp1_1 earg eq_refl (e_merge v0 v3) (e_merge e0 e3)
                     (PApp_merge v0 v3 (arg_exp earg) e0 e3 Hp2x1 Hp2x2)); eauto 8.
        -- eapply (IHHp1_2 earg eq_refl (e_merge v0 v3) (e_merge e0 e3)
                     (PApp_merge v0 v3 (arg_exp earg) e0 e3 Hp2x1 Hp2x2)); eauto 8.
      * (* C_merger *)
        destruct (merge_inf_components v0 v3 A2x Ht2) as [A2a Hrest].
        destruct Hrest as [A2b Hrest].
        destruct Hrest as [HeqA Hrest].
        destruct Hrest as [Hta Htb].
        subst A2x.
        inversion Hd2; subst.
        apply C_merger.
        -- apply (IHHp2x1 earg Hp1_1 Hp1_2 IHHp1_1 IHHp1_2 eq_refl
                    A1x A2a B1x C1x B1 C1 Ht1 Hta H2 Hd1 H4).
        -- apply (IHHp2x2 earg Hp1_1 Hp1_2 IHHp1_1 IHHp1_2 eq_refl
                    A1x A2b B1x C1x B2 C2 Ht1 Htb H3 Hd1 H6).
Qed.

Lemma papp_consistent_arrow :
  forall v1 v2 A1 A2 B1 C1 B2 C2 e e1 e2,
    Typing nil nil v1 Inf A1 ->
    Typing nil nil v2 Inf A2 ->
    consistent v1 v2 ->
    appDist A1 (t_arrow B1 C1) ->
    appDist A2 (t_arrow B2 C2) ->
    papp v1 (arg_exp e) e1 ->
    papp v2 (arg_exp e) e2 ->
    consistent e1 e2.
Proof.
  intros v1 v2 A1 A2 B1 C1 B2 C2 e e1 e2
    Ht1 Ht2 Hc Hd1 Hd2 Hp1 Hp2.
  exact (papp_consistent_arrow_true v1 v2 e e1 e2 Hp1 Hp2
           A1 A2 B1 C1 B2 C2 Ht1 Ht2 Hc Hd1 Hd2).
Qed.

Lemma rcd_source_pType : forall v l e,
  papp v (arg_la l) e ->
  forall A, Typing nil nil v Inf A -> pType v A.
Proof.
  intros v l e Hp.
  dependent induction Hp.
  - (* PApp_proj *)
    intros Aty Hty.
    inversion Hty; subst.
    apply PT_anno.
    + apply lc_e_rcd. exact H.
    + apply (proj1 (appDist_lc Aty (t_rcd l B) H0)).
  - (* PApp_merge *)
    intros Aty Hty.
    inversion Hty; subst.
    + apply PT_merge.
      * apply (IHHp1 l eq_refl). assumption.
      * apply (IHHp2 l eq_refl). assumption.
    + apply PT_merge.
      * apply (IHHp1 l eq_refl). assumption.
      * apply (IHHp2 l eq_refl). assumption.
Qed.

Lemma rcd_result_pType_prevalue_lc_exists : forall v l e,
  papp v (arg_la l) e ->
  exists C, pType e C /\ prevalue e /\ lc_exp e.
Proof.
  intros v l e Hp.
  dependent induction Hp.
  - exists B. repeat split.
    + apply PT_anno.
      * exact H.
      * apply (papp_lc_typ_rcd_cod A l B H0).
    + apply PV_anno.
      * exact H.
      * apply (papp_lc_typ_rcd_cod A l B H0).
    + apply lc_e_anno.
      * exact H.
      * apply (papp_lc_typ_rcd_cod A l B H0).
  - destruct (IHHp1 l eq_refl) as [C1 X1].
    destruct X1 as [Hpt1 X1].
    destruct X1 as [Hpv1 Hlc1].
    destruct (IHHp2 l eq_refl) as [C2 X2].
    destruct X2 as [Hpt2 X2].
    destruct X2 as [Hpv2 Hlc2].
    exists (t_and C1 C2). repeat split.
    + apply PT_merge; assumption.
    + apply PV_merge; assumption.
    + apply lc_e_merge; assumption.
Qed.


Lemma proj_vs_result_disjoint : forall A l B,
  appDist A (t_rcd l B) ->
  forall v2 l2 e2 A2 C2,
  papp v2 (arg_la l2) e2 ->
  pType v2 A2 -> pType e2 C2 ->
  l = l2 -> disjoint nil A A2 -> disjoint nil B C2.
Proof.
  intros A l B Hdist v2 l2 e2 A2 C2 Hp.
  revert A2 C2.
  dependent induction Hp.
  - (* proj *)
    intros A2 C2 Hptv Hpte Heq Hdis.
    inversion Hptv; subst.
    inversion Hpte; subst.
    apply (appDist_rcd_cod_disjoint A A2 l2 B C2 Hdis Hdist H0).
  - (* merge *)
    intros A2 C2 Hptv Hpte Heq Hdis.
    inversion Hptv; subst.
    inversion Hpte; subst.
    destruct (papp_disjoint_and_r_inv nil A A0 B0 Hdis) as [Hd1 Hd2].
    apply (D_andr nil B (t_and A1 B1) A1 B1).
    + apply Sp_and; [eapply pType_lc_typ; eassumption | eapply pType_lc_typ; eassumption].
    + apply (IHHp1 Hdist l2 eq_refl A0 A1 H1 H2 eq_refl Hd1).
    + apply (IHHp2 Hdist l2 eq_refl B0 B1 H3 H5 eq_refl Hd2).
Qed.

Lemma rcd_result_disjoint : forall v1 l e1,
  papp v1 (arg_la l) e1 ->
  forall v2 e2,
  papp v2 (arg_la l) e2 ->
  forall A1 A2 C1 C2,
  pType v1 A1 -> pType v2 A2 ->
  pType e1 C1 -> pType e2 C2 ->
  disjoint nil A1 A2 -> disjoint nil C1 C2.
Proof.
  intros v1 l e1 Hp1.
  dependent induction Hp1.
  - (* v1 proj *)
    intros v2 e2 Hp2 A1 A2 C1 C2 Hptv1 Hptv2 Hpte1 Hpte2 Hdis.
    inversion Hptv1; subst.
    inversion Hpte1; subst.
    apply (proj_vs_result_disjoint A1 l C1 H0 v2 l e2 A2 C2 Hp2 Hptv2 Hpte2 eq_refl Hdis).
  - (* v1 merge *)
    intros v2x e2x Hp2x A1 A2 C1 C2 Hptv1 Hptv2 Hpte1 Hpte2 Hdis.
    inversion Hptv1; subst.
    inversion Hpte1; subst.
    destruct (papp_disjoint_and_l_inv nil A B A2 Hdis) as [Hd1 Hd2].
    apply (D_andl nil (t_and A0 B0) C2 A0 B0).
    + apply Sp_and; [eapply pType_lc_typ; eassumption | eapply pType_lc_typ; eassumption].
    + apply (IHHp1_1 l eq_refl v2x e2x Hp2x A A2 A0 C2 H1 Hptv2 H2 Hpte2 Hd1).
    + apply (IHHp1_2 l eq_refl v2x e2x Hp2x B A2 B0 C2 H3 Hptv2 H5 Hpte2 Hd2).
Qed.

Lemma rcd_consistent_disjoint : forall v1 l e1,
  papp v1 (arg_la l) e1 ->
  forall v2 e2,
  papp v2 (arg_la l) e2 ->
  forall A1 A2,
  Typing nil nil v1 Inf A1 ->
  Typing nil nil v2 Inf A2 ->
  disjoint nil A1 A2 ->
  consistent e1 e2.
Proof.
  intros v1 l e1 Hp1 v2 e2 Hp2 A1 A2 Ht1 Ht2 Hdis.
  destruct (rcd_result_pType_prevalue_lc_exists v1 l e1 Hp1) as [C1 X1].
  destruct X1 as [Hpt1 X1].
  destruct X1 as [Hpv1 Hlc1].
  destruct (rcd_result_pType_prevalue_lc_exists v2 l e2 Hp2) as [C2 X2].
  destruct X2 as [Hpt2 X2].
  destruct X2 as [Hpv2 Hlc2].
  pose proof (rcd_source_pType v1 l e1 Hp1 A1 Ht1) as Hptv1.
  pose proof (rcd_source_pType v2 l e2 Hp2 A2 Ht2) as Hptv2.
  apply (C_disjoint e1 e2 C1 C2 Hpt1 Hpt2).
  - apply (rcd_result_disjoint v1 l e1 Hp1 v2 e2 Hp2
             A1 A2 C1 C2 Hptv1 Hptv2 Hpt1 Hpt2 Hdis).
  - exact Hpv1.
  - exact Hpv2.
Qed.

Lemma papp_consistent_rcd : forall v1 l e1,
  papp v1 (arg_la l) e1 ->
  forall v2 e2,
  papp v2 (arg_la l) e2 ->
  forall A1 A2,
  Typing nil nil v1 Inf A1 ->
  Typing nil nil v2 Inf A2 ->
  consistent v1 v2 -> consistent e1 e2.
Proof.
  intros v1 l e1 Hp1.
  dependent induction Hp1.
  - (* v1 proj *)
    intros v2 e2 Hp2.
    dependent induction Hp2.
    + (* both proj *)
      intros A1 A2 Ht1 Ht2 Hc.
      inversion Hc; subst.
      * (* C_anno *)
        apply C_anno.
        -- apply (papp_lc_typ_rcd_cod A l B H0).
        -- exact H.
        -- apply (papp_lc_typ_rcd_cod A0 l B0 H2).
      * (* C_disjoint *)
        pose proof (rcd_source_pType (e_anno (e_rcd l e) A) l (e_anno e B)
                      (PApp_proj l e A B H H0) A1 Ht1) as Hptv1.
        pose proof (rcd_source_pType (e_anno (e_rcd l e0) A0) l (e_anno e0 B0)
                      (PApp_proj l e0 A0 B0 H1 H2) A2 Ht2) as Hptv2.
        assert (HA : A3 = A1) by (eapply pType_det; eassumption).
        assert (HB : B1 = A2) by (eapply pType_det; eassumption).
        subst A3. subst B1.
        apply (rcd_consistent_disjoint (e_anno (e_rcd l e) A) l (e_anno e B)
                 (PApp_proj l e A B H H0)
                 (e_anno (e_rcd l e0) A0) (e_anno e0 B0)
                 (PApp_proj l e0 A0 B0 H1 H2) A1 A2 Ht1 Ht2 H5).
    + (* v2 merge *)
      intros A1 A2 Ht1 Ht2 Hc.
      inversion Hc; subst.
      * (* C_disjoint *)
        pose proof (rcd_source_pType (e_anno (e_rcd l e) A) l (e_anno e B)
                      (PApp_proj l e A B H H0) A1 Ht1) as Hptv1.
        pose proof (rcd_source_pType (e_merge v1 v2) l (e_merge e1 e2)
                      (PApp_merge v1 v2 (arg_la l) e1 e2 Hp2_1 Hp2_2)
                      A2 Ht2) as Hptv2.
        assert (HA : A0 = A1) by (eapply pType_det; eassumption).
        assert (HB : B0 = A2) by (eapply pType_det; eassumption).
        subst A0. subst B0.
        apply (rcd_consistent_disjoint (e_anno (e_rcd l e) A) l (e_anno e B)
                 (PApp_proj l e A B H H0)
                 (e_merge v1 v2) (e_merge e1 e2)
                 (PApp_merge v1 v2 (arg_la l) e1 e2 Hp2_1 Hp2_2)
                 A1 A2 Ht1 Ht2 H3).
      * (* C_merger *)
        destruct (merge_inf_components v1 v2 A2 Ht2) as [A2a X].
        destruct X as [A2b X].
        destruct X as [HeqA X].
        destruct X as [Hta Htb].
        apply C_merger.
        -- apply (IHHp2_1 l H H0 eq_refl A1 A2a Ht1 Hta H4).
        -- apply (IHHp2_2 l H H0 eq_refl A1 A2b Ht1 Htb H5).
  - (* v1 merge *)
    intros v2x e2x Hp2x.
    dependent induction Hp2x.
    + (* v2 proj *)
      intros A1 A2 Ht1 Ht2 Hc.
      inversion Hc; subst.
      * (* C_disjoint *)
        pose proof (rcd_source_pType (e_merge v1 v2) l (e_merge e1 e2)
                      (PApp_merge v1 v2 (arg_la l) e1 e2 Hp1_1 Hp1_2)
                      A1 Ht1) as Hptv1.
        pose proof (rcd_source_pType (e_anno (e_rcd l e) A) l (e_anno e B)
                      (PApp_proj l e A B H H0) A2 Ht2) as Hptv2.
        assert (HA : A0 = A1) by (eapply pType_det; eassumption).
        assert (HB : B0 = A2) by (eapply pType_det; eassumption).
        subst A0. subst B0.
        apply (rcd_consistent_disjoint (e_merge v1 v2) l (e_merge e1 e2)
                 (PApp_merge v1 v2 (arg_la l) e1 e2 Hp1_1 Hp1_2)
                 (e_anno (e_rcd l e) A) (e_anno e B)
                 (PApp_proj l e A B H H0) A1 A2 Ht1 Ht2 H3).
      * (* C_mergel *)
        destruct (merge_inf_components v1 v2 A1 Ht1) as [A1a X].
        destruct X as [A1b X].
        destruct X as [HeqA X].
        destruct X as [Hta Htb].
        apply C_mergel.
        -- apply (IHHp1_1 l eq_refl (e_anno (e_rcd l e) A) (e_anno e B)
                    (PApp_proj l e A B H H0) A1a A2 Hta Ht2 H3).
        -- apply (IHHp1_2 l eq_refl (e_anno (e_rcd l e) A) (e_anno e B)
                    (PApp_proj l e A B H H0) A1b A2 Htb Ht2 H5).
    + (* both merge *)
      intros A1 A2 Ht1 Ht2 Hc.
      inversion Hc; subst.
      * (* C_disjoint *)
        pose proof (rcd_source_pType (e_merge v1 v2) l (e_merge e1 e2)
                      (PApp_merge v1 v2 (arg_la l) e1 e2 Hp1_1 Hp1_2)
                      A1 Ht1) as Hptv1.
        pose proof (rcd_source_pType (e_merge v0 v3) l (e_merge e0 e3)
                      (PApp_merge v0 v3 (arg_la l) e0 e3 Hp2x1 Hp2x2)
                      A2 Ht2) as Hptv2.
        assert (HA : A = A1) by (eapply pType_det; eassumption).
        assert (HB : B = A2) by (eapply pType_det; eassumption).
        subst A. subst B.
        apply (rcd_consistent_disjoint (e_merge v1 v2) l (e_merge e1 e2)
                 (PApp_merge v1 v2 (arg_la l) e1 e2 Hp1_1 Hp1_2)
                 (e_merge v0 v3) (e_merge e0 e3)
                 (PApp_merge v0 v3 (arg_la l) e0 e3 Hp2x1 Hp2x2)
                 A1 A2 Ht1 Ht2 H1).
      * (* C_mergel *)
        destruct (merge_inf_components v1 v2 A1 Ht1) as [A1a X].
        destruct X as [A1b X].
        destruct X as [HeqA X].
        destruct X as [Hta Htb].
        apply C_mergel.
        -- apply (IHHp1_1 l eq_refl (e_merge v0 v3) (e_merge e0 e3)
                    (PApp_merge v0 v3 (arg_la l) e0 e3 Hp2x1 Hp2x2)
                    A1a A2 Hta Ht2 H1).
        -- apply (IHHp1_2 l eq_refl (e_merge v0 v3) (e_merge e0 e3)
                    (PApp_merge v0 v3 (arg_la l) e0 e3 Hp2x1 Hp2x2)
                    A1b A2 Htb Ht2 H3).
      * (* C_merger *)
        destruct (merge_inf_components v0 v3 A2 Ht2) as [A2a X].
        destruct X as [A2b X].
        destruct X as [HeqA X].
        destruct X as [Hta Htb].
        apply C_merger.
        -- apply (IHHp2x1 l Hp1_1 Hp1_2 IHHp1_1 IHHp1_2 eq_refl
                    A1 A2a Ht1 Hta H2).
        -- apply (IHHp2x2 l Hp1_1 Hp1_2 IHHp1_1 IHHp1_2 eq_refl
                    A1 A2b Ht1 Htb H3).
Qed.

Lemma all_result_disjoint : forall v1 C r1,
  papp v1 (arg_typ C) r1 ->
  forall v2 r2,
  papp v2 (arg_typ C) r2 ->
  forall A1 A2 B1 C1 B2 C2 P1 P2,
  pType v1 A1 -> pType v2 A2 ->
  appDist A1 (t_forall B1 C1) ->
  appDist A2 (t_forall B2 C2) ->
  disjoint nil A1 A2 ->
  disjoint nil C B1 -> disjoint nil C B2 ->
  pType r1 P1 -> pType r2 P2 ->
  disjoint nil P1 P2.
Proof.
  intros v1 C r1 Hp1.
  dependent induction Hp1.
  - (* v1 tabs *)
    intros v2 r2 Hp2x A1 A2 B0 C1 B3 C2 P1 P2
      Hptv1 Hptv2 Hd1 Hd2 HdA Hdis1 Hdis2 Hptr1 Hptr2.
    inversion Hptv1; subst.
    inversion Hptr1; subst.
    destruct (appDist_all_unique A1 B0 C1 B1 B2 Hd1 H1) as [EB EC].
    subst B0. subst C1.
    dependent induction Hp2x.
    + (* v2 tabs *)
      inversion Hptv2; subst.
      inversion Hptr2; subst.
      destruct (appDist_all_unique A2 B4 C2 B3 B0 Hd2 H2) as [EB4 EC2].
      subst B4. subst C2.
      apply (appDist_all_cod_disjoint_open_nil A1 A2 B1 B2 B3 B0 C
               HdA Hd1 Hd2 Hdis1 Hdis2).
    + (* v2 merge *)
      inversion Hptv2; subst.
      inversion Hd2; subst.
      inversion Hptr2; subst.
      destruct (papp_disjoint_and_r_inv nil A1 A B HdA) as [HdAa HdAb].
      destruct (papp_disjoint_and_r_inv nil C B0 B4 Hdis2) as [Hdis2a Hdis2b].
      assert (Hr1 : disjoint nil (open_typ_wrt_typ B2 C) A0).
      { exact (IHHp2x1 H1 H C H0 eq_refl A B0 C1 A0
                 Hptv1 H7 Hd1 H11 HdAa Hdis1 Hdis2a Hptr1 H9 H H6 H5 H8). }
      assert (Hr2 : disjoint nil (open_typ_wrt_typ B2 C) B3).
      { exact (IHHp2x2 H1 H C H0 eq_refl B B4 C0 B3
                 Hptv1 H10 Hd1 H13 HdAb Hdis1 Hdis2b Hptr1 H14 H H6 H5 H8). }
      apply (D_andr nil (open_typ_wrt_typ B2 C)
              (t_and A0 B3) A0 B3).
      * apply Sp_and.
        -- apply (pType_lc_typ e1 A0 H9).
        -- apply (pType_lc_typ e2 B3 H14).
      * exact Hr1.
      * exact Hr2.
  - (* v1 merge *)
    intros v0 r2 Hp2x A1 A2 B1 C1 B2 C2 P1 P2
      Hptv1 Hptv2 Hd1 Hd2 HdA Hdis1 Hdis2 Hptr1 Hptr2.
    inversion Hptv1; subst.
    inversion Hptr1; subst.
    dependent induction Hp2x.
    + (* v2 tabs *)
      inversion Hptv2; subst.
      inversion Hptr2; subst.
      destruct (appDist_all_unique A2 B3 C2 B1 B2 Hd2 H1) as [EB3 EC2].
      subst B3. subst C2.
      inversion Hd1; subst.
      destruct (papp_disjoint_and_l_inv nil A0 B A2 HdA) as [HdAa HdAb].
      destruct (papp_disjoint_and_r_inv nil C B3 B5 Hdis1) as [Hdis1a Hdis1b].
      assert (Hr1 : disjoint nil A1 (B2 ^-^ C)).
      { exact (IHHp1_1 C eq_refl (e_anno (e_tabs e) A2)
                 (e_anno (open_exp_wrt_typ e C) (B2 ^-^ C))
                 (PApp_tabs e A2 C B2 B1 H H0 H1)
                 A0 A2 B3 C0 B1 B2 A1 (B2 ^-^ C)
                 H2 Hptv2 H13 H1 HdAa Hdis1a Hdis2 H4 Hptr2). }
      assert (Hr2 : disjoint nil B4 (B2 ^-^ C)).
      { exact (IHHp1_2 C eq_refl (e_anno (e_tabs e) A2)
                 (e_anno (open_exp_wrt_typ e C) (B2 ^-^ C))
                 (PApp_tabs e A2 C B2 B1 H H0 H1)
                 B A2 B5 C2 B1 B2 B4 (B2 ^-^ C)
                 H3 Hptv2 H15 H1 HdAb Hdis1b Hdis2 H5 Hptr2). }
      apply (D_andl nil (t_and A1 B4) (B2 ^-^ C) A1 B4).
      * apply Sp_and.
        -- apply (pType_lc_typ e1 A1 H4).
        -- apply (pType_lc_typ e2 B4 H5).
      * exact Hr1.
      * exact Hr2.
    + (* v2 merge *)
      inversion Hptv2; subst.
      inversion Hd2; subst.
      inversion Hptr2; subst.
      inversion Hd1; subst.
      destruct (papp_disjoint_and_l_inv nil A B (A1 & B3) HdA) as [HdAa HdAb].
      destruct (papp_disjoint_and_r_inv nil C B6 B7 Hdis1) as [Hdis1a Hdis1b].
      assert (Hr1 : disjoint nil A0 (A2 & B2)).
      { exact (IHHp1_1 C eq_refl (e_merge v0 v3) (e_merge e0 e3)
                 (PApp_merge v0 v3 (arg_typ C) e0 e3 Hp2x1 Hp2x2)
                 A (A1 & B3) B6 C2 (B4 & B5) (C0 & C3) A0 (A2 & B2)
                 H1 Hptv2 H12 Hd2 HdAa Hdis1a Hdis2 H2 Hptr2). }
      assert (Hr2 : disjoint nil B0 (A2 & B2)).
      { exact (IHHp1_2 C eq_refl (e_merge v0 v3) (e_merge e0 e3)
                 (PApp_merge v0 v3 (arg_typ C) e0 e3 Hp2x1 Hp2x2)
                 B (A1 & B3) B7 C4 (B4 & B5) (C0 & C3) B0 (A2 & B2)
                 H3 Hptv2 H14 Hd2 HdAb Hdis1b Hdis2 H5 Hptr2). }
      apply (D_andl nil (A0 & B0) (A2 & B2) A0 B0).
      * apply Sp_and.
        -- apply (pType_lc_typ e1 A0 H2).
        -- apply (pType_lc_typ e2 B0 H5).
      * exact Hr1.
      * exact Hr2.
Qed.

Lemma all_consistent_disjoint : forall v1 v2 C r1 r2,
  papp v1 (arg_typ C) r1 ->
  papp v2 (arg_typ C) r2 ->
  forall A1 A2 B1 C1 B2 C2,
  Typing nil nil v1 Inf A1 ->
  Typing nil nil v2 Inf A2 ->
  appDist A1 (t_forall B1 C1) ->
  appDist A2 (t_forall B2 C2) ->
  disjoint nil A1 A2 ->
  disjoint nil C B1 -> disjoint nil C B2 ->
  consistent r1 r2.
Proof.
  intros v1 v2 C r1 r2 Hp1 Hp2 A1 A2 B1 C1 B2 C2
    Ht1 Ht2 Hd1 Hd2 HdA Hdis1 Hdis2.
  destruct (papp_result_pType_prevalue_lc_exists v1 (arg_typ C) r1 Hp1)
    as (P1 & Hptr1 & Hpv1 & Hlc1).
  destruct (papp_result_pType_prevalue_lc_exists v2 (arg_typ C) r2 Hp2)
    as (P2 & Hptr2 & Hpv2 & Hlc2).
  apply (C_disjoint r1 r2 P1 P2).
  - exact Hptr1.
  - exact Hptr2.
  - apply (all_result_disjoint v1 C r1 Hp1 v2 r2 Hp2 A1 A2 B1 C1 B2 C2 P1 P2).
    + apply (papp_source_pType v1 (arg_typ C) r1 Hp1 A1 Ht1).
    + apply (papp_source_pType v2 (arg_typ C) r2 Hp2 A2 Ht2).
    + exact Hd1.
    + exact Hd2.
    + exact HdA.
    + exact Hdis1.
    + exact Hdis2.
    + exact Hptr1.
    + exact Hptr2.
  - exact Hpv1.
  - exact Hpv2.
Qed.

Lemma papp_consistent_all_gen : forall v1 v2 C e1 e2,
  papp v1 (arg_typ C) e1 -> papp v2 (arg_typ C) e2 ->
  forall A1 A2 B1 C1 B2 C2,
  Typing nil nil v1 Inf A1 -> Typing nil nil v2 Inf A2 ->
  consistent v1 v2 ->
  appDist A1 (t_forall B1 C1) -> appDist A2 (t_forall B2 C2) ->
  disjoint nil C B1 -> disjoint nil C B2 -> consistent e1 e2.
Proof.
  intros v1 v2 C e1 e2 Hp1.
  revert v2 e2.
  dependent induction Hp1.
  - (* v1 tabs *)
    rename e into et. rename A into Asrc.
    rename B1 into Bdom. rename B2 into Bcod.
    intros v2x e2x Hp2x.
    dependent induction Hp2x.
    + (* v2 tabs *)
      rename e into et2. rename A into Asrc2.
      rename B1 into Bdom2. rename B2 into Bcod2.
      intros A1 A2 B0 C1 B3 C2 Ht1 Ht2 Hc Hd1 Hd2 Hdis1 Hdis2.
      inversion Hc; subst.
      * (* C_anno *)
        apply (C_anno (open_exp_wrt_typ et2 C) (Bcod ^-^ C) (Bcod2 ^-^ C)).
        -- exact (papp_lc_typ_all_cod_open Bdom Bcod C
                    (proj2 (appDist_lc Asrc (t_forall Bdom Bcod) H1)) H0).
        -- apply (papp_lc_exp_open_exp_typ_body et2 C).
           ++ apply (papp_lc_exp_tabs_inv et2 H).
           ++ exact H0.
        -- exact (papp_lc_typ_all_cod_open Bdom2 Bcod2 C
                    (proj2 (appDist_lc Asrc2 (t_forall Bdom2 Bcod2) H2)) H0).
      * (* C_disjoint *)
        assert (HA1 : A1 = A).
        { exact (pType_det _ A1 A
                   (papp_source_pType (e_anno (e_tabs et) Asrc) (arg_typ C)
                      (e_anno (open_exp_wrt_typ et C) (Bcod ^-^ C))
                      (PApp_tabs et Asrc C Bcod Bdom H H0 H1) A1 Ht1) H5). }
        assert (HA2 : A2 = B).
        { exact (pType_det _ A2 B
                   (papp_source_pType (e_anno (e_tabs et2) Asrc2) (arg_typ C)
                      (e_anno (open_exp_wrt_typ et2 C) (Bcod2 ^-^ C))
                      (PApp_tabs et2 Asrc2 C Bcod2 Bdom2 H3 H4 H2) A2 Ht2) H6). }
        subst A1. subst A2.
        apply (all_consistent_disjoint (e_anno (e_tabs et) Asrc)
                 (e_anno (e_tabs et2) Asrc2) C
                 (e_anno (open_exp_wrt_typ et C) (Bcod ^-^ C))
                 (e_anno (open_exp_wrt_typ et2 C) (Bcod2 ^-^ C))
                 (PApp_tabs et Asrc C Bcod Bdom H H0 H1)
                 (PApp_tabs et2 Asrc2 C Bcod2 Bdom2 H3 H4 H2)
                 A B B0 C1 B3 C2 Ht1 Ht2 Hd1 Hd2 H7 Hdis1 Hdis2).
    + (* v2 merge *)
      intros A1 A2 B1 C1 B2 C2 Ht1 Ht2 Hc Hd1 Hd2 Hdis1 Hdis2.
      inversion Hc; subst.
      * (* C_disjoint *)
        assert (HA1 : A1 = A).
        { exact (pType_det _ A1 A
                   (papp_source_pType (e_anno (e_tabs et) Asrc) (arg_typ C)
                      (e_anno (open_exp_wrt_typ et C) (Bcod ^-^ C))
                      (PApp_tabs et Asrc C Bcod Bdom H H0 H1) A1 Ht1) H2). }
        assert (HA2 : A2 = B).
        { exact (pType_det _ A2 B
                   (papp_source_pType (e_merge v1 v2) (arg_typ C)
                      (e_merge e1 e2)
                      (PApp_merge v1 v2 (arg_typ C) e1 e2 Hp2x1 Hp2x2) A2 Ht2) H3). }
        subst A1. subst A2.
        apply (all_consistent_disjoint (e_anno (e_tabs et) Asrc)
                 (e_merge v1 v2) C
                 (e_anno (open_exp_wrt_typ et C) (Bcod ^-^ C))
                 (e_merge e1 e2)
                 (PApp_tabs et Asrc C Bcod Bdom H H0 H1)
                 (PApp_merge v1 v2 (arg_typ C) e1 e2 Hp2x1 Hp2x2)
                 A B B1 C1 B2 C2 Ht1 Ht2 Hd1 Hd2 H4 Hdis1 Hdis2).
      * (* C_merger *)
        destruct (merge_inf_components v1 v2 A2 Ht2) as
          (A2a & A2b & Heq & Hta & Htb).
        subst A2.
        inversion Hd2; subst.
        destruct (papp_disjoint_and_r_inv nil C B0 B3 Hdis2) as [Hdis2a Hdis2b].
        apply C_merger.
        -- apply (IHHp2x1 H1 H C H0 eq_refl A1 A2a B1 C1 B0 C0
                    Ht1 Hta H5 Hd1 H7 Hdis1 Hdis2a).
        -- apply (IHHp2x2 H1 H C H0 eq_refl A1 A2b B1 C1 B3 C3
                    Ht1 Htb H6 Hd1 H9 Hdis1 Hdis2b).
  - (* v1 merge *)
    intros v2x e2x Hp2x.
    dependent induction Hp2x.
    + (* v2 tabs *)
      intros A1 A2 B0 C1 B3 C2 Ht1 Ht2 Hc Hd1 Hd2 Hdis1 Hdis2.
      inversion Hc; subst.
      * (* C_disjoint *)
        assert (HA1 : A1 = A0).
        { exact (pType_det _ A1 A0
                   (papp_source_pType (e_merge v1 v2) (arg_typ C)
                      (e_merge e1 e2)
                      (PApp_merge v1 v2 (arg_typ C) e1 e2 Hp1_1 Hp1_2) A1 Ht1) H2). }
        assert (HA2 : A2 = B).
        { exact (pType_det _ A2 B
                   (papp_source_pType (e_anno (e_tabs e) A) (arg_typ C)
                      (e_anno (open_exp_wrt_typ e C) (B2 ^-^ C))
                      (PApp_tabs e A C B2 B1 H H0 H1) A2 Ht2) H3). }
        subst A1. subst A2.
        apply (all_consistent_disjoint (e_merge v1 v2)
                 (e_anno (e_tabs e) A) C
                 (e_merge e1 e2)
                 (e_anno (open_exp_wrt_typ e C) (B2 ^-^ C))
                 (PApp_merge v1 v2 (arg_typ C) e1 e2 Hp1_1 Hp1_2)
                 (PApp_tabs e A C B2 B1 H H0 H1)
                 A0 B B0 C1 B3 C2 Ht1 Ht2 Hd1 Hd2 H4 Hdis1 Hdis2).
      * (* C_mergel *)
        destruct (merge_inf_components v1 v2 A1 Ht1) as
          (A1a & A1b & Heq & Hta & Htb).
        subst A1.
        inversion Hd1; subst.
        destruct (papp_disjoint_and_r_inv nil C B4 B5 Hdis1) as [Hdis1a Hdis1b].
        apply C_mergel.
        -- apply (IHHp1_1 C eq_refl (e_anno (e_tabs e) A)
                    (e_anno (open_exp_wrt_typ e C) (B2 ^-^ C))
                    (PApp_tabs e A C B2 B1 H H0 H1)
                    A1a A2 B4 C0 B3 C2 Hta Ht2 H4 H7 Hd2 Hdis1a Hdis2).
        -- apply (IHHp1_2 C eq_refl (e_anno (e_tabs e) A)
                    (e_anno (open_exp_wrt_typ e C) (B2 ^-^ C))
                    (PApp_tabs e A C B2 B1 H H0 H1)
                    A1b A2 B5 C3 B3 C2 Htb Ht2 H6 H9 Hd2 Hdis1b Hdis2).
    + (* v2 merge *)
      intros A1 A2 B1 C1 B2 C2 Ht1 Ht2 Hc Hd1 Hd2 Hdis1 Hdis2.
      inversion Hc; subst.
      * (* C_disjoint *)
        assert (HA1 : A1 = A).
        { exact (pType_det _ A1 A
                   (papp_source_pType (e_merge v1 v2) (arg_typ C)
                      (e_merge e1 e2)
                      (PApp_merge v1 v2 (arg_typ C) e1 e2 Hp1_1 Hp1_2) A1 Ht1) H). }
        assert (HA2 : A2 = B).
        { exact (pType_det _ A2 B
                   (papp_source_pType (e_merge v0 v3) (arg_typ C)
                      (e_merge e0 e3)
                      (PApp_merge v0 v3 (arg_typ C) e0 e3 Hp2x1 Hp2x2) A2 Ht2) H0). }
        subst A1. subst A2.
        apply (all_consistent_disjoint (e_merge v1 v2) (e_merge v0 v3) C
                 (e_merge e1 e2) (e_merge e0 e3)
                 (PApp_merge v1 v2 (arg_typ C) e1 e2 Hp1_1 Hp1_2)
                 (PApp_merge v0 v3 (arg_typ C) e0 e3 Hp2x1 Hp2x2)
                 A B B1 C1 B2 C2 Ht1 Ht2 Hd1 Hd2 H1 Hdis1 Hdis2).
      * (* C_mergel *)
        destruct (merge_inf_components v1 v2 A1 Ht1) as
          (A1a & A1b & Heq & Hta & Htb).
        subst A1.
        inversion Hd1; subst.
        destruct (papp_disjoint_and_r_inv nil C B0 B3 Hdis1) as [Hdis1a Hdis1b].
        apply C_mergel.
        -- apply (IHHp1_1 C eq_refl (e_merge v0 v3) (e_merge e0 e3)
                    (PApp_merge v0 v3 (arg_typ C) e0 e3 Hp2x1 Hp2x2)
                    A1a A2 B0 C0 B2 C2 Hta Ht2 H1 H4 Hd2 Hdis1a Hdis2).
        -- apply (IHHp1_2 C eq_refl (e_merge v0 v3) (e_merge e0 e3)
                    (PApp_merge v0 v3 (arg_typ C) e0 e3 Hp2x1 Hp2x2)
                    A1b A2 B3 C3 B2 C2 Htb Ht2 H3 H6 Hd2 Hdis1b Hdis2).
      * (* C_merger *)
        destruct (merge_inf_components v0 v3 A2 Ht2) as
          (A2a & A2b & Heq & Hta & Htb).
        subst A2.
        inversion Hd2; subst.
        destruct (papp_disjoint_and_r_inv nil C B0 B3 Hdis2) as [Hdis2a Hdis2b].
        apply C_merger.
        -- eapply IHHp2x1; eauto 8.
        -- eapply IHHp2x2; eauto 8.
Qed.
Lemma papp_consistent_all :
  forall v1 v2 A1 A2 B1 C1 B2 C2 C e1 e2,
    Typing nil nil v1 Inf A1 ->
    Typing nil nil v2 Inf A2 ->
    consistent v1 v2 ->
    appDist A1 (t_forall B1 C1) ->
    appDist A2 (t_forall B2 C2) ->
    disjoint nil C B1 ->
    disjoint nil C B2 ->
    papp v1 (arg_typ C) e1 ->
    papp v2 (arg_typ C) e2 ->
    consistent e1 e2.
Proof.
  intros v1 v2 A1 A2 B1 C1 B2 C2 C e1 e2
    Ht1 Ht2 Hc Hd1 Hd2 Hdis1 Hdis2 Hp1 Hp2.
  exact (papp_consistent_all_gen v1 v2 C e1 e2 Hp1 Hp2
           A1 A2 B1 C1 B2 C2 Ht1 Ht2 Hc Hd1 Hd2 Hdis1 Hdis2).
Qed.

Lemma papp_typing_app : forall v e2 r,
  papp v (arg_exp e2) r ->
  forall A B C,
    Typing nil nil v Inf A ->
    appDist A (t_arrow B C) ->
    Typing nil nil e2 Chk B ->
    exists C', Typing nil nil r Inf C' /\ subsub C' C.
Proof.
  intros v e2 r Hpapp.
  dependent induction Hpapp; intros AT BT CT Hty Happ Harg; try discriminate.
  - (* PApp_abs *)
    inversion Hty; subst.
    destruct (appDist_arrow_unique AT C1 C2 BT CT H0 Happ) as [E1 E2]; subst.
    destruct (papp_abs_arg_inf A e1 AT e2 e2' BT CT H5 H0 H1 Harg)
      as [P [HtyP [HsubP HTWP] ] ].
    destruct (papp_abs_chk_appDist_body A e1 AT H5 BT CT H0) as [L HL].
    destruct (atom_fresh (L \u termfv_exp e1)) as [x Hx].
    assert (HxL : x \notin L)
      by (apply (notin_union_1 x L (termfv_exp e1)); exact Hx).
    assert (Hxb : x \notin termfv_exp e1)
      by (apply (notin_union_2 x L (termfv_exp e1)); exact Hx).
    pose proof (HL x HxL) as Hbody.
    pose proof
      (subst_gen nil ((x,A)::nil) (open_exp_wrt_exp e1 (e_var_f x)) Chk CT Hbody
         x A nil nil eq_refl (notin_empty_1 x) e2' P
         (typing_lc_exp nil nil e2' Inf P HtyP) HTWP HtyP HsubP) as Hsubst.
    simpl in Hsubst.
    change (Typing nil nil
              (subst_exp e2' x (open_exp_wrt_exp_rec 0 (e_var_f x) e1)) Chk CT)
      in Hsubst.
    rewrite (subst_open_exp_exp_fresh 0 x e2' e1 Hxb) in Hsubst.
    exists CT. split.
    + apply Typ_anno. exact Hsubst.
    + apply papp_subsub_refl.
      exact (typing_lc_typ nil ((x,A)::nil)
               (open_exp_wrt_exp e1 (e_var_f x)) Chk CT Hbody).
  - (* PApp_merge *)
    inversion Hty; subst; try discriminate.
    + (* Typ_merge *)
      inversion Happ; subst.
      pose proof (chk_and_l nil nil e2 B1 B2 Harg) as Harg1.
      pose proof (chk_and_r nil nil e2 B1 B2 Harg) as Harg2.
      destruct (IHHpapp1 e2 eq_refl A B1 C1 H1 H3 Harg1)
        as [C1' [HC1' Hsub1] ].
      destruct (IHHpapp2 e2 eq_refl B B2 C2 H4 H7 Harg2)
        as [C2' [HC2' Hsub2] ].
      pose proof
        (appDist_arrow_cod_disjoint A B B1 C1 B2 C2 H5 H3 H7) as HdCod.
      assert (Hd' : disjoint nil C1' C2').
      { apply (disjoint_subsub_r nil C1' C2 C2').
        - apply (disjoint_subsub_l nil C1 C1' C2 HdCod Hsub1).
        - exact Hsub2. }
      exists (t_and C1' C2'). split.
      * apply Typ_merge; assumption.
      * apply papp_subsub_and_intro.
        -- exact (papp_lc_typ_arrow_cod_l A B1 C1 H3).
        -- exact (papp_lc_typ_arrow_cod_l B B2 C2 H7).
        -- exact Hsub1.
        -- exact Hsub2.
    + (* Typ_mergev *)
      inversion Happ; subst.
      pose proof (chk_and_l nil nil e2 B1 B2 Harg) as Harg1.
      pose proof (chk_and_r nil nil e2 B1 B2 Harg) as Harg2.
      destruct (IHHpapp1 e2 eq_refl A B1 C1 H4 H6 Harg1)
        as [C1' [HC1' Hsub1] ].
      destruct (IHHpapp2 e2 eq_refl B B2 C2 H7 H10 Harg2)
        as [C2' [HC2' Hsub2] ].
      assert (Hcons' : consistent e1 e0)
        by (apply (papp_consistent_arrow v1 v2 A B B1 C1 B2 C2
                     e2 e1 e0 H4 H7 H8 H6 H10 Hpapp1 Hpapp2)).
      exists (t_and C1' C2'). split.
      * eapply Typ_mergev.
        -- apply TCW_empty.
        -- apply CW_empty.
        -- apply uniq_nil.
        -- exact HC1'.
        -- exact HC2'.
        -- exact Hcons'.
      * apply papp_subsub_and_intro.
        -- exact (papp_lc_typ_arrow_cod_l A B1 C1 H6).
        -- exact (papp_lc_typ_arrow_cod_l B B2 C2 H10).
        -- exact Hsub1.
        -- exact Hsub2.
Qed.

Lemma papp_typing_proj : forall v l r,
  papp v (arg_la l) r ->
  forall A C,
    Typing nil nil v Inf A ->
    appDist A (t_rcd l C) ->
    exists C', Typing nil nil r Inf C' /\ subsub C' C.
Proof.
  intros v l r Hpapp.
  dependent induction Hpapp; intros AT CT Hty Happ; try discriminate.
  - (* PApp_proj *)
    inversion Hty; subst.
    destruct (appDist_rcd_unique AT l B l CT H0 Happ) as [EL EC]; subst.
    destruct (papp_rcd_chk_appDist_body l e AT H4 l CT H0) as [_ Hbody].
    exists CT. split.
    + apply Typ_anno. exact Hbody.
    + apply papp_subsub_refl. exact (papp_lc_typ_rcd_cod AT l CT H0).
  - (* PApp_merge *)
    inversion Hty; subst; try discriminate.
    + (* Typ_merge *)
      inversion Happ; subst.
      destruct (IHHpapp1 l eq_refl A B1 H1 H3) as [C1' [HC1' Hsub1] ].
      destruct (IHHpapp2 l eq_refl B B2 H4 H7) as [C2' [HC2' Hsub2] ].
      pose proof (appDist_rcd_cod_disjoint A B l B1 B2 H5 H3 H7) as HdCod.
      assert (Hd' : disjoint nil C1' C2').
      { apply (disjoint_subsub_r nil C1' B2 C2').
        - apply (disjoint_subsub_l nil B1 C1' B2 HdCod Hsub1).
        - exact Hsub2. }
      exists (t_and C1' C2'). split.
      * apply Typ_merge; assumption.
      * apply papp_subsub_and_intro.
        -- exact (papp_lc_typ_rcd_cod A l B1 H3).
        -- exact (papp_lc_typ_rcd_cod B l B2 H7).
        -- exact Hsub1.
        -- exact Hsub2.
    + (* Typ_mergev *)
      inversion Happ; subst.
      destruct (IHHpapp1 l eq_refl A B1 H4 H6) as [C1' [HC1' Hsub1] ].
      destruct (IHHpapp2 l eq_refl B B2 H7 H10) as [C2' [HC2' Hsub2] ].
      assert (Hcons' : consistent e1 e2)
        by (apply (papp_consistent_rcd v1 l e1 Hpapp1 v2 e2 Hpapp2
                     A B H4 H7 H8)).
      exists (t_and C1' C2'). split.
      * eapply Typ_mergev.
        -- apply TCW_empty.
        -- apply CW_empty.
        -- apply uniq_nil.
        -- exact HC1'.
        -- exact HC2'.
        -- exact Hcons'.
      * apply papp_subsub_and_intro.
        -- exact (papp_lc_typ_rcd_cod A l B1 H6).
        -- exact (papp_lc_typ_rcd_cod B l B2 H10).
        -- exact Hsub1.
        -- exact Hsub2.
Qed.

Lemma papp_typing_tapp : forall v A r,
  papp v (arg_typ A) r ->
  forall B C1 C2,
    Typing nil nil v Inf B ->
    appDist B (t_forall C1 C2) ->
    disjoint nil A C1 ->
    exists C', Typing nil nil r Inf C' /\
              subsub C' (open_typ_wrt_typ C2 A).
Proof.
  intros v A r Hpapp.
  dependent induction Hpapp; intros AT C1 C2 Hty Happ Hdisj; try discriminate.
  - (* PApp_tabs *)
    inversion Hty; subst.
    destruct (appDist_all_unique AT B1 B2 C1 C2 H1 Happ) as [E1 E2]; subst.
    pose proof (papp_tabs_chk_appDist_body
                  e AT H5 C1 C2 A H1 Hdisj) as Hbody.
    exists (open_typ_wrt_typ C2 A). split.
    + apply Typ_anno. exact Hbody.
    + apply papp_subsub_refl. exact (typing_lc_typ nil nil
        (open_exp_wrt_typ e A) Chk (open_typ_wrt_typ C2 A) Hbody).
  - (* PApp_merge *)
    inversion Hty; subst; try discriminate.
    + (* Typ_merge *)
      inversion Happ; subst.
      destruct (papp_disjoint_and_r_inv nil A B1 B2 Hdisj) as [Hd1 Hd2].
      destruct (IHHpapp1 A eq_refl A0 B1 C0 H1 H3 Hd1)
        as [C1' [HC1' Hsub1] ].
      destruct (IHHpapp2 A eq_refl B B2 C3 H4 H7 Hd2)
        as [C2' [HC2' Hsub2] ].
      pose proof (papp_arg_typ_lc v1 A e1 Hpapp1) as HlcA.
      pose proof
        (appDist_all_cod_disjoint_open_disj A0 B B1 C0 B2 C3 A
           H5 H3 H7 Hd1 Hd2) as HdCodOpen.
      pose proof
        (papp_lc_typ_all_cod_open B1 C0 A
           (proj2 (appDist_lc A0 (t_forall B1 C0) H3)) HlcA) as HlcC0.
      pose proof
        (papp_lc_typ_all_cod_open B2 C3 A
           (proj2 (appDist_lc B (t_forall B2 C3) H7)) HlcA) as HlcC3.
      assert (Hd' : disjoint nil C1' C2').
      { apply (disjoint_subsub_r nil C1'
                 (open_typ_wrt_typ C3 A) C2').
        - apply (disjoint_subsub_l nil (open_typ_wrt_typ C0 A)
                   C1' (open_typ_wrt_typ C3 A) HdCodOpen Hsub1).
        - exact Hsub2. }
      exists (t_and C1' C2'). split.
      * apply Typ_merge; assumption.
      * change (subsub (t_and C1' C2')
                  (t_and (open_typ_wrt_typ C0 A) (open_typ_wrt_typ C3 A))).
        apply papp_subsub_and_intro; assumption.
    + (* Typ_mergev *)
      inversion Happ; subst.
      destruct (papp_disjoint_and_r_inv nil A B1 B2 Hdisj) as [Hd1 Hd2].
      destruct (IHHpapp1 A eq_refl A0 B1 C0 H4 H6 Hd1)
        as [C1' [HC1' Hsub1] ].
      destruct (IHHpapp2 A eq_refl B B2 C3 H7 H10 Hd2)
        as [C2' [HC2' Hsub2] ].
      pose proof (papp_arg_typ_lc v1 A e1 Hpapp1) as HlcA.
      pose proof
        (papp_lc_typ_all_cod_open B1 C0 A
           (proj2 (appDist_lc A0 (t_forall B1 C0) H6)) HlcA) as HlcC0.
      pose proof
        (papp_lc_typ_all_cod_open B2 C3 A
           (proj2 (appDist_lc B (t_forall B2 C3) H10)) HlcA) as HlcC3.
      assert (Hcons' : consistent e1 e2)
        by (apply (papp_consistent_all v1 v2 A0 B B1 C0 B2 C3 A
                     e1 e2 H4 H7 H8 H6 H10 Hd1 Hd2 Hpapp1 Hpapp2)).
      exists (t_and C1' C2'). split.
      * apply (Typ_mergev nil nil e1 e2 C1' C2');
          [ exact H1 | exact H2 | exact H3 | exact HC1' | exact HC2' | exact Hcons' ].
      * change (subsub (t_and C1' C2')
                  (t_and (open_typ_wrt_typ C0 A) (open_typ_wrt_typ C3 A))).
        apply papp_subsub_and_intro; assumption.
Qed.

End PappTyping.

(* ================================================================== *)
(* The requested all-x argument-extraction statement for abstractions  *)
(* ([abs_chk_appDist_arg]) is false.  The following is a checked        *)
(* counterexample: t_top is an abstraction type whose arrow             *)
(* distributivity has domain [arrow t_top t_top], and an abstraction    *)
(* is Chk that domain but is not Chk t_top.                             *)
(* ================================================================== *)

Lemma papp_typing_top_chk_cons_top : forall x,
  Typing nil (cons (x, t_top) nil) e_top Chk t_top.
Proof.
  intros x.
  apply (Typ_sub nil (cons (x,t_top) nil) e_top t_top t_top).
  - apply Typ_top.
    + apply TCW_empty.
    + apply CW_cons; [ apply CW_empty | apply TW_top ].
    + apply (uniq_cons typ x t_top nil).
      * apply uniq_nil.
      * apply notin_empty.
  - apply (S_top nil t_top t_top); [ apply TW_top | apply O_top
      | apply TL_top; apply TCW_empty ].
Qed.

Lemma papp_typing_abs_top_arrow : forall B1,
  TWell nil B1 ->
  Typing nil nil (e_abs t_top e_top) Chk (t_arrow B1 t_top).
Proof.
  intros B1 HTW.
  apply (Typ_abs empty nil nil t_top e_top B1 t_top).
  - apply (S_top nil B1 t_top); [ exact HTW | apply O_top
      | apply TL_top; apply TCW_empty ].
  - intros x Hx. apply papp_typing_top_chk_cons_top.
Qed.

Lemma papp_typing_abs_top_not_top :
  ~ Typing nil nil (e_abs t_top e_top) Chk t_top.
Proof.
  intro H. inversion H; subst; try discriminate.
  exfalso. eapply papp_abs_inf_impossible; eassumption.
Qed.

Lemma papp_abs_chk_appDist_arg_false :
  ~ (forall A0 body B,
       Typing nil nil (e_abs A0 body) Chk B ->
       forall C1 C2, appDist B (t_arrow C1 C2) ->
       forall e2, Typing nil nil e2 Chk C1 -> Typing nil nil e2 Chk A0).
Proof.
  intro H.
  pose proof (papp_typing_abs_top_arrow (t_arrow t_top t_top)
                (TW_arrow nil t_top t_top (TW_top nil) (TW_top nil))) as Hbody.
  pose proof (papp_typing_abs_top_arrow t_top (TW_top nil)) as Harg.
  pose proof
    (H t_top e_top (t_arrow (t_arrow t_top t_top) t_top) Hbody
       (t_arrow t_top t_top) t_top
       (AD_refl (t_arrow (t_arrow t_top t_top) t_top)
          (lc_t_arrow (t_arrow t_top t_top) t_top
             (lc_t_arrow t_top t_top lc_t_top lc_t_top) lc_t_top))
       (e_abs t_top e_top) Harg) as Hbad.
  exact (papp_typing_abs_top_not_top Hbad).
Qed.


(* ================================================================== *)
(* Machine-checked counterexamples to the two remaining false         *)
(* parameters.  They show that [papp_typing_tapp] (for the universal   *)
(* merge case) and the [Typ_mergev] papp cases cannot be made          *)
(* unconditional as currently stated.                                 *)
(* ================================================================== *)

Definition papp_ce_all : typ := t_forall t_bot (t_tvar_b 0).

Lemma papp_ce_lc_all : lc_typ papp_ce_all.
Proof.
  unfold papp_ce_all. apply lc_t_forall.
  - apply lc_t_bot.
  - intro X. simpl. apply lc_t_tvar_f.
Qed.

Lemma papp_ce_TWell_all : TWell nil papp_ce_all.
Proof.
  unfold papp_ce_all. apply (TW_all empty nil t_bot (t_tvar_b 0)).
  - apply TW_bot.
  - intros X HX. simpl. apply (TW_var (cons (X,t_bot) nil) X t_bot).
    apply (@binds_cons_2 typ X X t_bot t_bot nil); auto.
Qed.

Lemma papp_ce_topLike_all : topLike nil papp_ce_all.
Proof.
  unfold papp_ce_all. eapply (TL_all empty nil t_bot (t_tvar_b 0)).
  intros X HX. simpl. apply (TL_var (cons (X,t_bot) nil) X t_bot).
  - apply TCW_cons.
    + apply TCW_empty.
    + apply TW_bot.
    + apply uniq_cons; [apply uniq_nil | apply notin_empty_1].
  - apply (@binds_cons_2 typ X X t_bot t_bot nil); auto.
  - apply BL_bot.
Qed.

Lemma papp_ce_disjoint_all : disjoint nil papp_ce_all papp_ce_all.
Proof.
  apply (D_topl nil papp_ce_all papp_ce_all
           papp_ce_TWell_all papp_ce_topLike_all).
Qed.

Lemma papp_ce_appDist_all : appDist papp_ce_all papp_ce_all.
Proof. unfold papp_ce_all. apply AD_refl. exact papp_ce_lc_all. Qed.

Lemma papp_ce_appDist_all_cod_disjoint_open_false :
  ~ (forall A1 A2 B1 C1 B2 C2 C,
      lc_typ C -> disjoint nil A1 A2 ->
      appDist A1 (t_forall B1 C1) ->
      appDist A2 (t_forall B2 C2) ->
      disjoint nil (open_typ_wrt_typ C1 C) (open_typ_wrt_typ C2 C)).
Proof.
  intro H.
  specialize (H papp_ce_all papp_ce_all
                t_bot (t_tvar_b 0) t_bot (t_tvar_b 0) t_int).
  assert (Hd : disjoint nil
                 (open_typ_wrt_typ (t_tvar_b 0) t_int)
                 (open_typ_wrt_typ (t_tvar_b 0) t_int)).
  { apply H.
    - apply lc_t_int.
    - exact papp_ce_disjoint_all.
    - exact papp_ce_appDist_all.
    - exact papp_ce_appDist_all. }
  simpl in Hd.
  exact (disjoint_int_int_false nil Hd).
Qed.

Definition papp_ce_body : exp := e_anno e_top (t_tvar_b 0).
Definition papp_ce_v1 : exp := e_anno (e_tabs e_top) papp_ce_all.
Definition papp_ce_v2 : exp := e_anno (e_tabs papp_ce_body) papp_ce_all.
Definition papp_ce_r1 : exp := e_anno e_top t_int.
Definition papp_ce_r2 : exp := e_anno (e_anno e_top t_int) t_int.

Lemma papp_ce_lc_tabs_body : lc_exp (e_tabs papp_ce_body).
Proof.
  apply lc_e_tabs. intro X. unfold papp_ce_body. simpl.
  apply lc_e_anno; [apply lc_e_top | apply lc_t_tvar_f].
Qed.

Lemma papp_ce_papp_v1 : papp papp_ce_v1 (arg_typ t_int)
  (e_anno e_top (open_typ_wrt_typ (t_tvar_b 0) t_int)).
Proof.
  unfold papp_ce_v1, papp_ce_all.
  eapply PApp_tabs.
  - apply lc_exp_tabs_top.
  - apply lc_t_int.
  - exact papp_ce_appDist_all.
Qed.

Lemma papp_ce_papp_v2 : papp papp_ce_v2 (arg_typ t_int)
  (e_anno (e_anno e_top (open_typ_wrt_typ (t_tvar_b 0) t_int))
          (open_typ_wrt_typ (t_tvar_b 0) t_int)).
Proof.
  unfold papp_ce_v2, papp_ce_body, papp_ce_all.
  eapply PApp_tabs.
  - exact papp_ce_lc_tabs_body.
  - apply lc_t_int.
  - exact papp_ce_appDist_all.
Qed.

Lemma papp_ce_consistent_v1_v2 : consistent papp_ce_v1 papp_ce_v2.
Proof.
  unfold papp_ce_v1, papp_ce_v2.
  apply (C_disjoint _ _ papp_ce_all papp_ce_all).
  - apply PT_anno; [apply lc_exp_tabs_top | exact papp_ce_lc_all].
  - apply PT_anno; [exact papp_ce_lc_tabs_body | exact papp_ce_lc_all].
  - exact papp_ce_disjoint_all.
  - apply PV_anno; [apply lc_exp_tabs_top | exact papp_ce_lc_all].
  - apply PV_anno; [exact papp_ce_lc_tabs_body | exact papp_ce_lc_all].
Qed.

Lemma papp_ce_pType_anno_eq : forall e A B,
  pType (e_anno e A) B -> B = A.
Proof. intros e A B H. dependent destruction H. reflexivity. Qed.

Lemma papp_ce_not_consistent_r1_r2 : ~ consistent papp_ce_r1 papp_ce_r2.
Proof.
  unfold papp_ce_r1, papp_ce_r2.
  intro H.
  dependent destruction H.
  pose proof (papp_ce_pType_anno_eq e_top t_int A H) as E1. subst A.
  pose proof (papp_ce_pType_anno_eq (e_anno e_top t_int) t_int B H0) as E2.
  subst B.
  exact (disjoint_int_int_false nil H1).
Qed.

Lemma papp_ce_papp_consistent_false :
  ~ (forall v1 v2 arg e1 e2,
      consistent v1 v2 -> papp v1 arg e1 -> papp v2 arg e2 ->
      consistent e1 e2).
Proof.
  intro H.
  apply papp_ce_not_consistent_r1_r2.
  exact (H papp_ce_v1 papp_ce_v2 (arg_typ t_int) papp_ce_r1 papp_ce_r2
          papp_ce_consistent_v1_v2 papp_ce_papp_v1 papp_ce_papp_v2).
Qed.

(* The same counterexample is already [Inf]-typed at [papp_ce_all], so
   adding source typing does not make the consistency statement true. *)

Lemma papp_ce_ctx_TCW : forall X, TCWell (cons (X,t_bot) nil).
Proof.
  intro X. apply TCW_cons.
  - apply TCW_empty.
  - apply TW_bot.
  - apply uniq_cons; [apply uniq_nil | apply notin_empty_1].
Qed.

Lemma papp_ce_ctx_binds : forall X, binds X t_bot (cons (X,t_bot) nil).
Proof.
  intro X. apply (@binds_cons_2 typ X X t_bot t_bot nil); auto.
Qed.

Lemma papp_ce_ctx_TW_var :
  forall X, TWell (cons (X,t_bot) nil) (t_tvar_f X).
Proof.
  intro X. simpl. apply (TW_var (cons (X,t_bot) nil) X t_bot).
  apply papp_ce_ctx_binds.
Qed.

Lemma papp_ce_ctx_TL_var :
  forall X, topLike (cons (X,t_bot) nil) (t_tvar_f X).
Proof.
  intro X. simpl. apply (TL_var (cons (X,t_bot) nil) X t_bot).
  - apply papp_ce_ctx_TCW.
  - apply papp_ce_ctx_binds.
  - apply BL_bot.
Qed.

Lemma papp_ce_top_chk_var :
  forall X, Typing (cons (X,t_bot) nil) nil e_top Chk (t_tvar_f X).
Proof.
  intro X.
  eapply (Typ_sub (cons (X,t_bot) nil) nil e_top (t_tvar_f X) t_top).
  - apply (Typ_top (cons (X,t_bot) nil) nil).
    + apply papp_ce_ctx_TCW.
    + apply CW_empty.
    + apply uniq_nil.
  - apply (S_top (cons (X,t_bot) nil) t_top (t_tvar_f X)).
    + apply TW_top.
    + apply O_var.
    + apply papp_ce_ctx_TL_var.
Qed.

Lemma papp_ce_anno_top_chk_var : forall X,
  Typing (cons (X,t_bot) nil) nil
    (e_anno e_top (t_tvar_f X)) Chk (t_tvar_f X).
Proof.
  intro X.
  eapply (Typ_sub (cons (X,t_bot) nil) nil
            (e_anno e_top (t_tvar_f X)) (t_tvar_f X) (t_tvar_f X)).
  - apply Typ_anno. apply papp_ce_top_chk_var.
  - apply (S_var (cons (X,t_bot) nil) X).
    + apply papp_ce_ctx_TCW.
    + apply papp_ce_ctx_TW_var.
Qed.

Lemma papp_ce_tabs_top_chk_all :
  Typing nil nil (e_tabs e_top) Chk papp_ce_all.
Proof.
  unfold papp_ce_all.
  eapply (Typ_tabs empty nil nil e_top t_bot (t_tvar_b 0)).
  - apply CW_empty.
  - intros X HX. simpl. apply papp_ce_top_chk_var.
Qed.

Lemma papp_ce_tabs_body_chk_all :
  Typing nil nil (e_tabs papp_ce_body) Chk papp_ce_all.
Proof.
  unfold papp_ce_all.
  eapply (Typ_tabs empty nil nil papp_ce_body t_bot (t_tvar_b 0)).
  - apply CW_empty.
  - intros X HX. unfold papp_ce_body. simpl.
    apply papp_ce_anno_top_chk_var.
Qed.

Lemma papp_ce_v1_typing : Typing nil nil papp_ce_v1 Inf papp_ce_all.
Proof.
  unfold papp_ce_v1. apply Typ_anno. apply papp_ce_tabs_top_chk_all.
Qed.

Lemma papp_ce_v2_typing : Typing nil nil papp_ce_v2 Inf papp_ce_all.
Proof.
  unfold papp_ce_v2. apply Typ_anno. apply papp_ce_tabs_body_chk_all.
Qed.

Lemma papp_ce_papp_consistent_typed_false :
  ~ (forall v1 v2 A1 A2 arg e1 e2,
      Typing nil nil v1 Inf A1 -> Typing nil nil v2 Inf A2 ->
      consistent v1 v2 -> papp v1 arg e1 -> papp v2 arg e2 ->
      consistent e1 e2).
Proof.
  intro H.
  pose proof (H papp_ce_v1 papp_ce_v2 papp_ce_all papp_ce_all
               (arg_typ t_int) papp_ce_r1 papp_ce_r2
               papp_ce_v1_typing papp_ce_v2_typing
               papp_ce_consistent_v1_v2
               papp_ce_papp_v1 papp_ce_papp_v2) as Hc.
  exact (papp_ce_not_consistent_r1_r2 Hc).
Qed.

Lemma papp_ce_appDist_all_cod_disjoint_open_typed_false :
  ~ (forall A1 A2 B1 C1 B2 C2 C v1 v2,
      Typing nil nil v1 Inf A1 -> Typing nil nil v2 Inf A2 ->
      lc_typ C -> disjoint nil A1 A2 ->
      appDist A1 (t_forall B1 C1) ->
      appDist A2 (t_forall B2 C2) ->
      disjoint nil (open_typ_wrt_typ C1 C) (open_typ_wrt_typ C2 C)).
Proof.
  intro H.
  specialize (H papp_ce_all papp_ce_all
                t_bot (t_tvar_b 0) t_bot (t_tvar_b 0) t_int
                papp_ce_v1 papp_ce_v2
                papp_ce_v1_typing papp_ce_v2_typing).
  assert (Hd : disjoint nil
                 (open_typ_wrt_typ (t_tvar_b 0) t_int)
                 (open_typ_wrt_typ (t_tvar_b 0) t_int)).
  { apply H.
    - apply lc_t_int.
    - exact papp_ce_disjoint_all.
    - exact papp_ce_appDist_all.
    - exact papp_ce_appDist_all. }
  simpl in Hd.
  exact (disjoint_int_int_false nil Hd).
Qed.
End papp_agent.
Import papp_agent.

Module agentE4.
Import ListNotations.

(* ================================================================== *)
(* 1. Local closure of the operational auxiliary relations.            *)
(* ================================================================== *)

Lemma lc_exp_merge_inv : forall e1 e2,
  lc_exp (e_merge e1 e2) -> lc_exp e1 /\ lc_exp e2.
Proof.
  intros e1 e2 H. inversion H; subst; auto.
Qed.

Lemma lc_exp_anno_inv : forall e A,
  lc_exp (e_anno e A) -> lc_exp e /\ lc_typ A.
Proof.
  intros e A H. inversion H; subst; auto.
Qed.

Lemma lc_exp_app_inv : forall e1 e2,
  lc_exp (e_app e1 e2) -> lc_exp e1 /\ lc_exp e2.
Proof.
  intros e1 e2 H. inversion H; subst; auto.
Qed.

Lemma lc_exp_proj_inv : forall e l,
  lc_exp (e_proj e l) -> lc_exp e.
Proof.
  intros e l H. inversion H; subst; auto.
Qed.

Lemma lc_exp_tapp_inv : forall e A,
  lc_exp (e_tapp e A) -> lc_exp e /\ lc_typ A.
Proof.
  intros e A H. inversion H; subst; auto.
Qed.

Lemma lc_exp_abs_inv : forall A e,
  lc_exp (e_abs A e) -> lc_typ A /\ (forall x, lc_exp (open_exp_wrt_exp e (e_var_f x))).
Proof.
  intros A e H. inversion H; subst; auto.
Qed.

Lemma lc_exp_tabs_inv : forall e,
  lc_exp (e_tabs e) -> (forall X, lc_exp (open_exp_wrt_typ e (t_tvar_f X))).
Proof.
  intros e H. inversion H; subst; auto.
Qed.

Lemma lc_exp_fixpoint_inv : forall A e,
  lc_exp (e_fixpoint A e) -> lc_typ A /\ (forall x, lc_exp (open_exp_wrt_exp e (e_var_f x))).
Proof.
  intros A e H. inversion H; subst; auto.
Qed.

Lemma lc_exp_open_exp_body : forall e v,
  (forall x, lc_exp (open_exp_wrt_exp e (e_var_f x))) ->
  lc_exp v ->
  lc_exp (open_exp_wrt_exp e v).
Proof.
  intros e v Hbody Hv.
  destruct (atom_fresh (termfv_exp e)) as [x Hx].
  change (lc_exp (open_exp_wrt_exp_rec 0 v e)).
  rewrite <- (agentC.subst_open_exp_exp_fresh 0 x v e Hx).
  apply agentC.lc_exp_subst_exp.
  - exact Hv.
  - exact (Hbody x).
Qed.

Lemma lc_exp_open_exp_typ_body : forall e C,
  (forall X, lc_exp (open_exp_wrt_typ e (t_tvar_f X))) ->
  lc_typ C ->
  lc_exp (open_exp_wrt_typ e C).
Proof.
  intros e C Hbody HC.
  destruct (atom_fresh (typefv_exp e)) as [X HX].
  change (lc_exp (open_exp_wrt_typ_rec 0 C e)).
  rewrite <- (agentC.typsubst_open_exp_typ 0 X C e HC HX).
  apply agentC.lc_exp_typsubst.
  - exact HC.
  - exact (Hbody X).
Qed.

Lemma wrapping_lc : forall e A e',
  lc_exp e -> wrapping e A e' -> lc_exp e'.
Proof.
  intros e A e' He Hw. revert He.
  induction Hw; intros He.
  - apply lc_e_top.
  - apply lc_e_anno.
    + apply agentK.lc_exp_abs_top.
    + apply agentA.ord_lc_typ. exact H0.
  - apply lc_e_anno.
    + apply agentK.lc_exp_tabs_top.
    + apply agentA.ord_lc_typ. exact H0.
  - apply lc_e_anno.
    + apply agentK.lc_exp_rcd_top.
    + apply agentA.ord_lc_typ. exact H0.
  - apply lc_e_anno.
    + exact He.
    + apply agentA.ord_lc_typ. assumption.
  - apply lc_e_merge; [apply IHHw1; assumption | apply IHHw2; assumption].
Qed.

Lemma casting_lc : forall v A v',
  lc_exp v -> casting v A v' -> lc_exp v'.
Proof.
  intros v A v' Hv Hc. revert Hv.
  induction Hc; intros Hv.
  - exact Hv.
  - apply lc_e_top.
  - apply lc_e_anno.
    + apply agentK.lc_exp_abs_top.
    + apply agentA.ord_lc_typ. exact H0.
  - apply lc_e_anno.
    + apply agentK.lc_exp_tabs_top.
    + apply agentA.ord_lc_typ. exact H0.
  - apply lc_e_anno.
    + apply agentK.lc_exp_rcd_top.
    + apply agentA.ord_lc_typ. exact H0.
  - apply lc_e_anno.
    + assumption.
    + apply agentA.ord_lc_typ. exact H0.
  - destruct (lc_exp_merge_inv _ _ Hv) as [Hv1 _].
    exact (IHHc Hv1).
  - destruct (lc_exp_merge_inv _ _ Hv) as [_ Hv2].
    exact (IHHc Hv2).
  - apply lc_e_merge; [apply IHHc1; assumption | apply IHHc2; assumption].
Qed.

Lemma papp_lc : forall v arg e,
  lc_exp v -> lc_arg arg -> papp v arg e -> lc_exp e.
Proof.
  intros v arg e Hv Harg Hp. revert Hv Harg.
  induction Hp as
    [ A e1 B e2 e2' C2 C1 Hlcsrc Hdist Hwr
    | e A C B2 B1 Hlcsrc HC Hdist
    | l e A B Hlcsrc Hdist
    | v1 v2 arg5 e1 e2 Hp1 IH1 Hp2 IH2 ];
    intros Hv Harg.
  - (* PApp_abs *)
    destruct (lc_exp_anno_inv _ _ Hv) as [Hinner _].
    destruct (lc_exp_abs_inv _ _ Hinner) as [_ Hbody].
    inversion Harg; subst.
    apply lc_e_anno.
    + apply (lc_exp_open_exp_body e1); [exact Hbody|].
      apply (wrapping_lc e2 A e2'); assumption.
    + apply (papp_agent.papp_lc_typ_arrow_cod_l B C1 C2). exact Hdist.
  - (* PApp_tabs *)
    destruct (lc_exp_anno_inv _ _ Hv) as [Hinner _].
    pose proof (lc_exp_tabs_inv e Hinner) as Hbody.
    inversion Harg; subst.
    apply lc_e_anno.
    + apply (lc_exp_open_exp_typ_body e C); [exact Hbody|exact HC].
    + apply (papp_agent.papp_lc_typ_all_cod_open B1 B2 C).
      * exact (proj2 (agentB.appDist_lc A (t_forall B1 B2) Hdist)).
      * exact HC.
  - (* PApp_proj *)
    destruct (lc_exp_anno_inv _ _ Hv) as [Hinner _].
    destruct (lc_exp_anno_inv _ _ Hv) as [_ _].
    inversion Hinner; subst.
    inversion Harg.
    apply lc_e_anno.
    + assumption.
    + apply (papp_agent.papp_lc_typ_rcd_cod A l B). exact Hdist.
  - (* PApp_merge *)
    destruct (lc_exp_merge_inv _ _ Hv) as [Hv1 Hv2].
    apply lc_e_merge.
    + apply (IH1 Hv1 Harg).
    + apply (IH2 Hv2 Harg).
Qed.

Lemma step_lc_exp : forall e e',
  lc_exp e -> step e e' -> lc_exp e'.
Proof.
  intros e e' He Hs. revert He.
  induction Hs; intros He.
  - (* Step_papp *)
    destruct (lc_exp_app_inv _ _ He) as [Hv Hin].
    apply (papp_lc v (arg_exp e) e').
    + exact Hv.
    + apply lc_arg_exp. exact Hin.
    + exact H0.
  - (* Step_pproj *)
    apply (papp_lc v (arg_la l) e).
    + apply lc_exp_proj_inv in He. exact He.
    + apply lc_arg_la.
    + exact H0.
  - (* Step_ptapp *)
    destruct (lc_exp_tapp_inv _ _ He) as [Hv HA].
    apply (papp_lc v (arg_typ A) e).
    + exact Hv.
    + apply lc_arg_typ. exact HA.
    + exact H0.
  - (* Step_annov *)
    destruct (lc_exp_anno_inv _ _ He) as [Hv _].
    apply (casting_lc v A v'); assumption.
  - (* Step_appl *)
    destruct (lc_exp_app_inv _ _ He) as [He1 He2].
    apply lc_e_app.
    + apply IHHs. exact He1.
    + exact He2.
  - (* Step_merge *)
    destruct (lc_exp_merge_inv _ _ He) as [He1 He2].
    apply lc_e_merge.
    + apply IHHs1. exact He1.
    + apply IHHs2. exact He2.
  - (* Step_mergel *)
    destruct (lc_exp_merge_inv _ _ He) as [He1 He2].
    apply lc_e_merge.
    + apply IHHs. exact He1.
    + exact He2.
  - (* Step_merger *)
    destruct (lc_exp_merge_inv _ _ He) as [He1 He2].
    apply lc_e_merge.
    + exact He1.
    + apply IHHs. exact He2.
  - (* Step_anno *)
    destruct (lc_exp_anno_inv _ _ He) as [He0 _].
    apply lc_e_anno.
    + apply IHHs. exact He0.
    + exact H.
  - (* Step_fix *)
    destruct (lc_exp_fixpoint_inv _ _ H) as [_ Hbody].
    apply lc_e_anno.
    + apply (lc_exp_open_exp_body e (e_fixpoint A e)).
      * exact Hbody.
      * exact H.
    + exact H0.
  - (* Step_proj *)
    apply lc_e_proj.
    apply IHHs.
    apply lc_exp_proj_inv in He. exact He.
  - (* Step_tapp *)
    destruct (lc_exp_tapp_inv _ _ He) as [He0 HA].
    apply lc_e_tapp.
    + apply IHHs. exact He0.
    + exact HA.
Qed.

(* Step is NOT deterministic in general: the untyped merge source      *)
(* [merge (lit 0) (lit 1)] has two casts to [t_int], giving two         *)
(* reductions of the same annotation.  Thus the proposed global         *)
(* [step_det] is false; only a typed restriction can be used.          *)
Lemma step_det_false :
  ~ (forall e1 e2 e3, step e1 e2 -> step e1 e3 -> e2 = e3).
Proof.
  intros Hdet.
  assert (Hs1 : step (e_anno (e_merge (e_lit 0) (e_lit 1)) t_int) (e_lit 0)).
  { eapply Step_annov.
    - apply V_merge; apply V_lit.
    - apply PV_merge; apply PV_int; apply PV_int.
    - apply (Cast_mergel (e_lit 0) (e_lit 1) t_int (e_lit 0)).
      + apply lc_e_lit.
      + apply O_int.
      + apply Cast_int. }
  assert (Hs2 : step (e_anno (e_merge (e_lit 0) (e_lit 1)) t_int) (e_lit 1)).
  { eapply Step_annov.
    - apply V_merge; apply V_lit.
    - apply PV_merge; apply PV_int; apply PV_int.
    - apply (Cast_merger (e_lit 0) (e_lit 1) t_int (e_lit 1)).
      + apply lc_e_lit.
      + apply O_int.
      + apply Cast_int. }
  pose proof (Hdet _ _ _ Hs1 Hs2). discriminate.
Qed.

(* A [Step_annov] result need not be unannotated: a literal can be    *)
(* cast to a top-like arrow type, whose canonical output is an         *)
(* annotation.  Hence inverting an outer annotation step has a         *)
(* genuine [Step_annov] branch even when the result is [anno _ _].    *)
Lemma step_annov_annotated_result :
  exists v A e',
    value v /\ prevalue v /\ step (e_anno v A) (e_anno e' A).
Proof.
  exists (e_lit 0), agentE.Bt, (e_abs t_top e_top).
  split; [ apply V_lit | split; [ apply PV_int | ] ].
  eapply Step_annov.
  - apply V_lit.
  - apply PV_int.
  - eapply Cast_topArrow.
    + apply lc_e_lit.
    + apply agentE.ord_Bt.
    + apply agentE.topLike_Bt.
Qed.

(* ================================================================== *)
(* 2. Inversion of an [Inf] typing of an annotated expression.        *)
(* ================================================================== *)

Lemma typing_anno_inf_chk : forall e A0 T,
  Typing nil nil (e_anno e A0) Inf T ->
  exists P, Typing nil nil e Chk P.
Proof.
  intros e A0 T Ht.
  inversion Ht; subst.
  exists T. assumption.
Qed.

(* ================================================================== *)
(* 2b. Determinism of [step] on typable expressions.                   *)
(* ================================================================== *)

Ltac step_det_use_ih :=
  match goal with
  | IH : forall a b : exp, step ?v a -> step ?v b -> a = b,
    Ha : step ?v ?a, Hb : step ?v ?b |- _ =>
      exact (IH a b Ha Hb)
  | IH : ?D = nil -> ?G = nil -> forall a b : exp, step ?v a -> step ?v b -> a = b,
    Ha : step ?v ?a, Hb : step ?v ?b |- _ =>
      first [ exact (IH eq_refl eq_refl a b Ha Hb)
            | match goal with
              | HD : ?D = nil, HG : ?G = nil |- _ =>
                  exact (IH HD HG a b Ha Hb)
              end ]
  end.

Lemma step_det_typing_aux :
  forall D G e d P, Typing D G e d P ->
    D = nil -> G = nil ->
    forall r1 r2, step e r1 -> step e r2 -> r1 = r2.
Proof.
  intros D G e d P Hty. induction Hty; intros HD HG r1 r2 Hs1 Hs2.
  - (* Typ_top *) inversion Hs1.
  - (* Typ_lit *) inversion Hs1.
  - (* Typ_var *) inversion Hs1.
  - (* Typ_abs *) inversion Hs1.
  - (* Typ_app *) inversion Hs1; subst; inversion Hs2; subst.
    + eapply agentK2.papp_detK; eassumption.
    + exfalso.
      match goal with Hv : value ?v, Hst : step ?v ?v' |- _ =>
        exact (agentE2.value_no_step v v' Hv Hst) end.
    + exfalso.
      match goal with Hv : value ?v, Hst : step ?v ?v' |- _ =>
        exact (agentE2.value_no_step v v' Hv Hst) end.
    + f_equal. step_det_use_ih.
  - (* Typ_tabs *) inversion Hs1.
  - (* Typ_tapp *) inversion Hs1; subst; inversion Hs2; subst.
    + eapply agentK2.papp_detK; eassumption.
    + exfalso.
      match goal with Hv : value ?v, Hst : step ?v ?v' |- _ =>
        exact (agentE2.value_no_step v v' Hv Hst) end.
    + exfalso.
      match goal with Hv : value ?v, Hst : step ?v ?v' |- _ =>
        exact (agentE2.value_no_step v v' Hv Hst) end.
    + f_equal. step_det_use_ih.
  - (* Typ_proj *) inversion Hs1; subst; inversion Hs2; subst.
    + eapply agentK2.papp_detK; eassumption.
    + exfalso.
      match goal with Hv : value ?v, Hst : step ?v ?v' |- _ =>
        exact (agentE2.value_no_step v v' Hv Hst) end.
    + exfalso.
      match goal with Hv : value ?v, Hst : step ?v ?v' |- _ =>
        exact (agentE2.value_no_step v v' Hv Hst) end.
    + f_equal. step_det_use_ih.
  - (* Typ_rcd *) inversion Hs1.
  - (* Typ_merge *) inversion Hs1; subst; inversion Hs2; subst.
    all: try (exfalso;
      match goal with Hv : value ?v, Hst : step ?v ?v' |- _ =>
        exact (agentE2.value_no_step v v' Hv Hst) end).
    all: try (f_equal).
    all: try step_det_use_ih.
    all: try reflexivity.
  - (* Typ_inter *) step_det_use_ih.
  - (* Typ_anno *)
    inversion Hs1; subst.
    + (* Hs1 uses Step_annov *)
      inversion Hs2; subst.
      * (* both Step_annov: cast functionality *)
        assert (Hinf : exists P, Typing nil nil e Inf P).
        { match goal with
          | Hchk : Typing nil nil e Chk A, Hpv0 : prevalue e |- _ =>
              exact (agentE3.prevalue_chk_inf e Hpv0 A Hchk)
          end. }
        destruct Hinf as [P HP].
        refine (@agentK2.casting_functional_inf_pre e P HP _ A r1 r2 _ _).
        all: assumption.
      * (* Step_annov vs Step_anno: value cannot step *)
        exfalso.
        match goal with Hv : value ?v, Hst : step ?v ?v' |- _ =>
          exact (agentE2.value_no_step v v' Hv Hst) end.
    + (* Hs1 uses Step_anno *)
      inversion Hs2; subst.
      * (* Step_anno vs Step_annov: value cannot step *)
        exfalso.
        match goal with Hv : value ?v, Hst : step ?v ?v' |- _ =>
          exact (agentE2.value_no_step v v' Hv Hst) end.
      * (* both Step_anno: recurse on the common inner term *)
        f_equal. step_det_use_ih.
  - (* Typ_fix *) inversion Hs1; subst; inversion Hs2; subst; reflexivity.
  - (* Typ_mergev *) inversion Hs1; subst; inversion Hs2; subst.
    all: try (exfalso;
      match goal with Hv : value ?v, Hst : step ?v ?v' |- _ =>
        exact (agentE2.value_no_step v v' Hv Hst) end).
    all: try (f_equal).
    all: try step_det_use_ih.
    all: try reflexivity.
  - (* Typ_sub *) step_det_use_ih.
Qed.

Lemma step_det_typing_nil :
  forall e d P, Typing nil nil e d P ->
  forall r1 r2, step e r1 -> step e r2 -> r1 = r2.
Proof.
  intros e d P Hty.
  exact (step_det_typing_aux nil nil e d P Hty eq_refl eq_refl).
Qed.

(* ================================================================== *)
(* 3. Consistency preservation for a both-step pair.                   *)
(* ================================================================== *)

Section ConsistentStepBothTyped.

Lemma anno_anno_step_consistent : forall e A0 B0 P0 u1' u2',
  lc_typ A0 ->
  lc_typ B0 ->
  Typing nil nil e Chk P0 ->
  step (e_anno e A0) u1' ->
  step (e_anno e B0) u2' ->
  consistent u1' u2'.
Proof.
  intros e A0 B0 P0 u1' u2' HlcA HlcB Hchk Hs1 Hs2.
  inversion Hs1 as [ v e1 e1' Hval Hpapp
                   | v l e1 Hval Hpapp
                   | v T1 e1 Hval Hpapp
                   | v T1 v1' Hval Hpv Hcast
                   | e1 e2 e1' Hlce2 Hstep
                   | e1 e2 e1' e2' Hstep1 Hstep2
                   | e1 v2 e1' Hval Hstep
                   | v1 e2 e2' Hval Hstep
                   | e1 T1 e1' HlcT Hstep
                   | T1 e1 Hlcfix HlcT
                   | e1 l e1' Hstep
                   | e1 T1 e1' HlcT Hstep ]; subst.
  - (* Step_annov left *)
    inversion Hs2 as [ v2 e2 e2' Hval2 Hpapp2
                     | v2 l e2 Hval2 Hpapp2
                     | v2 T2 e2 Hval2 Hpapp2
                     | v2 T2 v2' Hval2 Hpv2 Hcast2
                     | e2 e3 e2' Hlce3 Hstep2
                     | e2 e3 e2' e3' Hstep2 Hstep2'
                     | e2 v3 e2' Hval3 Hstep2
                     | v3 e3 e3' Hval3 Hstep2
                     | e2 T2 e2' HlcT2 Hstep2
                     | T2 e2 Hlcfix2 HlcT2
                     | e2 l e2' Hstep2
                     | e2 T2 e2' HlcT2 Hstep2 ]; subst.
    + (* both Step_annov *)
      destruct (agentE3.prevalue_chk_inf e Hpv P0 Hchk) as [Pinf HPinf].
      exact (agentK2.casting_consistent_inf_source e Pinf HPinf
               A0 B0 u1' u2' Hcast Hcast2).
    + (* right Step_anno: e is a value and steps *)
      exfalso. exact (agentE2.value_no_step e e2' Hval Hstep2).
  - (* Step_anno left *)
    inversion Hs2 as [ v2 e2 e2' Hval2 Hpapp2
                     | v2 l e2 Hval2 Hpapp2
                     | v2 T2 e2 Hval2 Hpapp2
                     | v2 T2 v2' Hval2 Hpv2 Hcast2
                     | e2 e3 e2' Hlce3 Hstep2
                     | e2 e3 e2' e3' Hstep2 Hstep2'
                     | e2 v3 e2' Hval3 Hstep2
                     | v3 e3 e3' Hval3 Hstep2
                     | e2 T2 e2' HlcT2 Hstep2
                     | T2 e2 Hlcfix2 HlcT2
                     | e2 l e2' Hstep2
                     | e2 T2 e2' HlcT2 Hstep2 ]; subst.
    + (* right Step_annov: e is a value and steps *)
      exfalso. exact (agentE2.value_no_step e e1' Hval2 Hstep).
    + (* both Step_anno *)
      match goal with
      | Hst1 : step e ?x, Hst2 : step e ?y |- _ =>
          assert (Heq : x = y) by
            exact (step_det_typing_nil e Chk P0 Hchk x y Hst1 Hst2);
          subst y;
          apply C_anno;
          [ exact HlcA
          | apply (step_lc_exp e x
                     (agentB.typing_lc_exp nil nil e Chk P0 Hchk) Hst1)
          | exact HlcB ]
      end.
Qed.

Lemma consistent_step_both_typed :
  forall u1 u2 A B u1' u2',
    Typing nil nil u1 Inf A ->
    Typing nil nil u2 Inf B ->
    consistent u1 u2 ->
    step u1 u1' ->
    step u2 u2' ->
    consistent u1' u2'.
Proof.
  intros u1 u2 A B u1' u2' Ht1 Ht2 Hc.
  revert A B u1' u2' Ht1 Ht2.
  induction Hc as
    [ i
    | e A0 B0 HlcA Hlce HlcB
    | u1 u2 P Q Hp1 Hp2 Hdis Hpv1 Hpv2
    | u1 u2 u Hc1 IH1 Hc2 IH2
    | u1 u2 u Hc1 IH1 Hc2 IH2 ];
    intros A B u1' u2' Ht1 Ht2 Hs1 Hs2.
  - (* C_lit *)
    exfalso. exact (agentE2.value_no_step _ _ (V_lit i) Hs1).
  - (* C_anno: both sides are [anno e _]. *)
    destruct (typing_anno_inf_chk e A0 A Ht1) as [P1 HP1].
    exact (anno_anno_step_consistent e A0 B0 P1 u1' u2'
             HlcA HlcB HP1 Hs1 Hs2).
  - (* C_disjoint *)
    destruct (agentE2.pType_step_subsub step_lc_exp u1 P u1' Hp1 Hs1)
      as [pnew hpnew_and_hsubp].
    destruct hpnew_and_hsubp as [hpnew hsubp].
    destruct (agentE2.pType_step_subsub step_lc_exp u2 Q u2' Hp2 Hs2)
      as [qnew hqnew_and_hsubq].
    destruct hqnew_and_hsubq as [hqnew hsubq].
    apply C_disjoint with (A := pnew) (B := qnew).
    + exact hpnew.
    + exact hqnew.
    + apply (agentK2.disjoint_subsub_r nil pnew Q qnew).
      * apply (agentK2.disjoint_subsub_l nil P pnew Q Hdis hsubp).
      * exact hsubq.
    + exact (agentE2.pType_prevalue u1' pnew hpnew).
    + exact (agentE2.pType_prevalue u2' qnew hqnew).
  - (* C_mergel: target [merge u1 u2], other side [u]. *)
    destruct (agentE3.merge_inf_components u1 u2 A Ht1) as
      [A1 merge_rest1].
    destruct merge_rest1 as [A2 merge_rest2].
    destruct merge_rest2 as [HeqA merge_rest3].
    destruct merge_rest3 as [HA1 HA2]. subst A.
    inversion Hs1 as [ v e1 e1' Hval Hpapp
                     | v l e1 Hval Hpapp
                     | v T1 e1 Hval Hpapp
                     | v T1 v1' Hval Hpv Hcast
                     | e1 e2 e1' Hlce2 Hstep
                     | e1 e2 e1' e2' Hstep1 Hstep2
                     | e1 v2 e1' Hval Hstep
                     | v1 e2 e2' Hval Hstep
                     | e1 T1 e1' HlcT Hstep
                     | T1 e1 Hlcfix HlcT
                     | e1 l e1' Hstep
                     | e1 T1 e1' HlcT Hstep ]; subst.
    + (* Step_merge *)
      apply C_mergel.
      * exact (IH1 A1 B e1' u2' HA1 Ht2 Hstep1 Hs2).
      * exact (IH2 A2 B e2' u2' HA2 Ht2 Hstep2 Hs2).
    + (* Step_mergel: the second component is the value [v2] *)
      apply C_mergel.
      * exact (IH1 A1 B e1' u2' HA1 Ht2 Hstep Hs2).
      * exact (agentE2.consistent_step_r_value step_lc_exp agentK2.disjoint_subsub_r
                 u2 u u2' Hval Hc2 Hs2).
    + (* Step_merger: the first component is the value [v1] *)
      apply C_mergel.
      * exact (agentE2.consistent_step_r_value step_lc_exp agentK2.disjoint_subsub_r
                 u1 u u2' Hval Hc1 Hs2).
      * exact (IH2 A2 B e2' u2' HA2 Ht2 Hstep Hs2).
  - (* C_merger: target [u], other side [merge u1 u2]. *)
    destruct (agentE3.merge_inf_components u2 u B Ht2) as
      [B1 merge_restB1].
    destruct merge_restB1 as [B2 merge_restB2].
    destruct merge_restB2 as [HeqB merge_restB3].
    destruct merge_restB3 as [HB1 HB2]. subst B.
    inversion Hs2 as [ v e1 e1' Hval Hpapp
                     | v l e1 Hval Hpapp
                     | v T1 e1 Hval Hpapp
                     | v T1 v1' Hval Hpv Hcast
                     | e1 e2 e1' Hlce2 Hstep
                     | e1 e2 e1' e2' Hstep1 Hstep2
                     | e1 v2 e1' Hval Hstep
                     | v1 e2 e2' Hval Hstep
                     | e1 T1 e1' HlcT Hstep
                     | T1 e1 Hlcfix HlcT
                     | e1 l e1' Hstep
                     | e1 T1 e1' HlcT Hstep ]; subst.
    + (* Step_merge on the right *)
      apply C_merger.
      * apply (IH1 A B1 u1' e1' Ht1 HB1 Hs1 Hstep1).
      * apply (IH2 A B2 u1' e2' Ht1 HB2 Hs1 Hstep2).
    + (* Step_mergel on the right: second component is a value *)
      apply C_merger.
      * apply (IH1 A B1 u1' e1' Ht1 HB1 Hs1 Hstep).
      * apply (agentE2.consistent_step_l_value step_lc_exp agentK2.disjoint_subsub_l
                 u1 u u1' Hval Hc2 Hs1).
    + (* Step_merger on the right: first component is a value *)
      apply C_merger.
      * apply (agentE2.consistent_step_l_value step_lc_exp agentK2.disjoint_subsub_l
                 u1 u2 u1' Hval Hc1 Hs1).
      * apply (IH2 A B2 u1' e2' Ht1 HB2 Hs1 Hstep).
Qed.

End ConsistentStepBothTyped.
End agentE4.
Import agentE4.

Module pres_agent.
Import ListNotations.

(* ================================================================== *)
(* Subject reduction / preservation scaffold for the final theorem     *)
(*                                                                     *)
(* Every missing piece of infrastructure is a [Section Variable].      *)
(* There are no axioms or admitted proofs in this file.                *)
(* ================================================================== *)

Definition PresRes (e:exp) (d:dirflag) (A:typ) (e':exp) : Prop :=
  match d with
  | Inf => exists A', Typing nil nil e' Inf A' /\ subsub A' A
  | Chk => Typing nil nil e' Chk A
  end.

Section Preservation.

(* ------------------------------------------------------------------ *)
(* 1. Section arguments of the duplication library (dup.v).            *)
(* ------------------------------------------------------------------ *)
Variable chk_and_l : forall D G e A B,
  Typing D G e Chk (t_and A B) -> Typing D G e Chk A.
Variable chk_and_r : forall D G e A B,
  Typing D G e Chk (t_and A B) -> Typing D G e Chk B.
Variable spl_open : forall A B C X, spl A B C ->
  spl (open_typ_wrt_typ A (t_tvar_f X))
      (open_typ_wrt_typ B (t_tvar_f X))
      (open_typ_wrt_typ C (t_tvar_f X)).
Variable spl_all_open : forall L A B C,
  (forall X, X \notin L ->
     spl (open_typ_wrt_typ A (t_tvar_f X))
         (open_typ_wrt_typ B (t_tvar_f X))
         (open_typ_wrt_typ C (t_tvar_f X))) ->
  forall X, spl (open_typ_wrt_typ A (t_tvar_f X))
                (open_typ_wrt_typ B (t_tvar_f X))
                (open_typ_wrt_typ C (t_tvar_f X)).

(* ------------------------------------------------------------------ *)
(* 2. Algorithmic subtyping infrastructure (not yet compiled).         *)
(* ------------------------------------------------------------------ *)
Variable subsub_algo_sub : forall D A B,
  TCWell D -> TWell D B -> subsub A B -> algo_sub D A B.
Variable algo_sub_trans : forall D A B C,
  TCWell D -> TWell D A -> TWell D B -> TWell D C ->
  algo_sub D A B -> algo_sub D B C -> algo_sub D A C.

(* ------------------------------------------------------------------ *)
(* 3. Disjointness / subsubning lemmas from agentI.                    *)
(*    (agentI.vo is not importable in this build: it makes             *)
(*     inconsistent assumptions over agentE.  We therefore keep the    *)
(*     exact statements as Section Variables.)                         *)
(* ------------------------------------------------------------------ *)
Variable subsub_lc : forall A B, subsub A B -> lc_typ A /\ lc_typ B.
Variable disjoint_DT_r : forall D A B B',
  disjoint D A B -> DuplicatedType B' B -> disjoint D A B'.
Variable disjoint_DT_l : forall D A A' B,
  disjoint D A B -> DuplicatedType A' A -> disjoint D A' B.
Variable disjoint_subsub_r : forall D A B B',
  disjoint D A B -> subsub B' B -> disjoint D A B'.
Variable disjoint_subsub_l : forall D A A' B,
  disjoint D A B -> subsub A' A -> disjoint D A' B.

(* ------------------------------------------------------------------ *)
(* 4. Typing implies type well-formedness in the empty type context.   *)
(*    Used to feed the [TWell nil _] premises of the wrapping and      *)
(*    casting helpers.                                                 *)
(* ------------------------------------------------------------------ *)
Variable typing_TWell : forall e d A,
  Typing nil nil e d A -> TWell nil A.

(* ------------------------------------------------------------------ *)
(* 5. The generic substitution lemma (proved separately).              *)
(* ------------------------------------------------------------------ *)
Variable subst_gen : forall D Gbody body d B,
  Typing D Gbody body d B ->
  forall xsub Asub Gout Gsub,
    Gbody = Gout ++ (xsub,Asub)::Gsub ->
    xsub # Gout ->
  forall v P,
    lc_exp v -> TWell D P ->
    Typing D (Gout++Gsub) v Inf P ->
    subsub P Asub ->
    (match d with
     | Inf => exists B',
         Typing D (Gout++Gsub) (subst_exp v xsub body) Inf B' /\ subsub B' B
     | Chk => Typing D (Gout++Gsub) (subst_exp v xsub body) Chk B
     end).

(* ------------------------------------------------------------------ *)
(* 6. Wrapping and casting at intersection / distributive types.       *)
(* ------------------------------------------------------------------ *)
Variable wrapping_typing_inf : forall e A e',
  wrapping e A e' -> TWell nil A -> Typing nil nil e Chk A ->
  exists P, Typing nil nil e' Inf P /\ subsub P A /\ TWell nil P.
Variable casting_typing_inf : forall v,
  value v -> prevalue v ->
  forall A v', Typing nil nil v Chk A -> TWell nil A -> casting v A v' ->
  exists P, Typing nil nil v' Inf P /\ subsub P A /\ TWell nil P.

(* ------------------------------------------------------------------ *)
(* 7. Body and argument extraction for [appDist] on abstractions.      *)
(*                                                                     *)
(* NOTE: [abs_chk_appDist_body] is stated for *all* [x].  The premise  *)
(* produced by [Typ_abs] only gives the body typing for fresh [x], so  *)
(* the all-[x] form may need an alpha-renaming argument.  It is kept   *)
(* as the task-requested usable form; see the report.                  *)
(* ------------------------------------------------------------------ *)
Variable abs_chk_appDist_body : forall A0 body B,
  Typing nil nil (e_abs A0 body) Chk B ->
  forall C1 C2, appDist B (t_arrow C1 C2) ->
  forall x, Typing nil (cons (x,A0) nil)
              (open_exp_wrt_exp body (e_var_f x)) Chk C2.
Variable abs_chk_appDist_arg : forall A0 body B,
  Typing nil nil (e_abs A0 body) Chk B ->
  forall C1 C2, appDist B (t_arrow C1 C2) ->
  forall e2, Typing nil nil e2 Chk C1 -> Typing nil nil e2 Chk A0.

(* NOTE: same freshness caveat as above; [disjoint nil C C1] is the     *)
(* side condition available at a [Typ_tapp] site.                       *)
Variable tabs_chk_appDist_body : forall body B,
  Typing nil nil (e_tabs body) Chk B ->
  forall C1 C2 C, appDist B (t_forall C1 C2) -> disjoint nil C C1 ->
  Typing nil nil (open_exp_wrt_typ body C) Chk (open_typ_wrt_typ C2 C).

(* ------------------------------------------------------------------ *)
(* 8. Uniqueness of the distributivity target.                         *)
(* ------------------------------------------------------------------ *)
Variable appDist_arrow_unique : forall A B C B' C',
  appDist A (t_arrow B C) -> appDist A (t_arrow B' C') ->
  B = B' /\ C = C'.
Variable appDist_rcd_unique : forall A l C l' C',
  appDist A (t_rcd l C) -> appDist A (t_rcd l' C') ->
  l = l' /\ C = C'.
Variable appDist_all_unique : forall A C1 C2 C1' C2',
  appDist A (t_forall C1 C2) -> appDist A (t_forall C1' C2') ->
  C1 = C1' /\ C2 = C2'.

(* ------------------------------------------------------------------ *)
(* 9. Consistency is preserved by the concrete merge step shapes.      *)
(*    (The unrestricted one-operand versions are false: [e_anno] can    *)
(*     step to a non-consistent term.)                                  *)
(* ------------------------------------------------------------------ *)
Variable consistent_step_both : forall u1 u2 A B u1' u2',
  Typing nil nil u1 Inf A -> Typing nil nil u2 Inf B ->
  consistent u1 u2 -> step u1 u1' -> step u2 u2' -> consistent u1' u2'.
Variable consistent_step_l_value : forall u1 u2 u1',
  value u2 -> consistent u1 u2 -> step u1 u1' -> consistent u1' u2.
Variable consistent_step_r_value : forall u1 u2 u2',
  value u1 -> consistent u1 u2 -> step u2 u2' -> consistent u1 u2'.

(* ------------------------------------------------------------------ *)
(* 10. Subject reduction for the [papp] auxiliary relation.            *)
(*     These are the pieces that remain to be proved by Agents J/K:    *)
(*     PApp_abs needs wrapping_typing_inf + abs_chk_appDist_* +        *)
(*     subst_gen; PApp_merge is obtained recursively.                  *)
(* ------------------------------------------------------------------ *)
Variable papp_typing_app : forall v e2 r,
  papp v (arg_exp e2) r ->
  forall A B C,
    Typing nil nil v Inf A ->
    appDist A (t_arrow B C) ->
    Typing nil nil e2 Chk B ->
    exists C', Typing nil nil r Inf C' /\ subsub C' C.
Variable papp_typing_proj : forall v l r,
  papp v (arg_la l) r ->
  forall A C,
    Typing nil nil v Inf A ->
    appDist A (t_rcd l C) ->
    exists C', Typing nil nil r Inf C' /\ subsub C' C.
Variable papp_typing_tapp : forall v A r,
  papp v (arg_typ A) r ->
  forall B C1 C2,
    Typing nil nil v Inf B ->
    appDist B (t_forall C1 C2) ->
    disjoint nil A C1 ->
    exists C', Typing nil nil r Inf C' /\
              subsub C' (open_typ_wrt_typ C2 A).

(* ------------------------------------------------------------------ *)
(* Small derived helpers.                                              *)
(* ------------------------------------------------------------------ *)

Lemma subsub_refl : forall A, lc_typ A -> subsub A A.
Proof. intros A H. apply IS_refl. exact H. Qed.

Lemma subsub_and_intro : forall A' B' A B,
  lc_typ A -> lc_typ B ->
  subsub A' A -> subsub B' B -> subsub (t_and A' B') (t_and A B).
Proof.
  intros A' B' A B HlcA HlcB HsubA HsubB.
  eapply IS_and.
  - apply Sp_and; assumption.
  - exact HsubA.
  - exact HsubB.
Qed.

(* The compiled [dup.appDist_subsub_all] only opens the codomain with a
   type variable.  Opening with an arbitrary locally closed type follows
   by type substitution; this removes the need for an extra assumption. *)
Lemma appDist_subsub_all_typ : forall A' A C1 C2,
  subsub A' A -> appDist A (t_forall C1 C2) ->
  forall B, lc_typ B ->
  exists C1' C2',
    appDist A' (t_forall C1' C2') /\
    DuplicatedType C1' C1 /\
    subsub (open_typ_wrt_typ C2' B) (open_typ_wrt_typ C2 B).
Proof.
  intros A' A C1 C2 Hss Hdist B HlcB.
  destruct (dup.appDist_subsub_all spl_all_open A' A Hss C1 C2 Hdist)
    as [C1' [C2' [Happ [Hdt HssX] ] ] ].
  exists C1', C2'; split; [ exact Happ | split; [ exact Hdt | ] ].
  destruct (atom_fresh ([[C2']] \u [[C2]])) as [Y HY].
  assert (HY1 : Y \notin [[C2']])
    by (apply (notin_union_l Y [[C2']] [[C2]]); exact HY).
  assert (HY2 : Y \notin [[C2]])
    by (apply (notin_union_r Y [[C2']] [[C2]]); exact HY).
  pose proof (subst_agent.subsub_typsubst B Y
                (open_typ_wrt_typ C2' (t_tvar_f Y))
                (open_typ_wrt_typ C2 (t_tvar_f Y)) HlcB (HssX Y)) as HssTs.
  unfold open_typ_wrt_typ in HssTs.
  rewrite (agentC.typsubst_open_typ 0 Y B C2' HlcB HY1) in HssTs.
  rewrite (agentC.typsubst_open_typ 0 Y B C2 HlcB HY2) in HssTs.
  unfold open_typ_wrt_typ.
  exact HssTs.
Qed.

(* ================================================================== *)
(* Subject reduction for closed terms.                                *)
(* ================================================================== *)

Lemma typing_pres : forall e d A,
  Typing nil nil e d A -> forall e', step e e' -> PresRes e d A e'.
Proof.
  intros e d A Hty.
  dependent induction Hty; intros e' Hstep.
  all: try (unfold PresRes in *; simpl in *).
  - (* Typ_top *)
    dependent destruction Hstep.
  - (* Typ_lit *)
    dependent destruction Hstep.
  - (* Typ_var *)
    dependent destruction Hstep.
  - (* Typ_abs *)
    dependent destruction Hstep.
  - (* Typ_app *)
    dependent destruction Hstep.
    + (* Step_papp *)
      match goal with
      | Hp : papp e1 (arg_exp e2) ?r |- _ =>
          destruct (papp_typing_app e1 e2 r Hp A B C Hty1 H Hty2)
            as [C' [HC' HsubC] ];
          exists C'; split; assumption
      end.
    + (* Step_appl *)
      match goal with
      | Hs : step e1 ?e1' |- _ =>
          destruct (IHHty1 (JMeq_refl _) (JMeq_refl _) e1' Hs)
            as [A' [HtyA' HsubA] ];
          destruct (appDist_subsub_arrow A' A HsubA B C H)
            as [B' [C' [Hdist' [HDT HsubC] ] ] ];
          assert (Hty2' : Typing nil nil e2 Chk B')
            by (apply (chk_dup chk_and_l chk_and_r B' B HDT nil nil e2 Hty2));
          exists C'; split;
          [ apply (Typ_app nil nil e1' e2 C' A' B' HtyA' Hdist' Hty2')
          | exact HsubC ]
      end.
  - (* Typ_tabs *)
    dependent destruction Hstep.
  - (* Typ_tapp *)
    dependent destruction Hstep.
    + (* Step_ptapp *)
      match goal with
      | Hp : papp e (arg_typ A) ?r |- _ =>
          destruct (papp_typing_tapp e A r Hp B C1 C2 Hty H H0)
            as [C' [HC' HsubC] ];
          exists C'; split; assumption
      end.
    + (* Step_tapp *)
      destruct (IHHty (JMeq_refl _) (JMeq_refl _) e' Hstep)
        as [B' [HtyB' HsubB] ];
      destruct (appDist_subsub_all_typ B' B C1 C2 HsubB H A H1)
        as [C1' [C2' [Hdist' [HDT Hbody] ] ] ];
      assert (Hdisj' : disjoint nil A C1')
        by (apply (disjoint_DT_r nil A C1 C1' H0 HDT));
      exists (open_typ_wrt_typ C2' A); split;
      [ apply (Typ_tapp nil nil e' A C2' B' C1' HtyB' Hdist' Hdisj')
      | exact Hbody ].
  - (* Typ_proj *)
    dependent destruction Hstep.
    + (* Step_pproj *)
      match goal with
      | Hp : papp e (arg_la l) ?r |- _ =>
          destruct (papp_typing_proj e l r Hp A C Hty H)
            as [C' [HC' HsubC] ];
          exists C'; split; assumption
      end.
    + (* Step_proj *)
      match goal with
      | Hs : step ?a ?e1' |- _ =>
          destruct (IHHty (JMeq_refl _) (JMeq_refl _) e1' Hs)
            as [A' [HtyA' HsubA] ];
          destruct (appDist_subsub_rcd A' A HsubA l C H)
            as [C' [Hdist' HsubC] ];
          exists C'; split;
          [ apply (Typ_proj nil nil e1' l C' A' HtyA' Hdist')
          | exact HsubC ]
      end.
  - (* Typ_rcd *)
    dependent destruction Hstep.
  - (* Typ_merge *)
    dependent destruction Hstep.
    + (* Step_merge *)
      match goal with
      | Hs1 : step e1 ?e1', Hs2 : step e2 ?e2' |- _ =>
          destruct (IHHty1 (JMeq_refl _) (JMeq_refl _) e1' Hs1)
            as [A' [HtyA' HsubA] ];
          destruct (IHHty2 (JMeq_refl _) (JMeq_refl _) e2' Hs2)
            as [B' [HtyB' HsubB] ];
          assert (Hd1 : disjoint nil A' B)
            by (apply (disjoint_subsub_l nil A A' B H HsubA));
          assert (Hd2 : disjoint nil A' B')
            by (apply (disjoint_subsub_r nil A' B B' Hd1 HsubB));
          exists (t_and A' B'); split;
          [ apply (Typ_merge nil nil e1' e2' A' B' HtyA' HtyB' Hd2)
          | apply subsub_and_intro;
            [ apply (typing_lc_typ nil nil e1 Inf A Hty1)
            | apply (typing_lc_typ nil nil e2 Inf B Hty2)
            | exact HsubA | exact HsubB ] ]
      end.
    + (* Step_mergel *)
      match goal with
      | Hs1 : step e1 ?e1' |- _ =>
          destruct (IHHty1 (JMeq_refl _) (JMeq_refl _) e1' Hs1)
            as [A' [HtyA' HsubA] ];
          assert (Hd1 : disjoint nil A' B)
            by (apply (disjoint_subsub_l nil A A' B H HsubA));
          exists (t_and A' B); split;
          [ apply (Typ_merge nil nil e1' e2 A' B HtyA' Hty2 Hd1)
          | apply subsub_and_intro;
            [ apply (typing_lc_typ nil nil e1 Inf A Hty1)
            | apply (typing_lc_typ nil nil e2 Inf B Hty2)
            | exact HsubA
            | apply subsub_refl; apply (typing_lc_typ nil nil e2 Inf B Hty2) ] ]
      end.
    + (* Step_merger *)
      match goal with
      | Hs2 : step e2 ?e2' |- _ =>
          destruct (IHHty2 (JMeq_refl _) (JMeq_refl _) e2' Hs2)
            as [B' [HtyB' HsubB] ];
          assert (Hd1 : disjoint nil A B')
            by (apply (disjoint_subsub_r nil A B B' H HsubB));
          exists (t_and A B'); split;
          [ apply (Typ_merge nil nil e1 e2' A B' Hty1 HtyB' Hd1)
          | apply subsub_and_intro;
            [ apply (typing_lc_typ nil nil e1 Inf A Hty1)
            | apply (typing_lc_typ nil nil e2 Inf B Hty2)
            | apply subsub_refl; apply (typing_lc_typ nil nil e1 Inf A Hty1)
            | exact HsubB ] ]
      end.
  - (* Typ_inter *)
    match goal with
    | |- Typing nil nil e' Chk (t_and A B) =>
        apply Typ_inter;
        [ exact (IHHty1 (JMeq_refl _) (JMeq_refl _) e' Hstep)
        | exact (IHHty2 (JMeq_refl _) (JMeq_refl _) e' Hstep) ]
    end.
  - (* Typ_anno *)
    dependent destruction Hstep.
    + (* Step_annov *)
      match goal with
      | Hcast : casting e A ?r |- _ =>
          match goal with
          | Hval : value e |- _ =>
              match goal with
              | Hpv : prevalue e |- _ =>
                  pose proof (typing_TWell e Chk A Hty) as HTW;
                  destruct (casting_typing_inf e Hval Hpv A r Hty HTW Hcast)
                    as [P [HtyP [HsubP HTWP] ] ];
                  exists P; split;
                  [ exact HtyP | exact HsubP ]
              end
          end
      end.
    + (* Step_anno *)
      match goal with
      | Hs : step e ?e1' |- _ =>
          assert (Hty1' : Typing nil nil e1' Chk A)
            by (exact (IHHty (JMeq_refl _) (JMeq_refl _) e1' Hs));
          exists A; split;
          [ apply (Typ_anno nil nil e1' A Hty1')
          | apply subsub_refl; apply (typing_lc_typ nil nil e Chk A Hty) ]
      end.
  - (* Typ_fix *)
    dependent destruction Hstep.
    match goal with
    | Hfix : forall x, x \notin ?Lfix ->
        Typing nil (cons (x,?Afix) nil) (open_exp_wrt_exp ?bodyfix (e_var_f x)) Chk ?Afix |- _ =>
        destruct (atom_fresh (Lfix \u termfv_exp bodyfix)) as [x Hx];
        destruct (notin_union x Lfix (termfv_exp bodyfix) Hx) as [HxL Hxfv];
        assert (Hxdom : x # (nil:ctx)) by (simpl; apply notin_empty);
        assert (Htyv : Typing nil nil (e_fixpoint Afix bodyfix) Inf Afix)
          by (apply (Typ_fix Lfix nil nil Afix bodyfix Hfix));
        pose proof (typing_TWell (e_fixpoint Afix bodyfix) Inf Afix Htyv) as HTW;
        pose proof (subst_gen nil (cons (x,Afix) nil)
                      (open_exp_wrt_exp bodyfix (e_var_f x)) Chk Afix
                      (Hfix x HxL) x Afix nil nil eq_refl Hxdom
                      (e_fixpoint Afix bodyfix) Afix H1
                      HTW Htyv (IS_refl Afix H2)) as Hres;
        simpl in Hres;
        assert (HEQ : subst_exp (e_fixpoint Afix bodyfix) x
                        (open_exp_wrt_exp bodyfix (e_var_f x))
                      = open_exp_wrt_exp bodyfix (e_fixpoint Afix bodyfix))
          by (apply agentC.subst_open_exp_exp_fresh; exact Hxfv);
        rewrite HEQ in Hres;
        exists Afix; split;
        [ apply (Typ_anno nil nil (open_exp_wrt_exp bodyfix (e_fixpoint Afix bodyfix)) Afix Hres)
        | apply subsub_refl; exact H2 ]
    end.
  - (* Typ_mergev *)
    dependent destruction Hstep.
    + (* Step_merge *)
      match goal with
      | Hs1 : step u1 ?u1', Hs2 : step u2 ?u2' |- _ =>
          destruct (IHHty1 (JMeq_refl _) (JMeq_refl _) u1' Hs1)
            as [A' [HtyA' HsubA] ];
          destruct (IHHty2 (JMeq_refl _) (JMeq_refl _) u2' Hs2)
            as [B' [HtyB' HsubB] ];
          assert (Hcons2 : consistent u1' u2')
            by (apply (consistent_step_both u1 u2 A B u1' u2' Hty1 Hty2 H2 Hs1 Hs2));
          exists (t_and A' B'); split;
          [ apply (Typ_mergev nil nil u1' u2' A' B' H H0 H1
                     HtyA' HtyB' Hcons2)
          | apply subsub_and_intro;
            [ apply (typing_lc_typ nil nil u1 Inf A Hty1)
            | apply (typing_lc_typ nil nil u2 Inf B Hty2)
            | exact HsubA | exact HsubB ] ]
      end.
    + (* Step_mergel *)
      match goal with
      | Hs1 : step u1 ?u1' |- _ =>
          match goal with
          | Hv : value u2 |- _ =>
          destruct (IHHty1 (JMeq_refl _) (JMeq_refl _) u1' Hs1)
            as [A' [HtyA' HsubA] ];
          assert (Hcons1 : consistent u1' u2)
            by (apply (consistent_step_l_value u1 u2 u1' Hv H2 Hs1));
          exists (t_and A' B); split;
          [ apply (Typ_mergev nil nil u1' u2 A' B H H0 H1
                     HtyA' Hty2 Hcons1)
          | apply subsub_and_intro;
            [ apply (typing_lc_typ nil nil u1 Inf A Hty1)
            | apply (typing_lc_typ nil nil u2 Inf B Hty2)
            | exact HsubA
            | apply subsub_refl; apply (typing_lc_typ nil nil u2 Inf B Hty2) ] ]
          end
      end.
    + (* Step_merger *)
      match goal with
      | Hs2 : step u2 ?u2' |- _ =>
          match goal with
          | Hv : value u1 |- _ =>
          destruct (IHHty2 (JMeq_refl _) (JMeq_refl _) u2' Hs2)
            as [B' [HtyB' HsubB] ];
          assert (Hcons1 : consistent u1 u2')
            by (apply (consistent_step_r_value u1 u2 u2' Hv H2 Hs2));
          exists (t_and A B'); split;
          [ apply (Typ_mergev nil nil u1 u2' A B' H H0 H1
                     Hty1 HtyB' Hcons1)
          | apply subsub_and_intro;
            [ apply (typing_lc_typ nil nil u1 Inf A Hty1)
            | apply (typing_lc_typ nil nil u2 Inf B Hty2)
            | apply subsub_refl; apply (typing_lc_typ nil nil u1 Inf A Hty1)
            | exact HsubB ] ]
          end
      end.
  - (* Typ_sub *)
    match goal with
    | Hsub : algo_sub nil A B |- Typing nil nil e' Chk B =>
        destruct (IHHty (JMeq_refl _) (JMeq_refl _) e' Hstep)
          as [A' [HtyA' HsubA] ];
        assert (HTC : TCWell nil)
          by (apply (proj1 (typing_env_wf nil nil e Inf A Hty)));
        assert (HTWA : TWell nil A)
          by (apply (algo_sub_TWell_source nil A B HTC Hsub));
        assert (HTWB : TWell nil B)
          by (apply (algo_sub_TWell_target nil A B HTC Hsub));
        assert (Hasub : algo_sub nil A' A)
          by (apply (subsub_algo_sub nil A' A HTC HTWA HsubA));
        assert (HTWA' : TWell nil A')
          by (apply (algo_sub_TWell_source nil A' A HTC Hasub));
        assert (Hasub' : algo_sub nil A' B)
          by (apply (algo_sub_trans nil A' A B HTC HTWA' HTWA HTWB Hasub Hsub));
        exact (Typ_sub nil nil e' B A' HtyA' Hasub')
    end.
Qed.



(* ================================================================== *)
(* Closed preservation and progress imply the final safety statement.  *)
(* ================================================================== *)

Section Safety.

Variable typing_progress : forall G e d A,
  Typing nil G e d A -> G = nil -> value e \/ exists e', step e e'.

Lemma type_safety_from_progress : forall e e' A,
  Typing nil nil e Inf A -> e ->* e' ->
  (value e' \/ exists e'', step e' e'').
Proof.
  intros e e' A Hty Hstar. revert A Hty.
  dependent induction Hstar; intros A Hty.
  - (* star_refl *)
    match goal with
    | H : Typing nil nil ?a Inf ?B |- _ =>
        exact (typing_progress nil a Inf B H eq_refl)
    end.
  - (* star_step *)
    destruct (typing_pres a Inf A Hty b H) as [B' [Htyb Hsub] ].
    exact (IHHstar B' Htyb).
Qed.

End Safety.

End Preservation.
End pres_agent.
Import pres_agent.

(* ===================== Final instantiation ===================== *)

Definition F_disjoint_subsub2 : forall D A1 A1' A2 A2',
  subsub A1' A1 -> subsub A2' A2 -> disjoint D A1 A2 -> disjoint D A1' A2' :=
  fun D A1 A1' A2 A2' H1 H2 Hd =>
    agentI.disjoint_subsub_r D A1' A2 A2' (agentI.disjoint_subsub_l D A1 A1' A2 Hd H1) H2.

Definition F_subst_gen : forall D Gbody body d B,
  Typing D Gbody body d B ->
  forall xsub Asub Gout Gsub,
    Gbody = Gout ++ (xsub,Asub) :: Gsub -> xsub # Gout ->
  forall v P, lc_exp v -> TWell D P -> Typing D (Gout ++ Gsub) v Inf P -> subsub P Asub ->
  match d with
  | Inf => exists B', Typing D (Gout ++ Gsub) (subst_exp v xsub body) Inf B' /\ subsub B' B
  | Chk => Typing D (Gout ++ Gsub) (subst_exp v xsub body) Chk B
  end :=
  subst_agent.typing_subst_gen agentE.chk_and_l agentE.chk_and_r splfacts.spl_all_open
    agentH2.algo_sub_trans_TWell agentH.subsub_algo_sub agentI.disjoint_DT_r
    F_disjoint_subsub2 agentI2.typing_nil_notin.

Definition F_papp_app : forall v e2 r, papp v (arg_exp e2) r ->
  forall A B C, Typing nil nil v Inf A -> appDist A (t_arrow B C) ->
    Typing nil nil e2 Chk B -> exists C', Typing nil nil r Inf C' /\ subsub C' C :=
  papp_agent.papp_typing_app.

Definition F_papp_proj : forall v l r, papp v (arg_la l) r ->
  forall A C, Typing nil nil v Inf A -> appDist A (t_rcd l C) ->
    exists C', Typing nil nil r Inf C' /\ subsub C' C :=
  papp_agent.papp_typing_proj.

Definition F_papp_tapp : forall v A r, papp v (arg_typ A) r ->
  forall B C1 C2, Typing nil nil v Inf B -> appDist B (t_forall C1 C2) ->
    disjoint nil A C1 ->
    exists C', Typing nil nil r Inf C' /\ subsub C' (open_typ_wrt_typ C2 A) :=
  papp_agent.papp_typing_tapp.

Definition F_consistent_l : forall u1 u2 u1',
  value u2 -> consistent u1 u2 -> step u1 u1' -> consistent u1' u2 :=
  agentE2.consistent_step_l_value agentE4.step_lc_exp agentI.disjoint_subsub_l.

Definition F_consistent_r : forall u1 u2 u2',
  value u1 -> consistent u1 u2 -> step u2 u2' -> consistent u1 u2' :=
  agentE2.consistent_step_r_value agentE4.step_lc_exp agentI.disjoint_subsub_r.

Theorem type_safety : forall e e' A,
  Typing nil nil e Inf A -> e ->* e' -> value e' \/ exists e'', step e' e''.
Proof.
  intros e e' A Hty Hstar.
  exact (pres_agent.type_safety_from_progress
    agentE.chk_and_l agentE.chk_and_r splfacts.spl_all_open
    agentH.subsub_algo_sub agentH2.algo_sub_trans_TWell
    agentI.disjoint_DT_r agentI.disjoint_subsub_r agentI.disjoint_subsub_l
    agentI2.typing_TWell F_subst_gen
    agentE3.casting_typing_inf_value_chk
    agentE4.consistent_step_both_typed F_consistent_l F_consistent_r
    F_papp_app F_papp_proj F_papp_tapp
    progress_final.typing_progress e e' A Hty Hstar).
Qed.
